        [ThreadStatic]
        private static string _activeCloneAuthorizationRefreshAttemptId;

        private static int Main(string[] args)
        {
            CloneAuthorizationRefreshLease cloneAuthorizationRefresh = null;
            try
            {
                Options options = Options.Parse(args);
                if (options.ShowHelp)
                {
                    PrintUsage();
                    return 0;
                }

                if (options.ShowVersion)
                {
                    PrintVersion();
                    return 0;
                }

                if (!IsKnownCommand(options.Command))
                {
                    throw new ArgumentException("Unknown command: " + options.Command);
                }

                if (!CommandRequiresProjectPath(options.Command))
                {
                    ExecuteLocalOnlyCommand(options);
                    return 0;
                }

                if (CommandRefreshesCloneAuthorization(options.Command))
                {
                    cloneAuthorizationRefresh = BeginCloneAuthorizationRefresh(options);
                }

                ProjectResolution projectResolution = ResolveProject(options.ProjectPath);
                options.ProjectPath = projectResolution.Path;

                if (EqualsIgnoreCase(options.Command, "clone"))
                {
                    string clonePath = CloneProjectFolder(options.ProjectPath, options.OutDir);
                    Console.WriteLine("Cloned project folder to: " + clonePath);
                    return 0;
                }

                if (EqualsIgnoreCase(options.Command, "hmi-import-probe-copy")
                    || EqualsIgnoreCase(options.Command, "hmi-project-texts-import-probe-copy"))
                {
                    PrepareHmiImportProbeCopyOptions(options);
                    projectResolution = CreateProjectResolution(options.ProjectPath, "copied-project-probe", Path.GetDirectoryName(options.ProjectPath), new[] { options.ProjectPath });
                }

                ApiResolution apiResolution = ResolveApiDirectory(options.ApiDir, projectResolution.ProjectVersionMajor);
                _apiDir = apiResolution.Directory;
                Console.WriteLine("Project: " + options.ProjectPath);
                Console.WriteLine("Project resolution: " + projectResolution.Source);
                Console.WriteLine("Project version: " + FormatProjectVersion(projectResolution.ProjectVersionMajor));
                Console.WriteLine("TIA Openness API: " + _apiDir);
                Console.WriteLine("TIA Openness API resolution: " + apiResolution.Source);
                if (!string.IsNullOrWhiteSpace(apiResolution.AssemblyVersion))
                {
                    Console.WriteLine("TIA Openness API assembly: " + apiResolution.AssemblyVersion);
                }

                Console.WriteLine("Command: " + options.Command);
                Console.WriteLine();

                ConfigureAssemblyLoading(_apiDir);
                LoadSiemensAssemblies(_apiDir);

                bool shouldBackup = IsWriteCommand(options.Command)
                    && options.Apply
                    && !options.NoBackup
                    && !EqualsIgnoreCase(options.Command, "apply-clone");
                if (shouldBackup && !options.Attach)
                {
                    string backupPath = BackupProjectFolder(options.ProjectPath);
                    Console.WriteLine("Backup created: " + backupPath);
                    Console.WriteLine();
                }

                object tiaPortal = options.Attach ? AttachToTiaPortal(options) : StartTiaPortal(options.Headless);
                object project = null;

                try
                {
                    _tiaPortal = tiaPortal;
                    _ownsProject = false;
                    project = OpenProject(tiaPortal, options.ProjectPath, options.Attach);
                    if (shouldBackup && options.Attach)
                    {
                        string backupPath = BackupProjectFolder(options.ProjectPath);
                        Console.WriteLine("Backup created: " + backupPath);
                        Console.WriteLine();
                    }

                    CloneAuthorizationCompletionMode cloneAuthorizationCompletion;
                    ExecuteCommand(project, options, out cloneAuthorizationCompletion);
                    if (cloneAuthorizationRefresh != null)
                    {
                        if (cloneAuthorizationCompletion == CloneAuthorizationCompletionMode.WithPlcBundle)
                        {
                            cloneAuthorizationRefresh.CompleteWithPlcBundle();
                        }
                        else if (cloneAuthorizationCompletion == CloneAuthorizationCompletionMode.WithoutPlcAuthorization)
                        {
                            cloneAuthorizationRefresh.CompleteWithoutPlcAuthorization();
                        }
                        else
                        {
                            cloneAuthorizationRefresh.AbortAndKeepRevoked();
                            throw new InvalidOperationException("Clone authorization refresh command completed without declaring its authorization outcome.");
                        }
                    }
                    return 0;
                }
                finally
                {
                    _tiaPortal = null;
                    if (_ownsProject)
                    {
                        TryDispose(project);
                    }

                    TryDispose(tiaPortal);
                }
            }
            catch (TargetInvocationException ex)
            {
                PrintException(AbortFailedCloneAuthorizationRefresh(
                    cloneAuthorizationRefresh,
                    ex.InnerException ?? ex));
                return 1;
            }
            catch (Exception ex)
            {
                PrintException(AbortFailedCloneAuthorizationRefresh(cloneAuthorizationRefresh, ex));
                return 1;
            }
            finally
            {
                if (cloneAuthorizationRefresh != null)
                {
                    cloneAuthorizationRefresh.Dispose();
                }
            }
        }

        private static void ExecuteCommand(object project, Options options, out CloneAuthorizationCompletionMode cloneAuthorizationCompletion)
        {
            cloneAuthorizationCompletion = CloneAuthorizationCompletionMode.NotApplicable;
            if (EqualsIgnoreCase(options.Command, "tree"))
            {
                PrintProject(project, options.MaxItems);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "inventory"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                string outDir = ResolveOutputDirectory(options.OutDir, "inventory");
                WriteInventory(snapshot, outDir);
                Console.WriteLine("Inventory written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "status") || EqualsIgnoreCase(options.Command, "check-all"))
            {
                cloneAuthorizationCompletion = ExecuteAuthoritativeToolStatus(project, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "init-workspace"))
            {
                if (options.Apply)
                {
                    throw new InvalidOperationException("init-workspace is read-only with respect to TIA Portal and does not accept --apply.");
                }

                cloneAuthorizationCompletion = ExecuteAuthoritativeWorkspaceInitialization(project, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-inventory"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                HmiInventorySnapshot hmiSnapshot = CollectHmiInventory(snapshot);
                string outDir = ResolveOutputDirectory(options.OutDir, "hmi-inventory");
                WriteHmiInventory(hmiSnapshot, outDir);
                Console.WriteLine("HMI inventory written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-export-xml"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                HmiInventorySnapshot hmiSnapshot = CollectHmiInventory(snapshot);
                string outDir = ResolveOutputDirectory(options.OutDir, "hmi-export-xml");
                ExportHmiXml(hmiSnapshot, outDir, options.Force);
                Console.WriteLine("HMI XML export written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-init-clone"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                HmiInventorySnapshot hmiSnapshot = CollectHmiInventory(snapshot);
                string outDir = ResolveCloneProjectDirectory(options.OutDir);
                InitializeHmiClone(snapshot, hmiSnapshot, outDir, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-check"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                HmiInventorySnapshot hmiSnapshot = CollectHmiInventory(snapshot);
                string outDir = ResolveCloneProjectDirectory(options.OutDir);
                CheckHmiClone(snapshot, hmiSnapshot, outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-sync-clone"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                HmiInventorySnapshot hmiSnapshot = CollectHmiInventory(snapshot);
                string outDir = ResolveCloneProjectDirectory(options.OutDir);
                SyncHmiClone(snapshot, hmiSnapshot, outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-import-capabilities"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                HmiInventorySnapshot hmiSnapshot = CollectHmiInventory(snapshot);
                string outDir = ResolveOutputDirectory(options.OutDir, "hmi-import-capabilities");
                WriteHmiImportCapabilities(snapshot, hmiSnapshot, outDir);
                Console.WriteLine("HMI import capabilities written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-textlist-model-probe"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                HmiInventorySnapshot hmiSnapshot = CollectHmiInventory(snapshot);
                string outDir = ResolveOutputDirectory(options.OutDir, "hmi-textlist-model-probe");
                WriteHmiTextListModelProbe(snapshot, hmiSnapshot, outDir, options);
                Console.WriteLine("HMI text list object-model probe written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-screen-model-probe"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                HmiInventorySnapshot hmiSnapshot = CollectHmiInventory(snapshot);
                string outDir = ResolveOutputDirectory(options.OutDir, "hmi-screen-model-probe");
                WriteHmiScreenModelProbe(snapshot, hmiSnapshot, outDir, options);
                Console.WriteLine("HMI screen object-model probe written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-project-texts-probe"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                string outDir = ResolveOutputDirectory(options.OutDir, "hmi-project-texts-probe");
                WriteHmiProjectTextsProbe(project, snapshot, outDir, options);
                Console.WriteLine("HMI project texts probe written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-import-probe-copy"))
            {
                HmiImportProbeCopyCommand(project, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-project-texts-import-probe-copy"))
            {
                HmiProjectTextsImportProbeCopyCommand(project, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-project-texts-apply-preflight"))
            {
                if (options.Apply)
                {
                    throw new InvalidOperationException("hmi-project-texts-apply-preflight is read-only and does not accept --apply.");
                }

                HmiProjectTextsApplyPreflightCommand(project, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-project-texts-apply"))
            {
                HmiProjectTextsApplyCommand(project, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "clone-folders"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                string outDir = ResolveCloneProjectDirectory(options.OutDir);
                CloneBlockFolderStructure(snapshot, outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "init-clone"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                snapshot = FilterInventoryBySoftwarePath(snapshot, options.SoftwarePathFilter);
                string outDir = ResolveCloneProjectDirectory(options.OutDir);
                InitializeProjectClone(snapshot, outDir, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "check-clone"))
            {
                ExecuteAuthoritativeCheckClone(project, options);
                cloneAuthorizationCompletion = CloneAuthorizationCompletionMode.WithPlcBundle;
                return;
            }

            if (EqualsIgnoreCase(options.Command, "apply-clone"))
            {
                ApplyCloneCommand(project, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "export-xml"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                string outDir = ResolveOutputDirectory(options.OutDir, "export-xml");
                ExportXml(snapshot, outDir, options.Force);
                Console.WriteLine("XML export written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "system-blocks-probe"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                string outDir = ResolveOutputDirectory(options.OutDir, "system-blocks-probe");
                SystemBlocksProbe(snapshot, outDir, options);
                Console.WriteLine("System blocks probe written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "export-documents"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                string outDir = ResolveOutputDirectory(options.OutDir, "export-documents");
                ExportBlockDocuments(snapshot, outDir, options);
                Console.WriteLine("Document export written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "export-source"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                string outDir = ResolveOutputDirectory(options.OutDir, "export-source");
                ExportBlockSources(snapshot, outDir, options);
                Console.WriteLine("Source export written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "inspect"))
            {
                InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
                InspectSnapshot(snapshot);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "set-attribute"))
            {
                SetAttributeCommand(project, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "compile-block"))
            {
                CompileBlockCommand(project, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "compile-all"))
            {
                CompileAllCommand(project, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "delete-block"))
            {
                DeleteBlockCommand(project, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "create-test-visual-fb"))
            {
                CreateTestVisualFbCommand(project, options);
                return;
            }

            throw new ArgumentException("Unknown command: " + options.Command);
        }

