        private static void ExecuteLocalOnlyCommand(Options options)
        {
            if (EqualsIgnoreCase(options.Command, "version"))
            {
                PrintVersion();
                return;
            }

            if (EqualsIgnoreCase(options.Command, "workspace-lock-probe"))
            {
                string cloneDir = ResolveCloneProjectDirectory(options.OutDir);
                using (AcquireCloneWorkspaceLock(cloneDir, "workspace-lock-probe"))
                {
                    Console.WriteLine("Workspace lock acquired: " + cloneDir);
                }
                return;
            }

            if (EqualsIgnoreCase(options.Command, "self-test-publication-crash-child"))
            {
                SelfTestPublicationCrashChild(options.OutDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "sync-clone"))
            {
                string cloneDir = ResolveCloneProjectDirectory(options.OutDir);
                SyncProjectClone(cloneDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "block-info"))
            {
                string cloneDir = ResolveCloneProjectDirectory(options.OutDir);
                BlockInfoCommand(cloneDir, options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "plc-runtime-probe"))
            {
                PlcRuntimeProbeCommand(options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "plc-runtime-map"))
            {
                PlcRuntimeMapCommand(options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "plc-runtime-read"))
            {
                PlcRuntimeReadCommand(options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "plc-runtime-write"))
            {
                PlcRuntimeWriteCommand(options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "plc-runtime-snapshot"))
            {
                PlcRuntimeSnapshotCommand(options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-digest"))
            {
                string inDir = ResolveRequiredInputDirectory(options.InDir);
                string outDir = ResolveOutputDirectory(options.OutDir, "hmi-digest");
                WriteHmiDigest(inDir, outDir);
                Console.WriteLine("HMI digest written to: " + outDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "hmi-apply-preflight"))
            {
                if (options.Apply)
                {
                    throw new InvalidOperationException("hmi-apply-preflight is read-only and does not accept --apply.");
                }

                string cloneDir = ResolveCloneProjectDirectory(options.OutDir);
                string patchPath = ResolveRequiredPatchFile(options.PatchPath);
                WriteHmiApplyPreflight(cloneDir, patchPath);
                Console.WriteLine("HMI apply preflight written to: " + cloneDir);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "self-test"))
            {
                RunSelfTest(options);
                return;
            }

            if (EqualsIgnoreCase(options.Command, "clean-local"))
            {
                CleanLocalCommand(options);
                return;
            }

            throw new ArgumentException("Command is not local-only: " + options.Command);
        }

        private static void CleanLocalCommand(Options options)
        {
            string scope = NormalizeCleanLocalScope(options.Scope);
            if (options.Apply && EqualsIgnoreCase(scope, "audit"))
            {
                throw new InvalidOperationException("clean-local --apply requires an explicit destructive scope, for example --scope probe-generated.");
            }

            if (options.Apply && EqualsIgnoreCase(scope, "workspace-transient"))
            {
                throw new InvalidOperationException("workspace-transient cleanup is audit-only in this version. Keep or remove those project audit folders manually after reviewing clean-local reports.");
            }

            string toolDir = ResolveToolDirectoryForCleanLocal();
            string projectRoot = Directory.GetParent(toolDir) == null ? Environment.CurrentDirectory : Directory.GetParent(toolDir).FullName;
            string cloneDir = EqualsIgnoreCase(scope, "workspace-transient") && !string.IsNullOrWhiteSpace(options.OutDir)
                ? Path.GetFullPath(options.OutDir)
                : Path.Combine(projectRoot, "CLONE_PROJECT");
            string reportDir = ResolveCleanLocalReportDirectory(toolDir, options);

            List<CleanLocalCandidate> candidates = BuildCleanLocalCandidates(projectRoot, toolDir, cloneDir, scope);
            if (!options.Apply)
            {
                foreach (CleanLocalCandidate candidate in candidates.Where(x => EqualsIgnoreCase(x.Status, "pending")))
                {
                    candidate.Status = "dry-run";
                    candidate.Message = "Deletion would be performed only with --apply.";
                }
            }

            if (options.Apply)
            {
                RecreateCleanLocalReportDirectory(reportDir, toolDir);
                WriteCleanLocalReports(reportDir, projectRoot, toolDir, cloneDir, scope, options.Apply, candidates, "pre-delete");
                ApplyCleanLocalDeletes(candidates, projectRoot, toolDir);
            }

            RecreateCleanLocalReportDirectory(reportDir, toolDir);
            WriteCleanLocalReports(reportDir, projectRoot, toolDir, cloneDir, scope, options.Apply, candidates, "final");

            int deleteCount = candidates.Count(x => EqualsIgnoreCase(x.Status, "deleted"));
            int skippedCount = candidates.Count(x => EqualsIgnoreCase(x.Status, "skipped"));
            int failedCount = candidates.Count(x => EqualsIgnoreCase(x.Status, "failed"));
            long deletedBytes = candidates.Where(x => EqualsIgnoreCase(x.Status, "deleted")).Sum(x => x.TotalBytes);

            Console.WriteLine("Clean-local completed.");
            Console.WriteLine("Scope: " + scope);
            Console.WriteLine("Apply: " + options.Apply);
            Console.WriteLine("Deleted candidates: " + deleteCount);
            Console.WriteLine("Deleted bytes: " + deletedBytes);
            Console.WriteLine("Skipped candidates: " + skippedCount);
            Console.WriteLine("Failed candidates: " + failedCount);
            Console.WriteLine("Report directory: " + reportDir);

            if (failedCount > 0)
            {
                throw new InvalidOperationException("clean-local failed for " + failedCount + " candidate(s). See clean-local-candidates.csv.");
            }
        }

        private static string NormalizeCleanLocalScope(string scope)
        {
            scope = string.IsNullOrWhiteSpace(scope) ? "audit" : scope.Trim();
            if (EqualsIgnoreCase(scope, "audit") || EqualsIgnoreCase(scope, "probe-generated") || EqualsIgnoreCase(scope, "workspace-transient"))
            {
                return scope;
            }

            throw new ArgumentException("Unknown clean-local scope: " + scope + ". Supported scopes: audit, probe-generated, workspace-transient.");
        }

        private static void PlcRuntimeProbeCommand(Options options)
        {
            if (options.DbNumber <= 0)
            {
                throw new ArgumentException("plc-runtime-probe requires --db <n>.");
            }

            if (options.RuntimeSize <= 0 || options.RuntimeSize > 222)
            {
                throw new ArgumentException("plc-runtime-probe --size must be between 1 and 222 bytes for the initial probe.");
            }

            if (options.RuntimeStart < 0)
            {
                throw new ArgumentException("plc-runtime-probe --start must be >= 0.");
            }

            string host = string.IsNullOrWhiteSpace(options.Host) ? "127.0.0.1" : options.Host.Trim();
            int rack = options.Rack < 0 ? 0 : options.Rack;
            int slot = options.Slot < 0 ? 2 : options.Slot;
            int connectionType = options.ConnectionType <= 0 ? 1 : options.ConnectionType;
            int timeoutMs = options.TimeoutMs <= 0 ? 3000 : options.TimeoutMs;

            Console.WriteLine("PLC runtime probe: read-only S7 DB bytes");
            Console.WriteLine("Host: " + host);
            Console.WriteLine("Port: 102");
            Console.WriteLine("Rack/slot: " + rack.ToString(CultureInfo.InvariantCulture) + "/" + slot.ToString(CultureInfo.InvariantCulture));
            Console.WriteLine("Connection type: 0x" + connectionType.ToString("X2", CultureInfo.InvariantCulture));
            Console.WriteLine("DB: " + options.DbNumber.ToString(CultureInfo.InvariantCulture));
            Console.WriteLine("Start: " + options.RuntimeStart.ToString(CultureInfo.InvariantCulture));
            Console.WriteLine("Size: " + options.RuntimeSize.ToString(CultureInfo.InvariantCulture));
            Console.WriteLine("Timeout ms: " + timeoutMs.ToString(CultureInfo.InvariantCulture));
            Console.WriteLine();

            using (S7RuntimeClient client = new S7RuntimeClient(host, rack, slot, connectionType, timeoutMs))
            {
                client.Connect();
                Console.WriteLine("Connected. Negotiated PDU length: " + client.PduLength.ToString(CultureInfo.InvariantCulture));
                byte[] data = client.ReadDb(options.DbNumber, options.RuntimeStart, options.RuntimeSize);
                Console.WriteLine("Read OK. Bytes: " + data.Length.ToString(CultureInfo.InvariantCulture));
                Console.WriteLine(HexDump(data, options.RuntimeStart));
            }
        }

        private static string HexDump(byte[] data, int baseOffset)
        {
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < data.Length; i += 16)
            {
                int count = Math.Min(16, data.Length - i);
                builder.Append((baseOffset + i).ToString("X4", CultureInfo.InvariantCulture));
                builder.Append(": ");
                for (int j = 0; j < 16; j++)
                {
                    if (j < count)
                    {
                        builder.Append(data[i + j].ToString("X2", CultureInfo.InvariantCulture));
                    }
                    else
                    {
                        builder.Append("  ");
                    }

                    builder.Append(j == 7 ? "  " : " ");
                }

                builder.Append(" ");
                for (int j = 0; j < count; j++)
                {
                    byte value = data[i + j];
                    builder.Append(value >= 32 && value <= 126 ? (char)value : '.');
                }

                if (i + count < data.Length)
                {
                    builder.AppendLine();
                }
            }

            return builder.ToString();
        }

        private static void PlcRuntimeReadCommand(Options options)
        {
            if (string.IsNullOrWhiteSpace(options.VarName))
            {
                throw new ArgumentException("plc-runtime-read requires --var <path>.");
            }

            if (options.DbNumber <= 0 && string.IsNullOrWhiteSpace(options.DbName))
            {
                throw new ArgumentException("plc-runtime-read requires --db <n/name>.");
            }

            string mapCsv = ResolveRuntimeMapCsv(options);
            Dictionary<string, string> entry = FindRuntimeMapEntry(mapCsv, options);
            int dbNumber = ParseRequiredRuntimeInt(GetCsvValue(entry, "DbNumber"), "DbNumber");
            int byteOffset = ParseRequiredRuntimeInt(GetCsvValue(entry, "ByteOffset"), "ByteOffset");
            int bitOffset = string.IsNullOrWhiteSpace(GetCsvValue(entry, "BitOffset")) ? -1 : ParseRequiredRuntimeInt(GetCsvValue(entry, "BitOffset"), "BitOffset");
            int lengthBytes = ParseRequiredRuntimeInt(GetCsvValue(entry, "LengthBytes"), "LengthBytes");
            string datatype = GetCsvValue(entry, "Datatype");
            if (!RuntimeDatatypeCanRead(datatype, bitOffset))
            {
                throw new InvalidOperationException("plc-runtime-read supports scalar values only. Variable '" + GetCsvValue(entry, "VariablePath") + "' has datatype '" + datatype + "'.");
            }

            string host = string.IsNullOrWhiteSpace(options.Host) ? "127.0.0.1" : options.Host.Trim();
            int rack = options.Rack < 0 ? 0 : options.Rack;
            int slot = options.Slot < 0 ? 2 : options.Slot;
            int connectionType = options.ConnectionType <= 0 ? 1 : options.ConnectionType;
            int timeoutMs = options.TimeoutMs <= 0 ? 3000 : options.TimeoutMs;

            using (S7RuntimeClient client = new S7RuntimeClient(host, rack, slot, connectionType, timeoutMs))
            {
                client.Connect();
                byte[] data = client.ReadDb(dbNumber, byteOffset, lengthBytes);
                string value = DecodeRuntimeValue(datatype, data, bitOffset);

                Console.WriteLine("PLC runtime read");
                Console.WriteLine("Host: " + host);
                Console.WriteLine("DB: " + GetCsvValue(entry, "DbName") + " [" + dbNumber.ToString(CultureInfo.InvariantCulture) + "]");
                Console.WriteLine("Variable: " + GetCsvValue(entry, "VariablePath"));
                Console.WriteLine("Datatype: " + datatype);
                Console.WriteLine("Offset: " + byteOffset.ToString(CultureInfo.InvariantCulture) + (bitOffset >= 0 ? "." + bitOffset.ToString(CultureInfo.InvariantCulture) : string.Empty));
                Console.WriteLine("Length bytes: " + lengthBytes.ToString(CultureInfo.InvariantCulture));
                Console.WriteLine("Access policy: " + GetCsvValue(entry, "AccessPolicy"));
                Console.WriteLine("Value: " + value);
                Console.WriteLine("Raw:");
                Console.WriteLine(HexDump(data, byteOffset));
            }
        }

        private static void PlcRuntimeWriteCommand(Options options)
        {
            if (string.IsNullOrWhiteSpace(options.VarName))
            {
                throw new ArgumentException("plc-runtime-write requires --var <path>.");
            }

            if (options.DbNumber <= 0 && string.IsNullOrWhiteSpace(options.DbName))
            {
                throw new ArgumentException("plc-runtime-write requires --db <n/name>.");
            }

            if (string.IsNullOrWhiteSpace(options.Value))
            {
                throw new ArgumentException("plc-runtime-write requires --value <value>.");
            }

            if (options.Apply && !options.WritesPlcConfirmed)
            {
                throw new InvalidOperationException("Real PLC write requires both --apply and --i-know-this-writes-plc.");
            }

            string mapCsv = ResolveRuntimeMapCsv(options);
            Dictionary<string, string> entry = FindRuntimeMapEntry(mapCsv, options);
            if (!EqualsIgnoreCase(GetCsvValue(entry, "AccessPolicy"), "write-candidate"))
            {
                throw new InvalidOperationException("Refusing to write variable with access policy '" + GetCsvValue(entry, "AccessPolicy") + "': " + GetCsvValue(entry, "VariablePath"));
            }

            int dbNumber = ParseRequiredRuntimeInt(GetCsvValue(entry, "DbNumber"), "DbNumber");
            int byteOffset = ParseRequiredRuntimeInt(GetCsvValue(entry, "ByteOffset"), "ByteOffset");
            int bitOffset = string.IsNullOrWhiteSpace(GetCsvValue(entry, "BitOffset")) ? -1 : ParseRequiredRuntimeInt(GetCsvValue(entry, "BitOffset"), "BitOffset");
            int lengthBytes = ParseRequiredRuntimeInt(GetCsvValue(entry, "LengthBytes"), "LengthBytes");
            string datatype = GetCsvValue(entry, "Datatype");
            if (!RuntimeDatatypeCanWrite(datatype, bitOffset))
            {
                throw new InvalidOperationException("plc-runtime-write supports Bool, Byte, Word, Int, DWord, DInt, and Real only. Variable datatype: " + datatype);
            }

            string host = string.IsNullOrWhiteSpace(options.Host) ? "127.0.0.1" : options.Host.Trim();
            int rack = options.Rack < 0 ? 0 : options.Rack;
            int slot = options.Slot < 0 ? 2 : options.Slot;
            int connectionType = options.ConnectionType <= 0 ? 1 : options.ConnectionType;
            int timeoutMs = options.TimeoutMs <= 0 ? 3000 : options.TimeoutMs;

            using (S7RuntimeClient client = new S7RuntimeClient(host, rack, slot, connectionType, timeoutMs))
            {
                client.Connect();
                byte[] current = client.ReadDb(dbNumber, byteOffset, lengthBytes);
                string currentValue = DecodeRuntimeValue(datatype, current, bitOffset);
                byte[] writeBytes = BuildRuntimeWriteBytes(entry, datatype, options.Value, current, bitOffset);
                string desiredValue = DecodeRuntimeValue(datatype, bitOffset >= 0 ? writeBytes : writeBytes, bitOffset);

                Console.WriteLine("PLC runtime write");
                Console.WriteLine("Mode: " + (options.Apply && options.WritesPlcConfirmed ? "APPLY" : "DRY-RUN"));
                Console.WriteLine("Host: " + host);
                Console.WriteLine("DB: " + GetCsvValue(entry, "DbName") + " [" + dbNumber.ToString(CultureInfo.InvariantCulture) + "]");
                Console.WriteLine("Variable: " + GetCsvValue(entry, "VariablePath"));
                Console.WriteLine("Datatype: " + datatype);
                Console.WriteLine("Offset: " + byteOffset.ToString(CultureInfo.InvariantCulture) + (bitOffset >= 0 ? "." + bitOffset.ToString(CultureInfo.InvariantCulture) : string.Empty));
                Console.WriteLine("Current value: " + currentValue);
                Console.WriteLine("Requested value: " + options.Value);
                Console.WriteLine("Prepared value: " + desiredValue);
                Console.WriteLine("Prepared raw:");
                Console.WriteLine(HexDump(writeBytes, byteOffset));

                if (!options.Apply || !options.WritesPlcConfirmed)
                {
                    Console.WriteLine("No write performed. Add --apply --i-know-this-writes-plc to write.");
                    return;
                }

                client.WriteDb(dbNumber, byteOffset, writeBytes);
                byte[] after = client.ReadDb(dbNumber, byteOffset, lengthBytes);
                Console.WriteLine("Write OK.");
                Console.WriteLine("Read-back value: " + DecodeRuntimeValue(datatype, after, bitOffset));
                Console.WriteLine("Read-back raw:");
                Console.WriteLine(HexDump(after, byteOffset));
            }
        }

        private static void PlcRuntimeSnapshotCommand(Options options)
        {
            string scope = string.IsNullOrWhiteSpace(options.Scope) ? "db" : options.Scope.Trim();
            if (!EqualsIgnoreCase(scope, "db") && !EqualsIgnoreCase(scope, "all"))
            {
                throw new ArgumentException("plc-runtime-snapshot --scope supports only db or all.");
            }

            if (EqualsIgnoreCase(scope, "db") && options.DbNumber <= 0 && string.IsNullOrWhiteSpace(options.DbName))
            {
                throw new ArgumentException("plc-runtime-snapshot requires --db <n/name> unless --scope all is used.");
            }

            if (options.MaxReadBytes <= 0 || options.MaxReadBytes > 222)
            {
                throw new ArgumentException("plc-runtime-snapshot --max-read-bytes must be between 1 and 222 for the current S7 runtime client.");
            }

            string mapCsv = ResolveRuntimeMapCsv(options);
            List<Dictionary<string, string>> mapRows = ReadCsv(mapCsv);
            List<IGrouping<string, Dictionary<string, string>>> dbGroups = SelectRuntimeSnapshotDbGroups(mapRows, options, scope);
            if (dbGroups.Count == 0)
            {
                throw new InvalidOperationException("No runtime map DB rows matched the snapshot request.");
            }

            string host = string.IsNullOrWhiteSpace(options.Host) ? "127.0.0.1" : options.Host.Trim();
            int rack = options.Rack < 0 ? 0 : options.Rack;
            int slot = options.Slot < 0 ? 2 : options.Slot;
            int connectionType = options.ConnectionType <= 0 ? 1 : options.ConnectionType;
            int timeoutMs = options.TimeoutMs <= 0 ? 3000 : options.TimeoutMs;
            DateTime startedLocal = DateTime.Now;
            DateTime startedUtc = DateTime.UtcNow;
            string snapshotRoot = ResolveRuntimeSnapshotRoot(options);
            string snapshotId = startedLocal.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
            string snapshotDir = Path.Combine(snapshotRoot, snapshotId);
            Directory.CreateDirectory(snapshotDir);

            List<RuntimeSnapshotValueRecord> values = new List<RuntimeSnapshotValueRecord>();
            List<RuntimeSnapshotReadRangeRecord> ranges = new List<RuntimeSnapshotReadRangeRecord>();
            List<RuntimeSnapshotRawBlock> rawBlocks = new List<RuntimeSnapshotRawBlock>();

            using (S7RuntimeClient client = new S7RuntimeClient(host, rack, slot, connectionType, timeoutMs))
            {
                client.Connect();
                foreach (IGrouping<string, Dictionary<string, string>> group in dbGroups)
                {
                    CaptureRuntimeSnapshotDb(client, group.ToList(), options, snapshotId, startedLocal, startedUtc, host, mapCsv, values, ranges, rawBlocks);
                }
            }

            DateTime finishedLocal = DateTime.Now;
            WriteRuntimeSnapshotArtifacts(snapshotDir, snapshotId, startedLocal, startedUtc, finishedLocal, host, mapCsv, values, ranges, rawBlocks, options);

            Console.WriteLine("PLC runtime snapshot");
            Console.WriteLine("Host: " + host);
            Console.WriteLine("Map: " + mapCsv);
            Console.WriteLine("Scope: " + scope);
            Console.WriteLine("DB count: " + dbGroups.Count.ToString(CultureInfo.InvariantCulture));
            Console.WriteLine("Values: " + values.Count.ToString(CultureInfo.InvariantCulture));
            Console.WriteLine("Read ranges: " + ranges.Count.ToString(CultureInfo.InvariantCulture));
            Console.WriteLine("Snapshot: " + snapshotDir);

            if (options.PrintValues)
            {
                Console.WriteLine();
                foreach (RuntimeSnapshotValueRecord value in values.OrderBy(x => SafeInt(x.DbNumber)).ThenBy(x => SafeInt(x.ByteOffset)).ThenBy(x => SafeInt(x.BitOffset)).ThenBy(x => x.VariablePath, StringComparer.OrdinalIgnoreCase))
                {
                    Console.WriteLine(value.DbName + "." + value.VariablePath + " = " + value.Value + " [" + value.Quality + "]");
                }
            }
        }

        private static List<IGrouping<string, Dictionary<string, string>>> SelectRuntimeSnapshotDbGroups(List<Dictionary<string, string>> mapRows, Options options, string scope)
        {
            IEnumerable<Dictionary<string, string>> rows = mapRows;
            if (!EqualsIgnoreCase(scope, "all"))
            {
                rows = rows.Where(x => RuntimeMapDbMatches(x, options));
            }

            return rows
                .Where(x => !string.IsNullOrWhiteSpace(GetCsvValue(x, "DbName")) && !string.IsNullOrWhiteSpace(GetCsvValue(x, "DbNumber")))
                .GroupBy(x => GetCsvValue(x, "DbName") + "|" + GetCsvValue(x, "DbNumber"), StringComparer.OrdinalIgnoreCase)
                .OrderBy(x => SafeInt(GetCsvValue(x.First(), "DbNumber")))
                .ThenBy(x => GetCsvValue(x.First(), "DbName"), StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static void CaptureRuntimeSnapshotDb(
            S7RuntimeClient client,
            List<Dictionary<string, string>> dbRows,
            Options options,
            string snapshotId,
            DateTime timestampLocal,
            DateTime timestampUtc,
            string host,
            string mapCsv,
            List<RuntimeSnapshotValueRecord> values,
            List<RuntimeSnapshotReadRangeRecord> ranges,
            List<RuntimeSnapshotRawBlock> rawBlocks)
        {
            if (dbRows.Count == 0)
            {
                return;
            }

            string dbName = GetCsvValue(dbRows[0], "DbName");
            string dbNumberText = GetCsvValue(dbRows[0], "DbNumber");
            int dbNumber = ParseRequiredRuntimeInt(dbNumberText, "DbNumber");
            int forcedStart;
            int forcedLength;
            bool hasForcedRange = TryGetRuntimeSnapshotForcedRange(dbRows, options, out forcedStart, out forcedLength);
            List<Dictionary<string, string>> selected = SelectRuntimeSnapshotRows(dbRows, options, hasForcedRange, forcedStart, forcedLength);

            if (selected.Count == 0 && !hasForcedRange)
            {
                throw new InvalidOperationException("No runtime map variables matched snapshot selection for DB " + dbName + ".");
            }

            int start;
            int length;
            if (hasForcedRange)
            {
                start = forcedStart;
                length = forcedLength;
            }
            else
            {
                start = selected.Min(x => ParseRequiredRuntimeInt(GetCsvValue(x, "ByteOffset"), "ByteOffset"));
                int end = selected.Max(x => ParseRequiredRuntimeInt(GetCsvValue(x, "ByteOffset"), "ByteOffset") + Math.Max(1, ParseRequiredRuntimeInt(GetCsvValue(x, "LengthBytes"), "LengthBytes")));
                length = end - start;
            }

            if (length <= 0)
            {
                throw new InvalidOperationException("Snapshot byte range is empty for DB " + dbName + ".");
            }

            List<RuntimeSnapshotReadRangeRecord> plannedRanges = BuildRuntimeSnapshotReadRanges(snapshotId, timestampLocal, timestampUtc, host, dbName, dbNumberText, start, length, options.MaxReadBytes);
            if (options.SingleRead && plannedRanges.Count > 1)
            {
                throw new InvalidOperationException("Snapshot requires " + plannedRanges.Count.ToString(CultureInfo.InvariantCulture) + " S7 reads for DB " + dbName + ". Remove --single-read or reduce the selected range.");
            }

            byte[] buffer = new byte[length];
            bool readOk = true;
            StringBuilder errorBuilder = new StringBuilder();
            foreach (RuntimeSnapshotReadRangeRecord range in plannedRanges)
            {
                DateTime rangeStarted = DateTime.Now;
                range.StartedAt = rangeStarted.ToString("o", CultureInfo.InvariantCulture);
                try
                {
                    byte[] chunk = client.ReadDb(dbNumber, SafeInt(range.StartByte), SafeInt(range.LengthBytes));
                    Buffer.BlockCopy(chunk, 0, buffer, SafeInt(range.StartByte) - start, chunk.Length);
                    range.Status = "ok";
                }
                catch (Exception ex)
                {
                    readOk = false;
                    range.Status = "read-error";
                    range.Message = ex.Message;
                    if (errorBuilder.Length > 0)
                    {
                        errorBuilder.Append(" | ");
                    }

                    errorBuilder.Append("range ");
                    errorBuilder.Append(range.RangeId);
                    errorBuilder.Append(": ");
                    errorBuilder.Append(ex.Message);
                }
                finally
                {
                    range.FinishedAt = DateTime.Now.ToString("o", CultureInfo.InvariantCulture);
                    ranges.Add(range);
                }
            }

            if (readOk)
            {
                rawBlocks.Add(new RuntimeSnapshotRawBlock
                {
                    DbName = dbName,
                    DbNumber = dbNumberText,
                    StartByte = start,
                    Data = buffer
                });
            }

            foreach (Dictionary<string, string> row in selected.OrderBy(x => SafeInt(GetCsvValue(x, "ByteOffset"))).ThenBy(x => SafeInt(GetCsvValue(x, "BitOffset"))).ThenBy(x => GetCsvValue(x, "VariablePath"), StringComparer.OrdinalIgnoreCase))
            {
                values.Add(BuildRuntimeSnapshotValueRecord(row, snapshotId, timestampLocal, timestampUtc, host, mapCsv, start, buffer, readOk, errorBuilder.ToString()));
            }
        }

        private static bool TryGetRuntimeSnapshotForcedRange(List<Dictionary<string, string>> dbRows, Options options, out int start, out int length)
        {
            start = 0;
            length = 0;
            if (!string.IsNullOrWhiteSpace(options.RuntimeRange))
            {
                string[] parts = options.RuntimeRange.Split(new[] { ':', '+', ',' }, StringSplitOptions.RemoveEmptyEntries);
                if (parts.Length != 2
                    || !int.TryParse(parts[0].Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out start)
                    || !int.TryParse(parts[1].Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out length)
                    || start < 0
                    || length <= 0)
                {
                    throw new ArgumentException("Invalid --range value. Use --range <start:size>, for example --range 0:180.");
                }

                return true;
            }

            if (!string.IsNullOrWhiteSpace(options.FromVar) || !string.IsNullOrWhiteSpace(options.ToVar))
            {
                if (string.IsNullOrWhiteSpace(options.FromVar) || string.IsNullOrWhiteSpace(options.ToVar))
                {
                    throw new ArgumentException("plc-runtime-snapshot requires both --from and --to when using a variable range.");
                }

                Dictionary<string, string> fromRow = FindRuntimeSnapshotVariableRow(dbRows, options.FromVar);
                Dictionary<string, string> toRow = FindRuntimeSnapshotVariableRow(dbRows, options.ToVar);
                int fromStart = ParseRequiredRuntimeInt(GetCsvValue(fromRow, "ByteOffset"), "ByteOffset");
                int toStart = ParseRequiredRuntimeInt(GetCsvValue(toRow, "ByteOffset"), "ByteOffset");
                int toEnd = toStart + Math.Max(1, ParseRequiredRuntimeInt(GetCsvValue(toRow, "LengthBytes"), "LengthBytes"));
                int fromEnd = fromStart + Math.Max(1, ParseRequiredRuntimeInt(GetCsvValue(fromRow, "LengthBytes"), "LengthBytes"));
                start = Math.Min(fromStart, toStart);
                length = Math.Max(fromEnd, toEnd) - start;
                return true;
            }

            return false;
        }

        private static List<Dictionary<string, string>> SelectRuntimeSnapshotRows(List<Dictionary<string, string>> dbRows, Options options, bool hasForcedRange, int forcedStart, int forcedLength)
        {
            List<Dictionary<string, string>> offsetRows = dbRows
                .Where(RuntimeMapRowHasOffsetAndLength)
                .ToList();

            if (hasForcedRange)
            {
                int forcedEnd = forcedStart + forcedLength;
                return offsetRows
                    .Where(x =>
                    {
                        int rowStart = ParseRequiredRuntimeInt(GetCsvValue(x, "ByteOffset"), "ByteOffset");
                        int rowEnd = rowStart + Math.Max(1, ParseRequiredRuntimeInt(GetCsvValue(x, "LengthBytes"), "LengthBytes"));
                        return rowStart >= forcedStart && rowEnd <= forcedEnd;
                    })
                    .ToList();
            }

            List<string> requestedVariables = RuntimeSnapshotRequestedVariables(options);
            if (requestedVariables.Count > 0)
            {
                List<Dictionary<string, string>> selected = new List<Dictionary<string, string>>();
                foreach (string variable in requestedVariables)
                {
                    selected.Add(FindRuntimeSnapshotVariableRow(offsetRows, variable));
                }

                return selected
                    .GroupBy(x => GetCsvValue(x, "DbName") + "." + GetCsvValue(x, "VariablePath"), StringComparer.OrdinalIgnoreCase)
                    .Select(x => x.First())
                    .ToList();
            }

            return offsetRows;
        }

        private static bool RuntimeMapRowHasOffsetAndLength(Dictionary<string, string> row)
        {
            int parsed;
            return int.TryParse(GetCsvValue(row, "ByteOffset"), NumberStyles.Integer, CultureInfo.InvariantCulture, out parsed)
                && int.TryParse(GetCsvValue(row, "LengthBytes"), NumberStyles.Integer, CultureInfo.InvariantCulture, out parsed)
                && parsed > 0;
        }

        private static Dictionary<string, string> FindRuntimeSnapshotVariableRow(List<Dictionary<string, string>> rows, string variable)
        {
            List<Dictionary<string, string>> matches = rows
                .Where(x => RuntimeSnapshotVariableMatches(x, variable))
                .ToList();
            if (matches.Count == 0)
            {
                throw new InvalidOperationException("Runtime snapshot variable was not found in map: " + variable);
            }

            if (matches.Count > 1)
            {
                throw new InvalidOperationException("Runtime snapshot variable is ambiguous: " + variable);
            }

            return matches[0];
        }

        private static bool RuntimeSnapshotVariableMatches(Dictionary<string, string> row, string variable)
        {
            string text = EmptyIfNull(variable).Trim();
            if (text.Length == 0)
            {
                return false;
            }

            string dbPrefix = GetCsvValue(row, "DbName") + ".";
            if (text.StartsWith(dbPrefix, StringComparison.OrdinalIgnoreCase))
            {
                text = text.Substring(dbPrefix.Length);
            }

            return EqualsIgnoreCase(GetCsvValue(row, "VariablePath"), text)
                || EqualsIgnoreCase(GetCsvValue(row, "Name"), text);
        }

        private static List<string> RuntimeSnapshotRequestedVariables(Options options)
        {
            List<string> variables = new List<string>();
            if (!string.IsNullOrWhiteSpace(options.VarsText))
            {
                variables.AddRange(options.VarsText.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => x.Length > 0));
            }

            if (!string.IsNullOrWhiteSpace(options.VarListPath))
            {
                string path = Path.GetFullPath(options.VarListPath);
                if (!File.Exists(path))
                {
                    throw new FileNotFoundException("Runtime snapshot variable list was not found.", path);
                }

                foreach (string line in File.ReadAllLines(path, Encoding.UTF8))
                {
                    string trimmed = line.Trim();
                    if (trimmed.Length == 0 || trimmed.StartsWith("#", StringComparison.Ordinal))
                    {
                        continue;
                    }

                    variables.AddRange(trimmed.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => x.Length > 0));
                }
            }

            return variables
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static List<RuntimeSnapshotReadRangeRecord> BuildRuntimeSnapshotReadRanges(string snapshotId, DateTime timestampLocal, DateTime timestampUtc, string host, string dbName, string dbNumber, int start, int length, int maxReadBytes)
        {
            List<RuntimeSnapshotReadRangeRecord> ranges = new List<RuntimeSnapshotReadRangeRecord>();
            int end = start + length;
            int rangeId = 1;
            for (int offset = start; offset < end; offset += maxReadBytes)
            {
                int count = Math.Min(maxReadBytes, end - offset);
                ranges.Add(new RuntimeSnapshotReadRangeRecord
                {
                    SnapshotId = snapshotId,
                    TimestampUtc = timestampUtc.ToString("o", CultureInfo.InvariantCulture),
                    TimestampLocal = timestampLocal.ToString("o", CultureInfo.InvariantCulture),
                    Host = host,
                    DbName = dbName,
                    DbNumber = dbNumber,
                    RangeId = rangeId.ToString(CultureInfo.InvariantCulture),
                    StartByte = offset.ToString(CultureInfo.InvariantCulture),
                    LengthBytes = count.ToString(CultureInfo.InvariantCulture),
                    Status = "pending",
                    Message = string.Empty
                });
                rangeId++;
            }

            return ranges;
        }

        private static RuntimeSnapshotValueRecord BuildRuntimeSnapshotValueRecord(Dictionary<string, string> row, string snapshotId, DateTime timestampLocal, DateTime timestampUtc, string host, string mapCsv, int bufferStart, byte[] buffer, bool readOk, string readError)
        {
            string datatype = GetCsvValue(row, "Datatype");
            int byteOffset = ParseRequiredRuntimeInt(GetCsvValue(row, "ByteOffset"), "ByteOffset");
            int bitOffset = string.IsNullOrWhiteSpace(GetCsvValue(row, "BitOffset")) ? -1 : ParseRequiredRuntimeInt(GetCsvValue(row, "BitOffset"), "BitOffset");
            int lengthBytes = ParseRequiredRuntimeInt(GetCsvValue(row, "LengthBytes"), "LengthBytes");
            string quality = "ok";
            string value = string.Empty;
            string rawHex = string.Empty;
            string message = string.Empty;

            if (!readOk)
            {
                quality = "read-error";
                message = readError;
            }
            else if (!EqualsIgnoreCase(GetCsvValue(row, "Status"), "ok"))
            {
                quality = EqualsIgnoreCase(GetCsvValue(row, "Status"), "unknown-type") ? "unknown-type" : "unsupported-type";
                message = "Map row status is " + GetCsvValue(row, "Status") + ".";
            }
            else if (!RuntimeDatatypeCanRead(datatype, bitOffset))
            {
                quality = "unsupported-type";
                message = "Datatype is not supported by runtime decoder: " + datatype + ".";
            }
            else
            {
                int localOffset = byteOffset - bufferStart;
                if (localOffset < 0 || localOffset + lengthBytes > buffer.Length)
                {
                    quality = "out-of-selected-range";
                    message = "Variable bytes were not included in selected read range.";
                }
                else
                {
                    byte[] data = new byte[lengthBytes];
                    Buffer.BlockCopy(buffer, localOffset, data, 0, lengthBytes);
                    rawHex = ToHex(data).ToUpperInvariant();
                    try
                    {
                        value = DecodeRuntimeValue(datatype, data, bitOffset);
                    }
                    catch (Exception ex)
                    {
                        quality = "decode-error";
                        message = ex.Message;
                    }
                }
            }

            return new RuntimeSnapshotValueRecord
            {
                SnapshotId = snapshotId,
                TimestampUtc = timestampUtc.ToString("o", CultureInfo.InvariantCulture),
                TimestampLocal = timestampLocal.ToString("o", CultureInfo.InvariantCulture),
                Host = host,
                DbName = GetCsvValue(row, "DbName"),
                DbNumber = GetCsvValue(row, "DbNumber"),
                InstanceOf = GetCsvValue(row, "InstanceOf"),
                RootSection = GetCsvValue(row, "RootSection"),
                Section = GetCsvValue(row, "Section"),
                VariablePath = GetCsvValue(row, "VariablePath"),
                Name = GetCsvValue(row, "Name"),
                Datatype = datatype,
                ByteOffset = GetCsvValue(row, "ByteOffset"),
                BitOffset = GetCsvValue(row, "BitOffset"),
                LengthBytes = GetCsvValue(row, "LengthBytes"),
                AccessPolicy = GetCsvValue(row, "AccessPolicy"),
                MapStatus = GetCsvValue(row, "Status"),
                Quality = quality,
                Value = value,
                RawHex = rawHex,
                Message = message,
                SourceMap = mapCsv
            };
        }

        private static string ResolveRuntimeSnapshotRoot(Options options)
        {
            if (!string.IsNullOrWhiteSpace(options.OutDir))
            {
                return Path.GetFullPath(options.OutDir);
            }

            string cloneSnapshots = Path.Combine(Environment.CurrentDirectory, "CLONE_PROJECT", "_runtime_snapshots");
            if (Directory.Exists(Path.Combine(Environment.CurrentDirectory, "CLONE_PROJECT")))
            {
                return cloneSnapshots;
            }

            return ResolveOutputDirectory(options.OutDir, "plc-runtime-snapshot");
        }

        private static void WriteRuntimeSnapshotArtifacts(
            string snapshotDir,
            string snapshotId,
            DateTime startedLocal,
            DateTime startedUtc,
            DateTime finishedLocal,
            string host,
            string mapCsv,
            List<RuntimeSnapshotValueRecord> values,
            List<RuntimeSnapshotReadRangeRecord> ranges,
            List<RuntimeSnapshotRawBlock> rawBlocks,
            Options options)
        {
            WriteCsv(Path.Combine(snapshotDir, "snapshot-values.csv"), RuntimeSnapshotValueHeaders(), values.Select(RuntimeSnapshotValueRow));
            WriteCsv(Path.Combine(snapshotDir, "snapshot-read-ranges.csv"), RuntimeSnapshotReadRangeHeaders(), ranges.Select(RuntimeSnapshotReadRangeRow));
            WriteRuntimeSnapshotMarkdown(Path.Combine(snapshotDir, "snapshot-values.md"), values);
            WriteRuntimeSnapshotJson(Path.Combine(snapshotDir, "snapshot-values.json"), snapshotId, startedLocal, startedUtc, finishedLocal, host, mapCsv, values, ranges);
            WriteRuntimeSnapshotRaw(Path.Combine(snapshotDir, "snapshot-raw.hex"), rawBlocks);
            WriteRuntimeSnapshotSummary(Path.Combine(snapshotDir, "snapshot-summary.txt"), snapshotId, startedLocal, startedUtc, finishedLocal, host, mapCsv, values, ranges, rawBlocks, options);
        }

        private static string[] RuntimeSnapshotValueHeaders()
        {
            return new[]
            {
                "SnapshotId", "TimestampUtc", "TimestampLocal", "Host", "DbName", "DbNumber", "InstanceOf", "RootSection", "Section",
                "VariablePath", "Name", "Datatype", "ByteOffset", "BitOffset", "LengthBytes", "AccessPolicy", "MapStatus",
                "Quality", "Value", "RawHex", "Message", "SourceMap"
            };
        }

        private static string[] RuntimeSnapshotValueRow(RuntimeSnapshotValueRecord record)
        {
            return new[]
            {
                record.SnapshotId, record.TimestampUtc, record.TimestampLocal, record.Host, record.DbName, record.DbNumber, record.InstanceOf, record.RootSection, record.Section,
                record.VariablePath, record.Name, record.Datatype, record.ByteOffset, record.BitOffset, record.LengthBytes, record.AccessPolicy, record.MapStatus,
                record.Quality, record.Value, record.RawHex, record.Message, record.SourceMap
            };
        }

        private static string[] RuntimeSnapshotReadRangeHeaders()
        {
            return new[] { "SnapshotId", "TimestampUtc", "TimestampLocal", "Host", "DbName", "DbNumber", "RangeId", "StartByte", "LengthBytes", "Status", "Message", "StartedAt", "FinishedAt" };
        }

        private static string[] RuntimeSnapshotReadRangeRow(RuntimeSnapshotReadRangeRecord record)
        {
            return new[] { record.SnapshotId, record.TimestampUtc, record.TimestampLocal, record.Host, record.DbName, record.DbNumber, record.RangeId, record.StartByte, record.LengthBytes, record.Status, record.Message, record.StartedAt, record.FinishedAt };
        }

        private static void WriteRuntimeSnapshotMarkdown(string path, List<RuntimeSnapshotValueRecord> values)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("# PLC runtime snapshot values");
                writer.WriteLine();
                foreach (IGrouping<string, RuntimeSnapshotValueRecord> group in values.GroupBy(x => x.DbName + " [" + x.DbNumber + "]").OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase))
                {
                    writer.WriteLine("## " + group.Key);
                    writer.WriteLine();
                    writer.WriteLine("| Variable | Section | Type | Offset | Quality | Value | RawHex |");
                    writer.WriteLine("| --- | --- | --- | ---: | --- | --- | --- |");
                    foreach (RuntimeSnapshotValueRecord record in group.OrderBy(x => SafeInt(x.ByteOffset)).ThenBy(x => SafeInt(x.BitOffset)).ThenBy(x => x.VariablePath, StringComparer.OrdinalIgnoreCase))
                    {
                        string offset = record.ByteOffset + (string.IsNullOrWhiteSpace(record.BitOffset) ? string.Empty : "." + record.BitOffset);
                        writer.WriteLine("| " + MarkdownCell(record.VariablePath) + " | " + MarkdownCell(record.Section) + " | " + MarkdownCell(record.Datatype) + " | " + MarkdownCell(offset) + " | " + MarkdownCell(record.Quality) + " | " + MarkdownCell(record.Value) + " | " + MarkdownCell(record.RawHex) + " |");
                    }

                    writer.WriteLine();
                }
            }
        }

        private static string MarkdownCell(string value)
        {
            return EmptyIfNull(value).Replace("|", "\\|").Replace("\r", " ").Replace("\n", " ");
        }

        private static void WriteRuntimeSnapshotJson(string path, string snapshotId, DateTime startedLocal, DateTime startedUtc, DateTime finishedLocal, string host, string mapCsv, List<RuntimeSnapshotValueRecord> values, List<RuntimeSnapshotReadRangeRecord> ranges)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"snapshotId\": " + Json(snapshotId) + ",");
                writer.WriteLine("  \"startedAtUtc\": " + Json(startedUtc.ToString("o", CultureInfo.InvariantCulture)) + ",");
                writer.WriteLine("  \"startedAtLocal\": " + Json(startedLocal.ToString("o", CultureInfo.InvariantCulture)) + ",");
                writer.WriteLine("  \"finishedAtLocal\": " + Json(finishedLocal.ToString("o", CultureInfo.InvariantCulture)) + ",");
                writer.WriteLine("  \"host\": " + Json(host) + ",");
                writer.WriteLine("  \"sourceMap\": " + Json(mapCsv) + ",");
                WriteJsonArray(writer, "readRanges", ranges.Select(x => new Dictionary<string, string>
                {
                    { "dbName", x.DbName },
                    { "dbNumber", x.DbNumber },
                    { "rangeId", x.RangeId },
                    { "startByte", x.StartByte },
                    { "lengthBytes", x.LengthBytes },
                    { "status", x.Status },
                    { "message", x.Message }
                }), true);
                WriteJsonArray(writer, "values", values.Select(x => new Dictionary<string, string>
                {
                    { "dbName", x.DbName },
                    { "dbNumber", x.DbNumber },
                    { "variablePath", x.VariablePath },
                    { "section", x.Section },
                    { "datatype", x.Datatype },
                    { "byteOffset", x.ByteOffset },
                    { "bitOffset", x.BitOffset },
                    { "lengthBytes", x.LengthBytes },
                    { "accessPolicy", x.AccessPolicy },
                    { "quality", x.Quality },
                    { "value", x.Value },
                    { "rawHex", x.RawHex },
                    { "message", x.Message }
                }), false);
                writer.WriteLine("}");
            }
        }

        private static void WriteRuntimeSnapshotRaw(string path, List<RuntimeSnapshotRawBlock> rawBlocks)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                foreach (RuntimeSnapshotRawBlock block in rawBlocks.OrderBy(x => SafeInt(x.DbNumber)).ThenBy(x => x.DbName, StringComparer.OrdinalIgnoreCase))
                {
                    writer.WriteLine("DB " + block.DbName + " [" + block.DbNumber + "], start " + block.StartByte.ToString(CultureInfo.InvariantCulture) + ", length " + block.Data.Length.ToString(CultureInfo.InvariantCulture));
                    writer.WriteLine(HexDump(block.Data, block.StartByte));
                    writer.WriteLine();
                }
            }
        }

        private static void WriteRuntimeSnapshotSummary(string path, string snapshotId, DateTime startedLocal, DateTime startedUtc, DateTime finishedLocal, string host, string mapCsv, List<RuntimeSnapshotValueRecord> values, List<RuntimeSnapshotReadRangeRecord> ranges, List<RuntimeSnapshotRawBlock> rawBlocks, Options options)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("PLC runtime snapshot");
                writer.WriteLine("SnapshotId: " + snapshotId);
                writer.WriteLine("StartedAtUtc: " + startedUtc.ToString("o", CultureInfo.InvariantCulture));
                writer.WriteLine("StartedAtLocal: " + startedLocal.ToString("o", CultureInfo.InvariantCulture));
                writer.WriteLine("FinishedAtLocal: " + finishedLocal.ToString("o", CultureInfo.InvariantCulture));
                writer.WriteLine("Host: " + host);
                writer.WriteLine("Map: " + mapCsv);
                writer.WriteLine("Scope: " + FirstNonEmpty(options.Scope, "db"));
                writer.WriteLine("DB filter: " + FirstNonEmpty(options.DbName, options.DbNumber > 0 ? options.DbNumber.ToString(CultureInfo.InvariantCulture) : string.Empty, "<none>"));
                writer.WriteLine("Values: " + values.Count.ToString(CultureInfo.InvariantCulture));
                writer.WriteLine("Read ranges: " + ranges.Count.ToString(CultureInfo.InvariantCulture));
                writer.WriteLine("Raw DB blocks: " + rawBlocks.Count.ToString(CultureInfo.InvariantCulture));
                writer.WriteLine("Max read bytes: " + options.MaxReadBytes.ToString(CultureInfo.InvariantCulture));
                writer.WriteLine("Single read requested: " + (options.SingleRead ? "true" : "false"));
                writer.WriteLine();
                writer.WriteLine("Quality counts:");
                foreach (IGrouping<string, RuntimeSnapshotValueRecord> group in values.GroupBy(x => x.Quality).OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase))
                {
                    writer.WriteLine("  " + group.Key + ": " + group.Count().ToString(CultureInfo.InvariantCulture));
                }

                writer.WriteLine();
                writer.WriteLine("Read range status counts:");
                foreach (IGrouping<string, RuntimeSnapshotReadRangeRecord> group in ranges.GroupBy(x => x.Status).OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase))
                {
                    writer.WriteLine("  " + group.Key + ": " + group.Count().ToString(CultureInfo.InvariantCulture));
                }

                writer.WriteLine();
                writer.WriteLine("Note:");
                writer.WriteLine("  A single S7 ReadVar range is the closest practical timing slice for one DB.");
                writer.WriteLine("  Multiple ranges and multiple DBs are read sequentially and may span several PLC cycles.");
            }
        }

        private static string ResolveRuntimeMapCsv(Options options)
        {
            string path = options.MapPath;
            if (string.IsNullOrWhiteSpace(path))
            {
                string cloneMap = Path.Combine(Environment.CurrentDirectory, "CLONE_PROJECT", "_runtime_maps", "plc-runtime-map.csv");
                path = File.Exists(cloneMap)
                    ? cloneMap
                    : Path.Combine(ResolveToolDirectoryForCleanLocal(), "out", "plc-runtime-map-current", "plc-runtime-map.csv");
            }

            path = Path.GetFullPath(path);
            if (Directory.Exists(path))
            {
                path = Path.Combine(path, "plc-runtime-map.csv");
            }

            if (!File.Exists(path))
            {
                throw new FileNotFoundException("Runtime map CSV was not found. Run plc-runtime-map first.", path);
            }

            return path;
        }

        private static Dictionary<string, string> FindRuntimeMapEntry(string mapCsv, Options options)
        {
            List<Dictionary<string, string>> matches = ReadCsv(mapCsv)
                .Where(x => RuntimeMapDbMatches(x, options)
                    && EqualsIgnoreCase(GetCsvValue(x, "VariablePath"), options.VarName))
                .ToList();

            if (matches.Count == 0)
            {
                throw new InvalidOperationException("Variable was not found in runtime map: DB=" + FirstNonEmpty(options.DbName, options.DbNumber > 0 ? options.DbNumber.ToString(CultureInfo.InvariantCulture) : string.Empty) + ", var=" + options.VarName);
            }

            if (matches.Count > 1)
            {
                throw new InvalidOperationException("Runtime map lookup is ambiguous for DB=" + FirstNonEmpty(options.DbName, options.DbNumber.ToString(CultureInfo.InvariantCulture)) + ", var=" + options.VarName + ".");
            }

            string status = GetCsvValue(matches[0], "Status");
            if (!EqualsIgnoreCase(status, "ok"))
            {
                throw new InvalidOperationException("Variable is not a direct scalar map row. Status=" + status + ", datatype=" + GetCsvValue(matches[0], "Datatype") + ".");
            }

            return matches[0];
        }

        private static bool RuntimeMapDbMatches(Dictionary<string, string> row, Options options)
        {
            if (options.DbNumber > 0)
            {
                return SafeInt(GetCsvValue(row, "DbNumber")) == options.DbNumber;
            }

            return EqualsIgnoreCase(GetCsvValue(row, "DbName"), options.DbName);
        }

        private static int ParseRequiredRuntimeInt(string value, string fieldName)
        {
            int parsed;
            if (!int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out parsed))
            {
                throw new InvalidOperationException("Runtime map field '" + fieldName + "' is not an integer: " + value);
            }

            return parsed;
        }

        private static bool RuntimeDatatypeCanRead(string datatype, int bitOffset)
        {
            string normalized = NormalizeRuntimeDatatype(datatype);
            if (bitOffset >= 0)
            {
                return EqualsIgnoreCase(normalized, "Bool");
            }

            return EqualsIgnoreCase(normalized, "Byte")
                || EqualsIgnoreCase(normalized, "Word")
                || EqualsIgnoreCase(normalized, "Int")
                || EqualsIgnoreCase(normalized, "DWord")
                || EqualsIgnoreCase(normalized, "DInt")
                || EqualsIgnoreCase(normalized, "Real");
        }

        private static bool RuntimeDatatypeCanWrite(string datatype, int bitOffset)
        {
            return RuntimeDatatypeCanRead(datatype, bitOffset);
        }

        private static string DecodeRuntimeValue(string datatype, byte[] data, int bitOffset)
        {
            string normalized = NormalizeRuntimeDatatype(datatype);
            if (bitOffset >= 0)
            {
                bool value = (data[0] & (1 << bitOffset)) != 0;
                return value ? "TRUE" : "FALSE";
            }

            if (EqualsIgnoreCase(normalized, "Byte"))
            {
                return "BYTE#16#" + data[0].ToString("X2", CultureInfo.InvariantCulture) + " (" + data[0].ToString(CultureInfo.InvariantCulture) + ")";
            }

            if (EqualsIgnoreCase(normalized, "Word"))
            {
                ushort value = (ushort)((data[0] << 8) | data[1]);
                return "WORD#16#" + value.ToString("X4", CultureInfo.InvariantCulture) + " (" + value.ToString(CultureInfo.InvariantCulture) + ")";
            }

            if (EqualsIgnoreCase(normalized, "Int"))
            {
                short value = unchecked((short)((data[0] << 8) | data[1]));
                return value.ToString(CultureInfo.InvariantCulture);
            }

            if (EqualsIgnoreCase(normalized, "DWord"))
            {
                uint value = ((uint)data[0] << 24) | ((uint)data[1] << 16) | ((uint)data[2] << 8) | data[3];
                return "DWORD#16#" + value.ToString("X8", CultureInfo.InvariantCulture) + " (" + value.ToString(CultureInfo.InvariantCulture) + ")";
            }

            if (EqualsIgnoreCase(normalized, "DInt"))
            {
                int value = unchecked((int)(((uint)data[0] << 24) | ((uint)data[1] << 16) | ((uint)data[2] << 8) | data[3]));
                return value.ToString(CultureInfo.InvariantCulture);
            }

            if (EqualsIgnoreCase(normalized, "Real"))
            {
                byte[] copy = new byte[4];
                Buffer.BlockCopy(data, 0, copy, 0, 4);
                if (BitConverter.IsLittleEndian)
                {
                    Array.Reverse(copy);
                }

                return BitConverter.ToSingle(copy, 0).ToString(CultureInfo.InvariantCulture);
            }

            throw new InvalidOperationException("Unsupported runtime datatype: " + datatype);
        }

        private static byte[] BuildRuntimeWriteBytes(Dictionary<string, string> entry, string datatype, string valueText, byte[] current, int bitOffset)
        {
            string normalized = NormalizeRuntimeDatatype(datatype);
            if (bitOffset >= 0)
            {
                bool value = ParseRuntimeBool(valueText);
                byte next = current[0];
                if (value)
                {
                    next = (byte)(next | (1 << bitOffset));
                }
                else
                {
                    next = (byte)(next & ~(1 << bitOffset));
                }

                return new[] { next };
            }

            if (EqualsIgnoreCase(normalized, "Byte"))
            {
                return new[] { checked((byte)ParseRuntimeUnsigned(valueText, 0xFF)) };
            }

            if (EqualsIgnoreCase(normalized, "Word"))
            {
                ushort value = checked((ushort)ParseRuntimeUnsigned(valueText, 0xFFFF));
                return new[] { (byte)(value >> 8), (byte)(value & 0xFF) };
            }

            if (EqualsIgnoreCase(normalized, "Int"))
            {
                short value = checked((short)ParseRuntimeSigned(valueText, short.MinValue, short.MaxValue));
                return new[] { (byte)((value >> 8) & 0xFF), (byte)(value & 0xFF) };
            }

            if (EqualsIgnoreCase(normalized, "DWord"))
            {
                uint value = checked((uint)ParseRuntimeUnsigned(valueText, 0xFFFFFFFF));
                GuardRuntimeDwordWrite(entry, value);
                return new[] { (byte)(value >> 24), (byte)((value >> 16) & 0xFF), (byte)((value >> 8) & 0xFF), (byte)(value & 0xFF) };
            }

            if (EqualsIgnoreCase(normalized, "DInt"))
            {
                int value = checked((int)ParseRuntimeSigned(valueText, int.MinValue, int.MaxValue));
                return new[] { (byte)(value >> 24), (byte)((value >> 16) & 0xFF), (byte)((value >> 8) & 0xFF), (byte)(value & 0xFF) };
            }

            if (EqualsIgnoreCase(normalized, "Real"))
            {
                float value = float.Parse(valueText, CultureInfo.InvariantCulture);
                byte[] bytes = BitConverter.GetBytes(value);
                if (BitConverter.IsLittleEndian)
                {
                    Array.Reverse(bytes);
                }

                return bytes;
            }

            throw new InvalidOperationException("Unsupported runtime write datatype: " + datatype);
        }

        private static void GuardRuntimeDwordWrite(Dictionary<string, string> entry, uint value)
        {
            string dbName = GetCsvValue(entry, "DbName");
            string variablePath = GetCsvValue(entry, "VariablePath");
            if ((EqualsIgnoreCase(variablePath, "CommandMask") || EqualsIgnoreCase(variablePath, "AllowedOutputMask"))
                && (value & 0xFF000000u) != 0)
            {
                throw new InvalidOperationException("Refusing to write high output bits. " + dbName + "." + variablePath + " allows only bits 0..23, value must be <= DWORD#16#00FF_FFFF.");
            }
        }

        private static bool ParseRuntimeBool(string value)
        {
            if (EqualsIgnoreCase(value, "true") || EqualsIgnoreCase(value, "1") || EqualsIgnoreCase(value, "on") || EqualsIgnoreCase(value, "yes"))
            {
                return true;
            }

            if (EqualsIgnoreCase(value, "false") || EqualsIgnoreCase(value, "0") || EqualsIgnoreCase(value, "off") || EqualsIgnoreCase(value, "no"))
            {
                return false;
            }

            throw new FormatException("Invalid Bool value: " + value);
        }

        private static ulong ParseRuntimeUnsigned(string value, ulong max)
        {
            string normalized = NormalizeRuntimeNumericText(value);
            ulong parsed;
            if (normalized.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
            {
                parsed = ulong.Parse(normalized.Substring(2), NumberStyles.HexNumber, CultureInfo.InvariantCulture);
            }
            else
            {
                parsed = ulong.Parse(normalized, NumberStyles.Integer, CultureInfo.InvariantCulture);
            }

            if (parsed > max)
            {
                throw new OverflowException("Value is out of range: " + value);
            }

            return parsed;
        }

        private static long ParseRuntimeSigned(string value, long min, long max)
        {
            string normalized = NormalizeRuntimeNumericText(value);
            long parsed;
            if (normalized.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
            {
                parsed = unchecked((long)ulong.Parse(normalized.Substring(2), NumberStyles.HexNumber, CultureInfo.InvariantCulture));
            }
            else
            {
                parsed = long.Parse(normalized, NumberStyles.Integer, CultureInfo.InvariantCulture);
            }

            if (parsed < min || parsed > max)
            {
                throw new OverflowException("Value is out of range: " + value);
            }

            return parsed;
        }

        private static string NormalizeRuntimeNumericText(string value)
        {
            string text = EmptyIfNull(value).Trim().Replace("_", string.Empty);
            int hash = text.LastIndexOf('#');
            if (hash >= 0 && hash + 1 < text.Length)
            {
                string prefix = text.Substring(0, hash);
                string number = text.Substring(hash + 1);
                if (prefix.IndexOf("16", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return "0x" + number;
                }

                return number;
            }

            return text;
        }

        private static void PlcRuntimeMapCommand(Options options)
        {
            string cloneDir = string.IsNullOrWhiteSpace(options.InDir)
                ? Path.Combine(Environment.CurrentDirectory, "CLONE_PROJECT")
                : Path.GetFullPath(options.InDir);
            if (!Directory.Exists(cloneDir))
            {
                throw new DirectoryNotFoundException("CLONE_PROJECT directory was not found: " + cloneDir);
            }

            string blocksCsv = Path.Combine(cloneDir, "plc-blocks.csv");
            if (!File.Exists(blocksCsv))
            {
                blocksCsv = Path.Combine(cloneDir, "_inventory", "blocks.csv");
            }

            if (!File.Exists(blocksCsv))
            {
                throw new FileNotFoundException("PLC block manifest was not found. Run check-clone/init-clone first.", blocksCsv);
            }

            string outDir = ResolveOutputDirectory(options.OutDir, "plc-runtime-map");
            Directory.CreateDirectory(outDir);

            List<Dictionary<string, string>> blocks = LoadRuntimeMapBlockRows(cloneDir, blocksCsv);
            Dictionary<string, string> fbSources = blocks
                .Where(x => IsFbBlock(GetCsvValue(x, "TypeName")) && File.Exists(GetCsvValue(x, "FilePath")))
                .GroupBy(x => GetCsvValue(x, "Name"), StringComparer.OrdinalIgnoreCase)
                .ToDictionary(x => x.Key, x => GetCsvValue(x.First(), "FilePath"), StringComparer.OrdinalIgnoreCase);

            List<RuntimeMapRecord> records = new List<RuntimeMapRecord>();
            foreach (Dictionary<string, string> db in blocks
                .Where(x => IsInstanceDbType(GetCsvValue(x, "TypeName")) && !string.IsNullOrWhiteSpace(GetCsvValue(x, "InstanceOfName")))
                .OrderBy(x => SafeInt(GetCsvValue(x, "Number"))))
            {
                string instanceOf = GetCsvValue(db, "InstanceOfName");
                string fbSource;
                if (!fbSources.TryGetValue(instanceOf, out fbSource))
                {
                    records.Add(new RuntimeMapRecord
                    {
                        DbName = GetCsvValue(db, "Name"),
                        DbNumber = GetCsvValue(db, "Number"),
                        InstanceOf = instanceOf,
                        Status = "fb-source-not-found"
                    });
                    continue;
                }
                AddRuntimeMapSourceFields(records, db, fbSource, ParseRuntimeMapSclFields(fbSource), fbSources);
            }

            foreach (Dictionary<string, string> db in blocks
                .Where(x => IsGlobalDbType(GetCsvValue(x, "TypeName")) && File.Exists(GetCsvValue(x, "FilePath")))
                .OrderBy(x => SafeInt(GetCsvValue(x, "Number"))))
            {
                string dbSource = GetCsvValue(db, "FilePath");
                AddRuntimeMapSourceFields(records, db, dbSource, ParseRuntimeMapDbFields(dbSource), fbSources);
            }

            WriteRuntimeMapArtifacts(outDir, records, cloneDir, blocksCsv);

            string cloneRuntimeMapDir = Path.Combine(cloneDir, "_runtime_maps");
            if (!SameDirectory(outDir, cloneRuntimeMapDir))
            {
                WriteRuntimeMapArtifacts(cloneRuntimeMapDir, records, cloneDir, blocksCsv);
            }

            Console.WriteLine("PLC runtime map written to: " + outDir);
            Console.WriteLine("PLC runtime map mirrored to: " + cloneRuntimeMapDir);
            Console.WriteLine("Rows: " + records.Count.ToString(CultureInfo.InvariantCulture));
        }

        private static void AddRuntimeMapSourceFields(List<RuntimeMapRecord> records, Dictionary<string, string> db, string sourceFile, IEnumerable<RuntimeMapField> fields, Dictionary<string, string> fbSources)
        {
            RuntimeLayoutCursor cursor = new RuntimeLayoutCursor();
            string previousSection = string.Empty;
            foreach (RuntimeMapField field in fields)
            {
                AlignRuntimeSectionBoundaryOnChange(cursor, ref previousSection, field.Section);
                AddRuntimeMapField(records, db, sourceFile, field, field.Name, field.Section, cursor, fbSources, new HashSet<string>(StringComparer.OrdinalIgnoreCase));
            }
            AlignRuntimeByte(cursor);
        }

        private static void WriteRuntimeMapArtifacts(string outDir, List<RuntimeMapRecord> records, string cloneDir, string blocksCsv)
        {
            Directory.CreateDirectory(outDir);
            WriteCsv(Path.Combine(outDir, "plc-runtime-map.csv"),
                RuntimeMapHeaders(),
                records.Select(RuntimeMapRow));

            using (StreamWriter writer = NewUtf8Writer(Path.Combine(outDir, "plc-runtime-map-summary.txt")))
            {
                writer.WriteLine("PLC runtime map");
                writer.WriteLine("Generated: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture));
                writer.WriteLine("Clone directory: " + cloneDir);
                writer.WriteLine("Blocks manifest: " + blocksCsv);
                writer.WriteLine("Rows: " + records.Count.ToString(CultureInfo.InvariantCulture));
                foreach (IGrouping<string, RuntimeMapRecord> group in records.GroupBy(x => FirstNonEmpty(x.Status, "ok")).OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase))
                {
                    writer.WriteLine("Status " + group.Key + ": " + group.Count().ToString(CultureInfo.InvariantCulture));
                }
            }

            WriteRuntimeMapMarkdown(Path.Combine(outDir, "plc-runtime-map.md"), records, cloneDir, blocksCsv, string.Empty);
            foreach (IGrouping<string, RuntimeMapRecord> group in records
                .Where(x => !string.IsNullOrWhiteSpace(x.DbName))
                .GroupBy(x => x.DbName, StringComparer.OrdinalIgnoreCase)
                .OrderBy(x => SafeInt(x.First().DbNumber))
                .ThenBy(x => x.Key, StringComparer.OrdinalIgnoreCase))
            {
                WriteRuntimeMapMarkdown(Path.Combine(outDir, SafeFileName(group.Key) + ".md"), group.ToList(), cloneDir, blocksCsv, group.Key);
            }
        }

        private static void WriteRuntimeMapMarkdown(string path, IEnumerable<RuntimeMapRecord> records, string cloneDir, string blocksCsv, string dbFilter)
        {
            List<RuntimeMapRecord> rows = records.ToList();
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine(string.IsNullOrWhiteSpace(dbFilter) ? "# PLC runtime offset map" : "# PLC runtime offset map: " + dbFilter);
                writer.WriteLine();
                writer.WriteLine("- Generated: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture));
                writer.WriteLine("- Clone directory: `" + cloneDir + "`");
                writer.WriteLine("- Blocks manifest: `" + blocksCsv + "`");
                writer.WriteLine("- Rows: " + rows.Count.ToString(CultureInfo.InvariantCulture));
                writer.WriteLine();

                foreach (IGrouping<string, RuntimeMapRecord> dbGroup in rows
                    .Where(x => !string.IsNullOrWhiteSpace(x.DbName))
                    .GroupBy(x => x.DbName, StringComparer.OrdinalIgnoreCase)
                    .OrderBy(x => SafeInt(x.First().DbNumber))
                    .ThenBy(x => x.Key, StringComparer.OrdinalIgnoreCase))
                {
                    RuntimeMapRecord first = dbGroup.First();
                    writer.WriteLine("## " + dbGroup.Key + " [DB" + first.DbNumber + "]");
                    writer.WriteLine();
                    writer.WriteLine("- Instance of: `" + first.InstanceOf + "`");
                    writer.WriteLine("- Rows: " + dbGroup.Count().ToString(CultureInfo.InvariantCulture));
                    writer.WriteLine();
                    writer.WriteLine("| Variable | Section | Type | Offset | Length | Access | Status |");
                    writer.WriteLine("| --- | --- | --- | --- | ---: | --- | --- |");
                    foreach (RuntimeMapRecord record in dbGroup.OrderBy(x => SafeInt(x.ByteOffset)).ThenBy(x => SafeInt(x.BitOffset)).ThenBy(x => x.VariablePath, StringComparer.OrdinalIgnoreCase))
                    {
                        writer.WriteLine("| " + MdCell(record.VariablePath)
                            + " | " + MdCell(FirstNonEmpty(record.RootSection, record.Section))
                            + " | " + MdCell(record.Datatype)
                            + " | " + MdCell(RuntimeOffsetText(record))
                            + " | " + MdCell(record.LengthBytes)
                            + " | " + MdCell(record.AccessPolicy)
                            + " | " + MdCell(record.Status)
                            + " |");
                    }

                    writer.WriteLine();
                }
            }
        }

        private static string RuntimeOffsetText(RuntimeMapRecord record)
        {
            if (string.IsNullOrWhiteSpace(record.ByteOffset))
            {
                return string.Empty;
            }

            return string.IsNullOrWhiteSpace(record.BitOffset)
                ? record.ByteOffset
                : record.ByteOffset + "." + record.BitOffset;
        }

        private static bool SameDirectory(string left, string right)
        {
            string leftFull = Path.GetFullPath(left).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            string rightFull = Path.GetFullPath(right).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            return EqualsIgnoreCase(leftFull, rightFull);
        }

        private static List<Dictionary<string, string>> LoadRuntimeMapBlockRows(string cloneDir, string blocksCsv)
        {
            List<Dictionary<string, string>> rows = File.Exists(blocksCsv)
                ? ReadCsv(blocksCsv)
                : new List<Dictionary<string, string>>();

            string rootDir = Path.Combine(cloneDir, "_root");
            if (!Directory.Exists(rootDir))
            {
                return rows;
            }

            HashSet<string> knownPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (Dictionary<string, string> row in rows)
            {
                string path = GetCsvValue(row, "FilePath");
                if (!string.IsNullOrWhiteSpace(path))
                {
                    knownPaths.Add(Path.GetFullPath(path));
                }
            }

            foreach (string file in Directory.GetFiles(rootDir, "*", SearchOption.AllDirectories).Where(IsKnownSourceFile).OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
            {
                string fullPath = Path.GetFullPath(file);
                if (knownPaths.Contains(fullPath))
                {
                    continue;
                }

                rows.Add(RuntimeMapBlockRowFromCloneRecord(CreateCloneBlockRecordFromSourceFile(rootDir, file, "Loaded from clone file scan.")));
                knownPaths.Add(fullPath);
            }

            return rows;
        }

        private static Dictionary<string, string> RuntimeMapBlockRowFromCloneRecord(CloneBlockRecord block)
        {
            Dictionary<string, string> row = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            row["SoftwarePath"] = EmptyIfNull(block.SoftwarePath);
            row["GroupPath"] = EmptyIfNull(block.GroupPath);
            row["GroupPathDisplay"] = EmptyIfNull(block.GroupPathDisplay);
            row["GroupPathKey"] = EmptyIfNull(block.GroupPath);
            row["Name"] = EmptyIfNull(block.Name);
            row["Number"] = EmptyIfNull(block.Number);
            row["AutoNumber"] = EmptyIfNull(block.AutoNumber);
            row["NumberMode"] = EmptyIfNull(block.NumberMode);
            row["NumberSpace"] = EmptyIfNull(block.NumberSpace);
            row["ProgrammingLanguage"] = EmptyIfNull(block.ProgrammingLanguage);
            row["BlockType"] = EmptyIfNull(block.BlockType);
            row["TypeName"] = EmptyIfNull(block.TypeName);
            row["SourceTypeName"] = EmptyIfNull(block.SourceTypeName);
            row["InstanceOfName"] = EmptyIfNull(block.InstanceOfName);
            row["InstanceOfNumber"] = EmptyIfNull(block.InstanceOfNumber);
            row["InstanceOfType"] = EmptyIfNull(block.InstanceOfType);
            row["SecondaryType"] = EmptyIfNull(block.SecondaryType);
            row["MemoryLayout"] = EmptyIfNull(block.MemoryLayout);
            row["IsConsistent"] = EmptyIfNull(block.IsConsistent);
            row["IsKnowHowProtected"] = EmptyIfNull(block.IsKnowHowProtected);
            row["TiaObjectId"] = EmptyIfNull(block.TiaObjectId);
            row["TiaObjectIdStatus"] = EmptyIfNull(block.TiaObjectIdStatus);
            row["FilePath"] = EmptyIfNull(block.ClonePath);
            row["SourceSha256"] = EmptyIfNull(block.SourceSha256);
            row["NormalizedSourceSha256"] = EmptyIfNull(block.NormalizedSourceSha256);
            row["Status"] = EmptyIfNull(block.ExportStatus);
            row["Message"] = EmptyIfNull(block.ExportMessage);
            return row;
        }

        private static string[] RuntimeMapHeaders()
        {
            return new[]
            {
                "DbName", "DbNumber", "InstanceOf", "RootSection", "Section", "VariablePath", "Name", "Datatype",
                "ByteOffset", "BitOffset", "LengthBytes", "AccessPolicy", "Status", "SourceFile"
            };
        }

        private static string[] RuntimeMapRow(RuntimeMapRecord record)
        {
            return new[]
            {
                record.DbName,
                record.DbNumber,
                record.InstanceOf,
                record.RootSection,
                record.Section,
                record.VariablePath,
                record.Name,
                record.Datatype,
                record.ByteOffset,
                record.BitOffset,
                record.LengthBytes,
                record.AccessPolicy,
                record.Status,
                record.SourceFile
            };
        }

        private static List<RuntimeMapField> ParseRuntimeMapSclFields(string path)
        {
            List<RuntimeMapField> fields = new List<RuntimeMapField>();
            Stack<RuntimeMapField> structs = new Stack<RuntimeMapField>();
            string section = string.Empty;
            bool includeSection = false;

            foreach (string rawLine in File.ReadAllLines(path, Encoding.UTF8))
            {
                string line = StripSclLineComment(rawLine).Trim();
                if (line.Length == 0)
                {
                    continue;
                }

                if (StartsWithIgnoreCase(line, "VAR_INPUT"))
                {
                    section = "Input";
                    includeSection = true;
                    structs.Clear();
                    continue;
                }

                if (StartsWithIgnoreCase(line, "VAR_OUTPUT"))
                {
                    section = "Output";
                    includeSection = true;
                    structs.Clear();
                    continue;
                }

                if (StartsWithIgnoreCase(line, "VAR_IN_OUT"))
                {
                    section = "InOut";
                    includeSection = true;
                    structs.Clear();
                    continue;
                }

                if (StartsWithIgnoreCase(line, "VAR_TEMP") || StartsWithIgnoreCase(line, "VAR CONSTANT"))
                {
                    section = string.Empty;
                    includeSection = false;
                    structs.Clear();
                    continue;
                }

                if (EqualsIgnoreCase(line, "VAR") || StartsWithIgnoreCase(line, "VAR "))
                {
                    section = "Static";
                    includeSection = true;
                    structs.Clear();
                    continue;
                }

                if (StartsWithIgnoreCase(line, "END_VAR"))
                {
                    section = string.Empty;
                    includeSection = false;
                    structs.Clear();
                    continue;
                }

                if (!includeSection)
                {
                    continue;
                }

                if (StartsWithIgnoreCase(line, "END_STRUCT"))
                {
                    if (structs.Count > 0)
                    {
                        structs.Pop();
                    }

                    continue;
                }

                RuntimeMapField field = TryParseRuntimeMapField(line, section);
                if (field == null)
                {
                    continue;
                }

                if (structs.Count > 0)
                {
                    structs.Peek().Children.Add(field);
                }
                else
                {
                    fields.Add(field);
                }

                if (EqualsIgnoreCase(field.Datatype, "Struct"))
                {
                    structs.Push(field);
                }
            }

            return fields;
        }

        private static List<RuntimeMapField> ParseRuntimeMapDbFields(string path)
        {
            List<RuntimeMapField> fields = new List<RuntimeMapField>();
            Stack<RuntimeMapField> structs = new Stack<RuntimeMapField>();
            bool dataBlockSeen = false;
            bool includeStruct = false;

            foreach (string rawLine in File.ReadAllLines(path, Encoding.UTF8))
            {
                string line = StripSclLineComment(rawLine).Trim();
                if (line.Length == 0)
                {
                    continue;
                }

                if (!dataBlockSeen)
                {
                    if (StartsWithIgnoreCase(line, "DATA_BLOCK"))
                    {
                        dataBlockSeen = true;
                    }

                    continue;
                }

                if (StartsWithIgnoreCase(line, "BEGIN"))
                {
                    break;
                }

                if (!includeStruct)
                {
                    if (StartsWithIgnoreCase(line, "STRUCT"))
                    {
                        includeStruct = true;
                        structs.Clear();
                    }

                    continue;
                }

                if (StartsWithIgnoreCase(line, "END_STRUCT"))
                {
                    if (structs.Count > 0)
                    {
                        structs.Pop();
                    }
                    else
                    {
                        break;
                    }

                    continue;
                }

                RuntimeMapField field = TryParseRuntimeMapField(line, "Data");
                if (field == null)
                {
                    continue;
                }

                if (structs.Count > 0)
                {
                    structs.Peek().Children.Add(field);
                }
                else
                {
                    fields.Add(field);
                }

                if (EqualsIgnoreCase(field.Datatype, "Struct"))
                {
                    structs.Push(field);
                }
            }

            return fields;
        }

        private static RuntimeMapField TryParseRuntimeMapField(string line, string section)
        {
            Match match = Regex.Match(line, "^(?:\"([^\"]+)\"|([A-Za-z_][A-Za-z0-9_]*))\\s*(?:\\{[^}]*\\})?\\s*:\\s*(.+?)(?:;)?$");
            if (!match.Success)
            {
                return null;
            }

            string name = match.Groups[1].Success ? match.Groups[1].Value : match.Groups[2].Value;
            string datatype = match.Groups[3].Value.Trim();
            int initIndex = datatype.IndexOf(":=", StringComparison.Ordinal);
            if (initIndex >= 0)
            {
                datatype = datatype.Substring(0, initIndex).Trim();
            }

            datatype = datatype.TrimEnd(';').Trim();
            return new RuntimeMapField { Name = name, Datatype = datatype, Section = section };
        }

        private static string StripSclLineComment(string line)
        {
            int index = line.IndexOf("//", StringComparison.Ordinal);
            return index >= 0 ? line.Substring(0, index) : line;
        }

        private static void AddRuntimeMapField(List<RuntimeMapRecord> records, Dictionary<string, string> db, string sourceFile, RuntimeMapField field, string variablePath, string rootSection, RuntimeLayoutCursor cursor, Dictionary<string, string> fbSources, HashSet<string> visiting)
        {
            string normalizedType = NormalizeRuntimeDatatype(field.Datatype);
            if (EqualsIgnoreCase(normalizedType, "Struct"))
            {
                AlignRuntimeByte(cursor);
                int start = cursor.ByteOffset;
                foreach (RuntimeMapField child in field.Children)
                {
                    AddRuntimeMapField(records, db, sourceFile, child, variablePath + "." + child.Name, rootSection, cursor, fbSources, visiting);
                }
                records.Add(CreateRuntimeMapRecord(db, sourceFile, field, variablePath, rootSection, start, -1, cursor.ByteOffset - start + (cursor.BitOffset > 0 ? 1 : 0), "struct"));
                return;
            }

            RuntimeArrayInfo arrayInfo;
            if (TryParseRuntimeArray(normalizedType, out arrayInfo))
            {
                AlignRuntimeByte(cursor);
                if (ClassicDatatypeAlignment(arrayInfo.ElementType) > 1 && (cursor.ByteOffset % 2) != 0)
                {
                    cursor.ByteOffset++;
                }
                int offset = cursor.ByteOffset;
                int length = arrayInfo.Count * ClassicDatatypeSize(arrayInfo.ElementType);
                cursor.ByteOffset += length;
                records.Add(CreateRuntimeMapRecord(db, sourceFile, field, variablePath, rootSection, offset, -1, length, "ok"));
                return;
            }

            if (EqualsIgnoreCase(normalizedType, "Bool"))
            {
                if (cursor.BitOffset >= 8)
                {
                    cursor.ByteOffset++;
                    cursor.BitOffset = 0;
                }
                int offset = cursor.ByteOffset;
                int bit = cursor.BitOffset;
                cursor.BitOffset++;
                records.Add(CreateRuntimeMapRecord(db, sourceFile, field, variablePath, rootSection, offset, bit, 1, "ok"));
                return;
            }

            int simpleSize = ClassicDatatypeSize(normalizedType);
            if (simpleSize > 0)
            {
                AlignRuntimeByte(cursor);
                if (ClassicDatatypeAlignment(normalizedType) > 1 && (cursor.ByteOffset % 2) != 0)
                {
                    cursor.ByteOffset++;
                }
                int offset = cursor.ByteOffset;
                cursor.ByteOffset += simpleSize;
                records.Add(CreateRuntimeMapRecord(db, sourceFile, field, variablePath, rootSection, offset, -1, simpleSize, "ok"));
                return;
            }

            int knownSize;
            if (TryGetRuntimeKnownBlockSize(normalizedType, out knownSize))
            {
                AlignRuntimeByte(cursor);
                if ((cursor.ByteOffset % 2) != 0)
                {
                    cursor.ByteOffset++;
                }
                int offset = cursor.ByteOffset;
                cursor.ByteOffset += knownSize;
                records.Add(CreateRuntimeMapRecord(db, sourceFile, field, variablePath, rootSection, offset, -1, knownSize, "opaque-known-size"));
                return;
            }

            string nestedSource;
            if (fbSources.TryGetValue(normalizedType, out nestedSource) && !visiting.Contains(normalizedType))
            {
                AlignRuntimeByte(cursor);
                if ((cursor.ByteOffset % 2) != 0)
                {
                    cursor.ByteOffset++;
                }
                int offset = cursor.ByteOffset;
                visiting.Add(normalizedType);
                string previousSection = string.Empty;
                foreach (RuntimeMapField child in ParseRuntimeMapSclFields(nestedSource))
                {
                    AlignRuntimeSectionBoundaryOnChange(cursor, ref previousSection, child.Section);
                    AddRuntimeMapField(records, db, nestedSource, child, variablePath + "." + child.Name, rootSection, cursor, fbSources, visiting);
                }
                visiting.Remove(normalizedType);
                records.Add(CreateRuntimeMapRecord(db, sourceFile, field, variablePath, rootSection, offset, -1, cursor.ByteOffset - offset + (cursor.BitOffset > 0 ? 1 : 0), "nested-fb"));
                return;
            }

            AlignRuntimeByte(cursor);
            records.Add(CreateRuntimeMapRecord(db, sourceFile, field, variablePath, rootSection, cursor.ByteOffset, -1, 0, "unknown-type"));
        }

        private static RuntimeMapRecord CreateRuntimeMapRecord(Dictionary<string, string> db, string sourceFile, RuntimeMapField field, string variablePath, string rootSection, int byteOffset, int bitOffset, int lengthBytes, string status)
        {
            return new RuntimeMapRecord
            {
                DbName = GetCsvValue(db, "Name"),
                DbNumber = GetCsvValue(db, "Number"),
                InstanceOf = GetCsvValue(db, "InstanceOfName"),
                RootSection = rootSection,
                Section = field.Section,
                VariablePath = variablePath,
                Name = field.Name,
                Datatype = field.Datatype,
                ByteOffset = byteOffset >= 0 ? byteOffset.ToString(CultureInfo.InvariantCulture) : string.Empty,
                BitOffset = bitOffset >= 0 ? bitOffset.ToString(CultureInfo.InvariantCulture) : string.Empty,
                LengthBytes = lengthBytes > 0 ? lengthBytes.ToString(CultureInfo.InvariantCulture) : string.Empty,
                AccessPolicy = EqualsIgnoreCase(rootSection, "Input") || EqualsIgnoreCase(rootSection, "InOut") || EqualsIgnoreCase(rootSection, "Data") ? "write-candidate" : "read-only",
                Status = status,
                SourceFile = sourceFile
            };
        }

        private static void AlignRuntimeByte(RuntimeLayoutCursor cursor)
        {
            if (cursor.BitOffset > 0)
            {
                cursor.ByteOffset++;
                cursor.BitOffset = 0;
            }
        }

        private static void AlignRuntimeSectionBoundaryOnChange(RuntimeLayoutCursor cursor, ref string previousSection, string section)
        {
            if (EqualsIgnoreCase(previousSection, section))
            {
                return;
            }

            if (!string.IsNullOrWhiteSpace(previousSection))
            {
                AlignRuntimeByte(cursor);
                if ((cursor.ByteOffset % 2) != 0)
                {
                    cursor.ByteOffset++;
                }
            }

            previousSection = section;
        }

        private static string NormalizeRuntimeDatatype(string datatype)
        {
            return (datatype ?? string.Empty).Trim().Trim('"');
        }

        private static bool TryParseRuntimeArray(string datatype, out RuntimeArrayInfo info)
        {
            info = null;
            Match match = Regex.Match(datatype, @"^Array\s*\[\s*(-?\d+)\s*\.\.\s*(-?\d+)\s*\]\s+of\s+(.+)$", RegexOptions.IgnoreCase);
            if (!match.Success)
            {
                return false;
            }
            int low = int.Parse(match.Groups[1].Value, CultureInfo.InvariantCulture);
            int high = int.Parse(match.Groups[2].Value, CultureInfo.InvariantCulture);
            string elementType = NormalizeRuntimeDatatype(match.Groups[3].Value);
            if (high < low || ClassicDatatypeSize(elementType) <= 0)
            {
                return false;
            }
            info = new RuntimeArrayInfo { Low = low, High = high, Count = high - low + 1, ElementType = elementType };
            return true;
        }

        private static bool TryGetRuntimeKnownBlockSize(string typeName, out int size)
        {
            if (EqualsIgnoreCase(typeName, "TCON")) { size = 20; return true; }
            if (EqualsIgnoreCase(typeName, "TDISCON")) { size = 10; return true; }
            if (EqualsIgnoreCase(typeName, "TSEND")) { size = 22; return true; }
            if (EqualsIgnoreCase(typeName, "TRCV")) { size = 24; return true; }
            size = 0;
            return false;
        }

        private static string ResolveToolDirectoryForCleanLocal()
        {
            string current = Path.GetFullPath(Environment.CurrentDirectory);
            if (File.Exists(Path.Combine(current, "Program.cs")) && IsToolDirectoryName(Path.GetFileName(current)))
            {
                return current;
            }

            foreach (string toolDirectoryName in ToolDirectoryNames)
            {
                string child = Path.Combine(current, toolDirectoryName);
                if (File.Exists(Path.Combine(child, "Program.cs")))
                {
                    return Path.GetFullPath(child);
                }
            }

            DirectoryInfo baseDir = new DirectoryInfo(AppDomain.CurrentDomain.BaseDirectory);
            DirectoryInfo candidate = baseDir.Name.Equals("bin", StringComparison.OrdinalIgnoreCase) && baseDir.Parent != null
                ? baseDir.Parent
                : baseDir;
            if (File.Exists(Path.Combine(candidate.FullName, "Program.cs")))
            {
                return candidate.FullName;
            }

            throw new DirectoryNotFoundException("Could not resolve " + ProductName + " tool directory from current directory or executable location.");
        }

        private static bool IsToolDirectoryName(string name)
        {
            return ToolDirectoryNames.Any(x => EqualsIgnoreCase(name, x));
        }

        private static string ResolveCleanLocalReportDirectory(string toolDir, Options options)
        {
            if (!string.IsNullOrWhiteSpace(options.OutDir) && !EqualsIgnoreCase(NormalizeCleanLocalScope(options.Scope), "workspace-transient"))
            {
                return Path.GetFullPath(options.OutDir);
            }

            return options.Apply
                ? Path.Combine(toolDir, "clean-local-last")
                : Path.Combine(toolDir, "out", "clean-local-current");
        }

        private static List<CleanLocalCandidate> BuildCleanLocalCandidates(string projectRoot, string toolDir, string cloneDir, string scope)
        {
            List<CleanLocalCandidate> candidates = new List<CleanLocalCandidate>();
            string binDir = Path.Combine(toolDir, "bin");
            string outDir = Path.Combine(toolDir, "out");
            bool runningFromBin = IsPathUnder(AppDomain.CurrentDomain.BaseDirectory, binDir);

            AddCleanLocalCandidate(candidates, scope, "probe-generated", "probe-build-output", EqualsIgnoreCase(scope, "probe-generated") && !runningFromBin ? "delete" : EqualsIgnoreCase(scope, "probe-generated") ? "manual-delete" : "candidate-delete", binDir, projectRoot, "Compiled executable output; rebuilt by build.cmd.", runningFromBin ? "Running executable is under this directory; delete manually after the process exits." : "Allowed only in probe-generated scope.");
            AddCleanLocalCandidate(candidates, scope, "probe-generated", "probe-output", EqualsIgnoreCase(scope, "probe-generated") ? "delete" : "candidate-delete", outDir, projectRoot, "Generated reports, probes, self-test outputs, and project-specific XML/CSV snapshots.", "Allowed only in probe-generated scope.");

            AddCleanLocalCandidate(candidates, scope, "workspace", "project-workspace", "keep", cloneDir, projectRoot, "Current project PLC/HMI clone baseline and reports.", "Project-specific workspace; do not remove as portable tool cleanup.");

            string[] transient =
            {
                "_compare",
                "_hmi_compare",
                "_preflight",
                "_hmi_preflight",
                "_sync-backups",
                "_hmi_sync_backups",
                "_hmi_sync_staging",
                "_hmi_import_probe",
                "_hmi_project_texts_import_probe",
                "_hmi_project_texts_apply",
                "_hmi_project_texts_apply_preflight",
                "_tmp_project_texts_inspect"
            };

            foreach (string name in transient)
            {
                AddCleanLocalCandidate(candidates, scope, "workspace-transient", "workspace-audit-artifact", EqualsIgnoreCase(scope, "workspace-transient") ? "candidate-delete" : "keep", Path.Combine(cloneDir, name), projectRoot, "Transient compare/preflight/probe artifacts inside CLONE_PROJECT.", "Audit-only in this version; review manually.");
            }

            string backupRoot = Path.Combine(Path.GetPathRoot(Path.GetFullPath(projectRoot)), "TIA_PROJECT_BACKUPS");
            AddCleanLocalCandidate(candidates, scope, "external-backup", "tia-project-backups", "keep", backupRoot, projectRoot, "External recovery backups created before write commands.", "Never deleted by clean-local.");

            string hmiProbeRoot = Path.Combine(Path.GetPathRoot(Path.GetFullPath(projectRoot)), "TIA_HMI_IMPORT_PROBE");
            AddCleanLocalCandidate(candidates, scope, "external-probe", "hmi-import-probe-copies", "keep", hmiProbeRoot, projectRoot, "Copied projects used for HMI import rehearsals.", "Never deleted by clean-local.");

            string[] tiaFolders = { "AdditionalFiles", "IM", "Logs", "Openness", "src", "System", "tmp", "UserFiles", "Vci", "XRef" };
            foreach (string name in tiaFolders)
            {
                AddCleanLocalCandidate(candidates, scope, "tia-project", "tia-project-folder", "keep", Path.Combine(projectRoot, name), projectRoot, "TIA Portal project folder.", "Never deleted by clean-local.");
            }

            return candidates;
        }

        private static void AddCleanLocalCandidate(List<CleanLocalCandidate> candidates, string scope, string cleanScope, string category, string action, string path, string projectRoot, string reason, string safety)
        {
            string fullPath = Path.GetFullPath(path);
            CleanLocalCandidate candidate = new CleanLocalCandidate
            {
                Scope = cleanScope,
                Category = category,
                Action = action,
                Path = fullPath,
                RelativePath = MakeRelativePathOrAbsolute(projectRoot, fullPath),
                Exists = File.Exists(fullPath) || Directory.Exists(fullPath),
                Reason = reason,
                Safety = safety,
                Status = "pending",
                Message = string.Empty
            };

            PopulateCleanLocalSize(candidate);

            if (!candidate.Exists)
            {
                candidate.Status = "missing";
                candidate.Message = "Path does not exist.";
            }
            else if (!EqualsIgnoreCase(action, "delete"))
            {
                candidate.Status = EqualsIgnoreCase(action, "manual-delete") ? "skipped" : "dry-run";
                candidate.Message = EqualsIgnoreCase(action, "manual-delete") ? "Deletion is deferred/manual for this running process." : "No deletion planned for scope '" + scope + "'.";
            }

            candidates.Add(candidate);
        }

        private static void PopulateCleanLocalSize(CleanLocalCandidate candidate)
        {
            try
            {
                if (candidate != null
                    && EqualsIgnoreCase(candidate.Action, "keep")
                    && StartsWithIgnoreCase(candidate.Scope, "external-"))
                {
                    // External backup/probe roots can be very large and are
                    // never deleted by this command. Do not recursively scan
                    // unrelated recovery data merely to produce an audit row.
                    return;
                }

                if (File.Exists(candidate.Path))
                {
                    FileInfo file = new FileInfo(candidate.Path);
                    candidate.FileCount = 1;
                    candidate.TotalBytes = file.Length;
                    return;
                }

                if (Directory.Exists(candidate.Path))
                {
                    DirectoryInfo dir = new DirectoryInfo(candidate.Path);
                    long files = 0;
                    long bytes = 0;
                    foreach (FileInfo file in dir.GetFiles("*", SearchOption.AllDirectories))
                    {
                        files++;
                        bytes += file.Length;
                    }

                    candidate.FileCount = files;
                    candidate.TotalBytes = bytes;
                }
            }
            catch (Exception ex)
            {
                candidate.Message = "Could not count files: " + ex.Message;
            }
        }

        private static void ApplyCleanLocalDeletes(List<CleanLocalCandidate> candidates, string projectRoot, string toolDir)
        {
            foreach (CleanLocalCandidate candidate in candidates.Where(x => EqualsIgnoreCase(x.Action, "delete")).ToList())
            {
                if (!candidate.Exists)
                {
                    candidate.Status = "missing";
                    candidate.Message = "Path does not exist.";
                    continue;
                }

                try
                {
                    ValidateCleanLocalDeleteTarget(candidate.Path, projectRoot, toolDir);
                    if (File.Exists(candidate.Path))
                    {
                        File.Delete(candidate.Path);
                    }
                    else
                    {
                        Directory.Delete(candidate.Path, true);
                    }

                    candidate.Status = "deleted";
                    candidate.Message = "Deleted.";
                }
                catch (Exception ex)
                {
                    candidate.Status = "failed";
                    candidate.Message = ex.Message;
                }
            }
        }

        private static void ValidateCleanLocalDeleteTarget(string path, string projectRoot, string toolDir)
        {
            string fullPath = Path.GetFullPath(path).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            string fullProjectRoot = Path.GetFullPath(projectRoot).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            string fullToolDir = Path.GetFullPath(toolDir).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            string root = Path.GetPathRoot(fullPath).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);

            if (string.IsNullOrWhiteSpace(fullPath) || EqualsIgnoreCase(fullPath, root))
            {
                throw new InvalidOperationException("Refusing to delete a drive/root path: " + fullPath);
            }

            if (EqualsIgnoreCase(fullPath, fullProjectRoot) || EqualsIgnoreCase(fullPath, fullToolDir))
            {
                throw new InvalidOperationException("Refusing to delete project/tool root: " + fullPath);
            }

            string binDir = Path.Combine(fullToolDir, "bin");
            string outDir = Path.Combine(fullToolDir, "out");
            bool allowed = EqualsIgnoreCase(fullPath, Path.GetFullPath(outDir).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar))
                || EqualsIgnoreCase(fullPath, Path.GetFullPath(binDir).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
            if (!allowed)
            {
                throw new InvalidOperationException("Path is not in the clean-local deletion allowlist: " + fullPath);
            }

            if (!IsPathUnder(fullPath, fullToolDir))
            {
                throw new InvalidOperationException("Path is outside " + ProductName + " tool directory: " + fullPath);
            }

            if (HasReparsePoint(fullPath))
            {
                throw new InvalidOperationException("Refusing to delete reparse point/symlink: " + fullPath);
            }
        }

        private static bool HasReparsePoint(string path)
        {
            if (File.Exists(path))
            {
                return (File.GetAttributes(path) & FileAttributes.ReparsePoint) != 0;
            }

            if (Directory.Exists(path))
            {
                Stack<DirectoryInfo> pending = new Stack<DirectoryInfo>();
                pending.Push(new DirectoryInfo(path));
                while (pending.Count > 0)
                {
                    DirectoryInfo directory = pending.Pop();
                    if ((directory.Attributes & FileAttributes.ReparsePoint) != 0)
                    {
                        return true;
                    }

                    foreach (FileSystemInfo entry in directory.GetFileSystemInfos())
                    {
                        if ((entry.Attributes & FileAttributes.ReparsePoint) != 0)
                        {
                            return true;
                        }
                        DirectoryInfo child = entry as DirectoryInfo;
                        if (child != null)
                        {
                            pending.Push(child);
                        }
                    }
                }
            }

            return false;
        }

        private static void RecreateCleanLocalReportDirectory(string reportDir, string toolDir)
        {
            string fullPath = Path.GetFullPath(reportDir);
            if (Directory.Exists(fullPath))
            {
                if (!IsPathUnder(fullPath, toolDir))
                {
                    throw new InvalidOperationException("Refusing to recreate clean-local report directory outside " + ProductName + ": " + fullPath);
                }

                Directory.Delete(fullPath, true);
            }

            Directory.CreateDirectory(fullPath);
        }

        private static void WriteCleanLocalReports(string reportDir, string projectRoot, string toolDir, string cloneDir, string scope, bool apply, List<CleanLocalCandidate> candidates, string phase)
        {
            string candidatesPath = Path.Combine(reportDir, phase == "pre-delete" ? "clean-local-predelete-candidates.csv" : "clean-local-candidates.csv");
            WriteCsv(candidatesPath,
                CleanLocalCandidateHeaders(),
                candidates.Select(CleanLocalCandidateRow));

            using (StreamWriter writer = NewUtf8Writer(Path.Combine(reportDir, phase == "pre-delete" ? "clean-local-predelete-summary.txt" : "clean-local-summary.txt")))
            {
                writer.WriteLine("Clean-local summary");
                writer.WriteLine("Generated: " + DateTime.Now.ToString("o"));
                writer.WriteLine("Phase: " + phase);
                writer.WriteLine("Scope: " + scope);
                writer.WriteLine("Apply: " + apply);
                writer.WriteLine("Project root: " + projectRoot);
                writer.WriteLine("Tool directory: " + toolDir);
                writer.WriteLine("Clone directory: " + cloneDir);
                writer.WriteLine("Candidates: " + candidates.Count);
                writer.WriteLine("Existing candidates: " + candidates.Count(x => x.Exists));
                writer.WriteLine("Delete planned: " + candidates.Count(x => EqualsIgnoreCase(x.Action, "delete")));
                writer.WriteLine("Deleted: " + candidates.Count(x => EqualsIgnoreCase(x.Status, "deleted")));
                writer.WriteLine("Failed: " + candidates.Count(x => EqualsIgnoreCase(x.Status, "failed")));
                writer.WriteLine("Total bytes in candidates: " + candidates.Sum(x => x.TotalBytes));
            }

            using (StreamWriter writer = NewUtf8Writer(Path.Combine(reportDir, phase == "pre-delete" ? "clean-local-predelete.json" : "clean-local.json")))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"generated\": " + Json(DateTime.Now.ToString("o")) + ",");
                writer.WriteLine("  \"phase\": " + Json(phase) + ",");
                writer.WriteLine("  \"scope\": " + Json(scope) + ",");
                writer.WriteLine("  \"apply\": " + Json(apply.ToString()) + ",");
                writer.WriteLine("  \"projectRoot\": " + Json(projectRoot) + ",");
                writer.WriteLine("  \"toolDir\": " + Json(toolDir) + ",");
                writer.WriteLine("  \"cloneDir\": " + Json(cloneDir) + ",");
                WriteJsonArray(writer, "candidates", candidates.Select(CleanLocalCandidateJsonRow), false);
                writer.WriteLine("}");
            }
        }

        private static string[] CleanLocalCandidateHeaders()
        {
            return new[] { "Scope", "Category", "Action", "Path", "RelativePath", "Exists", "FileCount", "TotalBytes", "Reason", "Safety", "Status", "Message" };
        }

        private static string[] CleanLocalCandidateRow(CleanLocalCandidate candidate)
        {
            return new[]
            {
                candidate.Scope,
                candidate.Category,
                candidate.Action,
                candidate.Path,
                candidate.RelativePath,
                candidate.Exists.ToString(),
                candidate.FileCount.ToString(CultureInfo.InvariantCulture),
                candidate.TotalBytes.ToString(CultureInfo.InvariantCulture),
                candidate.Reason,
                candidate.Safety,
                candidate.Status,
                candidate.Message
            };
        }

        private static Dictionary<string, string> CleanLocalCandidateJsonRow(CleanLocalCandidate candidate)
        {
            return new Dictionary<string, string>
            {
                { "scope", candidate.Scope },
                { "category", candidate.Category },
                { "action", candidate.Action },
                { "path", candidate.Path },
                { "relativePath", candidate.RelativePath },
                { "exists", candidate.Exists.ToString() },
                { "fileCount", candidate.FileCount.ToString(CultureInfo.InvariantCulture) },
                { "totalBytes", candidate.TotalBytes.ToString(CultureInfo.InvariantCulture) },
                { "reason", candidate.Reason },
                { "safety", candidate.Safety },
                { "status", candidate.Status },
                { "message", candidate.Message }
            };
        }

        private static string MakeRelativePathOrAbsolute(string root, string path)
        {
            return IsPathUnder(path, root) ? MakeRelativePath(root, path) : path;
        }

        private static bool IsPathUnder(string path, string root)
        {
            string fullPath = Path.GetFullPath(path).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            string fullRoot = Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            return EqualsIgnoreCase(fullPath, fullRoot) || fullPath.StartsWith(fullRoot + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) || fullPath.StartsWith(fullRoot + Path.AltDirectorySeparatorChar, StringComparison.OrdinalIgnoreCase);
        }

        private static ProjectResolution ResolveProject(string explicitPath)
        {
            if (!string.IsNullOrWhiteSpace(explicitPath))
            {
                string fullPath = Path.GetFullPath(explicitPath);
                if (!IsTiaProjectFileName(fullPath))
                {
                    throw new InvalidOperationException("Explicit --project does not look like a TIA Portal project file (*.apNN): " + fullPath);
                }

                if (!File.Exists(fullPath))
                {
                    throw new FileNotFoundException("Project file was not found. Pass --project <path-to-project.apNN> or run from the project folder.", fullPath);
                }

                return CreateProjectResolution(fullPath, "explicit", Path.GetDirectoryName(fullPath), new[] { fullPath });
            }

            List<string> checkedDirectories = new List<string>();
            string current = Path.GetFullPath(Environment.CurrentDirectory);
            checkedDirectories.Add(current);
            string[] currentProjects = FindProjectFiles(current);
            if (currentProjects.Length == 1)
            {
                return CreateProjectResolution(currentProjects[0], "current-directory", current, currentProjects);
            }

            if (currentProjects.Length > 1)
            {
                throw new InvalidOperationException(BuildMultipleProjectFilesMessage(current, currentProjects));
            }

            DirectoryInfo currentInfo = new DirectoryInfo(current);
            if (IsToolDirectoryName(currentInfo.Name))
            {
                DirectoryInfo parentInfo = currentInfo.Parent;
                if (parentInfo != null)
                {
                    string parent = parentInfo.FullName;
                    checkedDirectories.Add(parent);
                    string[] parentProjects = FindProjectFiles(parent);
                    if (parentProjects.Length == 1)
                    {
                        return CreateProjectResolution(parentProjects[0], "parent-project-directory", parent, parentProjects);
                    }

                    if (parentProjects.Length > 1)
                    {
                        throw new InvalidOperationException(BuildMultipleProjectFilesMessage(parent, parentProjects));
                    }
                }
            }

            throw new InvalidOperationException(BuildNoProjectFileMessage(checkedDirectories));
        }

        private static ProjectResolution CreateProjectResolution(string projectPath, string source, string searchDirectory, IEnumerable<string> candidates)
        {
            ProjectResolution resolution = new ProjectResolution();
            resolution.Path = Path.GetFullPath(projectPath);
            resolution.Source = source;
            resolution.SearchDirectory = searchDirectory;
            resolution.ProjectVersionMajor = GetProjectVersionMajor(projectPath);
            if (candidates != null)
            {
                resolution.Candidates.AddRange(candidates.Select(Path.GetFullPath));
            }

            return resolution;
        }

        private static string[] FindProjectFiles(string directory)
        {
            if (string.IsNullOrWhiteSpace(directory) || !Directory.Exists(directory))
            {
                return new string[0];
            }

            return Directory.GetFiles(directory, "*.ap*", SearchOption.TopDirectoryOnly)
                .Where(IsTiaProjectFileName)
                .OrderBy(x => x)
                .ToArray();
        }

        private static bool IsTiaProjectFileName(string path)
        {
            string extension = Path.GetExtension(path);
            return !string.IsNullOrWhiteSpace(extension)
                && Regex.IsMatch(extension, @"^\.ap\d+$", RegexOptions.IgnoreCase);
        }

        private static int GetProjectVersionMajor(string projectPath)
        {
            string extension = Path.GetExtension(projectPath);
            if (string.IsNullOrWhiteSpace(extension))
            {
                return 0;
            }

            Match match = Regex.Match(extension, @"^\.ap(?<major>\d+)$", RegexOptions.IgnoreCase);
            int major;
            return match.Success && int.TryParse(match.Groups["major"].Value, out major) ? major : 0;
        }

        private static string BuildMultipleProjectFilesMessage(string directory, IEnumerable<string> candidates)
        {
            StringBuilder builder = new StringBuilder();
            builder.AppendLine("Several TIA Portal project files (*.apNN) were found.");
            builder.AppendLine("Directory: " + directory);
            builder.AppendLine("Candidates:");
            foreach (string candidate in candidates)
            {
                builder.AppendLine("  " + candidate);
            }

            builder.Append("Pass --project <path> to choose one explicitly.");
            return builder.ToString();
        }

        private static string BuildNoProjectFileMessage(IEnumerable<string> checkedDirectories)
        {
            StringBuilder builder = new StringBuilder();
            builder.AppendLine("No TIA Portal project file (*.apNN) was found.");
            builder.AppendLine("Current directory: " + Environment.CurrentDirectory);
            builder.AppendLine("Checked directories:");
            foreach (string directory in checkedDirectories)
            {
                builder.AppendLine("  " + directory);
            }

            builder.Append("Pass --project <path-to-project.apNN> or run from the project folder.");
            return builder.ToString();
        }

        private static ApiResolution ResolveApiDirectory(string explicitApiDir, int projectVersionMajor)
        {
            if (!string.IsNullOrWhiteSpace(explicitApiDir))
            {
                ApiResolution explicitResolution = CreateApiResolutionFromDirectory(Path.GetFullPath(explicitApiDir), "explicit");
                if (explicitResolution == null)
                {
                    throw new InvalidOperationException("Explicit --api-dir does not contain Siemens.Engineering.Base.dll or Siemens.Engineering.dll: " + Path.GetFullPath(explicitApiDir));
                }

                ValidateApiProjectVersion(explicitResolution, projectVersionMajor);
                return explicitResolution;
            }

            string envDir = Environment.GetEnvironmentVariable("TIA_OPENNESS_API_DIR");
            if (!string.IsNullOrWhiteSpace(envDir))
            {
                ApiResolution envResolution = CreateApiResolutionFromDirectory(Path.GetFullPath(envDir), "environment");
                if (envResolution == null)
                {
                    throw new InvalidOperationException("TIA_OPENNESS_API_DIR does not contain Siemens.Engineering.Base.dll or Siemens.Engineering.dll: " + Path.GetFullPath(envDir));
                }

                ValidateApiProjectVersion(envResolution, projectVersionMajor);
                return envResolution;
            }

            if (projectVersionMajor > 0)
            {
                ApiResolution registryResolution = FindApiInRegistry(projectVersionMajor, "registry-project-version");
                if (registryResolution != null)
                {
                    ValidateApiProjectVersion(registryResolution, projectVersionMajor);
                    return registryResolution;
                }

                ApiResolution defaultResolution = FindDefaultApiDirectory(projectVersionMajor);
                if (defaultResolution != null)
                {
                    ValidateApiProjectVersion(defaultResolution, projectVersionMajor);
                    return defaultResolution;
                }

                throw new InvalidOperationException("TIA Portal Openness V" + projectVersionMajor + " PublicAPI directory was not found. Use --api-dir <PublicAPI\\V" + projectVersionMajor + "\\net48> or <PublicAPI\\V" + projectVersionMajor + "> or set TIA_OPENNESS_API_DIR.");
            }

            ApiResolution latestResolution = FindLatestApiInRegistry();
            if (latestResolution != null)
            {
                return latestResolution;
            }

            throw new InvalidOperationException("TIA Portal Openness PublicAPI directory was not found. Use --api-dir or set TIA_OPENNESS_API_DIR.");
        }

        private static ApiResolution FindApiInRegistry(int major, string source)
        {
            using (RegistryKey root = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Siemens\Automation\Openness\" + major.ToString(CultureInfo.InvariantCulture) + @".0\PublicAPI"))
            {
                if (root == null)
                {
                    return null;
                }

                foreach (string versionName in root.GetSubKeyNames().OrderByDescending(x => x))
                {
                    using (RegistryKey net48 = root.OpenSubKey(versionName + @"\net48"))
                    {
                        ApiResolution resolution = CreateApiResolutionFromRegistryKey(net48, source, major);
                        if (resolution != null)
                        {
                            return resolution;
                        }
                    }
                }
            }

            return null;
        }

        private static ApiResolution FindLatestApiInRegistry()
        {
            using (RegistryKey root = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Siemens\Automation\Openness"))
            {
                if (root == null)
                {
                    return null;
                }

                foreach (string majorName in root.GetSubKeyNames().OrderByDescending(x => x))
                {
                    Match match = Regex.Match(majorName, @"^(?<major>\d+)\.0$");
                    int major;
                    if (!match.Success || !int.TryParse(match.Groups["major"].Value, out major))
                    {
                        continue;
                    }

                    ApiResolution resolution = FindApiInRegistry(major, "registry-latest");
                    if (resolution != null)
                    {
                        return resolution;
                    }
                }
            }

            return null;
        }

        private static ApiResolution CreateApiResolutionFromRegistryKey(RegistryKey key, string source, int major)
        {
            if (key == null)
            {
                return null;
            }

            object value = key.GetValue("Siemens.Engineering.Base");
            string basePath = value as string;
            if (string.IsNullOrWhiteSpace(basePath) || !File.Exists(basePath))
            {
                return null;
            }

            ApiResolution resolution = CreateApiResolutionFromDirectory(Path.GetDirectoryName(basePath), source);
            if (resolution != null && resolution.VersionMajor == 0)
            {
                resolution.VersionMajor = major;
            }

            return resolution;
        }

        private static ApiResolution FindDefaultApiDirectory(int major)
        {
            string defaultDir = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),
                "Siemens",
                "Automation",
                "Portal V" + major.ToString(CultureInfo.InvariantCulture),
                "PublicAPI",
                "V" + major.ToString(CultureInfo.InvariantCulture),
                "net48");
            ApiResolution resolution = CreateApiResolutionFromDirectory(defaultDir, "default-project-version");
            if (resolution != null && resolution.VersionMajor == 0)
            {
                resolution.VersionMajor = major;
            }

            if (resolution != null)
            {
                return resolution;
            }

            string legacyDefaultDir = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),
                "Siemens",
                "Automation",
                "Portal V" + major.ToString(CultureInfo.InvariantCulture),
                "PublicAPI",
                "V" + major.ToString(CultureInfo.InvariantCulture));
            resolution = CreateApiResolutionFromDirectory(legacyDefaultDir, "default-project-version-legacy");
            if (resolution != null && resolution.VersionMajor == 0)
            {
                resolution.VersionMajor = major;
            }

            return resolution;
        }

        private static ApiResolution CreateApiResolutionFromDirectory(string directory, string source)
        {
            if (!HasEngineeringApiAssembly(directory))
            {
                return null;
            }

            string fullDirectory = Path.GetFullPath(directory);
            string baseAssemblyPath = GetPrimaryEngineeringAssemblyPath(fullDirectory);
            ApiResolution resolution = new ApiResolution();
            resolution.Directory = fullDirectory;
            resolution.Source = source;
            resolution.BaseAssemblyPath = baseAssemblyPath;
            resolution.VersionMajor = GetApiVersionMajor(fullDirectory, baseAssemblyPath);
            resolution.AssemblyVersion = GetAssemblyVersion(baseAssemblyPath);
            return resolution;
        }

        private static int GetApiVersionMajor(string directory, string baseAssemblyPath)
        {
            Match pathMatch = Regex.Match(directory, @"(?:Portal V|PublicAPI[\\/]+V)(?<major>\d+)", RegexOptions.IgnoreCase);
            int major;
            if (pathMatch.Success && int.TryParse(pathMatch.Groups["major"].Value, out major))
            {
                return major;
            }

            try
            {
                Version version = AssemblyName.GetAssemblyName(baseAssemblyPath).Version;
                return version == null ? 0 : version.Major;
            }
            catch
            {
                return 0;
            }
        }

        private static string GetAssemblyVersion(string assemblyPath)
        {
            try
            {
                Version version = AssemblyName.GetAssemblyName(assemblyPath).Version;
                return version == null ? string.Empty : version.ToString();
            }
            catch
            {
                return string.Empty;
            }
        }

        private static void ValidateApiProjectVersion(ApiResolution resolution, int projectVersionMajor)
        {
            if (resolution == null || projectVersionMajor <= 0 || resolution.VersionMajor <= 0)
            {
                return;
            }

            if (resolution.VersionMajor != projectVersionMajor)
            {
                throw new InvalidOperationException("TIA Openness API version V" + resolution.VersionMajor + " does not match project version V" + projectVersionMajor + ". Use a matching --api-dir.");
            }
        }

        private static string FormatProjectVersion(int major)
        {
            return major > 0 ? "V" + major.ToString(CultureInfo.InvariantCulture) : "unknown";
        }

        private static bool HasEngineeringApiAssembly(string directory)
        {
            return !string.IsNullOrWhiteSpace(directory)
                && !string.IsNullOrWhiteSpace(GetPrimaryEngineeringAssemblyPath(directory));
        }

        private static string GetPrimaryEngineeringAssemblyPath(string directory)
        {
            if (string.IsNullOrWhiteSpace(directory))
            {
                return null;
            }

            string baseAssembly = Path.Combine(directory, "Siemens.Engineering.Base.dll");
            if (File.Exists(baseAssembly))
            {
                return baseAssembly;
            }

            string legacyAssembly = Path.Combine(directory, "Siemens.Engineering.dll");
            return File.Exists(legacyAssembly) ? legacyAssembly : null;
        }

        private static void ConfigureAssemblyLoading(string apiDir)
        {
            AppDomain.CurrentDomain.AssemblyResolve += delegate(object sender, ResolveEventArgs args)
            {
                string name = new AssemblyName(args.Name).Name + ".dll";
                string candidate = Path.Combine(apiDir, name);
                return File.Exists(candidate) ? Assembly.LoadFrom(candidate) : null;
            };
        }

        private static void LoadSiemensAssemblies(string apiDir)
        {
            foreach (string dll in Directory.GetFiles(apiDir, "Siemens.Engineering*.dll").OrderBy(x => x))
            {
                Assembly.LoadFrom(dll);
            }
        }

        private static object StartTiaPortal(bool headless)
        {
            Type portalType = FindType("Siemens.Engineering.TiaPortal");
            Type modeType = FindType("Siemens.Engineering.TiaPortalMode");
            object mode = Enum.Parse(modeType, headless ? "WithoutUserInterface" : "WithUserInterface");

            Console.WriteLine("Starting TIA Portal (" + mode + ")...");
            return Activator.CreateInstance(portalType, new object[] { mode });
        }

        private static object AttachToTiaPortal(Options options)
        {
            Type processType = FindType("Siemens.Engineering.TiaPortalProcess");
            Type portalType = FindType("Siemens.Engineering.TiaPortal");
            MethodInfo getProcesses = processType.GetMethod("GetProcesses", BindingFlags.Public | BindingFlags.Static)
                ?? portalType.GetMethod("GetProcesses", BindingFlags.Public | BindingFlags.Static);
            if (getProcesses == null)
            {
                throw new MissingMethodException(processType.FullName + " or " + portalType.FullName, "GetProcesses");
            }

            List<object> processList = AsEnumerable(getProcesses.Invoke(null, null)).ToList();
            object process = null;
            if (processList.Count > 0)
            {
                int index = options.AttachIndex >= 0 ? options.AttachIndex : 0;
                if (index >= processList.Count)
                {
                    throw new InvalidOperationException("Attach index " + index + " is out of range. Running TIA processes: " + processList.Count);
                }

                Console.WriteLine("Running TIA Portal processes found: " + processList.Count);
                for (int i = 0; i < processList.Count; i++)
                {
                    Console.WriteLine("  [" + i + "] " + SafeDescribe(processList[i]) + Details(processList[i], new[] { "Id", "ProcessId", "Mode" }));
                }

                process = processList[index];
            }

            if (process == null)
            {
                throw new InvalidOperationException("No running TIA Portal process was found. Start TIA Portal or run without --attach.");
            }

            Console.WriteLine("Attaching to TIA Portal process: " + SafeDescribe(process));
            MethodInfo attach = process.GetType().GetMethod("Attach", BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
            if (attach == null)
            {
                throw new MissingMethodException(process.GetType().FullName, "Attach");
            }

            return attach.Invoke(process, null);
        }

        private static object OpenProject(object tiaPortal, string projectPath, bool attached)
        {
            object projects = GetPropertyValue(tiaPortal, "Projects");
            object existingProject = FindOpenProject(projects, projectPath);
            if (existingProject != null)
            {
                _ownsProject = false;
                Console.WriteLine("Using already open project: " + SafeGet(existingProject, "Name"));
                return existingProject;
            }

            if (attached)
            {
                throw new InvalidOperationException(BuildAttachedProjectMismatchMessage(projects, projectPath));
            }

            MethodInfo open = FindInstanceMethod(projects.GetType(), "Open", 1);
            if (open == null)
            {
                throw new MissingMethodException(projects.GetType().FullName, "Open");
            }

            Console.WriteLine("Opening project...");
            _ownsProject = true;
            return open.Invoke(projects, new object[] { new FileInfo(projectPath) });
        }

        private static object FindOpenProject(object projects, string projectPath)
        {
            List<object> openProjects = AsEnumerable(projects).ToList();
            if (openProjects.Count == 0)
            {
                return null;
            }

            List<object> pathMatches = new List<object>();
            foreach (object project in openProjects)
            {
                if (OpenProjectPathMatches(project, projectPath))
                {
                    pathMatches.Add(project);
                }
            }

            if (pathMatches.Count == 1)
            {
                return pathMatches[0];
            }

            if (pathMatches.Count > 1)
            {
                throw new InvalidOperationException("Several open TIA projects match selected project path: " + projectPath);
            }

            string expectedName = Path.GetFileNameWithoutExtension(projectPath);
            List<object> nameMatches = new List<object>();
            foreach (object project in openProjects)
            {
                string name = SafeGet(project, "Name");
                if (EqualsIgnoreCase(name, expectedName))
                {
                    nameMatches.Add(project);
                }
            }

            if (nameMatches.Count == 1 && !OpenProjectHasUsablePath(nameMatches[0]))
            {
                return nameMatches[0];
            }

            return null;
        }

        private static bool OpenProjectPathMatches(object project, string projectPath)
        {
            foreach (string candidate in GetOpenProjectPathCandidates(project))
            {
                if (ProjectPathMatchesCandidate(candidate, projectPath))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool OpenProjectHasUsablePath(object project)
        {
            return GetOpenProjectPathCandidates(project).Any(x => !string.IsNullOrWhiteSpace(x));
        }

        private static List<string> GetOpenProjectPathCandidates(object project)
        {
            List<string> candidates = new List<string>();

            object projectFile = TryGetPropertyValue(project, "ProjectFile");
            if (projectFile != null)
            {
                FileInfo fileInfo = projectFile as FileInfo;
                if (fileInfo != null)
                {
                    candidates.Add(fileInfo.FullName);
                }

                AddStringIfNotEmpty(candidates, SafeGet(projectFile, "FullName"));
                AddStringIfNotEmpty(candidates, Convert.ToString(projectFile));
            }

            AddStringIfNotEmpty(candidates, SafeGet(project, "Path"));
            return candidates.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
        }

        private static void AddStringIfNotEmpty(List<string> values, string value)
        {
            if (!string.IsNullOrWhiteSpace(value))
            {
                values.Add(value);
            }
        }

        private static bool ProjectPathMatchesCandidate(string candidate, string projectPath)
        {
            string normalizedCandidate = NormalizeComparablePath(candidate);
            string normalizedProject = NormalizeComparablePath(projectPath);
            if (string.IsNullOrEmpty(normalizedCandidate) || string.IsNullOrEmpty(normalizedProject))
            {
                return false;
            }

            if (EqualsIgnoreCase(normalizedCandidate, normalizedProject))
            {
                return true;
            }

            string projectDirectory = NormalizeComparablePath(Path.GetDirectoryName(projectPath));
            if (string.IsNullOrEmpty(projectDirectory))
            {
                return false;
            }

            if (EqualsIgnoreCase(normalizedCandidate, projectDirectory))
            {
                return true;
            }

            if (!IsTiaProjectFileName(candidate) && EqualsIgnoreCase(normalizedCandidate, projectDirectory))
            {
                return true;
            }

            return false;
        }

        private static string NormalizeComparablePath(string path)
        {
            if (string.IsNullOrWhiteSpace(path))
            {
                return string.Empty;
            }

            try
            {
                return Path.GetFullPath(path).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            }
            catch
            {
                return path.Trim().TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            }
        }

        private static string BuildAttachedProjectMismatchMessage(object projects, string projectPath)
        {
            StringBuilder builder = new StringBuilder();
            builder.AppendLine("Attached TIA Portal does not have the selected project open.");
            builder.AppendLine("Selected project: " + projectPath);
            builder.AppendLine("Open projects:");

            List<object> openProjects = AsEnumerable(projects).ToList();
            if (openProjects.Count == 0)
            {
                builder.AppendLine("  none");
            }
            else
            {
                for (int i = 0; i < openProjects.Count; i++)
                {
                    builder.AppendLine("  [" + i.ToString(CultureInfo.InvariantCulture) + "] " + DescribeOpenProject(openProjects[i]));
                }
            }

            builder.Append("Open the selected project in TIA Portal, choose another --attach-index, or pass the correct --project.");
            return builder.ToString();
        }

        private static string DescribeOpenProject(object project)
        {
            string name = SafeGet(project, "Name");
            List<string> paths = GetOpenProjectPathCandidates(project);
            return paths.Count == 0
                ? name
                : name + " - " + string.Join("; ", paths.ToArray());
        }

        private static void PrintProject(object project, int maxItems)
        {
            _printedItems = 0;
            Console.WriteLine();
            Console.WriteLine("Opened project");
            Console.WriteLine("  Name: " + SafeGet(project, "Name"));
            Console.WriteLine("  Type: " + project.GetType().FullName);
            Console.WriteLine();

            Console.WriteLine("Devices");
            object devices = TryGetPropertyValue(project, "Devices");
            if (devices != null)
            {
                foreach (object device in AsEnumerable(devices))
                {
                    if (!CanPrintMore(maxItems))
                    {
                        break;
                    }

                    PrintDevice(device, "  ", maxItems);
                }
            }

            object deviceGroups = TryGetPropertyValue(project, "DeviceGroups");
            if (deviceGroups != null)
            {
                Console.WriteLine("Device groups");
                PrintDeviceGroups(deviceGroups, "  ", maxItems);
            }

            if (_printedItems >= maxItems)
            {
                Console.WriteLine("Output limit reached. Increase it with --max <n>.");
            }
        }

        private static void PrintDeviceGroups(object deviceGroups, string indent, int maxItems)
        {
            if (deviceGroups == null)
            {
                return;
            }

            foreach (object group in AsEnumerable(deviceGroups))
            {
                if (!CanPrintMore(maxItems))
                {
                    return;
                }

                PrintLine(indent + "- Device group: " + Label(group), maxItems);

                object devices = TryGetPropertyValue(group, "Devices");
                if (devices != null)
                {
                    foreach (object device in AsEnumerable(devices))
                    {
                        if (!CanPrintMore(maxItems))
                        {
                            return;
                        }

                        PrintDevice(device, indent + "  ", maxItems);
                    }
                }

                object childGroups = TryGetPropertyValue(group, "Groups");
                if (childGroups == null)
                {
                    childGroups = TryGetPropertyValue(group, "DeviceGroups");
                }

                PrintDeviceGroups(childGroups, indent + "  ", maxItems);
            }
        }

        private static void PrintDevice(object device, string indent, int maxItems)
        {
            PrintLine(indent + "- Device: " + Label(device), maxItems);
            PrintDeviceItems(TryGetPropertyValue(device, "DeviceItems"), indent + "  ", maxItems);
        }

        private static void PrintDeviceItems(object deviceItems, string indent, int maxItems)
        {
            if (deviceItems == null)
            {
                return;
            }

            foreach (object item in AsEnumerable(deviceItems))
            {
                if (!CanPrintMore(maxItems))
                {
                    return;
                }

                PrintLine(indent + "- Item: " + Label(item), maxItems);
                PrintSoftware(item, indent + "  ", maxItems);
                PrintDeviceItems(TryGetPropertyValue(item, "DeviceItems"), indent + "  ", maxItems);
            }
        }

        private static void PrintSoftware(object deviceItem, string indent, int maxItems)
        {
            object software = TryGetSoftware(deviceItem);
            if (software == null)
            {
                return;
            }

            PrintLine(indent + "Software: " + Label(software) + " [" + software.GetType().FullName + "]", maxItems);

            object blockGroup = TryGetPropertyValue(software, "BlockGroup");
            if (blockGroup != null)
            {
                PrintLine(indent + "Blocks:", maxItems);
                PrintBlockGroup(blockGroup, indent + "  ", maxItems);
            }

            object tagTableGroup = TryGetPropertyValue(software, "TagTableGroup");
            if (tagTableGroup != null)
            {
                PrintLine(indent + "Tag tables:", maxItems);
                PrintTagTableGroup(tagTableGroup, indent + "  ", maxItems);
            }
        }

        private static void PrintBlockGroup(object group, string indent, int maxItems)
        {
            object blocks = TryGetPropertyValue(group, "Blocks");
            if (blocks != null)
            {
                foreach (object block in AsEnumerable(blocks))
                {
                    if (!CanPrintMore(maxItems))
                    {
                        return;
                    }

                    PrintLine(indent + "- Block: " + Label(block) + Details(block, new[] { "Number", "ProgrammingLanguage", "BlockType" }), maxItems);
                }
            }

            object groups = TryGetPropertyValue(group, "Groups");
            if (groups != null)
            {
                foreach (object child in AsEnumerable(groups))
                {
                    if (!CanPrintMore(maxItems))
                    {
                        return;
                    }

                    PrintLine(indent + "- Group: " + Label(child), maxItems);
                    PrintBlockGroup(child, indent + "  ", maxItems);
                }
            }
        }

        private static void PrintTagTableGroup(object group, string indent, int maxItems)
        {
            object tables = TryGetPropertyValue(group, "TagTables");
            if (tables != null)
            {
                foreach (object table in AsEnumerable(tables))
                {
                    if (!CanPrintMore(maxItems))
                    {
                        return;
                    }

                    PrintLine(indent + "- Tag table: " + Label(table), maxItems);
                    object tags = TryGetPropertyValue(table, "Tags");
                    if (tags == null)
                    {
                        continue;
                    }

                    foreach (object tag in AsEnumerable(tags))
                    {
                        if (!CanPrintMore(maxItems))
                        {
                            return;
                        }

                        PrintLine(indent + "  - Tag: " + Label(tag) + Details(tag, new[] { "DataTypeName", "LogicalAddress" }), maxItems);
                    }
                }
            }

            object groups = TryGetPropertyValue(group, "Groups");
            if (groups != null)
            {
                foreach (object child in AsEnumerable(groups))
                {
                    if (!CanPrintMore(maxItems))
                    {
                        return;
                    }

                    PrintLine(indent + "- Group: " + Label(child), maxItems);
                    PrintTagTableGroup(child, indent + "  ", maxItems);
                }
            }
        }

        private static InventorySnapshot CollectInventory(object project, string projectPath)
        {
            InventorySnapshot snapshot = new InventorySnapshot();
            snapshot.ProjectPath = NormalizeComparablePath(projectPath);
            snapshot.ProjectName = SafeGet(project, "Name");
            snapshot.ProjectType = project.GetType().FullName;
            snapshot.ProjectVersion = GetProjectVersionMajor(projectPath).ToString(CultureInfo.InvariantCulture);
            snapshot.CreatedAt = DateTime.Now;
            snapshot.ObjectIdentifierProvider = TryGetObjectIdentifierProvider(project);
            TryReadTiaObjectId(snapshot.ObjectIdentifierProvider, project, out snapshot.ProjectObjectId, out snapshot.ProjectObjectIdStatus);

            object devices = TryGetPropertyValue(project, "Devices");
            if (devices != null)
            {
                foreach (object device in AsEnumerable(devices))
                {
                    string deviceName = SafeName(device);
                    string devicePath = CombinePath(null, deviceName);
                    AddDeviceRecord(snapshot, "Device", device, devicePath, null);
                    CollectDeviceItems(snapshot, TryGetPropertyValue(device, "DeviceItems"), devicePath);
                }
            }

            CollectDeviceGroups(snapshot, TryGetPropertyValue(project, "DeviceGroups"), null);

            return snapshot;
        }

        private static InventorySnapshot FilterInventoryBySoftwarePath(InventorySnapshot source, string softwarePathFilter)
        {
            if (string.IsNullOrWhiteSpace(softwarePathFilter))
            {
                return source;
            }

            InventorySnapshot snapshot = new InventorySnapshot();
            snapshot.ProjectPath = source.ProjectPath;
            snapshot.ProjectName = source.ProjectName;
            snapshot.ProjectType = source.ProjectType;
            snapshot.ProjectVersion = source.ProjectVersion;
            snapshot.ProjectObjectId = source.ProjectObjectId;
            snapshot.ProjectObjectIdStatus = source.ProjectObjectIdStatus;
            snapshot.CreatedAt = source.CreatedAt;
            snapshot.ObjectIdentifierProvider = source.ObjectIdentifierProvider;

            snapshot.Devices.AddRange(source.Devices.Where(x => LogicalPathIsRelatedToFilter(x.Path, softwarePathFilter)));
            snapshot.BlockGroups.AddRange(source.BlockGroups.Where(x => LogicalPathMatchesFilter(x.SoftwarePath, softwarePathFilter)));
            snapshot.Blocks.AddRange(source.Blocks.Where(x => LogicalPathMatchesFilter(x.SoftwarePath, softwarePathFilter)));
            snapshot.TagTables.AddRange(source.TagTables.Where(x => LogicalPathMatchesFilter(x.SoftwarePath, softwarePathFilter)));
            snapshot.Tags.AddRange(source.Tags.Where(x => LogicalPathMatchesFilter(x.SoftwarePath, softwarePathFilter)));

            return snapshot;
        }

        private static HmiInventorySnapshot FilterHmiInventoryByTargetPath(HmiInventorySnapshot source, string hmiTargetPathFilter)
        {
            if (string.IsNullOrWhiteSpace(hmiTargetPathFilter))
            {
                return source;
            }

            HmiInventorySnapshot snapshot = new HmiInventorySnapshot();
            snapshot.ProjectName = source.ProjectName;
            snapshot.ProjectPath = source.ProjectPath;
            snapshot.ProjectType = source.ProjectType;
            snapshot.CreatedAt = source.CreatedAt;

            snapshot.Targets.AddRange(source.Targets.Where(x => LogicalPathMatchesFilter(x.TargetPath, hmiTargetPathFilter)));

            HashSet<string> includedTargets = new HashSet<string>(snapshot.Targets.Select(x => x.TargetPath), StringComparer.OrdinalIgnoreCase);
            snapshot.Screens.AddRange(source.Screens.Where(x => HmiTargetIncluded(includedTargets, x.TargetPath, hmiTargetPathFilter)));
            snapshot.TagTables.AddRange(source.TagTables.Where(x => HmiTargetIncluded(includedTargets, x.TargetPath, hmiTargetPathFilter)));
            snapshot.Tags.AddRange(source.Tags.Where(x => HmiTargetIncluded(includedTargets, x.TargetPath, hmiTargetPathFilter)));
            snapshot.TextLists.AddRange(source.TextLists.Where(x => HmiTargetIncluded(includedTargets, x.TargetPath, hmiTargetPathFilter)));
            snapshot.GraphicLists.AddRange(source.GraphicLists.Where(x => HmiTargetIncluded(includedTargets, x.TargetPath, hmiTargetPathFilter)));
            snapshot.Cycles.AddRange(source.Cycles.Where(x => HmiTargetIncluded(includedTargets, x.TargetPath, hmiTargetPathFilter)));
            snapshot.Scripts.AddRange(source.Scripts.Where(x => HmiTargetIncluded(includedTargets, x.TargetPath, hmiTargetPathFilter)));
            snapshot.Connections.AddRange(source.Connections.Where(x => HmiTargetIncluded(includedTargets, x.TargetPath, hmiTargetPathFilter)));

            return snapshot;
        }

        private static bool HmiTargetIncluded(HashSet<string> includedTargets, string targetPath, string hmiTargetPathFilter)
        {
            return includedTargets.Contains(targetPath) || LogicalPathMatchesFilter(targetPath, hmiTargetPathFilter);
        }

        private static bool LogicalPathMatchesFilter(string path, string filter)
        {
            string normalizedPath = NormalizeLogicalFilterPath(path);
            string normalizedFilter = NormalizeLogicalFilterPath(filter);
            if (string.IsNullOrWhiteSpace(normalizedFilter))
            {
                return true;
            }

            return EqualsIgnoreCase(normalizedPath, normalizedFilter)
                || normalizedPath.IndexOf(normalizedFilter, StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static bool LogicalPathIsRelatedToFilter(string path, string filter)
        {
            string normalizedPath = NormalizeLogicalFilterPath(path);
            string normalizedFilter = NormalizeLogicalFilterPath(filter);
            if (string.IsNullOrWhiteSpace(normalizedFilter))
            {
                return true;
            }

            return EqualsIgnoreCase(normalizedPath, normalizedFilter)
                || normalizedPath.StartsWith(normalizedFilter + "/", StringComparison.OrdinalIgnoreCase)
                || normalizedFilter.StartsWith(normalizedPath + "/", StringComparison.OrdinalIgnoreCase)
                || normalizedPath.IndexOf(normalizedFilter, StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static string NormalizeLogicalFilterPath(string value)
        {
            return (value ?? string.Empty).Replace('\\', '/').Trim().Trim('/');
        }

        private static void CollectDeviceGroups(InventorySnapshot snapshot, object deviceGroups, string parentPath)
        {
            if (deviceGroups == null)
            {
                return;
            }

            foreach (object group in AsEnumerable(deviceGroups))
            {
                string groupName = SafeName(group);
                string groupPath = CombinePath(parentPath, groupName);
                AddDeviceRecord(snapshot, "DeviceGroup", group, groupPath, null);

                object devices = TryGetPropertyValue(group, "Devices");
                if (devices != null)
                {
                    foreach (object device in AsEnumerable(devices))
                    {
                        string deviceName = SafeName(device);
                        string devicePath = CombinePath(groupPath, deviceName);
                        AddDeviceRecord(snapshot, "Device", device, devicePath, null);
                        CollectDeviceItems(snapshot, TryGetPropertyValue(device, "DeviceItems"), devicePath);
                    }
                }

                object childGroups = TryGetPropertyValue(group, "Groups");
                if (childGroups == null)
                {
                    childGroups = TryGetPropertyValue(group, "DeviceGroups");
                }

                CollectDeviceGroups(snapshot, childGroups, groupPath);
            }
        }

        private static void CollectDeviceItems(InventorySnapshot snapshot, object deviceItems, string parentPath)
        {
            if (deviceItems == null)
            {
                return;
            }

            foreach (object item in AsEnumerable(deviceItems))
            {
                string itemName = SafeName(item);
                string itemPath = CombinePath(parentPath, itemName);
                object software = TryGetSoftware(item);
                string softwareType = software == null ? null : software.GetType().FullName;
                AddDeviceRecord(snapshot, "DeviceItem", item, itemPath, softwareType);

                if (software != null)
                {
                    string softwarePath = CombinePath(itemPath, SafeName(software));
                    snapshot.Devices.Add(new DeviceRecord
                    {
                        Kind = "Software",
                        Path = softwarePath,
                        Name = SafeName(software),
                        TypeIdentifier = SafeGet(software, "TypeIdentifier"),
                        OrderNumber = SafeGet(software, "OrderNumber"),
                        SoftwareType = software.GetType().FullName,
                        Object = software
                    });

                    CollectSoftware(snapshot, software, softwarePath);
                }

                CollectDeviceItems(snapshot, TryGetPropertyValue(item, "DeviceItems"), itemPath);
            }
        }

        private static void AddDeviceRecord(InventorySnapshot snapshot, string kind, object value, string path, string softwareType)
        {
            snapshot.Devices.Add(new DeviceRecord
            {
                Kind = kind,
                Path = path,
                Name = SafeName(value),
                TypeIdentifier = SafeGet(value, "TypeIdentifier"),
                OrderNumber = SafeGet(value, "OrderNumber"),
                SoftwareType = softwareType,
                Object = value
            });
        }

        private static void CollectSoftware(InventorySnapshot snapshot, object software, string softwarePath)
        {
            object blockGroup = TryGetPropertyValue(software, "BlockGroup");
            if (blockGroup != null)
            {
                CollectBlockGroup(snapshot, softwarePath, blockGroup, null);
            }

            object tagTableGroup = TryGetPropertyValue(software, "TagTableGroup");
            if (tagTableGroup != null)
            {
                CollectTagTableGroup(snapshot, softwarePath, tagTableGroup, null);
            }
        }

        private static void CollectBlockGroup(InventorySnapshot snapshot, string softwarePath, object group, string groupPath)
        {
            string normalizedGroupPath = NormalizeGroupPathKey(groupPath);
            snapshot.BlockGroups.Add(new BlockGroupRecord
            {
                SoftwarePath = softwarePath,
                ParentGroupPath = ParentGroupPathKey(normalizedGroupPath),
                ParentGroupPathDisplay = GroupPathDisplay(ParentGroupPathKey(normalizedGroupPath)),
                GroupPath = normalizedGroupPath,
                GroupPathDisplay = GroupPathDisplay(normalizedGroupPath),
                Name = string.IsNullOrEmpty(normalizedGroupPath) ? "_root" : LastGroupNameFromKey(normalizedGroupPath),
                TypeName = group.GetType().FullName,
                Object = group
            });

            object blocks = TryGetPropertyValue(group, "Blocks");
            if (blocks != null)
            {
                foreach (object block in AsEnumerable(blocks))
                {
                    string autoNumber = SafeGet(block, "AutoNumber");
                    string typeName = block.GetType().FullName;
                    string programmingLanguage = SafeGet(block, "ProgrammingLanguage");
                    string tiaObjectId;
                    string tiaObjectIdStatus;
                    TryReadTiaObjectId(snapshot.ObjectIdentifierProvider, block, out tiaObjectId, out tiaObjectIdStatus);

                    snapshot.Blocks.Add(new BlockRecord
                    {
                        SoftwarePath = softwarePath,
                        GroupPath = normalizedGroupPath,
                        GroupPathDisplay = GroupPathDisplay(normalizedGroupPath),
                        Name = SafeName(block),
                        Number = SafeGet(block, "Number"),
                        AutoNumber = autoNumber,
                        NumberMode = DetermineNumberMode(block, autoNumber),
                        NumberSpace = BlockNumberSpace(typeName, programmingLanguage),
                        ProgrammingLanguage = programmingLanguage,
                        BlockType = SafeGet(block, "BlockType"),
                        TypeName = typeName,
                        SourceTypeName = string.Empty,
                        InstanceOfName = SafeGet(block, "InstanceOfName"),
                        InstanceOfNumber = Convert.ToString(TryReadAttribute(block, "InstanceOfNumber")),
                        InstanceOfType = Convert.ToString(TryReadAttribute(block, "InstanceOfType")),
                        SecondaryType = Convert.ToString(TryReadAttribute(block, "SecondaryType")),
                        MemoryLayout = SafeGet(block, "MemoryLayout"),
                        IsConsistent = SafeGet(block, "IsConsistent"),
                        IsKnowHowProtected = SafeGet(block, "IsKnowHowProtected"),
                        TiaObjectId = tiaObjectId,
                        TiaObjectIdStatus = tiaObjectIdStatus,
                        Object = block
                    });
                }
            }

            object groups = TryGetPropertyValue(group, "Groups");
            if (groups != null)
            {
                foreach (object child in AsEnumerable(groups))
                {
                    string childPath = CombineGroupPathKey(normalizedGroupPath, SafeName(child));
                    CollectBlockGroup(snapshot, softwarePath, child, childPath);
                }
            }
        }

        private static void CollectTagTableGroup(InventorySnapshot snapshot, string softwarePath, object group, string groupPath)
        {
            string normalizedGroupPath = NormalizeGroupPathKey(groupPath);
            object tables = TryGetPropertyValue(group, "TagTables");
            if (tables != null)
            {
                foreach (object table in AsEnumerable(tables))
                {
                    TagTableRecord tableRecord = new TagTableRecord
                    {
                        SoftwarePath = softwarePath,
                        GroupPath = normalizedGroupPath,
                        Name = SafeName(table),
                        TypeName = table.GetType().FullName,
                        Object = table
                    };
                    snapshot.TagTables.Add(tableRecord);

                    object tags = TryGetPropertyValue(table, "Tags");
                    if (tags == null)
                    {
                        continue;
                    }

                    foreach (object tag in AsEnumerable(tags))
                    {
                        snapshot.Tags.Add(new TagRecord
                        {
                            SoftwarePath = softwarePath,
                            GroupPath = normalizedGroupPath,
                            TableName = tableRecord.Name,
                            Name = SafeName(tag),
                            DataTypeName = SafeGet(tag, "DataTypeName"),
                            LogicalAddress = SafeGet(tag, "LogicalAddress"),
                            TypeName = tag.GetType().FullName,
                            Object = tag
                        });
                    }
                }
            }

            object groups = TryGetPropertyValue(group, "Groups");
            if (groups != null)
            {
                foreach (object child in AsEnumerable(groups))
                {
                    string childPath = CombineGroupPathKey(normalizedGroupPath, SafeName(child));
                    CollectTagTableGroup(snapshot, softwarePath, child, childPath);
                }
            }
        }

        private static void WriteInventory(InventorySnapshot snapshot, string outDir)
        {
            Directory.CreateDirectory(outDir);

            using (StreamWriter writer = NewUtf8Writer(Path.Combine(outDir, "project-summary.txt")))
            {
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Project type: " + snapshot.ProjectType);
                writer.WriteLine("Created at: " + snapshot.CreatedAt.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Devices/items/software: " + snapshot.Devices.Count);
                writer.WriteLine("Block groups: " + snapshot.BlockGroups.Count);
                writer.WriteLine("Blocks: " + snapshot.Blocks.Count);
                writer.WriteLine("Tag tables: " + snapshot.TagTables.Count);
                writer.WriteLine("Tags: " + snapshot.Tags.Count);
            }

            WriteCsv(Path.Combine(outDir, "devices.csv"),
                new[] { "Kind", "Path", "Name", "TypeIdentifier", "OrderNumber", "SoftwareType" },
                snapshot.Devices.Select(x => new[] { x.Kind, x.Path, x.Name, x.TypeIdentifier, x.OrderNumber, x.SoftwareType }));

            WriteCsv(Path.Combine(outDir, "block-groups.csv"),
                new[] { "SoftwarePath", "ParentGroupPath", "ParentGroupPathDisplay", "GroupPath", "GroupPathDisplay", "GroupPathKey", "Name", "TypeName" },
                snapshot.BlockGroups.Select(x => new[] { x.SoftwarePath, x.ParentGroupPath, x.ParentGroupPathDisplay, x.GroupPath, x.GroupPathDisplay, x.GroupPath, x.Name, x.TypeName }));

            WriteCsv(Path.Combine(outDir, "blocks.csv"),
                new[]
                {
                    "SoftwarePath", "GroupPath", "GroupPathDisplay", "GroupPathKey", "Name", "Number", "AutoNumber", "NumberMode", "NumberSpace",
                    "ProgrammingLanguage", "BlockType", "TypeName", "SourceTypeName",
                    "InstanceOfName", "InstanceOfNumber", "InstanceOfType", "SecondaryType",
                    "MemoryLayout", "IsConsistent", "IsKnowHowProtected", "TiaObjectId", "TiaObjectIdStatus"
                },
                snapshot.Blocks.Select(x => new[]
                {
                    x.SoftwarePath, x.GroupPath, x.GroupPathDisplay, x.GroupPath, x.Name, x.Number, x.AutoNumber, x.NumberMode, x.NumberSpace,
                    x.ProgrammingLanguage, x.BlockType, x.TypeName, x.SourceTypeName,
                    x.InstanceOfName, x.InstanceOfNumber, x.InstanceOfType, x.SecondaryType,
                    x.MemoryLayout, x.IsConsistent, x.IsKnowHowProtected, x.TiaObjectId, x.TiaObjectIdStatus
                }));

            WriteCsv(Path.Combine(outDir, "tag-tables.csv"),
                new[] { "SoftwarePath", "GroupPath", "Name", "TypeName" },
                snapshot.TagTables.Select(x => new[] { x.SoftwarePath, x.GroupPath, x.Name, x.TypeName }));

            WriteCsv(Path.Combine(outDir, "tags.csv"),
                new[] { "SoftwarePath", "GroupPath", "TableName", "Name", "DataTypeName", "LogicalAddress", "TypeName" },
                snapshot.Tags.Select(x => new[] { x.SoftwarePath, x.GroupPath, x.TableName, x.Name, x.DataTypeName, x.LogicalAddress, x.TypeName }));

            WriteInventoryJson(snapshot, Path.Combine(outDir, "inventory.json"));
        }

        private static HmiInventorySnapshot CollectHmiInventory(InventorySnapshot projectSnapshot)
        {
            HmiInventorySnapshot snapshot = new HmiInventorySnapshot();
            snapshot.ProjectName = projectSnapshot.ProjectName;
            snapshot.ProjectPath = projectSnapshot.ProjectPath;
            snapshot.ProjectType = projectSnapshot.ProjectType;
            snapshot.CreatedAt = DateTime.Now;

            foreach (DeviceRecord softwareRecord in projectSnapshot.Devices.Where(x => EqualsIgnoreCase(x.Kind, "Software") && x.Object != null))
            {
                object hmiTarget = softwareRecord.Object;
                if (!LooksLikeHmiTarget(hmiTarget, softwareRecord.SoftwareType))
                {
                    continue;
                }

                string targetPath = softwareRecord.Path;
                snapshot.Targets.Add(new HmiTargetRecord
                {
                    TargetPath = targetPath,
                    Name = SafeName(hmiTarget),
                    Author = Convert.ToString(TryReadAttribute(hmiTarget, "Author")),
                    TypeName = hmiTarget.GetType().FullName,
                    Object = hmiTarget
                });

                CollectHmiScreenFolder(snapshot, targetPath, TryGetPropertyValue(hmiTarget, "ScreenFolder"), "Screens", "Screen", "Screens", "Folders");
                CollectHmiScreenFolder(snapshot, targetPath, TryGetPropertyValue(hmiTarget, "ScreenPopupFolder"), "Pop-up screens", "Popup", "ScreenPopups", "Folders");
                CollectHmiScreenFolder(snapshot, targetPath, TryGetPropertyValue(hmiTarget, "ScreenSlideinFolder"), "Slideins", "Slidein", "ScreenSlideins", "Folders");
                CollectHmiScreenFolder(snapshot, targetPath, TryGetPropertyValue(hmiTarget, "ScreenTemplateFolder"), "Templates", "Template", "ScreenTemplates", "Folders");
                CollectHmiTagFolder(snapshot, targetPath, TryGetPropertyValue(hmiTarget, "TagFolder"), "HMI tags");
                CollectHmiScriptFolder(snapshot, targetPath, TryGetPropertyValue(hmiTarget, "VBScriptFolder"), "VB scripts");
                CollectHmiNamedRecords(snapshot.TextLists, targetPath, string.Empty, TryGetPropertyValue(hmiTarget, "TextLists"), "TextList");
                CollectHmiNamedRecords(snapshot.GraphicLists, targetPath, string.Empty, TryGetPropertyValue(hmiTarget, "GraphicLists"), "GraphicList");
                CollectHmiNamedRecords(snapshot.Cycles, targetPath, string.Empty, TryGetPropertyValue(hmiTarget, "Cycles"), "Cycle");
                CollectHmiNamedRecords(snapshot.Connections, targetPath, string.Empty, TryGetPropertyValue(hmiTarget, "Connections"), "Connection");
            }

            return snapshot;
        }

        private static bool LooksLikeHmiTarget(object software, string softwareType)
        {
            if (software == null)
            {
                return false;
            }

            string typeName = softwareType ?? software.GetType().FullName;
            if (typeName.IndexOf("HmiTarget", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return true;
            }

            return TryGetPropertyValue(software, "ScreenFolder") != null
                || TryGetPropertyValue(software, "TagFolder") != null
                || TryGetPropertyValue(software, "ScreenPopupFolder") != null;
        }

        private static void CollectHmiScreenFolder(HmiInventorySnapshot snapshot, string targetPath, object folder, string folderPath, string kind, string itemProperty, string childFoldersProperty)
        {
            if (folder == null)
            {
                return;
            }

            int index = 0;
            object items = TryGetPropertyValue(folder, itemProperty);
            foreach (object item in AsEnumerable(items))
            {
                index++;
                snapshot.Screens.Add(new HmiScreenRecord
                {
                    TargetPath = targetPath,
                    Kind = kind,
                    FolderPath = EmptyIfNull(folderPath),
                    Name = SafeHmiName(item, kind, index),
                    Index = Convert.ToString(index),
                    TypeName = item.GetType().FullName,
                    Object = item
                });
            }

            object childFolders = TryGetPropertyValue(folder, childFoldersProperty);
            foreach (object child in AsEnumerable(childFolders))
            {
                string childPath = CombinePath(folderPath, SafeName(child));
                CollectHmiScreenFolder(snapshot, targetPath, child, childPath, kind, itemProperty, childFoldersProperty);
            }
        }

        private static void CollectHmiTagFolder(HmiInventorySnapshot snapshot, string targetPath, object folder, string folderPath)
        {
            if (folder == null)
            {
                return;
            }

            object tables = TryGetPropertyValue(folder, "TagTables");
            foreach (object table in AsEnumerable(tables))
            {
                HmiTagTableRecord tableRecord = new HmiTagTableRecord
                {
                    TargetPath = targetPath,
                    FolderPath = EmptyIfNull(folderPath),
                    Name = SafeName(table),
                    IsSystemObject = Convert.ToString(TryReadAttribute(table, "IsSystemObject")),
                    TypeName = table.GetType().FullName,
                    Object = table
                };
                snapshot.TagTables.Add(tableRecord);

                object tags = TryGetPropertyValue(table, "Tags");
                int index = 0;
                foreach (object tag in AsEnumerable(tags))
                {
                    index++;
                    snapshot.Tags.Add(new HmiTagRecord
                    {
                        TargetPath = targetPath,
                        FolderPath = tableRecord.FolderPath,
                        TableName = tableRecord.Name,
                        Name = SafeHmiName(tag, "Tag", index),
                        DataTypeName = FirstNonEmpty(Convert.ToString(TryReadAttribute(tag, "DataTypeName")), Convert.ToString(TryReadAttribute(tag, "DataType"))),
                        LogicalAddress = FirstNonEmpty(Convert.ToString(TryReadAttribute(tag, "LogicalAddress")), Convert.ToString(TryReadAttribute(tag, "Address"))),
                        AcquisitionMode = Convert.ToString(TryReadAttribute(tag, "AcquisitionMode")),
                        TypeName = tag.GetType().FullName,
                        Object = tag
                    });
                }
            }

            object childFolders = TryGetPropertyValue(folder, "Folders");
            foreach (object child in AsEnumerable(childFolders))
            {
                string childPath = CombinePath(folderPath, SafeName(child));
                CollectHmiTagFolder(snapshot, targetPath, child, childPath);
            }
        }

        private static void CollectHmiScriptFolder(HmiInventorySnapshot snapshot, string targetPath, object folder, string folderPath)
        {
            if (folder == null)
            {
                return;
            }

            CollectHmiNamedRecords(snapshot.Scripts, targetPath, folderPath, TryGetPropertyValue(folder, "VBScripts"), "VBScript");

            object childFolders = TryGetPropertyValue(folder, "Folders");
            foreach (object child in AsEnumerable(childFolders))
            {
                string childPath = CombinePath(folderPath, SafeName(child));
                CollectHmiScriptFolder(snapshot, targetPath, child, childPath);
            }
        }

        private static void CollectHmiNamedRecords(List<HmiNamedRecord> records, string targetPath, string parentPath, object values, string kind)
        {
            int index = 0;
            foreach (object value in AsEnumerable(values))
            {
                index++;
                records.Add(new HmiNamedRecord
                {
                    TargetPath = targetPath,
                    ParentPath = EmptyIfNull(parentPath),
                    Kind = kind,
                    Name = SafeHmiName(value, kind, index),
                    Index = Convert.ToString(index),
                    TypeName = value.GetType().FullName,
                    Object = value
                });
            }
        }

        private static string SafeHmiName(object value, string fallbackKind, int index)
        {
            string name = SafeGet(value, "Name");
            string typeName = value == null ? string.Empty : value.GetType().FullName;
            if (!string.IsNullOrWhiteSpace(name) && !EqualsIgnoreCase(name, typeName))
            {
                return name;
            }

            string described = SafeDescribe(value);
            if (!string.IsNullOrWhiteSpace(described) && !EqualsIgnoreCase(described, typeName))
            {
                return described;
            }

            return fallbackKind + "_" + index.ToString("000");
        }

        private static void WriteHmiInventory(HmiInventorySnapshot snapshot, string outDir)
        {
            Directory.CreateDirectory(outDir);

            using (StreamWriter writer = NewUtf8Writer(Path.Combine(outDir, "hmi-summary.txt")))
            {
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Project type: " + snapshot.ProjectType);
                writer.WriteLine("Created at: " + snapshot.CreatedAt.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("HMI targets: " + snapshot.Targets.Count);
                writer.WriteLine("HMI screens/popups/slideins/templates: " + snapshot.Screens.Count);
                writer.WriteLine("HMI tag tables: " + snapshot.TagTables.Count);
                writer.WriteLine("HMI tags: " + snapshot.Tags.Count);
                writer.WriteLine("HMI text lists: " + snapshot.TextLists.Count);
                writer.WriteLine("HMI graphic lists: " + snapshot.GraphicLists.Count);
                writer.WriteLine("HMI cycles: " + snapshot.Cycles.Count);
                writer.WriteLine("HMI scripts: " + snapshot.Scripts.Count);
                writer.WriteLine("HMI connections: " + snapshot.Connections.Count);
            }

            WriteCsv(Path.Combine(outDir, "hmi-targets.csv"),
                new[] { "TargetPath", "Name", "Author", "TypeName" },
                snapshot.Targets.Select(x => new[] { x.TargetPath, x.Name, x.Author, x.TypeName }));

            WriteCsv(Path.Combine(outDir, "hmi-screens.csv"),
                new[] { "TargetPath", "Kind", "FolderPath", "Name", "Index", "TypeName" },
                snapshot.Screens.Select(x => new[] { x.TargetPath, x.Kind, x.FolderPath, x.Name, x.Index, x.TypeName }));

            WriteCsv(Path.Combine(outDir, "hmi-tag-tables.csv"),
                new[] { "TargetPath", "FolderPath", "Name", "IsSystemObject", "TypeName" },
                snapshot.TagTables.Select(x => new[] { x.TargetPath, x.FolderPath, x.Name, x.IsSystemObject, x.TypeName }));

            WriteCsv(Path.Combine(outDir, "hmi-tags.csv"),
                new[] { "TargetPath", "FolderPath", "TableName", "Name", "DataTypeName", "LogicalAddress", "AcquisitionMode", "TypeName" },
                snapshot.Tags.Select(x => new[] { x.TargetPath, x.FolderPath, x.TableName, x.Name, x.DataTypeName, x.LogicalAddress, x.AcquisitionMode, x.TypeName }));

            WriteHmiNamedCsv(Path.Combine(outDir, "hmi-text-lists.csv"), snapshot.TextLists);
            WriteHmiNamedCsv(Path.Combine(outDir, "hmi-graphic-lists.csv"), snapshot.GraphicLists);
            WriteHmiNamedCsv(Path.Combine(outDir, "hmi-cycles.csv"), snapshot.Cycles);
            WriteHmiNamedCsv(Path.Combine(outDir, "hmi-scripts.csv"), snapshot.Scripts);
            WriteHmiNamedCsv(Path.Combine(outDir, "hmi-connections.csv"), snapshot.Connections);
            WriteHmiInventoryJson(snapshot, Path.Combine(outDir, "hmi-inventory.json"));
        }

        private static void WriteHmiNamedCsv(string path, List<HmiNamedRecord> records)
        {
            WriteCsv(path,
                new[] { "TargetPath", "ParentPath", "Kind", "Name", "Index", "TypeName" },
                records.Select(x => new[] { x.TargetPath, x.ParentPath, x.Kind, x.Name, x.Index, x.TypeName }));
        }

        private static void WriteHmiInventoryJson(HmiInventorySnapshot snapshot, string path)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"project\": {");
                writer.WriteLine("    \"name\": " + Json(snapshot.ProjectName) + ",");
                writer.WriteLine("    \"path\": " + Json(snapshot.ProjectPath) + ",");
                writer.WriteLine("    \"type\": " + Json(snapshot.ProjectType) + ",");
                writer.WriteLine("    \"createdAt\": " + Json(snapshot.CreatedAt.ToString("o")));
                writer.WriteLine("  },");
                WriteJsonArray(writer, "targets", snapshot.Targets.Select(x => new Dictionary<string, string>
                {
                    { "targetPath", x.TargetPath },
                    { "name", x.Name },
                    { "author", x.Author },
                    { "typeName", x.TypeName }
                }), true);
                WriteJsonArray(writer, "screens", snapshot.Screens.Select(x => new Dictionary<string, string>
                {
                    { "targetPath", x.TargetPath },
                    { "kind", x.Kind },
                    { "folderPath", x.FolderPath },
                    { "name", x.Name },
                    { "index", x.Index },
                    { "typeName", x.TypeName }
                }), true);
                WriteJsonArray(writer, "tagTables", snapshot.TagTables.Select(x => new Dictionary<string, string>
                {
                    { "targetPath", x.TargetPath },
                    { "folderPath", x.FolderPath },
                    { "name", x.Name },
                    { "isSystemObject", x.IsSystemObject },
                    { "typeName", x.TypeName }
                }), true);
                WriteJsonArray(writer, "tags", snapshot.Tags.Select(x => new Dictionary<string, string>
                {
                    { "targetPath", x.TargetPath },
                    { "folderPath", x.FolderPath },
                    { "tableName", x.TableName },
                    { "name", x.Name },
                    { "dataTypeName", x.DataTypeName },
                    { "logicalAddress", x.LogicalAddress },
                    { "acquisitionMode", x.AcquisitionMode },
                    { "typeName", x.TypeName }
                }), true);
                WriteJsonArray(writer, "textLists", HmiNamedJsonRows(snapshot.TextLists), true);
                WriteJsonArray(writer, "graphicLists", HmiNamedJsonRows(snapshot.GraphicLists), true);
                WriteJsonArray(writer, "cycles", HmiNamedJsonRows(snapshot.Cycles), true);
                WriteJsonArray(writer, "scripts", HmiNamedJsonRows(snapshot.Scripts), true);
                WriteJsonArray(writer, "connections", HmiNamedJsonRows(snapshot.Connections), false);
                writer.WriteLine("}");
            }
        }

        private static IEnumerable<Dictionary<string, string>> HmiNamedJsonRows(List<HmiNamedRecord> records)
        {
            return records.Select(x => new Dictionary<string, string>
            {
                { "targetPath", x.TargetPath },
                { "parentPath", x.ParentPath },
                { "kind", x.Kind },
                { "name", x.Name },
                { "index", x.Index },
                { "typeName", x.TypeName }
            });
        }

        private static void ExportHmiXml(HmiInventorySnapshot snapshot, string outDir, bool force)
        {
            Directory.CreateDirectory(outDir);
            List<string[]> report = new List<string[]>();

            foreach (HmiScreenRecord screen in snapshot.Screens)
            {
                string directory = HmiScreenExportDirectory(screen.Kind);
                string systemRoot = HmiScreenSystemRoot(screen.Kind);
                ExportHmiObject(report, screen.Kind, screen.TargetPath, screen.FolderPath, screen.Name, screen.Index, screen.TypeName, screen.Object, outDir, directory, systemRoot, force);
            }

            foreach (HmiTagTableRecord table in snapshot.TagTables)
            {
                ExportHmiObject(report, "TagTable", table.TargetPath, table.FolderPath, table.Name, string.Empty, table.TypeName, table.Object, outDir, "tag-tables", "HMI tags", force);
            }

            ExportHmiNamedObjects(report, snapshot.TextLists, outDir, "text-lists", string.Empty, force);
            ExportHmiNamedObjects(report, snapshot.GraphicLists, outDir, "graphic-lists", string.Empty, force);
            ExportHmiNamedObjects(report, snapshot.Scripts, outDir, "scripts", "VB scripts", force);
            ExportHmiNamedObjects(report, snapshot.Connections, outDir, "connections", string.Empty, force);

            WriteCsv(Path.Combine(outDir, "hmi-export-report.csv"),
                new[] { "Kind", "TargetPath", "FolderPath", "Name", "TypeName", "FilePath", "Status", "Message" },
                report);
        }

        private static void ExportHmiNamedObjects(List<string[]> report, List<HmiNamedRecord> records, string outDir, string directory, string systemRoot, bool force)
        {
            foreach (HmiNamedRecord record in records)
            {
                ExportHmiObject(report, record.Kind, record.TargetPath, record.ParentPath, record.Name, record.Index, record.TypeName, record.Object, outDir, directory, systemRoot, force);
            }
        }

        private static void ExportHmiObject(List<string[]> report, string kind, string targetPath, string folderPath, string name, string index, string typeName, object target, string outDir, string directory, string systemRoot, bool force)
        {
            string relativeFolder = HmiRelativeFolderPath(folderPath, systemRoot);
            string exportDir = string.IsNullOrWhiteSpace(relativeFolder)
                ? Path.Combine(outDir, directory)
                : Path.Combine(outDir, directory, SafeFilePath(relativeFolder));
            string fileName = SafeFileName(HmiExportFilePrefix(index) + name + ".xml");
            string filePath = Path.Combine(exportDir, fileName);

            ExportReportRow row = TryExportObject(target, filePath, force);
            report.Add(new[] { kind, targetPath, EmptyIfNull(folderPath), name, typeName, filePath, row.Status, row.Message });
        }

        private static string HmiScreenExportDirectory(string kind)
        {
            if (EqualsIgnoreCase(kind, "Popup"))
            {
                return "popups";
            }

            if (EqualsIgnoreCase(kind, "Slidein"))
            {
                return "slideins";
            }

            if (EqualsIgnoreCase(kind, "Template"))
            {
                return "templates";
            }

            return "screens";
        }

        private static string HmiScreenSystemRoot(string kind)
        {
            if (EqualsIgnoreCase(kind, "Popup"))
            {
                return "Pop-up screens";
            }

            if (EqualsIgnoreCase(kind, "Slidein"))
            {
                return "Slideins";
            }

            if (EqualsIgnoreCase(kind, "Template"))
            {
                return "Templates";
            }

            return "Screens";
        }

        private static string HmiRelativeFolderPath(string folderPath, string systemRoot)
        {
            string value = EmptyIfNull(folderPath).Trim('/').Trim('\\');
            string root = EmptyIfNull(systemRoot).Trim('/').Trim('\\');
            if (string.IsNullOrEmpty(value) || string.IsNullOrEmpty(root))
            {
                return value;
            }

            if (EqualsIgnoreCase(value, root))
            {
                return string.Empty;
            }

            string prefix = root + "/";
            if (value.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
            {
                return value.Substring(prefix.Length);
            }

            return value;
        }

        private static string HmiExportFilePrefix(string index)
        {
            int parsed;
            if (int.TryParse(index, out parsed) && parsed > 0)
            {
                return parsed.ToString("000") + "_";
            }

            return string.Empty;
        }

        private static void WriteHmiDigest(string inDir, string outDir)
        {
            Directory.CreateDirectory(outDir);

            Dictionary<string, Dictionary<string, string>> reportByPath = LoadHmiExportReport(inDir);
            List<HmiXmlFileDigestRecord> xmlFiles = new List<HmiXmlFileDigestRecord>();
            List<HmiObjectIndexRecord> objectIndex = new List<HmiObjectIndexRecord>();
            List<HmiScreenItemDigestRecord> screenItems = new List<HmiScreenItemDigestRecord>();
            List<HmiScreenBindingDigestRecord> screenBindings = new List<HmiScreenBindingDigestRecord>();
            List<HmiEventHandlerDigestRecord> eventHandlers = new List<HmiEventHandlerDigestRecord>();
            List<HmiTagDetailDigestRecord> tagDetails = new List<HmiTagDetailDigestRecord>();
            List<HmiTextListItemDigestRecord> textListItems = new List<HmiTextListItemDigestRecord>();

            foreach (string filePath in Directory.GetFiles(inDir, "*.xml", SearchOption.AllDirectories).OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
            {
                string fullPath = Path.GetFullPath(filePath);
                string relativePath = RelativePathUnder(inDir, fullPath);
                Dictionary<string, string> report = null;
                if (!reportByPath.TryGetValue(fullPath, out report))
                {
                    reportByPath.TryGetValue(NormalizeHmiRelativePath(relativePath), out report);
                }
                string kind = FirstNonEmpty(GetCsvValue(report, "Kind"), InferHmiKindFromRelativePath(relativePath));
                string name = GetCsvValue(report, "Name");
                string typeName = GetCsvValue(report, "TypeName");
                string sha256 = ComputeFileSha256(fullPath);
                FileInfo info = new FileInfo(fullPath);

                HmiXmlFileDigestRecord fileRecord = new HmiXmlFileDigestRecord
                {
                    RelativePath = relativePath,
                    Kind = kind,
                    Name = name,
                    TypeName = typeName,
                    Length = Convert.ToString(info.Length),
                    Sha256 = sha256,
                    ParseStatus = "ok"
                };

                try
                {
                    XmlDocument document = LoadXmlDocument(fullPath);
                    XmlElement rootObject = FindExportRootObject(document);
                    fileRecord.EngineeringVersion = GetEngineeringVersion(document);
                    fileRecord.ExportSetting = GetDocumentInfoText(document, "ExportSetting");
                    fileRecord.RootElement = document.DocumentElement == null ? string.Empty : document.DocumentElement.Name;
                    fileRecord.ObjectElement = rootObject == null ? string.Empty : rootObject.Name;
                    fileRecord.ObjectId = rootObject == null ? string.Empty : rootObject.GetAttribute("ID");
                    fileRecord.ObjectName = rootObject == null ? string.Empty : GetAttributeListValue(rootObject, "Name");

                    if (string.IsNullOrWhiteSpace(fileRecord.Name))
                    {
                        fileRecord.Name = FirstNonEmpty(fileRecord.ObjectName, Path.GetFileNameWithoutExtension(relativePath));
                    }

                    if (string.IsNullOrWhiteSpace(fileRecord.TypeName))
                    {
                        fileRecord.TypeName = fileRecord.ObjectElement;
                    }

                    if (rootObject != null)
                    {
                        AddHmiObjectIndex(objectIndex, "ExportObject", fileRecord.Name, string.Empty, relativePath, rootObject);
                        if (IsHmiScreenLikeKind(kind, relativePath))
                        {
                            ParseHmiScreenDigest(relativePath, fileRecord.Name, kind, rootObject, objectIndex, screenItems, screenBindings, eventHandlers, outDir);
                        }
                        else if (EqualsIgnoreCase(kind, "TagTable") || relativePath.StartsWith("tag-tables", StringComparison.OrdinalIgnoreCase))
                        {
                            ParseHmiTagTableDigest(relativePath, fileRecord.Name, rootObject, objectIndex, tagDetails);
                        }
                        else if (EqualsIgnoreCase(kind, "TextList") || relativePath.StartsWith("text-lists", StringComparison.OrdinalIgnoreCase))
                        {
                            ParseHmiTextListDigest(relativePath, fileRecord.Name, rootObject, objectIndex, textListItems);
                        }
                    }
                }
                catch (Exception ex)
                {
                    fileRecord.ParseStatus = "error";
                    fileRecord.Message = ex.GetType().Name + ": " + ex.Message;
                }

                xmlFiles.Add(fileRecord);
            }

            WriteCsv(Path.Combine(outDir, "hmi-xml-files.csv"),
                new[] { "RelativePath", "Kind", "Name", "TypeName", "Length", "Sha256", "RootElement", "ObjectElement", "ObjectId", "ObjectName", "EngineeringVersion", "ExportSetting", "ParseStatus", "Message" },
                xmlFiles.Select(x => new[] { x.RelativePath, x.Kind, x.Name, x.TypeName, x.Length, x.Sha256, x.RootElement, x.ObjectElement, x.ObjectId, x.ObjectName, x.EngineeringVersion, x.ExportSetting, x.ParseStatus, x.Message }));

            WriteCsv(Path.Combine(outDir, "hmi-object-index.csv"),
                new[] { "Kind", "Name", "ParentName", "RelativePath", "ObjectId", "ObjectType", "CompositionName", "Left", "Top", "Width", "Height" },
                objectIndex.Select(x => new[] { x.Kind, x.Name, x.ParentName, x.RelativePath, x.ObjectId, x.ObjectType, x.CompositionName, x.Left, x.Top, x.Width, x.Height }));

            WriteCsv(Path.Combine(outDir, "hmi-screen-items.csv"),
                new[] { "ScreenName", "RelativePath", "ItemName", "ItemId", "ItemType", "CompositionName", "Left", "Top", "Width", "Height", "Text", "Bindings", "Events" },
                screenItems.Select(x => new[] { x.ScreenName, x.RelativePath, x.ItemName, x.ItemId, x.ItemType, x.CompositionName, x.Left, x.Top, x.Width, x.Height, x.Text, x.Bindings, x.Events }));

            WriteCsv(Path.Combine(outDir, "hmi-screen-bindings.csv"),
                new[] { "ScreenName", "RelativePath", "ItemName", "ItemId", "BindingKind", "TargetName", "TargetId" },
                screenBindings.Select(x => new[] { x.ScreenName, x.RelativePath, x.ItemName, x.ItemId, x.BindingKind, x.TargetName, x.TargetId }));

            WriteCsv(Path.Combine(outDir, "hmi-event-handlers.csv"),
                new[] { "ScreenName", "RelativePath", "ItemName", "ItemId", "EventName", "FunctionName", "FunctionType", "Parameters" },
                eventHandlers.Select(x => new[] { x.ScreenName, x.RelativePath, x.ItemName, x.ItemId, x.EventName, x.FunctionName, x.FunctionType, x.Parameters }));

            WriteCsv(Path.Combine(outDir, "hmi-tag-details.csv"),
                new[] { "TagTableName", "RelativePath", "Name", "LogicalAddress", "AddressAccessMode", "AcquisitionTriggerMode", "AcquisitionCycle", "Connection", "ControllerTag", "DataType", "HmiDataType", "Coding", "Length" },
                tagDetails.Select(x => new[] { x.TagTableName, x.RelativePath, x.Name, x.LogicalAddress, x.AddressAccessMode, x.AcquisitionTriggerMode, x.AcquisitionCycle, x.Connection, x.ControllerTag, x.DataType, x.HmiDataType, x.Coding, x.Length }));

            WriteCsv(Path.Combine(outDir, "hmi-text-list-items.csv"),
                new[] { "TextListName", "RelativePath", "EntryId", "From", "To", "EntryType", "DefaultEntry", "Texts" },
                textListItems.Select(x => new[] { x.TextListName, x.RelativePath, x.EntryId, x.From, x.To, x.EntryType, x.DefaultEntry, x.Texts }));

            WriteHmiDigestJson(Path.Combine(outDir, "hmi-digest.json"), inDir, xmlFiles, objectIndex, screenItems, screenBindings, eventHandlers, tagDetails, textListItems);
        }

        private static Dictionary<string, Dictionary<string, string>> LoadHmiExportReport(string inDir)
        {
            Dictionary<string, Dictionary<string, string>> result = new Dictionary<string, Dictionary<string, string>>(StringComparer.OrdinalIgnoreCase);
            string reportPath = Path.Combine(inDir, "hmi-export-report.csv");
            if (!File.Exists(reportPath))
            {
                return result;
            }

            foreach (Dictionary<string, string> row in ReadCsv(reportPath))
            {
                string filePath = GetCsvValue(row, "FilePath");
                if (!string.IsNullOrWhiteSpace(filePath))
                {
                    string fullPath = Path.GetFullPath(filePath);
                    result[fullPath] = row;

                    string relativePath = HmiExportReportRelativePath(inDir, fullPath);
                    if (!string.IsNullOrWhiteSpace(relativePath))
                    {
                        result[NormalizeHmiRelativePath(relativePath)] = row;
                    }
                }
            }

            return result;
        }

        private static string HmiExportReportRelativePath(string inDir, string filePath)
        {
            string fullPath = Path.GetFullPath(filePath);
            string root = Path.GetFullPath(inDir).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar) + Path.DirectorySeparatorChar;
            if (fullPath.StartsWith(root, StringComparison.OrdinalIgnoreCase))
            {
                return RelativePathUnder(inDir, fullPath);
            }

            string normalized = fullPath.Replace(Path.AltDirectorySeparatorChar, Path.DirectorySeparatorChar);
            foreach (string segment in new[] { "screens", "popups", "slideins", "templates", "tag-tables", "text-lists", "graphic-lists", "scripts", "connections" })
            {
                string marker = Path.DirectorySeparatorChar + segment + Path.DirectorySeparatorChar;
                int index = normalized.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
                if (index >= 0)
                {
                    return normalized.Substring(index + 1);
                }
            }

            return string.Empty;
        }

        private static XmlDocument LoadXmlDocument(string filePath)
        {
            XmlDocument document = new XmlDocument();
            document.PreserveWhitespace = false;
            using (XmlReader reader = XmlReader.Create(filePath, new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit }))
            {
                document.Load(reader);
            }

            return document;
        }

        private static XmlElement FindExportRootObject(XmlDocument document)
        {
            if (document.DocumentElement == null)
            {
                return null;
            }

            foreach (XmlElement child in ChildElements(document.DocumentElement))
            {
                if (!EqualsIgnoreCase(child.Name, "Engineering") && !EqualsIgnoreCase(child.Name, "DocumentInfo"))
                {
                    return child;
                }
            }

            return null;
        }

        private static string GetEngineeringVersion(XmlDocument document)
        {
            if (document.DocumentElement == null)
            {
                return string.Empty;
            }

            foreach (XmlElement child in ChildElements(document.DocumentElement))
            {
                if (EqualsIgnoreCase(child.Name, "Engineering"))
                {
                    return child.GetAttribute("version");
                }
            }

            return string.Empty;
        }

        private static string GetDocumentInfoText(XmlDocument document, string name)
        {
            if (document.DocumentElement == null)
            {
                return string.Empty;
            }

            foreach (XmlElement child in ChildElements(document.DocumentElement))
            {
                if (!EqualsIgnoreCase(child.Name, "DocumentInfo"))
                {
                    continue;
                }

                foreach (XmlElement infoChild in ChildElements(child))
                {
                    if (EqualsIgnoreCase(infoChild.Name, name))
                    {
                        return CleanXmlText(infoChild.InnerText);
                    }
                }
            }

            return string.Empty;
        }

        private static void ParseHmiScreenDigest(string relativePath, string screenName, string kind, XmlElement rootObject, List<HmiObjectIndexRecord> objectIndex, List<HmiScreenItemDigestRecord> screenItems, List<HmiScreenBindingDigestRecord> bindings, List<HmiEventHandlerDigestRecord> eventHandlers, string outDir)
        {
            List<HmiScreenItemDigestRecord> localItems = new List<HmiScreenItemDigestRecord>();

            foreach (XmlElement item in DescendantElements(rootObject).Where(x => EqualsIgnoreCase(x.GetAttribute("CompositionName"), "ScreenItems")))
            {
                string itemName = FirstNonEmpty(GetAttributeListValue(item, "ObjectName"), GetAttributeListValue(item, "Name"), ShortXmlType(item.Name) + "_" + item.GetAttribute("ID"));
                string itemId = item.GetAttribute("ID");
                string itemType = item.Name;
                string compositionName = item.GetAttribute("CompositionName");
                string itemText = GetMultilingualTextSummary(item, "Text");
                string bindingSummary = GetLinkSummary(item);
                string eventSummary = GetEventSummary(item);

                HmiScreenItemDigestRecord row = new HmiScreenItemDigestRecord
                {
                    ScreenName = screenName,
                    RelativePath = relativePath,
                    ItemName = itemName,
                    ItemId = itemId,
                    ItemType = itemType,
                    CompositionName = compositionName,
                    Left = GetAttributeListValue(item, "Left"),
                    Top = GetAttributeListValue(item, "Top"),
                    Width = GetAttributeListValue(item, "Width"),
                    Height = GetAttributeListValue(item, "Height"),
                    Text = itemText,
                    Bindings = bindingSummary,
                    Events = eventSummary
                };
                screenItems.Add(row);
                localItems.Add(row);
                AddHmiObjectIndex(objectIndex, "ScreenItem", itemName, screenName, relativePath, item);

                foreach (HmiScreenBindingDigestRecord binding in ExtractHmiBindings(screenName, relativePath, itemName, itemId, item))
                {
                    bindings.Add(binding);
                }

                ParseHmiEventHandlers(screenName, relativePath, itemName, itemId, item, eventHandlers);
            }

            foreach (XmlElement screenEvent in DirectObjectChildren(rootObject, "Hmi.Event.Event", "Events"))
            {
                ParseHmiEventHandlers(screenName, relativePath, "SCREEN", string.Empty, screenEvent, eventHandlers);
            }

            WriteHmiScreenMarkdown(outDir, screenName, relativePath, rootObject, localItems);
        }

        private static void ParseHmiTagTableDigest(string relativePath, string tagTableName, XmlElement rootObject, List<HmiObjectIndexRecord> objectIndex, List<HmiTagDetailDigestRecord> tagDetails)
        {
            foreach (XmlElement tag in DescendantElements(rootObject).Where(x => EqualsIgnoreCase(x.Name, "Hmi.Tag.Tag")))
            {
                string tagName = GetAttributeListValue(tag, "Name");
                tagDetails.Add(new HmiTagDetailDigestRecord
                {
                    TagTableName = tagTableName,
                    RelativePath = relativePath,
                    Name = tagName,
                    LogicalAddress = GetAttributeListValue(tag, "LogicalAddress"),
                    AddressAccessMode = GetAttributeListValue(tag, "AddressAccessMode"),
                    AcquisitionTriggerMode = GetAttributeListValue(tag, "AcquisitionTriggerMode"),
                    AcquisitionCycle = GetDirectLinkName(tag, "AcquisitionCycle"),
                    Connection = GetDirectLinkName(tag, "Connection"),
                    ControllerTag = GetDirectLinkName(tag, "ControllerTag"),
                    DataType = GetDirectLinkName(tag, "DataType"),
                    HmiDataType = GetDirectLinkName(tag, "HmiDataType"),
                    Coding = GetAttributeListValue(tag, "Coding"),
                    Length = GetAttributeListValue(tag, "Length")
                });
                AddHmiObjectIndex(objectIndex, "HmiTag", tagName, tagTableName, relativePath, tag);
            }
        }

        private static void ParseHmiTextListDigest(string relativePath, string textListName, XmlElement rootObject, List<HmiObjectIndexRecord> objectIndex, List<HmiTextListItemDigestRecord> textListItems)
        {
            foreach (XmlElement entry in DescendantElements(rootObject).Where(x => EqualsIgnoreCase(x.Name, "Hmi.TextGraphicList.TextListEntry")))
            {
                textListItems.Add(new HmiTextListItemDigestRecord
                {
                    TextListName = textListName,
                    RelativePath = relativePath,
                    EntryId = entry.GetAttribute("ID"),
                    From = GetAttributeListValue(entry, "From"),
                    To = GetAttributeListValue(entry, "To"),
                    EntryType = GetAttributeListValue(entry, "EntryType"),
                    DefaultEntry = GetAttributeListValue(entry, "DefaultEntry"),
                    Texts = GetMultilingualTextSummary(entry, "Text")
                });
                AddHmiObjectIndex(objectIndex, "TextListEntry", textListName + ":" + GetAttributeListValue(entry, "From"), textListName, relativePath, entry);
            }
        }

        private static void AddHmiObjectIndex(List<HmiObjectIndexRecord> objectIndex, string kind, string name, string parentName, string relativePath, XmlElement element)
        {
            objectIndex.Add(new HmiObjectIndexRecord
            {
                Kind = kind,
                Name = name,
                ParentName = parentName,
                RelativePath = relativePath,
                ObjectId = element == null ? string.Empty : element.GetAttribute("ID"),
                ObjectType = element == null ? string.Empty : element.Name,
                CompositionName = element == null ? string.Empty : element.GetAttribute("CompositionName"),
                Left = element == null ? string.Empty : GetAttributeListValue(element, "Left"),
                Top = element == null ? string.Empty : GetAttributeListValue(element, "Top"),
                Width = element == null ? string.Empty : GetAttributeListValue(element, "Width"),
                Height = element == null ? string.Empty : GetAttributeListValue(element, "Height")
            });
        }

        private static List<HmiScreenBindingDigestRecord> ExtractHmiBindings(string screenName, string relativePath, string itemName, string itemId, XmlElement item)
        {
            List<HmiScreenBindingDigestRecord> rows = new List<HmiScreenBindingDigestRecord>();
            foreach (XmlElement linkList in DescendantElements(item).Where(x => EqualsIgnoreCase(x.Name, "LinkList")))
            {
                foreach (XmlElement link in ChildElements(linkList))
                {
                    string targetName = GetDirectChildText(link, "Name");
                    if (string.IsNullOrWhiteSpace(targetName))
                    {
                        continue;
                    }

                    rows.Add(new HmiScreenBindingDigestRecord
                    {
                        ScreenName = screenName,
                        RelativePath = relativePath,
                        ItemName = itemName,
                        ItemId = itemId,
                        BindingKind = link.Name,
                        TargetName = targetName,
                        TargetId = link.GetAttribute("TargetID")
                    });
                }
            }

            return rows;
        }

        private static void ParseHmiEventHandlers(string screenName, string relativePath, string itemName, string itemId, XmlElement scope, List<HmiEventHandlerDigestRecord> rows)
        {
            IEnumerable<XmlElement> events = EqualsIgnoreCase(scope.Name, "Hmi.Event.Event")
                ? new[] { scope }
                : DescendantElements(scope).Where(x => EqualsIgnoreCase(x.Name, "Hmi.Event.Event"));

            foreach (XmlElement eventElement in events)
            {
                string eventName = GetAttributeListValue(eventElement, "Name");
                foreach (XmlElement function in DescendantElements(eventElement).Where(x => EqualsIgnoreCase(x.Name, "Hmi.Event.FunctionListEntry")))
                {
                    rows.Add(new HmiEventHandlerDigestRecord
                    {
                        ScreenName = screenName,
                        RelativePath = relativePath,
                        ItemName = itemName,
                        ItemId = itemId,
                        EventName = eventName,
                        FunctionName = GetAttributeListValue(function, "Name"),
                        FunctionType = GetAttributeListValue(function, "Type"),
                        Parameters = GetFunctionParametersSummary(function)
                    });
                }
            }
        }

        private static string GetFunctionParametersSummary(XmlElement function)
        {
            List<string> parts = new List<string>();
            foreach (XmlElement parameter in DescendantElements(function).Where(x => EqualsIgnoreCase(x.Name, "Hmi.Event.FunctionListEntryParameter")))
            {
                string name = GetAttributeListValue(parameter, "Name");
                string value = FirstNonEmpty(GetAttributeListValue(parameter, "Value"), GetDirectLinkName(parameter, "Value"));
                if (!string.IsNullOrWhiteSpace(name) || !string.IsNullOrWhiteSpace(value))
                {
                    parts.Add(name + "=" + value);
                }
            }

            return string.Join("; ", parts.ToArray());
        }

        private static string GetEventSummary(XmlElement item)
        {
            List<string> names = DescendantElements(item)
                .Where(x => EqualsIgnoreCase(x.Name, "Hmi.Event.Event"))
                .Select(x => GetAttributeListValue(x, "Name"))
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToList();

            return string.Join("; ", names.ToArray());
        }

        private static string GetLinkSummary(XmlElement item)
        {
            List<string> parts = new List<string>();
            foreach (HmiScreenBindingDigestRecord binding in ExtractHmiBindings(string.Empty, string.Empty, string.Empty, string.Empty, item))
            {
                parts.Add(binding.BindingKind + "=" + binding.TargetName);
            }

            return string.Join("; ", parts.Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToArray());
        }

        private static string GetMultilingualTextSummary(XmlElement parent, string compositionName)
        {
            List<string> parts = new List<string>();
            foreach (XmlElement text in DirectObjectChildren(parent, "MultilingualText", compositionName))
            {
                foreach (XmlElement item in DescendantElements(text).Where(x => EqualsIgnoreCase(x.Name, "MultilingualTextItem")))
                {
                    string culture = GetAttributeListValue(item, "Culture");
                    string value = GetAttributeListValue(item, "Text");
                    if (!string.IsNullOrWhiteSpace(value))
                    {
                        parts.Add((string.IsNullOrWhiteSpace(culture) ? "neutral" : culture) + "=" + value);
                    }
                }
            }

            return string.Join(" | ", parts.ToArray());
        }

        private static IEnumerable<XmlElement> DirectObjectChildren(XmlElement parent, string elementName, string compositionName)
        {
            foreach (XmlElement objectList in ChildElements(parent).Where(x => EqualsIgnoreCase(x.Name, "ObjectList")))
            {
                foreach (XmlElement child in ChildElements(objectList))
                {
                    if ((string.IsNullOrEmpty(elementName) || EqualsIgnoreCase(child.Name, elementName))
                        && (string.IsNullOrEmpty(compositionName) || EqualsIgnoreCase(child.GetAttribute("CompositionName"), compositionName)))
                    {
                        yield return child;
                    }
                }
            }
        }

        private static string GetAttributeListValue(XmlElement element, string name)
        {
            if (element == null)
            {
                return string.Empty;
            }

            foreach (XmlElement child in ChildElements(element))
            {
                if (!EqualsIgnoreCase(child.Name, "AttributeList"))
                {
                    continue;
                }

                foreach (XmlElement attribute in ChildElements(child))
                {
                    if (EqualsIgnoreCase(attribute.Name, name))
                    {
                        return CleanXmlText(attribute.InnerText);
                    }
                }
            }

            return string.Empty;
        }

        private static string GetDirectLinkName(XmlElement element, string linkName)
        {
            foreach (XmlElement child in ChildElements(element))
            {
                if (!EqualsIgnoreCase(child.Name, "LinkList"))
                {
                    continue;
                }

                foreach (XmlElement link in ChildElements(child))
                {
                    if (EqualsIgnoreCase(link.Name, linkName))
                    {
                        return GetDirectChildText(link, "Name");
                    }
                }
            }

            return string.Empty;
        }

        private static string GetDirectChildText(XmlElement element, string childName)
        {
            foreach (XmlElement child in ChildElements(element))
            {
                if (EqualsIgnoreCase(child.Name, childName))
                {
                    return CleanXmlText(child.InnerText);
                }
            }

            return string.Empty;
        }

        private static IEnumerable<XmlElement> ChildElements(XmlNode node)
        {
            if (node == null)
            {
                yield break;
            }

            foreach (XmlNode child in node.ChildNodes)
            {
                XmlElement element = child as XmlElement;
                if (element != null)
                {
                    yield return element;
                }
            }
        }

        private static IEnumerable<XmlElement> DescendantElements(XmlNode node)
        {
            foreach (XmlElement child in ChildElements(node))
            {
                yield return child;
                foreach (XmlElement descendant in DescendantElements(child))
                {
                    yield return descendant;
                }
            }
        }

        private static string CleanXmlText(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return string.Empty;
            }

            return Regex.Replace(value, "\\s+", " ").Trim();
        }

        private static string ShortXmlType(string typeName)
        {
            if (string.IsNullOrWhiteSpace(typeName))
            {
                return string.Empty;
            }

            int index = typeName.LastIndexOf('.');
            return index >= 0 && index + 1 < typeName.Length ? typeName.Substring(index + 1) : typeName;
        }

        private static bool IsHmiScreenLikeKind(string kind, string relativePath)
        {
            return EqualsIgnoreCase(kind, "Screen")
                || EqualsIgnoreCase(kind, "Popup")
                || EqualsIgnoreCase(kind, "Slidein")
                || EqualsIgnoreCase(kind, "Template")
                || relativePath.StartsWith("screens", StringComparison.OrdinalIgnoreCase)
                || relativePath.StartsWith("popups", StringComparison.OrdinalIgnoreCase)
                || relativePath.StartsWith("slideins", StringComparison.OrdinalIgnoreCase)
                || relativePath.StartsWith("templates", StringComparison.OrdinalIgnoreCase);
        }

        private static string InferHmiKindFromRelativePath(string relativePath)
        {
            string first = relativePath.Split(new[] { Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar }, StringSplitOptions.RemoveEmptyEntries).FirstOrDefault() ?? string.Empty;
            if (EqualsIgnoreCase(first, "screens")) return "Screen";
            if (EqualsIgnoreCase(first, "popups")) return "Popup";
            if (EqualsIgnoreCase(first, "slideins")) return "Slidein";
            if (EqualsIgnoreCase(first, "templates")) return "Template";
            if (EqualsIgnoreCase(first, "tag-tables")) return "TagTable";
            if (EqualsIgnoreCase(first, "text-lists")) return "TextList";
            if (EqualsIgnoreCase(first, "graphic-lists")) return "GraphicList";
            if (EqualsIgnoreCase(first, "scripts")) return "Script";
            if (EqualsIgnoreCase(first, "connections")) return "Connection";
            return first;
        }

        private static string RelativePathUnder(string rootDir, string fullPath)
        {
            string root = Path.GetFullPath(rootDir).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar) + Path.DirectorySeparatorChar;
            string full = Path.GetFullPath(fullPath);
            return full.StartsWith(root, StringComparison.OrdinalIgnoreCase) ? full.Substring(root.Length) : full;
        }

        private static void WriteHmiScreenMarkdown(string outDir, string screenName, string relativePath, XmlElement rootObject, List<HmiScreenItemDigestRecord> items)
        {
            string directory = Path.Combine(outDir, "screens");
            Directory.CreateDirectory(directory);
            string path = Path.Combine(directory, SafeFileName(screenName + ".md"));
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("# " + screenName);
                writer.WriteLine();
                writer.WriteLine("- Source XML: `" + relativePath + "`");
                writer.WriteLine("- Size: `" + GetAttributeListValue(rootObject, "Width") + " x " + GetAttributeListValue(rootObject, "Height") + "`");
                writer.WriteLine("- Items: `" + items.Count + "`");
                writer.WriteLine();
                writer.WriteLine("## Item Types");
                writer.WriteLine();
                foreach (IGrouping<string, HmiScreenItemDigestRecord> group in items.GroupBy(x => ShortXmlType(x.ItemType)).OrderByDescending(x => x.Count()).ThenBy(x => x.Key))
                {
                    writer.WriteLine("- `" + group.Key + "`: " + group.Count());
                }
                writer.WriteLine();
                writer.WriteLine("## Items");
                writer.WriteLine();
                writer.WriteLine("| Name | Type | Bounds | Text | Bindings | Events |");
                writer.WriteLine("| --- | --- | --- | --- | --- | --- |");
                foreach (HmiScreenItemDigestRecord item in items.Take(200))
                {
                    string bounds = item.Left + "," + item.Top + " " + item.Width + "x" + item.Height;
                    writer.WriteLine("| " + MdCell(item.ItemName) + " | " + MdCell(ShortXmlType(item.ItemType)) + " | " + MdCell(bounds) + " | " + MdCell(item.Text) + " | " + MdCell(item.Bindings) + " | " + MdCell(item.Events) + " |");
                }
            }
        }

        private static string MdCell(string value)
        {
            return EmptyIfNull(value).Replace("|", "\\|").Replace("\r", " ").Replace("\n", " ");
        }

        private static void WriteHmiDigestJson(string path, string inDir, List<HmiXmlFileDigestRecord> xmlFiles, List<HmiObjectIndexRecord> objectIndex, List<HmiScreenItemDigestRecord> screenItems, List<HmiScreenBindingDigestRecord> screenBindings, List<HmiEventHandlerDigestRecord> eventHandlers, List<HmiTagDetailDigestRecord> tagDetails, List<HmiTextListItemDigestRecord> textListItems)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"inputDir\": " + Json(inDir) + ",");
                writer.WriteLine("  \"createdAt\": " + Json(DateTime.Now.ToString("o")) + ",");
                writer.WriteLine("  \"counts\": {");
                writer.WriteLine("    \"xmlFiles\": " + xmlFiles.Count + ",");
                writer.WriteLine("    \"objects\": " + objectIndex.Count + ",");
                writer.WriteLine("    \"screenItems\": " + screenItems.Count + ",");
                writer.WriteLine("    \"screenBindings\": " + screenBindings.Count + ",");
                writer.WriteLine("    \"eventHandlers\": " + eventHandlers.Count + ",");
                writer.WriteLine("    \"tagDetails\": " + tagDetails.Count + ",");
                writer.WriteLine("    \"textListItems\": " + textListItems.Count);
                writer.WriteLine("  },");
                WriteJsonArray(writer, "xmlFiles", xmlFiles.Select(x => new Dictionary<string, string>
                {
                    { "relativePath", x.RelativePath },
                    { "kind", x.Kind },
                    { "name", x.Name },
                    { "typeName", x.TypeName },
                    { "length", x.Length },
                    { "sha256", x.Sha256 },
                    { "objectElement", x.ObjectElement },
                    { "parseStatus", x.ParseStatus },
                    { "message", x.Message }
                }), true);
                WriteJsonArray(writer, "screenItems", screenItems.Select(x => new Dictionary<string, string>
                {
                    { "screenName", x.ScreenName },
                    { "relativePath", x.RelativePath },
                    { "itemName", x.ItemName },
                    { "itemType", x.ItemType },
                    { "left", x.Left },
                    { "top", x.Top },
                    { "width", x.Width },
                    { "height", x.Height },
                    { "text", x.Text },
                    { "bindings", x.Bindings },
                    { "events", x.Events }
                }), true);
                WriteJsonArray(writer, "tagDetails", tagDetails.Select(x => new Dictionary<string, string>
                {
                    { "tagTableName", x.TagTableName },
                    { "name", x.Name },
                    { "logicalAddress", x.LogicalAddress },
                    { "connection", x.Connection },
                    { "controllerTag", x.ControllerTag },
                    { "dataType", x.DataType },
                    { "hmiDataType", x.HmiDataType },
                    { "acquisitionCycle", x.AcquisitionCycle }
                }), true);
                WriteJsonArray(writer, "textListItems", textListItems.Select(x => new Dictionary<string, string>
                {
                    { "textListName", x.TextListName },
                    { "entryId", x.EntryId },
                    { "from", x.From },
                    { "to", x.To },
                    { "entryType", x.EntryType },
                    { "texts", x.Texts }
                }), false);
                writer.WriteLine("}");
            }
        }

        private static void InitializeHmiClone(InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, Options options)
        {
            Directory.CreateDirectory(outDir);
            string hmiRoot = Path.Combine(outDir, "_hmi");
            string metadataDir = Path.Combine(outDir, "_hmi_metadata");
            string digestDir = Path.Combine(metadataDir, "digest");
            string inventoryDir = Path.Combine(metadataDir, "inventory");

            Directory.CreateDirectory(hmiRoot);
            Directory.CreateDirectory(metadataDir);

            ExportHmiXml(hmiSnapshot, hmiRoot, options.Force);
            WriteHmiDigest(hmiRoot, digestDir);
            WriteHmiInventory(hmiSnapshot, inventoryDir);

            List<HmiObjectManifestRecord> manifest = BuildHmiObjectManifest(hmiRoot, digestDir);
            string manifestPath = Path.Combine(metadataDir, "hmi-objects.csv");
            WriteHmiObjectManifest(manifestPath, manifest);
            WriteHmiCloneSummary(Path.Combine(metadataDir, "hmi-clone-summary.txt"), snapshot, hmiSnapshot, outDir, hmiRoot, digestDir, inventoryDir, manifest, options.Force);

            Console.WriteLine("HMI clone initialized in: " + outDir);
            Console.WriteLine("HMI XML root: " + hmiRoot);
            Console.WriteLine("HMI metadata: " + metadataDir);
            Console.WriteLine("HMI objects in manifest: " + manifest.Count);
            Console.WriteLine("HMI XML export ok/skipped: " + manifest.Count(HasUsableHmiXml));
            Console.WriteLine("HMI XML export errors: " + manifest.Count(x => EqualsIgnoreCase(x.ExportStatus, "error")));
            Console.WriteLine("HMI object manifest written to: " + manifestPath);
        }

        private static void CheckHmiClone(InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir)
        {
            string hmiRoot = Path.Combine(outDir, "_hmi");
            string metadataDir = Path.Combine(outDir, "_hmi_metadata");
            string cloneManifestPath = Path.Combine(metadataDir, "hmi-objects.csv");
            if (!Directory.Exists(hmiRoot))
            {
                throw new DirectoryNotFoundException("HMI clone root was not found. Run hmi-init-clone first: " + hmiRoot);
            }

            if (!File.Exists(cloneManifestPath))
            {
                throw new FileNotFoundException("HMI clone manifest was not found. Run hmi-init-clone first.", cloneManifestPath);
            }

            HmiCurrentSnapshotRecord currentSnapshot = CreateCurrentHmiSnapshot(hmiSnapshot, outDir);
            List<HmiObjectManifestRecord> cloneManifest = LoadHmiObjectManifest(cloneManifestPath, hmiRoot);
            List<HmiObjectManifestRecord> currentManifest = currentSnapshot.Manifest;
            List<HmiObjectDiffRecord> diffs = BuildHmiObjectDiffs(cloneManifest, currentManifest);

            WriteHmiCheckReports(snapshot, outDir, currentSnapshot.CompareDir, cloneManifest, currentManifest, diffs);
            PrintHmiCheckResult(hmiRoot, currentSnapshot.CompareDir, Path.Combine(outDir, "hmi-check-objects.csv"), Path.Combine(outDir, "hmi-check-summary.txt"), diffs);
        }

        private static HmiCurrentSnapshotRecord CreateCurrentHmiSnapshot(HmiInventorySnapshot hmiSnapshot, string outDir)
        {
            string compareRoot = Path.Combine(outDir, "_hmi_compare");
            Directory.CreateDirectory(compareRoot);

            string compareDir = UniquePath(Path.Combine(compareRoot, "current-" + DateTime.Now.ToString("yyyyMMdd-HHmmss")));
            string currentHmiRoot = Path.Combine(compareDir, "_hmi");
            string currentMetadataDir = Path.Combine(compareDir, "_hmi_metadata");
            string currentDigestDir = Path.Combine(currentMetadataDir, "digest");
            string currentInventoryDir = Path.Combine(currentMetadataDir, "inventory");

            ExportHmiXml(hmiSnapshot, currentHmiRoot, true);
            WriteHmiDigest(currentHmiRoot, currentDigestDir);
            WriteHmiInventory(hmiSnapshot, currentInventoryDir);

            List<HmiObjectManifestRecord> currentManifest = BuildHmiObjectManifest(currentHmiRoot, currentDigestDir);
            string currentManifestPath = Path.Combine(currentMetadataDir, "hmi-objects.csv");
            WriteHmiObjectManifest(currentManifestPath, currentManifest);

            return new HmiCurrentSnapshotRecord
            {
                CompareDir = compareDir,
                HmiRoot = currentHmiRoot,
                MetadataDir = currentMetadataDir,
                DigestDir = currentDigestDir,
                InventoryDir = currentInventoryDir,
                ManifestPath = currentManifestPath,
                Manifest = currentManifest
            };
        }

        private static void WriteHmiCheckReports(InventorySnapshot snapshot, string outDir, string compareDir, List<HmiObjectManifestRecord> cloneManifest, List<HmiObjectManifestRecord> currentManifest, List<HmiObjectDiffRecord> diffs)
        {
            string reportPath = Path.Combine(outDir, "hmi-check-objects.csv");
            WriteCsv(reportPath, HmiObjectDiffHeaders(), diffs.Select(HmiObjectDiffRow));

            string summaryPath = Path.Combine(outDir, "hmi-check-summary.txt");
            WriteHmiCheckSummary(summaryPath, snapshot, outDir, compareDir, cloneManifest, currentManifest, diffs);
        }

        private static void PrintHmiCheckResult(string hmiRoot, string compareDir, string reportPath, string summaryPath, List<HmiObjectDiffRecord> diffs)
        {
            Console.WriteLine("HMI check completed.");
            Console.WriteLine("HMI clone root: " + hmiRoot);
            Console.WriteLine("Current HMI snapshot: " + compareDir);
            PrintHmiDiffCount("HMI unchanged", diffs, "unchanged");
            PrintHmiDiffCount("HMI changed", diffs, "changed");
            PrintHmiDiffCount("HMI added", diffs, "added");
            PrintHmiDiffCount("HMI removed", diffs, "removed");
            PrintHmiDiffCount("HMI moved/renamed", diffs, "moved-or-renamed");
            PrintHmiDiffCount("HMI moved/renamed and changed", diffs, "moved-or-renamed-and-changed");
            PrintHmiDiffCount("HMI export errors", diffs, "export-error");
            PrintHmiDiffCount("HMI parse errors", diffs, "parse-error");
            PrintHmiDiffCount("HMI baseline errors", diffs, "baseline-error");
            Console.WriteLine("HMI object report written to: " + reportPath);
            Console.WriteLine("Summary written to: " + summaryPath);
        }

        private static void SyncHmiClone(InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir)
        {
            Directory.CreateDirectory(outDir);

            string reportPath = Path.Combine(outDir, "hmi-sync-objects.csv");
            string summaryPath = Path.Combine(outDir, "hmi-sync-summary.txt");
            string jsonPath = Path.Combine(outDir, "hmi-sync.json");
            string verificationReportPath = Path.Combine(outDir, "hmi-check-objects.csv");

            if (hmiSnapshot.Targets.Count == 0)
            {
                List<HmiObjectDiffRecord> emptyDiffs = new List<HmiObjectDiffRecord>();
                List<string> emptyBlockers = new List<string>();
                WriteHmiSyncReport(reportPath, emptyDiffs, false, false, false, false);
                WriteHmiSyncSummary(summaryPath, snapshot, hmiSnapshot, outDir, null, "NotPresent", "No HMI targets were found in the current project.", string.Empty, string.Empty, string.Empty, reportPath, verificationReportPath, emptyDiffs, emptyBlockers);
                WriteHmiSyncJson(jsonPath, snapshot, hmiSnapshot, outDir, null, "NotPresent", "No HMI targets were found in the current project.", string.Empty, string.Empty, string.Empty, reportPath, verificationReportPath, emptyDiffs, emptyBlockers);
                Console.WriteLine("HMI sync completed: NotPresent.");
                Console.WriteLine("No HMI targets were found in the current project.");
                Console.WriteLine("Summary written to: " + summaryPath);
                return;
            }

            string hmiRoot = Path.Combine(outDir, "_hmi");
            string metadataDir = Path.Combine(outDir, "_hmi_metadata");
            string cloneManifestPath = Path.Combine(metadataDir, "hmi-objects.csv");
            if (!Directory.Exists(hmiRoot))
            {
                throw new DirectoryNotFoundException("HMI clone root was not found. Run hmi-init-clone first: " + hmiRoot);
            }

            if (!File.Exists(cloneManifestPath))
            {
                throw new FileNotFoundException("HMI clone manifest was not found. Run hmi-init-clone first.", cloneManifestPath);
            }

            HmiCurrentSnapshotRecord currentSnapshot = CreateCurrentHmiSnapshot(hmiSnapshot, outDir);
            List<HmiObjectManifestRecord> cloneManifest = LoadHmiObjectManifest(cloneManifestPath, hmiRoot);
            List<HmiObjectManifestRecord> currentManifest = currentSnapshot.Manifest;
            List<HmiObjectDiffRecord> diffs = BuildHmiObjectDiffs(cloneManifest, currentManifest);
            WriteHmiCheckReports(snapshot, outDir, currentSnapshot.CompareDir, cloneManifest, currentManifest, diffs);

            List<string> blockers = BuildHmiSyncBlockers(currentManifest, diffs);
            bool blocked = blockers.Count > 0;
            bool needsSync = diffs.Any(x => !EqualsIgnoreCase(x.Status, "unchanged"));
            string syncStamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
            string backupDir = string.Empty;
            string stagingDir = string.Empty;

            if (blocked)
            {
                WriteHmiSyncReport(reportPath, diffs, true, needsSync, false, false);
                WriteHmiSyncSummary(summaryPath, snapshot, hmiSnapshot, outDir, currentSnapshot, "Blocked", "Current HMI snapshot has export/parse/missing XML blockers; baseline was not changed.", backupDir, stagingDir, string.Empty, reportPath, verificationReportPath, diffs, blockers);
                WriteHmiSyncJson(jsonPath, snapshot, hmiSnapshot, outDir, currentSnapshot, "Blocked", "Current HMI snapshot has export/parse/missing XML blockers; baseline was not changed.", backupDir, stagingDir, string.Empty, reportPath, verificationReportPath, diffs, blockers);
                PrintHmiSyncResult("Blocked", outDir, currentSnapshot.CompareDir, backupDir, reportPath, summaryPath, diffs, blockers);
                return;
            }

            if (!needsSync)
            {
                WriteHmiSyncReport(reportPath, diffs, false, false, false, false);
                WriteHmiSyncSummary(summaryPath, snapshot, hmiSnapshot, outDir, currentSnapshot, "AlreadySynced", "HMI clone baseline already matches the current TIA HMI snapshot.", backupDir, stagingDir, string.Empty, reportPath, verificationReportPath, diffs, blockers);
                WriteHmiSyncJson(jsonPath, snapshot, hmiSnapshot, outDir, currentSnapshot, "AlreadySynced", "HMI clone baseline already matches the current TIA HMI snapshot.", backupDir, stagingDir, string.Empty, reportPath, verificationReportPath, diffs, blockers);
                PrintHmiSyncResult("AlreadySynced", outDir, currentSnapshot.CompareDir, backupDir, reportPath, summaryPath, diffs, blockers);
                return;
            }

            backupDir = UniquePath(Path.Combine(outDir, "_hmi_sync_backups", "sync-" + syncStamp));
            stagingDir = UniquePath(Path.Combine(outDir, "_hmi_sync_staging", "sync-" + syncStamp));

            try
            {
                AcceptCurrentHmiSnapshotIntoClone(outDir, currentSnapshot, backupDir, stagingDir);
                RefreshLiveHmiCloneMetadata(snapshot, hmiSnapshot, outDir, currentSnapshot.CompareDir, backupDir, "synced");

                string verificationMessage;
                bool verificationClean = VerifyHmiCloneClean(snapshot, hmiSnapshot, outDir, out verificationMessage);
                string verdict = verificationClean ? "Synced" : "SyncedWithVerificationError";
                string message = verificationClean
                    ? "Current HMI snapshot was accepted into CLONE_PROJECT and verification hmi-check is clean."
                    : verificationMessage;

                WriteHmiSyncReport(reportPath, diffs, false, true, true, false);
                WriteHmiSyncSummary(summaryPath, snapshot, hmiSnapshot, outDir, currentSnapshot, verdict, message, backupDir, stagingDir, string.Empty, reportPath, verificationReportPath, diffs, blockers);
                WriteHmiSyncJson(jsonPath, snapshot, hmiSnapshot, outDir, currentSnapshot, verdict, message, backupDir, stagingDir, string.Empty, reportPath, verificationReportPath, diffs, blockers);
                PrintHmiSyncResult(verdict, outDir, currentSnapshot.CompareDir, backupDir, reportPath, summaryPath, diffs, blockers);
            }
            catch (Exception ex)
            {
                string message = "HMI sync failed: " + ex.GetType().Name + ": " + ex.Message;
                WriteHmiSyncReport(reportPath, diffs, false, true, false, true);
                WriteHmiSyncSummary(summaryPath, snapshot, hmiSnapshot, outDir, currentSnapshot, "Error", message, backupDir, stagingDir, string.Empty, reportPath, verificationReportPath, diffs, new List<string> { message });
                WriteHmiSyncJson(jsonPath, snapshot, hmiSnapshot, outDir, currentSnapshot, "Error", message, backupDir, stagingDir, string.Empty, reportPath, verificationReportPath, diffs, new List<string> { message });
                throw;
            }
        }

        private static void WriteHmiSyncReport(string path, List<HmiObjectDiffRecord> diffs, bool blocked, bool needsSync, bool syncCompleted, bool syncError)
        {
            WriteCsv(path, HmiSyncReportHeaders(), diffs.Select(x => HmiSyncReportRow(x, blocked, needsSync, syncCompleted, syncError)));
        }

        private static string[] HmiSyncReportHeaders()
        {
            return new[]
            {
                "CheckStatus", "SyncAction", "SyncStatus", "Kind", "Name", "FolderPath",
                "CloneRelativePath", "CurrentRelativePath", "ClonePath", "CurrentPath", "Message"
            };
        }

        private static string[] HmiSyncReportRow(HmiObjectDiffRecord record, bool blocked, bool needsSync, bool syncCompleted, bool syncError)
        {
            return new[]
            {
                record.Status,
                HmiSyncAction(record.Status),
                HmiSyncRowStatus(record.Status, blocked, needsSync, syncCompleted, syncError),
                record.Kind,
                record.Name,
                record.FolderPath,
                record.CloneRelativePath,
                record.CurrentRelativePath,
                record.ClonePath,
                record.CurrentPath,
                record.Message
            };
        }

        private static string HmiSyncAction(string status)
        {
            if (EqualsIgnoreCase(status, "unchanged"))
            {
                return "skip";
            }

            if (EqualsIgnoreCase(status, "changed"))
            {
                return "update";
            }

            if (EqualsIgnoreCase(status, "added"))
            {
                return "add";
            }

            if (EqualsIgnoreCase(status, "removed"))
            {
                return "remove";
            }

            if (EqualsIgnoreCase(status, "moved-or-renamed"))
            {
                return "move";
            }

            if (EqualsIgnoreCase(status, "moved-or-renamed-and-changed"))
            {
                return "move-update";
            }

            if (EqualsIgnoreCase(status, "baseline-error"))
            {
                return "recover-baseline";
            }

            if (EqualsIgnoreCase(status, "export-error"))
            {
                return "block-current-export-error";
            }

            if (EqualsIgnoreCase(status, "parse-error"))
            {
                return "block-current-parse-error";
            }

            if (EqualsIgnoreCase(status, "missing-xml"))
            {
                return "block-current-missing-xml";
            }

            return "block-unknown-status";
        }

        private static string HmiSyncRowStatus(string status, bool blocked, bool needsSync, bool syncCompleted, bool syncError)
        {
            if (syncError && !EqualsIgnoreCase(status, "unchanged"))
            {
                return "error";
            }

            if (blocked)
            {
                return IsHmiSyncCurrentBlockerStatus(status) || !IsHmiSyncAcceptableStatus(status)
                    ? "blocked"
                    : "skipped";
            }

            if (!needsSync || EqualsIgnoreCase(status, "unchanged"))
            {
                return "skipped";
            }

            return syncCompleted ? "ok" : "pending";
        }

        private static List<string> BuildHmiSyncBlockers(List<HmiObjectManifestRecord> currentManifest, List<HmiObjectDiffRecord> diffs)
        {
            List<string> blockers = new List<string>();
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (HmiObjectManifestRecord record in currentManifest)
            {
                if (EqualsIgnoreCase(record.ExportStatus, "error"))
                {
                    AddUniqueHmiSyncBlocker(blockers, seen, "Current export error: " + HmiManifestDisplayName(record) + " - " + EmptyIfNull(record.ExportMessage));
                }

                if (EqualsIgnoreCase(record.ParseStatus, "error"))
                {
                    AddUniqueHmiSyncBlocker(blockers, seen, "Current parse error: " + HmiManifestDisplayName(record) + " - " + EmptyIfNull(record.ParseMessage));
                }

                if (!HasUsableHmiXml(record))
                {
                    AddUniqueHmiSyncBlocker(blockers, seen, "Current XML is missing or unusable: " + HmiManifestDisplayName(record));
                }
            }

            foreach (HmiObjectDiffRecord diff in diffs)
            {
                if (IsHmiSyncCurrentBlockerStatus(diff.Status))
                {
                    AddUniqueHmiSyncBlocker(blockers, seen, "Current HMI check blocker: " + HmiDiffDisplayName(diff) + " status=" + diff.Status + " - " + EmptyIfNull(diff.Message));
                }
                else if (!IsHmiSyncAcceptableStatus(diff.Status))
                {
                    AddUniqueHmiSyncBlocker(blockers, seen, "Unsupported HMI sync status: " + HmiDiffDisplayName(diff) + " status=" + diff.Status);
                }
            }

            return blockers;
        }

        private static void AddUniqueHmiSyncBlocker(List<string> blockers, HashSet<string> seen, string blocker)
        {
            blocker = EmptyIfNull(blocker);
            if (seen.Add(blocker))
            {
                blockers.Add(blocker);
            }
        }

        private static bool IsHmiSyncAcceptableStatus(string status)
        {
            return EqualsIgnoreCase(status, "unchanged")
                || EqualsIgnoreCase(status, "changed")
                || EqualsIgnoreCase(status, "added")
                || EqualsIgnoreCase(status, "removed")
                || EqualsIgnoreCase(status, "moved-or-renamed")
                || EqualsIgnoreCase(status, "moved-or-renamed-and-changed")
                || EqualsIgnoreCase(status, "baseline-error");
        }

        private static bool IsHmiSyncCurrentBlockerStatus(string status)
        {
            return EqualsIgnoreCase(status, "export-error")
                || EqualsIgnoreCase(status, "parse-error")
                || EqualsIgnoreCase(status, "missing-xml");
        }

        private static string HmiManifestDisplayName(HmiObjectManifestRecord record)
        {
            if (record == null)
            {
                return "<unknown>";
            }

            return FirstNonEmpty(record.Kind, "HMI object") + " " + FirstNonEmpty(record.Name, record.RelativePath, record.TypeName, "<unnamed>");
        }

        private static string HmiDiffDisplayName(HmiObjectDiffRecord diff)
        {
            if (diff == null)
            {
                return "<unknown>";
            }

            return FirstNonEmpty(diff.Kind, "HMI object") + " " + FirstNonEmpty(diff.Name, diff.RelativePath, diff.CurrentRelativePath, diff.CloneRelativePath, "<unnamed>");
        }

        private static void AcceptCurrentHmiSnapshotIntoClone(string outDir, HmiCurrentSnapshotRecord currentSnapshot, string backupDir, string stagingDir)
        {
            EnsurePathInside(stagingDir, outDir);
            EnsurePathInside(backupDir, outDir);
            Directory.CreateDirectory(stagingDir);

            string stagingHmiRoot = Path.Combine(stagingDir, "_hmi");
            string stagingMetadataDir = Path.Combine(stagingDir, "_hmi_metadata");
            EnsurePathInside(stagingHmiRoot, outDir);
            EnsurePathInside(stagingMetadataDir, outDir);

            CopyDirectory(currentSnapshot.HmiRoot, stagingHmiRoot, false);
            CopyDirectory(currentSnapshot.MetadataDir, stagingMetadataDir, false);
            ValidateHmiSyncStaging(outDir, stagingHmiRoot, stagingMetadataDir);
            ReplaceHmiCloneDirectories(outDir, stagingDir, stagingHmiRoot, stagingMetadataDir, backupDir);
        }

        private static void ValidateHmiSyncStaging(string outDir, string stagingHmiRoot, string stagingMetadataDir)
        {
            EnsurePathInside(stagingHmiRoot, outDir);
            EnsurePathInside(stagingMetadataDir, outDir);

            if (!Directory.Exists(stagingHmiRoot))
            {
                throw new DirectoryNotFoundException("HMI sync staging XML root was not found: " + stagingHmiRoot);
            }

            if (!Directory.Exists(Path.Combine(stagingMetadataDir, "digest")))
            {
                throw new DirectoryNotFoundException("HMI sync staging digest directory was not found: " + Path.Combine(stagingMetadataDir, "digest"));
            }

            if (!Directory.Exists(Path.Combine(stagingMetadataDir, "inventory")))
            {
                throw new DirectoryNotFoundException("HMI sync staging inventory directory was not found: " + Path.Combine(stagingMetadataDir, "inventory"));
            }

            string manifestPath = Path.Combine(stagingMetadataDir, "hmi-objects.csv");
            if (!File.Exists(manifestPath))
            {
                throw new FileNotFoundException("HMI sync staging manifest was not found.", manifestPath);
            }
        }

        private static void ReplaceHmiCloneDirectories(string outDir, string stagingDir, string stagingHmiRoot, string stagingMetadataDir, string backupDir)
        {
            string liveHmiRoot = Path.Combine(outDir, "_hmi");
            string liveMetadataDir = Path.Combine(outDir, "_hmi_metadata");
            string backupHmiRoot = Path.Combine(backupDir, "_hmi");
            string backupMetadataDir = Path.Combine(backupDir, "_hmi_metadata");

            EnsurePathInside(liveHmiRoot, outDir);
            EnsurePathInside(liveMetadataDir, outDir);
            EnsurePathInside(stagingDir, outDir);
            EnsurePathInside(stagingHmiRoot, outDir);
            EnsurePathInside(stagingMetadataDir, outDir);
            EnsurePathInside(backupDir, outDir);
            EnsurePathInside(backupHmiRoot, outDir);
            EnsurePathInside(backupMetadataDir, outDir);

            Directory.CreateDirectory(backupDir);

            bool archivedHmi = false;
            bool archivedMetadata = false;
            bool installedHmi = false;
            bool installedMetadata = false;
            try
            {
                Directory.Move(liveHmiRoot, backupHmiRoot);
                archivedHmi = true;
                Directory.Move(liveMetadataDir, backupMetadataDir);
                archivedMetadata = true;
                Directory.Move(stagingHmiRoot, liveHmiRoot);
                installedHmi = true;
                Directory.Move(stagingMetadataDir, liveMetadataDir);
                installedMetadata = true;
            }
            catch
            {
                TryRestoreHmiCloneDirectories(outDir, stagingDir, liveHmiRoot, liveMetadataDir, backupHmiRoot, backupMetadataDir, archivedHmi, archivedMetadata, installedHmi, installedMetadata);
                throw;
            }
        }

        private static void TryRestoreHmiCloneDirectories(string outDir, string stagingDir, string liveHmiRoot, string liveMetadataDir, string backupHmiRoot, string backupMetadataDir, bool archivedHmi, bool archivedMetadata, bool installedHmi, bool installedMetadata)
        {
            try
            {
                if (installedMetadata && Directory.Exists(liveMetadataDir))
                {
                    string failedMetadata = UniquePath(Path.Combine(stagingDir, "_failed_live_hmi_metadata"));
                    EnsurePathInside(failedMetadata, outDir);
                    Directory.Move(liveMetadataDir, failedMetadata);
                }

                if (installedHmi && Directory.Exists(liveHmiRoot))
                {
                    string failedHmi = UniquePath(Path.Combine(stagingDir, "_failed_live_hmi"));
                    EnsurePathInside(failedHmi, outDir);
                    Directory.Move(liveHmiRoot, failedHmi);
                }

                if (archivedMetadata && !Directory.Exists(liveMetadataDir) && Directory.Exists(backupMetadataDir))
                {
                    Directory.Move(backupMetadataDir, liveMetadataDir);
                }

                if (archivedHmi && !Directory.Exists(liveHmiRoot) && Directory.Exists(backupHmiRoot))
                {
                    Directory.Move(backupHmiRoot, liveHmiRoot);
                }
            }
            catch
            {
            }
        }

        private static List<HmiObjectManifestRecord> RefreshLiveHmiCloneMetadata(InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, string sourceCompareDir, string backupDir, string mode)
        {
            string hmiRoot = Path.Combine(outDir, "_hmi");
            string metadataDir = Path.Combine(outDir, "_hmi_metadata");
            string digestDir = Path.Combine(metadataDir, "digest");
            string inventoryDir = Path.Combine(metadataDir, "inventory");

            Directory.CreateDirectory(metadataDir);
            RewriteHmiExportReportFilePaths(Path.Combine(hmiRoot, "hmi-export-report.csv"), Path.Combine(sourceCompareDir, "_hmi"), hmiRoot);
            WriteHmiDigest(hmiRoot, digestDir);
            WriteHmiInventory(hmiSnapshot, inventoryDir);
            List<HmiObjectManifestRecord> manifest = BuildHmiObjectManifest(hmiRoot, digestDir);
            WriteHmiObjectManifest(Path.Combine(metadataDir, "hmi-objects.csv"), manifest);
            WriteHmiCloneBaselineSummary(Path.Combine(metadataDir, "hmi-clone-summary.txt"), snapshot, hmiSnapshot, outDir, hmiRoot, digestDir, inventoryDir, manifest, mode, sourceCompareDir, backupDir);
            return manifest;
        }

        private static void RewriteHmiExportReportFilePaths(string reportPath, string oldHmiRoot, string newHmiRoot)
        {
            if (!File.Exists(reportPath))
            {
                return;
            }

            string[] headers = new[] { "Kind", "TargetPath", "FolderPath", "Name", "TypeName", "FilePath", "Status", "Message" };
            List<Dictionary<string, string>> rows = ReadCsv(reportPath);
            foreach (Dictionary<string, string> row in rows)
            {
                string filePath = GetCsvValue(row, "FilePath");
                if (string.IsNullOrWhiteSpace(filePath))
                {
                    continue;
                }

                string relative = string.Empty;
                if (Path.IsPathRooted(filePath))
                {
                    if (IsPathInside(filePath, oldHmiRoot))
                    {
                        relative = MakeRelativePath(oldHmiRoot, filePath);
                    }
                    else if (IsPathInside(filePath, newHmiRoot))
                    {
                        relative = MakeRelativePath(newHmiRoot, filePath);
                    }
                }
                else
                {
                    relative = NormalizeHmiRelativePath(filePath);
                }

                if (!string.IsNullOrWhiteSpace(relative))
                {
                    row["FilePath"] = Path.Combine(newHmiRoot, relative);
                }
            }

            WriteCsv(reportPath, headers, rows.Select(row => headers.Select(header => GetCsvValue(row, header)).ToArray()));
        }

        private static void WriteHmiCloneBaselineSummary(string path, InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, string hmiRoot, string digestDir, string inventoryDir, List<HmiObjectManifestRecord> manifest, string mode, string sourceCompareDir, string backupDir)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("HMI clone baseline " + FirstNonEmpty(mode, "updated") + " at: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Clone directory: " + outDir);
                writer.WriteLine("HMI XML root: " + hmiRoot);
                writer.WriteLine("HMI digest directory: " + digestDir);
                writer.WriteLine("HMI inventory directory: " + inventoryDir);
                writer.WriteLine("Source compare snapshot: " + EmptyIfNull(sourceCompareDir));
                writer.WriteLine("Backup directory: " + EmptyIfNull(backupDir));
                writer.WriteLine();
                writer.WriteLine("HMI targets: " + hmiSnapshot.Targets.Count);
                writer.WriteLine("HMI objects in manifest: " + manifest.Count);
                WriteStatusCounts(writer, "HMI export", manifest.Select(x => FirstNonEmpty(x.ExportStatus, "unknown")));
                WriteStatusCounts(writer, "HMI parse", manifest.Select(x => FirstNonEmpty(x.ParseStatus, "unknown")));
            }
        }

        private static bool VerifyHmiCloneClean(InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, out string message)
        {
            try
            {
                CheckHmiClone(snapshot, hmiSnapshot, outDir);
                string reportPath = Path.Combine(outDir, "hmi-check-objects.csv");
                List<Dictionary<string, string>> rows = ReadCsvIfExists(reportPath);
                List<Dictionary<string, string>> dirtyRows = rows
                    .Where(x => !EqualsIgnoreCase(GetCsvValue(x, "Status"), "unchanged"))
                    .ToList();
                if (dirtyRows.Count == 0)
                {
                    message = "Verification hmi-check is clean.";
                    return true;
                }

                message = "Verification hmi-check is dirty: " + dirtyRows.Count + " non-unchanged HMI object(s). See " + reportPath + ".";
                return false;
            }
            catch (Exception ex)
            {
                message = "Verification hmi-check failed: " + ex.GetType().Name + ": " + ex.Message;
                return false;
            }
        }

        private static void WriteHmiSyncSummary(string path, InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, HmiCurrentSnapshotRecord currentSnapshot, string verdict, string message, string backupDir, string stagingDir, string verificationMessage, string reportPath, string verificationReportPath, List<HmiObjectDiffRecord> diffs, List<string> blockers)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("HMI clone sync checked at: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Verdict: " + verdict);
                writer.WriteLine("Message: " + message);
                if (!string.IsNullOrWhiteSpace(verificationMessage))
                {
                    writer.WriteLine("Verification message: " + verificationMessage);
                }

                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Clone directory: " + outDir);
                writer.WriteLine("Current HMI snapshot: " + (currentSnapshot == null ? string.Empty : currentSnapshot.CompareDir));
                writer.WriteLine("Backup directory: " + EmptyIfNull(backupDir));
                writer.WriteLine("Staging directory: " + EmptyIfNull(stagingDir));
                writer.WriteLine("Sync report: " + reportPath);
                writer.WriteLine("Verification report: " + verificationReportPath);
                writer.WriteLine();
                writer.WriteLine("HMI targets: " + hmiSnapshot.Targets.Count);
                writer.WriteLine("HMI objects in current snapshot: " + (currentSnapshot == null || currentSnapshot.Manifest == null ? 0 : currentSnapshot.Manifest.Count));
                WriteStatusCounts(writer, "HMI sync check", diffs.Select(x => FirstNonEmpty(x.Status, "unknown")));
                writer.WriteLine();
                writer.WriteLine("Blockers:");
                if (blockers.Count == 0)
                {
                    writer.WriteLine("  none");
                }
                else
                {
                    foreach (string blocker in blockers)
                    {
                        writer.WriteLine("  " + blocker);
                    }
                }
            }
        }

        private static void WriteHmiSyncJson(string path, InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, HmiCurrentSnapshotRecord currentSnapshot, string verdict, string message, string backupDir, string stagingDir, string verificationMessage, string reportPath, string verificationReportPath, List<HmiObjectDiffRecord> diffs, List<string> blockers)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"generatedAt\": " + Json(DateTime.Now.ToString("o")) + ",");
                writer.WriteLine("  \"verdict\": " + Json(verdict) + ",");
                writer.WriteLine("  \"message\": " + Json(message) + ",");
                writer.WriteLine("  \"verificationMessage\": " + Json(verificationMessage) + ",");
                writer.WriteLine("  \"project\": {");
                writer.WriteLine("    \"name\": " + Json(snapshot.ProjectName) + ",");
                writer.WriteLine("    \"path\": " + Json(snapshot.ProjectPath) + ",");
                writer.WriteLine("    \"type\": " + Json(snapshot.ProjectType));
                writer.WriteLine("  },");
                writer.WriteLine("  \"cloneDirectory\": " + Json(outDir) + ",");
                writer.WriteLine("  \"currentSnapshot\": " + Json(currentSnapshot == null ? string.Empty : currentSnapshot.CompareDir) + ",");
                writer.WriteLine("  \"backupDirectory\": " + Json(backupDir) + ",");
                writer.WriteLine("  \"stagingDirectory\": " + Json(stagingDir) + ",");
                writer.WriteLine("  \"syncReport\": " + Json(reportPath) + ",");
                writer.WriteLine("  \"verificationReport\": " + Json(verificationReportPath) + ",");
                writer.WriteLine("  \"targets\": {");
                writer.WriteLine("    \"hmiTargets\": " + hmiSnapshot.Targets.Count + ",");
                writer.WriteLine("    \"hmiScreens\": " + hmiSnapshot.Screens.Count + ",");
                writer.WriteLine("    \"hmiTextLists\": " + hmiSnapshot.TextLists.Count + ",");
                writer.WriteLine("    \"hmiTags\": " + hmiSnapshot.Tags.Count);
                writer.WriteLine("  },");
                writer.WriteLine("  \"counts\": {");
                List<IGrouping<string, HmiObjectDiffRecord>> counts = diffs
                    .GroupBy(x => FirstNonEmpty(x.Status, "unknown"), StringComparer.OrdinalIgnoreCase)
                    .OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                for (int i = 0; i < counts.Count; i++)
                {
                    string comma = i == counts.Count - 1 ? string.Empty : ",";
                    writer.WriteLine("    " + Json(counts[i].Key) + ": " + counts[i].Count() + comma);
                }

                writer.WriteLine("  },");
                writer.WriteLine("  \"blockers\": [");
                for (int i = 0; i < blockers.Count; i++)
                {
                    string comma = i == blockers.Count - 1 ? string.Empty : ",";
                    writer.WriteLine("    " + Json(blockers[i]) + comma);
                }

                writer.WriteLine("  ]");
                writer.WriteLine("}");
            }
        }

        private static void PrintHmiSyncResult(string verdict, string outDir, string compareDir, string backupDir, string reportPath, string summaryPath, List<HmiObjectDiffRecord> diffs, List<string> blockers)
        {
            Console.WriteLine("HMI sync completed: " + verdict);
            Console.WriteLine("Clone directory: " + outDir);
            Console.WriteLine("Current HMI snapshot: " + compareDir);
            Console.WriteLine("Backup directory: " + EmptyIfNull(backupDir));
            PrintHmiDiffCount("HMI unchanged", diffs, "unchanged");
            PrintHmiDiffCount("HMI changed", diffs, "changed");
            PrintHmiDiffCount("HMI added", diffs, "added");
            PrintHmiDiffCount("HMI removed", diffs, "removed");
            PrintHmiDiffCount("HMI moved/renamed", diffs, "moved-or-renamed");
            PrintHmiDiffCount("HMI moved/renamed and changed", diffs, "moved-or-renamed-and-changed");
            PrintHmiDiffCount("HMI baseline errors", diffs, "baseline-error");
            PrintHmiDiffCount("HMI export errors", diffs, "export-error");
            PrintHmiDiffCount("HMI parse errors", diffs, "parse-error");
            PrintHmiDiffCount("HMI missing XML", diffs, "missing-xml");
            Console.WriteLine("Blockers: " + blockers.Count);
            Console.WriteLine("Sync report written to: " + reportPath);
            Console.WriteLine("Summary written to: " + summaryPath);
        }

        private static bool InitializeWorkspace(InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, Options options)
        {
            using (AcquireCloneWorkspaceLock(outDir, "init-workspace"))
            {
                return InitializeWorkspaceLocked(snapshot, hmiSnapshot, outDir, options);
            }
        }

        private static bool InitializeWorkspaceLocked(InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, Options options)
        {
            DateTime startedAt = DateTime.Now;
            List<WorkspaceInitStepRecord> steps = new List<WorkspaceInitStepRecord>();
            List<string> blockers = new List<string>();
            string backupDir = string.Empty;
            string verdict = "Error";
            string message = string.Empty;
            bool fatalError = false;
            bool plcAuthorizationPrepared = false;

            Directory.CreateDirectory(outDir);

            try
            {
                if (WorkspaceHasExistingCloneArtifacts(outDir))
                {
                    if (!options.Force)
                    {
                        verdict = "ExistingWorkspace";
                        message = "Workspace already contains clone artifacts. Run status for diagnostics, or rerun init-workspace with --force to reinitialize local artifacts after backup.";
                        WorkspaceInitStepRecord existingStep = StartWorkspaceInitStep(steps, "workspace-preflight", "Workspace", outDir);
                        FinishWorkspaceInitStep(existingStep, "blocked", message);
                        WriteWorkspaceInitReports(startedAt, verdict, message, snapshot, hmiSnapshot, outDir, backupDir, steps, blockers);
                        PrintWorkspaceInitResult(verdict, outDir, backupDir, steps, blockers);
                        return false;
                    }

                    WorkspaceInitStepRecord backupStep = StartWorkspaceInitStep(steps, "workspace-backup", "Workspace", outDir);
                    backupDir = BackupWorkspaceGeneratedArtifacts(outDir);
                    FinishWorkspaceInitStep(backupStep, "ok", "Existing generated workspace artifacts moved to backup: " + backupDir);
                }

                WorkspaceInitStepRecord inventoryStep = StartWorkspaceInitStep(steps, "inventory", "Project", Path.Combine(outDir, "_inventory"));
                WriteInventory(snapshot, Path.Combine(outDir, "_inventory"));
                FinishWorkspaceInitStep(inventoryStep, "ok", "Project inventory written.");

                bool hasPlc = HasPlcSoftware(snapshot);
                bool plcClean = true;
                if (!hasPlc)
                {
                    WorkspaceInitStepRecord plcMissingStep = StartWorkspaceInitStep(steps, "plc-detect", "PLC", outDir);
                    FinishWorkspaceInitStep(plcMissingStep, "not-present", "No PLC software was found in the current project.");
                }
                else
                {
                    WorkspaceInitStepRecord plcInitStep = StartWorkspaceInitStep(steps, "init-clone", "PLC", outDir);
                    InitializeProjectClone(snapshot, outDir, options);
                    FinishWorkspaceInitStep(plcInitStep, "ok", "PLC clone initialized.");

                    WorkspaceInitStepRecord plcCheckStep = StartWorkspaceInitStep(steps, "check-clone", "PLC", outDir);
                    CheckProjectClone(snapshot, outDir);
                    plcAuthorizationPrepared = true;
                    List<string> plcBlockers = BuildWorkspacePlcBlockers(outDir);
                    if (plcBlockers.Count == 0)
                    {
                        FinishWorkspaceInitStep(plcCheckStep, "ok", "PLC clone check is clean.");
                    }
                    else
                    {
                        plcClean = false;
                        blockers.AddRange(plcBlockers);
                        FinishWorkspaceInitStep(plcCheckStep, "blocked", "PLC clone check has blockers: " + plcBlockers.Count);
                    }
                }

                bool hmiClean = true;
                if (hmiSnapshot.Targets.Count == 0)
                {
                    WorkspaceInitStepRecord hmiMissingStep = StartWorkspaceInitStep(steps, "hmi-detect", "HMI", outDir);
                    FinishWorkspaceInitStep(hmiMissingStep, "not-present", "No HMI targets were found in the current project.");
                }
                else
                {
                    WorkspaceInitStepRecord hmiInitStep = StartWorkspaceInitStep(steps, "hmi-init-clone", "HMI", outDir);
                    InitializeHmiClone(snapshot, hmiSnapshot, outDir, options);
                    FinishWorkspaceInitStep(hmiInitStep, "ok", "HMI clone initialized, including XML export, digest, inventory, and manifest.");

                    WorkspaceInitStepRecord hmiCheckStep = StartWorkspaceInitStep(steps, "hmi-check", "HMI", outDir);
                    CheckHmiClone(snapshot, hmiSnapshot, outDir);
                    List<string> hmiBlockers = BuildWorkspaceHmiBlockers(outDir);
                    if (hmiBlockers.Count == 0)
                    {
                        FinishWorkspaceInitStep(hmiCheckStep, "ok", "HMI clone check is clean.");
                    }
                    else
                    {
                        hmiClean = false;
                        blockers.AddRange(hmiBlockers);
                        FinishWorkspaceInitStep(hmiCheckStep, "blocked", "HMI clone check has blockers: " + hmiBlockers.Count);
                    }
                }

                WorkspaceInitStepRecord statusStep = StartWorkspaceInitStep(steps, "status", "Workspace", outDir);
                if (hasPlc)
                {
                    if (!WriteToolStatus(snapshot, hmiSnapshot, outDir))
                    {
                        throw new InvalidOperationException("PLC status completed without preparing PLC authorization evidence.");
                    }
                    FinishWorkspaceInitStep(statusStep, "ok", "Combined tool status written.");
                }
                else
                {
                    FinishWorkspaceInitStep(statusStep, "skipped", "Combined status currently requires PLC clone support; skipped because no PLC software was found.");
                }

                if (blockers.Count > 0 || !plcClean || !hmiClean)
                {
                    verdict = "Blocked";
                    message = "Workspace was initialized, but one or more checks reported blockers.";
                }
                else if (!hasPlc && hmiSnapshot.Targets.Count == 0)
                {
                    verdict = "Error";
                    message = "Neither PLC software nor HMI targets were found; workspace has no supported engineering layer.";
                    fatalError = true;
                    blockers.Add(message);
                }
                else if (!hasPlc)
                {
                    verdict = "ReadyHmiOnly";
                    message = "Workspace initialized for HMI-only project.";
                }
                else if (hmiSnapshot.Targets.Count == 0)
                {
                    verdict = "ReadyNoHmi";
                    message = "Workspace initialized and PLC baseline is clean. No HMI targets were found.";
                }
                else
                {
                    verdict = "Ready";
                    message = "Workspace initialized and PLC/HMI baselines are clean.";
                }
            }
            catch (Exception ex)
            {
                fatalError = true;
                verdict = "Error";
                message = ex.GetType().Name + ": " + ex.Message;
                blockers.Add(message);
                WorkspaceInitStepRecord current = steps.LastOrDefault(x => string.IsNullOrWhiteSpace(x.FinishedAt));
                if (current != null)
                {
                    FinishWorkspaceInitStep(current, "error", message);
                }
            }

            WriteWorkspaceInitReports(startedAt, verdict, message, snapshot, hmiSnapshot, outDir, backupDir, steps, blockers);
            PrintWorkspaceInitResult(verdict, outDir, backupDir, steps, blockers);

            if (fatalError)
            {
                throw new InvalidOperationException("init-workspace failed: " + message);
            }

            return plcAuthorizationPrepared;
        }

        private static bool HasPlcSoftware(InventorySnapshot snapshot)
        {
            return GetFirstPlcSoftware(snapshot) != null;
        }

        private static WorkspaceInitStepRecord StartWorkspaceInitStep(List<WorkspaceInitStepRecord> steps, string step, string layer, string outputPath)
        {
            WorkspaceInitStepRecord record = new WorkspaceInitStepRecord
            {
                Step = step,
                Layer = layer,
                Status = "running",
                StartedAt = DateTime.Now.ToString("o"),
                FinishedAt = string.Empty,
                OutputPath = outputPath,
                Message = string.Empty
            };
            steps.Add(record);
            return record;
        }

        private static void FinishWorkspaceInitStep(WorkspaceInitStepRecord record, string status, string message)
        {
            record.Status = status;
            record.FinishedAt = DateTime.Now.ToString("o");
            record.Message = message;
        }

        private static bool WorkspaceHasExistingCloneArtifacts(string outDir)
        {
            return Directory.Exists(outDir)
                && new DirectoryInfo(outDir).GetFileSystemInfos()
                    .Any(x => !IsWorkspaceControlFileName(x.Name) && IsWorkspaceCloneArtifactName(x.Name));
        }

        private static string BackupWorkspaceGeneratedArtifacts(string outDir)
        {
            DirectoryInfo directory = new DirectoryInfo(outDir);
            if (!directory.Exists)
            {
                return string.Empty;
            }

            List<FileSystemInfo> unknown = directory.GetFileSystemInfos()
                .Where(x => !IsWorkspaceControlFileName(x.Name) && !IsWorkspaceGeneratedArtifactName(x.Name))
                .ToList();
            if (unknown.Count > 0)
            {
                string first = unknown.Select(x => x.Name).FirstOrDefault();
                throw new InvalidOperationException("Workspace contains unknown top-level file or directory '" + first + "'. Choose another --out directory or move unknown files manually before --force.");
            }

            List<FileSystemInfo> generated = directory.GetFileSystemInfos()
                .Where(x => !IsWorkspaceControlFileName(x.Name)
                    && IsWorkspaceGeneratedArtifactName(x.Name)
                    && !EqualsIgnoreCase(x.Name, "_workspace_init_backups"))
                .ToList();
            if (generated.Count == 0)
            {
                return string.Empty;
            }

            string backupDir = UniquePath(Path.Combine(outDir, "_workspace_init_backups", "init-" + DateTime.Now.ToString("yyyyMMdd-HHmmss")));
            EnsurePathInside(backupDir, outDir);
            Directory.CreateDirectory(backupDir);

            foreach (FileSystemInfo entry in generated)
            {
                EnsurePathInside(entry.FullName, outDir);
                string destination = Path.Combine(backupDir, entry.Name);
                EnsurePathInside(destination, outDir);
                if (Directory.Exists(entry.FullName))
                {
                    Directory.Move(entry.FullName, destination);
                }
                else if (File.Exists(entry.FullName))
                {
                    File.Move(entry.FullName, destination);
                }
            }

            return backupDir;
        }

        private static bool IsWorkspaceCloneArtifactName(string name)
        {
            return IsWorkspaceGeneratedArtifactName(name)
                && !EqualsIgnoreCase(name, "workspace-init-summary.txt")
                && !EqualsIgnoreCase(name, "workspace-init.json")
                && !EqualsIgnoreCase(name, "workspace-init-steps.csv")
                && !EqualsIgnoreCase(name, "_workspace_init_backups");
        }

        private static bool IsWorkspaceGeneratedArtifactName(string name)
        {
            return EqualsIgnoreCase(name, "_root")
                || EqualsIgnoreCase(name, "_metadata")
                || EqualsIgnoreCase(name, "_inventory")
                || EqualsIgnoreCase(name, "_compare")
                || EqualsIgnoreCase(name, "_preflight")
                || EqualsIgnoreCase(name, "_preflight-quarantine")
                || EqualsIgnoreCase(name, "_check-publish")
                || EqualsIgnoreCase(name, "_manifest-publish")
                || EqualsIgnoreCase(name, "_apply-staging")
                || EqualsIgnoreCase(name, "_apply-staging-quarantine")
                || EqualsIgnoreCase(name, "_apply-validation")
                || EqualsIgnoreCase(name, "_apply-validation-quarantine")
                || EqualsIgnoreCase(name, "_apply-validation-cleanup-audit")
                || EqualsIgnoreCase(name, "_apply-backups")
                || EqualsIgnoreCase(name, "_sync-staging")
                || EqualsIgnoreCase(name, "_sync-staging-quarantine")
                || EqualsIgnoreCase(name, "_sync-staging-cleanup-audit")
                || EqualsIgnoreCase(name, "_sync-backups")
                || EqualsIgnoreCase(name, "_hmi")
                || EqualsIgnoreCase(name, "_hmi_metadata")
                || EqualsIgnoreCase(name, "_hmi_compare")
                || EqualsIgnoreCase(name, "_hmi_sync_backups")
                || EqualsIgnoreCase(name, "_hmi_sync_staging")
                || EqualsIgnoreCase(name, "_hmi_preflight")
                || EqualsIgnoreCase(name, "_hmi_project_texts_preflight")
                || EqualsIgnoreCase(name, "_hmi_project_texts_apply")
                || EqualsIgnoreCase(name, "_hmi_import_probe")
                || EqualsIgnoreCase(name, "_workspace_init_backups")
                || EqualsIgnoreCase(name, "project-summary.txt")
                || EqualsIgnoreCase(name, "devices.csv")
                || EqualsIgnoreCase(name, "block-groups.csv")
                || EqualsIgnoreCase(name, "blocks.csv")
                || EqualsIgnoreCase(name, "tag-tables.csv")
                || EqualsIgnoreCase(name, "tags.csv")
                || EqualsIgnoreCase(name, "inventory.json")
                || EqualsIgnoreCase(name, "workspace-init-summary.txt")
                || EqualsIgnoreCase(name, "workspace-init.json")
                || EqualsIgnoreCase(name, "workspace-init-steps.csv")
                || StartsWithIgnoreCase(name, "plc-")
                || StartsWithIgnoreCase(name, "clone-")
                || StartsWithIgnoreCase(name, "sync-")
                || StartsWithIgnoreCase(name, "apply-clone-")
                || StartsWithIgnoreCase(name, "hmi-")
                || StartsWithIgnoreCase(name, "tool-status");
        }

        private static bool IsWorkspaceControlFileName(string name)
        {
            return EqualsIgnoreCase(name, CloneWorkspaceLockFileName)
                || EqualsIgnoreCase(name, CloneCheckAttemptFileName)
                || EqualsIgnoreCase(name, PublicationTransactionFileName);
        }

        private static bool StartsWithIgnoreCase(string value, string prefix)
        {
            return EmptyIfNull(value).StartsWith(prefix, StringComparison.OrdinalIgnoreCase);
        }

        private static List<string> BuildWorkspacePlcBlockers(string outDir)
        {
            List<string> blockers = new List<string>();
            CloneCheckBundleEvidence bundle = LoadAndValidateCloneCheckBundle(outDir);
            List<Dictionary<string, string>> blockRows = bundle.BlockRows;
            List<Dictionary<string, string>> groupRows = bundle.GroupRows;
            List<Dictionary<string, string>> sourceBlockers = bundle.SourceBlockerRows;

            AddWorkspaceBlockerIf(blockers, StatusCount(blockRows, "Status", "changed"), "PLC changed blocks");
            AddWorkspaceBlockerIf(blockers, StatusCount(blockRows, "Status", "added"), "PLC blocks added");
            AddWorkspaceBlockerIf(blockers, StatusCount(blockRows, "Status", "removed"), "PLC blocks removed");
            AddWorkspaceBlockerIf(blockers, StatusCount(blockRows, "Status", "moved-or-renamed"), "PLC blocks moved or renamed");
            AddWorkspaceBlockerIf(blockers, StatusCount(blockRows, "Status", "moved-or-renamed-and-changed"), "PLC blocks moved/renamed and changed");
            AddWorkspaceBlockerIf(blockers, StatusCount(blockRows, "Status", "object-replaced-or-mismatched"), "PLC object replacements or identity mismatches");
            AddWorkspaceBlockerIf(blockers, StatusCount(blockRows, "Status", "object-id-continuity-unproven"), "PLC durable object-ID continuity gaps");
            AddWorkspaceBlockerIf(blockers, StatusCount(blockRows, "Status", "ambiguous-rename-and-renumber"), "PLC ambiguous rename and renumber transitions");
            AddWorkspaceBlockerIf(blockers, StatusCount(blockRows, "Status", "ambiguous-object-correlation"), "PLC ambiguous engineering-object correlations");
            AddWorkspaceBlockerIf(blockers, StatusCount(blockRows, "Status", "export-error"), "PLC export errors");
            AddWorkspaceBlockerIf(blockers, BlockingSourceBlockerCount(blockRows, sourceBlockers), "PLC source blockers");
            AddWorkspaceBlockerIf(blockers, StatusCount(groupRows, "Status", "added"), "PLC block groups added");
            AddWorkspaceBlockerIf(blockers, StatusCount(groupRows, "Status", "removed"), "PLC block groups removed");
            return blockers;
        }

        private static List<string> BuildWorkspaceHmiBlockers(string outDir)
        {
            List<string> blockers = new List<string>();
            List<Dictionary<string, string>> rows = ReadCsvIfExists(Path.Combine(outDir, "hmi-check-objects.csv"));

            AddWorkspaceBlockerIf(blockers, StatusCount(rows, "Status", "changed"), "HMI objects changed");
            AddWorkspaceBlockerIf(blockers, StatusCount(rows, "Status", "added"), "HMI objects added");
            AddWorkspaceBlockerIf(blockers, StatusCount(rows, "Status", "removed"), "HMI objects removed");
            AddWorkspaceBlockerIf(blockers, StatusCount(rows, "Status", "moved-or-renamed"), "HMI objects moved or renamed");
            AddWorkspaceBlockerIf(blockers, StatusCount(rows, "Status", "moved-or-renamed-and-changed"), "HMI objects moved/renamed and changed");
            AddWorkspaceBlockerIf(blockers, StatusCount(rows, "Status", "export-error"), "HMI export errors");
            AddWorkspaceBlockerIf(blockers, StatusCount(rows, "Status", "parse-error"), "HMI parse errors");
            AddWorkspaceBlockerIf(blockers, StatusCount(rows, "Status", "baseline-error"), "HMI baseline errors");
            AddWorkspaceBlockerIf(blockers, StatusCount(rows, "Status", "missing-xml"), "HMI missing XML");
            return blockers;
        }

        private static void AddWorkspaceBlockerIf(List<string> blockers, int count, string label)
        {
            if (count > 0)
            {
                blockers.Add(label + ": " + count);
            }
        }

        private static void WriteWorkspaceInitReports(DateTime startedAt, string verdict, string message, InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, string backupDir, List<WorkspaceInitStepRecord> steps, List<string> blockers)
        {
            Directory.CreateDirectory(outDir);
            string stepsPath = Path.Combine(outDir, "workspace-init-steps.csv");
            WriteCsv(stepsPath,
                new[] { "Step", "Layer", "Status", "StartedAt", "FinishedAt", "OutputPath", "Message" },
                steps.Select(x => new[] { x.Step, x.Layer, x.Status, x.StartedAt, x.FinishedAt, x.OutputPath, x.Message }));

            WriteWorkspaceInitSummary(Path.Combine(outDir, "workspace-init-summary.txt"), startedAt, verdict, message, snapshot, hmiSnapshot, outDir, backupDir, steps, blockers);
            WriteWorkspaceInitJson(Path.Combine(outDir, "workspace-init.json"), startedAt, verdict, message, snapshot, hmiSnapshot, outDir, backupDir, steps, blockers);
        }

        private static void WriteWorkspaceInitSummary(string path, DateTime startedAt, string verdict, string message, InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, string backupDir, List<WorkspaceInitStepRecord> steps, List<string> blockers)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("Workspace initialized at: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Started at: " + startedAt.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Verdict: " + verdict);
                writer.WriteLine("Message: " + message);
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Project type: " + snapshot.ProjectType);
                writer.WriteLine("TIA Openness API: " + _apiDir);
                writer.WriteLine("Clone directory: " + outDir);
                writer.WriteLine("Backup directory: " + EmptyIfNull(backupDir));
                writer.WriteLine();
                writer.WriteLine("Targets:");
                writer.WriteLine("  PLC devices: " + snapshot.Devices.Count);
                writer.WriteLine("  PLC blocks: " + snapshot.Blocks.Count);
                writer.WriteLine("  PLC block groups: " + snapshot.BlockGroups.Count);
                writer.WriteLine("  HMI targets: " + hmiSnapshot.Targets.Count);
                writer.WriteLine("  HMI screens: " + hmiSnapshot.Screens.Count);
                writer.WriteLine("  HMI text lists: " + hmiSnapshot.TextLists.Count);
                writer.WriteLine();
                writer.WriteLine("Steps:");
                foreach (WorkspaceInitStepRecord step in steps)
                {
                    writer.WriteLine("  " + step.Layer + "/" + step.Step + ": " + step.Status + " - " + step.Message);
                }

                writer.WriteLine();
                writer.WriteLine("Reports:");
                writer.WriteLine("  PLC clone check: " + Path.Combine(outDir, "clone-check-summary.txt"));
                writer.WriteLine("  HMI clone check: " + Path.Combine(outDir, "hmi-check-summary.txt"));
                writer.WriteLine("  Tool status: " + Path.Combine(outDir, "tool-status-summary.txt"));
                writer.WriteLine("  Steps CSV: " + Path.Combine(outDir, "workspace-init-steps.csv"));
                writer.WriteLine();
                writer.WriteLine("Blockers:");
                if (blockers.Count == 0)
                {
                    writer.WriteLine("  none");
                }
                else
                {
                    foreach (string blocker in blockers)
                    {
                        writer.WriteLine("  " + blocker);
                    }
                }
            }
        }

        private static void WriteWorkspaceInitJson(string path, DateTime startedAt, string verdict, string message, InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, string backupDir, List<WorkspaceInitStepRecord> steps, List<string> blockers)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"generatedAt\": " + Json(DateTime.Now.ToString("o")) + ",");
                writer.WriteLine("  \"startedAt\": " + Json(startedAt.ToString("o")) + ",");
                writer.WriteLine("  \"verdict\": " + Json(verdict) + ",");
                writer.WriteLine("  \"message\": " + Json(message) + ",");
                writer.WriteLine("  \"project\": {");
                writer.WriteLine("    \"name\": " + Json(snapshot.ProjectName) + ",");
                writer.WriteLine("    \"path\": " + Json(snapshot.ProjectPath) + ",");
                writer.WriteLine("    \"type\": " + Json(snapshot.ProjectType));
                writer.WriteLine("  },");
                writer.WriteLine("  \"tia\": {");
                writer.WriteLine("    \"opennessApiDir\": " + Json(_apiDir));
                writer.WriteLine("  },");
                writer.WriteLine("  \"cloneDirectory\": " + Json(outDir) + ",");
                writer.WriteLine("  \"backupDirectory\": " + Json(backupDir) + ",");
                writer.WriteLine("  \"targets\": {");
                writer.WriteLine("    \"plcDevices\": " + snapshot.Devices.Count + ",");
                writer.WriteLine("    \"plcBlocks\": " + snapshot.Blocks.Count + ",");
                writer.WriteLine("    \"plcBlockGroups\": " + snapshot.BlockGroups.Count + ",");
                writer.WriteLine("    \"hmiTargets\": " + hmiSnapshot.Targets.Count + ",");
                writer.WriteLine("    \"hmiScreens\": " + hmiSnapshot.Screens.Count + ",");
                writer.WriteLine("    \"hmiTextLists\": " + hmiSnapshot.TextLists.Count);
                writer.WriteLine("  },");
                writer.WriteLine("  \"steps\": [");
                for (int i = 0; i < steps.Count; i++)
                {
                    WorkspaceInitStepRecord step = steps[i];
                    writer.WriteLine("    {");
                    writer.WriteLine("      \"step\": " + Json(step.Step) + ",");
                    writer.WriteLine("      \"layer\": " + Json(step.Layer) + ",");
                    writer.WriteLine("      \"status\": " + Json(step.Status) + ",");
                    writer.WriteLine("      \"startedAt\": " + Json(step.StartedAt) + ",");
                    writer.WriteLine("      \"finishedAt\": " + Json(step.FinishedAt) + ",");
                    writer.WriteLine("      \"outputPath\": " + Json(step.OutputPath) + ",");
                    writer.WriteLine("      \"message\": " + Json(step.Message));
                    writer.WriteLine("    }" + (i == steps.Count - 1 ? string.Empty : ","));
                }

                writer.WriteLine("  ],");
                writer.WriteLine("  \"blockers\": [");
                for (int i = 0; i < blockers.Count; i++)
                {
                    writer.WriteLine("    " + Json(blockers[i]) + (i == blockers.Count - 1 ? string.Empty : ","));
                }

                writer.WriteLine("  ],");
                writer.WriteLine("  \"reports\": {");
                writer.WriteLine("    \"summary\": " + Json(Path.Combine(outDir, "workspace-init-summary.txt")) + ",");
                writer.WriteLine("    \"stepsCsv\": " + Json(Path.Combine(outDir, "workspace-init-steps.csv")) + ",");
                writer.WriteLine("    \"plcCheck\": " + Json(Path.Combine(outDir, "clone-check-summary.txt")) + ",");
                writer.WriteLine("    \"hmiCheck\": " + Json(Path.Combine(outDir, "hmi-check-summary.txt")) + ",");
                writer.WriteLine("    \"toolStatus\": " + Json(Path.Combine(outDir, "tool-status-summary.txt")));
                writer.WriteLine("  }");
                writer.WriteLine("}");
            }
        }

        private static void PrintWorkspaceInitResult(string verdict, string outDir, string backupDir, List<WorkspaceInitStepRecord> steps, List<string> blockers)
        {
            Console.WriteLine("Workspace init completed: " + verdict);
            Console.WriteLine("Clone directory: " + outDir);
            Console.WriteLine("Backup directory: " + EmptyIfNull(backupDir));
            Console.WriteLine("Steps: " + steps.Count);
            Console.WriteLine("Blockers: " + blockers.Count);
            Console.WriteLine("Summary written to: " + Path.Combine(outDir, "workspace-init-summary.txt"));
            Console.WriteLine("JSON written to: " + Path.Combine(outDir, "workspace-init.json"));
        }

        private static bool WriteToolStatus(InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir)
        {
            Directory.CreateDirectory(outDir);

            DateTime generatedAt = DateTime.Now;
            List<ToolStatusLayerRecord> layers = new List<ToolStatusLayerRecord>();
            layers.Add(RunPlcToolStatus(snapshot, outDir));
            layers.Add(RunHmiToolStatus(snapshot, hmiSnapshot, outDir));

            bool overallReady = layers.All(x => !EqualsIgnoreCase(x.Status, "blocked") && !EqualsIgnoreCase(x.Status, "error"));
            string summaryPath = Path.Combine(outDir, "tool-status-summary.txt");
            string jsonPath = Path.Combine(outDir, "tool-status.json");

            WriteToolStatusSummary(summaryPath, generatedAt, overallReady, snapshot, hmiSnapshot, outDir, layers);
            WriteToolStatusJson(jsonPath, generatedAt, overallReady, snapshot, hmiSnapshot, outDir, layers);

            Console.WriteLine("Tool status completed.");
            Console.WriteLine("Overall status: " + (overallReady ? "Ready" : "Blocked"));
            foreach (ToolStatusLayerRecord layer in layers)
            {
                Console.WriteLine(layer.Name + ": " + ToolStatusDisplay(layer.Status) + " - " + layer.Message);
            }

            Console.WriteLine("Summary written to: " + summaryPath);
            Console.WriteLine("JSON written to: " + jsonPath);

            ToolStatusLayerRecord plcLayer = layers.First(x => EqualsIgnoreCase(x.Name, "PLC"));
            ThrowIfPlcToolStatusFailed(plcLayer);

            return HasPlcSoftware(snapshot);
        }

        private static ToolStatusLayerRecord RunPlcToolStatus(InventorySnapshot snapshot, string outDir)
        {
            return RunPlcToolStatus(snapshot, outDir, null);
        }

        private static ToolStatusLayerRecord RunPlcToolStatus(InventorySnapshot snapshot, string outDir, Action injectedPlcEvidencePhase)
        {
            ToolStatusLayerRecord layer = NewToolStatusLayer("PLC", "PLC apply");
            layer.ReportPath = Path.Combine(outDir, "clone-check-blocks.csv");
            layer.SummaryPath = Path.Combine(outDir, "clone-check-summary.txt");
            layer.BlockerPath = Path.Combine(outDir, "clone-check-source-blockers.csv");
            AddToolStatusCount(layer, "currentBlocks", snapshot.Blocks.Count);
            AddToolStatusCount(layer, "currentBlockGroups", snapshot.BlockGroups.Count);

            if (!HasPlcSoftware(snapshot))
            {
                layer.Status = "not-present";
                layer.Ready = true;
                layer.ReadyForApply = "not-applicable";
                layer.Message = "No PLC software was found in the current project; no PLC authorization bundle was produced.";
                return layer;
            }

            try
            {
                if (injectedPlcEvidencePhase == null)
                {
                    CheckProjectClone(snapshot, outDir);
                    PopulatePlcToolStatus(layer, snapshot, outDir);
                }
                else
                {
                    injectedPlcEvidencePhase();
                }
            }
            catch (Exception ex)
            {
                layer.Status = "error";
                layer.Ready = false;
                layer.ReadyForApply = "no";
                layer.Message = "PLC clone check failed: " + ex.GetType().Name + ": " + ex.Message;
                layer.Blockers.Add(layer.Message);
                layer.Failure = ex;
            }

            return layer;
        }

        private static void ThrowIfPlcToolStatusFailed(ToolStatusLayerRecord plcLayer)
        {
            if (plcLayer != null && plcLayer.Failure != null)
            {
                throw new InvalidOperationException(
                    "PLC evidence phase failed after tool-status diagnostics were written; clone authorization remains revoked.",
                    plcLayer.Failure);
            }
        }

        private static ToolStatusLayerRecord RunHmiToolStatus(InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir)
        {
            ToolStatusLayerRecord layer = NewToolStatusLayer("HMI", "HMI ProjectTexts apply");
            layer.ReportPath = Path.Combine(outDir, "hmi-check-objects.csv");
            layer.SummaryPath = Path.Combine(outDir, "hmi-check-summary.txt");
            AddToolStatusCount(layer, "currentHmiTargets", hmiSnapshot.Targets.Count);
            AddToolStatusCount(layer, "currentHmiScreens", hmiSnapshot.Screens.Count);
            AddToolStatusCount(layer, "currentHmiTextLists", hmiSnapshot.TextLists.Count);
            AddToolStatusCount(layer, "currentHmiTags", hmiSnapshot.Tags.Count);

            if (hmiSnapshot.Targets.Count == 0)
            {
                layer.Status = "not-present";
                layer.Ready = true;
                layer.ReadyForApply = "not-applicable";
                layer.Message = "No HMI targets were found in the current project.";
                return layer;
            }

            try
            {
                CheckHmiClone(snapshot, hmiSnapshot, outDir);
                PopulateHmiToolStatus(layer, hmiSnapshot, outDir);
            }
            catch (Exception ex)
            {
                layer.Status = "error";
                layer.Ready = false;
                layer.ReadyForApply = "no";
                layer.Message = "HMI clone check failed: " + ex.GetType().Name + ": " + ex.Message;
                layer.Blockers.Add(layer.Message);
            }

            return layer;
        }

        private static ToolStatusLayerRecord NewToolStatusLayer(string name, string readinessTarget)
        {
            return new ToolStatusLayerRecord
            {
                Name = name,
                Status = "unknown",
                Ready = false,
                ReadinessTarget = readinessTarget,
                ReadyForApply = "unknown",
                Message = string.Empty
            };
        }

        private static void PopulatePlcToolStatus(ToolStatusLayerRecord layer, InventorySnapshot snapshot, string outDir)
        {
            string blockReportPath = Path.Combine(outDir, "clone-check-blocks.csv");
            string groupReportPath = Path.Combine(outDir, "clone-check-groups.csv");
            string sourceBlockerReportPath = Path.Combine(outDir, "clone-check-source-blockers.csv");
            CloneCheckBundleEvidence bundle = LoadAndValidateCloneCheckBundle(outDir);
            List<Dictionary<string, string>> blockRows = bundle.BlockRows;
            List<Dictionary<string, string>> groupRows = bundle.GroupRows;
            List<Dictionary<string, string>> sourceBlockerRows = bundle.SourceBlockerRows;

            layer.ReportPath = blockReportPath;
            layer.SummaryPath = Path.Combine(outDir, "clone-check-summary.txt");
            layer.BlockerPath = sourceBlockerReportPath;
            AddToolStatusCount(layer, "reportRows", blockRows.Count);
            AddToolStatusCount(layer, "groupReportRows", groupRows.Count);
            AddToolStatusCountsByStatus(layer, blockRows, "blockStatus", "Status");
            AddToolStatusCountsByStatus(layer, groupRows, "groupStatus", "Status");

            int changed = StatusCount(blockRows, "Status", "changed");
            int added = StatusCount(blockRows, "Status", "added");
            int removed = StatusCount(blockRows, "Status", "removed");
            int moved = StatusCount(blockRows, "Status", "moved-or-renamed");
            int movedChanged = StatusCount(blockRows, "Status", "moved-or-renamed-and-changed");
            int objectMismatches = StatusCount(blockRows, "Status", "object-replaced-or-mismatched");
            int objectIdContinuityUnproven = StatusCount(blockRows, "Status", "object-id-continuity-unproven");
            int ambiguousRenameRenumber = StatusCount(blockRows, "Status", "ambiguous-rename-and-renumber");
            int ambiguousObjectCorrelation = StatusCount(blockRows, "Status", "ambiguous-object-correlation");
            int exportErrors = StatusCount(blockRows, "Status", "export-error");
            int sourceBlockers = BlockingSourceBlockerCount(blockRows, sourceBlockerRows);
            int informationalSourceBlockers = InformationalSourceBlockerCount(blockRows);
            int groupAdded = StatusCount(groupRows, "Status", "added");
            int groupRemoved = StatusCount(groupRows, "Status", "removed");
            int dirtyRows = changed + added + removed + moved + movedChanged + objectMismatches + objectIdContinuityUnproven + ambiguousRenameRenumber + ambiguousObjectCorrelation + exportErrors + sourceBlockers + groupAdded + groupRemoved;

            AddToolStatusCount(layer, "dirtyRows", dirtyRows);
            AddToolStatusCount(layer, "sourceBlockers", sourceBlockers);
            AddToolStatusCount(layer, "informationalSourceBlockers", informationalSourceBlockers);
            AddToolStatusBlockerIf(layer, changed, "PLC changed blocks");
            AddToolStatusBlockerIf(layer, added, "PLC blocks added in TIA");
            AddToolStatusBlockerIf(layer, removed, "PLC blocks removed from TIA");
            AddToolStatusBlockerIf(layer, moved, "PLC blocks moved or renamed");
            AddToolStatusBlockerIf(layer, movedChanged, "PLC blocks moved/renamed and changed");
            AddToolStatusBlockerIf(layer, objectMismatches, "PLC object replacements or identity mismatches");
            AddToolStatusBlockerIf(layer, objectIdContinuityUnproven, "PLC durable object-ID continuity gaps");
            AddToolStatusBlockerIf(layer, ambiguousRenameRenumber, "PLC ambiguous rename and renumber transitions");
            AddToolStatusBlockerIf(layer, ambiguousObjectCorrelation, "PLC ambiguous engineering-object correlations");
            AddToolStatusBlockerIf(layer, exportErrors, "PLC source export errors");
            AddToolStatusBlockerIf(layer, sourceBlockers, "PLC source blockers");
            AddToolStatusBlockerIf(layer, groupAdded, "PLC block groups added in TIA");
            AddToolStatusBlockerIf(layer, groupRemoved, "PLC block groups removed from TIA");

            layer.Ready = dirtyRows == 0;
            layer.Status = layer.Ready ? "ready" : "blocked";
            layer.ReadyForApply = layer.Ready ? "yes" : "no";
            layer.Message = layer.Ready
                ? "PLC clone baseline is clean."
                : "PLC clone baseline is dirty; resolve blockers before apply-clone.";
        }

        private static void PopulateHmiToolStatus(ToolStatusLayerRecord layer, HmiInventorySnapshot hmiSnapshot, string outDir)
        {
            string reportPath = Path.Combine(outDir, "hmi-check-objects.csv");
            List<Dictionary<string, string>> rows = ReadCsvIfExists(reportPath);

            layer.ReportPath = reportPath;
            layer.SummaryPath = Path.Combine(outDir, "hmi-check-summary.txt");
            AddToolStatusCount(layer, "reportRows", rows.Count);
            AddToolStatusCountsByStatus(layer, rows, "objectStatus", "Status");

            int changed = StatusCount(rows, "Status", "changed");
            int added = StatusCount(rows, "Status", "added");
            int removed = StatusCount(rows, "Status", "removed");
            int moved = StatusCount(rows, "Status", "moved-or-renamed");
            int movedChanged = StatusCount(rows, "Status", "moved-or-renamed-and-changed");
            int exportErrors = StatusCount(rows, "Status", "export-error");
            int parseErrors = StatusCount(rows, "Status", "parse-error");
            int baselineErrors = StatusCount(rows, "Status", "baseline-error");
            int missingXml = StatusCount(rows, "Status", "missing-xml");
            int dirtyRows = changed + added + removed + moved + movedChanged + exportErrors + parseErrors + baselineErrors + missingXml;

            AddToolStatusCount(layer, "dirtyRows", dirtyRows);
            AddToolStatusBlockerIf(layer, changed, "HMI objects changed");
            AddToolStatusBlockerIf(layer, added, "HMI objects added in TIA");
            AddToolStatusBlockerIf(layer, removed, "HMI objects removed from TIA");
            AddToolStatusBlockerIf(layer, moved, "HMI objects moved or renamed");
            AddToolStatusBlockerIf(layer, movedChanged, "HMI objects moved/renamed and changed");
            AddToolStatusBlockerIf(layer, exportErrors, "HMI export errors");
            AddToolStatusBlockerIf(layer, parseErrors, "HMI XML parse errors");
            AddToolStatusBlockerIf(layer, baselineErrors, "HMI baseline errors");
            AddToolStatusBlockerIf(layer, missingXml, "HMI XML missing or unusable");

            layer.Ready = dirtyRows == 0;
            layer.Status = layer.Ready ? "ready" : "blocked";
            layer.ReadyForApply = layer.Ready ? "yes" : "no";
            layer.Message = layer.Ready
                ? "HMI clone baseline is clean; ProjectTexts apply can enter patch-specific preflight gates."
                : "HMI clone baseline is dirty; accept/sync intended HMI changes before ProjectTexts apply.";
        }

        private static void WriteToolStatusSummary(string path, DateTime generatedAt, bool overallReady, InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, List<ToolStatusLayerRecord> layers)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("Tool status generated at: " + generatedAt.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Overall: " + (overallReady ? "Ready" : "Blocked"));
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Project type: " + snapshot.ProjectType);
                writer.WriteLine("TIA Openness API: " + _apiDir);
                writer.WriteLine("Clone directory: " + outDir);
                writer.WriteLine();
                writer.WriteLine("Targets:");
                writer.WriteLine("  PLC devices: " + snapshot.Devices.Count);
                writer.WriteLine("  PLC blocks: " + snapshot.Blocks.Count);
                writer.WriteLine("  PLC block groups: " + snapshot.BlockGroups.Count);
                writer.WriteLine("  HMI targets: " + hmiSnapshot.Targets.Count);
                writer.WriteLine("  HMI screens: " + hmiSnapshot.Screens.Count);
                writer.WriteLine("  HMI text lists: " + hmiSnapshot.TextLists.Count);
                writer.WriteLine();

                foreach (ToolStatusLayerRecord layer in layers)
                {
                    WriteToolStatusLayerSummary(writer, layer);
                    writer.WriteLine();
                }

                writer.WriteLine("Current blockers:");
                List<string> blockers = layers.SelectMany(x => x.Blockers.Select(y => x.Name + ": " + y)).ToList();
                if (blockers.Count == 0)
                {
                    writer.WriteLine("  none");
                }
                else
                {
                    foreach (string blocker in blockers)
                    {
                        writer.WriteLine("  " + blocker);
                    }
                }
            }
        }

        private static void WriteToolStatusLayerSummary(StreamWriter writer, ToolStatusLayerRecord layer)
        {
            writer.WriteLine(layer.Name + ":");
            writer.WriteLine("  Status: " + ToolStatusDisplay(layer.Status));
            writer.WriteLine("  Ready for " + layer.ReadinessTarget + ": " + layer.ReadyForApply);
            writer.WriteLine("  Message: " + layer.Message);
            writer.WriteLine("  Dirty rows: " + ToolStatusCount(layer, "dirtyRows"));
            if (ToolStatusCount(layer, "sourceBlockers") > 0)
            {
                writer.WriteLine("  Source blockers: " + ToolStatusCount(layer, "sourceBlockers"));
            }

            if (ToolStatusCount(layer, "informationalSourceBlockers") > 0)
            {
                writer.WriteLine("  Informational source blockers (non-blocking): " + ToolStatusCount(layer, "informationalSourceBlockers"));
            }

            writer.WriteLine("  Report: " + EmptyIfNull(layer.ReportPath));
            if (!string.IsNullOrWhiteSpace(layer.BlockerPath))
            {
                writer.WriteLine("  Blockers report: " + layer.BlockerPath);
            }

            writer.WriteLine("  Summary: " + EmptyIfNull(layer.SummaryPath));
            writer.WriteLine("  Counts:");
            foreach (KeyValuePair<string, int> pair in layer.Counts.OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase))
            {
                writer.WriteLine("    " + pair.Key + ": " + pair.Value);
            }
        }

        private static void WriteToolStatusJson(string path, DateTime generatedAt, bool overallReady, InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, List<ToolStatusLayerRecord> layers)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"generatedAt\": " + Json(generatedAt.ToString("o")) + ",");
                writer.WriteLine("  \"overallStatus\": " + Json(overallReady ? "ready" : "blocked") + ",");
                writer.WriteLine("  \"project\": {");
                writer.WriteLine("    \"name\": " + Json(snapshot.ProjectName) + ",");
                writer.WriteLine("    \"path\": " + Json(snapshot.ProjectPath) + ",");
                writer.WriteLine("    \"type\": " + Json(snapshot.ProjectType));
                writer.WriteLine("  },");
                writer.WriteLine("  \"tia\": {");
                writer.WriteLine("    \"opennessApiDir\": " + Json(_apiDir));
                writer.WriteLine("  },");
                writer.WriteLine("  \"cloneDirectory\": " + Json(outDir) + ",");
                writer.WriteLine("  \"targets\": {");
                writer.WriteLine("    \"plcDevices\": " + snapshot.Devices.Count + ",");
                writer.WriteLine("    \"plcBlocks\": " + snapshot.Blocks.Count + ",");
                writer.WriteLine("    \"plcBlockGroups\": " + snapshot.BlockGroups.Count + ",");
                writer.WriteLine("    \"hmiTargets\": " + hmiSnapshot.Targets.Count + ",");
                writer.WriteLine("    \"hmiScreens\": " + hmiSnapshot.Screens.Count + ",");
                writer.WriteLine("    \"hmiTextLists\": " + hmiSnapshot.TextLists.Count);
                writer.WriteLine("  },");
                writer.WriteLine("  \"layers\": [");
                for (int i = 0; i < layers.Count; i++)
                {
                    WriteToolStatusLayerJson(writer, layers[i], i < layers.Count - 1);
                }

                writer.WriteLine("  ]");
                writer.WriteLine("}");
            }
        }

        private static void WriteToolStatusLayerJson(StreamWriter writer, ToolStatusLayerRecord layer, bool trailingComma)
        {
            writer.WriteLine("    {");
            writer.WriteLine("      \"name\": " + Json(layer.Name) + ",");
            writer.WriteLine("      \"status\": " + Json(layer.Status) + ",");
            writer.WriteLine("      \"ready\": " + (layer.Ready ? "true" : "false") + ",");
            writer.WriteLine("      \"readinessTarget\": " + Json(layer.ReadinessTarget) + ",");
            writer.WriteLine("      \"readyForApply\": " + Json(layer.ReadyForApply) + ",");
            writer.WriteLine("      \"message\": " + Json(layer.Message) + ",");
            writer.WriteLine("      \"reportPath\": " + Json(layer.ReportPath) + ",");
            writer.WriteLine("      \"summaryPath\": " + Json(layer.SummaryPath) + ",");
            writer.WriteLine("      \"blockerPath\": " + Json(layer.BlockerPath) + ",");
            writer.WriteLine("      \"counts\": {");
            List<KeyValuePair<string, int>> counts = layer.Counts.OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase).ToList();
            for (int i = 0; i < counts.Count; i++)
            {
                string comma = i == counts.Count - 1 ? string.Empty : ",";
                writer.WriteLine("        " + Json(counts[i].Key) + ": " + counts[i].Value + comma);
            }

            writer.WriteLine("      },");
            writer.WriteLine("      \"blockers\": [");
            for (int i = 0; i < layer.Blockers.Count; i++)
            {
                string comma = i == layer.Blockers.Count - 1 ? string.Empty : ",";
                writer.WriteLine("        " + Json(layer.Blockers[i]) + comma);
            }

            writer.WriteLine("      ]");
            writer.WriteLine("    }" + (trailingComma ? "," : string.Empty));
        }

        private static List<Dictionary<string, string>> ReadCsvIfExists(string path)
        {
            return File.Exists(path)
                ? ReadCsv(path)
                : new List<Dictionary<string, string>>();
        }

        private static void AddToolStatusCountsByStatus(ToolStatusLayerRecord layer, List<Dictionary<string, string>> rows, string prefix, string column)
        {
            foreach (IGrouping<string, Dictionary<string, string>> group in rows
                .Select(x => new { Status = FirstNonEmpty(GetCsvValue(x, column), "unknown"), Row = x })
                .GroupBy(x => x.Status, x => x.Row, StringComparer.OrdinalIgnoreCase)
                .OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase))
            {
                AddToolStatusCount(layer, prefix + "." + group.Key, group.Count());
            }
        }

        private static int StatusCount(List<Dictionary<string, string>> rows, string column, string status)
        {
            return rows.Count(x => EqualsIgnoreCase(GetCsvValue(x, column), status));
        }

        private static int StatusPrefixCount(List<Dictionary<string, string>> rows, string column, string prefix)
        {
            return rows.Count(x => EmptyIfNull(GetCsvValue(x, column)).StartsWith(prefix, StringComparison.OrdinalIgnoreCase));
        }

        private static void AddToolStatusCount(ToolStatusLayerRecord layer, string key, int value)
        {
            int existing;
            if (layer.Counts.TryGetValue(key, out existing))
            {
                layer.Counts[key] = existing + value;
            }
            else
            {
                layer.Counts.Add(key, value);
            }
        }

        private static int ToolStatusCount(ToolStatusLayerRecord layer, string key)
        {
            int value;
            return layer.Counts.TryGetValue(key, out value) ? value : 0;
        }

        private static void AddToolStatusBlockerIf(ToolStatusLayerRecord layer, int count, string label)
        {
            if (count > 0)
            {
                layer.Blockers.Add(label + ": " + count);
            }
        }

        private static string ToolStatusDisplay(string status)
        {
            if (EqualsIgnoreCase(status, "ready"))
            {
                return "Ready";
            }

            if (EqualsIgnoreCase(status, "blocked"))
            {
                return "Blocked";
            }

            if (EqualsIgnoreCase(status, "error"))
            {
                return "Error";
            }

            if (EqualsIgnoreCase(status, "not-present"))
            {
                return "Not present";
            }

            return FirstNonEmpty(status, "Unknown");
        }

        private static List<HmiObjectManifestRecord> BuildHmiObjectManifest(string hmiRoot, string digestDir)
        {
            string reportPath = Path.Combine(hmiRoot, "hmi-export-report.csv");
            string digestPath = Path.Combine(digestDir, "hmi-xml-files.csv");
            Dictionary<string, Dictionary<string, string>> digestByRelative = new Dictionary<string, Dictionary<string, string>>(StringComparer.OrdinalIgnoreCase);
            if (File.Exists(digestPath))
            {
                foreach (Dictionary<string, string> row in ReadCsv(digestPath))
                {
                    string relative = NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath"));
                    if (!string.IsNullOrWhiteSpace(relative) && !digestByRelative.ContainsKey(relative))
                    {
                        digestByRelative.Add(relative, row);
                    }
                }
            }

            List<HmiObjectManifestRecord> result = new List<HmiObjectManifestRecord>();
            HashSet<string> seenRelativePaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (File.Exists(reportPath))
            {
                foreach (Dictionary<string, string> row in ReadCsv(reportPath))
                {
                    string filePath = ResolveExportReportFilePath(hmiRoot, GetCsvValue(row, "FilePath"));
                    string relative = NormalizeHmiRelativePath(RelativePathUnder(hmiRoot, filePath));
                    Dictionary<string, string> digest = null;
                    digestByRelative.TryGetValue(relative, out digest);
                    seenRelativePaths.Add(relative);

                    result.Add(new HmiObjectManifestRecord
                    {
                        Kind = FirstNonEmpty(GetCsvValue(row, "Kind"), GetCsvValue(digest, "Kind"), InferHmiKindFromRelativePath(relative)),
                        TargetPath = GetCsvValue(row, "TargetPath"),
                        FolderPath = GetCsvValue(row, "FolderPath"),
                        Name = FirstNonEmpty(GetCsvValue(row, "Name"), GetCsvValue(digest, "Name")),
                        TypeName = FirstNonEmpty(GetCsvValue(row, "TypeName"), GetCsvValue(digest, "TypeName")),
                        RelativePath = relative,
                        FilePath = filePath,
                        Length = FirstNonEmpty(GetCsvValue(digest, "Length"), File.Exists(filePath) ? Convert.ToString(new FileInfo(filePath).Length) : string.Empty),
                        Sha256 = FirstNonEmpty(GetCsvValue(digest, "Sha256"), File.Exists(filePath) ? ComputeFileSha256(filePath) : string.Empty),
                        ComparableSha256 = File.Exists(filePath) ? ComputeHmiComparableXmlSha256(filePath) : string.Empty,
                        ExportStatus = GetCsvValue(row, "Status"),
                        ExportMessage = GetCsvValue(row, "Message"),
                        ParseStatus = GetCsvValue(digest, "ParseStatus"),
                        ParseMessage = GetCsvValue(digest, "Message"),
                        ObjectElement = GetCsvValue(digest, "ObjectElement"),
                        ObjectId = GetCsvValue(digest, "ObjectId")
                    });
                }
            }

            foreach (Dictionary<string, string> digest in digestByRelative.Values.OrderBy(x => GetCsvValue(x, "RelativePath"), StringComparer.OrdinalIgnoreCase))
            {
                string relative = NormalizeHmiRelativePath(GetCsvValue(digest, "RelativePath"));
                if (seenRelativePaths.Contains(relative))
                {
                    continue;
                }

                string filePath = Path.Combine(hmiRoot, relative);
                result.Add(new HmiObjectManifestRecord
                {
                    Kind = FirstNonEmpty(GetCsvValue(digest, "Kind"), InferHmiKindFromRelativePath(relative)),
                    Name = GetCsvValue(digest, "Name"),
                    TypeName = GetCsvValue(digest, "TypeName"),
                    RelativePath = relative,
                    FilePath = filePath,
                    Length = GetCsvValue(digest, "Length"),
                    Sha256 = GetCsvValue(digest, "Sha256"),
                    ComparableSha256 = File.Exists(filePath) ? ComputeHmiComparableXmlSha256(filePath) : string.Empty,
                    ExportStatus = "untracked-xml",
                    ExportMessage = "XML file exists but is not listed in hmi-export-report.csv.",
                    ParseStatus = GetCsvValue(digest, "ParseStatus"),
                    ParseMessage = GetCsvValue(digest, "Message"),
                    ObjectElement = GetCsvValue(digest, "ObjectElement"),
                    ObjectId = GetCsvValue(digest, "ObjectId")
                });
            }

            return result
                .OrderBy(x => x.Kind, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.FolderPath, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.Name, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.RelativePath, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static string ResolveExportReportFilePath(string hmiRoot, string filePath)
        {
            if (string.IsNullOrWhiteSpace(filePath))
            {
                return string.Empty;
            }

            return Path.IsPathRooted(filePath)
                ? Path.GetFullPath(filePath)
                : Path.GetFullPath(Path.Combine(hmiRoot, filePath));
        }

        private static string NormalizeHmiRelativePath(string path)
        {
            return EmptyIfNull(path)
                .Replace(Path.AltDirectorySeparatorChar, Path.DirectorySeparatorChar)
                .TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        }

        private static bool HasUsableHmiXml(HmiObjectManifestRecord record)
        {
            return record != null && (!string.IsNullOrWhiteSpace(record.Sha256) || !string.IsNullOrWhiteSpace(record.ComparableSha256));
        }

        private static string ComputeHmiComparableXmlSha256(string filePath)
        {
            if (string.IsNullOrWhiteSpace(filePath) || !File.Exists(filePath))
            {
                return string.Empty;
            }

            try
            {
                XmlDocument document = LoadXmlDocument(filePath);
                if (document.DocumentElement != null)
                {
                    foreach (XmlElement child in ChildElements(document.DocumentElement))
                    {
                        if (!EqualsIgnoreCase(child.Name, "DocumentInfo"))
                        {
                            continue;
                        }

                        foreach (XmlElement infoChild in ChildElements(child))
                        {
                            if (EqualsIgnoreCase(infoChild.Name, "Created"))
                            {
                                infoChild.InnerText = string.Empty;
                            }
                        }
                    }
                }

                StringBuilder builder = new StringBuilder();
                XmlWriterSettings settings = new XmlWriterSettings
                {
                    OmitXmlDeclaration = false,
                    Encoding = Encoding.UTF8,
                    NewLineHandling = NewLineHandling.None
                };
                using (XmlWriter writer = XmlWriter.Create(builder, settings))
                {
                    document.Save(writer);
                }

                return ComputeTextSha256(builder.ToString());
            }
            catch
            {
                return ComputeFileSha256(filePath);
            }
        }

        private static string ComputeTextSha256(string text)
        {
            using (SHA256 sha = SHA256.Create())
            {
                return ToHex(sha.ComputeHash(Encoding.UTF8.GetBytes(text ?? string.Empty)));
            }
        }

        private static void WriteHmiObjectManifest(string path, List<HmiObjectManifestRecord> records)
        {
            WriteCsv(path, HmiObjectManifestHeaders(), records.Select(HmiObjectManifestRow));
        }

        private static string[] HmiObjectManifestHeaders()
        {
            return new[]
            {
                "Kind", "TargetPath", "FolderPath", "Name", "TypeName",
                "RelativePath", "FilePath", "Length", "Sha256", "ComparableSha256",
                "ExportStatus", "ExportMessage", "ParseStatus", "ParseMessage",
                "ObjectElement", "ObjectId"
            };
        }

        private static string[] HmiObjectManifestRow(HmiObjectManifestRecord record)
        {
            return new[]
            {
                record.Kind, record.TargetPath, record.FolderPath, record.Name, record.TypeName,
                record.RelativePath, record.FilePath, record.Length, record.Sha256, record.ComparableSha256,
                record.ExportStatus, record.ExportMessage, record.ParseStatus, record.ParseMessage,
                record.ObjectElement, record.ObjectId
            };
        }

        private static List<HmiObjectManifestRecord> LoadHmiObjectManifest(string path, string hmiRoot)
        {
            List<HmiObjectManifestRecord> records = new List<HmiObjectManifestRecord>();
            foreach (Dictionary<string, string> row in ReadCsv(path))
            {
                string relative = NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath"));
                records.Add(new HmiObjectManifestRecord
                {
                    Kind = GetCsvValue(row, "Kind"),
                    TargetPath = GetCsvValue(row, "TargetPath"),
                    FolderPath = GetCsvValue(row, "FolderPath"),
                    Name = GetCsvValue(row, "Name"),
                    TypeName = GetCsvValue(row, "TypeName"),
                    RelativePath = relative,
                    FilePath = FirstNonEmpty(GetCsvValue(row, "FilePath"), string.IsNullOrWhiteSpace(relative) ? string.Empty : Path.Combine(hmiRoot, relative)),
                    Length = GetCsvValue(row, "Length"),
                    Sha256 = GetCsvValue(row, "Sha256"),
                    ComparableSha256 = FirstNonEmpty(GetCsvValue(row, "ComparableSha256"), ComputeHmiComparableXmlSha256(FirstNonEmpty(GetCsvValue(row, "FilePath"), string.IsNullOrWhiteSpace(relative) ? string.Empty : Path.Combine(hmiRoot, relative)))),
                    ExportStatus = GetCsvValue(row, "ExportStatus"),
                    ExportMessage = GetCsvValue(row, "ExportMessage"),
                    ParseStatus = GetCsvValue(row, "ParseStatus"),
                    ParseMessage = GetCsvValue(row, "ParseMessage"),
                    ObjectElement = GetCsvValue(row, "ObjectElement"),
                    ObjectId = GetCsvValue(row, "ObjectId")
                });
            }

            return records;
        }

        private static List<HmiObjectDiffRecord> BuildHmiObjectDiffs(List<HmiObjectManifestRecord> cloneObjects, List<HmiObjectManifestRecord> currentObjects)
        {
            List<HmiObjectDiffRecord> diffs = new List<HmiObjectDiffRecord>();
            Dictionary<string, HmiObjectManifestRecord> cloneByRelative = UniqueHmiManifestByRelativePath(cloneObjects);
            Dictionary<string, HmiObjectManifestRecord> currentByRelative = UniqueHmiManifestByRelativePath(currentObjects);
            Dictionary<string, HmiObjectManifestRecord> cloneByIdentity = UniqueHmiManifestByIdentity(cloneObjects);
            HashSet<string> usedCloneKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (HmiObjectManifestRecord current in currentObjects)
            {
                string currentProblemStatus = HmiObjectProblemStatus(current, false);
                if (!string.IsNullOrWhiteSpace(currentProblemStatus))
                {
                    HmiObjectManifestRecord blockedClone = FindHmiCloneMatchForCurrent(current, cloneByRelative, cloneByIdentity);
                    if (blockedClone != null)
                    {
                        usedCloneKeys.Add(HmiManifestUsageKey(blockedClone));
                    }

                    diffs.Add(HmiObjectDiff(currentProblemStatus, current, blockedClone, HmiObjectProblemMessage(current)));
                    continue;
                }

                HmiObjectManifestRecord clone;
                if (!string.IsNullOrWhiteSpace(current.RelativePath) && cloneByRelative.TryGetValue(current.RelativePath, out clone))
                {
                    usedCloneKeys.Add(HmiManifestUsageKey(clone));
                    string cloneProblemStatus = HmiObjectProblemStatus(clone, true);
                    if (!string.IsNullOrWhiteSpace(cloneProblemStatus))
                    {
                        diffs.Add(HmiObjectDiff("baseline-error", current, clone, HmiObjectProblemMessage(clone)));
                        continue;
                    }

                    bool identical = HmiObjectComparableHash(current) == HmiObjectComparableHash(clone);
                    diffs.Add(HmiObjectDiff(identical ? "unchanged" : "changed", current, clone, identical ? "XML content is identical." : "XML content differs."));
                    continue;
                }

                string identity = HmiObjectIdentity(current);
                if (!string.IsNullOrWhiteSpace(identity) && cloneByIdentity.TryGetValue(identity, out clone))
                {
                    usedCloneKeys.Add(HmiManifestUsageKey(clone));
                    string cloneProblemStatus = HmiObjectProblemStatus(clone, true);
                    if (!string.IsNullOrWhiteSpace(cloneProblemStatus))
                    {
                        diffs.Add(HmiObjectDiff("baseline-error", current, clone, HmiObjectProblemMessage(clone)));
                        continue;
                    }

                    bool identical = HmiObjectComparableHash(current) == HmiObjectComparableHash(clone);
                    string status = identical ? "moved-or-renamed" : "moved-or-renamed-and-changed";
                    string message = "Clone relative path was '" + clone.RelativePath + "', current relative path is '" + current.RelativePath + "'.";
                    if (!identical)
                    {
                        message += " XML content also differs.";
                    }

                    diffs.Add(HmiObjectDiff(status, current, clone, message));
                    continue;
                }

                diffs.Add(HmiObjectDiff("added", current, null, "HMI object exists in current TIA project but not in clone."));
            }

            foreach (HmiObjectManifestRecord clone in cloneObjects)
            {
                if (usedCloneKeys.Contains(HmiManifestUsageKey(clone)))
                {
                    continue;
                }

                if (!string.IsNullOrWhiteSpace(clone.RelativePath) && currentByRelative.ContainsKey(clone.RelativePath))
                {
                    continue;
                }

                diffs.Add(HmiObjectDiff("removed", null, clone, "HMI object exists in clone but not in current TIA project."));
            }

            return diffs
                .OrderBy(x => x.Status, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.Kind, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.FolderPath, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.Name, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.RelativePath, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static Dictionary<string, HmiObjectManifestRecord> UniqueHmiManifestByRelativePath(IEnumerable<HmiObjectManifestRecord> records)
        {
            return records
                .Where(x => !string.IsNullOrWhiteSpace(x.RelativePath))
                .GroupBy(x => x.RelativePath, StringComparer.OrdinalIgnoreCase)
                .Where(x => x.Count() == 1)
                .ToDictionary(x => x.Key, x => x.First(), StringComparer.OrdinalIgnoreCase);
        }

        private static Dictionary<string, HmiObjectManifestRecord> UniqueHmiManifestByIdentity(IEnumerable<HmiObjectManifestRecord> records)
        {
            return records
                .Select(x => new { Key = HmiObjectIdentity(x), Value = x })
                .Where(x => !string.IsNullOrWhiteSpace(x.Key))
                .GroupBy(x => x.Key, StringComparer.OrdinalIgnoreCase)
                .Where(x => x.Count() == 1)
                .ToDictionary(x => x.Key, x => x.First().Value, StringComparer.OrdinalIgnoreCase);
        }

        private static string HmiObjectIdentity(HmiObjectManifestRecord record)
        {
            if (record == null || string.IsNullOrWhiteSpace(record.Kind) || string.IsNullOrWhiteSpace(record.Name))
            {
                return string.Empty;
            }

            return record.Kind + "|" + EmptyIfNull(record.FolderPath) + "|" + record.Name;
        }

        private static string HmiManifestUsageKey(HmiObjectManifestRecord record)
        {
            if (record == null)
            {
                return string.Empty;
            }

            return !string.IsNullOrWhiteSpace(record.RelativePath) ? "path|" + record.RelativePath : "identity|" + HmiObjectIdentity(record);
        }

        private static HmiObjectManifestRecord FindHmiCloneMatchForCurrent(HmiObjectManifestRecord current, Dictionary<string, HmiObjectManifestRecord> cloneByRelative, Dictionary<string, HmiObjectManifestRecord> cloneByIdentity)
        {
            HmiObjectManifestRecord clone;
            if (!string.IsNullOrWhiteSpace(current.RelativePath) && cloneByRelative.TryGetValue(current.RelativePath, out clone))
            {
                return clone;
            }

            string identity = HmiObjectIdentity(current);
            if (!string.IsNullOrWhiteSpace(identity) && cloneByIdentity.TryGetValue(identity, out clone))
            {
                return clone;
            }

            return null;
        }

        private static string HmiObjectProblemStatus(HmiObjectManifestRecord record, bool baseline)
        {
            if (record == null)
            {
                return baseline ? "baseline-missing" : "missing";
            }

            if (EqualsIgnoreCase(record.ExportStatus, "error"))
            {
                return baseline ? "baseline-error" : "export-error";
            }

            if (EqualsIgnoreCase(record.ParseStatus, "error"))
            {
                return baseline ? "baseline-error" : "parse-error";
            }

            if (!HasUsableHmiXml(record))
            {
                return baseline ? "baseline-error" : "missing-xml";
            }

            return string.Empty;
        }

        private static string HmiObjectComparableHash(HmiObjectManifestRecord record)
        {
            return record == null ? string.Empty : FirstNonEmpty(record.ComparableSha256, record.Sha256);
        }

        private static string HmiObjectProblemMessage(HmiObjectManifestRecord record)
        {
            if (record == null)
            {
                return "HMI object is missing.";
            }

            return FirstNonEmpty(record.ExportMessage, record.ParseMessage, "HMI XML is not available for comparison.");
        }

        private static HmiObjectDiffRecord HmiObjectDiff(string status, HmiObjectManifestRecord current, HmiObjectManifestRecord clone, string message)
        {
            HmiObjectManifestRecord source = current ?? clone;
            return new HmiObjectDiffRecord
            {
                Status = status,
                Kind = source == null ? string.Empty : source.Kind,
                TargetPath = source == null ? string.Empty : source.TargetPath,
                FolderPath = source == null ? string.Empty : source.FolderPath,
                Name = source == null ? string.Empty : source.Name,
                TypeName = source == null ? string.Empty : source.TypeName,
                RelativePath = source == null ? string.Empty : source.RelativePath,
                Sha256 = source == null ? string.Empty : source.Sha256,
                ComparableSha256 = source == null ? string.Empty : source.ComparableSha256,
                CloneKind = clone == null ? string.Empty : clone.Kind,
                CloneTargetPath = clone == null ? string.Empty : clone.TargetPath,
                CloneFolderPath = clone == null ? string.Empty : clone.FolderPath,
                CloneName = clone == null ? string.Empty : clone.Name,
                CloneTypeName = clone == null ? string.Empty : clone.TypeName,
                CloneRelativePath = clone == null ? string.Empty : clone.RelativePath,
                ClonePath = clone == null ? string.Empty : clone.FilePath,
                CloneSha256 = clone == null ? string.Empty : clone.Sha256,
                CloneComparableSha256 = clone == null ? string.Empty : clone.ComparableSha256,
                CloneExportStatus = clone == null ? string.Empty : clone.ExportStatus,
                CloneParseStatus = clone == null ? string.Empty : clone.ParseStatus,
                CurrentKind = current == null ? string.Empty : current.Kind,
                CurrentTargetPath = current == null ? string.Empty : current.TargetPath,
                CurrentFolderPath = current == null ? string.Empty : current.FolderPath,
                CurrentName = current == null ? string.Empty : current.Name,
                CurrentTypeName = current == null ? string.Empty : current.TypeName,
                CurrentRelativePath = current == null ? string.Empty : current.RelativePath,
                CurrentPath = current == null ? string.Empty : current.FilePath,
                CurrentSha256 = current == null ? string.Empty : current.Sha256,
                CurrentComparableSha256 = current == null ? string.Empty : current.ComparableSha256,
                CurrentExportStatus = current == null ? string.Empty : current.ExportStatus,
                CurrentParseStatus = current == null ? string.Empty : current.ParseStatus,
                Message = message
            };
        }

        private static string[] HmiObjectDiffHeaders()
        {
            return new[]
            {
                "Status", "Kind", "TargetPath", "FolderPath", "Name", "TypeName", "RelativePath", "Sha256", "ComparableSha256",
                "CloneKind", "CloneTargetPath", "CloneFolderPath", "CloneName", "CloneTypeName", "CloneRelativePath", "ClonePath", "CloneSha256", "CloneComparableSha256", "CloneExportStatus", "CloneParseStatus",
                "CurrentKind", "CurrentTargetPath", "CurrentFolderPath", "CurrentName", "CurrentTypeName", "CurrentRelativePath", "CurrentPath", "CurrentSha256", "CurrentComparableSha256", "CurrentExportStatus", "CurrentParseStatus",
                "Message"
            };
        }

        private static string[] HmiObjectDiffRow(HmiObjectDiffRecord record)
        {
            return new[]
            {
                record.Status, record.Kind, record.TargetPath, record.FolderPath, record.Name, record.TypeName, record.RelativePath, record.Sha256, record.ComparableSha256,
                record.CloneKind, record.CloneTargetPath, record.CloneFolderPath, record.CloneName, record.CloneTypeName, record.CloneRelativePath, record.ClonePath, record.CloneSha256, record.CloneComparableSha256, record.CloneExportStatus, record.CloneParseStatus,
                record.CurrentKind, record.CurrentTargetPath, record.CurrentFolderPath, record.CurrentName, record.CurrentTypeName, record.CurrentRelativePath, record.CurrentPath, record.CurrentSha256, record.CurrentComparableSha256, record.CurrentExportStatus, record.CurrentParseStatus,
                record.Message
            };
        }

        private static void WriteHmiCloneSummary(string path, InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, string hmiRoot, string digestDir, string inventoryDir, List<HmiObjectManifestRecord> manifest, bool force)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("HMI clone initialized at: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Clone directory: " + outDir);
                writer.WriteLine("HMI XML root: " + hmiRoot);
                writer.WriteLine("HMI digest directory: " + digestDir);
                writer.WriteLine("HMI inventory directory: " + inventoryDir);
                writer.WriteLine("Overwrite existing HMI XML files: " + force);
                writer.WriteLine();
                writer.WriteLine("HMI targets: " + hmiSnapshot.Targets.Count);
                writer.WriteLine("HMI objects in manifest: " + manifest.Count);
                WriteStatusCounts(writer, "HMI export", manifest.Select(x => FirstNonEmpty(x.ExportStatus, "unknown")));
                WriteStatusCounts(writer, "HMI parse", manifest.Select(x => FirstNonEmpty(x.ParseStatus, "unknown")));
                writer.WriteLine();
                writer.WriteLine("Layout:");
                writer.WriteLine("  _hmi\\                  HMI XML snapshot");
                writer.WriteLine("  _hmi_metadata\\          HMI manifest, digest, and inventory");
                writer.WriteLine("  _hmi_metadata\\digest\\   Lightweight CSV/JSON/Markdown indexes");
            }
        }

        private static void WriteHmiCheckSummary(string path, InventorySnapshot snapshot, string outDir, string compareDir, List<HmiObjectManifestRecord> cloneManifest, List<HmiObjectManifestRecord> currentManifest, List<HmiObjectDiffRecord> diffs)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("HMI clone checked at: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Clone directory: " + outDir);
                writer.WriteLine("Current HMI snapshot: " + compareDir);
                writer.WriteLine();
                writer.WriteLine("HMI objects in clone manifest: " + cloneManifest.Count);
                writer.WriteLine("HMI objects in current TIA project: " + currentManifest.Count);
                WriteStatusCounts(writer, "HMI object", diffs.Select(x => x.Status));
            }
        }

        private static void PrintHmiDiffCount(string label, List<HmiObjectDiffRecord> diffs, string status)
        {
            Console.WriteLine(label + ": " + diffs.Count(x => EqualsIgnoreCase(x.Status, status)));
        }

        private static void WriteHmiImportCapabilities(InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir)
        {
            Directory.CreateDirectory(outDir);

            List<HmiCapabilityObjectRecord> objects = CollectHmiCapabilityObjects(hmiSnapshot);
            List<HmiCapabilityMethodRecord> methods = new List<HmiCapabilityMethodRecord>();
            List<HmiCapabilityPropertyRecord> properties = new List<HmiCapabilityPropertyRecord>();

            foreach (HmiCapabilityObjectRecord record in objects)
            {
                if (record.Object == null)
                {
                    continue;
                }

                foreach (MethodInfo method in record.Object.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance).Where(x => IsHmiCapabilityMethodName(x.Name)).OrderBy(x => x.Name).ThenBy(x => x.GetParameters().Length))
                {
                    methods.Add(new HmiCapabilityMethodRecord
                    {
                        Category = record.Category,
                        Path = record.Path,
                        Name = record.Name,
                        TypeName = record.TypeName,
                        MethodKind = HmiCapabilityMethodKind(method.Name),
                        MethodName = method.Name,
                        Signature = DescribeMethod(method),
                        ReturnType = TypeDisplayName(method.ReturnType),
                        ParameterTypes = string.Join(" | ", method.GetParameters().Select(x => TypeDisplayName(x.ParameterType)).ToArray()),
                        ParameterNames = string.Join(" | ", method.GetParameters().Select(x => x.Name ?? string.Empty).ToArray()),
                        EnumParameters = HmiCapabilityEnumParameters(method)
                    });
                }

                foreach (PropertyInfo property in record.Object.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance).OrderBy(x => x.Name))
                {
                    properties.Add(new HmiCapabilityPropertyRecord
                    {
                        Category = record.Category,
                        Path = record.Path,
                        Name = record.Name,
                        TypeName = record.TypeName,
                        PropertyName = property.Name,
                        PropertyType = TypeDisplayName(property.PropertyType),
                        CanRead = property.CanRead.ToString(),
                        CanWrite = property.CanWrite.ToString()
                    });
                }
            }

            WriteCsv(Path.Combine(outDir, "hmi-import-objects.csv"),
                new[] { "Category", "Path", "Name", "TypeName", "HasImport", "ImportMethodCount", "HasExport", "ExportMethodCount", "HasCreate", "CreateMethodCount", "HasDelete", "DeleteMethodCount", "RelevantMethodCount", "Message" },
                objects.Select(x => HmiCapabilityObjectRow(x, methods)));

            WriteCsv(Path.Combine(outDir, "hmi-import-methods.csv"),
                new[] { "Category", "Path", "Name", "TypeName", "MethodKind", "MethodName", "Signature", "ReturnType", "ParameterTypes", "ParameterNames", "EnumParameters" },
                methods.Select(x => new[] { x.Category, x.Path, x.Name, x.TypeName, x.MethodKind, x.MethodName, x.Signature, x.ReturnType, x.ParameterTypes, x.ParameterNames, x.EnumParameters }));

            WriteCsv(Path.Combine(outDir, "hmi-import-properties.csv"),
                new[] { "Category", "Path", "Name", "TypeName", "PropertyName", "PropertyType", "CanRead", "CanWrite" },
                properties.Select(x => new[] { x.Category, x.Path, x.Name, x.TypeName, x.PropertyName, x.PropertyType, x.CanRead, x.CanWrite }));

            WriteHmiImportCapabilitiesSummary(Path.Combine(outDir, "hmi-import-summary.txt"), snapshot, hmiSnapshot, objects, methods);
            WriteHmiImportCapabilitiesJson(Path.Combine(outDir, "hmi-import-capabilities.json"), snapshot, hmiSnapshot, objects, methods);
        }

        private static void WriteHmiTextListModelProbe(InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, string outDir, Options options)
        {
            Directory.CreateDirectory(outDir);

            int maxItems = options.MaxItems <= 0 ? 300 : options.MaxItems;
            List<HmiModelObjectRecord> objects = new List<HmiModelObjectRecord>();
            List<HmiModelPropertyRecord> properties = new List<HmiModelPropertyRecord>();
            List<HmiModelAttributeRecord> attributes = new List<HmiModelAttributeRecord>();
            List<HmiModelCompositionRecord> compositions = new List<HmiModelCompositionRecord>();
            List<HmiModelCreationRecord> creations = new List<HmiModelCreationRecord>();
            List<HmiModelInvocationRecord> invocations = new List<HmiModelInvocationRecord>();
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            IEnumerable<HmiNamedRecord> textLists = hmiSnapshot.TextLists;
            if (!string.IsNullOrWhiteSpace(options.Name))
            {
                textLists = textLists.Where(x => EqualsIgnoreCase(x.Name, options.Name));
            }

            foreach (HmiNamedRecord textList in textLists.OrderBy(x => x.Name, StringComparer.OrdinalIgnoreCase))
            {
                string path = CombinePath(textList.TargetPath, "TextLists/" + textList.Name);
                ProbeHmiModelObject(textList.Object, "TextList", path, textList.Name, 0, maxItems, seen, objects, properties, attributes, compositions, creations, invocations);
            }

            WriteCsv(Path.Combine(outDir, "hmi-textlist-model-objects.csv"),
                new[] { "Path", "Role", "Name", "TypeName", "Depth", "EnumerableCount", "Preview", "Message" },
                objects.Select(x => new[] { x.Path, x.Role, x.Name, x.TypeName, x.Depth, x.EnumerableCount, x.Preview, x.Message }));

            WriteCsv(Path.Combine(outDir, "hmi-textlist-model-properties.csv"),
                new[] { "Path", "OwnerTypeName", "PropertyName", "PropertyType", "CanRead", "CanWrite", "ValueTypeName", "ValuePreview", "Message" },
                properties.Select(x => new[] { x.Path, x.OwnerTypeName, x.PropertyName, x.PropertyType, x.CanRead, x.CanWrite, x.ValueTypeName, x.ValuePreview, x.Message }));

            WriteCsv(Path.Combine(outDir, "hmi-textlist-model-attributes.csv"),
                new[] { "Path", "OwnerTypeName", "AttributeName", "AccessMode", "CreateRelevance", "SupportedTypes", "ValueTypeName", "ValuePreview", "ReadStatus", "Message" },
                attributes.Select(x => new[] { x.Path, x.OwnerTypeName, x.AttributeName, x.AccessMode, x.CreateRelevance, x.SupportedTypes, x.ValueTypeName, x.ValuePreview, x.ReadStatus, x.Message }));

            WriteCsv(Path.Combine(outDir, "hmi-textlist-model-compositions.csv"),
                new[] { "Path", "OwnerTypeName", "CompositionName", "CompositionType", "GetStatus", "CompositionObjectType", "Count", "IsReadOnly", "ItemsInspected", "Message" },
                compositions.Select(x => new[] { x.Path, x.OwnerTypeName, x.CompositionName, x.CompositionType, x.GetStatus, x.CompositionObjectType, x.Count, x.IsReadOnly, x.ItemsInspected, x.Message }));

            WriteCsv(Path.Combine(outDir, "hmi-textlist-model-creations.csv"),
                new[] { "Path", "OwnerTypeName", "CompositionName", "CreationType", "ParameterInfos" },
                creations.Select(x => new[] { x.Path, x.OwnerTypeName, x.CompositionName, x.CreationType, x.ParameterInfos }));

            WriteCsv(Path.Combine(outDir, "hmi-textlist-model-invocations.csv"),
                new[] { "Path", "OwnerTypeName", "InvocationName", "InvocationType", "ParameterInfos" },
                invocations.Select(x => new[] { x.Path, x.OwnerTypeName, x.InvocationName, x.InvocationType, x.ParameterInfos }));

            WriteHmiTextListModelProbeSummary(Path.Combine(outDir, "hmi-textlist-model-summary.txt"), snapshot, hmiSnapshot, options, objects, properties, attributes, compositions, creations, invocations);
        }

