                attributes.Select(x => new[] { x.Path, x.OwnerTypeName, x.AttributeName, x.AccessMode, x.CreateRelevance, x.SupportedTypes, x.ValueTypeName, x.ValuePreview, x.ReadStatus, x.Message }));

            WriteCsv(Path.Combine(outDir, "hmi-screen-model-compositions.csv"),
                new[] { "Path", "OwnerTypeName", "CompositionName", "CompositionType", "GetStatus", "CompositionObjectType", "Count", "IsReadOnly", "ItemsInspected", "Message" },
                compositions.Select(x => new[] { x.Path, x.OwnerTypeName, x.CompositionName, x.CompositionType, x.GetStatus, x.CompositionObjectType, x.Count, x.IsReadOnly, x.ItemsInspected, x.Message }));

            WriteCsv(Path.Combine(outDir, "hmi-screen-model-creations.csv"),
                new[] { "Path", "OwnerTypeName", "CompositionName", "CreationType", "ParameterInfos" },
                creations.Select(x => new[] { x.Path, x.OwnerTypeName, x.CompositionName, x.CreationType, x.ParameterInfos }));

            WriteCsv(Path.Combine(outDir, "hmi-screen-model-invocations.csv"),
                new[] { "Path", "OwnerTypeName", "InvocationName", "InvocationType", "ParameterInfos" },
                invocations.Select(x => new[] { x.Path, x.OwnerTypeName, x.InvocationName, x.InvocationType, x.ParameterInfos }));

            WriteHmiScreenModelProbeSummary(Path.Combine(outDir, "hmi-screen-model-summary.txt"), snapshot, hmiSnapshot, options, objects, properties, attributes, compositions, creations, invocations);
        }

        private static void ProbeHmiModelObject(
            object value,
            string role,
            string path,
            string name,
            int depth,
            int maxItems,
            HashSet<string> seen,
            List<HmiModelObjectRecord> objects,
            List<HmiModelPropertyRecord> properties,
            List<HmiModelAttributeRecord> attributes,
            List<HmiModelCompositionRecord> compositions,
            List<HmiModelCreationRecord> creations,
            List<HmiModelInvocationRecord> invocations)
        {
            string typeName = value == null ? string.Empty : value.GetType().FullName;
            string key = NormalizeLogicalPath(path) + "|" + role + "|" + typeName;
            if (!seen.Add(key))
            {
                return;
            }

            objects.Add(new HmiModelObjectRecord
            {
                Path = NormalizeLogicalPath(path),
                Role = EmptyIfNull(role),
                Name = EmptyIfNull(name),
                TypeName = typeName,
                Depth = Convert.ToString(depth),
                EnumerableCount = value == null ? string.Empty : HmiModelEnumerableCount(value, maxItems),
                Preview = HmiModelPreview(value),
                Message = value == null ? "Object was not found." : string.Empty
            });

            if (value == null)
            {
                return;
            }

            AddHmiModelProperties(value, path, properties);
            AddHmiModelAttributes(value, path, attributes);
            AddHmiModelInvocations(value, path, invocations);
            AddHmiModelCompositions(value, path, depth, maxItems, seen, objects, properties, attributes, compositions, creations, invocations);
        }

        private static void AddHmiModelProperties(object value, string path, List<HmiModelPropertyRecord> properties)
        {
            foreach (PropertyInfo property in value.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance).OrderBy(x => x.Name))
            {
                HmiModelPropertyRecord record = new HmiModelPropertyRecord
                {
                    Path = NormalizeLogicalPath(path),
                    OwnerTypeName = value.GetType().FullName,
                    PropertyName = property.Name,
                    PropertyType = TypeDisplayName(property.PropertyType),
                    CanRead = property.CanRead.ToString(),
                    CanWrite = property.CanWrite.ToString()
                };

                if (property.CanRead)
                {
                    try
                    {
                        object propertyValue = property.GetValue(value, null);
                        record.ValueTypeName = propertyValue == null ? string.Empty : propertyValue.GetType().FullName;
                        record.ValuePreview = HmiModelPreview(propertyValue);
                    }
                    catch (Exception ex)
                    {
                        record.Message = ex.GetType().Name + ": " + ex.Message;
                    }
                }

                properties.Add(record);
            }
        }

        private static void AddHmiModelAttributes(object value, string path, List<HmiModelAttributeRecord> attributes)
        {
            foreach (object info in ReadAttributeInfos(value))
            {
                string attributeName = SafeGet(info, "Name");
                HmiModelAttributeRecord record = new HmiModelAttributeRecord
                {
                    Path = NormalizeLogicalPath(path),
                    OwnerTypeName = value.GetType().FullName,
                    AttributeName = attributeName,
                    AccessMode = Convert.ToString(TryGetPropertyValue(info, "AccessMode")),
                    CreateRelevance = Convert.ToString(TryGetPropertyValue(info, "CreateRelevance")),
                    SupportedTypes = FormatTypeList(TryGetPropertyValue(info, "SupportedTypes"))
                };

                try
                {
                    object attributeValue = TryReadAttribute(value, attributeName);
                    record.ValueTypeName = attributeValue == null ? string.Empty : attributeValue.GetType().FullName;
                    record.ValuePreview = HmiModelPreview(attributeValue);
                    record.ReadStatus = "ok";
                }
                catch (Exception ex)
                {
                    record.ReadStatus = "error";
                    record.Message = ex.GetType().Name + ": " + ex.Message;
                }

                attributes.Add(record);
            }
        }

        private static void AddHmiModelCompositions(
            object value,
            string path,
            int depth,
            int maxItems,
            HashSet<string> seen,
            List<HmiModelObjectRecord> objects,
            List<HmiModelPropertyRecord> properties,
            List<HmiModelAttributeRecord> attributes,
            List<HmiModelCompositionRecord> compositions,
            List<HmiModelCreationRecord> creations,
            List<HmiModelInvocationRecord> invocations)
        {
            foreach (object info in ReadEngineeringCompositionInfos(value))
            {
                string compositionName = SafeGet(info, "Name");
                HmiModelCompositionRecord record = new HmiModelCompositionRecord
                {
                    Path = NormalizeLogicalPath(path),
                    OwnerTypeName = value.GetType().FullName,
                    CompositionName = compositionName,
                    CompositionType = TypeDisplayName(TryGetPropertyValue(info, "Type") as Type)
                };

                object composition = null;
                try
                {
                    composition = InvokeEngineeringObjectMethod(value, "GetComposition", new object[] { compositionName });
                    record.GetStatus = composition == null ? "null" : "ok";
                    record.CompositionObjectType = composition == null ? string.Empty : composition.GetType().FullName;
                    record.Count = SafeGet(composition, "Count");
                    record.IsReadOnly = SafeGet(composition, "IsReadOnly");
                }
                catch (Exception ex)
                {
                    record.GetStatus = "error";
                    record.Message = ex.GetType().Name + ": " + ex.Message;
                }

                AddHmiModelCreations(value, path, compositionName, creations);

                int inspected = 0;
                if (composition != null && depth < 4)
                {
                    string compositionPath = CombinePath(path, compositionName);
                    ProbeHmiModelObject(composition, "Composition", compositionPath, compositionName, depth + 1, maxItems, seen, objects, properties, attributes, compositions, creations, invocations);
                    foreach (object item in AsEnumerable(composition).Take(maxItems))
                    {
                        inspected++;
                        string itemName = FirstNonEmpty(SafeGet(item, "Name"), SafeGet(item, "Text"), SafeDescribe(item));
                        ProbeHmiModelObject(item, "CompositionItem", CombinePath(compositionPath, SafeFileName(FirstNonEmpty(itemName, "item-" + inspected.ToString()))), itemName, depth + 2, maxItems, seen, objects, properties, attributes, compositions, creations, invocations);
                    }
                }

                record.ItemsInspected = Convert.ToString(inspected);
                compositions.Add(record);
            }
        }

        private static void AddHmiModelCreations(object value, string path, string compositionName, List<HmiModelCreationRecord> creations)
        {
            foreach (object info in ReadEngineeringCreationInfos(value, compositionName))
            {
                creations.Add(new HmiModelCreationRecord
                {
                    Path = NormalizeLogicalPath(path),
                    OwnerTypeName = value.GetType().FullName,
                    CompositionName = compositionName,
                    CreationType = TypeDisplayName(TryGetPropertyValue(info, "Type") as Type),
                    ParameterInfos = FormatInfoList(TryGetPropertyValue(info, "ParameterInfos"))
                });
            }
        }

        private static void ProbeHmiModelCompositionCandidates(object value, string path, IEnumerable<string> compositionNames, List<HmiModelCompositionRecord> compositions, List<HmiModelCreationRecord> creations)
        {
            if (value == null)
            {
                return;
            }

            foreach (string compositionName in compositionNames.Where(x => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase))
            {
                HmiModelCompositionRecord record = new HmiModelCompositionRecord
                {
                    Path = NormalizeLogicalPath(path),
                    OwnerTypeName = value.GetType().FullName,
                    CompositionName = compositionName,
                    CompositionType = "<candidate>"
                };

                try
                {
                    object composition = InvokeEngineeringObjectMethod(value, "GetComposition", new object[] { compositionName });
                    record.GetStatus = composition == null ? "null" : "ok";
                    record.CompositionObjectType = composition == null ? string.Empty : composition.GetType().FullName;
                    record.Count = SafeGet(composition, "Count");
                    record.IsReadOnly = SafeGet(composition, "IsReadOnly");
                }
                catch (Exception ex)
                {
                    record.GetStatus = "error";
                    record.Message = ex.GetType().Name + ": " + ex.Message;
                }

                int before = creations.Count;
                try
                {
                    AddHmiModelCreations(value, path, compositionName, creations);
                }
                catch (Exception ex)
                {
                    record.Message = FirstNonEmpty(record.Message, ex.GetType().Name + ": " + ex.Message);
                }

                record.ItemsInspected = "candidate; creationInfos=" + (creations.Count - before).ToString();
                compositions.Add(record);
            }
        }

        private static void AddHmiModelInvocations(object value, string path, List<HmiModelInvocationRecord> invocations)
        {
            foreach (object info in ReadEngineeringInvocationInfos(value))
            {
                invocations.Add(new HmiModelInvocationRecord
                {
                    Path = NormalizeLogicalPath(path),
                    OwnerTypeName = value.GetType().FullName,
                    InvocationName = SafeGet(info, "Name"),
                    InvocationType = TypeDisplayName(TryGetPropertyValue(info, "Type") as Type),
                    ParameterInfos = FormatInfoList(TryGetPropertyValue(info, "ParameterInfos"))
                });
            }
        }

        private static IEnumerable<object> ReadAttributeInfos(object value)
        {
            if (value == null)
            {
                yield break;
            }

            MethodInfo method = value.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(x => x.Name == "GetAttributeInfos" && x.GetParameters().Length == 0);
            if (method == null)
            {
                yield break;
            }

            IEnumerable infos = null;
            try
            {
                infos = method.Invoke(value, null) as IEnumerable;
            }
            catch
            {
                yield break;
            }

            foreach (object info in AsEnumerable(infos))
            {
                yield return info;
            }
        }

        private static IEnumerable<object> ReadEngineeringCompositionInfos(object value)
        {
            return AsEnumerable(InvokeEngineeringObjectMethod(value, "GetCompositionInfos", new object[0]));
        }

        private static IEnumerable<object> ReadEngineeringCreationInfos(object value, string compositionName)
        {
            return AsEnumerable(InvokeEngineeringObjectMethod(value, "GetCreationInfos", new object[] { compositionName }));
        }

        private static IEnumerable<object> ReadEngineeringInvocationInfos(object value)
        {
            return AsEnumerable(InvokeEngineeringObjectMethod(value, "GetInvocationInfos", new object[0]));
        }

        private static object InvokeEngineeringObjectMethod(object value, string methodName, object[] arguments)
        {
            if (value == null)
            {
                return null;
            }

            Type interfaceType = TryFindType("Siemens.Engineering.IEngineeringObject");
            if (interfaceType == null || !interfaceType.IsAssignableFrom(value.GetType()))
            {
                return null;
            }

            MethodInfo method = interfaceType.GetMethods().FirstOrDefault(x => x.Name == methodName && x.GetParameters().Length == arguments.Length);
            if (method == null)
            {
                return null;
            }

            try
            {
                return method.Invoke(value, arguments);
            }
            catch (TargetInvocationException ex)
            {
                throw ex.InnerException ?? ex;
            }
        }

        private static string HmiModelEnumerableCount(object value, int maxItems)
        {
            if (value == null || value is string)
            {
                return string.Empty;
            }

            IEnumerable enumerable = value as IEnumerable;
            if (enumerable == null)
            {
                return string.Empty;
            }

            int count = 0;
            foreach (object ignored in enumerable)
            {
                count++;
                if (count > maxItems)
                {
                    return count.ToString() + "+";
                }
            }

            return count.ToString();
        }

        private static string HmiModelPreview(object value)
        {
            if (value == null)
            {
                return string.Empty;
            }

            if (value is string || value.GetType().IsPrimitive || value.GetType().IsEnum || value is decimal)
            {
                return Convert.ToString(value);
            }

            IEnumerable enumerable = value as IEnumerable;
            if (enumerable != null && !(value is string))
            {
                List<string> parts = new List<string>();
                foreach (object item in enumerable)
                {
                    parts.Add(SafeDescribe(item));
                    if (parts.Count >= 5)
                    {
                        break;
                    }
                }

                return "Enumerable[" + string.Join(" | ", parts.ToArray()) + "]";
            }

            return SafeDescribe(value);
        }

        private static string FormatTypeList(object value)
        {
            IEnumerable enumerable = value as IEnumerable;
            if (enumerable == null || value is string)
            {
                Type singleType = value as Type;
                return singleType == null ? Convert.ToString(value) : TypeDisplayName(singleType);
            }

            List<string> names = new List<string>();
            foreach (object item in enumerable)
            {
                Type type = item as Type;
                names.Add(type == null ? Convert.ToString(item) : TypeDisplayName(type));
            }

            return string.Join(" | ", names.ToArray());
        }

        private static string FormatInfoList(object value)
        {
            IEnumerable enumerable = value as IEnumerable;
            if (enumerable == null || value is string)
            {
                return HmiModelPreview(value);
            }

            List<string> parts = new List<string>();
            foreach (object item in enumerable)
            {
                List<string> itemParts = new List<string>();
                foreach (PropertyInfo property in item.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance).OrderBy(x => x.Name))
                {
                    object propertyValue = TryGetPropertyValue(item, property.Name);
                    Type type = propertyValue as Type;
                    itemParts.Add(property.Name + "=" + (type == null ? HmiModelPreview(propertyValue) : TypeDisplayName(type)));
                }

                parts.Add("{" + string.Join(", ", itemParts.ToArray()) + "}");
            }

            return string.Join("; ", parts.ToArray());
        }

        private static void WriteHmiTextListModelProbeSummary(
            string path,
            InventorySnapshot snapshot,
            HmiInventorySnapshot hmiSnapshot,
            Options options,
            List<HmiModelObjectRecord> objects,
            List<HmiModelPropertyRecord> properties,
            List<HmiModelAttributeRecord> attributes,
            List<HmiModelCompositionRecord> compositions,
            List<HmiModelCreationRecord> creations,
            List<HmiModelInvocationRecord> invocations)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("HMI text list object-model probe");
                writer.WriteLine("Generated: " + DateTime.Now.ToString("o"));
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Text list filter: " + FirstNonEmpty(options.Name, "<all>"));
                writer.WriteLine("HMI text lists in inventory: " + hmiSnapshot.TextLists.Count);
                writer.WriteLine("Objects inspected: " + objects.Count);
                writer.WriteLine("Properties inspected: " + properties.Count);
                writer.WriteLine("Attributes inspected: " + attributes.Count);
                writer.WriteLine("Compositions found: " + compositions.Count);
                writer.WriteLine("Creation infos found: " + creations.Count);
                writer.WriteLine("Invocation infos found: " + invocations.Count);
                writer.WriteLine();
                writer.WriteLine("Composition names:");
                foreach (IGrouping<string, HmiModelCompositionRecord> group in compositions.GroupBy(x => x.CompositionName).OrderBy(x => x.Key))
                {
                    writer.WriteLine("  " + group.Key + ": " + group.Count());
                }
            }
        }

        private static void WriteHmiScreenModelProbeSummary(
            string path,
            InventorySnapshot snapshot,
            HmiInventorySnapshot hmiSnapshot,
            Options options,
            List<HmiModelObjectRecord> objects,
            List<HmiModelPropertyRecord> properties,
            List<HmiModelAttributeRecord> attributes,
            List<HmiModelCompositionRecord> compositions,
            List<HmiModelCreationRecord> creations,
            List<HmiModelInvocationRecord> invocations)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("HMI screen object-model probe");
                writer.WriteLine("Generated: " + DateTime.Now.ToString("o"));
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Screen filter: " + FirstNonEmpty(options.Name, "<all>"));
                writer.WriteLine("HMI screens/popups/slideins/templates in inventory: " + hmiSnapshot.Screens.Count);
                writer.WriteLine("Objects inspected: " + objects.Count);
                writer.WriteLine("Properties inspected: " + properties.Count);
                writer.WriteLine("Attributes inspected: " + attributes.Count);
                writer.WriteLine("Compositions found: " + compositions.Count);
                writer.WriteLine("Creation infos found: " + creations.Count);
                writer.WriteLine("Invocation infos found: " + invocations.Count);
                writer.WriteLine();
                writer.WriteLine("Composition names:");
                foreach (IGrouping<string, HmiModelCompositionRecord> group in compositions.GroupBy(x => x.CompositionName).OrderBy(x => x.Key))
                {
                    writer.WriteLine("  " + group.Key + ": " + group.Count());
                }
                writer.WriteLine();
                writer.WriteLine("Creation types:");
                foreach (IGrouping<string, HmiModelCreationRecord> group in creations.GroupBy(x => FirstNonEmpty(x.CompositionName, "<root>")).OrderBy(x => x.Key))
                {
                    writer.WriteLine("  " + group.Key + ": " + group.Count());
                }
            }
        }

        private static void WriteHmiProjectTextsProbe(object project, InventorySnapshot snapshot, string outDir, Options options)
        {
            Directory.CreateDirectory(outDir);

            string sourceCultureName = "en-US";
            string targetCultureName = FirstNonEmpty(options.Language, "ru-RU");
            string xlsxPath = Path.Combine(outDir, "project-texts-" + SafeFileName(sourceCultureName + "-" + targetCultureName) + ".xlsx");
            MethodInfo export = project.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(x =>
                {
                    if (x.Name != "ExportProjectTexts")
                    {
                        return false;
                    }

                    ParameterInfo[] parameters = x.GetParameters();
                    return parameters.Length == 3
                        && parameters[0].ParameterType == typeof(FileInfo)
                        && parameters[1].ParameterType == typeof(CultureInfo)
                        && parameters[2].ParameterType == typeof(CultureInfo);
                });
            if (export == null)
            {
                throw new MissingMethodException(project.GetType().FullName, "ExportProjectTexts(FileInfo, CultureInfo, CultureInfo)");
            }

            export.Invoke(project, new object[]
            {
                new FileInfo(xlsxPath),
                new CultureInfo(sourceCultureName),
                new CultureInfo(targetCultureName)
            });

            WriteHmiProjectTextsProbeSummary(Path.Combine(outDir, "hmi-project-texts-summary.txt"), snapshot, xlsxPath, sourceCultureName, targetCultureName, export);
        }

        private static void WriteHmiProjectTextsProbeSummary(string path, InventorySnapshot snapshot, string xlsxPath, string sourceCultureName, string targetCultureName, MethodInfo export)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("HMI project texts probe");
                writer.WriteLine("Generated: " + DateTime.Now.ToString("o"));
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Mode: read-only ExportProjectTexts only.");
                writer.WriteLine("Source culture: " + sourceCultureName);
                writer.WriteLine("Target culture: " + targetCultureName);
                writer.WriteLine("Export method: " + DescribeMethod(export));
                writer.WriteLine("XLSX: " + xlsxPath);
                writer.WriteLine("XLSX exists: " + File.Exists(xlsxPath));
                writer.WriteLine("XLSX size: " + (File.Exists(xlsxPath) ? new FileInfo(xlsxPath).Length.ToString() : string.Empty));
            }
        }

        private static void HmiImportProbeCopyCommand(object project, Options options)
        {
            string cloneDir = ResolveCloneProjectDirectory(options.OutDir);
            string patchedDir = ResolveRequiredInputDirectory(options.InDir);
            string patchedHmiRoot = Path.Combine(patchedDir, "_hmi");
            string patchedDigestDir = Path.Combine(patchedDir, "_hmi_metadata", "digest");
            string patchedManifestPath = Path.Combine(patchedDir, "_hmi_metadata", "hmi-objects.csv");

            if (!Directory.Exists(patchedHmiRoot))
            {
                throw new DirectoryNotFoundException("Patched HMI XML root was not found: " + patchedHmiRoot);
            }

            if (!Directory.Exists(patchedDigestDir))
            {
                throw new DirectoryNotFoundException("Patched HMI digest directory was not found: " + patchedDigestDir);
            }

            Directory.CreateDirectory(cloneDir);
            string probeDir = Path.Combine(cloneDir, "_hmi_import_probe", "probe-" + DateTime.Now.ToString("yyyyMMdd-HHmmss"));
            string beforeDir = Path.Combine(probeDir, "before");
            string afterDir = Path.Combine(probeDir, "after");
            string beforeHmiRoot = Path.Combine(beforeDir, "_hmi");
            string beforeDigestDir = Path.Combine(beforeDir, "_hmi_metadata", "digest");
            string beforeManifestPath = Path.Combine(beforeDir, "_hmi_metadata", "hmi-objects.csv");
            string afterHmiRoot = Path.Combine(afterDir, "_hmi");
            string afterDigestDir = Path.Combine(afterDir, "_hmi_metadata", "digest");
            string afterManifestPath = Path.Combine(afterDir, "_hmi_metadata", "hmi-objects.csv");

            List<HmiImportProbeTarget> targets = LoadHmiImportProbeTargets(patchedDir, patchedHmiRoot, patchedDigestDir, patchedManifestPath);
            if (targets.Count == 0)
            {
                throw new InvalidOperationException("No changed HMI XML target was found in patched preflight collateral: " + patchedDir);
            }

            InventorySnapshot beforeSnapshot = CollectInventory(project, options.ProjectPath);
            HmiInventorySnapshot beforeHmi = CollectHmiInventory(beforeSnapshot);
            ExportHmiXml(beforeHmi, beforeHmiRoot, true);
            WriteHmiDigest(beforeHmiRoot, beforeDigestDir);
            List<HmiObjectManifestRecord> beforeManifest = BuildHmiObjectManifest(beforeHmiRoot, beforeDigestDir);
            WriteHmiObjectManifest(beforeManifestPath, beforeManifest);

            foreach (HmiImportProbeTarget target in targets)
            {
                HmiObjectManifestRecord before = FindHmiManifestByRelativePath(beforeManifest, target.RelativePath);
                target.BeforeComparableSha256 = before == null ? string.Empty : before.ComparableSha256;
                target.BeforeStatus = before == null ? "missing-before" : FirstNonEmpty(before.ParseStatus, before.ExportStatus);
                ImportHmiPatchedXml(beforeHmi, target);
            }

            if (options.Save)
            {
                SaveProject(project);
            }

            InventorySnapshot afterSnapshot = CollectInventory(project, options.ProjectPath);
            HmiInventorySnapshot afterHmi = CollectHmiInventory(afterSnapshot);
            ExportHmiXml(afterHmi, afterHmiRoot, true);
            WriteHmiDigest(afterHmiRoot, afterDigestDir);
            List<HmiObjectManifestRecord> afterManifest = BuildHmiObjectManifest(afterHmiRoot, afterDigestDir);
            WriteHmiObjectManifest(afterManifestPath, afterManifest);

            List<HmiObjectDiffRecord> objectDiffs = BuildHmiObjectDiffs(beforeManifest, afterManifest);
            HmiExpectedDigestChanges expected = LoadExpectedDigestChangesFromPreflightCollateral(patchedDir);
            List<HmiApplyCollateralDiffRecord> collateral = BuildHmiDigestCollateralDiff(beforeDigestDir, afterDigestDir, expected);
            List<HmiObjectManifestRecord> patchedManifest = File.Exists(patchedManifestPath)
                ? LoadHmiObjectManifest(patchedManifestPath, patchedHmiRoot)
                : BuildHmiObjectManifest(patchedHmiRoot, patchedDigestDir);

            foreach (HmiImportProbeTarget target in targets)
            {
                HmiObjectManifestRecord patched = FindHmiManifestByRelativePath(patchedManifest, target.RelativePath);
                HmiObjectManifestRecord after = FindHmiManifestForProbeTarget(afterManifest, target);
                target.PatchedComparableSha256 = patched == null ? target.PatchedComparableSha256 : patched.ComparableSha256;
                target.AfterComparableSha256 = after == null ? string.Empty : after.ComparableSha256;
                target.AfterRelativePath = after == null ? string.Empty : after.RelativePath;
                target.AfterStatus = after == null ? "missing-after" : FirstNonEmpty(after.ParseStatus, after.ExportStatus);
                target.MatchesPatchedComparableSha256 = !string.IsNullOrWhiteSpace(target.PatchedComparableSha256)
                    && EqualsIgnoreCase(target.AfterComparableSha256, target.PatchedComparableSha256);
                target.RelativePathChanged = after != null && !EqualsIgnoreCase(NormalizeHmiRelativePath(target.RelativePath), NormalizeHmiRelativePath(after.RelativePath));
            }

            string summaryPath = Path.Combine(cloneDir, "hmi-import-probe-copy-summary.txt");
            string targetsPath = Path.Combine(cloneDir, "hmi-import-probe-copy-targets.csv");
            string diffsPath = Path.Combine(cloneDir, "hmi-import-probe-copy-object-diff.csv");
            string collateralPath = Path.Combine(cloneDir, "hmi-import-probe-copy-collateral.csv");

            WriteCsv(targetsPath, HmiImportProbeTargetHeaders(), targets.Select(HmiImportProbeTargetRow));
            WriteCsv(diffsPath, HmiObjectDiffHeaders(), objectDiffs.Select(HmiObjectDiffRow));
            WriteCsv(collateralPath, HmiApplyCollateralDiffHeaders(), collateral.Select(HmiApplyCollateralDiffRow));
            WriteJsonl(Path.Combine(probeDir, "hmi-import-probe-copy-targets.jsonl"), targets.Select(HmiImportProbeTargetJsonRow));
            WriteJsonl(Path.Combine(probeDir, "hmi-import-probe-copy-collateral.jsonl"), collateral.Select(HmiApplyCollateralDiffJsonRow));
            WriteHmiImportProbeCopySummary(summaryPath, options, patchedDir, probeDir, targets, objectDiffs, collateral);

            Console.WriteLine("HMI import probe on copied project");
            Console.WriteLine("  Project copy: " + options.ImportProbeProjectCopyDir);
            Console.WriteLine("  Probe directory: " + probeDir);
            Console.WriteLine("  Import targets: " + targets.Count);
            Console.WriteLine("  Import ok: " + targets.Count(x => EqualsIgnoreCase(x.ImportStatus, "ok")));
            Console.WriteLine("  Matches patched comparable hash: " + targets.Count(x => x.MatchesPatchedComparableSha256));
            Console.WriteLine("  Targets with relative path change: " + targets.Count(x => x.RelativePathChanged));
            Console.WriteLine("  Object diff rows: " + objectDiffs.Count(x => !EqualsIgnoreCase(x.Status, "unchanged")));
            Console.WriteLine("  Collateral rows: " + collateral.Count);
            Console.WriteLine("  Unexpected collateral rows: " + collateral.Count(x => !x.Expected));
            Console.WriteLine("  In-place safety verdict: " + (IsHmiImportProbeAccepted(targets, collateral) ? "accepted" : "rejected"));
            Console.WriteLine("  Summary: " + summaryPath);
            Console.WriteLine("  Targets: " + targetsPath);
            Console.WriteLine("  Collateral: " + collateralPath);
        }

        private static List<HmiImportProbeTarget> LoadHmiImportProbeTargets(string patchedDir, string patchedHmiRoot, string patchedDigestDir, string patchedManifestPath)
        {
            List<HmiImportProbeTarget> targets = new List<HmiImportProbeTarget>();
            string collateralPath = Path.Combine(patchedDir, "hmi-apply-preflight-collateral.jsonl");
            if (!File.Exists(collateralPath))
            {
                throw new FileNotFoundException("Patched preflight collateral JSONL was not found.", collateralPath);
            }

            List<HmiObjectManifestRecord> patchedManifest = File.Exists(patchedManifestPath)
                ? LoadHmiObjectManifest(patchedManifestPath, patchedHmiRoot)
                : BuildHmiObjectManifest(patchedHmiRoot, patchedDigestDir);
            List<Dictionary<string, string>> patchedXmlRows = LoadRequiredCsv(Path.Combine(patchedDigestDir, "hmi-xml-files.csv"), "Patched digest is required for import probe.");

            string planPath = Path.Combine(patchedDir, "hmi-apply-preflight-plan.jsonl");
            if (File.Exists(planPath))
            {
                foreach (Dictionary<string, string> row in ReadFlatJsonlRows(planPath, "hmi import probe preflight plan"))
                {
                    if ((!EqualsIgnoreCase(GetCsvValue(row, "status"), "ready") && !EqualsIgnoreCase(GetCsvValue(row, "status"), "ready-with-warnings"))
                        || !EqualsIgnoreCase(GetCsvValue(row, "localPatchStatus"), "changed"))
                    {
                        continue;
                    }

                    string relativePath = NormalizeHmiRelativePath(GetCsvValue(row, "targetRelativePath"));
                    AddHmiImportProbeTarget(targets, patchedManifest, patchedXmlRows, patchedHmiRoot, relativePath);
                }
            }

            foreach (Dictionary<string, string> row in ReadFlatJsonlRows(collateralPath, "hmi import probe collateral"))
            {
                if (!EqualsIgnoreCase(GetCsvValue(row, "expected"), "True")
                    || !EqualsIgnoreCase(GetCsvValue(row, "report"), "hmi-xml-files.csv")
                    || !EqualsIgnoreCase(GetCsvValue(row, "status"), "changed"))
                {
                    continue;
                }

                string relativePath = NormalizeHmiRelativePath(GetCsvValue(row, "relativePath"));
                AddHmiImportProbeTarget(targets, patchedManifest, patchedXmlRows, patchedHmiRoot, relativePath);
            }

            return targets
                .GroupBy(x => x.RelativePath, StringComparer.OrdinalIgnoreCase)
                .Select(x => x.First())
                .OrderBy(x => x.RelativePath, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static void AddHmiImportProbeTarget(List<HmiImportProbeTarget> targets, List<HmiObjectManifestRecord> patchedManifest, List<Dictionary<string, string>> patchedXmlRows, string patchedHmiRoot, string relativePath)
        {
            if (string.IsNullOrWhiteSpace(relativePath))
            {
                return;
            }

            if (targets.Any(x => EqualsIgnoreCase(NormalizeHmiRelativePath(x.RelativePath), relativePath)))
            {
                return;
            }

            HmiObjectManifestRecord manifest = FindHmiManifestByRelativePath(patchedManifest, relativePath);
            Dictionary<string, string> xmlRow = patchedXmlRows.FirstOrDefault(x => EqualsIgnoreCase(NormalizeHmiRelativePath(GetCsvValue(x, "RelativePath")), relativePath));
            string filePath = Path.Combine(patchedHmiRoot, relativePath);
            if (!File.Exists(filePath))
            {
                throw new FileNotFoundException("Patched XML target file was not found.", filePath);
            }

            targets.Add(new HmiImportProbeTarget
            {
                Kind = FirstNonEmpty(manifest == null ? string.Empty : manifest.Kind, GetCsvValue(xmlRow, "Kind"), InferHmiKindFromRelativePath(relativePath)),
                TargetPath = manifest == null ? string.Empty : manifest.TargetPath,
                FolderPath = manifest == null ? string.Empty : manifest.FolderPath,
                Name = FirstNonEmpty(manifest == null ? string.Empty : manifest.Name, GetCsvValue(xmlRow, "Name"), Path.GetFileNameWithoutExtension(relativePath)),
                TypeName = FirstNonEmpty(manifest == null ? string.Empty : manifest.TypeName, GetCsvValue(xmlRow, "TypeName")),
                RelativePath = relativePath,
                PatchedXmlPath = filePath,
                PatchedComparableSha256 = manifest == null ? string.Empty : manifest.ComparableSha256,
                ImportStatus = "pending"
            });
        }

        private static List<Dictionary<string, string>> ReadFlatJsonlRows(string path, string context)
        {
            List<Dictionary<string, string>> rows = new List<Dictionary<string, string>>();
            string[] lines = File.ReadAllLines(path, Encoding.UTF8);
            for (int i = 0; i < lines.Length; i++)
            {
                string trimmed = EmptyIfNull(lines[i]).Trim();
                if (string.IsNullOrWhiteSpace(trimmed) || trimmed.StartsWith("#", StringComparison.Ordinal) || trimmed.StartsWith("//", StringComparison.Ordinal))
                {
                    continue;
                }

                rows.Add(ParseFlatJsonObject(trimmed, context + " row " + (i + 1)));
            }

            return rows;
        }

        private static void ImportHmiPatchedXml(HmiInventorySnapshot hmiSnapshot, HmiImportProbeTarget target)
        {
            try
            {
                object container = ResolveHmiImportContainer(hmiSnapshot, target);
                MethodInfo import = FindHmiImportFileInfoMethod(container);
                Type importOptionsType = import.GetParameters()[1].ParameterType;
                object importOptions = ChooseEnumValue(importOptionsType, new[] { "Override", "None" });
                object result = import.Invoke(container, new object[] { new FileInfo(target.PatchedXmlPath), importOptions });

                target.ContainerType = container.GetType().FullName;
                target.ImportMethod = DescribeMethod(import);
                target.ImportOptions = Convert.ToString(importOptions);
                target.ImportResult = result == null ? string.Empty : SafeDescribe(result);
                target.ImportStatus = "ok";
                target.ImportMessage = "Import invoked on copied project only.";
            }
            catch (Exception ex)
            {
                Exception actual = ex is TargetInvocationException && ex.InnerException != null ? ex.InnerException : ex;
                target.ImportStatus = "error";
                target.ImportMessage = actual.GetType().Name + ": " + actual.Message;
            }
        }

        private static object ResolveHmiImportContainer(HmiInventorySnapshot hmiSnapshot, HmiImportProbeTarget target)
        {
            HmiTargetRecord hmiTarget = hmiSnapshot.Targets.FirstOrDefault(x => string.IsNullOrWhiteSpace(target.TargetPath) || EqualsIgnoreCase(x.TargetPath, target.TargetPath))
                ?? hmiSnapshot.Targets.FirstOrDefault();
            if (hmiTarget == null || hmiTarget.Object == null)
            {
                throw new InvalidOperationException("No HMI target was found in copied project.");
            }

            object targetObject = hmiTarget.Object;
            if (EqualsIgnoreCase(target.Kind, "TextList"))
            {
                return RequiredProperty(targetObject, "TextLists");
            }

            if (EqualsIgnoreCase(target.Kind, "GraphicList"))
            {
                return RequiredProperty(targetObject, "GraphicLists");
            }

            if (EqualsIgnoreCase(target.Kind, "TagTable"))
            {
                object tagFolder = RequiredProperty(targetObject, "TagFolder");
                object folder = FindHmiFolderByPath(tagFolder, target.FolderPath, "HMI tags");
                return RequiredProperty(folder, "TagTables");
            }

            if (EqualsIgnoreCase(target.Kind, "Screen"))
            {
                object folder = FindHmiFolderByPath(RequiredProperty(targetObject, "ScreenFolder"), target.FolderPath, "Screens");
                return RequiredProperty(folder, "Screens");
            }

            if (EqualsIgnoreCase(target.Kind, "Popup"))
            {
                object folder = FindHmiFolderByPath(RequiredProperty(targetObject, "ScreenPopupFolder"), target.FolderPath, "Pop-up screens");
                return RequiredProperty(folder, "ScreenPopups");
            }

            if (EqualsIgnoreCase(target.Kind, "Slidein"))
            {
                object folder = FindHmiFolderByPath(RequiredProperty(targetObject, "ScreenSlideinFolder"), target.FolderPath, "Slideins");
                return RequiredProperty(folder, "ScreenSlideins");
            }

            if (EqualsIgnoreCase(target.Kind, "Template"))
            {
                object folder = FindHmiFolderByPath(RequiredProperty(targetObject, "ScreenTemplateFolder"), target.FolderPath, "Templates");
                return RequiredProperty(folder, "ScreenTemplates");
            }

            throw new NotSupportedException("HMI import probe does not support kind yet: " + target.Kind);
        }

        private static object RequiredProperty(object value, string propertyName)
        {
            object result = TryGetPropertyValue(value, propertyName);
            if (result == null)
            {
                throw new MissingMemberException(value == null ? "<null>" : value.GetType().FullName, propertyName);
            }

            return result;
        }

        private static object FindHmiFolderByPath(object rootFolder, string folderPath, string systemRoot)
        {
            string relative = HmiRelativeFolderPath(folderPath, systemRoot);
            if (string.IsNullOrWhiteSpace(relative))
            {
                return rootFolder;
            }

            object current = rootFolder;
            foreach (string part in relative.Split(new[] { '/', '\\' }, StringSplitOptions.RemoveEmptyEntries))
            {
                object folders = TryGetPropertyValue(current, "Folders");
                object next = AsEnumerable(folders).FirstOrDefault(x => EqualsIgnoreCase(SafeName(x), part));
                if (next == null)
                {
                    throw new InvalidOperationException("HMI folder was not found: " + folderPath);
                }

                current = next;
            }

            return current;
        }

        private static MethodInfo FindHmiImportFileInfoMethod(object container)
        {
            if (container == null)
            {
                throw new ArgumentNullException("container");
            }

            MethodInfo import = container.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .Where(x => x.Name == "Import")
                .FirstOrDefault(x =>
                {
                    ParameterInfo[] parameters = x.GetParameters();
                    return parameters.Length == 2
                        && parameters[0].ParameterType == typeof(FileInfo)
                        && parameters[1].ParameterType.IsEnum;
                });
            if (import == null)
            {
                throw new MissingMethodException(container.GetType().FullName, "Import(FileInfo, ImportOptions)");
            }

            return import;
        }

        private static HmiObjectManifestRecord FindHmiManifestByRelativePath(List<HmiObjectManifestRecord> manifest, string relativePath)
        {
            string normalized = NormalizeHmiRelativePath(relativePath);
            return manifest.FirstOrDefault(x => EqualsIgnoreCase(NormalizeHmiRelativePath(x.RelativePath), normalized));
        }

        private static HmiObjectManifestRecord FindHmiManifestForProbeTarget(List<HmiObjectManifestRecord> manifest, HmiImportProbeTarget target)
        {
            HmiObjectManifestRecord exact = FindHmiManifestByRelativePath(manifest, target.RelativePath);
            if (exact != null)
            {
                return exact;
            }

            List<HmiObjectManifestRecord> candidates = manifest
                .Where(x => EqualsIgnoreCase(x.Kind, target.Kind) && EqualsIgnoreCase(x.Name, target.Name))
                .Where(x => string.IsNullOrWhiteSpace(target.TargetPath) || EqualsIgnoreCase(x.TargetPath, target.TargetPath))
                .Where(x => string.IsNullOrWhiteSpace(target.FolderPath) || EqualsIgnoreCase(x.FolderPath, target.FolderPath))
                .ToList();

            if (candidates.Count == 1)
            {
                return candidates[0];
            }

            if (!string.IsNullOrWhiteSpace(target.TypeName))
            {
                List<HmiObjectManifestRecord> typed = candidates.Where(x => EqualsIgnoreCase(x.TypeName, target.TypeName)).ToList();
                if (typed.Count == 1)
                {
                    return typed[0];
                }
            }

            return null;
        }

        private static HmiExpectedDigestChanges LoadExpectedDigestChangesFromPreflightCollateral(string patchedDir)
        {
            HmiExpectedDigestChanges expected = new HmiExpectedDigestChanges();
            string path = Path.Combine(patchedDir, "hmi-apply-preflight-collateral.jsonl");
            foreach (Dictionary<string, string> row in ReadFlatJsonlRows(path, "hmi import expected collateral"))
            {
                if (!EqualsIgnoreCase(GetCsvValue(row, "expected"), "True"))
                {
                    continue;
                }

                string report = GetCsvValue(row, "report");
                string key = GetCsvValue(row, "key");
                string relativePath = NormalizeHmiRelativePath(GetCsvValue(row, "relativePath"));
                if (!string.IsNullOrWhiteSpace(report) && !string.IsNullOrWhiteSpace(key))
                {
                    expected.RowKeys.Add(report + "|" + key);
                }

                if (!string.IsNullOrWhiteSpace(relativePath))
                {
                    expected.RelativePaths.Add(relativePath);
                }
            }

            return expected;
        }

        private static string[] HmiImportProbeTargetHeaders()
        {
            return new[]
            {
                "Kind", "Name", "TargetPath", "FolderPath", "TypeName", "RelativePath", "AfterRelativePath",
                "RelativePathChanged", "PatchedXmlPath", "ImportStatus", "ImportOptions", "ImportResult",
                "ContainerType", "ImportMethod", "BeforeComparableSha256", "PatchedComparableSha256",
                "AfterComparableSha256", "MatchesPatchedComparableSha256", "BeforeStatus", "AfterStatus", "Message"
            };
        }

        private static string[] HmiImportProbeTargetRow(HmiImportProbeTarget target)
        {
            return new[]
            {
                target.Kind,
                target.Name,
                target.TargetPath,
                target.FolderPath,
                target.TypeName,
                target.RelativePath,
                target.AfterRelativePath,
                target.RelativePathChanged.ToString(),
                target.PatchedXmlPath,
                target.ImportStatus,
                target.ImportOptions,
                target.ImportResult,
                target.ContainerType,
                target.ImportMethod,
                target.BeforeComparableSha256,
                target.PatchedComparableSha256,
                target.AfterComparableSha256,
                target.MatchesPatchedComparableSha256.ToString(),
                target.BeforeStatus,
                target.AfterStatus,
                target.ImportMessage
            };
        }

        private static Dictionary<string, string> HmiImportProbeTargetJsonRow(HmiImportProbeTarget target)
        {
            return new Dictionary<string, string>
            {
                { "kind", target.Kind },
                { "name", target.Name },
                { "targetPath", target.TargetPath },
                { "folderPath", target.FolderPath },
                { "typeName", target.TypeName },
                { "relativePath", target.RelativePath },
                { "afterRelativePath", target.AfterRelativePath },
                { "relativePathChanged", target.RelativePathChanged.ToString() },
                { "patchedXmlPath", target.PatchedXmlPath },
                { "importStatus", target.ImportStatus },
                { "importOptions", target.ImportOptions },
                { "importResult", target.ImportResult },
                { "containerType", target.ContainerType },
                { "importMethod", target.ImportMethod },
                { "beforeComparableSha256", target.BeforeComparableSha256 },
                { "patchedComparableSha256", target.PatchedComparableSha256 },
                { "afterComparableSha256", target.AfterComparableSha256 },
                { "matchesPatchedComparableSha256", target.MatchesPatchedComparableSha256.ToString() },
                { "beforeStatus", target.BeforeStatus },
                { "afterStatus", target.AfterStatus },
                { "message", target.ImportMessage }
            };
        }

        private static void WriteHmiImportProbeCopySummary(string path, Options options, string patchedDir, string probeDir, List<HmiImportProbeTarget> targets, List<HmiObjectDiffRecord> objectDiffs, List<HmiApplyCollateralDiffRecord> collateral)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("HMI import probe on copied project");
                writer.WriteLine("Generated: " + DateTime.Now.ToString("o"));
                writer.WriteLine("Mode: copied-project-only; the original project is not opened for import.");
                writer.WriteLine("Original project: " + options.OriginalProjectPath);
                writer.WriteLine("Copied project: " + options.ProjectPath);
                writer.WriteLine("Copied project directory: " + options.ImportProbeProjectCopyDir);
                writer.WriteLine("Patched preflight directory: " + patchedDir);
                writer.WriteLine("Probe report directory: " + probeDir);
                writer.WriteLine("Saved copied project: " + options.Save);
                writer.WriteLine();
                writer.WriteLine("Import targets: " + targets.Count);
                writer.WriteLine("Import ok: " + targets.Count(x => EqualsIgnoreCase(x.ImportStatus, "ok")));
                writer.WriteLine("Import errors: " + targets.Count(x => EqualsIgnoreCase(x.ImportStatus, "error")));
                writer.WriteLine("Targets matching patched comparable hash: " + targets.Count(x => x.MatchesPatchedComparableSha256));
                writer.WriteLine("Targets with changed relative path: " + targets.Count(x => x.RelativePathChanged));
                writer.WriteLine("Changed object diff rows: " + objectDiffs.Count(x => !EqualsIgnoreCase(x.Status, "unchanged")));
                writer.WriteLine("Collateral rows: " + collateral.Count);
                writer.WriteLine("Unexpected collateral rows: " + collateral.Count(x => !x.Expected));
                writer.WriteLine("In-place safety verdict: " + (IsHmiImportProbeAccepted(targets, collateral) ? "accepted" : "rejected"));
                if (!IsHmiImportProbeAccepted(targets, collateral))
                {
                    writer.WriteLine("Verdict reason: import must match patched comparable hashes, keep target relative paths stable, and produce no unexpected collateral rows.");
                }
                writer.WriteLine();
                writer.WriteLine("Root reports:");
                writer.WriteLine("  " + Path.Combine(Path.GetDirectoryName(path), "hmi-import-probe-copy-targets.csv"));
                writer.WriteLine("  " + Path.Combine(Path.GetDirectoryName(path), "hmi-import-probe-copy-object-diff.csv"));
                writer.WriteLine("  " + Path.Combine(Path.GetDirectoryName(path), "hmi-import-probe-copy-collateral.csv"));
            }
        }

        private static bool IsHmiImportProbeAccepted(List<HmiImportProbeTarget> targets, List<HmiApplyCollateralDiffRecord> collateral)
        {
            return targets.Count > 0
                && targets.All(x => EqualsIgnoreCase(x.ImportStatus, "ok") && x.MatchesPatchedComparableSha256 && !x.RelativePathChanged)
                && !collateral.Any(x => !x.Expected);
        }

        private static void HmiProjectTextsImportProbeCopyCommand(object project, Options options)
        {
            string cloneDir = ResolveCloneProjectDirectory(options.OutDir);
            string patchedDir = ResolveRequiredInputDirectory(options.InDir);
            string sourceCultureName = "en-US";
            string targetCultureName = FirstNonEmpty(options.Language, "ru-RU");

            Directory.CreateDirectory(cloneDir);
            string probeDir = Path.Combine(cloneDir, "_hmi_project_texts_import_probe", "probe-" + DateTime.Now.ToString("yyyyMMdd-HHmmss"));
            string beforeDir = Path.Combine(probeDir, "before");
            string afterDir = Path.Combine(probeDir, "after");
            string beforeHmiRoot = Path.Combine(beforeDir, "_hmi");
            string beforeDigestDir = Path.Combine(beforeDir, "_hmi_metadata", "digest");
            string beforeManifestPath = Path.Combine(beforeDir, "_hmi_metadata", "hmi-objects.csv");
            string afterHmiRoot = Path.Combine(afterDir, "_hmi");
            string afterDigestDir = Path.Combine(afterDir, "_hmi_metadata", "digest");
            string afterManifestPath = Path.Combine(afterDir, "_hmi_metadata", "hmi-objects.csv");
            Directory.CreateDirectory(probeDir);

            List<HmiProjectTextImportTarget> targets = LoadHmiProjectTextImportTargets(cloneDir, patchedDir, targetCultureName);
            if (targets.Count == 0)
            {
                throw new InvalidOperationException("No changed HMI project-text target was found in patched preflight directory: " + patchedDir);
            }

            InventorySnapshot beforeSnapshot = CollectInventory(project, options.ProjectPath);
            HmiInventorySnapshot beforeHmi = CollectHmiInventory(beforeSnapshot);
            ExportHmiXml(beforeHmi, beforeHmiRoot, true);
            WriteHmiDigest(beforeHmiRoot, beforeDigestDir);
            List<HmiObjectManifestRecord> beforeManifest = BuildHmiObjectManifest(beforeHmiRoot, beforeDigestDir);
            WriteHmiObjectManifest(beforeManifestPath, beforeManifest);
            foreach (HmiProjectTextImportTarget target in targets)
            {
                HmiObjectManifestRecord before = FindHmiManifestByRelativePath(beforeManifest, target.RelativePath);
                target.BeforeComparableSha256 = before == null ? string.Empty : before.ComparableSha256;
            }

            string beforeXlsx = Path.Combine(probeDir, "project-texts-before-" + SafeFileName(sourceCultureName + "-" + targetCultureName) + ".xlsx");
            string patchedXlsx = Path.Combine(probeDir, "project-texts-patched-" + SafeFileName(sourceCultureName + "-" + targetCultureName) + ".xlsx");
            ExportProjectTextsWorkbook(project, beforeXlsx, sourceCultureName, targetCultureName);
            File.Copy(beforeXlsx, patchedXlsx, true);
            PatchProjectTextsWorkbook(patchedXlsx, targets, targetCultureName);

            if (targets.Any(x => EqualsIgnoreCase(x.XlsxPatchStatus, "error")))
            {
                throw new InvalidOperationException("Project-texts XLSX patch failed. Inspect targets under: " + probeDir);
            }

            MethodInfo import = ImportProjectTextsWorkbook(project, patchedXlsx, options.UpdateSourceLanguage);
            foreach (HmiProjectTextImportTarget target in targets)
            {
                target.ImportStatus = "ok";
                target.ImportMethod = DescribeMethod(import);
                target.ImportMessage = "ImportProjectTexts invoked on copied project only. updateSourceLanguage=" + options.UpdateSourceLanguage.ToString() + ".";
            }

            if (options.Save)
            {
                SaveProject(project);
            }

            InventorySnapshot afterSnapshot = CollectInventory(project, options.ProjectPath);
            HmiInventorySnapshot afterHmi = CollectHmiInventory(afterSnapshot);
            ExportHmiXml(afterHmi, afterHmiRoot, true);
            WriteHmiDigest(afterHmiRoot, afterDigestDir);
            List<HmiObjectManifestRecord> afterManifest = BuildHmiObjectManifest(afterHmiRoot, afterDigestDir);
            WriteHmiObjectManifest(afterManifestPath, afterManifest);

            List<HmiObjectDiffRecord> objectDiffs = BuildHmiObjectDiffs(beforeManifest, afterManifest);
            HmiExpectedDigestChanges expected = LoadExpectedDigestChangesFromPreflightCollateral(patchedDir);
            List<HmiApplyCollateralDiffRecord> collateral = BuildHmiDigestCollateralDiff(beforeDigestDir, afterDigestDir, expected);
            PopulateHmiProjectTextImportResultTargets(targets, patchedDir, afterDigestDir, afterManifest);

            string summaryPath = Path.Combine(cloneDir, "hmi-project-texts-import-probe-copy-summary.txt");
            string targetsPath = Path.Combine(cloneDir, "hmi-project-texts-import-probe-copy-targets.csv");
            string diffsPath = Path.Combine(cloneDir, "hmi-project-texts-import-probe-copy-object-diff.csv");
            string collateralPath = Path.Combine(cloneDir, "hmi-project-texts-import-probe-copy-collateral.csv");

            WriteCsv(targetsPath, HmiProjectTextImportTargetHeaders(), targets.Select(HmiProjectTextImportTargetRow));
            WriteCsv(diffsPath, HmiObjectDiffHeaders(), objectDiffs.Select(HmiObjectDiffRow));
            WriteCsv(collateralPath, HmiApplyCollateralDiffHeaders(), collateral.Select(HmiApplyCollateralDiffRow));
            WriteJsonl(Path.Combine(probeDir, "hmi-project-texts-import-probe-copy-targets.jsonl"), targets.Select(HmiProjectTextImportTargetJsonRow));
            WriteJsonl(Path.Combine(probeDir, "hmi-project-texts-import-probe-copy-collateral.jsonl"), collateral.Select(HmiApplyCollateralDiffJsonRow));
            WriteHmiProjectTextsImportProbeCopySummary(summaryPath, options, patchedDir, probeDir, sourceCultureName, targetCultureName, beforeXlsx, patchedXlsx, targets, objectDiffs, collateral);

            Console.WriteLine("HMI project-texts import probe on copied project");
            Console.WriteLine("  Project copy: " + options.ImportProbeProjectCopyDir);
            Console.WriteLine("  Probe directory: " + probeDir);
            Console.WriteLine("  Project-text targets: " + targets.Count);
            Console.WriteLine("  XLSX patched: " + targets.Count(x => EqualsIgnoreCase(x.XlsxPatchStatus, "changed")));
            Console.WriteLine("  Import ok: " + targets.Count(x => EqualsIgnoreCase(x.ImportStatus, "ok")));
            Console.WriteLine("  Matches patched text: " + targets.Count(x => x.MatchesPatchedText));
            Console.WriteLine("  Matches patched comparable hash: " + targets.Count(x => x.MatchesPatchedComparableSha256));
            Console.WriteLine("  Targets with relative path change: " + targets.Count(x => x.RelativePathChanged));
            Console.WriteLine("  Object diff rows: " + objectDiffs.Count(x => !EqualsIgnoreCase(x.Status, "unchanged")));
            Console.WriteLine("  Collateral rows: " + collateral.Count);
            Console.WriteLine("  Unexpected collateral rows: " + collateral.Count(x => !x.Expected));
            Console.WriteLine("  In-place safety verdict: " + (IsHmiProjectTextsImportProbeAccepted(targets, collateral) ? "accepted" : "rejected"));
            Console.WriteLine("  Summary: " + summaryPath);
            Console.WriteLine("  Targets: " + targetsPath);
            Console.WriteLine("  Collateral: " + collateralPath);
        }

        private static void ExportProjectTextsWorkbook(object project, string xlsxPath, string sourceCultureName, string targetCultureName)
        {
            MethodInfo export = project.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(x =>
                {
                    if (x.Name != "ExportProjectTexts")
                    {
                        return false;
                    }

                    ParameterInfo[] parameters = x.GetParameters();
                    return parameters.Length == 3
                        && parameters[0].ParameterType == typeof(FileInfo)
                        && parameters[1].ParameterType == typeof(CultureInfo)
                        && parameters[2].ParameterType == typeof(CultureInfo);
                });
            if (export == null)
            {
                throw new MissingMethodException(project.GetType().FullName, "ExportProjectTexts(FileInfo, CultureInfo, CultureInfo)");
            }

            Directory.CreateDirectory(Path.GetDirectoryName(xlsxPath));
            export.Invoke(project, new object[]
            {
                new FileInfo(xlsxPath),
                new CultureInfo(sourceCultureName),
                new CultureInfo(targetCultureName)
            });
        }

        private static MethodInfo ImportProjectTextsWorkbook(object project, string xlsxPath, bool updateSourceLanguage)
        {
            MethodInfo import = project.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(x =>
                {
                    if (x.Name != "ImportProjectTexts")
                    {
                        return false;
                    }

                    ParameterInfo[] parameters = x.GetParameters();
                    return parameters.Length == 2
                        && parameters[0].ParameterType == typeof(FileInfo)
                        && parameters[1].ParameterType == typeof(bool);
                });
            if (import == null)
            {
                throw new MissingMethodException(project.GetType().FullName, "ImportProjectTexts(FileInfo, bool)");
            }

            import.Invoke(project, new object[] { new FileInfo(xlsxPath), updateSourceLanguage });
            return import;
        }

        private static List<HmiProjectTextImportTarget> LoadHmiProjectTextImportTargets(string cloneDir, string patchedDir, string targetCultureName)
        {
            string baseDigestDir = Path.Combine(cloneDir, "_hmi_metadata", "digest");
            string patchedDigestDir = Path.Combine(patchedDir, "_hmi_metadata", "digest");
            HmiExpectedDigestChanges expected = LoadExpectedDigestChangesFromPreflightCollateral(patchedDir);
            List<HmiProjectTextImportTarget> targets = new List<HmiProjectTextImportTarget>();

            AddHmiTextListProjectTextImportTargets(baseDigestDir, patchedDigestDir, expected, targetCultureName, targets);
            AddHmiScreenItemProjectTextImportTargets(baseDigestDir, patchedDigestDir, expected, targetCultureName, targets);

            return targets;
        }

        private static void AddHmiTextListProjectTextImportTargets(
            string baseDigestDir,
            string patchedDigestDir,
            HmiExpectedDigestChanges expected,
            string targetCultureName,
            List<HmiProjectTextImportTarget> targets)
        {
            List<Dictionary<string, string>> baseRows = LoadRequiredCsv(Path.Combine(baseDigestDir, "hmi-text-list-items.csv"), "Base HMI digest is required.");
            List<Dictionary<string, string>> patchedRows = LoadRequiredCsv(Path.Combine(patchedDigestDir, "hmi-text-list-items.csv"), "Patched HMI digest is required.");
            Dictionary<string, Dictionary<string, string>> patchedByKey = patchedRows
                .GroupBy(x => HmiDigestRowKey("hmi-text-list-items.csv", x), StringComparer.OrdinalIgnoreCase)
                .ToDictionary(x => x.Key, x => x.First(), StringComparer.OrdinalIgnoreCase);

            Dictionary<string, int> ordinals = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (Dictionary<string, string> baseRow in baseRows)
            {
                string ordinalKey = NormalizeHmiRelativePath(GetCsvValue(baseRow, "RelativePath")) + "|" + GetCsvValue(baseRow, "TextListName");
                int ordinal;
                ordinals.TryGetValue(ordinalKey, out ordinal);
                ordinal++;
                ordinals[ordinalKey] = ordinal;

                string key = HmiDigestRowKey("hmi-text-list-items.csv", baseRow);
                if (!expected.RowKeys.Contains("hmi-text-list-items.csv|" + key))
                {
                    continue;
                }

                Dictionary<string, string> patchedRow;
                if (!patchedByKey.TryGetValue(key, out patchedRow))
                {
                    continue;
                }

                Dictionary<string, string> beforeTexts = ParseHmiDigestTextMap(GetCsvValue(baseRow, "Texts"));
                Dictionary<string, string> afterTexts = ParseHmiDigestTextMap(GetCsvValue(patchedRow, "Texts"));
                foreach (string culture in beforeTexts.Keys.Union(afterTexts.Keys, StringComparer.OrdinalIgnoreCase).OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
                {
                    string beforeText = GetTextMapValue(beforeTexts, culture);
                    string patchedText = GetTextMapValue(afterTexts, culture);
                    if (string.Equals(beforeText, patchedText, StringComparison.Ordinal))
                    {
                        continue;
                    }

                    if (!EqualsIgnoreCase(culture, targetCultureName))
                    {
                        throw new InvalidOperationException("Patched text culture '" + culture + "' does not match project-texts target language '" + targetCultureName + "'. Re-run with --language " + culture + ".");
                    }

                    targets.Add(new HmiProjectTextImportTarget
                    {
                        TargetKind = "TextListEntry",
                        DigestReport = "hmi-text-list-items.csv",
                        TextListName = GetCsvValue(baseRow, "TextListName"),
                        RelativePath = NormalizeHmiRelativePath(GetCsvValue(baseRow, "RelativePath")),
                        EntryId = GetCsvValue(baseRow, "EntryId"),
                        From = GetCsvValue(baseRow, "From"),
                        To = GetCsvValue(baseRow, "To"),
                        EntryType = GetCsvValue(baseRow, "EntryType"),
                        Culture = culture,
                        BeforeText = beforeText,
                        PatchedText = patchedText,
                        DigestKey = key,
                        XlsxEntryOrdinal = ordinal,
                        XlsxViewPathSuffix = "\\Text and graphic lists\\" + GetCsvValue(baseRow, "TextListName") + "\\Text_list_entry_" + ordinal.ToString() + "\\Text",
                        XlsxPatchStatus = "pending",
                        ImportStatus = "pending"
                    });
                }
            }
        }

        private static void AddHmiScreenItemProjectTextImportTargets(
            string baseDigestDir,
            string patchedDigestDir,
            HmiExpectedDigestChanges expected,
            string targetCultureName,
            List<HmiProjectTextImportTarget> targets)
        {
            List<Dictionary<string, string>> baseRows = LoadRequiredCsv(Path.Combine(baseDigestDir, "hmi-screen-items.csv"), "Base HMI digest is required.");
            List<Dictionary<string, string>> patchedRows = LoadRequiredCsv(Path.Combine(patchedDigestDir, "hmi-screen-items.csv"), "Patched HMI digest is required.");
            Dictionary<string, Dictionary<string, string>> patchedByKey = patchedRows
                .GroupBy(x => HmiDigestRowKey("hmi-screen-items.csv", x), StringComparer.OrdinalIgnoreCase)
                .ToDictionary(x => x.Key, x => x.First(), StringComparer.OrdinalIgnoreCase);

            foreach (Dictionary<string, string> baseRow in baseRows)
            {
                string key = HmiDigestRowKey("hmi-screen-items.csv", baseRow);
                if (!expected.RowKeys.Contains("hmi-screen-items.csv|" + key))
                {
                    continue;
                }

                Dictionary<string, string> patchedRow;
                if (!patchedByKey.TryGetValue(key, out patchedRow))
                {
                    continue;
                }

                Dictionary<string, string> beforeTexts = ParseHmiDigestTextMap(GetCsvValue(baseRow, "Text"));
                Dictionary<string, string> afterTexts = ParseHmiDigestTextMap(GetCsvValue(patchedRow, "Text"));
                foreach (string culture in beforeTexts.Keys.Union(afterTexts.Keys, StringComparer.OrdinalIgnoreCase).OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
                {
                    string beforeText = GetTextMapValue(beforeTexts, culture);
                    string patchedText = GetTextMapValue(afterTexts, culture);
                    if (string.Equals(beforeText, patchedText, StringComparison.Ordinal))
                    {
                        continue;
                    }

                    if (!EqualsIgnoreCase(culture, targetCultureName))
                    {
                        throw new InvalidOperationException("Patched screen-item text culture '" + culture + "' does not match project-texts target language '" + targetCultureName + "'. Re-run with --language " + culture + ".");
                    }

                    string screenName = GetCsvValue(baseRow, "ScreenName");
                    string itemName = GetCsvValue(baseRow, "ItemName");
                    targets.Add(new HmiProjectTextImportTarget
                    {
                        TargetKind = "ScreenItemText",
                        DigestReport = "hmi-screen-items.csv",
                        ScreenName = screenName,
                        ItemName = itemName,
                        ItemId = GetCsvValue(baseRow, "ItemId"),
                        RelativePath = NormalizeHmiRelativePath(GetCsvValue(baseRow, "RelativePath")),
                        Culture = culture,
                        BeforeText = beforeText,
                        PatchedText = patchedText,
                        DigestKey = key,
                        XlsxViewPathSuffix = "\\Screens\\" + screenName + "\\" + itemName + "\\Text",
                        XlsxPatchStatus = "pending",
                        ImportStatus = "pending"
                    });
                }
            }
        }

        private static Dictionary<string, string> ParseHmiDigestTextMap(string value)
        {
            Dictionary<string, string> result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (string part in EmptyIfNull(value).Split(new[] { " | " }, StringSplitOptions.None))
            {
                int index = part.IndexOf('=');
                if (index <= 0)
                {
                    continue;
                }

                result[part.Substring(0, index).Trim()] = part.Substring(index + 1);
            }

            return result;
        }

        private static string GetTextMapValue(Dictionary<string, string> texts, string culture)
        {
            string value;
            return texts != null && texts.TryGetValue(culture, out value) ? value : string.Empty;
        }

        private static void PatchProjectTextsWorkbook(string xlsxPath, List<HmiProjectTextImportTarget> targets, string targetCultureName)
        {
            string tempDir = Path.Combine(Path.GetTempPath(), ProductName + "ProjectTexts_" + Guid.NewGuid().ToString("N"));
            try
            {
                ZipFile.ExtractToDirectory(xlsxPath, tempDir);
                string workbookPath = Path.Combine(tempDir, "xl", "workbook.xml");
                string relsPath = Path.Combine(tempDir, "xl", "_rels", "workbook.xml.rels");
                string sheetRelativePath = FindWorkbookSheetPath(workbookPath, relsPath, "User Texts");
                string normalizedSheetPath = sheetRelativePath.Replace('/', Path.DirectorySeparatorChar);
                string sheetPath = normalizedSheetPath.StartsWith("xl" + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)
                    ? Path.Combine(tempDir, normalizedSheetPath)
                    : Path.Combine(Path.Combine(tempDir, "xl"), normalizedSheetPath);
                string sharedStringsPath = Path.Combine(tempDir, "xl", "sharedStrings.xml");
                XmlDocument sharedStrings = LoadOpenXmlDocument(sharedStringsPath);
                List<string> shared = ReadSharedStrings(sharedStrings);
                XmlDocument worksheet = LoadOpenXmlDocument(sheetPath);
                List<XmlElement> rows = DescendantElements(worksheet.DocumentElement)
                    .Where(x => EqualsIgnoreCase(x.LocalName, "row"))
                    .ToList();
                XmlElement headerRow = rows.FirstOrDefault(x => GetXlsxRowIndex(x) == 1) ?? rows.FirstOrDefault();
                Dictionary<string, int> columns = ReadXlsxHeaderColumns(headerRow, shared);
                int viewPathColumn = RequireXlsxColumn(columns, "ViewPath");
                int cultureColumn = RequireXlsxColumn(columns, targetCultureName);

                foreach (HmiProjectTextImportTarget target in targets)
                {
                    string expectedSuffix = BuildHmiProjectTextViewPathSuffix(target);
                    XmlElement row = rows.FirstOrDefault(x =>
                    {
                        string viewPath = ReadXlsxCellText(GetXlsxCellByColumn(x, viewPathColumn), shared).Replace('/', '\\');
                        return viewPath.EndsWith(expectedSuffix, StringComparison.OrdinalIgnoreCase);
                    });
                    if (row == null)
                    {
                        target.XlsxPatchStatus = "error";
                        target.XlsxMessage = "Could not find User Texts row ending with: " + expectedSuffix;
                        continue;
                    }

                    int rowIndex = GetXlsxRowIndex(row);
                    XmlElement cell = GetOrCreateXlsxCell(worksheet, row, cultureColumn, rowIndex);
                    target.XlsxRow = rowIndex.ToString();
                    target.XlsxCell = GetXlsxColumnName(cultureColumn) + rowIndex.ToString();
                    target.XlsxBeforeText = ReadXlsxCellText(cell, shared);
                    if (!string.Equals(target.XlsxBeforeText, target.BeforeText, StringComparison.Ordinal))
                    {
                        target.XlsxPatchStatus = "error";
                        target.XlsxMessage = "Workbook cell value does not match digest before text. Digest='" + target.BeforeText + "' XLSX='" + target.XlsxBeforeText + "'.";
                        continue;
                    }

                    if (string.Equals(target.XlsxBeforeText, target.PatchedText, StringComparison.Ordinal))
                    {
                        target.XlsxPatchStatus = "no-change";
                        target.XlsxAfterText = target.XlsxBeforeText;
                        target.XlsxMessage = "Workbook already contains patched text.";
                        continue;
                    }

                    int sharedIndex = GetOrAddSharedString(sharedStrings, shared, target.PatchedText);
                    SetXlsxSharedStringCellValue(worksheet, cell, sharedIndex);
                    target.XlsxPatchStatus = "changed";
                    target.XlsxAfterText = target.PatchedText;
                    target.XlsxMessage = "Patched target language cell in exported project-texts workbook.";
                }

                SaveXmlDocumentNoBom(sharedStrings, sharedStringsPath);
                SaveXmlDocumentNoBom(worksheet, sheetPath);
                File.Delete(xlsxPath);
                CreateZipFromDirectoryWithForwardSlashes(tempDir, xlsxPath);
            }
            finally
            {
                if (Directory.Exists(tempDir))
                {
                    Directory.Delete(tempDir, true);
                }
            }
        }

        private static string BuildHmiProjectTextViewPathSuffix(HmiProjectTextImportTarget target)
        {
            if (!string.IsNullOrWhiteSpace(target.XlsxViewPathSuffix))
            {
                return target.XlsxViewPathSuffix;
            }

            if (EqualsIgnoreCase(target.TargetKind, "ScreenItemText"))
            {
                target.XlsxViewPathSuffix = "\\Screens\\" + target.ScreenName + "\\" + target.ItemName + "\\Text";
                return target.XlsxViewPathSuffix;
            }

            target.XlsxViewPathSuffix = "\\Text and graphic lists\\" + target.TextListName + "\\Text_list_entry_" + target.XlsxEntryOrdinal.ToString() + "\\Text";
            return target.XlsxViewPathSuffix;
        }

        private static void CreateZipFromDirectoryWithForwardSlashes(string sourceDir, string zipPath)
        {
            using (ZipArchive archive = ZipFile.Open(zipPath, ZipArchiveMode.Create))
            {
                foreach (string filePath in Directory.GetFiles(sourceDir, "*", SearchOption.AllDirectories))
                {
                    string entryName = MakeRelativePath(sourceDir, filePath).Replace('\\', '/');
                    archive.CreateEntryFromFile(filePath, entryName, CompressionLevel.Optimal);
                }
            }
        }

        private static XmlDocument LoadOpenXmlDocument(string path)
        {
            XmlDocument document = new XmlDocument();
            document.PreserveWhitespace = true;
            using (XmlReader reader = XmlReader.Create(path, new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit }))
            {
                document.Load(reader);
            }

            return document;
        }

        private static string FindWorkbookSheetPath(string workbookPath, string relsPath, string sheetName)
        {
            XmlDocument workbook = LoadOpenXmlDocument(workbookPath);
            XmlElement sheet = DescendantElements(workbook.DocumentElement)
                .FirstOrDefault(x => EqualsIgnoreCase(x.LocalName, "sheet") && EqualsIgnoreCase(x.GetAttribute("name"), sheetName));
            if (sheet == null)
            {
                throw new InvalidDataException("Workbook sheet was not found: " + sheetName);
            }

            string relationshipId = GetOpenXmlRelationshipId(sheet);
            XmlDocument rels = LoadOpenXmlDocument(relsPath);
            XmlElement relationship = DescendantElements(rels.DocumentElement)
                .FirstOrDefault(x => EqualsIgnoreCase(x.LocalName, "Relationship") && EqualsIgnoreCase(x.GetAttribute("Id"), relationshipId));
            if (relationship == null)
            {
                throw new InvalidDataException("Workbook relationship was not found for sheet: " + sheetName);
            }

            return relationship.GetAttribute("Target").TrimStart('/', '\\');
        }

        private static string GetOpenXmlRelationshipId(XmlElement element)
        {
            if (element == null)
            {
                return string.Empty;
            }

            foreach (XmlAttribute attribute in element.Attributes)
            {
                if (EqualsIgnoreCase(attribute.LocalName, "id"))
                {
                    return attribute.Value;
                }
            }

            return string.Empty;
        }

        private static List<string> ReadSharedStrings(XmlDocument sharedStrings)
        {
            List<string> result = new List<string>();
            foreach (XmlElement si in ChildElements(sharedStrings.DocumentElement).Where(x => EqualsIgnoreCase(x.LocalName, "si")))
            {
                result.Add(si.InnerText);
            }

            return result;
        }

        private static Dictionary<string, int> ReadXlsxHeaderColumns(XmlElement headerRow, List<string> sharedStrings)
        {
            Dictionary<string, int> result = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            if (headerRow == null)
            {
                return result;
            }

            foreach (XmlElement cell in ChildElements(headerRow).Where(x => EqualsIgnoreCase(x.LocalName, "c")))
            {
                int column = GetXlsxCellColumn(cell);
                string text = ReadXlsxCellText(cell, sharedStrings);
                if (!string.IsNullOrWhiteSpace(text) && column > 0)
                {
                    result[text.TrimEnd('*')] = column;
                    result[text] = column;
                }
            }

            return result;
        }

        private static int RequireXlsxColumn(Dictionary<string, int> columns, string name)
        {
            int column;
            if (columns.TryGetValue(name, out column))
            {
                return column;
            }

            throw new InvalidDataException("Project-texts workbook does not contain required column: " + name);
        }

        private static XmlElement GetXlsxCellByColumn(XmlElement row, int column)
        {
            return ChildElements(row)
                .Where(x => EqualsIgnoreCase(x.LocalName, "c"))
                .FirstOrDefault(x => GetXlsxCellColumn(x) == column);
        }

        private static XmlElement GetOrCreateXlsxCell(XmlDocument document, XmlElement row, int column, int rowIndex)
        {
            XmlElement existing = GetXlsxCellByColumn(row, column);
            if (existing != null)
            {
                return existing;
            }

            string ns = row.NamespaceURI;
            XmlElement cell = document.CreateElement("c", ns);
            cell.SetAttribute("r", GetXlsxColumnName(column) + rowIndex.ToString());
            XmlElement insertBefore = ChildElements(row)
                .Where(x => EqualsIgnoreCase(x.LocalName, "c") && GetXlsxCellColumn(x) > column)
                .FirstOrDefault();
            if (insertBefore == null)
            {
                row.AppendChild(cell);
            }
            else
            {
                row.InsertBefore(cell, insertBefore);
            }

            return cell;
        }

        private static string ReadXlsxCellText(XmlElement cell, List<string> sharedStrings)
        {
            if (cell == null)
            {
                return string.Empty;
            }

            string type = cell.GetAttribute("t");
            XmlElement value = ChildElements(cell).FirstOrDefault(x => EqualsIgnoreCase(x.LocalName, "v"));
            if (EqualsIgnoreCase(type, "s"))
            {
                int index;
                if (value != null && int.TryParse(value.InnerText, out index) && index >= 0 && index < sharedStrings.Count)
                {
                    return sharedStrings[index];
                }

                return string.Empty;
            }

            if (EqualsIgnoreCase(type, "inlineStr"))
            {
                return cell.InnerText;
            }

            return value == null ? string.Empty : value.InnerText;
        }

        private static void SetXlsxSharedStringCellValue(XmlDocument document, XmlElement cell, int sharedStringIndex)
        {
            cell.SetAttribute("t", "s");
            foreach (XmlElement child in ChildElements(cell).Where(x => !EqualsIgnoreCase(x.LocalName, "v")).ToList())
            {
                cell.RemoveChild(child);
            }

            XmlElement value = ChildElements(cell).FirstOrDefault(x => EqualsIgnoreCase(x.LocalName, "v"));
            if (value == null)
            {
                value = document.CreateElement("v", cell.NamespaceURI);
                cell.AppendChild(value);
            }

            value.InnerText = sharedStringIndex.ToString();
        }

        private static int GetOrAddSharedString(XmlDocument document, List<string> sharedStrings, string value)
        {
            for (int i = 0; i < sharedStrings.Count; i++)
            {
                if (string.Equals(sharedStrings[i], EmptyIfNull(value), StringComparison.Ordinal))
                {
                    return i;
                }
            }

            string ns = document.DocumentElement.NamespaceURI;
            XmlElement si = document.CreateElement("si", ns);
            XmlElement t = document.CreateElement("t", ns);
            t.InnerText = EmptyIfNull(value);
            if (value != null && (value.StartsWith(" ", StringComparison.Ordinal) || value.EndsWith(" ", StringComparison.Ordinal)))
            {
                XmlAttribute space = document.CreateAttribute("xml", "space", "http://www.w3.org/XML/1998/namespace");
                space.Value = "preserve";
                t.Attributes.Append(space);
            }

            si.AppendChild(t);
            document.DocumentElement.AppendChild(si);
            sharedStrings.Add(EmptyIfNull(value));
            SetOpenXmlCountAttribute(document.DocumentElement, "count", sharedStrings.Count);
            SetOpenXmlCountAttribute(document.DocumentElement, "uniqueCount", sharedStrings.Count);
            return sharedStrings.Count - 1;
        }

        private static void SetOpenXmlCountAttribute(XmlElement element, string name, int value)
        {
            if (element.HasAttribute(name))
            {
                element.SetAttribute(name, value.ToString());
            }
        }

        private static int GetXlsxRowIndex(XmlElement row)
        {
            int value;
            return row != null && int.TryParse(row.GetAttribute("r"), out value) ? value : 0;
        }

        private static int GetXlsxCellColumn(XmlElement cell)
        {
            string reference = cell == null ? string.Empty : cell.GetAttribute("r");
            int result = 0;
            foreach (char c in reference)
            {
                if (!char.IsLetter(c))
                {
                    break;
                }

                result = result * 26 + (char.ToUpperInvariant(c) - 'A' + 1);
            }

            return result;
        }

        private static string GetXlsxColumnName(int column)
        {
            StringBuilder builder = new StringBuilder();
            int value = column;
            while (value > 0)
            {
                value--;
                builder.Insert(0, (char)('A' + (value % 26)));
                value /= 26;
            }

            return builder.ToString();
        }

        private static HmiObjectManifestRecord FindHmiManifestForProjectTextTarget(List<HmiObjectManifestRecord> manifest, HmiProjectTextImportTarget target)
        {
            HmiObjectManifestRecord exact = FindHmiManifestByRelativePath(manifest, target.RelativePath);
            if (exact != null)
            {
                return exact;
            }

            List<HmiObjectManifestRecord> candidates = manifest
                .Where(x => (EqualsIgnoreCase(target.TargetKind, "ScreenItemText")
                        && IsHmiScreenLikeKind(x.Kind, x.RelativePath)
                        && EqualsIgnoreCase(x.Name, target.ScreenName))
                    || (!EqualsIgnoreCase(target.TargetKind, "ScreenItemText")
                        && EqualsIgnoreCase(x.Kind, "TextList")
                        && EqualsIgnoreCase(x.Name, target.TextListName)))
                .ToList();
            return candidates.Count == 1 ? candidates[0] : null;
        }

