        private static void WriteHmiProjectTextsImportProbeCopySummary(
            string path,
            Options options,
            string patchedDir,
            string probeDir,
            string sourceCultureName,
            string targetCultureName,
            string beforeXlsx,
            string patchedXlsx,
            List<HmiProjectTextImportTarget> targets,
            List<HmiObjectDiffRecord> objectDiffs,
            List<HmiApplyCollateralDiffRecord> collateral)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("HMI project-texts import probe on copied project");
                writer.WriteLine("Generated: " + DateTime.Now.ToString("o"));
                writer.WriteLine("Mode: copied-project-only; the original project is not opened for import.");
                writer.WriteLine("Original project: " + options.OriginalProjectPath);
                writer.WriteLine("Copied project: " + options.ProjectPath);
                writer.WriteLine("Copied project directory: " + options.ImportProbeProjectCopyDir);
                writer.WriteLine("Patched preflight directory: " + patchedDir);
                writer.WriteLine("Probe report directory: " + probeDir);
                writer.WriteLine("Source culture: " + sourceCultureName);
                writer.WriteLine("Target culture: " + targetCultureName);
                writer.WriteLine("Import uses updateSourceLanguage: " + options.UpdateSourceLanguage);
                writer.WriteLine("Saved copied project: " + options.Save);
                writer.WriteLine("Before XLSX: " + beforeXlsx);
                writer.WriteLine("Patched XLSX: " + patchedXlsx);
                writer.WriteLine();
                writer.WriteLine("Project-text targets: " + targets.Count);
                writer.WriteLine("XLSX patched rows: " + targets.Count(x => EqualsIgnoreCase(x.XlsxPatchStatus, "changed")));
                writer.WriteLine("Import ok: " + targets.Count(x => EqualsIgnoreCase(x.ImportStatus, "ok")));
                writer.WriteLine("Targets matching patched digest text: " + targets.Count(x => x.MatchesPatchedText));
                writer.WriteLine("Targets matching patched comparable hash: " + targets.Count(x => x.MatchesPatchedComparableSha256));
                writer.WriteLine("Targets with changed relative path: " + targets.Count(x => x.RelativePathChanged));
                writer.WriteLine("Changed object diff rows: " + objectDiffs.Count(x => !EqualsIgnoreCase(x.Status, "unchanged")));
                writer.WriteLine("Collateral rows: " + collateral.Count);
                writer.WriteLine("Unexpected collateral rows: " + collateral.Count(x => !x.Expected));
                writer.WriteLine("In-place safety verdict: " + (IsHmiProjectTextsImportProbeAccepted(targets, collateral) ? "accepted" : "rejected"));
                if (!IsHmiProjectTextsImportProbeAccepted(targets, collateral))
                {
                    writer.WriteLine("Verdict reason: imported project texts must match patched digest text, keep target relative paths stable, match patched comparable hashes, and produce no unexpected collateral rows.");
                }
                writer.WriteLine();
                writer.WriteLine("Root reports:");
                writer.WriteLine("  " + Path.Combine(Path.GetDirectoryName(path), "hmi-project-texts-import-probe-copy-targets.csv"));
                writer.WriteLine("  " + Path.Combine(Path.GetDirectoryName(path), "hmi-project-texts-import-probe-copy-object-diff.csv"));
                writer.WriteLine("  " + Path.Combine(Path.GetDirectoryName(path), "hmi-project-texts-import-probe-copy-collateral.csv"));
            }
        }

        private static bool IsHmiProjectTextsImportProbeAccepted(List<HmiProjectTextImportTarget> targets, List<HmiApplyCollateralDiffRecord> collateral)
        {
            return targets.Count > 0
                && targets.All(x => EqualsIgnoreCase(x.XlsxPatchStatus, "changed")
                    && EqualsIgnoreCase(x.ImportStatus, "ok")
                    && x.MatchesPatchedText
                    && x.MatchesPatchedComparableSha256
                    && !x.RelativePathChanged)
                && !collateral.Any(x => !x.Expected);
        }

        private static void HmiProjectTextsApplyPreflightCommand(object project, Options options)
        {
            string cloneDir = ResolveCloneProjectDirectory(options.OutDir);
            string patchedDir = ResolveRequiredInputDirectory(options.InDir);
            string sourceCultureName = "en-US";
            string targetCultureName = FirstNonEmpty(options.Language, "ru-RU");

            HmiApplyPreflightContext context = LoadHmiApplyPreflightContext(cloneDir);
            List<HmiProjectTextImportTarget> targets = LoadHmiProjectTextImportTargets(cloneDir, patchedDir, targetCultureName);
            HmiProjectTextsCopyProbeGate copyGate = ValidateHmiProjectTextsCopyProbeGate(cloneDir, patchedDir, targets);

            string preflightDir = Path.Combine(cloneDir, "_hmi_project_texts_apply_preflight", "preflight-" + DateTime.Now.ToString("yyyyMMdd-HHmmss"));
            string beforeDir = Path.Combine(preflightDir, "before");
            string beforeHmiRoot = Path.Combine(beforeDir, "_hmi");
            string beforeDigestDir = Path.Combine(beforeDir, "_hmi_metadata", "digest");
            string beforeManifestPath = Path.Combine(beforeDir, "_hmi_metadata", "hmi-objects.csv");
            Directory.CreateDirectory(preflightDir);

            InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
            HmiInventorySnapshot hmiSnapshot = CollectHmiInventory(snapshot);
            ExportHmiXml(hmiSnapshot, beforeHmiRoot, true);
            WriteHmiDigest(beforeHmiRoot, beforeDigestDir);
            List<HmiObjectManifestRecord> cloneManifest = LoadHmiObjectManifest(context.ManifestPath, context.HmiRoot);
            List<HmiObjectManifestRecord> beforeManifest = BuildHmiObjectManifest(beforeHmiRoot, beforeDigestDir);
            WriteHmiObjectManifest(beforeManifestPath, beforeManifest);
            List<HmiObjectDiffRecord> liveDiffs = BuildHmiObjectDiffs(cloneManifest, beforeManifest);

            string beforeXlsx = Path.Combine(preflightDir, "project-texts-live-" + SafeFileName(sourceCultureName + "-" + targetCultureName) + ".xlsx");
            string patchedXlsx = Path.Combine(preflightDir, "project-texts-apply-candidate-" + SafeFileName(sourceCultureName + "-" + targetCultureName) + ".xlsx");
            ExportProjectTextsWorkbook(project, beforeXlsx, sourceCultureName, targetCultureName);
            File.Copy(beforeXlsx, patchedXlsx, true);
            PatchProjectTextsWorkbook(patchedXlsx, targets, targetCultureName);

            string summaryPath = Path.Combine(cloneDir, "hmi-project-texts-apply-preflight-summary.txt");
            string targetsPath = Path.Combine(cloneDir, "hmi-project-texts-apply-preflight-targets.csv");
            string liveDiffPath = Path.Combine(cloneDir, "hmi-project-texts-apply-preflight-live-diff.csv");
            string gatePath = Path.Combine(cloneDir, "hmi-project-texts-apply-preflight-gate.csv");
            bool accepted = IsHmiProjectTextsApplyPreflightAccepted(targets, liveDiffs, copyGate);

            WriteCsv(targetsPath, HmiProjectTextsApplyPreflightTargetHeaders(), targets.Select(HmiProjectTextsApplyPreflightTargetRow));
            WriteCsv(liveDiffPath, HmiObjectDiffHeaders(), liveDiffs.Select(HmiObjectDiffRow));
            WriteCsv(gatePath, HmiProjectTextsCopyProbeGateHeaders(), HmiProjectTextsCopyProbeGateRows(copyGate));
            WriteJsonl(Path.Combine(preflightDir, "hmi-project-texts-apply-preflight-targets.jsonl"), targets.Select(HmiProjectTextImportTargetJsonRow));
            WriteHmiProjectTextsApplyPreflightSummary(
                summaryPath,
                options,
                patchedDir,
                preflightDir,
                sourceCultureName,
                targetCultureName,
                beforeXlsx,
                patchedXlsx,
                targets,
                liveDiffs,
                copyGate,
                accepted);

            Console.WriteLine("HMI project-texts apply preflight");
            Console.WriteLine("  Mode: read-only; no ImportProjectTexts was invoked on the open project.");
            Console.WriteLine("  Preflight directory: " + preflightDir);
            Console.WriteLine("  Project-text targets: " + targets.Count);
            Console.WriteLine("  XLSX patched: " + targets.Count(x => EqualsIgnoreCase(x.XlsxPatchStatus, "changed")));
            Console.WriteLine("  Copy-only rehearsal accepted: " + copyGate.Accepted);
            Console.WriteLine("  Live HMI diff rows: " + liveDiffs.Count(x => !EqualsIgnoreCase(x.Status, "unchanged")));
            Console.WriteLine("  Ready for guarded apply: " + accepted);
            Console.WriteLine("  Summary: " + summaryPath);
            Console.WriteLine("  Targets: " + targetsPath);
            Console.WriteLine("  Gate: " + gatePath);
        }

        private static void HmiProjectTextsApplyCommand(object project, Options options)
        {
            if (!options.Apply)
            {
                throw new InvalidOperationException("hmi-project-texts-apply requires explicit --apply. Use hmi-project-texts-apply-preflight for read-only preparation.");
            }

            string cloneDir = ResolveCloneProjectDirectory(options.OutDir);
            string patchedDir = ResolveRequiredInputDirectory(options.InDir);
            string sourceCultureName = "en-US";
            string targetCultureName = FirstNonEmpty(options.Language, "ru-RU");

            HmiApplyPreflightContext context = LoadHmiApplyPreflightContext(cloneDir);
            List<HmiProjectTextImportTarget> targets = LoadHmiProjectTextImportTargets(cloneDir, patchedDir, targetCultureName);
            HmiProjectTextsCopyProbeGate copyGate = ValidateHmiProjectTextsCopyProbeGate(cloneDir, patchedDir, targets);

            string applyDir = Path.Combine(cloneDir, "_hmi_project_texts_apply", "apply-" + DateTime.Now.ToString("yyyyMMdd-HHmmss"));
            string beforeDir = Path.Combine(applyDir, "before");
            string afterDir = Path.Combine(applyDir, "after");
            string beforeHmiRoot = Path.Combine(beforeDir, "_hmi");
            string beforeDigestDir = Path.Combine(beforeDir, "_hmi_metadata", "digest");
            string beforeManifestPath = Path.Combine(beforeDir, "_hmi_metadata", "hmi-objects.csv");
            string afterHmiRoot = Path.Combine(afterDir, "_hmi");
            string afterDigestDir = Path.Combine(afterDir, "_hmi_metadata", "digest");
            string afterManifestPath = Path.Combine(afterDir, "_hmi_metadata", "hmi-objects.csv");
            Directory.CreateDirectory(applyDir);

            InventorySnapshot beforeSnapshot = CollectInventory(project, options.ProjectPath);
            HmiInventorySnapshot beforeHmi = CollectHmiInventory(beforeSnapshot);
            ExportHmiXml(beforeHmi, beforeHmiRoot, true);
            WriteHmiDigest(beforeHmiRoot, beforeDigestDir);
            List<HmiObjectManifestRecord> cloneManifest = LoadHmiObjectManifest(context.ManifestPath, context.HmiRoot);
            List<HmiObjectManifestRecord> beforeManifest = BuildHmiObjectManifest(beforeHmiRoot, beforeDigestDir);
            WriteHmiObjectManifest(beforeManifestPath, beforeManifest);
            List<HmiObjectDiffRecord> liveDiffs = BuildHmiObjectDiffs(cloneManifest, beforeManifest);

            foreach (HmiProjectTextImportTarget target in targets)
            {
                HmiObjectManifestRecord before = FindHmiManifestByRelativePath(beforeManifest, target.RelativePath);
                target.BeforeComparableSha256 = before == null ? string.Empty : before.ComparableSha256;
            }

            string beforeXlsx = Path.Combine(applyDir, "project-texts-live-" + SafeFileName(sourceCultureName + "-" + targetCultureName) + ".xlsx");
            string candidateXlsx = Path.Combine(applyDir, "project-texts-apply-candidate-" + SafeFileName(sourceCultureName + "-" + targetCultureName) + ".xlsx");
            ExportProjectTextsWorkbook(project, beforeXlsx, sourceCultureName, targetCultureName);
            File.Copy(beforeXlsx, candidateXlsx, true);
            PatchProjectTextsWorkbook(candidateXlsx, targets, targetCultureName);

            List<HmiProjectTextsApplyGateRecord> gates = new List<HmiProjectTextsApplyGateRecord>();
            AddHmiProjectTextsApplyBeforeImportGates(
                gates,
                options,
                cloneDir,
                patchedDir,
                context.ManifestPath,
                Path.Combine(patchedDir, "_hmi_metadata", "digest"),
                sourceCultureName,
                targetCultureName,
                targets,
                copyGate,
                liveDiffs,
                beforeXlsx,
                candidateXlsx);

            bool canImport = CanImportHmiProjectTextsApply(gates);
            bool preflightAccepted = IsHmiProjectTextsApplyPreflightAccepted(targets, liveDiffs, copyGate) && canImport;
            bool importAttempted = false;
            bool importInvoked = false;
            bool savedProject = false;
            string importMessage = string.Empty;
            List<HmiObjectDiffRecord> objectDiffs = new List<HmiObjectDiffRecord>();
            List<HmiApplyCollateralDiffRecord> collateral = new List<HmiApplyCollateralDiffRecord>();

            if (preflightAccepted)
            {
                try
                {
                    importAttempted = true;
                    MethodInfo import = ImportProjectTextsWorkbook(project, candidateXlsx, options.UpdateSourceLanguage);
                    importInvoked = true;
                    importMessage = "ImportProjectTexts(FileInfo, " + options.UpdateSourceLanguage.ToString() + ") completed on the open project.";
                    AddHmiProjectTextsApplyGate(gates, "import", "import-invocation", "passed", true, false, true, importMessage, candidateXlsx, "ImportProjectTexts succeeds exactly once.", "completed");
                    foreach (HmiProjectTextImportTarget target in targets)
                    {
                        target.ImportStatus = "ok";
                        target.ImportMethod = DescribeMethod(import);
                        target.ImportMessage = importMessage;
                    }
                }
                catch (Exception ex)
                {
                    Exception actual = ex is TargetInvocationException && ex.InnerException != null ? ex.InnerException : ex;
                    importMessage = actual.GetType().Name + ": " + actual.Message;
                    AddHmiProjectTextsApplyGate(gates, "import", "import-invocation", "failed", true, false, true, importMessage, candidateXlsx, "ImportProjectTexts succeeds exactly once.", actual.GetType().Name);
                    foreach (HmiProjectTextImportTarget target in targets)
                    {
                        target.ImportStatus = "error";
                        target.ImportMessage = importMessage;
                    }
                }
            }
            else
            {
                importMessage = "Import blocked by preflight gate.";
                AddHmiProjectTextsApplyGate(gates, "import", "import-invocation", "skipped", true, false, true, importMessage, candidateXlsx, "All before-import gates passed.", "blocked");
                foreach (HmiProjectTextImportTarget target in targets)
                {
                    target.ImportStatus = "blocked";
                    target.ImportMessage = importMessage;
                }
            }

            if (importInvoked)
            {
                InventorySnapshot afterSnapshot = CollectInventory(project, options.ProjectPath);
                HmiInventorySnapshot afterHmi = CollectHmiInventory(afterSnapshot);
                ExportHmiXml(afterHmi, afterHmiRoot, true);
                WriteHmiDigest(afterHmiRoot, afterDigestDir);
                List<HmiObjectManifestRecord> afterManifest = BuildHmiObjectManifest(afterHmiRoot, afterDigestDir);
                WriteHmiObjectManifest(afterManifestPath, afterManifest);

                objectDiffs = BuildHmiObjectDiffs(beforeManifest, afterManifest);
                HmiExpectedDigestChanges expected = LoadExpectedDigestChangesFromPreflightCollateral(patchedDir);
                collateral = BuildHmiDigestCollateralDiff(beforeDigestDir, afterDigestDir, expected);
                PopulateHmiProjectTextImportResultTargets(targets, patchedDir, afterDigestDir, afterManifest);
                AddHmiProjectTextsApplyAfterImportGates(gates, targets, objectDiffs, collateral, afterManifestPath, afterDigestDir);
            }

            bool accepted = IsHmiProjectTextsApplyAccepted(targets, collateral, copyGate, preflightAccepted, importInvoked) && IsHmiProjectTextsApplyAcceptedByGates(gates, importInvoked);
            if (accepted && options.Save)
            {
                SaveProject(project);
                savedProject = true;
            }
            AddHmiProjectTextsApplySavePolicyGate(gates, accepted, importAttempted, importInvoked, savedProject, options.Save);

            string summaryPath = Path.Combine(cloneDir, "hmi-project-texts-apply-summary.txt");
            string targetsPath = Path.Combine(cloneDir, "hmi-project-texts-apply-targets.csv");
            string liveDiffPath = Path.Combine(cloneDir, "hmi-project-texts-apply-live-diff.csv");
            string objectDiffPath = Path.Combine(cloneDir, "hmi-project-texts-apply-object-diff.csv");
            string collateralPath = Path.Combine(cloneDir, "hmi-project-texts-apply-collateral.csv");
            string gatePath = Path.Combine(cloneDir, "hmi-project-texts-apply-gate.csv");
            string copyGatePath = Path.Combine(cloneDir, "hmi-project-texts-apply-copy-gate.csv");
            string gateJsonPath = Path.Combine(applyDir, "hmi-project-texts-apply-final-gates.jsonl");

            WriteCsv(targetsPath, HmiProjectTextsApplyTargetHeaders(), targets.Select(HmiProjectTextsApplyTargetRow));
            WriteCsv(liveDiffPath, HmiObjectDiffHeaders(), liveDiffs.Select(HmiObjectDiffRow));
            WriteCsv(objectDiffPath, HmiObjectDiffHeaders(), objectDiffs.Select(HmiObjectDiffRow));
            WriteCsv(collateralPath, HmiApplyCollateralDiffHeaders(), collateral.Select(HmiApplyCollateralDiffRow));
            WriteCsv(gatePath, HmiProjectTextsApplyGateHeaders(), gates.Select(HmiProjectTextsApplyGateRow));
            WriteCsv(copyGatePath, HmiProjectTextsCopyProbeGateHeaders(), HmiProjectTextsCopyProbeGateRows(copyGate));
            WriteJsonl(Path.Combine(applyDir, "hmi-project-texts-apply-targets.jsonl"), targets.Select(HmiProjectTextImportTargetJsonRow));
            WriteJsonl(Path.Combine(applyDir, "hmi-project-texts-apply-collateral.jsonl"), collateral.Select(HmiApplyCollateralDiffJsonRow));
            WriteJsonl(gateJsonPath, gates.Select(HmiProjectTextsApplyGateJsonRow));
            WriteHmiProjectTextsApplySummary(
                summaryPath,
                options,
                patchedDir,
                applyDir,
                sourceCultureName,
                targetCultureName,
                beforeXlsx,
                candidateXlsx,
                targets,
                liveDiffs,
                objectDiffs,
                collateral,
                copyGate,
                gates,
                preflightAccepted,
                canImport,
                importAttempted,
                importInvoked,
                accepted,
                savedProject,
                importMessage);

            Console.WriteLine("HMI project-texts guarded apply");
            Console.WriteLine("  Apply directory: " + applyDir);
            Console.WriteLine("  Project-text targets: " + targets.Count);
            Console.WriteLine("  Before-import gates accepted: " + canImport);
            Console.WriteLine("  Preflight gate accepted: " + preflightAccepted);
            Console.WriteLine("  Import attempted: " + importAttempted);
            Console.WriteLine("  Import invoked: " + importInvoked);
            Console.WriteLine("  Import ok: " + targets.Count(x => EqualsIgnoreCase(x.ImportStatus, "ok")));
            Console.WriteLine("  Matches patched text: " + targets.Count(x => x.MatchesPatchedText));
            Console.WriteLine("  Matches patched comparable hash: " + targets.Count(x => x.MatchesPatchedComparableSha256));
            Console.WriteLine("  Targets with relative path change: " + targets.Count(x => x.RelativePathChanged));
            Console.WriteLine("  Unexpected collateral rows: " + collateral.Count(x => !x.Expected));
            Console.WriteLine("  Saved project: " + savedProject);
            Console.WriteLine("  Apply verdict: " + (accepted ? "accepted" : "rejected"));
            Console.WriteLine("  Summary: " + summaryPath);
            Console.WriteLine("  Targets: " + targetsPath);
            Console.WriteLine("  Collateral: " + collateralPath);
            Console.WriteLine("  Gates: " + gatePath);

            if (!preflightAccepted)
            {
                throw new InvalidOperationException("hmi-project-texts-apply blocked before import. Inspect: " + summaryPath);
            }

            if (!accepted)
            {
                throw new InvalidOperationException("hmi-project-texts-apply completed but post-apply gate rejected the result. Inspect: " + summaryPath);
            }
        }

        private static HmiProjectTextsCopyProbeGate ValidateHmiProjectTextsCopyProbeGate(string cloneDir, string patchedDir, List<HmiProjectTextImportTarget> targets)
        {
            HmiProjectTextsCopyProbeGate gate = new HmiProjectTextsCopyProbeGate
            {
                TargetsPath = Path.Combine(cloneDir, "hmi-project-texts-import-probe-copy-targets.csv"),
                CollateralPath = Path.Combine(cloneDir, "hmi-project-texts-import-probe-copy-collateral.csv"),
                SummaryPath = Path.Combine(cloneDir, "hmi-project-texts-import-probe-copy-summary.txt"),
                ExpectedPatchedDir = NormalizeComparablePath(patchedDir)
            };

            if (!File.Exists(gate.SummaryPath))
            {
                gate.Issues.Add("COPY_PROBE_SUMMARY_MISSING: " + gate.SummaryPath);
            }

            if (!File.Exists(gate.TargetsPath))
            {
                gate.Issues.Add("COPY_PROBE_TARGETS_MISSING: " + gate.TargetsPath);
            }

            if (!File.Exists(gate.CollateralPath))
            {
                gate.Issues.Add("COPY_PROBE_COLLATERAL_MISSING: " + gate.CollateralPath);
            }

            if (File.Exists(gate.SummaryPath))
            {
                gate.ProbeSourceCulture = ReadSummaryValue(gate.SummaryPath, "Source culture");
                gate.ProbeTargetCulture = ReadSummaryValue(gate.SummaryPath, "Target culture");
                gate.ProbeUpdateSourceLanguage = EqualsIgnoreCase(ReadSummaryValue(gate.SummaryPath, "Import uses updateSourceLanguage"), "True");
                gate.ProbePatchedDir = NormalizeComparablePath(ReadSummaryValue(gate.SummaryPath, "Patched preflight directory"));
                gate.PatchedDirMatches = !string.IsNullOrWhiteSpace(gate.ProbePatchedDir)
                    && EqualsIgnoreCase(gate.ProbePatchedDir, gate.ExpectedPatchedDir);
                if (!gate.PatchedDirMatches)
                {
                    gate.Issues.Add("COPY_PROBE_PATCHED_DIR_MISMATCH: expected '" + gate.ExpectedPatchedDir + "' but summary has '" + gate.ProbePatchedDir + "'.");
                }
            }

            if (gate.Issues.Count > 0)
            {
                gate.Message = string.Join(" | ", gate.Issues.ToArray());
                return gate;
            }

            List<Dictionary<string, string>> copyTargets = ReadCsv(gate.TargetsPath);
            List<Dictionary<string, string>> collateral = ReadCsv(gate.CollateralPath);
            gate.TargetRows = copyTargets.Count;
            gate.UnexpectedCollateralRows = collateral.Count(x => !EqualsIgnoreCase(GetCsvValue(x, "Expected"), "True"));
            if (gate.UnexpectedCollateralRows > 0)
            {
                gate.Issues.Add("COPY_PROBE_UNEXPECTED_COLLATERAL: " + gate.UnexpectedCollateralRows);
            }

            Dictionary<string, Dictionary<string, string>> copyByKey = copyTargets
                .GroupBy(HmiProjectTextCopyProbeRowDigestKey, StringComparer.OrdinalIgnoreCase)
                .ToDictionary(x => x.Key, x => x.First(), StringComparer.OrdinalIgnoreCase);

            foreach (HmiProjectTextImportTarget target in targets)
            {
                Dictionary<string, string> row;
                if (!copyByKey.TryGetValue(HmiProjectTextImportTargetIdentity(target), out row))
                {
                    target.CopyProbeStatus = "missing";
                    target.CopyProbeMessage = "Copy-only project-texts probe does not contain this target.";
                    gate.Issues.Add("COPY_PROBE_TARGET_MISSING: " + HmiProjectTextImportTargetIdentity(target));
                    continue;
                }

                List<string> targetIssues = new List<string>();
                RequireCopyProbeField(row, "XlsxPatchStatus", "changed", targetIssues);
                RequireCopyProbeField(row, "ImportStatus", "ok", targetIssues);
                RequireCopyProbeField(row, "MatchesPatchedText", "True", targetIssues);
                RequireCopyProbeField(row, "MatchesPatchedComparableSha256", "True", targetIssues);
                RequireCopyProbeField(row, "RelativePathChanged", "False", targetIssues);
                if (!string.Equals(GetCsvValue(row, "BeforeText"), target.BeforeText, StringComparison.Ordinal))
                {
                    targetIssues.Add("BeforeText mismatch.");
                }

                if (!string.Equals(GetCsvValue(row, "PatchedText"), target.PatchedText, StringComparison.Ordinal))
                {
                    targetIssues.Add("PatchedText mismatch.");
                }

                if (!EqualsIgnoreCase(GetCsvValue(row, "Culture"), target.Culture))
                {
                    targetIssues.Add("Culture mismatch.");
                }

                target.CopyProbeStatus = targetIssues.Count == 0 ? "accepted" : "rejected";
                target.CopyProbeMessage = targetIssues.Count == 0 ? "Copy-only rehearsal accepted this target." : string.Join(" | ", targetIssues.ToArray());
                if (targetIssues.Count > 0)
                {
                    gate.Issues.Add("COPY_PROBE_TARGET_REJECTED: " + HmiProjectTextImportTargetIdentity(target) + " " + target.CopyProbeMessage);
                }
            }

            gate.Accepted = gate.Issues.Count == 0 && targets.Count > 0;
            gate.Message = gate.Accepted ? "Copy-only project-texts rehearsal accepted all targets." : string.Join(" | ", gate.Issues.ToArray());
            return gate;
        }

        private static string ReadSummaryValue(string path, string label)
        {
            if (!File.Exists(path))
            {
                return string.Empty;
            }

            foreach (string line in File.ReadAllLines(path, Encoding.UTF8))
            {
                if (line.StartsWith(label + ":", StringComparison.OrdinalIgnoreCase))
                {
                    return line.Substring(label.Length + 1).Trim();
                }
            }

            return string.Empty;
        }

        private static void RequireCopyProbeField(Dictionary<string, string> row, string field, string expected, List<string> issues)
        {
            if (!EqualsIgnoreCase(GetCsvValue(row, field), expected))
            {
                issues.Add(field + " expected '" + expected + "' but was '" + GetCsvValue(row, field) + "'.");
            }
        }

        private static string HmiProjectTextCopyProbeRowDigestKey(Dictionary<string, string> row)
        {
            string reportName = FirstNonEmpty(GetCsvValue(row, "DigestReport"), InferHmiProjectTextDigestReport(row));
            return reportName + "|" + HmiDigestRowKey(reportName, row);
        }

        private static string HmiProjectTextImportTargetIdentity(HmiProjectTextImportTarget target)
        {
            return HmiProjectTextTargetDigestReport(target) + "|" + target.DigestKey;
        }

        private static string HmiProjectTextTargetDigestReport(HmiProjectTextImportTarget target)
        {
            return FirstNonEmpty(target.DigestReport, EqualsIgnoreCase(target.TargetKind, "ScreenItemText") ? "hmi-screen-items.csv" : "hmi-text-list-items.csv");
        }

        private static string InferHmiProjectTextDigestReport(Dictionary<string, string> row)
        {
            if (EqualsIgnoreCase(GetCsvValue(row, "TargetKind"), "ScreenItemText") || !string.IsNullOrWhiteSpace(GetCsvValue(row, "ScreenName")))
            {
                return "hmi-screen-items.csv";
            }

            return "hmi-text-list-items.csv";
        }

        private static bool IsHmiProjectTextsApplyPreflightAccepted(List<HmiProjectTextImportTarget> targets, List<HmiObjectDiffRecord> liveDiffs, HmiProjectTextsCopyProbeGate copyGate)
        {
            return copyGate.Accepted
                && targets.Count > 0
                && targets.All(x => EqualsIgnoreCase(x.XlsxPatchStatus, "changed") && EqualsIgnoreCase(x.CopyProbeStatus, "accepted"))
                && !liveDiffs.Any(x => !EqualsIgnoreCase(x.Status, "unchanged"));
        }

        private static void PopulateHmiProjectTextImportResultTargets(List<HmiProjectTextImportTarget> targets, string patchedDir, string afterDigestDir, List<HmiObjectManifestRecord> afterManifest)
        {
            string patchedDigestDir = Path.Combine(patchedDir, "_hmi_metadata", "digest");
            string patchedHmiRoot = Path.Combine(patchedDir, "_hmi");
            List<HmiObjectManifestRecord> patchedManifest = BuildHmiObjectManifest(patchedHmiRoot, patchedDigestDir);
            Dictionary<string, Dictionary<string, Dictionary<string, string>>> afterRowsByReport =
                new Dictionary<string, Dictionary<string, Dictionary<string, string>>>(StringComparer.OrdinalIgnoreCase);

            foreach (HmiProjectTextImportTarget target in targets)
            {
                string reportName = HmiProjectTextTargetDigestReport(target);
                HmiObjectManifestRecord patched = FindHmiManifestByRelativePath(patchedManifest, target.RelativePath);
                HmiObjectManifestRecord after = FindHmiManifestForProjectTextTarget(afterManifest, target);
                target.PatchedComparableSha256 = patched == null ? string.Empty : patched.ComparableSha256;
                target.AfterComparableSha256 = after == null ? string.Empty : after.ComparableSha256;
                target.AfterRelativePath = after == null ? string.Empty : after.RelativePath;
                target.RelativePathChanged = after != null && !EqualsIgnoreCase(NormalizeHmiRelativePath(target.RelativePath), NormalizeHmiRelativePath(after.RelativePath));
                target.MatchesPatchedComparableSha256 = !string.IsNullOrWhiteSpace(target.PatchedComparableSha256)
                    && EqualsIgnoreCase(target.AfterComparableSha256, target.PatchedComparableSha256);

                Dictionary<string, string> afterRow;
                Dictionary<string, Dictionary<string, string>> afterByKey = GetHmiDigestRowsByKey(afterRowsByReport, afterDigestDir, reportName);
                if (afterByKey.TryGetValue(target.DigestKey, out afterRow))
                {
                    Dictionary<string, string> afterTexts = ParseHmiDigestTextMap(GetHmiProjectTextDigestTextSummary(afterRow, reportName));
                    target.AfterText = GetTextMapValue(afterTexts, target.Culture);
                    target.MatchesPatchedText = string.Equals(target.AfterText, target.PatchedText, StringComparison.Ordinal);
                }
            }
        }

        private static Dictionary<string, Dictionary<string, string>> GetHmiDigestRowsByKey(
            Dictionary<string, Dictionary<string, Dictionary<string, string>>> cache,
            string digestDir,
            string reportName)
        {
            Dictionary<string, Dictionary<string, string>> rows;
            if (cache.TryGetValue(reportName, out rows))
            {
                return rows;
            }

            rows = LoadRequiredCsv(Path.Combine(digestDir, reportName), "After digest was not produced.")
                .GroupBy(x => HmiDigestRowKey(reportName, x), StringComparer.OrdinalIgnoreCase)
                .ToDictionary(x => x.Key, x => x.First(), StringComparer.OrdinalIgnoreCase);
            cache[reportName] = rows;
            return rows;
        }

        private static string GetHmiProjectTextDigestTextSummary(Dictionary<string, string> row, string reportName)
        {
            return EqualsIgnoreCase(reportName, "hmi-screen-items.csv")
                ? GetCsvValue(row, "Text")
                : GetCsvValue(row, "Texts");
        }

        private static bool IsHmiProjectTextsApplyAccepted(
            List<HmiProjectTextImportTarget> targets,
            List<HmiApplyCollateralDiffRecord> collateral,
            HmiProjectTextsCopyProbeGate copyGate,
            bool preflightAccepted,
            bool importInvoked)
        {
            return preflightAccepted
                && importInvoked
                && copyGate.Accepted
                && targets.Count > 0
                && targets.All(x => EqualsIgnoreCase(x.XlsxPatchStatus, "changed")
                    && EqualsIgnoreCase(x.CopyProbeStatus, "accepted")
                    && EqualsIgnoreCase(x.ImportStatus, "ok")
                    && x.MatchesPatchedText
                    && x.MatchesPatchedComparableSha256
                    && !x.RelativePathChanged)
                && !collateral.Any(x => !x.Expected);
        }

        private static void AddHmiProjectTextsApplyBeforeImportGates(
            List<HmiProjectTextsApplyGateRecord> gates,
            Options options,
            string cloneDir,
            string patchedDir,
            string manifestPath,
            string patchedDigestDir,
            string sourceCultureName,
            string targetCultureName,
            List<HmiProjectTextImportTarget> targets,
            HmiProjectTextsCopyProbeGate copyGate,
            List<HmiObjectDiffRecord> liveDiffs,
            string beforeXlsx,
            string candidateXlsx)
        {
            AddHmiProjectTextsApplyGate(
                gates,
                "before-import",
                "command-intent",
                options.Apply && !string.IsNullOrWhiteSpace(options.InDir) && !string.IsNullOrWhiteSpace(targetCultureName) ? "passed" : "failed",
                true,
                true,
                false,
                "hmi-project-texts-apply requires explicit --apply, --in and a target language.",
                patchedDir,
                "--apply=true; --in present; language present",
                "--apply=" + options.Apply + "; --in=" + EmptyIfNull(options.InDir) + "; language=" + EmptyIfNull(targetCultureName));

            AddHmiProjectTextsApplyGate(
                gates,
                "before-import",
                "backup-required",
                options.NoBackup ? "failed" : "passed",
                true,
                true,
                false,
                options.NoBackup
                    ? "Production HMI ProjectTexts apply cannot run with --no-backup."
                    : "Backup protection is enabled for this write command.",
                options.ProjectPath,
                "--no-backup=false",
                "--no-backup=" + options.NoBackup);

            string hmiRoot = Path.Combine(cloneDir, "_hmi");
            string baseDigestDir = Path.Combine(cloneDir, "_hmi_metadata", "digest");
            List<string> workspaceIssues = new List<string>();
            if (!Directory.Exists(hmiRoot))
            {
                workspaceIssues.Add("missing _hmi");
            }
            if (!Directory.Exists(baseDigestDir))
            {
                workspaceIssues.Add("missing _hmi_metadata/digest");
            }
            if (!File.Exists(manifestPath))
            {
                workspaceIssues.Add("missing hmi-objects.csv");
            }
            if (!Directory.Exists(patchedDigestDir))
            {
                workspaceIssues.Add("missing patched _hmi_metadata/digest");
            }
            if (targets.Count == 0)
            {
                workspaceIssues.Add("no project-text targets");
            }

            AddHmiProjectTextsApplyGate(
                gates,
                "before-import",
                "workspace-inputs",
                workspaceIssues.Count == 0 ? "passed" : "failed",
                true,
                true,
                false,
                workspaceIssues.Count == 0 ? "Clone workspace and patched digest are present." : string.Join(" | ", workspaceIssues.ToArray()),
                cloneDir,
                "clone baseline, patched digest and targets exist",
                "targets=" + targets.Count.ToString(CultureInfo.InvariantCulture));

            bool copyProbeFilesPresent = File.Exists(copyGate.SummaryPath) && File.Exists(copyGate.TargetsPath) && File.Exists(copyGate.CollateralPath);
            AddHmiProjectTextsApplyGate(
                gates,
                "before-import",
                "copy-probe-files",
                copyProbeFilesPresent ? "passed" : "failed",
                true,
                true,
                false,
                copyProbeFilesPresent ? "Copy-only rehearsal reports are present." : "Copy-only rehearsal reports are missing.",
                copyGate.SummaryPath,
                "summary, targets and collateral reports exist",
                "summary=" + File.Exists(copyGate.SummaryPath) + "; targets=" + File.Exists(copyGate.TargetsPath) + "; collateral=" + File.Exists(copyGate.CollateralPath));

            AddHmiProjectTextsApplyGate(
                gates,
                "before-import",
                "copy-probe-patched-dir",
                copyGate.PatchedDirMatches ? "passed" : "failed",
                true,
                true,
                false,
                copyGate.PatchedDirMatches ? "Copy-only rehearsal was run for this patched directory." : "Copy-only rehearsal does not match the current patched directory.",
                copyGate.SummaryPath,
                copyGate.ExpectedPatchedDir,
                copyGate.ProbePatchedDir);

            int acceptedCopyTargets = targets.Count(x => EqualsIgnoreCase(x.CopyProbeStatus, "accepted"));
            AddHmiProjectTextsApplyGate(
                gates,
                "before-import",
                "copy-probe-targets",
                copyGate.Accepted && targets.Count > 0 && acceptedCopyTargets == targets.Count ? "passed" : "failed",
                true,
                true,
                false,
                copyGate.Accepted ? "Copy-only rehearsal accepted all current targets." : FirstNonEmpty(copyGate.Message, "Copy-only rehearsal rejected one or more targets."),
                copyGate.TargetsPath,
                "accepted targets=" + targets.Count.ToString(CultureInfo.InvariantCulture),
                "accepted targets=" + acceptedCopyTargets.ToString(CultureInfo.InvariantCulture) + "; copy rows=" + copyGate.TargetRows.ToString(CultureInfo.InvariantCulture));

            AddHmiProjectTextsApplyGate(
                gates,
                "before-import",
                "copy-probe-collateral",
                copyGate.Accepted && copyGate.UnexpectedCollateralRows == 0 ? "passed" : "failed",
                true,
                true,
                false,
                copyGate.UnexpectedCollateralRows == 0 ? "Copy-only rehearsal produced no unexpected collateral." : "Copy-only rehearsal produced unexpected collateral.",
                copyGate.CollateralPath,
                "unexpected collateral rows=0",
                "unexpected collateral rows=" + copyGate.UnexpectedCollateralRows.ToString(CultureInfo.InvariantCulture));

            int changedLiveRows = liveDiffs.Count(x => !EqualsIgnoreCase(x.Status, "unchanged"));
            AddHmiProjectTextsApplyGate(
                gates,
                "before-import",
                "live-baseline",
                changedLiveRows == 0 ? "passed" : "failed",
                true,
                true,
                false,
                changedLiveRows == 0 ? "Live HMI snapshot matches clone baseline." : "Live HMI baseline is dirty; run hmi-sync-clone or revert manual HMI changes before apply.",
                manifestPath,
                "changed live diff rows=0",
                "changed live diff rows=" + changedLiveRows.ToString(CultureInfo.InvariantCulture));

            int changedXlsxTargets = targets.Count(x => EqualsIgnoreCase(x.XlsxPatchStatus, "changed"));
            string candidateEvidence = File.Exists(candidateXlsx)
                ? "sha256=" + ComputeFileSha256(candidateXlsx) + "; bytes=" + new FileInfo(candidateXlsx).Length.ToString(CultureInfo.InvariantCulture)
                : "missing";
            AddHmiProjectTextsApplyGate(
                gates,
                "before-import",
                "workbook-patch",
                targets.Count > 0 && changedXlsxTargets == targets.Count ? "passed" : "failed",
                true,
                true,
                false,
                targets.Count > 0 && changedXlsxTargets == targets.Count ? "Live ProjectTexts workbook candidate was patched only for requested targets." : "Not all ProjectTexts targets were patched in the candidate workbook.",
                candidateXlsx,
                "changed XLSX rows=" + targets.Count.ToString(CultureInfo.InvariantCulture),
                "changed XLSX rows=" + changedXlsxTargets.ToString(CultureInfo.InvariantCulture) + "; " + candidateEvidence);

            AddHmiProjectTextsLanguageModeGate(gates, sourceCultureName, targetCultureName, options.UpdateSourceLanguage, copyGate);
        }

        private static void AddHmiProjectTextsLanguageModeGate(
            List<HmiProjectTextsApplyGateRecord> gates,
            string sourceCultureName,
            string targetCultureName,
            bool updateSourceLanguage,
            HmiProjectTextsCopyProbeGate copyGate)
        {
            string status;
            string message;
            if (string.IsNullOrWhiteSpace(targetCultureName))
            {
                status = "failed";
                message = "Target language is empty.";
            }
            else if (EqualsIgnoreCase(targetCultureName, sourceCultureName))
            {
                bool copyProbeConfirmsSourceLanguage = updateSourceLanguage
                    && copyGate != null
                    && copyGate.Accepted
                    && copyGate.ProbeUpdateSourceLanguage
                    && EqualsIgnoreCase(copyGate.ProbeSourceCulture, sourceCultureName)
                    && EqualsIgnoreCase(copyGate.ProbeTargetCulture, targetCultureName);
                status = copyProbeConfirmsSourceLanguage ? "passed" : "failed";
                message = copyProbeConfirmsSourceLanguage
                    ? "Source-language ProjectTexts apply is allowed by an accepted copy-only rehearsal with updateSourceLanguage=True."
                    : "Source-language ProjectTexts apply requires --update-source-language and an accepted source-language copy-only rehearsal.";
            }
            else if (updateSourceLanguage)
            {
                status = "failed";
                message = "--update-source-language is not allowed for target-language ProjectTexts apply.";
            }
            else
            {
                status = "passed";
                message = "Target-language ProjectTexts apply uses ImportProjectTexts(FileInfo, false).";
            }

            AddHmiProjectTextsApplyGate(
                gates,
                "before-import",
                "language-mode",
                status,
                true,
                true,
                false,
                message,
                string.Empty,
                "target language differs from source and updateSourceLanguage=false",
                "source=" + EmptyIfNull(sourceCultureName) + "; target=" + EmptyIfNull(targetCultureName) + "; updateSourceLanguage=" + updateSourceLanguage);
        }

        private static void AddHmiProjectTextsApplyAfterImportGates(
            List<HmiProjectTextsApplyGateRecord> gates,
            List<HmiProjectTextImportTarget> targets,
            List<HmiObjectDiffRecord> objectDiffs,
            List<HmiApplyCollateralDiffRecord> collateral,
            string afterManifestPath,
            string afterDigestDir)
        {
            AddHmiProjectTextsApplyGate(
                gates,
                "after-import",
                "after-export",
                File.Exists(afterManifestPath) && Directory.Exists(afterDigestDir) ? "passed" : "failed",
                true,
                false,
                true,
                "After-import HMI export/digest artifacts were produced.",
                afterManifestPath,
                "after manifest and digest exist",
                "manifest=" + File.Exists(afterManifestPath) + "; digest=" + Directory.Exists(afterDigestDir));

            int matchingText = targets.Count(x => x.MatchesPatchedText);
            AddHmiProjectTextsApplyGate(
                gates,
                "after-import",
                "target-text-match",
                targets.Count > 0 && matchingText == targets.Count ? "passed" : "failed",
                true,
                false,
                true,
                "After-import digest text must match patched text for every target.",
                afterDigestDir,
                "matches=" + targets.Count.ToString(CultureInfo.InvariantCulture),
                "matches=" + matchingText.ToString(CultureInfo.InvariantCulture));

            int matchingHash = targets.Count(x => x.MatchesPatchedComparableSha256);
            AddHmiProjectTextsApplyGate(
                gates,
                "after-import",
                "target-hash-match",
                targets.Count > 0 && matchingHash == targets.Count ? "passed" : "failed",
                true,
                false,
                true,
                "After-import comparable HMI XML hash must match patched snapshot for every target.",
                afterManifestPath,
                "matches=" + targets.Count.ToString(CultureInfo.InvariantCulture),
                "matches=" + matchingHash.ToString(CultureInfo.InvariantCulture));

            int relativePathChanges = targets.Count(x => x.RelativePathChanged);
            AddHmiProjectTextsApplyGate(
                gates,
                "after-import",
                "relative-path-stability",
                relativePathChanges == 0 ? "passed" : "failed",
                true,
                false,
                true,
                relativePathChanges == 0 ? "Target HMI relative paths stayed stable." : "At least one target HMI relative path changed after import.",
                afterManifestPath,
                "relative path changes=0",
                "relative path changes=" + relativePathChanges.ToString(CultureInfo.InvariantCulture));

            int unexpectedCollateral = collateral.Count(x => !x.Expected);
            AddHmiProjectTextsApplyGate(
                gates,
                "after-import",
                "unexpected-collateral",
                unexpectedCollateral == 0 ? "passed" : "failed",
                true,
                false,
                true,
                unexpectedCollateral == 0 ? "Post-import digest collateral contains only expected rows." : "Post-import digest collateral contains unexpected rows.",
                afterDigestDir,
                "unexpected collateral rows=0",
                "unexpected collateral rows=" + unexpectedCollateral.ToString(CultureInfo.InvariantCulture));

            AddHmiProjectTextsApplyGate(
                gates,
                "after-import",
                "object-diff-count",
                "passed",
                false,
                false,
                true,
                "Object diff rows are reported for audit; collateral digest is the blocking safety gate.",
                afterManifestPath,
                "audit only",
                "changed object diff rows=" + objectDiffs.Count(x => !EqualsIgnoreCase(x.Status, "unchanged")).ToString(CultureInfo.InvariantCulture));
        }

        private static void AddHmiProjectTextsApplySavePolicyGate(
            List<HmiProjectTextsApplyGateRecord> gates,
            bool accepted,
            bool importAttempted,
            bool importInvoked,
            bool savedProject,
            bool saveRequested)
        {
            string status = (!savedProject || (accepted && saveRequested)) ? "passed" : "failed";
            string message;
            if (savedProject)
            {
                message = "Project was saved only after accepted apply and explicit --save.";
            }
            else if (!importAttempted)
            {
                message = "Project was not modified by this command; save skipped.";
            }
            else if (!accepted)
            {
                message = "Project was not saved because apply verdict was rejected.";
            }
            else
            {
                message = "Project was left unsaved because --save was not requested.";
            }

            AddHmiProjectTextsApplyGate(
                gates,
                "save",
                "save-policy",
                status,
                true,
                false,
                true,
                message,
                string.Empty,
                "SaveProject only when accepted and --save=true",
                "accepted=" + accepted + "; importAttempted=" + importAttempted + "; importCompleted=" + importInvoked + "; saveRequested=" + saveRequested + "; saved=" + savedProject);
        }

        private static void AddHmiProjectTextsApplyGate(
            List<HmiProjectTextsApplyGateRecord> gates,
            string phase,
            string gate,
            string status,
            bool blocking,
            bool beforeImport,
            bool afterImport,
            string message,
            string evidencePath,
            string expected,
            string actual)
        {
            gates.Add(new HmiProjectTextsApplyGateRecord
            {
                Phase = phase,
                Gate = gate,
                Status = status,
                Blocking = blocking,
                BeforeImport = beforeImport,
                AfterImport = afterImport,
                Message = message,
                EvidencePath = EmptyIfNull(evidencePath),
                Expected = EmptyIfNull(expected),
                Actual = EmptyIfNull(actual)
            });
        }

        private static bool CanImportHmiProjectTextsApply(List<HmiProjectTextsApplyGateRecord> gates)
        {
            return !gates.Any(x => x.Blocking && x.BeforeImport && EqualsIgnoreCase(x.Status, "failed"));
        }

        private static bool IsHmiProjectTextsApplyAcceptedByGates(List<HmiProjectTextsApplyGateRecord> gates, bool importInvoked)
        {
            return importInvoked && !gates.Any(x => x.Blocking && EqualsIgnoreCase(x.Status, "failed"));
        }

        private static string HmiProjectTextsApplyState(bool canImport, bool importAttempted, bool importInvoked, bool accepted)
        {
            if (accepted)
            {
                return "accepted_after_import";
            }

            if (!canImport || !importAttempted)
            {
                return "blocked_before_import";
            }

            if (importAttempted && !importInvoked)
            {
                return "import_error";
            }

            return "rejected_after_import";
        }

        private static string HmiProjectTextsProjectModifiedState(bool importAttempted, bool importInvoked)
        {
            if (!importAttempted)
            {
                return "false";
            }

            return importInvoked ? "true" : "unknown";
        }

        private static string HmiProjectTextsRecoveryInstruction(bool importAttempted, bool accepted)
        {
            if (!importAttempted)
            {
                return "No import was attempted; fix the failed before-import gates and re-run preflight/copy probe.";
            }

            if (accepted)
            {
                return "No recovery required.";
            }

            return "Import was attempted but final gates rejected the result. Do not save the project; close without saving or restore the pre-apply backup.";
        }

