            List<HmiObjectDiffRecord> liveDiffs,
            HmiProjectTextsCopyProbeGate copyGate,
            bool accepted)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("HMI project-texts apply preflight");
                writer.WriteLine("Generated: " + DateTime.Now.ToString("o"));
                writer.WriteLine("Mode: read-only; no ImportProjectTexts was invoked on the open project.");
                writer.WriteLine("Project: " + options.ProjectPath);
                writer.WriteLine("Clone directory: " + ResolveCloneProjectDirectory(options.OutDir));
                writer.WriteLine("Patched preflight directory: " + patchedDir);
                writer.WriteLine("Preflight report directory: " + preflightDir);
                writer.WriteLine("Source culture: " + sourceCultureName);
                writer.WriteLine("Target culture: " + targetCultureName);
                writer.WriteLine("Live project texts XLSX: " + beforeXlsx);
                writer.WriteLine("Apply candidate XLSX: " + patchedXlsx);
                writer.WriteLine("Planned import uses updateSourceLanguage: " + options.UpdateSourceLanguage);
                writer.WriteLine();
                writer.WriteLine("Project-text targets: " + targets.Count);
                writer.WriteLine("XLSX patched rows: " + targets.Count(x => EqualsIgnoreCase(x.XlsxPatchStatus, "changed")));
                writer.WriteLine("Copy-only rehearsal accepted: " + copyGate.Accepted);
                writer.WriteLine("Copy-only unexpected collateral rows: " + copyGate.UnexpectedCollateralRows);
                writer.WriteLine("Live HMI changed diff rows: " + liveDiffs.Count(x => !EqualsIgnoreCase(x.Status, "unchanged")));
                writer.WriteLine("Ready for guarded apply: " + accepted);
                if (!accepted)
                {
                    writer.WriteLine("Verdict reason: requires accepted copy-only rehearsal, clean live HMI diff, and changed XLSX target cells only.");
                    writer.WriteLine("Copy-only gate message: " + copyGate.Message);
                }

                writer.WriteLine();
                writer.WriteLine("Root reports:");
                writer.WriteLine("  " + Path.Combine(Path.GetDirectoryName(path), "hmi-project-texts-apply-preflight-targets.csv"));
                writer.WriteLine("  " + Path.Combine(Path.GetDirectoryName(path), "hmi-project-texts-apply-preflight-live-diff.csv"));
                writer.WriteLine("  " + Path.Combine(Path.GetDirectoryName(path), "hmi-project-texts-apply-preflight-gate.csv"));
