                writer.WriteLine("Project-text targets: " + targets.Count);
                writer.WriteLine("XLSX patched rows: " + targets.Count(x => EqualsIgnoreCase(x.XlsxPatchStatus, "changed")));
                writer.WriteLine("Copy-only rehearsal accepted: " + copyGate.Accepted);
                writer.WriteLine("Preflight gate accepted: " + preflightAccepted);
                writer.WriteLine("Final gate rows: " + gates.Count);
                writer.WriteLine("Failed blocking gate rows: " + gates.Count(x => x.Blocking && EqualsIgnoreCase(x.Status, "failed")));
                writer.WriteLine("Live HMI changed diff rows before import: " + liveDiffs.Count(x => !EqualsIgnoreCase(x.Status, "unchanged")));
