                {
                    writer.WriteLine("Verdict reason: requires accepted before-import gates, successful import, target text/hash match, stable relative paths, and no unexpected collateral.");
                    writer.WriteLine("Copy-only gate message: " + copyGate.Message);
                    IEnumerable<HmiProjectTextsApplyGateRecord> failedGates = gates.Where(x => x.Blocking && EqualsIgnoreCase(x.Status, "failed"));
                    foreach (HmiProjectTextsApplyGateRecord gate in failedGates)
