                writer.WriteLine("  " + Path.Combine(Path.GetDirectoryName(path), "hmi-project-texts-apply-gate.csv"));
                writer.WriteLine("  " + Path.Combine(Path.GetDirectoryName(path), "hmi-project-texts-apply-copy-gate.csv"));
            }
        }

        private static void WriteHmiApplyPreflight(string cloneDir, string patchPath)
        {
            Directory.CreateDirectory(cloneDir);

            HmiApplyPreflightContext context = LoadHmiApplyPreflightContext(cloneDir);
            List<HmiApplyPatchItem> patches = ReadHmiPatchJsonl(patchPath);
            List<HmiApplyPreflightPlanItem> plan = new List<HmiApplyPreflightPlanItem>();
            List<HmiApplyPreflightIssue> issues = new List<HmiApplyPreflightIssue>();

            ValidateHmiCheckClean(context, issues);

            foreach (HmiApplyPatchItem patch in patches)
            {
                HmiApplyPreflightPlanItem item = BuildHmiApplyPreflightPlanItem(patch);
                plan.Add(item);
                ValidateHmiApplyPatchItem(context, patch, item, issues);
            }

            string stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
            string preflightDir = Path.Combine(cloneDir, "_hmi_preflight", "patched-" + stamp);
            Directory.CreateDirectory(preflightDir);

            List<HmiApplyCollateralDiffRecord> collateral = new List<HmiApplyCollateralDiffRecord>();
            string patchedHmiRoot = Path.Combine(preflightDir, "_hmi");
            string patchedDigestDir = Path.Combine(preflightDir, "_hmi_metadata", "digest");
            string patchedManifestPath = Path.Combine(preflightDir, "_hmi_metadata", "hmi-objects.csv");

            if (!issues.Any(x => EqualsIgnoreCase(x.Severity, "error")))
            {
                collateral = CreateHmiPatchedSnapshot(context, patches, plan, issues, preflightDir, patchedHmiRoot, patchedDigestDir, patchedManifestPath);
            }

            FinalizeHmiApplyPreflightPlan(plan, issues);

            string summaryPath = Path.Combine(cloneDir, "hmi-apply-preflight-summary.txt");
            string planPath = Path.Combine(cloneDir, "hmi-apply-preflight-plan.csv");
            string issuesPath = Path.Combine(cloneDir, "hmi-apply-preflight-issues.csv");
            string collateralPath = Path.Combine(cloneDir, "hmi-apply-preflight-collateral.csv");

            WriteCsv(planPath, HmiApplyPreflightPlanHeaders(), plan.Select(HmiApplyPreflightPlanRow));
            WriteCsv(issuesPath, HmiApplyPreflightIssueHeaders(), issues.Select(HmiApplyPreflightIssueRow));
            WriteCsv(collateralPath, HmiApplyCollateralDiffHeaders(), collateral.Select(HmiApplyCollateralDiffRow));
            WriteJsonl(Path.Combine(preflightDir, "hmi-apply-preflight-plan.jsonl"), plan.Select(HmiApplyPreflightPlanJsonRow));
            WriteJsonl(Path.Combine(preflightDir, "hmi-apply-preflight-issues.jsonl"), issues.Select(HmiApplyPreflightIssueJsonRow));
            WriteJsonl(Path.Combine(preflightDir, "hmi-apply-preflight-collateral.jsonl"), collateral.Select(HmiApplyCollateralDiffJsonRow));
            WriteHmiApplyPreflightSummary(summaryPath, cloneDir, patchPath, preflightDir, patchedHmiRoot, patchedDigestDir, patchedManifestPath, planPath, issuesPath, collateralPath, context, patches, plan, issues, collateral);

            Console.WriteLine("HMI apply preflight");
            Console.WriteLine("  Patch rows: " + patches.Count);
            Console.WriteLine("  Ready: " + plan.Count(x => EqualsIgnoreCase(x.Status, "ready") || EqualsIgnoreCase(x.Status, "ready-with-warnings")));
            Console.WriteLine("  Invalid: " + plan.Count(x => EqualsIgnoreCase(x.Status, "invalid")));
            Console.WriteLine("  Errors: " + issues.Count(x => EqualsIgnoreCase(x.Severity, "error")));
            Console.WriteLine("  Warnings: " + issues.Count(x => EqualsIgnoreCase(x.Severity, "warning")));
            Console.WriteLine("  Collateral rows: " + collateral.Count);
            Console.WriteLine("  Unexpected collateral rows: " + collateral.Count(x => !x.Expected));
            Console.WriteLine("  Patched snapshot: " + preflightDir);
            Console.WriteLine("  Summary: " + summaryPath);
            Console.WriteLine("  Plan: " + planPath);
            Console.WriteLine("  Issues: " + issuesPath);
            Console.WriteLine("  Collateral: " + collateralPath);
        }

        private static HmiApplyPreflightContext LoadHmiApplyPreflightContext(string cloneDir)
        {
            string metadataDir = Path.Combine(cloneDir, "_hmi_metadata");
            string digestDir = Path.Combine(metadataDir, "digest");

            HmiApplyPreflightContext context = new HmiApplyPreflightContext
            {
                CloneDir = cloneDir,
                HmiRoot = Path.Combine(cloneDir, "_hmi"),
                MetadataDir = metadataDir,
                DigestDir = digestDir,
                CheckPath = Path.Combine(cloneDir, "hmi-check-objects.csv"),
                ManifestPath = Path.Combine(metadataDir, "hmi-objects.csv")
            };

            if (!Directory.Exists(context.HmiRoot))
            {
                throw new DirectoryNotFoundException("HMI clone XML root was not found. Run hmi-init-clone before hmi-apply-preflight: " + context.HmiRoot);
            }

            context.CheckRows = LoadRequiredCsv(context.CheckPath, "Run hmi-check before hmi-apply-preflight.");
            context.ManifestRows = LoadRequiredCsv(context.ManifestPath, "Run hmi-init-clone before hmi-apply-preflight.");
            context.XmlFiles = LoadRequiredCsv(Path.Combine(digestDir, "hmi-xml-files.csv"), "Run hmi-digest before hmi-apply-preflight.");
            context.ScreenItems = LoadRequiredCsv(Path.Combine(digestDir, "hmi-screen-items.csv"), "Run hmi-digest before hmi-apply-preflight.");
            context.ScreenBindings = LoadRequiredCsv(Path.Combine(digestDir, "hmi-screen-bindings.csv"), "Run hmi-digest before hmi-apply-preflight.");
            context.EventHandlers = LoadRequiredCsv(Path.Combine(digestDir, "hmi-event-handlers.csv"), "Run hmi-digest before hmi-apply-preflight.");
            context.TagDetails = LoadRequiredCsv(Path.Combine(digestDir, "hmi-tag-details.csv"), "Run hmi-digest before hmi-apply-preflight.");
            context.TextListItems = LoadRequiredCsv(Path.Combine(digestDir, "hmi-text-list-items.csv"), "Run hmi-digest before hmi-apply-preflight.");

            return context;
        }

        private static List<Dictionary<string, string>> LoadRequiredCsv(string path, string hint)
        {
            if (!File.Exists(path))
            {
                throw new FileNotFoundException("Required report was not found: " + path + ". " + hint, path);
            }

            return ReadCsv(path);
        }

        private static List<HmiApplyPatchItem> ReadHmiPatchJsonl(string patchPath)
        {
            List<HmiApplyPatchItem> result = new List<HmiApplyPatchItem>();
            string[] lines = File.ReadAllLines(patchPath, Encoding.UTF8);
            for (int i = 0; i < lines.Length; i++)
            {
                string raw = lines[i];
                string trimmed = EmptyIfNull(raw).Trim();
                if (string.IsNullOrWhiteSpace(trimmed) || trimmed.StartsWith("#", StringComparison.Ordinal) || trimmed.StartsWith("//", StringComparison.Ordinal))
                {
                    continue;
                }

                HmiApplyPatchItem item = new HmiApplyPatchItem
                {
                    Row = i + 1,
                    Raw = raw,
                    Fields = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                };

                try
                {
                    item.Fields = ParseFlatJsonObject(trimmed, "HMI patch row " + item.Row);
                }
                catch (Exception ex)
                {
                    item.ParseError = ex.Message;
                }

                item.Operation = PatchValue(item, "op");
                result.Add(item);
            }

            return result;
        }

        private static HmiApplyPreflightPlanItem BuildHmiApplyPreflightPlanItem(HmiApplyPatchItem patch)
        {
            return new HmiApplyPreflightPlanItem
            {
                Row = patch.Row,
                Operation = FirstNonEmpty(patch.Operation, "parse"),
                Status = "pending",
                Severity = "info",
                Selector = HmiPatchSelectorSummary(patch),
                Value = FirstNonEmpty(PatchValue(patch, "value"), PatchValue(patch, "text")),
                Message = string.Empty
            };
        }

