                writer.WriteLine("Patch rows: " + patches.Count);
                writer.WriteLine("Plan items: " + plan.Count);
                writer.WriteLine("Ready: " + plan.Count(x => EqualsIgnoreCase(x.Status, "ready")));
                writer.WriteLine("Ready with warnings: " + plan.Count(x => EqualsIgnoreCase(x.Status, "ready-with-warnings")));
                writer.WriteLine("Invalid: " + plan.Count(x => EqualsIgnoreCase(x.Status, "invalid")));
                writer.WriteLine("Errors: " + issues.Count(x => EqualsIgnoreCase(x.Severity, "error")));
                writer.WriteLine("Warnings: " + issues.Count(x => EqualsIgnoreCase(x.Severity, "warning")));
                writer.WriteLine("Local XML patch changed items: " + plan.Count(x => EqualsIgnoreCase(x.LocalPatchStatus, "changed")));
                writer.WriteLine("Local XML patch no-op items: " + plan.Count(x => EqualsIgnoreCase(x.LocalPatchStatus, "no-change")));
                writer.WriteLine("Collateral rows: " + collateral.Count);
                writer.WriteLine("Unexpected collateral rows: " + collateral.Count(x => !x.Expected));
                writer.WriteLine();
                writer.WriteLine("Supported operations:");
                writer.WriteLine("  set-attribute: screen-item geometry attributes Left/Top/Width/Height");
                writer.WriteLine("  set-link: screen-item links Tag/TextList/Picture/PictureOff");
                writer.WriteLine("  set-text-list-entry: text list entry text by textList/from/culture");
                writer.WriteLine("  set-screen-item-text: visible screen item text by screen/item or itemId/culture");
                writer.WriteLine("  duplicate-screen-items: clone existing screen items inside one screen XML");
                writer.WriteLine("  move-screen-items: shift existing screen items inside one screen XML");
                writer.WriteLine("  set-event-parameter: existing event function parameter");
                writer.WriteLine();
                writer.WriteLine("Plan report: " + planPath);
                writer.WriteLine("Issues report: " + issuesPath);
                writer.WriteLine("Collateral report: " + collateralPath);
                writer.WriteLine("JSONL snapshot directory: " + preflightDir);
            }
        }

        private static void FinalizeHmiApplyPreflightPlan(List<HmiApplyPreflightPlanItem> plan, List<HmiApplyPreflightIssue> issues)
        {
            bool hasGlobalError = issues.Any(x => x.Row == 0 && EqualsIgnoreCase(x.Severity, "error"));
            foreach (HmiApplyPreflightPlanItem item in plan)
            {
                bool hasItemError = issues.Any(x => x.Row == item.Row && EqualsIgnoreCase(x.Severity, "error"));
                bool hasItemWarning = issues.Any(x => x.Row == item.Row && EqualsIgnoreCase(x.Severity, "warning"));
                if (hasGlobalError || hasItemError)
                {
                    item.Severity = "error";
                    item.Status = "invalid";
                }
                else if (hasItemWarning)
                {
                    item.Severity = "warning";
                    item.Status = "ready-with-warnings";
                }
                else
                {
                    item.Severity = "info";
                    item.Status = "ready";
                }

                if (string.IsNullOrWhiteSpace(item.LocalPatchStatus))
                {
                    item.LocalPatchStatus = hasGlobalError || hasItemError ? "not-run" : "validated";
                }

                if (string.IsNullOrWhiteSpace(item.Message))
                {
                    string message = string.Join(" | ", issues
                        .Where(x => x.Row == item.Row)
                        .Select(x => x.Code + ": " + x.Message)
                        .ToArray());
                    item.Message = string.IsNullOrWhiteSpace(message)
                        ? "Preflight passed. No TIA writes were performed."
                        : message;
                }
            }
        }

        private static List<HmiApplyCollateralDiffRecord> CreateHmiPatchedSnapshot(
            HmiApplyPreflightContext context,
            List<HmiApplyPatchItem> patches,
            List<HmiApplyPreflightPlanItem> plan,
            List<HmiApplyPreflightIssue> issues,
            string preflightDir,
            string patchedHmiRoot,
            string patchedDigestDir,
            string patchedManifestPath)
        {
            CopyDirectory(context.HmiRoot, patchedHmiRoot, false);
            RewriteHmiExportReportPaths(patchedHmiRoot);

            Dictionary<int, HmiApplyPreflightPlanItem> planByRow = plan.ToDictionary(x => x.Row);
            foreach (HmiApplyPatchItem patch in patches)
            {
                HmiApplyPreflightPlanItem item;
                if (!planByRow.TryGetValue(patch.Row, out item))
                {
                    continue;
                }

                ApplyHmiPatchToLocalXml(context, patch, item, issues, patchedHmiRoot);
            }

            if (issues.Any(x => EqualsIgnoreCase(x.Severity, "error")))
            {
                return new List<HmiApplyCollateralDiffRecord>();
            }

            WriteHmiDigest(patchedHmiRoot, patchedDigestDir);
            List<HmiObjectManifestRecord> patchedManifest = BuildHmiObjectManifest(patchedHmiRoot, patchedDigestDir);
            WriteHmiObjectManifest(patchedManifestPath, patchedManifest);

            List<Dictionary<string, string>> patchedXmlFiles = LoadRequiredCsv(Path.Combine(patchedDigestDir, "hmi-xml-files.csv"), "Patched digest was not produced.");
            foreach (Dictionary<string, string> row in patchedXmlFiles.Where(x => !EqualsIgnoreCase(GetCsvValue(x, "ParseStatus"), "ok")))
            {
                AddHmiApplyPreflightIssue(
                    issues,
                    "error",
                    "PATCHED_XML_PARSE_ERROR",
                    null,
                    GetCsvValue(row, "RelativePath"),
                    "Patched XML digest has parse status '" + GetCsvValue(row, "ParseStatus") + "': " + GetCsvValue(row, "Message"));
            }

            HmiExpectedDigestChanges expected = BuildHmiExpectedDigestChanges(context, patches);
            List<HmiApplyCollateralDiffRecord> collateral = BuildHmiDigestCollateralDiff(context.DigestDir, patchedDigestDir, expected);
            int unexpected = collateral.Count(x => !x.Expected);
            if (unexpected > 0)
            {
                AddHmiApplyPreflightIssue(
                    issues,
                    "warning",
                    "UNEXPECTED_COLLATERAL_DIFF",
                    null,
                    preflightDir,
                    "Patched digest contains " + unexpected + " row-level change(s) outside expected patch targets. Inspect hmi-apply-preflight-collateral.csv before any future import design.");
            }

            return collateral;
        }

        private static void RewriteHmiExportReportPaths(string hmiRoot)
        {
            string reportPath = Path.Combine(hmiRoot, "hmi-export-report.csv");
            if (!File.Exists(reportPath))
            {
                return;
            }

            List<Dictionary<string, string>> rows = ReadCsv(reportPath);
            foreach (Dictionary<string, string> row in rows)
            {
                string filePath = GetCsvValue(row, "FilePath");
                string relativePath = HmiExportReportRelativePath(hmiRoot, filePath);
                if (!string.IsNullOrWhiteSpace(relativePath))
                {
                    row["FilePath"] = Path.Combine(hmiRoot, relativePath);
                }
            }

            WriteCsv(reportPath,
                new[] { "Kind", "TargetPath", "FolderPath", "Name", "TypeName", "FilePath", "Status", "Message" },
                rows.Select(x => new[]
                {
                    GetCsvValue(x, "Kind"),
                    GetCsvValue(x, "TargetPath"),
                    GetCsvValue(x, "FolderPath"),
                    GetCsvValue(x, "Name"),
                    GetCsvValue(x, "TypeName"),
                    GetCsvValue(x, "FilePath"),
                    GetCsvValue(x, "Status"),
                    GetCsvValue(x, "Message")
                }));
        }

        private static string[] HmiApplyCollateralDiffHeaders()
        {
            return new[] { "Expected", "Report", "Status", "Key", "RelativePath", "Before", "After", "Message" };
        }

        private static string[] HmiApplyCollateralDiffRow(HmiApplyCollateralDiffRecord row)
        {
            return new[] { row.Expected.ToString(), row.Report, row.Status, row.Key, row.RelativePath, row.Before, row.After, row.Message };
        }

        private static Dictionary<string, string> HmiApplyCollateralDiffJsonRow(HmiApplyCollateralDiffRecord row)
        {
            return new Dictionary<string, string>
            {
                { "expected", row.Expected.ToString() },
                { "report", row.Report },
                { "status", row.Status },
                { "key", row.Key },
                { "relativePath", row.RelativePath },
                { "before", row.Before },
                { "after", row.After },
                { "message", row.Message }
            };
        }

        private static void ApplyHmiPatchToLocalXml(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues, string patchedHmiRoot)
        {
            if (EqualsIgnoreCase(patch.Operation, "set-attribute"))
            {
                ApplyHmiSetAttributePatch(context, patch, plan, issues, patchedHmiRoot);
            }
            else if (EqualsIgnoreCase(patch.Operation, "set-link"))
            {
                ApplyHmiSetLinkPatch(context, patch, plan, issues, patchedHmiRoot);
            }
            else if (EqualsIgnoreCase(patch.Operation, "set-text-list-entry"))
            {
                ApplyHmiSetTextListEntryPatch(context, patch, plan, issues, patchedHmiRoot);
            }
            else if (EqualsIgnoreCase(patch.Operation, "set-screen-item-text"))
            {
                ApplyHmiSetScreenItemTextPatch(context, patch, plan, issues, patchedHmiRoot);
            }
            else if (EqualsIgnoreCase(patch.Operation, "duplicate-screen-items"))
            {
                ApplyHmiDuplicateScreenItemsPatch(context, patch, plan, issues, patchedHmiRoot);
            }
            else if (EqualsIgnoreCase(patch.Operation, "move-screen-items"))
            {
                ApplyHmiMoveScreenItemsPatch(context, patch, plan, issues, patchedHmiRoot);
            }
            else if (EqualsIgnoreCase(patch.Operation, "set-event-parameter"))
            {
                ApplyHmiSetEventParameterPatch(context, patch, plan, issues, patchedHmiRoot);
            }
        }

        private static void ApplyHmiSetAttributePatch(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues, string patchedHmiRoot)
        {
            Dictionary<string, string> row = ResolveHmiScreenItemSelector(context, patch, issues);
            XmlDocument document;
            XmlElement item = LoadPatchedScreenItem(patchedHmiRoot, row, patch, plan, issues, out document);
            if (item == null)
            {
                return;
            }

            string attribute = PatchValue(patch, "attribute");
            string value = PatchValue(patch, "value");
            bool changed = SetDirectAttributeListValue(item, attribute, value, patch, plan, issues);
            SavePatchedDocumentIfChanged(document, plan, changed);
        }

        private static void ApplyHmiSetLinkPatch(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues, string patchedHmiRoot)
        {
            Dictionary<string, string> row = ResolveHmiScreenItemSelector(context, patch, issues);
            XmlDocument document;
            XmlElement item = LoadPatchedScreenItem(patchedHmiRoot, row, patch, plan, issues, out document);
            if (item == null)
            {
                return;
            }

            string linkName = PatchValue(patch, "link");
            string value = PatchValue(patch, "value");
            List<XmlElement> links = DescendantElements(item)
                .Where(x => x.ParentNode is XmlElement && EqualsIgnoreCase(((XmlElement)x.ParentNode).Name, "LinkList") && EqualsIgnoreCase(x.Name, linkName))
                .ToList();
            if (links.Count != 1)
            {
                AddHmiApplyPreflightIssue(issues, "error", links.Count == 0 ? "PATCH_LINK_NODE_NOT_FOUND" : "PATCH_LINK_NODE_AMBIGUOUS", patch, plan.Selector, "Expected exactly one XML link node named '" + linkName + "' under selected screen item, found " + links.Count + ".");
                return;
            }

            XmlElement name = GetDirectChildElement(links[0], "Name");
            if (name == null)
            {
                AddHmiApplyPreflightIssue(issues, "error", "PATCH_LINK_NAME_NOT_FOUND", patch, plan.Selector, "Selected XML link node does not contain child Name.");
                return;
            }

            bool changed = SetXmlElementText(name, value);
            SavePatchedDocumentIfChanged(document, plan, changed);
        }

        private static void ApplyHmiSetTextListEntryPatch(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues, string patchedHmiRoot)
        {
            Dictionary<string, string> row = ResolveHmiTextListEntryRow(context, patch, issues);
            if (row == null)
            {
                return;
            }

            string relativePath = NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath"));
            string filePath = Path.Combine(patchedHmiRoot, relativePath);
            XmlDocument document = LoadXmlDocumentForPatch(filePath);
            XmlElement root = FindExportRootObject(document);
            XmlElement entry = FindHmiTextListEntryElement(root, row);
            if (entry == null)
            {
                AddHmiApplyPreflightIssue(issues, "error", "PATCH_TEXT_LIST_ENTRY_XML_NOT_FOUND", patch, plan.Selector, "Text list entry exists in digest but was not found in patched XML: " + plan.TargetName);
                return;
            }

            bool changed = SetHmiMultilingualTextValue(entry, PatchValue(patch, "culture"), PatchValue(patch, "text"), patch, plan, issues);
            plan.PatchedSnapshotPath = filePath;
            SavePatchedDocumentIfChanged(document, plan, changed);
        }

        private static void ApplyHmiSetScreenItemTextPatch(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues, string patchedHmiRoot)
        {
            Dictionary<string, string> row = ResolveHmiScreenItemSelector(context, patch, issues);
            XmlDocument document;
            XmlElement item = LoadPatchedScreenItem(patchedHmiRoot, row, patch, plan, issues, out document);
            if (item == null)
            {
                return;
            }

            bool changed = SetHmiNamedMultilingualTextValue(item, "Text", PatchValue(patch, "culture"), PatchValue(patch, "text"), patch, plan, issues);
            SavePatchedDocumentIfChanged(document, plan, changed);
        }

        private static void ApplyHmiDuplicateScreenItemsPatch(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues, string patchedHmiRoot)
        {
            List<Dictionary<string, string>> rows = ResolveHmiScreenItemListSelector(context, patch, issues);
            if (rows.Count == 0)
            {
                return;
            }

            List<string> newIds = SplitHmiPatchList(PatchValue(patch, "newItemIds"));
            List<string> newNames = SplitHmiPatchList(PatchValue(patch, "newItems"));
            int deltaX = ParseHmiPatchInt(patch, "deltaX", 0, issues, plan.Selector);
            int deltaY = ParseHmiPatchInt(patch, "deltaY", 0, issues, plan.Selector);
            if (newIds.Count != rows.Count || newNames.Count != rows.Count || issues.Any(x => x.Row == patch.Row && EqualsIgnoreCase(x.Severity, "error")))
            {
                return;
            }

            string relativePath = NormalizeHmiRelativePath(GetCsvValue(rows[0], "RelativePath"));
            string filePath = Path.Combine(patchedHmiRoot, relativePath);
            XmlDocument document = LoadXmlDocumentForPatch(filePath);
            XmlElement root = FindExportRootObject(document);
            List<XmlElement> sourceItems = rows.Select(x => FindHmiScreenItemElement(root, x)).ToList();
            if (sourceItems.Any(x => x == null))
            {
                AddHmiApplyPreflightIssue(issues, "error", "PATCH_DUPLICATE_SOURCE_XML_NOT_FOUND", patch, plan.Selector, "At least one source screen item exists in digest but was not found in patched XML.");
                return;
            }

            XmlNode parent = sourceItems[0].ParentNode;
            if (parent == null || sourceItems.Any(x => !object.ReferenceEquals(x.ParentNode, parent)))
            {
                AddHmiApplyPreflightIssue(issues, "error", "PATCH_DUPLICATE_SOURCE_PARENT_MISMATCH", patch, plan.Selector, "Source screen items must share one XML parent ObjectList.");
                return;
            }

            HashSet<string> usedIds = CollectXmlIdValues(document);
            foreach (string id in newIds)
            {
                usedIds.Add(id);
            }

            XmlNode insertAfter = sourceItems[sourceItems.Count - 1];
            for (int i = 0; i < sourceItems.Count; i++)
            {
                XmlElement clone = (XmlElement)sourceItems[i].CloneNode(true);
                clone.SetAttribute("ID", newIds[i]);
                SetDirectAttributeListText(clone, "ObjectName", newNames[i]);
                ShiftHmiScreenItemGeometry(clone, deltaX, deltaY);
                AssignFreshXmlIdsToDescendants(clone, usedIds);
                insertAfter = parent.InsertAfter(clone, insertAfter);
            }

            plan.PatchedSnapshotPath = filePath;
            SavePatchedDocumentIfChanged(document, plan, true);
        }

        private static void ApplyHmiMoveScreenItemsPatch(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues, string patchedHmiRoot)
        {
            List<Dictionary<string, string>> rows = ResolveHmiScreenItemListSelector(context, patch, issues);
            if (rows.Count == 0)
            {
                return;
            }

            int deltaX = ParseHmiPatchInt(patch, "deltaX", 0, issues, plan.Selector);
            int deltaY = ParseHmiPatchInt(patch, "deltaY", 0, issues, plan.Selector);
            if (issues.Any(x => x.Row == patch.Row && EqualsIgnoreCase(x.Severity, "error")))
            {
                return;
            }

            string relativePath = NormalizeHmiRelativePath(GetCsvValue(rows[0], "RelativePath"));
            string filePath = Path.Combine(patchedHmiRoot, relativePath);
            XmlDocument document = LoadXmlDocumentForPatch(filePath);
            XmlElement root = FindExportRootObject(document);

            foreach (Dictionary<string, string> row in rows)
            {
                XmlElement item = FindHmiScreenItemElement(root, row);
                if (item == null)
                {
                    AddHmiApplyPreflightIssue(issues, "error", "PATCH_SCREEN_ITEM_XML_NOT_FOUND", patch, plan.Selector, "Screen item exists in digest but was not found in patched XML: " + HmiScreenItemDisplayName(row));
                    return;
                }

                ShiftHmiScreenItemGeometry(item, deltaX, deltaY);
            }

            plan.PatchedSnapshotPath = filePath;
            SavePatchedDocumentIfChanged(document, plan, deltaX != 0 || deltaY != 0);
        }

        private static void ApplyHmiSetEventParameterPatch(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues, string patchedHmiRoot)
        {
            Dictionary<string, string> eventRow = ResolveHmiEventHandlerRow(context, patch, issues);
            if (eventRow == null)
            {
                return;
            }

            XmlDocument document;
            XmlElement item = LoadPatchedScreenItemByEventRow(patchedHmiRoot, eventRow, patch, plan, issues, out document);
            if (item == null)
            {
                return;
            }

            XmlElement function = FindHmiEventFunctionElement(item, eventRow);
            if (function == null)
            {
                AddHmiApplyPreflightIssue(issues, "error", "PATCH_EVENT_FUNCTION_XML_NOT_FOUND", patch, plan.Selector, "Event function exists in digest but was not found in patched XML: " + plan.TargetName);
                return;
            }

            bool changed = SetHmiFunctionParameterValue(function, PatchValue(patch, "parameter"), PatchValue(patch, "value"), patch, plan, issues);
            SavePatchedDocumentIfChanged(document, plan, changed);
        }

        private static XmlElement LoadPatchedScreenItem(string patchedHmiRoot, Dictionary<string, string> row, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues, out XmlDocument document)
        {
            document = null;
            if (row == null)
            {
                return null;
            }

            string relativePath = NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath"));
            string filePath = Path.Combine(patchedHmiRoot, relativePath);
            document = LoadXmlDocumentForPatch(filePath);
            XmlElement root = FindExportRootObject(document);
            XmlElement item = FindHmiScreenItemElement(root, row);
            if (item == null)
            {
                AddHmiApplyPreflightIssue(issues, "error", "PATCH_SCREEN_ITEM_XML_NOT_FOUND", patch, plan.Selector, "Screen item exists in digest but was not found in patched XML: " + HmiScreenItemDisplayName(row));
                return null;
            }

            plan.PatchedSnapshotPath = filePath;
            return item;
        }

        private static XmlElement LoadPatchedScreenItemByEventRow(string patchedHmiRoot, Dictionary<string, string> row, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues, out XmlDocument document)
        {
            document = null;
            string relativePath = NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath"));
            string filePath = Path.Combine(patchedHmiRoot, relativePath);
            document = LoadXmlDocumentForPatch(filePath);
            XmlElement root = FindExportRootObject(document);

            XmlElement item;
            if (EqualsIgnoreCase(GetCsvValue(row, "ItemName"), "SCREEN"))
            {
                item = root;
            }
            else
            {
                item = FindHmiScreenItemElement(root, row);
            }

            if (item == null)
            {
                AddHmiApplyPreflightIssue(issues, "error", "PATCH_EVENT_ITEM_XML_NOT_FOUND", patch, plan.Selector, "Event item exists in digest but was not found in patched XML: " + plan.TargetName);
                return null;
            }

            plan.PatchedSnapshotPath = filePath;
            return item;
        }

        private static Dictionary<string, string> ResolveHmiTextListEntryRow(HmiApplyPreflightContext context, HmiApplyPatchItem patch, List<HmiApplyPreflightIssue> issues)
        {
            string textList = PatchValue(patch, "textList");
            string from = PatchValue(patch, "from");
            List<Dictionary<string, string>> matches = context.TextListItems
                .Where(x => EqualsIgnoreCase(GetCsvValue(x, "TextListName"), textList)
                    && EqualsIgnoreCase(GetCsvValue(x, "From"), from)
                    && (string.IsNullOrWhiteSpace(PatchValue(patch, "to")) || EqualsIgnoreCase(GetCsvValue(x, "To"), PatchValue(patch, "to")))
                    && (string.IsNullOrWhiteSpace(PatchValue(patch, "entryType")) || EqualsIgnoreCase(GetCsvValue(x, "EntryType"), PatchValue(patch, "entryType"))))
                .ToList();

            return RequireSingleHmiMatch(patch, issues, matches, "TEXT_LIST_ENTRY_NOT_FOUND", "TEXT_LIST_ENTRY_AMBIGUOUS", "text list entry " + textList + " from " + from);
        }

        private static Dictionary<string, string> ResolveHmiEventHandlerRow(HmiApplyPreflightContext context, HmiApplyPatchItem patch, List<HmiApplyPreflightIssue> issues)
        {
            string screen = PatchValue(patch, "screen");
            string item = PatchValue(patch, "item");
            string itemId = PatchValue(patch, "itemId");
            string eventName = PatchValue(patch, "event");
            string function = PatchValue(patch, "function");
            List<Dictionary<string, string>> matches = context.EventHandlers
                .Where(x => EqualsIgnoreCase(GetCsvValue(x, "ScreenName"), screen)
                    && EqualsIgnoreCase(GetCsvValue(x, "EventName"), eventName)
                    && EqualsIgnoreCase(GetCsvValue(x, "FunctionName"), function)
                    && (string.IsNullOrWhiteSpace(item) || EqualsIgnoreCase(GetCsvValue(x, "ItemName"), item) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), item))
                    && (string.IsNullOrWhiteSpace(itemId) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), itemId)))
                .ToList();

            return RequireSingleHmiMatch(patch, issues, matches, "EVENT_HANDLER_NOT_FOUND", "EVENT_HANDLER_AMBIGUOUS", "event handler " + screen + "/" + eventName + "/" + function);
        }

        private static XmlDocument LoadXmlDocumentForPatch(string filePath)
        {
            if (!File.Exists(filePath))
            {
                throw new FileNotFoundException("Patched XML file was not found.", filePath);
            }

            XmlDocument document = new XmlDocument();
            document.PreserveWhitespace = true;
            using (XmlReader reader = XmlReader.Create(filePath, new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit }))
            {
                document.Load(reader);
            }

            return document;
        }

        private static XmlElement FindHmiScreenItemElement(XmlElement root, Dictionary<string, string> row)
        {
            if (root == null || row == null)
            {
                return null;
            }

            string itemId = GetCsvValue(row, "ItemId");
            string itemName = GetCsvValue(row, "ItemName");
            return DescendantElements(root)
                .Where(x => EqualsIgnoreCase(x.GetAttribute("CompositionName"), "ScreenItems"))
                .FirstOrDefault(x => (!string.IsNullOrWhiteSpace(itemId) && EqualsIgnoreCase(x.GetAttribute("ID"), itemId))
                    || (!string.IsNullOrWhiteSpace(itemName) && EqualsIgnoreCase(GetAttributeListValue(x, "ObjectName"), itemName)));
        }

        private static XmlElement FindHmiTextListEntryElement(XmlElement root, Dictionary<string, string> row)
        {
            if (root == null || row == null)
            {
                return null;
            }

            string entryId = GetCsvValue(row, "EntryId");
            string from = GetCsvValue(row, "From");
            string to = GetCsvValue(row, "To");
            string entryType = GetCsvValue(row, "EntryType");
            return DescendantElements(root)
                .Where(x => EqualsIgnoreCase(x.Name, "Hmi.TextGraphicList.TextListEntry"))
                .FirstOrDefault(x => (!string.IsNullOrWhiteSpace(entryId) && EqualsIgnoreCase(x.GetAttribute("ID"), entryId))
                    || (EqualsIgnoreCase(GetAttributeListValue(x, "From"), from)
                        && EqualsIgnoreCase(GetAttributeListValue(x, "To"), to)
                        && EqualsIgnoreCase(GetAttributeListValue(x, "EntryType"), entryType)));
        }

        private static XmlElement FindHmiEventFunctionElement(XmlElement item, Dictionary<string, string> row)
        {
            if (item == null || row == null)
            {
                return null;
            }

            string eventName = GetCsvValue(row, "EventName");
            string functionName = GetCsvValue(row, "FunctionName");
            List<XmlElement> matches = new List<XmlElement>();
            foreach (XmlElement eventElement in DescendantElements(item).Where(x => EqualsIgnoreCase(x.Name, "Hmi.Event.Event") && EqualsIgnoreCase(GetAttributeListValue(x, "Name"), eventName)))
            {
                matches.AddRange(DescendantElements(eventElement).Where(x => EqualsIgnoreCase(x.Name, "Hmi.Event.FunctionListEntry") && EqualsIgnoreCase(GetAttributeListValue(x, "Name"), functionName)));
            }

            return matches.Count == 1 ? matches[0] : null;
        }

        private static bool SetDirectAttributeListValue(XmlElement element, string attributeName, string value, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            XmlElement attribute = GetDirectAttributeListElement(element, attributeName);
            if (attribute == null)
            {
                AddHmiApplyPreflightIssue(issues, "error", "PATCH_ATTRIBUTE_XML_NOT_FOUND", patch, plan.Selector, "Attribute '" + attributeName + "' exists in patch allowlist but was not found in selected XML node.");
                return false;
            }

            return SetXmlElementText(attribute, value);
        }

        private static void SetDirectAttributeListText(XmlElement element, string attributeName, string value)
        {
            XmlElement attribute = GetDirectAttributeListElement(element, attributeName);
            if (attribute != null)
            {
                SetXmlElementText(attribute, value);
            }
        }

        private static void ShiftHmiScreenItemGeometry(XmlElement element, int deltaX, int deltaY)
        {
            ShiftDirectIntegerAttribute(element, "Left", deltaX);
            ShiftDirectIntegerAttribute(element, "Top", deltaY);

            XmlElement points = GetDirectAttributeListElement(element, "Points");
            if (points != null)
            {
                points.InnerText = Regex.Replace(points.InnerText, @"(-?\d+),\s*(-?\d+)", match =>
                {
                    int x;
                    int y;
                    if (!int.TryParse(match.Groups[1].Value, out x) || !int.TryParse(match.Groups[2].Value, out y))
                    {
                        return match.Value;
                    }

                    return (x + deltaX).ToString(CultureInfo.InvariantCulture) + ", " + (y + deltaY).ToString(CultureInfo.InvariantCulture);
                });
            }
        }

        private static void ShiftDirectIntegerAttribute(XmlElement element, string attributeName, int delta)
        {
            if (delta == 0)
            {
                return;
            }

            XmlElement attribute = GetDirectAttributeListElement(element, attributeName);
            if (attribute == null)
            {
                return;
            }

            int value;
            if (int.TryParse(CleanXmlText(attribute.InnerText), NumberStyles.Integer, CultureInfo.InvariantCulture, out value))
            {
                SetXmlElementText(attribute, (value + delta).ToString(CultureInfo.InvariantCulture));
            }
        }

        private static HashSet<string> CollectXmlIdValues(XmlDocument document)
        {
            HashSet<string> result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (XmlElement element in DescendantElements(document.DocumentElement))
            {
                string id = element.GetAttribute("ID");
                if (!string.IsNullOrWhiteSpace(id))
                {
                    result.Add(id);
                }
            }

            return result;
        }

        private static void AssignFreshXmlIdsToDescendants(XmlElement root, HashSet<string> usedIds)
        {
            foreach (XmlElement element in DescendantElements(root).Where(x => !object.ReferenceEquals(x, root) && x.HasAttribute("ID")))
            {
                string id = NextHmiXmlId(usedIds);
                element.SetAttribute("ID", id);
                usedIds.Add(id);
            }
        }

        private static string NextHmiXmlId(HashSet<string> usedIds)
        {
            int max = 0;
            foreach (string id in usedIds)
            {
                int value;
                if (int.TryParse(id, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out value) && value > max)
                {
                    max = value;
                }
            }

            for (int value = max + 1; value < int.MaxValue; value++)
            {
                string candidate = value.ToString("X", CultureInfo.InvariantCulture);
                if (!usedIds.Contains(candidate))
                {
                    return candidate;
                }
            }

            throw new InvalidOperationException("Could not allocate a fresh HMI XML ID.");
        }

        private static bool SetHmiNamedMultilingualTextValue(XmlElement parent, string compositionName, string culture, string text, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            List<XmlElement> texts = DirectObjectChildren(parent, "MultilingualText", compositionName).ToList();
            if (texts.Count != 1)
            {
                AddHmiApplyPreflightIssue(issues, "error", texts.Count == 0 ? "PATCH_TEXT_COMPOSITION_XML_NOT_FOUND" : "PATCH_TEXT_COMPOSITION_XML_AMBIGUOUS", patch, plan.Selector, "Expected exactly one MultilingualText composition '" + compositionName + "', found " + texts.Count + ".");
                return false;
            }

            return SetHmiMultilingualTextValue(texts[0], culture, text, patch, plan, issues);
        }

        private static bool SetHmiMultilingualTextValue(XmlElement parent, string culture, string text, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            List<XmlElement> items = DescendantElements(parent)
                .Where(x => EqualsIgnoreCase(x.Name, "MultilingualTextItem") && EqualsIgnoreCase(GetAttributeListValue(x, "Culture"), culture))
                .ToList();
            if (items.Count != 1)
            {
                AddHmiApplyPreflightIssue(issues, "error", items.Count == 0 ? "PATCH_TEXT_CULTURE_XML_NOT_FOUND" : "PATCH_TEXT_CULTURE_XML_AMBIGUOUS", patch, plan.Selector, "Expected exactly one MultilingualTextItem for culture '" + culture + "', found " + items.Count + ".");
                return false;
            }

            XmlElement textElement = GetDirectAttributeListElement(items[0], "Text");
            if (textElement == null)
            {
                AddHmiApplyPreflightIssue(issues, "error", "PATCH_TEXT_XML_NOT_FOUND", patch, plan.Selector, "Selected MultilingualTextItem does not contain AttributeList/Text.");
                return false;
            }

            string oldValue = CleanXmlText(textElement.InnerText);
            if (EqualsIgnoreCase(oldValue, text))
            {
                return false;
            }

            textElement.InnerXml = "<body><p>" + XmlEscape(text) + "</p></body>";
            return true;
        }

        private static bool SetHmiFunctionParameterValue(XmlElement function, string parameterName, string value, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            List<XmlElement> parameters = DescendantElements(function)
                .Where(x => EqualsIgnoreCase(x.Name, "Hmi.Event.FunctionListEntryParameter") && EqualsIgnoreCase(GetAttributeListValue(x, "Name"), parameterName))
                .ToList();
            if (parameters.Count != 1)
            {
                AddHmiApplyPreflightIssue(issues, "error", parameters.Count == 0 ? "PATCH_EVENT_PARAMETER_XML_NOT_FOUND" : "PATCH_EVENT_PARAMETER_XML_AMBIGUOUS", patch, plan.Selector, "Expected exactly one event parameter '" + parameterName + "', found " + parameters.Count + ".");
                return false;
            }

            XmlElement linkValue = GetDirectLinkElement(parameters[0], "Value");
            if (linkValue != null)
            {
                XmlElement name = GetDirectChildElement(linkValue, "Name");
                if (name == null)
                {
                    AddHmiApplyPreflightIssue(issues, "error", "PATCH_EVENT_PARAMETER_LINK_NAME_NOT_FOUND", patch, plan.Selector, "Event parameter link does not contain child Name.");
                    return false;
                }

                return SetXmlElementText(name, value);
            }

            XmlElement attributeValue = GetDirectAttributeListElement(parameters[0], "Value");
            if (attributeValue == null)
            {
                AddHmiApplyPreflightIssue(issues, "error", "PATCH_EVENT_PARAMETER_VALUE_NOT_FOUND", patch, plan.Selector, "Event parameter does not contain a Value link or attribute.");
                return false;
            }

            return SetXmlElementText(attributeValue, value);
        }

        private static bool SetXmlElementText(XmlElement element, string value)
        {
            string oldValue = CleanXmlText(element.InnerText);
            if (string.Equals(oldValue, EmptyIfNull(value), StringComparison.Ordinal))
            {
                return false;
            }

            element.InnerText = EmptyIfNull(value);
            return true;
        }

        private static XmlElement GetDirectAttributeListElement(XmlElement element, string attributeName)
        {
            if (element == null)
            {
                return null;
            }

            foreach (XmlElement attributeList in ChildElements(element).Where(x => EqualsIgnoreCase(x.Name, "AttributeList")))
            {
                foreach (XmlElement attribute in ChildElements(attributeList))
                {
                    if (EqualsIgnoreCase(attribute.Name, attributeName))
                    {
                        return attribute;
                    }
                }
            }

            return null;
        }

        private static XmlElement GetDirectLinkElement(XmlElement element, string linkName)
        {
            if (element == null)
            {
                return null;
            }

            foreach (XmlElement linkList in ChildElements(element).Where(x => EqualsIgnoreCase(x.Name, "LinkList")))
            {
                foreach (XmlElement link in ChildElements(linkList))
                {
                    if (EqualsIgnoreCase(link.Name, linkName))
                    {
                        return link;
                    }
                }
            }

            return null;
        }

        private static XmlElement GetDirectChildElement(XmlElement element, string childName)
        {
            if (element == null)
            {
                return null;
            }

            foreach (XmlElement child in ChildElements(element))
            {
                if (EqualsIgnoreCase(child.Name, childName))
                {
                    return child;
                }
            }

            return null;
        }

        private static void SavePatchedDocumentIfChanged(XmlDocument document, HmiApplyPreflightPlanItem plan, bool changed)
        {
            if (string.IsNullOrWhiteSpace(plan.PatchedSnapshotPath))
            {
                return;
            }

            if (!changed)
            {
                plan.LocalPatchStatus = "no-change";
                plan.Message = "Validated; local XML already had the requested value.";
                return;
            }

            SaveXmlDocumentNoBom(document, plan.PatchedSnapshotPath);
            plan.LocalPatchStatus = "changed";
            plan.Message = "Validated; local XML patch changed the copied snapshot only.";
        }

        private static void SaveXmlDocumentNoBom(XmlDocument document, string path)
        {
            XmlWriterSettings settings = new XmlWriterSettings
            {
                Encoding = new UTF8Encoding(false),
                Indent = false,
                NewLineHandling = NewLineHandling.None
            };

            using (XmlWriter writer = XmlWriter.Create(path, settings))
            {
                document.Save(writer);
            }
        }

        private static HmiExpectedDigestChanges BuildHmiExpectedDigestChanges(HmiApplyPreflightContext context, List<HmiApplyPatchItem> patches)
        {
            HmiExpectedDigestChanges expected = new HmiExpectedDigestChanges();
            foreach (HmiApplyPatchItem patch in patches)
            {
                if (EqualsIgnoreCase(patch.Operation, "set-attribute"))
                {
                    Dictionary<string, string> row = FindHmiScreenItemRow(context, patch);
                    AddExpectedDigestRow(expected, "hmi-screen-items.csv", row);
                    AddExpectedDigestRow(expected, "hmi-object-index.csv", FindHmiObjectIndexLikeRow(context.DigestDir, "ScreenItem", GetCsvValue(row, "ScreenName"), GetCsvValue(row, "ItemName"), GetCsvValue(row, "ItemId"), GetCsvValue(row, "RelativePath")));
                    AddExpectedRelativePath(expected, row);
                }
                else if (EqualsIgnoreCase(patch.Operation, "set-link"))
                {
                    Dictionary<string, string> row = FindHmiScreenItemRow(context, patch);
                    AddExpectedDigestRow(expected, "hmi-screen-items.csv", row);
                    foreach (Dictionary<string, string> binding in FindHmiScreenBindingRows(context, patch))
                    {
                        AddExpectedDigestRow(expected, "hmi-screen-bindings.csv", binding);
                    }
                    AddExpectedRelativePath(expected, row);
                }
                else if (EqualsIgnoreCase(patch.Operation, "set-text-list-entry"))
                {
                    Dictionary<string, string> row = FindHmiTextListEntryRow(context, patch);
                    AddExpectedDigestRow(expected, "hmi-text-list-items.csv", row);
                    AddExpectedRelativePath(expected, row);
                }
                else if (EqualsIgnoreCase(patch.Operation, "set-screen-item-text"))
                {
                    Dictionary<string, string> row = FindHmiScreenItemRow(context, patch);
                    AddExpectedDigestRow(expected, "hmi-screen-items.csv", row);
                    AddExpectedRelativePath(expected, row);
                }
                else if (EqualsIgnoreCase(patch.Operation, "duplicate-screen-items"))
                {
                    AddExpectedDuplicateScreenItems(context, expected, patch);
                }
                else if (EqualsIgnoreCase(patch.Operation, "move-screen-items"))
                {
                    AddExpectedMoveScreenItems(context, expected, patch);
                }
                else if (EqualsIgnoreCase(patch.Operation, "set-event-parameter"))
                {
                    Dictionary<string, string> row = FindHmiEventHandlerRow(context, patch);
                    AddExpectedDigestRow(expected, "hmi-event-handlers.csv", row);
                    AddExpectedRelativePath(expected, row);
                }
            }

            return expected;
        }

        private static void AddExpectedDigestRow(HmiExpectedDigestChanges expected, string reportName, Dictionary<string, string> row)
        {
            if (row == null)
            {
                return;
            }

            expected.RowKeys.Add(reportName + "|" + HmiDigestRowKey(reportName, row));
        }

        private static void AddExpectedRelativePath(HmiExpectedDigestChanges expected, Dictionary<string, string> row)
        {
            string relativePath = NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath"));
            if (!string.IsNullOrWhiteSpace(relativePath))
            {
                expected.RelativePaths.Add(relativePath);
            }
        }

        private static void AddExpectedDuplicateScreenItems(HmiApplyPreflightContext context, HmiExpectedDigestChanges expected, HmiApplyPatchItem patch)
        {
            List<Dictionary<string, string>> rows = FindHmiScreenItemRows(context, patch);
            List<string> newIds = SplitHmiPatchList(PatchValue(patch, "newItemIds"));
            List<string> newNames = SplitHmiPatchList(PatchValue(patch, "newItems"));
            int deltaX = ParseIntOrDefault(PatchValue(patch, "deltaX"), 0);
            int deltaY = ParseIntOrDefault(PatchValue(patch, "deltaY"), 0);
            if (rows.Count == 0 || rows.Count != newIds.Count || rows.Count != newNames.Count)
            {
                return;
            }

            AddExpectedRelativePath(expected, rows[0]);
            for (int i = 0; i < rows.Count; i++)
            {
                Dictionary<string, string> item = new Dictionary<string, string>(rows[i], StringComparer.OrdinalIgnoreCase);
                item["ItemId"] = newIds[i];
                item["ItemName"] = newNames[i];
                item["Left"] = (ParseIntOrDefault(GetCsvValue(item, "Left"), 0) + deltaX).ToString(CultureInfo.InvariantCulture);
                item["Top"] = (ParseIntOrDefault(GetCsvValue(item, "Top"), 0) + deltaY).ToString(CultureInfo.InvariantCulture);
                AddExpectedDigestRow(expected, "hmi-screen-items.csv", item);

                Dictionary<string, string> index = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                {
                    { "RelativePath", GetCsvValue(item, "RelativePath") },
                    { "Kind", "ScreenItem" },
                    { "ParentName", GetCsvValue(item, "ScreenName") },
                    { "ObjectId", GetCsvValue(item, "ItemId") },
                    { "Name", GetCsvValue(item, "ItemName") }
                };
                AddExpectedDigestRow(expected, "hmi-object-index.csv", index);
            }
        }

        private static void AddExpectedMoveScreenItems(HmiApplyPreflightContext context, HmiExpectedDigestChanges expected, HmiApplyPatchItem patch)
        {
            foreach (Dictionary<string, string> row in FindHmiScreenItemRows(context, patch))
            {
                AddExpectedDigestRow(expected, "hmi-screen-items.csv", row);
                AddExpectedDigestRow(expected, "hmi-object-index.csv", FindHmiObjectIndexLikeRow(context.DigestDir, "ScreenItem", GetCsvValue(row, "ScreenName"), GetCsvValue(row, "ItemName"), GetCsvValue(row, "ItemId"), GetCsvValue(row, "RelativePath")));
                AddExpectedRelativePath(expected, row);
            }
        }

        private static List<HmiApplyCollateralDiffRecord> BuildHmiDigestCollateralDiff(string baseDigestDir, string patchedDigestDir, HmiExpectedDigestChanges expected)
        {
            List<HmiApplyCollateralDiffRecord> result = new List<HmiApplyCollateralDiffRecord>();
            foreach (string reportName in HmiDigestReportsForCollateral())
            {
                string basePath = Path.Combine(baseDigestDir, reportName);
                string patchedPath = Path.Combine(patchedDigestDir, reportName);
                if (!File.Exists(basePath) || !File.Exists(patchedPath))
                {
                    continue;
                }

                Dictionary<string, Dictionary<string, string>> before = ReadCsv(basePath)
                    .GroupBy(x => HmiDigestRowKey(reportName, x), StringComparer.OrdinalIgnoreCase)
                    .ToDictionary(x => x.Key, x => x.First(), StringComparer.OrdinalIgnoreCase);
                Dictionary<string, Dictionary<string, string>> after = ReadCsv(patchedPath)
                    .GroupBy(x => HmiDigestRowKey(reportName, x), StringComparer.OrdinalIgnoreCase)
                    .ToDictionary(x => x.Key, x => x.First(), StringComparer.OrdinalIgnoreCase);

                foreach (string key in before.Keys.Union(after.Keys, StringComparer.OrdinalIgnoreCase).OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
                {
                    Dictionary<string, string> left;
                    Dictionary<string, string> right;
                    bool hasLeft = before.TryGetValue(key, out left);
                    bool hasRight = after.TryGetValue(key, out right);
                    string leftSignature = hasLeft ? HmiDigestRowSignature(reportName, left) : string.Empty;
                    string rightSignature = hasRight ? HmiDigestRowSignature(reportName, right) : string.Empty;
                    if (hasLeft && hasRight && string.Equals(leftSignature, rightSignature, StringComparison.Ordinal))
                    {
                        continue;
                    }

                    string relativePath = FirstNonEmpty(
                        NormalizeHmiRelativePath(GetCsvValue(right, "RelativePath")),
                        NormalizeHmiRelativePath(GetCsvValue(left, "RelativePath")));
                    bool isExpected = expected.RowKeys.Contains(reportName + "|" + key)
                        || (EqualsIgnoreCase(reportName, "hmi-xml-files.csv") && expected.RelativePaths.Contains(relativePath));

                    result.Add(new HmiApplyCollateralDiffRecord
                    {
                        Expected = isExpected,
                        Report = reportName,
                        Status = hasLeft && hasRight ? "changed" : hasLeft ? "removed" : "added",
                        Key = key,
                        RelativePath = relativePath,
                        Before = leftSignature,
                        After = rightSignature,
                        Message = isExpected ? "Expected digest change for patch target." : "Unexpected collateral digest change."
                    });
                }
            }

            return result;
        }

        private static string[] HmiDigestReportsForCollateral()
        {
            return new[]
            {
                "hmi-xml-files.csv",
                "hmi-object-index.csv",
                "hmi-screen-items.csv",
                "hmi-screen-bindings.csv",
                "hmi-event-handlers.csv",
                "hmi-tag-details.csv",
                "hmi-text-list-items.csv"
            };
        }

        private static string HmiDigestRowKey(string reportName, Dictionary<string, string> row)
        {
            if (EqualsIgnoreCase(reportName, "hmi-xml-files.csv"))
            {
                return NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath"));
            }

            if (EqualsIgnoreCase(reportName, "hmi-object-index.csv"))
            {
                return NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath")) + "|" + GetCsvValue(row, "Kind") + "|" + GetCsvValue(row, "ParentName") + "|" + GetCsvValue(row, "ObjectId") + "|" + GetCsvValue(row, "Name");
            }

            if (EqualsIgnoreCase(reportName, "hmi-screen-items.csv"))
            {
                return NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath")) + "|" + GetCsvValue(row, "ScreenName") + "|" + GetCsvValue(row, "ItemId") + "|" + GetCsvValue(row, "ItemName");
            }

            if (EqualsIgnoreCase(reportName, "hmi-screen-bindings.csv"))
            {
                return NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath")) + "|" + GetCsvValue(row, "ScreenName") + "|" + GetCsvValue(row, "ItemId") + "|" + GetCsvValue(row, "BindingKind") + "|" + GetCsvValue(row, "TargetId");
            }

            if (EqualsIgnoreCase(reportName, "hmi-event-handlers.csv"))
            {
                return NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath")) + "|" + GetCsvValue(row, "ScreenName") + "|" + GetCsvValue(row, "ItemId") + "|" + GetCsvValue(row, "EventName") + "|" + GetCsvValue(row, "FunctionName");
            }

            if (EqualsIgnoreCase(reportName, "hmi-tag-details.csv"))
            {
                return NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath")) + "|" + GetCsvValue(row, "TagTableName") + "|" + GetCsvValue(row, "Name");
            }

            if (EqualsIgnoreCase(reportName, "hmi-text-list-items.csv"))
            {
                return NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath")) + "|" + GetCsvValue(row, "TextListName") + "|" + GetCsvValue(row, "EntryId") + "|" + GetCsvValue(row, "From") + "|" + GetCsvValue(row, "To") + "|" + GetCsvValue(row, "EntryType");
            }

            return HmiDigestRowSignature(row);
        }

        private static string HmiDigestRowSignature(Dictionary<string, string> row)
        {
            return HmiDigestRowSignature(string.Empty, row);
        }

        private static string HmiDigestRowSignature(string reportName, Dictionary<string, string> row)
        {
            if (row == null)
            {
                return string.Empty;
            }

            HashSet<string> ignoredColumns = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (EqualsIgnoreCase(reportName, "hmi-xml-files.csv"))
            {
                ignoredColumns.Add("Length");
                ignoredColumns.Add("Sha256");
            }

            return string.Join("; ", row.Keys
                .Where(x => !ignoredColumns.Contains(x))
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .Select(x => x + "=" + GetCsvValue(row, x))
                .ToArray());
        }

        private static Dictionary<string, string> FindHmiScreenItemRow(HmiApplyPreflightContext context, HmiApplyPatchItem patch)
        {
            string screen = PatchValue(patch, "screen");
            string item = PatchValue(patch, "item");
            string itemId = PatchValue(patch, "itemId");
            return context.ScreenItems.FirstOrDefault(x => EqualsIgnoreCase(GetCsvValue(x, "ScreenName"), screen)
                && (string.IsNullOrWhiteSpace(item) || EqualsIgnoreCase(GetCsvValue(x, "ItemName"), item) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), item))
                && (string.IsNullOrWhiteSpace(itemId) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), itemId)));
        }

        private static List<Dictionary<string, string>> FindHmiScreenItemRows(HmiApplyPreflightContext context, HmiApplyPatchItem patch)
        {
            string screen = PatchValue(patch, "screen");
            List<string> selectors = SplitHmiPatchList(FirstNonEmpty(PatchValue(patch, "itemIds"), PatchValue(patch, "items")));
            List<Dictionary<string, string>> result = new List<Dictionary<string, string>>();
            foreach (string selector in selectors)
            {
                Dictionary<string, string> row = context.ScreenItems.FirstOrDefault(x => EqualsIgnoreCase(GetCsvValue(x, "ScreenName"), screen)
                    && (EqualsIgnoreCase(GetCsvValue(x, "ItemName"), selector) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), selector)));
                if (row != null)
                {
                    result.Add(row);
                }
            }

            return result;
        }

        private static List<Dictionary<string, string>> FindHmiScreenBindingRows(HmiApplyPreflightContext context, HmiApplyPatchItem patch)
        {
            Dictionary<string, string> item = FindHmiScreenItemRow(context, patch);
            if (item == null)
            {
                return new List<Dictionary<string, string>>();
            }

            string link = PatchValue(patch, "link");
            return context.ScreenBindings
                .Where(x => EqualsIgnoreCase(GetCsvValue(x, "RelativePath"), GetCsvValue(item, "RelativePath"))
                    && EqualsIgnoreCase(GetCsvValue(x, "ScreenName"), GetCsvValue(item, "ScreenName"))
                    && EqualsIgnoreCase(GetCsvValue(x, "ItemId"), GetCsvValue(item, "ItemId"))
                    && EqualsIgnoreCase(GetCsvValue(x, "BindingKind"), link))
                .ToList();
        }

        private static Dictionary<string, string> FindHmiTextListEntryRow(HmiApplyPreflightContext context, HmiApplyPatchItem patch)
        {
            string textList = PatchValue(patch, "textList");
            string from = PatchValue(patch, "from");
            return context.TextListItems.FirstOrDefault(x => EqualsIgnoreCase(GetCsvValue(x, "TextListName"), textList)
                && EqualsIgnoreCase(GetCsvValue(x, "From"), from)
                && (string.IsNullOrWhiteSpace(PatchValue(patch, "to")) || EqualsIgnoreCase(GetCsvValue(x, "To"), PatchValue(patch, "to")))
                && (string.IsNullOrWhiteSpace(PatchValue(patch, "entryType")) || EqualsIgnoreCase(GetCsvValue(x, "EntryType"), PatchValue(patch, "entryType"))));
        }

        private static Dictionary<string, string> FindHmiEventHandlerRow(HmiApplyPreflightContext context, HmiApplyPatchItem patch)
        {
            string screen = PatchValue(patch, "screen");
            string item = PatchValue(patch, "item");
            string itemId = PatchValue(patch, "itemId");
            string eventName = PatchValue(patch, "event");
            string function = PatchValue(patch, "function");
            return context.EventHandlers.FirstOrDefault(x => EqualsIgnoreCase(GetCsvValue(x, "ScreenName"), screen)
                && EqualsIgnoreCase(GetCsvValue(x, "EventName"), eventName)
                && EqualsIgnoreCase(GetCsvValue(x, "FunctionName"), function)
                && (string.IsNullOrWhiteSpace(item) || EqualsIgnoreCase(GetCsvValue(x, "ItemName"), item) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), item))
                && (string.IsNullOrWhiteSpace(itemId) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), itemId)));
        }

        private static Dictionary<string, string> FindHmiObjectIndexLikeRow(string digestDir, string kind, string parentName, string name, string objectId, string relativePath)
        {
            string path = Path.Combine(digestDir, "hmi-object-index.csv");
            if (!File.Exists(path))
            {
                return null;
            }

            return ReadCsv(path).FirstOrDefault(x => EqualsIgnoreCase(GetCsvValue(x, "Kind"), kind)
                && EqualsIgnoreCase(GetCsvValue(x, "ParentName"), parentName)
                && EqualsIgnoreCase(GetCsvValue(x, "Name"), name)
                && EqualsIgnoreCase(GetCsvValue(x, "ObjectId"), objectId)
                && EqualsIgnoreCase(NormalizeHmiRelativePath(GetCsvValue(x, "RelativePath")), NormalizeHmiRelativePath(relativePath)));
        }

        private static void ValidateHmiCheckClean(HmiApplyPreflightContext context, List<HmiApplyPreflightIssue> issues)
        {
            List<Dictionary<string, string>> dirtyRows = context.CheckRows
                .Where(x => !EqualsIgnoreCase(GetCsvValue(x, "Status"), "unchanged"))
                .ToList();
            if (dirtyRows.Count == 0)
            {
                return;
            }

            AddHmiApplyPreflightIssue(
                issues,
                "error",
                "HMI_CHECK_NOT_CLEAN",
                null,
                "hmi-check-objects.csv",
                "HMI check report contains " + dirtyRows.Count + " non-unchanged object(s). Run hmi-check and resolve drift before preparing an HMI apply plan.");
        }

        private static void ValidateHmiApplyPatchItem(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            if (!string.IsNullOrWhiteSpace(patch.ParseError))
            {
                AddHmiApplyPreflightIssue(issues, "error", "PATCH_PARSE_ERROR", patch, plan.Selector, patch.ParseError);
                return;
            }

            string operation = PatchValue(patch, "op");
            if (string.IsNullOrWhiteSpace(operation))
            {
                AddHmiApplyPreflightIssue(issues, "error", "MISSING_OPERATION", patch, plan.Selector, "Patch row does not contain required field 'op'.");
                return;
            }

            if (EqualsIgnoreCase(operation, "set-attribute"))
            {
                ValidateHmiSetAttribute(context, patch, plan, issues);
            }
            else if (EqualsIgnoreCase(operation, "set-link"))
            {
                ValidateHmiSetLink(context, patch, plan, issues);
            }
            else if (EqualsIgnoreCase(operation, "set-text-list-entry"))
            {
                ValidateHmiSetTextListEntry(context, patch, plan, issues);
            }
            else if (EqualsIgnoreCase(operation, "set-screen-item-text"))
            {
                ValidateHmiSetScreenItemText(context, patch, plan, issues);
            }
            else if (EqualsIgnoreCase(operation, "duplicate-screen-items"))
            {
                ValidateHmiDuplicateScreenItems(context, patch, plan, issues);
            }
            else if (EqualsIgnoreCase(operation, "move-screen-items"))
            {
                ValidateHmiMoveScreenItems(context, patch, plan, issues);
            }
            else if (EqualsIgnoreCase(operation, "set-event-parameter"))
            {
                ValidateHmiSetEventParameter(context, patch, plan, issues);
            }
            else
            {
                AddHmiApplyPreflightIssue(issues, "error", "UNSUPPORTED_OPERATION", patch, plan.Selector, "Unsupported HMI preflight operation: " + operation);
            }
        }

        private static void ValidateHmiSetAttribute(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            RequireHmiPatchObject(patch, issues, "screen-item");
            string attribute = RequireHmiPatchField(patch, issues, "attribute");
            RequireHmiPatchField(patch, issues, "value");

            if (!string.IsNullOrWhiteSpace(attribute) && !IsAllowedHmiScreenItemAttribute(attribute))
            {
                AddHmiApplyPreflightIssue(issues, "error", "UNSUPPORTED_ATTRIBUTE", patch, plan.Selector, "Only screen item geometry attributes are supported now: Left, Top, Width, Height.");
            }

            Dictionary<string, string> row = ResolveHmiScreenItemSelector(context, patch, issues);
            if (row != null)
            {
                SetHmiPlanTargetFromRow(plan, "screen-item", HmiScreenItemDisplayName(row), row);
                ValidateHmiTargetCheckStatus(context, row, patch, plan, issues);
            }
        }

        private static void ValidateHmiSetLink(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            RequireHmiPatchObject(patch, issues, "screen-item");
            string link = RequireHmiPatchField(patch, issues, "link");
            string value = RequireHmiPatchField(patch, issues, "value");

            if (!string.IsNullOrWhiteSpace(link) && !IsAllowedHmiLinkKind(link))
            {
                AddHmiApplyPreflightIssue(issues, "error", "UNSUPPORTED_LINK", patch, plan.Selector, "Supported link kinds are: Tag, TextList, Picture, PictureOff.");
            }

            Dictionary<string, string> row = ResolveHmiScreenItemSelector(context, patch, issues);
            if (row != null)
            {
                SetHmiPlanTargetFromRow(plan, "screen-item", HmiScreenItemDisplayName(row), row);
                ValidateHmiTargetCheckStatus(context, row, patch, plan, issues);
            }

            if (!string.IsNullOrWhiteSpace(link) && !string.IsNullOrWhiteSpace(value))
            {
                ValidateHmiLinkTargetExists(context, patch, issues, link, value);
            }
        }

        private static void ValidateHmiSetTextListEntry(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            string textList = RequireHmiPatchField(patch, issues, "textList");
            string from = RequireHmiPatchField(patch, issues, "from");
            string culture = RequireHmiPatchField(patch, issues, "culture");
            RequireHmiPatchField(patch, issues, "text");

            if (string.IsNullOrWhiteSpace(textList) || string.IsNullOrWhiteSpace(from))
            {
                return;
            }

            List<Dictionary<string, string>> matches = context.TextListItems
                .Where(x => EqualsIgnoreCase(GetCsvValue(x, "TextListName"), textList)
                    && EqualsIgnoreCase(GetCsvValue(x, "From"), from)
                    && (string.IsNullOrWhiteSpace(PatchValue(patch, "to")) || EqualsIgnoreCase(GetCsvValue(x, "To"), PatchValue(patch, "to")))
                    && (string.IsNullOrWhiteSpace(PatchValue(patch, "entryType")) || EqualsIgnoreCase(GetCsvValue(x, "EntryType"), PatchValue(patch, "entryType"))))
                .ToList();

            Dictionary<string, string> row = RequireSingleHmiMatch(patch, issues, matches, "TEXT_LIST_ENTRY_NOT_FOUND", "TEXT_LIST_ENTRY_AMBIGUOUS", "text list entry " + textList + " from " + from);
            if (row == null)
            {
                return;
            }

            SetHmiPlanTargetFromRow(plan, "text-list-entry", GetCsvValue(row, "TextListName") + "[" + GetCsvValue(row, "From") + "]", row);
            ValidateHmiTargetCheckStatus(context, row, patch, plan, issues);

            if (!string.IsNullOrWhiteSpace(culture) && GetCsvValue(row, "Texts").IndexOf(culture + "=", StringComparison.OrdinalIgnoreCase) < 0)
            {
                AddHmiApplyPreflightIssue(issues, "warning", "TEXT_CULTURE_NOT_SEEN", patch, plan.Selector, "Culture '" + culture + "' is not present in current digest text entry.");
            }
        }

        private static void ValidateHmiSetScreenItemText(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            RequireHmiPatchObject(patch, issues, "screen-item");
            string culture = RequireHmiPatchField(patch, issues, "culture");
            RequireHmiPatchField(patch, issues, "text");

            Dictionary<string, string> row = ResolveHmiScreenItemSelector(context, patch, issues);
            if (row == null)
            {
                return;
            }

            SetHmiPlanTargetFromRow(plan, "screen-item-text", HmiScreenItemDisplayName(row), row);
            ValidateHmiTargetCheckStatus(context, row, patch, plan, issues);

            if (!string.IsNullOrWhiteSpace(culture) && GetCsvValue(row, "Text").IndexOf(culture + "=", StringComparison.OrdinalIgnoreCase) < 0)
            {
                AddHmiApplyPreflightIssue(issues, "warning", "TEXT_CULTURE_NOT_SEEN", patch, plan.Selector, "Culture '" + culture + "' is not present in current screen item text.");
            }
        }

        private static void ValidateHmiDuplicateScreenItems(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            RequireHmiPatchObject(patch, issues, "screen-items");
            RequireHmiPatchField(patch, issues, "screen");
            RequireHmiPatchField(patch, issues, "newItemIds");
            RequireHmiPatchField(patch, issues, "newItems");
            RequireHmiPatchField(patch, issues, "deltaY");
            ParseHmiPatchInt(patch, "deltaX", 0, issues, plan.Selector);
            ParseHmiPatchInt(patch, "deltaY", 0, issues, plan.Selector);

            List<Dictionary<string, string>> rows = ResolveHmiScreenItemListSelector(context, patch, issues);
            List<string> newIds = SplitHmiPatchList(PatchValue(patch, "newItemIds"));
            List<string> newNames = SplitHmiPatchList(PatchValue(patch, "newItems"));
            if (rows.Count == 0)
            {
                return;
            }

            if (newIds.Count != rows.Count)
            {
                AddHmiApplyPreflightIssue(issues, "error", "DUPLICATE_NEW_ID_COUNT_MISMATCH", patch, plan.Selector, "newItemIds count must match selected source item count.");
            }

            if (newNames.Count != rows.Count)
            {
                AddHmiApplyPreflightIssue(issues, "error", "DUPLICATE_NEW_NAME_COUNT_MISMATCH", patch, plan.Selector, "newItems count must match selected source item count.");
            }

            if (newIds.Count != newIds.Distinct(StringComparer.OrdinalIgnoreCase).Count())
            {
                AddHmiApplyPreflightIssue(issues, "error", "DUPLICATE_NEW_ID_REPEATED", patch, plan.Selector, "newItemIds contains repeated IDs.");
            }

            if (newNames.Count != newNames.Distinct(StringComparer.OrdinalIgnoreCase).Count())
            {
                AddHmiApplyPreflightIssue(issues, "error", "DUPLICATE_NEW_NAME_REPEATED", patch, plan.Selector, "newItems contains repeated names.");
            }

            string screen = GetCsvValue(rows[0], "ScreenName");
            foreach (string id in newIds)
            {
                if (context.ScreenItems.Any(x => EqualsIgnoreCase(GetCsvValue(x, "ScreenName"), screen) && EqualsIgnoreCase(GetCsvValue(x, "ItemId"), id)))
                {
                    AddHmiApplyPreflightIssue(issues, "error", "DUPLICATE_NEW_ID_EXISTS", patch, plan.Selector, "Screen item ID already exists: " + id);
                }
            }

            foreach (string name in newNames)
            {
                if (context.ScreenItems.Any(x => EqualsIgnoreCase(GetCsvValue(x, "ScreenName"), screen) && EqualsIgnoreCase(GetCsvValue(x, "ItemName"), name)))
                {
                    AddHmiApplyPreflightIssue(issues, "error", "DUPLICATE_NEW_NAME_EXISTS", patch, plan.Selector, "Screen item name already exists: " + name);
                }
            }

            SetHmiPlanTargetFromRow(plan, "screen-items-duplicate", screen + "/" + string.Join(",", newNames.ToArray()), rows[0]);
            ValidateHmiTargetCheckStatus(context, rows[0], patch, plan, issues);
        }

        private static void ValidateHmiMoveScreenItems(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            RequireHmiPatchObject(patch, issues, "screen-items");
            RequireHmiPatchField(patch, issues, "screen");
            RequireHmiPatchField(patch, issues, "deltaY");
            int deltaX = ParseHmiPatchInt(patch, "deltaX", 0, issues, plan.Selector);
            int deltaY = ParseHmiPatchInt(patch, "deltaY", 0, issues, plan.Selector);

            if (deltaX == 0 && deltaY == 0)
            {
                AddHmiApplyPreflightIssue(issues, "warning", "MOVE_ZERO_DELTA", patch, plan.Selector, "move-screen-items has zero deltaX and deltaY.");
            }

            List<Dictionary<string, string>> rows = ResolveHmiScreenItemListSelector(context, patch, issues);
            if (rows.Count == 0)
            {
                return;
            }

            string screen = GetCsvValue(rows[0], "ScreenName");
            SetHmiPlanTargetFromRow(plan, "screen-items-move", screen + "/" + string.Join(",", rows.Select(x => GetCsvValue(x, "ItemName")).ToArray()), rows[0]);
            ValidateHmiTargetCheckStatus(context, rows[0], patch, plan, issues);
        }

        private static void ValidateHmiSetEventParameter(HmiApplyPreflightContext context, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            string screen = RequireHmiPatchField(patch, issues, "screen");
            string eventName = RequireHmiPatchField(patch, issues, "event");
            string function = RequireHmiPatchField(patch, issues, "function");
            string parameter = RequireHmiPatchField(patch, issues, "parameter");
            string value = RequireHmiPatchField(patch, issues, "value");

            if (string.IsNullOrWhiteSpace(screen) || string.IsNullOrWhiteSpace(eventName) || string.IsNullOrWhiteSpace(function) || string.IsNullOrWhiteSpace(parameter))
            {
                return;
            }

            string item = PatchValue(patch, "item");
            string itemId = PatchValue(patch, "itemId");
            List<Dictionary<string, string>> matches = context.EventHandlers
                .Where(x => EqualsIgnoreCase(GetCsvValue(x, "ScreenName"), screen)
                    && EqualsIgnoreCase(GetCsvValue(x, "EventName"), eventName)
                    && EqualsIgnoreCase(GetCsvValue(x, "FunctionName"), function)
                    && (string.IsNullOrWhiteSpace(item) || EqualsIgnoreCase(GetCsvValue(x, "ItemName"), item) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), item))
                    && (string.IsNullOrWhiteSpace(itemId) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), itemId)))
                .ToList();

            Dictionary<string, string> row = RequireSingleHmiMatch(patch, issues, matches, "EVENT_HANDLER_NOT_FOUND", "EVENT_HANDLER_AMBIGUOUS", "event handler " + screen + "/" + eventName + "/" + function);
            if (row == null)
            {
                return;
            }

            SetHmiPlanTargetFromRow(plan, "event-handler", HmiEventHandlerDisplayName(row), row);
            ValidateHmiTargetCheckStatus(context, row, patch, plan, issues);

            if (!ContainsHmiEventParameter(GetCsvValue(row, "Parameters"), parameter))
            {
                AddHmiApplyPreflightIssue(issues, "error", "EVENT_PARAMETER_NOT_FOUND", patch, plan.Selector, "The selected event handler does not contain parameter '" + parameter + "'.");
            }

            if (!string.IsNullOrWhiteSpace(value))
            {
                if (EqualsIgnoreCase(parameter, "Tag"))
                {
                    ValidateHmiTagExists(context, patch, issues, value);
                }
                else if (parameter.IndexOf("screen", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    ValidateHmiScreenExists(context, patch, issues, value);
                }
            }
        }

        private static void RequireHmiPatchObject(HmiApplyPatchItem patch, List<HmiApplyPreflightIssue> issues, string expected)
        {
            string value = PatchValue(patch, "object");
            if (string.IsNullOrWhiteSpace(value))
            {
                AddHmiApplyPreflightIssue(issues, "error", "MISSING_OBJECT", patch, HmiPatchSelectorSummary(patch), "Patch row does not contain required field 'object'. Expected '" + expected + "'.");
                return;
            }

            if (!EqualsIgnoreCase(value, expected))
            {
                AddHmiApplyPreflightIssue(issues, "error", "UNSUPPORTED_OBJECT", patch, HmiPatchSelectorSummary(patch), "Unsupported object '" + value + "'. Expected '" + expected + "'.");
            }
        }

        private static string RequireHmiPatchField(HmiApplyPatchItem patch, List<HmiApplyPreflightIssue> issues, string field)
        {
            string value = PatchValue(patch, field);
            if (string.IsNullOrWhiteSpace(value))
            {
                AddHmiApplyPreflightIssue(issues, "error", "MISSING_FIELD", patch, HmiPatchSelectorSummary(patch), "Patch row does not contain required field '" + field + "'.");
            }

            return value;
        }

        private static Dictionary<string, string> ResolveHmiScreenItemSelector(HmiApplyPreflightContext context, HmiApplyPatchItem patch, List<HmiApplyPreflightIssue> issues)
        {
            string screen = RequireHmiPatchField(patch, issues, "screen");
            string item = PatchValue(patch, "item");
            string itemId = PatchValue(patch, "itemId");
            if (string.IsNullOrWhiteSpace(screen) || (string.IsNullOrWhiteSpace(item) && string.IsNullOrWhiteSpace(itemId)))
            {
                if (string.IsNullOrWhiteSpace(item) && string.IsNullOrWhiteSpace(itemId))
                {
                    AddHmiApplyPreflightIssue(issues, "error", "MISSING_ITEM_SELECTOR", patch, HmiPatchSelectorSummary(patch), "Patch row must contain 'item' or 'itemId'.");
                }

                return null;
            }

            List<Dictionary<string, string>> matches = context.ScreenItems
                .Where(x => EqualsIgnoreCase(GetCsvValue(x, "ScreenName"), screen)
                    && (string.IsNullOrWhiteSpace(item) || EqualsIgnoreCase(GetCsvValue(x, "ItemName"), item) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), item))
                    && (string.IsNullOrWhiteSpace(itemId) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), itemId)))
                .ToList();

            return RequireSingleHmiMatch(patch, issues, matches, "SCREEN_ITEM_NOT_FOUND", "SCREEN_ITEM_AMBIGUOUS", "screen item " + screen + "/" + FirstNonEmpty(item, itemId));
        }

        private static List<Dictionary<string, string>> ResolveHmiScreenItemListSelector(HmiApplyPreflightContext context, HmiApplyPatchItem patch, List<HmiApplyPreflightIssue> issues)
        {
            string screen = RequireHmiPatchField(patch, issues, "screen");
            List<string> selectors = SplitHmiPatchList(FirstNonEmpty(PatchValue(patch, "itemIds"), PatchValue(patch, "items")));
            if (string.IsNullOrWhiteSpace(screen) || selectors.Count == 0)
            {
                if (selectors.Count == 0)
                {
                    AddHmiApplyPreflightIssue(issues, "error", "MISSING_ITEM_LIST_SELECTOR", patch, HmiPatchSelectorSummary(patch), "Patch row must contain 'itemIds' or 'items'.");
                }

                return new List<Dictionary<string, string>>();
            }

            List<Dictionary<string, string>> result = new List<Dictionary<string, string>>();
            foreach (string selector in selectors)
            {
                List<Dictionary<string, string>> matches = context.ScreenItems
                    .Where(x => EqualsIgnoreCase(GetCsvValue(x, "ScreenName"), screen)
                        && (EqualsIgnoreCase(GetCsvValue(x, "ItemName"), selector) || EqualsIgnoreCase(GetCsvValue(x, "ItemId"), selector)))
                    .ToList();
                Dictionary<string, string> row = RequireSingleHmiMatch(patch, issues, matches, "SCREEN_ITEM_NOT_FOUND", "SCREEN_ITEM_AMBIGUOUS", "screen item " + screen + "/" + selector);
                if (row != null)
                {
                    result.Add(row);
                }
            }

            return result;
        }

        private static Dictionary<string, string> RequireSingleHmiMatch(HmiApplyPatchItem patch, List<HmiApplyPreflightIssue> issues, List<Dictionary<string, string>> matches, string notFoundCode, string ambiguousCode, string selector)
        {
            if (matches.Count == 0)
            {
                AddHmiApplyPreflightIssue(issues, "error", notFoundCode, patch, HmiPatchSelectorSummary(patch), "Could not find " + selector + " in current HMI digest.");
                return null;
            }

            if (matches.Count > 1)
            {
                AddHmiApplyPreflightIssue(issues, "error", ambiguousCode, patch, HmiPatchSelectorSummary(patch), "Selector matched " + matches.Count + " objects for " + selector + ". Add a more specific selector.");
                return null;
            }

            return matches[0];
        }

        private static void SetHmiPlanTargetFromRow(HmiApplyPreflightPlanItem plan, string kind, string name, Dictionary<string, string> row)
        {
            plan.TargetKind = kind;
            plan.TargetName = name;
            plan.TargetRelativePath = NormalizeHmiRelativePath(GetCsvValue(row, "RelativePath"));
        }

        private static void ValidateHmiTargetCheckStatus(HmiApplyPreflightContext context, Dictionary<string, string> targetRow, HmiApplyPatchItem patch, HmiApplyPreflightPlanItem plan, List<HmiApplyPreflightIssue> issues)
        {
            string relativePath = NormalizeHmiRelativePath(GetCsvValue(targetRow, "RelativePath"));
            if (string.IsNullOrWhiteSpace(relativePath))
            {
                AddHmiApplyPreflightIssue(issues, "error", "TARGET_WITHOUT_RELATIVE_PATH", patch, plan.Selector, "Resolved HMI target does not contain RelativePath in digest.");
                return;
            }

            Dictionary<string, string> checkRow = FindHmiCheckRow(context, relativePath);
            if (checkRow == null)
            {
                AddHmiApplyPreflightIssue(issues, "error", "TARGET_NOT_IN_CHECK", patch, plan.Selector, "Resolved HMI XML is not present in hmi-check-objects.csv: " + relativePath);
                return;
            }

            plan.CheckStatus = GetCsvValue(checkRow, "Status");
            plan.TargetComparableSha256 = FirstNonEmpty(GetCsvValue(checkRow, "ComparableSha256"), GetCsvValue(checkRow, "CloneComparableSha256"), GetCsvValue(checkRow, "CurrentComparableSha256"));
            if (!EqualsIgnoreCase(plan.CheckStatus, "unchanged"))
            {
                AddHmiApplyPreflightIssue(issues, "error", "TARGET_NOT_UNCHANGED", patch, plan.Selector, "Resolved HMI XML is not clean in current hmi-check report: " + relativePath + " status=" + plan.CheckStatus);
            }
        }

        private static Dictionary<string, string> FindHmiCheckRow(HmiApplyPreflightContext context, string relativePath)
        {
            string normalized = NormalizeHmiRelativePath(relativePath);
            return context.CheckRows.FirstOrDefault(x =>
                EqualsIgnoreCase(NormalizeHmiRelativePath(GetCsvValue(x, "RelativePath")), normalized)
                || EqualsIgnoreCase(NormalizeHmiRelativePath(GetCsvValue(x, "CloneRelativePath")), normalized)
                || EqualsIgnoreCase(NormalizeHmiRelativePath(GetCsvValue(x, "CurrentRelativePath")), normalized));
        }

        private static void ValidateHmiLinkTargetExists(HmiApplyPreflightContext context, HmiApplyPatchItem patch, List<HmiApplyPreflightIssue> issues, string link, string value)
        {
            if (EqualsIgnoreCase(link, "Tag"))
            {
                ValidateHmiTagExists(context, patch, issues, value);
            }
            else if (EqualsIgnoreCase(link, "TextList"))
            {
                string name = NormalizeHmiReferenceValue(value);
                if (!context.TextListItems.Any(x => EqualsIgnoreCase(GetCsvValue(x, "TextListName"), name)))
                {
                    AddHmiApplyPreflightIssue(issues, "error", "TEXT_LIST_NOT_FOUND", patch, HmiPatchSelectorSummary(patch), "Text list was not found in digest: " + name);
                }
            }
            else if (EqualsIgnoreCase(link, "Picture") || EqualsIgnoreCase(link, "PictureOff"))
            {
                string name = NormalizeHmiReferenceValue(value);
                if (!context.ScreenBindings.Any(x => (EqualsIgnoreCase(GetCsvValue(x, "BindingKind"), "Picture") || EqualsIgnoreCase(GetCsvValue(x, "BindingKind"), "PictureOff"))
                    && EqualsIgnoreCase(NormalizeHmiReferenceValue(GetCsvValue(x, "TargetName")), name)))
                {
                    AddHmiApplyPreflightIssue(issues, "warning", "PICTURE_REFERENCE_NOT_SEEN", patch, HmiPatchSelectorSummary(patch), "Picture reference is not visible in current screen bindings digest: " + name);
                }
            }
        }

        private static void ValidateHmiTagExists(HmiApplyPreflightContext context, HmiApplyPatchItem patch, List<HmiApplyPreflightIssue> issues, string value)
        {
            string tagName = NormalizeHmiReferenceValue(value);
            if (string.IsNullOrWhiteSpace(tagName))
            {
                AddHmiApplyPreflightIssue(issues, "error", "EMPTY_TAG_REFERENCE", patch, HmiPatchSelectorSummary(patch), "Tag reference is empty.");
                return;
            }

            if (!context.TagDetails.Any(x => EqualsIgnoreCase(GetCsvValue(x, "Name"), tagName) || EqualsIgnoreCase(GetCsvValue(x, "ControllerTag"), tagName)))
            {
                AddHmiApplyPreflightIssue(issues, "error", "TAG_NOT_FOUND", patch, HmiPatchSelectorSummary(patch), "Tag was not found in digest: " + tagName);
            }
        }

        private static void ValidateHmiScreenExists(HmiApplyPreflightContext context, HmiApplyPatchItem patch, List<HmiApplyPreflightIssue> issues, string value)
        {
            string screenName = NormalizeHmiReferenceValue(value);
            if (string.IsNullOrWhiteSpace(screenName))
            {
                AddHmiApplyPreflightIssue(issues, "warning", "EMPTY_SCREEN_REFERENCE", patch, HmiPatchSelectorSummary(patch), "Screen reference is empty.");
                return;
            }

            if (!context.XmlFiles.Any(x => IsHmiScreenLikeKind(GetCsvValue(x, "Kind"), GetCsvValue(x, "RelativePath")) && EqualsIgnoreCase(GetCsvValue(x, "Name"), screenName)))
            {
                AddHmiApplyPreflightIssue(issues, "error", "SCREEN_NOT_FOUND", patch, HmiPatchSelectorSummary(patch), "Screen was not found in digest: " + screenName);
            }
        }

        private static bool ContainsHmiEventParameter(string parameters, string parameter)
        {
            if (string.IsNullOrWhiteSpace(parameters) || string.IsNullOrWhiteSpace(parameter))
            {
                return false;
            }

            return parameters.IndexOf(parameter + "=", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static bool IsAllowedHmiScreenItemAttribute(string attribute)
        {
            return EqualsIgnoreCase(attribute, "Left")
                || EqualsIgnoreCase(attribute, "Top")
                || EqualsIgnoreCase(attribute, "Width")
                || EqualsIgnoreCase(attribute, "Height");
        }

        private static bool IsAllowedHmiLinkKind(string link)
        {
            return EqualsIgnoreCase(link, "Tag")
                || EqualsIgnoreCase(link, "TextList")
                || EqualsIgnoreCase(link, "Picture")
                || EqualsIgnoreCase(link, "PictureOff");
        }

        private static string NormalizeHmiReferenceValue(string value)
        {
            string result = EmptyIfNull(value).Trim();
            if (result.Length >= 2 && result[0] == '"' && result[result.Length - 1] == '"')
            {
                result = result.Substring(1, result.Length - 2);
            }

            return result.Trim();
        }

        private static string HmiScreenItemDisplayName(Dictionary<string, string> row)
        {
            return GetCsvValue(row, "ScreenName") + "/" + FirstNonEmpty(GetCsvValue(row, "ItemName"), GetCsvValue(row, "ItemId"));
        }

        private static string HmiEventHandlerDisplayName(Dictionary<string, string> row)
        {
            return GetCsvValue(row, "ScreenName") + "/" + FirstNonEmpty(GetCsvValue(row, "ItemName"), GetCsvValue(row, "ItemId")) + "/" + GetCsvValue(row, "EventName") + "/" + GetCsvValue(row, "FunctionName");
        }

        private static string PatchValue(HmiApplyPatchItem patch, string key)
        {
            if (patch == null || patch.Fields == null)
            {
                return string.Empty;
            }

            string value;
            return patch.Fields.TryGetValue(key, out value) ? value : string.Empty;
        }

        private static List<string> SplitHmiPatchList(string value)
        {
            return EmptyIfNull(value)
                .Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(x => x.Trim())
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .ToList();
        }

        private static int ParseHmiPatchInt(HmiApplyPatchItem patch, string field, int defaultValue, List<HmiApplyPreflightIssue> issues, string selector)
        {
            string value = PatchValue(patch, field);
            if (string.IsNullOrWhiteSpace(value))
            {
                return defaultValue;
            }

            int parsed;
            if (!int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out parsed))
            {
                AddHmiApplyPreflightIssue(issues, "error", "INVALID_INTEGER_FIELD", patch, selector, "Patch field '" + field + "' must be an integer.");
                return defaultValue;
            }

            return parsed;
        }

        private static int ParseIntOrDefault(string value, int defaultValue)
        {
            int parsed;
            return int.TryParse(EmptyIfNull(value), NumberStyles.Integer, CultureInfo.InvariantCulture, out parsed) ? parsed : defaultValue;
        }

        private static string HmiPatchSelectorSummary(HmiApplyPatchItem patch)
        {
            if (patch == null)
            {
                return string.Empty;
            }

            List<string> parts = new List<string>();
            AddHmiPatchSelectorPart(parts, "screen", PatchValue(patch, "screen"));
            AddHmiPatchSelectorPart(parts, "item", FirstNonEmpty(PatchValue(patch, "item"), PatchValue(patch, "itemId")));
            AddHmiPatchSelectorPart(parts, "textList", PatchValue(patch, "textList"));
            AddHmiPatchSelectorPart(parts, "from", PatchValue(patch, "from"));
            AddHmiPatchSelectorPart(parts, "event", PatchValue(patch, "event"));
            AddHmiPatchSelectorPart(parts, "function", PatchValue(patch, "function"));
            AddHmiPatchSelectorPart(parts, "parameter", PatchValue(patch, "parameter"));
            AddHmiPatchSelectorPart(parts, "attribute", PatchValue(patch, "attribute"));
            AddHmiPatchSelectorPart(parts, "link", PatchValue(patch, "link"));
            return parts.Count == 0 ? "row " + patch.Row : string.Join("; ", parts.ToArray());
        }

        private static void AddHmiPatchSelectorPart(List<string> parts, string key, string value)
        {
            if (!string.IsNullOrWhiteSpace(value))
            {
                parts.Add(key + "=" + value);
            }
        }

        private static void AddHmiApplyPreflightIssue(List<HmiApplyPreflightIssue> issues, string severity, string code, HmiApplyPatchItem patch, string selector, string message)
        {
            issues.Add(new HmiApplyPreflightIssue
            {
                Severity = severity,
                Code = code,
                Row = patch == null ? 0 : patch.Row,
                Operation = patch == null ? string.Empty : FirstNonEmpty(patch.Operation, PatchValue(patch, "op")),
                Selector = selector,
                Message = message
            });
        }

        private static Dictionary<string, string> ParseFlatJsonObject(string text, string context)
        {
            string trimmed = EmptyIfNull(text).Trim();
            if (!trimmed.StartsWith("{", StringComparison.Ordinal) || !trimmed.EndsWith("}", StringComparison.Ordinal))
            {
                throw new InvalidDataException(context + " is not a JSON object.");
            }

            Dictionary<string, string> result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            int index = 1;
            while (true)
            {
                SkipJsonWhitespace(trimmed, ref index);
                if (index >= trimmed.Length - 1)
                {
                    break;
                }

                string key = ReadJsonStringLiteral(trimmed, ref index, context + " key");
                SkipJsonWhitespace(trimmed, ref index);
                if (index >= trimmed.Length || trimmed[index] != ':')
                {
                    throw new InvalidDataException(context + " has a property without ':'.");
                }

                index++;
                SkipJsonWhitespace(trimmed, ref index);
                string value;
                if (index < trimmed.Length && trimmed[index] == '"')
                {
                    value = ReadJsonStringLiteral(trimmed, ref index, context + " value");
                }
                else
                {
                    int start = index;
                    while (index < trimmed.Length && trimmed[index] != ',' && trimmed[index] != '}')
                    {
                        index++;
                    }

                    value = trimmed.Substring(start, index - start).Trim();
                    if (EqualsIgnoreCase(value, "null"))
                    {
                        value = string.Empty;
                    }
                }

                if (string.IsNullOrWhiteSpace(key))
                {
                    throw new InvalidDataException(context + " contains an empty property name.");
                }

                result[key] = value;
                SkipJsonWhitespace(trimmed, ref index);
                if (index < trimmed.Length && trimmed[index] == ',')
                {
                    index++;
                    continue;
                }

                if (index < trimmed.Length && trimmed[index] == '}')
                {
                    break;
                }

                if (index < trimmed.Length - 1)
                {
                    throw new InvalidDataException(context + " has invalid JSON object syntax.");
                }
            }

            return result;
        }

        private static string ReadJsonStringLiteral(string text, ref int index, string context)
        {
            if (index >= text.Length || text[index] != '"')
            {
                throw new InvalidDataException(context + " is not a JSON string.");
            }

            index++;
            StringBuilder raw = new StringBuilder();
            bool escaped = false;
            while (index < text.Length)
            {
                char c = text[index++];
                if (escaped)
                {
                    raw.Append('\\');
                    raw.Append(c);
                    escaped = false;
                    continue;
                }

                if (c == '\\')
                {
                    escaped = true;
                    continue;
                }

                if (c == '"')
                {
                    return JsonUnescape(raw.ToString());
                }

                raw.Append(c);
            }

            throw new InvalidDataException(context + " is not closed.");
        }

        private static void SkipJsonWhitespace(string text, ref int index)
        {
            while (index < text.Length && char.IsWhiteSpace(text[index]))
            {
                index++;
            }
        }

        private static List<HmiCapabilityObjectRecord> CollectHmiCapabilityObjects(HmiInventorySnapshot snapshot)
        {
            List<HmiCapabilityObjectRecord> records = new List<HmiCapabilityObjectRecord>();
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (HmiTargetRecord target in snapshot.Targets)
            {
                AddHmiCapabilityObject(records, seen, "HmiTarget", target.TargetPath, target.Name, target.Object, string.Empty);
                AddHmiTargetContainerCapabilities(records, seen, target);
            }

            foreach (HmiScreenRecord screen in snapshot.Screens)
            {
                AddHmiCapabilityObject(records, seen, screen.Kind, CombinePath(screen.TargetPath, screen.FolderPath + "/" + screen.Name), screen.Name, screen.Object, string.Empty);
            }

            foreach (HmiTagTableRecord table in snapshot.TagTables)
            {
                AddHmiCapabilityObject(records, seen, "TagTable", CombinePath(table.TargetPath, table.FolderPath + "/" + table.Name), table.Name, table.Object, string.Empty);
            }

            foreach (HmiTagRecord tag in snapshot.Tags)
            {
                AddHmiCapabilityObject(records, seen, "Tag", CombinePath(tag.TargetPath, tag.FolderPath + "/" + tag.TableName + "/" + tag.Name), tag.Name, tag.Object, string.Empty);
            }

            AddHmiNamedCapabilityObjects(records, seen, snapshot.TextLists);
            AddHmiNamedCapabilityObjects(records, seen, snapshot.GraphicLists);
            AddHmiNamedCapabilityObjects(records, seen, snapshot.Scripts);
            AddHmiNamedCapabilityObjects(records, seen, snapshot.Connections);

            return records
                .OrderBy(x => x.Category, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.Path, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.Name, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static void AddHmiTargetContainerCapabilities(List<HmiCapabilityObjectRecord> records, HashSet<string> seen, HmiTargetRecord target)
        {
            object hmiTarget = target.Object;
            if (hmiTarget == null)
            {
                return;
            }

            AddHmiScreenFolderCapability(records, seen, target.TargetPath, TryGetPropertyValue(hmiTarget, "ScreenFolder"), "Screens", "ScreenFolder", "Screens", "Folders");
            AddHmiScreenFolderCapability(records, seen, target.TargetPath, TryGetPropertyValue(hmiTarget, "ScreenPopupFolder"), "Pop-up screens", "PopupFolder", "ScreenPopups", "Folders");
            AddHmiScreenFolderCapability(records, seen, target.TargetPath, TryGetPropertyValue(hmiTarget, "ScreenSlideinFolder"), "Slideins", "SlideinFolder", "ScreenSlideins", "Folders");
            AddHmiScreenFolderCapability(records, seen, target.TargetPath, TryGetPropertyValue(hmiTarget, "ScreenTemplateFolder"), "Templates", "TemplateFolder", "ScreenTemplates", "Folders");
            AddHmiTagFolderCapability(records, seen, target.TargetPath, TryGetPropertyValue(hmiTarget, "TagFolder"), "HMI tags");
            AddHmiScriptFolderCapability(records, seen, target.TargetPath, TryGetPropertyValue(hmiTarget, "VBScriptFolder"), "VB scripts");
            AddHmiCapabilityObject(records, seen, "TextListsComposition", CombinePath(target.TargetPath, "TextLists"), "TextLists", TryGetPropertyValue(hmiTarget, "TextLists"), string.Empty);
            AddHmiCapabilityObject(records, seen, "GraphicListsComposition", CombinePath(target.TargetPath, "GraphicLists"), "GraphicLists", TryGetPropertyValue(hmiTarget, "GraphicLists"), string.Empty);
            AddHmiCapabilityObject(records, seen, "CyclesComposition", CombinePath(target.TargetPath, "Cycles"), "Cycles", TryGetPropertyValue(hmiTarget, "Cycles"), string.Empty);
            AddHmiCapabilityObject(records, seen, "ConnectionsComposition", CombinePath(target.TargetPath, "Connections"), "Connections", TryGetPropertyValue(hmiTarget, "Connections"), string.Empty);
        }

        private static void AddHmiScreenFolderCapability(List<HmiCapabilityObjectRecord> records, HashSet<string> seen, string targetPath, object folder, string folderPath, string category, string itemProperty, string childFoldersProperty)
        {
            if (folder == null)
            {
                return;
            }

            string path = CombinePath(targetPath, folderPath);
            AddHmiCapabilityObject(records, seen, category, path, LastLogicalPathPart(folderPath), folder, string.Empty);
            AddHmiCapabilityObject(records, seen, category + "ItemsComposition", CombinePath(path, itemProperty), itemProperty, TryGetPropertyValue(folder, itemProperty), string.Empty);
            AddHmiCapabilityObject(records, seen, category + "FoldersComposition", CombinePath(path, childFoldersProperty), childFoldersProperty, TryGetPropertyValue(folder, childFoldersProperty), string.Empty);

            foreach (object child in AsEnumerable(TryGetPropertyValue(folder, childFoldersProperty)))
            {
                AddHmiScreenFolderCapability(records, seen, targetPath, child, CombinePath(folderPath, SafeName(child)), category, itemProperty, childFoldersProperty);
            }
        }

        private static void AddHmiTagFolderCapability(List<HmiCapabilityObjectRecord> records, HashSet<string> seen, string targetPath, object folder, string folderPath)
        {
            if (folder == null)
            {
                return;
            }

            string path = CombinePath(targetPath, folderPath);
            AddHmiCapabilityObject(records, seen, "TagFolder", path, LastLogicalPathPart(folderPath), folder, string.Empty);
            AddHmiCapabilityObject(records, seen, "TagTablesComposition", CombinePath(path, "TagTables"), "TagTables", TryGetPropertyValue(folder, "TagTables"), string.Empty);
            AddHmiCapabilityObject(records, seen, "TagFoldersComposition", CombinePath(path, "Folders"), "Folders", TryGetPropertyValue(folder, "Folders"), string.Empty);

            foreach (object child in AsEnumerable(TryGetPropertyValue(folder, "Folders")))
            {
                AddHmiTagFolderCapability(records, seen, targetPath, child, CombinePath(folderPath, SafeName(child)));
            }
        }

        private static void AddHmiScriptFolderCapability(List<HmiCapabilityObjectRecord> records, HashSet<string> seen, string targetPath, object folder, string folderPath)
        {
            if (folder == null)
            {
                return;
            }

            string path = CombinePath(targetPath, folderPath);
            AddHmiCapabilityObject(records, seen, "VBScriptFolder", path, LastLogicalPathPart(folderPath), folder, string.Empty);
            AddHmiCapabilityObject(records, seen, "VBScriptsComposition", CombinePath(path, "VBScripts"), "VBScripts", TryGetPropertyValue(folder, "VBScripts"), string.Empty);
            AddHmiCapabilityObject(records, seen, "VBScriptFoldersComposition", CombinePath(path, "Folders"), "Folders", TryGetPropertyValue(folder, "Folders"), string.Empty);

            foreach (object child in AsEnumerable(TryGetPropertyValue(folder, "Folders")))
            {
                AddHmiScriptFolderCapability(records, seen, targetPath, child, CombinePath(folderPath, SafeName(child)));
            }
        }

        private static void AddHmiNamedCapabilityObjects(List<HmiCapabilityObjectRecord> records, HashSet<string> seen, List<HmiNamedRecord> namedRecords)
        {
            foreach (HmiNamedRecord record in namedRecords)
            {
                AddHmiCapabilityObject(records, seen, record.Kind, CombinePath(record.TargetPath, record.ParentPath + "/" + record.Name), record.Name, record.Object, string.Empty);
            }
        }

        private static void AddHmiCapabilityObject(List<HmiCapabilityObjectRecord> records, HashSet<string> seen, string category, string path, string name, object value, string message)
        {
            string typeName = value == null ? string.Empty : value.GetType().FullName;
            string normalizedPath = NormalizeLogicalPath(path);
            string key = category + "|" + normalizedPath + "|" + typeName + "|" + EmptyIfNull(name);
            if (!seen.Add(key))
            {
                return;
            }

            records.Add(new HmiCapabilityObjectRecord
            {
                Category = EmptyIfNull(category),
                Path = normalizedPath,
                Name = EmptyIfNull(name),
                TypeName = typeName,
                Object = value,
                Message = value == null ? FirstNonEmpty(message, "Object/property was not found.") : EmptyIfNull(message)
            });
        }

        private static string[] HmiCapabilityObjectRow(HmiCapabilityObjectRecord record, List<HmiCapabilityMethodRecord> methods)
        {
            List<HmiCapabilityMethodRecord> local = methods
                .Where(x => EqualsIgnoreCase(x.Category, record.Category) && EqualsIgnoreCase(x.Path, record.Path) && EqualsIgnoreCase(x.TypeName, record.TypeName))
                .ToList();
            int importCount = local.Count(x => EqualsIgnoreCase(x.MethodKind, "Import"));
            int exportCount = local.Count(x => EqualsIgnoreCase(x.MethodKind, "Export"));
            int createCount = local.Count(x => EqualsIgnoreCase(x.MethodKind, "Create"));
            int deleteCount = local.Count(x => EqualsIgnoreCase(x.MethodKind, "Delete"));

            return new[]
            {
                record.Category,
                record.Path,
                record.Name,
                record.TypeName,
                (importCount > 0).ToString(),
                Convert.ToString(importCount),
                (exportCount > 0).ToString(),
                Convert.ToString(exportCount),
                (createCount > 0).ToString(),
                Convert.ToString(createCount),
                (deleteCount > 0).ToString(),
                Convert.ToString(deleteCount),
                Convert.ToString(local.Count),
                record.Message
            };
        }

        private static bool IsHmiCapabilityMethodName(string name)
        {
            return name.IndexOf("Import", StringComparison.OrdinalIgnoreCase) >= 0
                || name.IndexOf("Export", StringComparison.OrdinalIgnoreCase) >= 0
                || name.IndexOf("Create", StringComparison.OrdinalIgnoreCase) >= 0
                || name.IndexOf("Delete", StringComparison.OrdinalIgnoreCase) >= 0
                || name.IndexOf("Generate", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static string HmiCapabilityMethodKind(string name)
        {
            if (name.IndexOf("Import", StringComparison.OrdinalIgnoreCase) >= 0) return "Import";
            if (name.IndexOf("Export", StringComparison.OrdinalIgnoreCase) >= 0) return "Export";
            if (name.IndexOf("Create", StringComparison.OrdinalIgnoreCase) >= 0) return "Create";
            if (name.IndexOf("Delete", StringComparison.OrdinalIgnoreCase) >= 0) return "Delete";
            if (name.IndexOf("Generate", StringComparison.OrdinalIgnoreCase) >= 0) return "Generate";
            return "Other";
        }

        private static string HmiCapabilityEnumParameters(MethodInfo method)
        {
            List<string> parts = new List<string>();
            foreach (ParameterInfo parameter in method.GetParameters().Where(x => x.ParameterType.IsEnum))
            {
                parts.Add(parameter.Name + ":" + TypeDisplayName(parameter.ParameterType) + "=" + string.Join("|", Enum.GetNames(parameter.ParameterType)));
            }

            return string.Join("; ", parts.ToArray());
        }

        private static string TypeDisplayName(Type type)
        {
            return type == null ? string.Empty : FirstNonEmpty(type.FullName, type.Name);
        }

        private static void WriteHmiImportCapabilitiesSummary(string path, InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, List<HmiCapabilityObjectRecord> objects, List<HmiCapabilityMethodRecord> methods)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("HMI import capabilities inspected at: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("HMI targets: " + hmiSnapshot.Targets.Count);
                writer.WriteLine("Candidate objects/containers: " + objects.Count);
                writer.WriteLine("Relevant methods: " + methods.Count);
                writer.WriteLine("Objects with Import methods: " + objects.Count(x => ObjectHasMethodKind(x, methods, "Import")));
                writer.WriteLine("Objects with Export methods: " + objects.Count(x => ObjectHasMethodKind(x, methods, "Export")));
                writer.WriteLine("Objects with Create methods: " + objects.Count(x => ObjectHasMethodKind(x, methods, "Create")));
                writer.WriteLine("Objects with Delete methods: " + objects.Count(x => ObjectHasMethodKind(x, methods, "Delete")));
                writer.WriteLine();
                writer.WriteLine("Important: this command uses reflection only. It does not invoke Import/Create/Delete/Export methods.");
                writer.WriteLine();
                writer.WriteLine("Import-capable categories:");
                foreach (IGrouping<string, HmiCapabilityMethodRecord> group in methods.Where(x => EqualsIgnoreCase(x.MethodKind, "Import")).GroupBy(x => x.Category).OrderBy(x => x.Key))
                {
                    writer.WriteLine("  " + group.Key + ": " + group.Count());
                }
            }
        }

        private static bool ObjectHasMethodKind(HmiCapabilityObjectRecord record, List<HmiCapabilityMethodRecord> methods, string kind)
        {
            return methods.Any(x => EqualsIgnoreCase(x.MethodKind, kind)
                && EqualsIgnoreCase(x.Category, record.Category)
                && EqualsIgnoreCase(x.Path, record.Path)
                && EqualsIgnoreCase(x.TypeName, record.TypeName));
        }

        private static void WriteHmiImportCapabilitiesJson(string path, InventorySnapshot snapshot, HmiInventorySnapshot hmiSnapshot, List<HmiCapabilityObjectRecord> objects, List<HmiCapabilityMethodRecord> methods)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"project\": " + Json(snapshot.ProjectName) + ",");
                writer.WriteLine("  \"projectPath\": " + Json(snapshot.ProjectPath) + ",");
                writer.WriteLine("  \"createdAt\": " + Json(DateTime.Now.ToString("o")) + ",");
                writer.WriteLine("  \"counts\": {");
                writer.WriteLine("    \"hmiTargets\": " + hmiSnapshot.Targets.Count + ",");
                writer.WriteLine("    \"objects\": " + objects.Count + ",");
                writer.WriteLine("    \"methods\": " + methods.Count + ",");
                writer.WriteLine("    \"importMethods\": " + methods.Count(x => EqualsIgnoreCase(x.MethodKind, "Import")));
                writer.WriteLine("  },");
                WriteJsonArray(writer, "importMethods", methods.Where(x => EqualsIgnoreCase(x.MethodKind, "Import")).Select(x => new Dictionary<string, string>
                {
                    { "category", x.Category },
                    { "path", x.Path },
                    { "name", x.Name },
                    { "typeName", x.TypeName },
                    { "signature", x.Signature },
                    { "enumParameters", x.EnumParameters }
                }), false);
                writer.WriteLine("}");
            }
        }

        private static void CloneBlockFolderStructure(InventorySnapshot snapshot, string outDir)
        {
            using (AcquireCloneWorkspaceLock(outDir, "clone-folders"))
            {
                CloneBlockFolderStructureLocked(snapshot, outDir);
            }
        }

        private static void CloneBlockFolderStructureLocked(InventorySnapshot snapshot, string outDir)
        {
            Directory.CreateDirectory(outDir);
            string rootDir = Path.Combine(outDir, "_root");

            List<string[]> rows = new List<string[]>();
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            int created = 0;
            int existing = 0;

            IEnumerable<BlockGroupRecord> groups = snapshot.BlockGroups
                .OrderBy(x => EmptyIfNull(x.GroupPath).Length)
                .ThenBy(x => EmptyIfNull(x.GroupPath), StringComparer.OrdinalIgnoreCase);

            foreach (BlockGroupRecord group in groups)
            {
                string groupPath = EmptyIfNull(group.GroupPath);
                if (!seen.Add(groupPath))
                {
                    continue;
                }

                string directory = CloneDirectoryForBlockGroup(rootDir, groupPath);
                bool existed = Directory.Exists(directory);
                Directory.CreateDirectory(directory);

                if (existed)
                {
                    existing++;
                }
                else
                {
                    created++;
                }

                rows.Add(new[]
                {
                    group.SoftwarePath,
                    group.ParentGroupPath,
                    group.ParentGroupPathDisplay,
                    group.GroupPath,
                    group.GroupPathDisplay,
                    group.GroupPath,
                    group.Name,
                    directory
                });
            }

            if (!seen.Contains(string.Empty))
            {
                bool existed = Directory.Exists(rootDir);
                Directory.CreateDirectory(rootDir);
                if (existed)
                {
                    existing++;
                }
                else
                {
                    created++;
                }

                rows.Insert(0, new[] { string.Empty, string.Empty, string.Empty, string.Empty, string.Empty, string.Empty, "_root", rootDir });
            }

            string manifestPath = Path.Combine(outDir, "block-groups.csv");
            WriteCsv(manifestPath,
                new[] { "SoftwarePath", "ParentGroupPath", "ParentGroupPathDisplay", "GroupPath", "GroupPathDisplay", "GroupPathKey", "Name", "Directory" },
                rows);

            Console.WriteLine("Block folder structure written to: " + rootDir);
            Console.WriteLine("Directories created: " + created);
            Console.WriteLine("Directories already present: " + existing);
            Console.WriteLine("Manifest written to: " + manifestPath);
        }

        private static void InitializeProjectClone(InventorySnapshot snapshot, string outDir, Options options)
        {
            using (AcquireCloneWorkspaceLock(outDir, "init-clone"))
            {
                InitializeProjectCloneLocked(snapshot, outDir, options);
            }
        }

        private static void InitializeProjectCloneLocked(InventorySnapshot snapshot, string outDir, Options options)
        {
            DeviceRecord softwareRecord = RequireSinglePlcSoftware(snapshot, "init-clone");
            object software = softwareRecord.Object;
            object externalSourceGroup = TryGetPropertyValue(software, "ExternalSourceGroup");
            if (externalSourceGroup == null)
            {
                throw new InvalidOperationException("PLC software does not expose ExternalSourceGroup.");
            }

            Type generateSourceType = FindType("Siemens.Engineering.SW.ExternalSources.IGenerateSource");
            MethodInfo generateSource = FindGenerateSourceMethod(externalSourceGroup);

            // All target selection and capability checks must finish before an
            // existing clone workspace or authorization marker is touched.
            // A direct init-clone rerun must also finish any durable provenance
            // transaction before it starts replacing the baseline. Otherwise a
            // later check-clone recovery could publish the stale staged manifest
            // over the newly initialized one.
            string rootDir = PrepareProjectCloneInitializationWorkspace(outDir);

            CloneBlockFolderStructure(snapshot, outDir);
            WriteCloneSummary(snapshot, outDir, options.Force);

            List<string[]> report = new List<string[]>();
            int exported = 0;
            int skipped = 0;
            int errors = 0;

            foreach (BlockRecord block in snapshot.Blocks.OrderBy(x => EmptyIfNull(x.GroupPath)).ThenBy(x => SafeInt(x.Number)).ThenBy(x => x.Name))
            {
                string extension = DefaultSourceExtension(block.ProgrammingLanguage);
                string directory = CloneDirectoryForBlockGroup(rootDir, block.GroupPath);
                string fileName = SafeFileName(BlockSourceFileName(block, extension));
                string filePath = Path.Combine(directory, fileName);
                ExportReportRow row = TryGenerateCloneSourceFile(externalSourceGroup, generateSource, generateSourceType, block, filePath, options.Force);

                if (EqualsIgnoreCase(row.Status, "ok"))
                {
                    exported++;
                }
                else if (EqualsIgnoreCase(row.Status, "skipped"))
                {
                    skipped++;
                }
                else
                {
                    errors++;
                }

                report.Add(BuildBlockManifestRow(block, filePath, row.Status, row.Message));
            }

            string reportPath = Path.Combine(outDir, "plc-blocks.csv");
            WriteCsv(reportPath, BlockManifestHeaders(), report);
            WriteCloneMetadata(outDir);

            WriteInventory(snapshot, Path.Combine(outDir, "_inventory"));

            Console.WriteLine("Project clone initialized in: " + outDir);
            Console.WriteLine("PLC block source files exported: " + exported);
            Console.WriteLine("PLC block source files skipped: " + skipped);
            Console.WriteLine("PLC block source export errors: " + errors);
            Console.WriteLine("PLC block manifest written to: " + reportPath);
            Console.WriteLine("Inventory written to: " + Path.Combine(outDir, "_inventory"));
        }

        private static string PrepareProjectCloneInitializationWorkspace(string outDir)
        {
            string rootDir = Path.Combine(outDir, "_root");
            RecoverPendingProvenancePromotions(outDir, rootDir);
            Directory.CreateDirectory(outDir);
            InvalidateCloneCheckBundle(outDir);
            return rootDir;
        }

        private static void WriteCloneSummary(InventorySnapshot snapshot, string outDir, bool force)
        {
            using (StreamWriter writer = NewUtf8Writer(Path.Combine(outDir, "clone-summary.txt")))
            {
                writer.WriteLine("Project clone initialized at: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Project type: " + snapshot.ProjectType);
                writer.WriteLine("Block groups: " + snapshot.BlockGroups.Count);
                writer.WriteLine("PLC blocks: " + snapshot.Blocks.Count);
                writer.WriteLine("Overwrite existing block files: " + force);
                writer.WriteLine();
                writer.WriteLine("Layout:");
                writer.WriteLine("  _root\\                 PLC block groups and source files");
                writer.WriteLine("  block-groups.csv        TIA block group to filesystem directory map");
                writer.WriteLine("  plc-blocks.csv          PLC block to source file map and export status");
                writer.WriteLine("  _inventory\\             CSV/JSON inventory snapshot");
            }
        }

        private static void CheckProjectClone(InventorySnapshot snapshot, string outDir)
        {
            CheckProjectClone(snapshot, outDir, new List<ExplicitNewPromotionReceipt>());
        }

        private static void ExecuteAuthoritativeCheckClone(object project, Options options)
        {
            string outDir = ResolveCloneProjectDirectory(options.OutDir);
            using (AcquireCloneWorkspaceLock(outDir, "check-clone"))
            {
                InvalidateCloneCheckBundle(outDir);
                try
                {
                    using (AcquireTiaExclusiveAccess("OpennessLLM authoritative check-clone snapshot"))
                    {
                        RequireCleanProjectForAuthoritativeEvidence(project, "before check-clone");
                        InventorySnapshot snapshot = FilterInventoryBySoftwarePath(
                            CollectInventory(project, options.ProjectPath),
                            options.SoftwarePathFilter);
                        CheckProjectCloneLocked(snapshot, outDir, new List<ExplicitNewPromotionReceipt>());
                        RequireCleanProjectForAuthoritativeEvidence(project, "after check-clone source export");
                        InventorySnapshot after = FilterInventoryBySoftwarePath(
                            CollectInventory(project, options.ProjectPath),
                            options.SoftwarePathFilter);
                        ValidateApplyInventoryIdentityStable(snapshot, after, "authoritative check-clone");
                    }
                }
                catch
                {
                    InvalidateCloneCheckBundle(outDir);
                    throw;
                }
            }
        }

        private static CloneAuthorizationCompletionMode ExecuteAuthoritativeWorkspaceInitialization(object project, Options options)
        {
            string outDir = ResolveCloneProjectDirectory(options.OutDir);
            bool plcAuthorizationPrepared;
            using (AcquireCloneWorkspaceLock(outDir, "init-workspace"))
            {
                InvalidateCloneCheckBundle(outDir);
                try
                {
                    using (AcquireTiaExclusiveAccess("OpennessLLM authoritative init-workspace snapshot"))
                    {
                        RequireCleanProjectForAuthoritativeEvidence(project, "before init-workspace");
                        InventorySnapshot rawSnapshot = CollectInventory(project, options.ProjectPath);
                        InventorySnapshot snapshot = FilterInventoryBySoftwarePath(rawSnapshot, options.SoftwarePathFilter);
                        HmiInventorySnapshot hmiSnapshot = FilterHmiInventoryByTargetPath(
                            CollectHmiInventory(rawSnapshot),
                            options.HmiTargetPathFilter);
                        plcAuthorizationPrepared = InitializeWorkspaceLocked(snapshot, hmiSnapshot, outDir, options);
                        RequireCleanProjectForAuthoritativeEvidence(project, "after init-workspace source export");
                        InventorySnapshot after = FilterInventoryBySoftwarePath(
                            CollectInventory(project, options.ProjectPath),
                            options.SoftwarePathFilter);
                        ValidateApplyInventoryIdentityStable(snapshot, after, "authoritative init-workspace");
                    }
                }
                catch
                {
                    InvalidateCloneCheckBundle(outDir);
                    throw;
                }
            }

            return plcAuthorizationPrepared
                ? CloneAuthorizationCompletionMode.WithPlcBundle
                : CloneAuthorizationCompletionMode.WithoutPlcAuthorization;
        }

        private static CloneAuthorizationCompletionMode ExecuteAuthoritativeToolStatus(object project, Options options)
        {
            string outDir = ResolveCloneProjectDirectory(options.OutDir);
            bool plcAuthorizationPrepared;
            using (AcquireCloneWorkspaceLock(outDir, "status"))
            {
                InvalidateCloneCheckBundle(outDir);
                try
                {
                    using (AcquireTiaExclusiveAccess("OpennessLLM authoritative status snapshot"))
                    {
                        RequireCleanProjectForAuthoritativeEvidence(project, "before status");
                        InventorySnapshot rawSnapshot = CollectInventory(project, options.ProjectPath);
                        InventorySnapshot snapshot = FilterInventoryBySoftwarePath(rawSnapshot, options.SoftwarePathFilter);
                        HmiInventorySnapshot hmiSnapshot = FilterHmiInventoryByTargetPath(
                            CollectHmiInventory(rawSnapshot),
                            options.HmiTargetPathFilter);
                        plcAuthorizationPrepared = WriteToolStatus(snapshot, hmiSnapshot, outDir);
                        RequireCleanProjectForAuthoritativeEvidence(project, "after status source export");
                        InventorySnapshot after = FilterInventoryBySoftwarePath(
                            CollectInventory(project, options.ProjectPath),
                            options.SoftwarePathFilter);
                        ValidateApplyInventoryIdentityStable(snapshot, after, "authoritative status");
                    }
                }
                catch
                {
                    InvalidateCloneCheckBundle(outDir);
                    throw;
                }
            }

            return plcAuthorizationPrepared
                ? CloneAuthorizationCompletionMode.WithPlcBundle
                : CloneAuthorizationCompletionMode.WithoutPlcAuthorization;
        }

        private static void RequireCleanProjectForAuthoritativeEvidence(object project, string phase)
        {
            bool? modified = TryReadProjectIsModified(project);
            if (modified != false)
            {
                throw new InvalidOperationException(
                    "Authoritative clone evidence requires Project.IsModified=false "
                    + phase + "; actual=" + (modified.HasValue ? modified.Value.ToString() : "unavailable") + ". Save or discard changes in TIA Portal and retry.");
            }
        }

        private static void CheckProjectClone(
            InventorySnapshot snapshot,
            string outDir,
            List<ExplicitNewPromotionReceipt> promotionReceipts)
        {
            using (AcquireCloneWorkspaceLock(outDir, "check-clone"))
            {
                CheckProjectCloneLocked(snapshot, outDir, promotionReceipts);
            }
        }

        private static void CheckProjectCloneLocked(
            InventorySnapshot snapshot,
            string outDir,
            List<ExplicitNewPromotionReceipt> promotionReceipts)
        {
            string rootDir = Path.Combine(outDir, "_root");
            if (!Directory.Exists(rootDir))
            {
                throw new DirectoryNotFoundException("Clone root was not found. Run init-clone first: " + rootDir);
            }

            DeviceRecord softwareRecord = RequireSinglePlcSoftware(snapshot, "check-clone");
            CloneCheckTargetIdentity targetIdentity = CloneCheckTargetFromSnapshot(snapshot);
            object software = softwareRecord.Object;
            object externalSourceGroup = TryGetPropertyValue(software, "ExternalSourceGroup");
            if (externalSourceGroup == null)
            {
                throw new InvalidOperationException("PLC software does not expose ExternalSourceGroup.");
            }

            Type generateSourceType = FindType("Siemens.Engineering.SW.ExternalSources.IGenerateSource");
            MethodInfo generateSource = FindGenerateSourceMethod(externalSourceGroup);

            RecoverPendingProvenancePromotions(outDir, rootDir);

            // The marker is the report-bundle record. Under a Main-level
            // refresh transaction it remains reports-prepared until the outer
            // clean-project and fresh-inventory checks commit it. Invalidate the
            // former marker before starting this report generation phase.
            string bundleMarkerPath = Path.Combine(outDir, CloneCheckBundleFileName);
            InvalidateCloneCheckBundle(outDir);

            string checkRunId = Guid.NewGuid().ToString("N");
            string compareDir = Path.Combine(outDir, "_compare", "current-" + DateTime.Now.ToString("yyyyMMdd-HHmmss-fff") + "-" + checkRunId.Substring(0, 8));
            string compareRootDir = Path.Combine(compareDir, "_root");
            Directory.CreateDirectory(compareRootDir);

            List<CloneBlockRecord> currentBlocks = new List<CloneBlockRecord>();
            foreach (BlockRecord block in snapshot.Blocks.OrderBy(x => EmptyIfNull(x.GroupPath)).ThenBy(x => SafeInt(x.Number)).ThenBy(x => x.Name))
            {
                string relativePath = BlockSourceRelativePath(block);
                string currentPath = Path.Combine(compareRootDir, relativePath);
                ExportReportRow row = TryGenerateCloneSourceFile(externalSourceGroup, generateSource, generateSourceType, block, currentPath, true);
                currentBlocks.Add(new CloneBlockRecord
                {
                    SoftwarePath = block.SoftwarePath,
                    GroupPath = block.GroupPath,
                    GroupPathDisplay = block.GroupPathDisplay,
                    Name = block.Name,
                    Number = block.Number,
                    AutoNumber = block.AutoNumber,
                    NumberMode = block.NumberMode,
                    NumberSpace = block.NumberSpace,
                    ProgrammingLanguage = block.ProgrammingLanguage,
                    BlockType = block.BlockType,
                    TypeName = block.TypeName,
                    SourceTypeName = InferBlockTypeNameFromSourceFile(currentPath, block.ProgrammingLanguage),
                    InstanceOfName = block.InstanceOfName,
                    InstanceOfNumber = block.InstanceOfNumber,
                    InstanceOfType = block.InstanceOfType,
                    SecondaryType = block.SecondaryType,
                    MemoryLayout = block.MemoryLayout,
                    IsConsistent = block.IsConsistent,
                    IsKnowHowProtected = block.IsKnowHowProtected,
                    TiaObjectId = block.TiaObjectId,
                    TiaObjectIdStatus = block.TiaObjectIdStatus,
                    SourceSha256 = File.Exists(currentPath) ? ComputeFileSha256(currentPath) : string.Empty,
                    NormalizedSourceSha256 = File.Exists(currentPath) ? ComputeNormalizedTextSha256(currentPath) : string.Empty,
                    RelativePath = relativePath,
                    ClonePath = Path.Combine(rootDir, relativePath),
                    CurrentPath = currentPath,
                    ExportStatus = row.Status,
                    ExportMessage = row.Message
                });
            }

            List<CloneBlockRecord> promotionCloneBlocks = LoadCloneBlockManifest(outDir, rootDir);
            PromoteMatchedExplicitNewSources(outDir, rootDir, promotionCloneBlocks, currentBlocks, promotionReceipts);

            using (CloneWorkspaceSnapshotLease localSnapshot = AcquireStableCloneWorkspaceSnapshot(outDir, checkRunId))
            {
            List<CloneWorkspaceFileRecord> workspaceFiles = localSnapshot.Files;
            string localSnapshotDir = localSnapshot.DirectoryPath;
            string localSnapshotRoot = Path.Combine(localSnapshotDir, "_root");
            List<CloneBlockRecord> cloneBlocks = LoadCloneBlockManifest(localSnapshotDir, localSnapshotRoot);
            RemapCloneSnapshotPaths(cloneBlocks, localSnapshotRoot, rootDir);
            List<CloneDiffRecord> blockDiffs = BuildCloneBlockDiffs(cloneBlocks, currentBlocks);
            List<CloneGroupDiffRecord> groupDiffs = BuildCloneGroupDiffs(localSnapshotDir, snapshot);
            foreach (CloneGroupDiffRecord groupDiff in groupDiffs)
            {
                groupDiff.CloneDirectory = CloneDirectoryForBlockGroup(rootDir, groupDiff.GroupPath);
            }
            ValidateCloneDiffHashesAgainstWorkspace(outDir, blockDiffs, workspaceFiles);
            ValidateCloneWorkspaceInventory(outDir, CloneWorkspaceInventoryRows(workspaceFiles));

            string publishRoot = Path.Combine(outDir, "_check-publish");
            string publishDir = Path.Combine(publishRoot, "run-" + checkRunId);
            Directory.CreateDirectory(publishDir);
            string stagedBlockReportPath = Path.Combine(publishDir, CloneCheckBlockFileName);
            WriteCsv(stagedBlockReportPath,
                new[]
                {
                    "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Status", "GroupPath", "GroupPathDisplay", "GroupPathKey", "Name", "Number", "AutoNumber", "NumberMode", "NumberSpace",
                    "ProgrammingLanguage", "BlockType", "TypeName", "SourceTypeName",
                    "InstanceOfName", "InstanceOfNumber", "InstanceOfType", "SecondaryType",
                    "MemoryLayout", "IsConsistent", "IsKnowHowProtected", "TiaObjectId", "TiaObjectIdStatus",
                    "SourceSha256", "NormalizedSourceSha256",
                    "CloneSoftwarePath", "CloneGroupPath", "CloneGroupPathDisplay", "CloneGroupPathKey", "CloneName", "CloneNumber", "CloneAutoNumber", "CloneNumberMode", "CloneNumberSpace",
                    "CloneProgrammingLanguage", "CloneBlockType", "CloneTypeName", "CloneSourceTypeName",
                    "CloneInstanceOfName", "CloneInstanceOfNumber", "CloneInstanceOfType", "CloneSecondaryType",
                    "CloneMemoryLayout", "CloneIsConsistent", "CloneIsKnowHowProtected", "CloneTiaObjectId", "CloneTiaObjectIdStatus",
                    "CloneSourceSha256", "CloneNormalizedSourceSha256", "CloneRelativePath", "ClonePath", "CloneProvenance",
                    "CurrentSoftwarePath", "CurrentGroupPath", "CurrentGroupPathDisplay", "CurrentGroupPathKey", "CurrentName", "CurrentNumber", "CurrentAutoNumber", "CurrentNumberMode", "CurrentNumberSpace",
                    "CurrentProgrammingLanguage", "CurrentBlockType", "CurrentTypeName", "CurrentSourceTypeName",
                    "CurrentInstanceOfName", "CurrentInstanceOfNumber", "CurrentInstanceOfType", "CurrentSecondaryType",
                    "CurrentMemoryLayout", "CurrentIsConsistent", "CurrentIsKnowHowProtected", "CurrentTiaObjectId", "CurrentTiaObjectIdStatus",
                    "CurrentSourceSha256", "CurrentNormalizedSourceSha256", "CurrentRelativePath", "CurrentPath",
                    "Message"
                },
                blockDiffs.Select(x => new[]
                {
                    CloneCheckBundleSchemaVersion, checkRunId, x.SoftwarePath, x.Status, x.GroupPath, x.GroupPathDisplay, x.GroupPath, x.Name, x.Number, x.AutoNumber, x.NumberMode, x.NumberSpace,
                    x.ProgrammingLanguage, x.BlockType, x.TypeName, x.SourceTypeName,
                    x.InstanceOfName, x.InstanceOfNumber, x.InstanceOfType, x.SecondaryType,
                    x.MemoryLayout, x.IsConsistent, x.IsKnowHowProtected, x.TiaObjectId, x.TiaObjectIdStatus,
                    x.SourceSha256, x.NormalizedSourceSha256,
                    x.CloneSoftwarePath, x.CloneGroupPath, x.CloneGroupPathDisplay, x.CloneGroupPath, x.CloneName, x.CloneNumber, x.CloneAutoNumber, x.CloneNumberMode, x.CloneNumberSpace,
                    x.CloneProgrammingLanguage, x.CloneBlockType, x.CloneTypeName, x.CloneSourceTypeName,
                    x.CloneInstanceOfName, x.CloneInstanceOfNumber, x.CloneInstanceOfType, x.CloneSecondaryType,
                    x.CloneMemoryLayout, x.CloneIsConsistent, x.CloneIsKnowHowProtected, x.CloneTiaObjectId, x.CloneTiaObjectIdStatus,
                    x.CloneSourceSha256, x.CloneNormalizedSourceSha256, x.CloneRelativePath, x.ClonePath, x.CloneProvenance,
                    x.CurrentSoftwarePath, x.CurrentGroupPath, x.CurrentGroupPathDisplay, x.CurrentGroupPath, x.CurrentName, x.CurrentNumber, x.CurrentAutoNumber, x.CurrentNumberMode, x.CurrentNumberSpace,
                    x.CurrentProgrammingLanguage, x.CurrentBlockType, x.CurrentTypeName, x.CurrentSourceTypeName,
                    x.CurrentInstanceOfName, x.CurrentInstanceOfNumber, x.CurrentInstanceOfType, x.CurrentSecondaryType,
                    x.CurrentMemoryLayout, x.CurrentIsConsistent, x.CurrentIsKnowHowProtected, x.CurrentTiaObjectId, x.CurrentTiaObjectIdStatus,
                    x.CurrentSourceSha256, x.CurrentNormalizedSourceSha256, x.CurrentRelativePath, x.CurrentPath,
                    x.Message
                }));

            string stagedGroupReportPath = Path.Combine(publishDir, CloneCheckGroupFileName);
            WriteCsv(stagedGroupReportPath,
                new[] { "CheckSchemaVersion", "CheckRunId", "Status", "GroupPath", "GroupPathDisplay", "GroupPathKey", "CloneDirectory", "Message" },
                groupDiffs.Select(x => new[] { CloneCheckBundleSchemaVersion, checkRunId, x.Status, x.GroupPath, x.GroupPathDisplay, x.GroupPath, x.CloneDirectory, x.Message }));

            string stagedSourceBlockerReportPath = Path.Combine(publishDir, CloneCheckSourceBlockerFileName);
            WriteCloneCheckSourceBlockerReport(stagedSourceBlockerReportPath, blockDiffs, CloneCheckBundleSchemaVersion, checkRunId);

            string stagedWorkspaceReportPath = Path.Combine(publishDir, CloneCheckWorkspaceFileName);
            WriteCsv(
                stagedWorkspaceReportPath,
                new[] { "CheckSchemaVersion", "CheckRunId", "Kind", "RelativePath", "Size", "Sha256" },
                workspaceFiles.Select(x => new[]
                {
                    CloneCheckBundleSchemaVersion,
                    checkRunId,
                    x.Kind,
                    x.RelativePath,
                    x.Size.ToString(CultureInfo.InvariantCulture),
                    x.Sha256
                }));

            string stagedSummaryPath = Path.Combine(publishDir, CloneCheckSummaryFileName);
            WriteCloneCheckSummary(stagedSummaryPath, snapshot, outDir, compareDir, cloneBlocks, currentBlocks, blockDiffs, groupDiffs, CloneCheckBundleSchemaVersion, checkRunId);

            string stagedMarkerPath = Path.Combine(publishDir, CloneCheckBundleFileName);
            WriteCloneCheckBundleMarker(
                stagedMarkerPath,
                checkRunId,
                compareDir,
                targetIdentity,
                stagedBlockReportPath,
                blockDiffs.Count,
                stagedGroupReportPath,
                groupDiffs.Count,
                stagedSourceBlockerReportPath,
                blockDiffs.Count(IsSourceEvidenceBlockerDiff),
                stagedWorkspaceReportPath,
                workspaceFiles.Count,
                stagedSummaryPath,
                string.IsNullOrWhiteSpace(_activeCloneAuthorizationRefreshAttemptId)
                    ? "authoritative-complete"
                    : "reports-prepared");

            string blockReportPath = Path.Combine(outDir, CloneCheckBlockFileName);
            string groupReportPath = Path.Combine(outDir, CloneCheckGroupFileName);
            string sourceBlockerReportPath = Path.Combine(outDir, CloneCheckSourceBlockerFileName);
            string workspaceReportPath = Path.Combine(outDir, CloneCheckWorkspaceFileName);
            string summaryPath = Path.Combine(outDir, CloneCheckSummaryFileName);
            PublishFileAtomically(stagedBlockReportPath, blockReportPath, publishDir);
            PublishFileAtomically(stagedGroupReportPath, groupReportPath, publishDir);
            PublishFileAtomically(stagedSourceBlockerReportPath, sourceBlockerReportPath, publishDir);
            PublishFileAtomically(stagedWorkspaceReportPath, workspaceReportPath, publishDir);
            PublishFileAtomically(stagedSummaryPath, summaryPath, publishDir);
            // The diff, row hashes, and workspace inventory were all built
            // from the immutable local snapshot. Re-check the editor-visible
            // workspace at the last possible point before committing the
            // authorization marker.
            ValidateCloneWorkspaceInventory(outDir, CloneWorkspaceInventoryRows(workspaceFiles));
            ValidateCloneDiffHashesAgainstWorkspace(outDir, blockDiffs, workspaceFiles);
            // Commit marker is deliberately last. Consumers reject any bundle
            // whose marker is absent or whose hashes/run IDs do not match.
            PublishFileAtomically(stagedMarkerPath, bundleMarkerPath, publishDir);
            try
            {
                Directory.Delete(publishDir, true);
                if (Directory.Exists(publishRoot) && !Directory.EnumerateFileSystemEntries(publishRoot).Any())
                {
                    Directory.Delete(publishRoot, false);
                }
            }
            catch
            {
                // Publication is already committed. Staging cleanup is best effort.
            }
            Console.WriteLine("Clone check completed.");
            Console.WriteLine("Clone root: " + rootDir);
            Console.WriteLine("Current export snapshot: " + compareDir);
            PrintDiffCount("Block unchanged", blockDiffs, "unchanged");
            PrintDiffCount("Block content changed", blockDiffs, "changed");
            PrintDiffCount("Block added", blockDiffs, "added");
            PrintDiffCount("Block removed", blockDiffs, "removed");
            PrintDiffCount("Block moved/renamed", blockDiffs, "moved-or-renamed");
            PrintDiffCount("Block moved/renamed and changed", blockDiffs, "moved-or-renamed-and-changed");
            PrintDiffCount("Block object replacements/mismatches", blockDiffs, "object-replaced-or-mismatched");
            PrintDiffCount("Block object-ID continuity unproven", blockDiffs, "object-id-continuity-unproven");
            PrintDiffCount("Block ambiguous rename+renumber", blockDiffs, "ambiguous-rename-and-renumber");
            PrintDiffCount("Block ambiguous object correlations", blockDiffs, "ambiguous-object-correlation");
            PrintDiffCount("Block export errors", blockDiffs, "export-error");
            Console.WriteLine("Source blockers (blocking / total): " + BlockingSourceBlockedDiffCount(blockDiffs) + " / " + blockDiffs.Count(IsSourceEvidenceBlockerDiff));
            PrintGroupDiffCount("Group unchanged", groupDiffs, "unchanged");
            PrintGroupDiffCount("Group added", groupDiffs, "added");
            PrintGroupDiffCount("Group removed", groupDiffs, "removed");
            Console.WriteLine("Block report written to: " + blockReportPath);
            Console.WriteLine("Source blocker report written to: " + sourceBlockerReportPath);
            Console.WriteLine("Group report written to: " + groupReportPath);
            Console.WriteLine("Summary written to: " + summaryPath);
            }
        }

        private static ExportReportRow TryGenerateCloneSourceFile(object externalSourceGroup, MethodInfo generateSource, Type generateSourceType, BlockRecord block, string filePath, bool force)
        {
            if (!IsCloneSourceExportableLanguage(block.ProgrammingLanguage))
            {
                return new ExportReportRow("unsupported-language", UnsupportedCloneSourceLanguageMessage(block));
            }

            return TryGenerateSourceFile(externalSourceGroup, generateSource, generateSourceType, block.Object, filePath, force);
        }

        private static List<CloneDiffRecord> BuildCloneBlockDiffs(List<CloneBlockRecord> cloneBlocks, List<CloneBlockRecord> currentBlocks)
        {
            cloneBlocks = cloneBlocks ?? new List<CloneBlockRecord>();
            currentBlocks = currentBlocks ?? new List<CloneBlockRecord>();
            List<CloneDiffRecord> diffs = new List<CloneDiffRecord>();
            Dictionary<string, CloneBlockRecord> cloneByRelative = cloneBlocks
                .GroupBy(CloneBlockRelativeIdentity, StringComparer.OrdinalIgnoreCase)
                .Where(x => !string.IsNullOrWhiteSpace(x.Key))
                .Where(x => x.Count() == 1)
                .ToDictionary(x => x.Key, x => x.First(), StringComparer.OrdinalIgnoreCase);
            Dictionary<string, CloneBlockRecord> cloneByUnscopedRelative = cloneBlocks
                .GroupBy(CloneBlockUnscopedRelativeIdentity, StringComparer.OrdinalIgnoreCase)
                .Where(x => !string.IsNullOrWhiteSpace(x.Key))
                .Where(x => x.Count() == 1)
                .ToDictionary(x => x.Key, x => x.First(), StringComparer.OrdinalIgnoreCase);
            HashSet<string> uniqueCurrentUnscopedRelativePaths = new HashSet<string>(
                currentBlocks
                    .GroupBy(CloneBlockUnscopedRelativeIdentity, StringComparer.OrdinalIgnoreCase)
                    .Where(x => !string.IsNullOrWhiteSpace(x.Key))
                    .Where(x => x.Count() == 1)
                    .Select(x => x.Key),
                StringComparer.OrdinalIgnoreCase);
            Dictionary<string, CloneBlockRecord> cloneByIdentity = UniqueByIdentity(cloneBlocks);
            Dictionary<string, CloneBlockRecord> cloneByObjectId = UniqueByUsableTiaObjectId(cloneBlocks, "clone baseline");
            UniqueByUsableTiaObjectId(currentBlocks, "current TIA snapshot");

            Dictionary<CloneBlockRecord, CloneBlockRecord> exactObjectMatches = new Dictionary<CloneBlockRecord, CloneBlockRecord>();
            foreach (CloneBlockRecord current in currentBlocks.Where(HasUsableTiaObjectId))
            {
                CloneBlockRecord objectMatch;
                if (cloneByObjectId.TryGetValue(CloneBlockObjectIdentity(current), out objectMatch))
                {
                    exactObjectMatches[current] = objectMatch;
                }
            }

            // Reserve every exact durable-ID pair before considering path/name/
            // number fallbacks. This prevents an unrelated block that reused an
            // old number from consuming the tracked baseline row first.
            HashSet<CloneBlockRecord> usedCloneBlocks = new HashSet<CloneBlockRecord>(exactObjectMatches.Values);
            Dictionary<CloneBlockRecord, string> fallbackMatchMessages;
            Dictionary<CloneBlockRecord, CloneBlockRecord> ambiguousFallbackEvidence;
            Dictionary<CloneBlockRecord, string> ambiguousFallbackStatuses;
            Dictionary<CloneBlockRecord, string> ambiguousFallbackMessages;
            Dictionary<CloneBlockRecord, CloneBlockRecord> fallbackMatches = BuildCloneFallbackMatches(
                currentBlocks,
                cloneBlocks,
                exactObjectMatches,
                cloneByRelative,
                cloneByUnscopedRelative,
                uniqueCurrentUnscopedRelativePaths,
                cloneByIdentity,
                usedCloneBlocks,
                out fallbackMatchMessages,
                out ambiguousFallbackEvidence,
                out ambiguousFallbackStatuses,
                out ambiguousFallbackMessages);

            foreach (CloneBlockRecord current in currentBlocks)
            {
                CloneBlockRecord clone;
                if (exactObjectMatches.TryGetValue(current, out clone))
                {
                    AddMatchedCloneBlockDiff(diffs, current, clone, "Matched by durable TIA object identifier.");
                    continue;
                }

                if (fallbackMatches.TryGetValue(current, out clone))
                {
                    AddMatchedCloneBlockDiff(diffs, current, clone, fallbackMatchMessages[current]);
                    continue;
                }

                CloneBlockRecord ambiguousClone;
                string ambiguousStatus;
                string ambiguousMessage;
                if (ambiguousFallbackStatuses.TryGetValue(current, out ambiguousStatus))
                {
                    ambiguousFallbackEvidence.TryGetValue(current, out ambiguousClone);
                    ambiguousFallbackMessages.TryGetValue(current, out ambiguousMessage);
                    if (!EqualsIgnoreCase(current.ExportStatus, "ok"))
                    {
                        ambiguousMessage += " Source export is also unavailable: " + SourceBlockedMessage(current, ambiguousClone);
                    }
                    diffs.Add(CloneDiff(
                        ambiguousStatus,
                        current,
                        ambiguousClone,
                        ambiguousMessage));
                    continue;
                }

                if (!EqualsIgnoreCase(current.ExportStatus, "ok"))
                {
                    diffs.Add(CloneDiff(SourceBlockedStatus(current, null), current, null, SourceBlockedMessage(current, null)));
                    continue;
                }

                diffs.Add(CloneDiff("added", current, null, "Block exists in current TIA project but not in clone."));
            }

            foreach (CloneBlockRecord clone in cloneBlocks)
            {
                if (usedCloneBlocks.Contains(clone))
                {
                    continue;
                }

                if (!CloneSourceFileExists(clone) && !MissingCloneRecordNeededForSourceBlockerEvidence(clone, diffs))
                {
                    // Keep the manifest record available during matching, but do
                    // not turn stale metadata into a clone-only create action.
                    // If neither an exportable live block nor an ambiguous visual
                    // block remains, the absent source represents a completed
                    // clone-side deletion.
                    continue;
                }

                diffs.Add(CloneDiff("removed", null, clone, "Block exists in clone but not in current TIA project."));
            }

            return diffs.OrderBy(x => x.Status).ThenBy(x => x.GroupPath).ThenBy(x => SafeInt(x.Number)).ThenBy(x => x.Name).ToList();
        }

        private static void AddMatchedCloneBlockDiff(
            List<CloneDiffRecord> diffs,
            CloneBlockRecord current,
            CloneBlockRecord clone,
            string matchMessage)
        {
            if (HasUsableTiaObjectId(clone) && !HasUsableTiaObjectId(current))
            {
                diffs.Add(CloneDiff(
                    "object-id-continuity-unproven",
                    current,
                    clone,
                    "OBJECT_ID_CONTINUITY_UNPROVEN: the tracked baseline has durable TIA object identifier '"
                        + clone.TiaObjectId + "', but the current snapshot does not expose a usable identifier. Refusing to downgrade or erase durable identity evidence."));
                return;
            }

            if (HasUsableTiaObjectId(current)
                && HasUsableTiaObjectId(clone)
                && !EqualsIgnoreCase(current.TiaObjectId, clone.TiaObjectId))
            {
                diffs.Add(CloneDiff(
                    "object-replaced-or-mismatched",
                    current,
                    clone,
                    "OBJECT_REPLACED_OR_MISMATCHED: the fallback path/logical/number candidate has a different usable TIA object identifier. Clone="
                        + clone.TiaObjectId + "; current=" + current.TiaObjectId + "."));
                return;
            }

            if (!EqualsIgnoreCase(current.ExportStatus, "ok"))
            {
                diffs.Add(CloneDiff(SourceBlockedStatus(current, clone), current, clone, SourceBlockedMessage(current, clone)));
                return;
            }

            if (AddCloneDeletedDiffIfSourceMissing(diffs, current, clone))
            {
                return;
            }

            bool identical = CloneSourceContentEquivalentForDiff(current, clone);
            bool metadataChanged = !EqualsIgnoreCase(current.Name, clone.Name)
                || !EqualsIgnoreCase(EmptyIfNull(current.GroupPath), EmptyIfNull(clone.GroupPath))
                || !EqualsIgnoreCase(current.Number, clone.Number)
                || !EqualsIgnoreCase(BlockNumberSpace(current.TypeName, current.ProgrammingLanguage), BlockNumberSpace(clone.TypeName, clone.ProgrammingLanguage))
                || MetadataValueChanged(current.AutoNumber, clone.AutoNumber)
                || MetadataValueChanged(current.NumberMode, clone.NumberMode)
                || !EqualsIgnoreCase(EmptyIfNull(current.InstanceOfName), EmptyIfNull(clone.InstanceOfName));
            string status = metadataChanged
                ? (identical ? "moved-or-renamed" : "moved-or-renamed-and-changed")
                : (identical ? "unchanged" : "changed");
            string message = status == "unchanged"
                ? "Content is identical."
                : status == "changed"
                    ? "Content differs."
                    : "Clone metadata differs from current TIA block metadata.";
            if (metadataChanged && !identical)
            {
                message += " Content also differs.";
            }
            if (!string.IsNullOrWhiteSpace(matchMessage))
            {
                message += " " + matchMessage;
            }

            diffs.Add(CloneDiff(status, current, clone, message));
        }

        private static bool CloneSourceContentEquivalentForDiff(
            CloneBlockRecord current,
            CloneBlockRecord clone)
        {
            if (current == null || clone == null)
            {
                return false;
            }
            if (FilesEqual(clone.ClonePath, current.CurrentPath))
            {
                return true;
            }
            if (EqualsIgnoreCase(current.Name, clone.Name)
                || string.IsNullOrWhiteSpace(clone.ClonePath)
                || string.IsNullOrWhiteSpace(current.CurrentPath)
                || !File.Exists(clone.ClonePath)
                || !File.Exists(current.CurrentPath))
            {
                return false;
            }

            try
            {
                if (!EqualsIgnoreCase(TryReadBlockNameFromSource(clone.ClonePath), clone.Name)
                    || !EqualsIgnoreCase(TryReadBlockNameFromSource(current.CurrentPath), current.Name))
                {
                    return false;
                }
                string cloneCanonical = ComputeCanonicalSourceSha256(clone.ClonePath, true);
                string currentCanonical = ComputeCanonicalSourceSha256(current.CurrentPath, true);
                return !string.IsNullOrWhiteSpace(cloneCanonical)
                    && EqualsIgnoreCase(cloneCanonical, currentCanonical);
            }
            catch
            {
                return false;
            }
        }

        private static bool AddCloneDeletedDiffIfSourceMissing(List<CloneDiffRecord> diffs, CloneBlockRecord current, CloneBlockRecord clone)
        {
            if (CloneSourceFileExists(clone))
            {
                return false;
            }

            diffs.Add(CloneDiff(
                "added",
                current,
                clone,
                "The tracked clone source file is missing. The exportable current block is treated as deleted from clone."));
            return true;
        }

        private static bool CloneSourceFileExists(CloneBlockRecord clone)
        {
            return clone != null
                && !string.IsNullOrWhiteSpace(clone.ClonePath)
                && File.Exists(clone.ClonePath);
        }

        private static bool MissingCloneRecordNeededForSourceBlockerEvidence(CloneBlockRecord clone, List<CloneDiffRecord> diffs)
        {
            RemovedCloneRef removed = new RemovedCloneRef
            {
                Key = new BlockKey(
                    clone == null ? string.Empty : clone.SoftwarePath,
                    clone == null ? string.Empty : clone.NumberSpace,
                    clone == null ? string.Empty : clone.Number,
                    clone == null ? string.Empty : clone.Name),
                ExplicitNewLocalSource = clone != null && EqualsIgnoreCase(clone.Provenance, "explicit-new-local-source"),
            };
            List<RemovedCloneRef> removedRows = new List<RemovedCloneRef> { removed };
            return (diffs ?? new List<CloneDiffRecord>())
                .Where(x => x != null && EqualsIgnoreCase(x.Status, "source-blocked-current-only"))
                .Any(x => SourceBlockedStatusBlocksWrite(
                    x.Status,
                    new BlockKey(
                        FirstNonEmpty(x.CurrentSoftwarePath, x.SoftwarePath),
                        FirstNonEmpty(x.CurrentNumberSpace, x.NumberSpace),
                        FirstNonEmpty(x.CurrentNumber, x.Number),
                        FirstNonEmpty(x.CurrentName, x.Name)),
                    removedRows));
        }

        private static Dictionary<CloneBlockRecord, CloneBlockRecord> BuildCloneFallbackMatches(
            IEnumerable<CloneBlockRecord> currentBlocks,
            IEnumerable<CloneBlockRecord> cloneBlocks,
            Dictionary<CloneBlockRecord, CloneBlockRecord> exactObjectMatches,
            Dictionary<string, CloneBlockRecord> cloneByRelative,
            Dictionary<string, CloneBlockRecord> cloneByUnscopedRelative,
            HashSet<string> uniqueCurrentUnscopedRelativePaths,
            Dictionary<string, CloneBlockRecord> cloneByIdentity,
            HashSet<CloneBlockRecord> usedCloneBlocks,
            out Dictionary<CloneBlockRecord, string> matchMessages,
            out Dictionary<CloneBlockRecord, CloneBlockRecord> ambiguousEvidence,
            out Dictionary<CloneBlockRecord, string> ambiguousStatuses,
            out Dictionary<CloneBlockRecord, string> ambiguousMessages)
        {
            List<CloneBlockRecord> unmatched = (currentBlocks ?? Enumerable.Empty<CloneBlockRecord>())
                .Where(current => !exactObjectMatches.ContainsKey(current))
                .ToList();
            Dictionary<CloneBlockRecord, CloneBlockRecord> matches = new Dictionary<CloneBlockRecord, CloneBlockRecord>();
            matchMessages = new Dictionary<CloneBlockRecord, string>();
            ambiguousEvidence = new Dictionary<CloneBlockRecord, CloneBlockRecord>();
            ambiguousStatuses = new Dictionary<CloneBlockRecord, string>();
            ambiguousMessages = new Dictionary<CloneBlockRecord, string>();

            foreach (CloneBlockRecord current in unmatched)
            {
                CloneBlockRecord clone;
                string key = CloneBlockRelativeIdentity(current);
                if (!string.IsNullOrWhiteSpace(key)
                    && cloneByRelative.TryGetValue(key, out clone)
                    && !usedCloneBlocks.Contains(clone))
                {
                    matches[current] = clone;
                    matchMessages[current] = "Matched by software-scoped clone relative path.";
                    usedCloneBlocks.Add(clone);
                }
            }

            foreach (CloneBlockRecord current in unmatched.Where(current => !matches.ContainsKey(current)))
            {
                CloneBlockRecord clone;
                if (TryGetUniqueCrossScopeRelativeMatch(current, cloneByUnscopedRelative, uniqueCurrentUnscopedRelativePaths, out clone)
                    && !usedCloneBlocks.Contains(clone))
                {
                    matches[current] = clone;
                    matchMessages[current] = "Matched by unique unscoped clone relative path.";
                    usedCloneBlocks.Add(clone);
                }
            }

            foreach (CloneBlockRecord current in unmatched.Where(current => !matches.ContainsKey(current)))
            {
                CloneBlockRecord clone;
                string key = CloneBlockIdentity(current);
                if (!string.IsNullOrWhiteSpace(key)
                    && cloneByIdentity.TryGetValue(key, out clone)
                    && !usedCloneBlocks.Contains(clone))
                {
                    matches[current] = clone;
                    matchMessages[current] = "Matched by logical identity.";
                    usedCloneBlocks.Add(clone);
                }
            }

            // A same-path/same-logical replacement must not consume the baseline
            // before an unmatched, source-equivalent block that moved by both
            // name and number can enter the global correlation graph.
            List<CloneBlockRecord> provisionallyUnmatchedCurrent = unmatched
                .Where(current => !matches.ContainsKey(current))
                .ToList();
            foreach (KeyValuePair<CloneBlockRecord, CloneBlockRecord> pair in matches.ToList())
            {
                if (HasUsableTiaObjectId(pair.Key) || HasUsableTiaObjectId(pair.Value))
                {
                    continue;
                }
                if (!provisionallyUnmatchedCurrent.Any(candidate =>
                    IsPlausibleMovedSourceEquivalentCandidate(candidate, pair.Value)))
                {
                    continue;
                }

                matches.Remove(pair.Key);
                matchMessages.Remove(pair.Key);
                usedCloneBlocks.Remove(pair.Value);
            }

            // Number-only matches and no-ID rename+renumber possibilities are
            // evaluated as one global graph. A greedy number match is unsafe:
            // an unrelated block may reuse the old number while the tracked
            // object has changed both name and number. Only an isolated,
            // mutually unique number edge may be accepted automatically.
            List<CloneBlockRecord> weakCurrent = unmatched
                .Where(current => !matches.ContainsKey(current))
                .ToList();
            List<CloneBlockRecord> weakClone = (cloneBlocks ?? Enumerable.Empty<CloneBlockRecord>())
                .Where(clone => !usedCloneBlocks.Contains(clone))
                .ToList();
            Dictionary<CloneBlockRecord, List<CloneBlockRecord>> candidatesByCurrent = weakCurrent
                .ToDictionary(
                    current => current,
                    current => weakClone.Where(clone => IsCloneWeakFallbackCandidate(current, clone)).ToList());
            Dictionary<CloneBlockRecord, List<CloneBlockRecord>> candidatesByClone = weakClone
                .ToDictionary(
                    clone => clone,
                    clone => weakCurrent.Where(current => IsCloneWeakFallbackCandidate(current, clone)).ToList());

            foreach (CloneBlockRecord current in weakCurrent)
            {
                List<CloneBlockRecord> candidates = candidatesByCurrent[current];
                if (candidates.Count == 0)
                {
                    continue;
                }

                CloneBlockRecord uniqueCandidate = candidates.Count == 1 ? candidates[0] : null;
                bool mutuallyUnique = uniqueCandidate != null
                    && candidatesByClone[uniqueCandidate].Count == 1;
                bool simultaneousRenameAndRenumber = uniqueCandidate != null
                    && !EqualsIgnoreCase(current.Name, uniqueCandidate.Name)
                    && !EqualsIgnoreCase(current.Number, uniqueCandidate.Number);
                if (mutuallyUnique && !simultaneousRenameAndRenumber)
                {
                    matches[current] = uniqueCandidate;
                    matchMessages[current] = "Matched by a globally isolated, mutually unique software/type/number fallback.";
                    usedCloneBlocks.Add(uniqueCandidate);
                    continue;
                }

                foreach (CloneBlockRecord candidate in candidates)
                {
                    // Reserve the complete ambiguous component as evidence so
                    // no clone-only removed row can leak into an apply plan.
                    usedCloneBlocks.Add(candidate);
                }
                if (uniqueCandidate != null)
                {
                    ambiguousEvidence[current] = uniqueCandidate;
                }
                if (mutuallyUnique && simultaneousRenameAndRenumber)
                {
                    ambiguousStatuses[current] = "ambiguous-rename-and-renumber";
                    ambiguousMessages[current] = "AMBIGUOUS_RENAME_AND_RENUMBER: current and tracked clone blocks share a software/number space, but both name and number changed while a durable object ID is unavailable. Automatic destructive pairing is forbidden.";
                }
                else
                {
                    ambiguousStatuses[current] = "ambiguous-object-correlation";
                    ambiguousMessages[current] = "AMBIGUOUS_OBJECT_CORRELATION: the global no-ID fallback graph is not mutually one-to-one. An old number may have been reused while the tracked object was renamed or renumbered. Candidate baseline objects: "
                        + string.Join(", ", candidates
                            .Select(candidate => EmptyIfNull(candidate.Name) + " " + EmptyIfNull(candidate.NumberSpace) + EmptyIfNull(candidate.Number))
                            .ToArray())
                        + ". No automatic destructive pair is authorized.";
                }
            }

            return matches;
        }

        private static bool IsCloneWeakFallbackCandidate(CloneBlockRecord current, CloneBlockRecord clone)
        {
            if (current == null || clone == null
                || EqualsIgnoreCase(clone.Provenance, "explicit-new-local-source")
                || string.IsNullOrWhiteSpace(current.SoftwarePath)
                || string.IsNullOrWhiteSpace(clone.SoftwarePath)
                || !EqualsIgnoreCase(current.SoftwarePath, clone.SoftwarePath)
                || !EqualsIgnoreCase(
                    BlockNumberSpace(current.TypeName, current.ProgrammingLanguage),
                    BlockNumberSpace(clone.TypeName, clone.ProgrammingLanguage)))
            {
                return false;
            }

            string currentNumberIdentity = CloneBlockNumberIdentity(current);
            string cloneNumberIdentity = CloneBlockNumberIdentity(clone);
            if (!string.IsNullOrWhiteSpace(currentNumberIdentity)
                && !string.IsNullOrWhiteSpace(cloneNumberIdentity)
                && EqualsIgnoreCase(currentNumberIdentity, cloneNumberIdentity))
            {
                return true;
            }

            return CloneSourceFileExists(clone)
                && !EqualsIgnoreCase(clone.Name, current.Name)
                && !EqualsIgnoreCase(clone.Number, current.Number)
                && (!HasUsableTiaObjectId(clone) || !HasUsableTiaObjectId(current));
        }

        private static bool IsPlausibleMovedSourceEquivalentCandidate(
            CloneBlockRecord current,
            CloneBlockRecord clone)
        {
            return current != null
                && clone != null
                && !EqualsIgnoreCase(clone.Provenance, "explicit-new-local-source")
                && !HasUsableTiaObjectId(current)
                && !HasUsableTiaObjectId(clone)
                && EqualsIgnoreCase(current.SoftwarePath, clone.SoftwarePath)
                && EqualsIgnoreCase(
                    BlockNumberSpace(current.TypeName, current.ProgrammingLanguage),
                    BlockNumberSpace(clone.TypeName, clone.ProgrammingLanguage))
                && !EqualsIgnoreCase(current.Name, clone.Name)
                && !EqualsIgnoreCase(current.Number, clone.Number)
                && CloneSourceContentEquivalentForDiff(current, clone);
        }

        private static Dictionary<string, CloneBlockRecord> UniqueByUsableTiaObjectId(
            IEnumerable<CloneBlockRecord> blocks,
            string label)
        {
            List<IGrouping<string, CloneBlockRecord>> groups = (blocks ?? Enumerable.Empty<CloneBlockRecord>())
                .Where(HasUsableTiaObjectId)
                .GroupBy(CloneBlockObjectIdentity, StringComparer.OrdinalIgnoreCase)
                .ToList();
            IGrouping<string, CloneBlockRecord> duplicate = groups.FirstOrDefault(group => group.Count() != 1);
            if (duplicate != null)
            {
                throw new InvalidDataException(
                    "Duplicate usable TIA object identifier in " + label + ": " + duplicate.Key + ".");
            }

            return groups.ToDictionary(group => group.Key, group => group.Single(), StringComparer.OrdinalIgnoreCase);
        }

        private static bool HasUsableTiaObjectId(CloneBlockRecord block)
        {
            return block != null
                && EqualsIgnoreCase(block.TiaObjectIdStatus, "ok")
                && !string.IsNullOrWhiteSpace(block.TiaObjectId);
        }

        private static string CloneBlockObjectIdentity(CloneBlockRecord block)
        {
            return HasUsableTiaObjectId(block)
                ? EmptyIfNull(block.SoftwarePath) + "|" + block.TiaObjectId
                : string.Empty;
        }

        private static bool TryGetUniqueCrossScopeRelativeMatch(
            CloneBlockRecord current,
            Dictionary<string, CloneBlockRecord> cloneByUnscopedRelative,
            HashSet<string> uniqueCurrentUnscopedRelativePaths,
            out CloneBlockRecord clone)
        {
            clone = null;
            string relativePath = CloneBlockUnscopedRelativeIdentity(current);
            if (string.IsNullOrWhiteSpace(relativePath)
                || uniqueCurrentUnscopedRelativePaths == null
                || !uniqueCurrentUnscopedRelativePaths.Contains(relativePath)
                || cloneByUnscopedRelative == null
                || !cloneByUnscopedRelative.TryGetValue(relativePath, out clone))
            {
                clone = null;
                return false;
            }

            // Scoped rows from two distinct PLCs must never match merely because
            // the shared physical _root layout produced the same relative path.
            // This fallback exists only to bind an unscoped loose source to the
            // one live export that can resolve it after creation.
            if (!string.IsNullOrWhiteSpace(current.SoftwarePath) && !string.IsNullOrWhiteSpace(clone.SoftwarePath))
            {
                clone = null;
                return false;
            }

            return true;
        }

        private static string SourceBlockedStatus(CloneBlockRecord current, CloneBlockRecord clone)
        {
            if (EqualsIgnoreCase(current.ExportStatus, "unsupported-language"))
            {
                return clone == null ? "source-blocked-current-only" : "source-blocked-language-converted";
            }

            return clone == null ? "export-error" : "source-blocked-export-error";
        }

        private static string SourceBlockedMessage(CloneBlockRecord current, CloneBlockRecord clone)
        {
            if (EqualsIgnoreCase(current.ExportStatus, "unsupported-language"))
            {
                if (clone == null)
                {
                    return "Current TIA block language '" + current.ProgrammingLanguage + "' cannot be exported as clone source. Convert this block to STL/SCL in TIA before adding it to the source clone workflow.";
                }

                if (EqualsIgnoreCase(clone.ProgrammingLanguage, current.ProgrammingLanguage))
                {
                    return "Current TIA block is represented by tracked clone source metadata, but language '" + current.ProgrammingLanguage + "' cannot be exported safely. Convert it to STL/SCL in TIA, compile, and run check-clone again.";
                }

                return "Current TIA block matches clone block by identity, but the language changed from '" + clone.ProgrammingLanguage + "' in clone to unsupported '" + current.ProgrammingLanguage + "' in TIA. Convert it back to STL/SCL in TIA, compile, and run check-clone again.";
            }

            if (clone != null)
            {
                return "Current TIA block matches clone block by identity, but source export failed. The clone file is kept as protected baseline until the export issue is resolved. " + EmptyIfNull(current.ExportMessage);
            }

            return EmptyIfNull(current.ExportMessage);
        }

        private static List<CloneGroupDiffRecord> BuildCloneGroupDiffs(string outDir, InventorySnapshot snapshot)
        {
            string rootDir = Path.Combine(outDir, "_root");
            HashSet<string> cloneGroups = LoadCloneGroupPaths(outDir);
            HashSet<string> currentGroups = new HashSet<string>(
                snapshot.BlockGroups.Select(x => EmptyIfNull(x.GroupPath)),
                StringComparer.OrdinalIgnoreCase);

            List<CloneGroupDiffRecord> rows = new List<CloneGroupDiffRecord>();
            foreach (string groupPath in currentGroups.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
            {
                string status = cloneGroups.Contains(groupPath) ? "unchanged" : "added";
                rows.Add(new CloneGroupDiffRecord
                {
                    Status = status,
                    GroupPath = groupPath,
                    GroupPathDisplay = GroupPathDisplay(groupPath),
                    CloneDirectory = CloneDirectoryForBlockGroup(rootDir, groupPath),
                    Message = status == "unchanged" ? "Group exists in clone and current TIA project." : "Group exists in current TIA project but not in clone."
                });
            }

            foreach (string groupPath in cloneGroups.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
            {
                if (currentGroups.Contains(groupPath))
                {
                    continue;
                }

                rows.Add(new CloneGroupDiffRecord
                {
                    Status = "removed",
                    GroupPath = groupPath,
                    GroupPathDisplay = GroupPathDisplay(groupPath),
                    CloneDirectory = CloneDirectoryForBlockGroup(rootDir, groupPath),
                    Message = "Group exists in clone but not in current TIA project."
                });
            }

            return rows.OrderBy(x => x.Status).ThenBy(x => x.GroupPath).ToList();
        }

        private static CloneDiffRecord CloneDiff(string status, CloneBlockRecord current, CloneBlockRecord clone, string message)
        {
            CloneBlockRecord source = current ?? clone;
            return new CloneDiffRecord
            {
                SoftwarePath = source == null ? string.Empty : EmptyIfNull(source.SoftwarePath),
                Status = status,
                GroupPath = source == null ? string.Empty : EmptyIfNull(source.GroupPath),
                GroupPathDisplay = source == null ? string.Empty : GroupPathDisplay(source.GroupPath),
                Name = source == null ? string.Empty : source.Name,
                Number = source == null ? string.Empty : source.Number,
                AutoNumber = source == null ? string.Empty : source.AutoNumber,
                NumberMode = source == null ? string.Empty : source.NumberMode,
                NumberSpace = source == null ? string.Empty : source.NumberSpace,
                ProgrammingLanguage = source == null ? string.Empty : source.ProgrammingLanguage,
                BlockType = source == null ? string.Empty : source.BlockType,
                TypeName = source == null ? string.Empty : source.TypeName,
                SourceTypeName = source == null ? string.Empty : source.SourceTypeName,
                InstanceOfName = source == null ? string.Empty : source.InstanceOfName,
                InstanceOfNumber = source == null ? string.Empty : source.InstanceOfNumber,
                InstanceOfType = source == null ? string.Empty : source.InstanceOfType,
                SecondaryType = source == null ? string.Empty : source.SecondaryType,
                MemoryLayout = source == null ? string.Empty : source.MemoryLayout,
                IsConsistent = source == null ? string.Empty : source.IsConsistent,
                IsKnowHowProtected = source == null ? string.Empty : source.IsKnowHowProtected,
                TiaObjectId = source == null ? string.Empty : source.TiaObjectId,
                TiaObjectIdStatus = source == null ? string.Empty : source.TiaObjectIdStatus,
                SourceSha256 = source == null ? string.Empty : source.SourceSha256,
                NormalizedSourceSha256 = source == null ? string.Empty : source.NormalizedSourceSha256,
                CloneGroupPath = clone == null ? string.Empty : EmptyIfNull(clone.GroupPath),
                CloneGroupPathDisplay = clone == null ? string.Empty : GroupPathDisplay(clone.GroupPath),
                CloneSoftwarePath = clone == null ? string.Empty : EmptyIfNull(clone.SoftwarePath),
                CloneName = clone == null ? string.Empty : clone.Name,
                CloneNumber = clone == null ? string.Empty : clone.Number,
                CloneAutoNumber = clone == null ? string.Empty : clone.AutoNumber,
                CloneNumberMode = clone == null ? string.Empty : clone.NumberMode,
                CloneNumberSpace = clone == null ? string.Empty : clone.NumberSpace,
                CloneProgrammingLanguage = clone == null ? string.Empty : clone.ProgrammingLanguage,
                CloneBlockType = clone == null ? string.Empty : clone.BlockType,
                CloneTypeName = clone == null ? string.Empty : clone.TypeName,
                CloneSourceTypeName = clone == null ? string.Empty : clone.SourceTypeName,
                CloneInstanceOfName = clone == null ? string.Empty : clone.InstanceOfName,
                CloneInstanceOfNumber = clone == null ? string.Empty : clone.InstanceOfNumber,
                CloneInstanceOfType = clone == null ? string.Empty : clone.InstanceOfType,
                CloneSecondaryType = clone == null ? string.Empty : clone.SecondaryType,
                CloneMemoryLayout = clone == null ? string.Empty : clone.MemoryLayout,
                CloneIsConsistent = clone == null ? string.Empty : clone.IsConsistent,
                CloneIsKnowHowProtected = clone == null ? string.Empty : clone.IsKnowHowProtected,
                CloneTiaObjectId = clone == null ? string.Empty : clone.TiaObjectId,
                CloneTiaObjectIdStatus = clone == null ? string.Empty : clone.TiaObjectIdStatus,
                CloneSourceSha256 = clone == null ? string.Empty : clone.SourceSha256,
                CloneNormalizedSourceSha256 = clone == null ? string.Empty : clone.NormalizedSourceSha256,
                CloneRelativePath = clone == null ? string.Empty : clone.RelativePath,
                ClonePath = clone == null ? (current == null ? string.Empty : current.ClonePath) : clone.ClonePath,
                CloneProvenance = clone == null ? string.Empty : EmptyIfNull(clone.Provenance),
                CurrentGroupPath = current == null ? string.Empty : EmptyIfNull(current.GroupPath),
                CurrentGroupPathDisplay = current == null ? string.Empty : GroupPathDisplay(current.GroupPath),
                CurrentSoftwarePath = current == null ? string.Empty : EmptyIfNull(current.SoftwarePath),
                CurrentName = current == null ? string.Empty : current.Name,
                CurrentNumber = current == null ? string.Empty : current.Number,
                CurrentAutoNumber = current == null ? string.Empty : current.AutoNumber,
                CurrentNumberMode = current == null ? string.Empty : current.NumberMode,
                CurrentNumberSpace = current == null ? string.Empty : current.NumberSpace,
                CurrentProgrammingLanguage = current == null ? string.Empty : current.ProgrammingLanguage,
                CurrentBlockType = current == null ? string.Empty : current.BlockType,
                CurrentTypeName = current == null ? string.Empty : current.TypeName,
                CurrentSourceTypeName = current == null ? string.Empty : current.SourceTypeName,
                CurrentInstanceOfName = current == null ? string.Empty : current.InstanceOfName,
                CurrentInstanceOfNumber = current == null ? string.Empty : current.InstanceOfNumber,
                CurrentInstanceOfType = current == null ? string.Empty : current.InstanceOfType,
                CurrentSecondaryType = current == null ? string.Empty : current.SecondaryType,
                CurrentMemoryLayout = current == null ? string.Empty : current.MemoryLayout,
                CurrentIsConsistent = current == null ? string.Empty : current.IsConsistent,
                CurrentIsKnowHowProtected = current == null ? string.Empty : current.IsKnowHowProtected,
                CurrentTiaObjectId = current == null ? string.Empty : current.TiaObjectId,
                CurrentTiaObjectIdStatus = current == null ? string.Empty : current.TiaObjectIdStatus,
                CurrentSourceSha256 = current == null ? string.Empty : current.SourceSha256,
                CurrentNormalizedSourceSha256 = current == null ? string.Empty : current.NormalizedSourceSha256,
                CurrentRelativePath = current == null ? string.Empty : current.RelativePath,
                CurrentPath = current == null ? string.Empty : current.CurrentPath,
                CurrentExportStatus = current == null ? string.Empty : current.ExportStatus,
                Message = message
            };
        }

        private static Dictionary<string, CloneBlockRecord> UniqueByIdentity(IEnumerable<CloneBlockRecord> blocks)
        {
            return blocks
                .Select(x => new { Key = CloneBlockIdentity(x), Value = x })
                .Where(x => !string.IsNullOrEmpty(x.Key))
                .GroupBy(x => x.Key, StringComparer.OrdinalIgnoreCase)
                .Where(x => x.Count() == 1)
                .ToDictionary(x => x.Key, x => x.First().Value, StringComparer.OrdinalIgnoreCase);
        }

        private static bool MetadataValueChanged(string currentValue, string cloneValue)
        {
            if (string.IsNullOrWhiteSpace(currentValue) || string.IsNullOrWhiteSpace(cloneValue))
            {
                return false;
            }

            if (EqualsIgnoreCase(currentValue, "Unknown") || EqualsIgnoreCase(cloneValue, "Unknown"))
            {
                return false;
            }

            return !EqualsIgnoreCase(currentValue, cloneValue);
        }

        private static string CloneBlockIdentity(CloneBlockRecord block)
        {
            if (block == null
                || string.IsNullOrWhiteSpace(block.SoftwarePath)
                || string.IsNullOrWhiteSpace(block.Number)
                || string.IsNullOrWhiteSpace(block.ProgrammingLanguage)
                || string.IsNullOrWhiteSpace(block.Name))
            {
                return string.Empty;
            }

            return block.SoftwarePath + "|" + BlockNumberSpace(block.TypeName, block.ProgrammingLanguage) + "|" + block.Number + "|" + block.Name;
        }

        private static string CloneBlockNumberIdentity(CloneBlockRecord block)
        {
            if (block == null
                || string.IsNullOrWhiteSpace(block.SoftwarePath)
                || string.IsNullOrWhiteSpace(block.Number)
                || string.IsNullOrWhiteSpace(block.ProgrammingLanguage))
            {
                return string.Empty;
            }

            return block.SoftwarePath + "|" + BlockNumberSpace(block.TypeName, block.ProgrammingLanguage) + "|" + block.Number;
        }

        private static string CloneBlockRelativeIdentity(CloneBlockRecord block)
        {
            if (block == null
                || string.IsNullOrWhiteSpace(block.SoftwarePath)
                || string.IsNullOrWhiteSpace(block.RelativePath))
            {
                return string.Empty;
            }

            return block.SoftwarePath + "|" + block.RelativePath;
        }

        private static string CloneBlockUnscopedRelativeIdentity(CloneBlockRecord block)
        {
            return block == null ? string.Empty : EmptyIfNull(block.RelativePath).Trim();
        }

        private static void WriteCloneCheckSummary(string path, InventorySnapshot snapshot, string outDir, string compareDir, List<CloneBlockRecord> cloneBlocks, List<CloneBlockRecord> currentBlocks, List<CloneDiffRecord> blockDiffs, List<CloneGroupDiffRecord> groupDiffs, string schemaVersion, string checkRunId)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("Check schema version: " + schemaVersion);
                writer.WriteLine("Check run ID: " + checkRunId);
                writer.WriteLine("Project clone checked at: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Project: " + snapshot.ProjectName);
                writer.WriteLine("Project path: " + snapshot.ProjectPath);
                writer.WriteLine("Clone directory: " + outDir);
                writer.WriteLine("Current export snapshot: " + compareDir);
                writer.WriteLine();
                writer.WriteLine("PLC blocks in clone manifest: " + cloneBlocks.Count);
                writer.WriteLine("PLC blocks in current TIA project: " + currentBlocks.Count);
                WriteStatusCounts(writer, "Block", blockDiffs.Select(x => x.Status));
                writer.WriteLine("Source blockers (blocking / total): " + BlockingSourceBlockedDiffCount(blockDiffs) + " / " + blockDiffs.Count(IsSourceEvidenceBlockerDiff));
                writer.WriteLine();
                WriteStatusCounts(writer, "Group", groupDiffs.Select(x => x.Status));
            }
        }

        private static void WriteCloneCheckBundleMarker(
            string path,
            string checkRunId,
            string compareDirectory,
            CloneCheckTargetIdentity target,
            string blockPath,
            int blockRowCount,
            string groupPath,
            int groupRowCount,
            string sourceBlockerPath,
            int sourceBlockerRowCount,
            string workspacePath,
            int workspaceRowCount,
            string summaryPath,
            string state)
        {
            if (target == null)
            {
                throw new ArgumentNullException("target");
            }

            string softwarePaths = CanonicalSoftwarePaths(target.SoftwarePaths);
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"state\": " + Json(state) + ",");
                writer.WriteLine("  \"schemaVersion\": " + Json(CloneCheckBundleSchemaVersion) + ",");
                writer.WriteLine("  \"toolVersion\": " + Json(ProductVersion) + ",");
                writer.WriteLine("  \"cloneMatcherRevision\": " + Json(CloneMatcherRevision) + ",");
                writer.WriteLine("  \"writeSafetyPolicyRevision\": " + Json(CloneWriteSafetyPolicyRevision) + ",");
                writer.WriteLine("  \"checkRunId\": " + Json(checkRunId) + ",");
                writer.WriteLine("  \"compareDirectory\": " + Json(Path.GetFullPath(compareDirectory)) + ",");
                writer.WriteLine("  \"projectPath\": " + Json(NormalizeComparablePath(target.ProjectPath)) + ",");
                writer.WriteLine("  \"projectName\": " + Json(EmptyIfNull(target.ProjectName)) + ",");
                writer.WriteLine("  \"projectVersion\": " + Json(EmptyIfNull(target.ProjectVersion)) + ",");
                writer.WriteLine("  \"projectObjectId\": " + Json(EmptyIfNull(target.ProjectObjectId)) + ",");
                writer.WriteLine("  \"projectObjectIdStatus\": " + Json(EmptyIfNull(target.ProjectObjectIdStatus)) + ",");
                writer.WriteLine("  \"softwarePathCount\": " + Json(target.SoftwarePaths.Count.ToString(CultureInfo.InvariantCulture)) + ",");
                writer.WriteLine("  \"softwarePathsSha256\": " + Json(ComputeTextSha256(softwarePaths)) + ",");
                writer.WriteLine("  \"softwarePaths\": " + Json(softwarePaths) + ",");
                writer.WriteLine("  \"blockSha256\": " + Json(ComputeFileSha256(blockPath)) + ",");
                writer.WriteLine("  \"blockRowCount\": " + Json(blockRowCount.ToString(CultureInfo.InvariantCulture)) + ",");
                writer.WriteLine("  \"groupSha256\": " + Json(ComputeFileSha256(groupPath)) + ",");
                writer.WriteLine("  \"groupRowCount\": " + Json(groupRowCount.ToString(CultureInfo.InvariantCulture)) + ",");
                writer.WriteLine("  \"sourceBlockerSha256\": " + Json(ComputeFileSha256(sourceBlockerPath)) + ",");
                writer.WriteLine("  \"sourceBlockerRowCount\": " + Json(sourceBlockerRowCount.ToString(CultureInfo.InvariantCulture)) + ",");
                writer.WriteLine("  \"workspaceSha256\": " + Json(ComputeFileSha256(workspacePath)) + ",");
                writer.WriteLine("  \"workspaceRowCount\": " + Json(workspaceRowCount.ToString(CultureInfo.InvariantCulture)) + ",");
                writer.WriteLine("  \"summarySha256\": " + Json(ComputeFileSha256(summaryPath)));
                writer.WriteLine("}");
            }
        }

        private static void PublishFileAtomically(string stagedPath, string finalPath, string backupDirectory)
        {
            if (!File.Exists(stagedPath))
            {
                throw new FileNotFoundException("Staged clone-check report was not found.", stagedPath);
            }

            Directory.CreateDirectory(Path.GetDirectoryName(finalPath));
            if (!File.Exists(finalPath))
            {
                File.Move(stagedPath, finalPath);
                return;
            }

            string backupPath = Path.Combine(backupDirectory, Path.GetFileName(finalPath) + ".previous");
            if (File.Exists(backupPath))
            {
                File.Delete(backupPath);
            }

            File.Replace(stagedPath, finalPath, backupPath, true);
            if (File.Exists(backupPath))
            {
                File.Delete(backupPath);
            }
        }

        private static void InvalidateCloneCheckBundle(string outDir)
        {
            string markerPath = Path.Combine(outDir, CloneCheckBundleFileName);
            if (File.Exists(markerPath))
            {
                File.Delete(markerPath);
            }
        }

        private static CloneAuthorizationRefreshLease BeginCloneAuthorizationRefresh(Options options)
        {
            string outDir = ResolveCloneProjectDirectory(options.OutDir);
            IDisposable workspaceLock = AcquireCloneWorkspaceLock(outDir, "clone-authorization-refresh");
            string attemptId = Guid.NewGuid().ToString("N");
            try
            {
                if (!string.IsNullOrWhiteSpace(_activeCloneAuthorizationRefreshAttemptId))
                {
                    throw new InvalidOperationException("A clone authorization refresh is already active on this thread.");
                }

                _activeCloneAuthorizationRefreshAttemptId = attemptId;
                string attemptPath = Path.Combine(outDir, CloneCheckAttemptFileName);
                WriteFlatJsonObjectAtomically(
                    attemptPath,
                    new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                    {
                        { "state", "refresh-started" },
                        { "attemptId", attemptId },
                        { "startedUtc", DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) },
                        { "command", EmptyIfNull(options.Command) },
                        { "previousBundleRevoked", "true" }
                    });
                FlushFileToDisk(attemptPath);

                // The durable attempt marker is written first. Even if deleting
                // the old bundle or attaching to TIA fails, every consumer now
                // rejects the former authorization.
                InvalidateCloneCheckBundle(outDir);
                return new CloneAuthorizationRefreshLease(outDir, attemptId, workspaceLock);
            }
            catch
            {
                if (EqualsIgnoreCase(_activeCloneAuthorizationRefreshAttemptId, attemptId))
                {
                    _activeCloneAuthorizationRefreshAttemptId = null;
                }
                workspaceLock.Dispose();
                throw;
            }
        }

        private static Exception AbortFailedCloneAuthorizationRefresh(
            CloneAuthorizationRefreshLease refresh,
            Exception originalFailure)
        {
            if (refresh == null)
            {
                return originalFailure;
            }

            try
            {
                refresh.AbortAndKeepRevoked();
                return originalFailure;
            }
            catch (Exception abortFailure)
            {
                return new AggregateException(
                    "Clone authorization refresh failed, and provisional authorization cleanup also failed. The durable attempt marker remains authoritative revocation evidence.",
                    originalFailure,
                    abortFailure);
            }
        }

        private static void CommitPreparedCloneCheckBundle(string outDir)
        {
            string markerPath = Path.Combine(outDir, CloneCheckBundleFileName);
            Dictionary<string, string> marker = ParseStrictFlatJsonObject(
                File.ReadAllText(markerPath, Encoding.UTF8),
                markerPath);
            string state = RequiredCloneCheckMarkerValue(marker, "state", markerPath);
            if (!EqualsIgnoreCase(state, "reports-prepared")
                && !EqualsIgnoreCase(state, "authoritative-complete"))
            {
                throw new InvalidDataException("Clone-check bundle cannot be committed from state '" + state + "'.");
            }

            marker["state"] = "authoritative-complete";
            WriteFlatJsonObjectAtomically(markerPath, marker);
            FlushFileToDisk(markerPath);
        }

        private static void FlushFileToDisk(string path)
        {
            using (FileStream stream = new FileStream(path, FileMode.Open, FileAccess.ReadWrite, FileShare.Read))
            {
                stream.Flush(true);
            }
        }

        private static CloneCheckBundleEvidence LoadAndValidateCloneCheckBundle(string outDir)
        {
            ValidateCloneWorkspacePhysicalIsolation(outDir);
            string attemptPath = Path.Combine(outDir, CloneCheckAttemptFileName);
            bool ownsActiveAttempt = false;
            if (File.Exists(attemptPath))
            {
                Dictionary<string, string> attempt = ParseStrictFlatJsonObject(
                    File.ReadAllText(attemptPath, Encoding.UTF8),
                    attemptPath);
                string attemptState = RequiredCloneCheckMarkerValue(attempt, "state", attemptPath);
                string attemptId = RequiredCloneCheckMarkerValue(attempt, "attemptId", attemptPath);
                string previousBundleRevoked = RequiredCloneCheckMarkerValue(attempt, "previousBundleRevoked", attemptPath);
                ownsActiveAttempt = EqualsIgnoreCase(attemptState, "refresh-started")
                    && EqualsIgnoreCase(previousBundleRevoked, "true")
                    && EqualsIgnoreCase(attemptId, _activeCloneAuthorizationRefreshAttemptId);
                if (!ownsActiveAttempt)
                {
                    throw new InvalidDataException(
                        "Clone authorization refresh is incomplete; the previous bundle remains revoked. Run check-clone again: "
                        + attemptPath);
                }
            }

            string markerPath = Path.Combine(outDir, CloneCheckBundleFileName);
            if (!File.Exists(markerPath))
            {
                throw new InvalidDataException("Completed clone-check bundle marker is missing. Run check-clone again: " + markerPath);
            }

            Dictionary<string, string> marker = ParseStrictFlatJsonObject(File.ReadAllText(markerPath, Encoding.UTF8), markerPath);
            string state = RequiredCloneCheckMarkerValue(marker, "state", markerPath);
            string schemaVersion = RequiredCloneCheckMarkerValue(marker, "schemaVersion", markerPath);
            string checkRunId = RequiredCloneCheckMarkerValue(marker, "checkRunId", markerPath);
            bool stateAccepted = EqualsIgnoreCase(state, "authoritative-complete")
                || (ownsActiveAttempt && EqualsIgnoreCase(state, "reports-prepared"));
            if (!stateAccepted)
            {
                throw new InvalidDataException("Clone-check bundle marker is not authoritative-complete: " + markerPath);
            }

            if (!EqualsIgnoreCase(schemaVersion, CloneCheckBundleSchemaVersion))
            {
                throw new InvalidDataException("Unsupported clone-check bundle schema version '" + schemaVersion + "'. Run check-clone with the current safety policy.");
            }

            string toolVersion = RequiredCloneCheckMarkerValue(marker, "toolVersion", markerPath);
            string cloneMatcherRevision = RequiredCloneCheckMarkerValue(marker, "cloneMatcherRevision", markerPath);
            string writeSafetyPolicyRevision = RequiredCloneCheckMarkerValue(marker, "writeSafetyPolicyRevision", markerPath);
            if (!EqualsIgnoreCase(toolVersion, ProductVersion)
                || !EqualsIgnoreCase(cloneMatcherRevision, CloneMatcherRevision)
                || !EqualsIgnoreCase(writeSafetyPolicyRevision, CloneWriteSafetyPolicyRevision))
            {
                throw new InvalidDataException(
                    "Clone-check bundle matcher/write-safety policy is not current. Run check-clone with the current safety policy."
                    + " Bundle tool=" + toolVersion
                    + "; matcher=" + cloneMatcherRevision
                    + "; writePolicy=" + writeSafetyPolicyRevision + ".");
            }

            if (!Regex.IsMatch(checkRunId, "^[0-9a-fA-F]{32}$"))
            {
                throw new InvalidDataException("Clone-check bundle has an invalid checkRunId.");
            }

            string blockPath = Path.Combine(outDir, CloneCheckBlockFileName);
            string groupPath = Path.Combine(outDir, CloneCheckGroupFileName);
            string sourceBlockerPath = Path.Combine(outDir, CloneCheckSourceBlockerFileName);
            string workspacePath = Path.Combine(outDir, CloneCheckWorkspaceFileName);
            string summaryPath = Path.Combine(outDir, CloneCheckSummaryFileName);
            List<Dictionary<string, string>> blockRows = ValidateCloneCheckCsvFile(blockPath, marker, "block", schemaVersion, checkRunId);
            List<Dictionary<string, string>> groupRows = ValidateCloneCheckCsvFile(groupPath, marker, "group", schemaVersion, checkRunId);
            List<Dictionary<string, string>> sourceBlockerRows = ValidateCloneCheckCsvFile(sourceBlockerPath, marker, "sourceBlocker", schemaVersion, checkRunId);
            List<Dictionary<string, string>> workspaceRows = ValidateCloneCheckCsvFile(workspacePath, marker, "workspace", schemaVersion, checkRunId);
            ValidateCloneCheckFileHash(summaryPath, RequiredCloneCheckMarkerValue(marker, "summarySha256", markerPath));
            ValidateCloneWorkspaceInventory(outDir, workspaceRows);

            string compareDirectory = Path.GetFullPath(RequiredCloneCheckMarkerValue(marker, "compareDirectory", markerPath));
            string compareBase = Path.Combine(Path.GetFullPath(outDir), "_compare");
            EnsurePathInside(compareDirectory, compareBase);
            if (!Directory.Exists(Path.Combine(compareDirectory, "_root")))
            {
                throw new InvalidDataException("Clone-check bundle compare snapshot is missing: " + compareDirectory);
            }

            ValidateCloneCheckRowPaths(outDir, compareDirectory, blockRows);
            ValidateNoConflictingClonePhysicalPaths(outDir, compareDirectory, blockRows);
            ValidateNoConflictingCloneDiffPairs(blockRows);

            string projectPath = NormalizeComparablePath(RequiredCloneCheckMarkerValue(marker, "projectPath", markerPath));
            string projectName = MarkerValue(marker, "projectName");
            string projectVersion = RequiredCloneCheckMarkerValue(marker, "projectVersion", markerPath);
            string projectObjectId = MarkerValue(marker, "projectObjectId");
            string projectObjectIdStatus = RequiredCloneCheckMarkerValue(marker, "projectObjectIdStatus", markerPath);
            string softwarePathsText = RequiredCloneCheckMarkerValue(marker, "softwarePaths", markerPath);
            List<string> softwarePaths = softwarePathsText
                .Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(x => x.Trim())
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToList();
            int softwarePathCount;
            if (!int.TryParse(RequiredCloneCheckMarkerValue(marker, "softwarePathCount", markerPath), NumberStyles.None, CultureInfo.InvariantCulture, out softwarePathCount)
                || softwarePathCount <= 0
                || softwarePathCount != softwarePaths.Count)
            {
                throw new InvalidDataException("Clone-check bundle has an invalid or inconsistent softwarePathCount.");
            }

            if (!EqualsIgnoreCase(
                ComputeTextSha256(CanonicalSoftwarePaths(softwarePaths)),
                RequiredCloneCheckMarkerValue(marker, "softwarePathsSha256", markerPath)))
            {
                throw new InvalidDataException("Clone-check bundle software-path set hash mismatch.");
            }

            return new CloneCheckBundleEvidence
            {
                SchemaVersion = schemaVersion,
                ToolVersion = toolVersion,
                CloneMatcherRevision = cloneMatcherRevision,
                WriteSafetyPolicyRevision = writeSafetyPolicyRevision,
                CheckRunId = checkRunId,
                CompareDirectory = compareDirectory,
                ProjectPath = projectPath,
                ProjectName = projectName,
                ProjectVersion = projectVersion,
                ProjectObjectId = projectObjectId,
                ProjectObjectIdStatus = projectObjectIdStatus,
                SoftwarePaths = softwarePaths,
                BlockRows = blockRows,
                GroupRows = groupRows,
                SourceBlockerRows = sourceBlockerRows,
                WorkspaceRows = workspaceRows
            };
        }

        private static string RequiredCloneCheckMarkerValue(Dictionary<string, string> marker, string key, string markerPath)
        {
            string value;
            if (marker == null || !marker.TryGetValue(key, out value) || string.IsNullOrWhiteSpace(value))
            {
                throw new InvalidDataException("Clone-check bundle marker is missing '" + key + "': " + markerPath);
            }

            return value.Trim();
        }

        private static string MarkerValue(Dictionary<string, string> marker, string key)
        {
            string value;
            return marker != null && marker.TryGetValue(key, out value) ? EmptyIfNull(value).Trim() : string.Empty;
        }

        private static List<Dictionary<string, string>> ValidateCloneCheckCsvFile(
            string path,
            Dictionary<string, string> marker,
            string markerPrefix,
            string schemaVersion,
            string checkRunId)
        {
            string markerPath = Path.Combine(Path.GetDirectoryName(path), CloneCheckBundleFileName);
            string expectedHash = RequiredCloneCheckMarkerValue(marker, markerPrefix + "Sha256", markerPath);
            ValidateCloneCheckFileHash(path, expectedHash);

            int expectedRowCount;
            string rowCountText = RequiredCloneCheckMarkerValue(marker, markerPrefix + "RowCount", markerPath);
            if (!int.TryParse(rowCountText, NumberStyles.None, CultureInfo.InvariantCulture, out expectedRowCount) || expectedRowCount < 0)
            {
                throw new InvalidDataException("Clone-check bundle marker has an invalid " + markerPrefix + "RowCount.");
            }

            string[] lines = File.ReadAllLines(path, Encoding.UTF8);
            if (lines.Length == 0)
            {
                throw new InvalidDataException("Clone-check CSV has no header: " + path);
            }

            List<string> headers = ParseCsvLine(lines[0]);
            if (!headers.Any(x => EqualsIgnoreCase(x, "CheckSchemaVersion"))
                || !headers.Any(x => EqualsIgnoreCase(x, "CheckRunId")))
            {
                throw new InvalidDataException("Clone-check CSV lacks bundle identity columns: " + path);
            }

            List<Dictionary<string, string>> rows = ReadCsv(path);
            if (rows.Count != expectedRowCount)
            {
                throw new InvalidDataException("Clone-check CSV row count does not match its bundle marker: " + path);
            }

            if (rows.Any(row => !EqualsIgnoreCase(GetCsvValue(row, "CheckSchemaVersion"), schemaVersion)
                || !EqualsIgnoreCase(GetCsvValue(row, "CheckRunId"), checkRunId)))
            {
                throw new InvalidDataException("Clone-check CSV contains rows from a different schema/run: " + path);
            }

            return rows;
        }

        private static void ValidateCloneCheckFileHash(string path, string expectedHash)
        {
            if (!File.Exists(path))
            {
                throw new InvalidDataException("Clone-check bundle file is missing: " + path);
            }

            string actualHash = ComputeFileSha256(path);
            if (string.IsNullOrWhiteSpace(expectedHash) || !EqualsIgnoreCase(actualHash, expectedHash))
            {
                throw new InvalidDataException("Clone-check bundle file hash mismatch: " + path);
            }
        }

        private static List<CloneWorkspaceFileRecord> BuildCloneWorkspaceInventory(string outDir)
        {
            string fullOutDir = Path.GetFullPath(outDir);
            ValidateCloneWorkspacePhysicalIsolation(fullOutDir);
            List<CloneWorkspaceFileRecord> records = new List<CloneWorkspaceFileRecord>();
            string rootDir = Path.Combine(fullOutDir, "_root");
            if (Directory.Exists(rootDir))
            {
                foreach (string file in Directory.GetFiles(rootDir, "*", SearchOption.AllDirectories))
                {
                    string kind = IsKnownSourceFile(file)
                        ? "source"
                        : file.EndsWith(".meta.json", StringComparison.OrdinalIgnoreCase) ? "sidecar" : "root-file";
                    records.Add(CreateCloneWorkspaceFileRecord(fullOutDir, file, kind));
                }
            }

            foreach (string manifestName in new[] { "plc-blocks.csv", "block-groups.csv" })
            {
                string manifestPath = Path.Combine(fullOutDir, manifestName);
                if (File.Exists(manifestPath))
                {
                    records.Add(CreateCloneWorkspaceFileRecord(fullOutDir, manifestPath, "manifest"));
                }
            }

            string metadataDir = Path.Combine(fullOutDir, "_metadata");
            if (Directory.Exists(metadataDir))
            {
                foreach (string file in Directory.GetFiles(metadataDir, "*", SearchOption.AllDirectories))
                {
                    records.Add(CreateCloneWorkspaceFileRecord(fullOutDir, file, "machine-manifest"));
                }
            }

            return records
                .OrderBy(x => x.RelativePath, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static string CreateStableCloneWorkspaceSnapshot(
            string outDir,
            string checkRunId,
            out List<CloneWorkspaceFileRecord> workspaceFiles)
        {
            workspaceFiles = BuildCloneWorkspaceInventory(outDir);
            string snapshotBase = Path.Combine(Path.GetTempPath(), "OpennessLLM-check-snapshots");
            CleanupStaleOwnedCloneWorkspaceSnapshots(snapshotBase);
            string snapshotRoot = Path.Combine(
                snapshotBase,
                "run-" + checkRunId + "-" + Guid.NewGuid().ToString("N").Substring(0, 8));
            try
            {
                Directory.CreateDirectory(snapshotRoot);
                WriteFlatJsonObjectAtomically(
                    Path.Combine(snapshotRoot, CloneWorkspaceSnapshotOwnerFileName),
                    new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                    {
                        { "owner", ProductName },
                        { "purpose", "immutable-clone-check-snapshot" },
                        { "checkRunId", EmptyIfNull(checkRunId) },
                        { "createdUtc", DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) }
                    });
                foreach (CloneWorkspaceFileRecord record in workspaceFiles)
                {
                    string relativePath = record.RelativePath.Replace('/', Path.DirectorySeparatorChar);
                    string sourcePath = Path.Combine(outDir, relativePath);
                    string snapshotPath = Path.Combine(snapshotRoot, relativePath);
                    EnsurePathInside(sourcePath, outDir);
                    EnsurePathInside(snapshotPath, snapshotRoot);
                    Directory.CreateDirectory(Path.GetDirectoryName(snapshotPath));
                    File.Copy(sourcePath, snapshotPath, false);
                    FileInfo copied = new FileInfo(snapshotPath);
                    if (copied.Length != record.Size
                        || !EqualsIgnoreCase(ComputeFileSha256(snapshotPath), record.Sha256))
                    {
                        throw new InvalidDataException("Clone workspace changed while its immutable check snapshot was being created: " + record.RelativePath);
                    }
                }

                List<Dictionary<string, string>> expectedRows = CloneWorkspaceInventoryRows(workspaceFiles);
                ValidateCloneWorkspaceInventory(snapshotRoot, expectedRows);
                ValidateCloneWorkspaceInventory(outDir, expectedRows);
                return snapshotRoot;
            }
            catch (Exception snapshotException)
            {
                try
                {
                    DeleteCloneWorkspaceSnapshotStrict(
                        snapshotRoot,
                        delegate(string candidate) { Directory.Delete(candidate, true); },
                        false);
                }
                catch (Exception cleanupException)
                {
                    throw new AggregateException(
                        "Clone workspace snapshot creation and cleanup both failed.",
                        snapshotException,
                        cleanupException);
                }
                throw;
            }
        }

        private static CloneWorkspaceSnapshotLease AcquireStableCloneWorkspaceSnapshot(
            string outDir,
            string checkRunId)
        {
            List<CloneWorkspaceFileRecord> files;
            string directoryPath = CreateStableCloneWorkspaceSnapshot(outDir, checkRunId, out files);
            return new CloneWorkspaceSnapshotLease(directoryPath, files);
        }

        private static List<Dictionary<string, string>> CloneWorkspaceInventoryRows(
            List<CloneWorkspaceFileRecord> records)
        {
            return (records ?? new List<CloneWorkspaceFileRecord>())
                .Select(record => new Dictionary<string, string>
                {
                    { "Kind", record.Kind },
                    { "RelativePath", record.RelativePath },
                    { "Size", record.Size.ToString(CultureInfo.InvariantCulture) },
                    { "Sha256", record.Sha256 }
                })
                .ToList();
        }

        private static void RemapCloneSnapshotPaths(
            List<CloneBlockRecord> cloneBlocks,
            string snapshotRoot,
            string durableRoot)
        {
            foreach (CloneBlockRecord block in cloneBlocks ?? new List<CloneBlockRecord>())
            {
                if (block == null || string.IsNullOrWhiteSpace(block.RelativePath))
                {
                    continue;
                }

                string snapshotPath = Path.Combine(snapshotRoot, block.RelativePath);
                EnsurePathInside(snapshotPath, snapshotRoot);
                block.ClonePath = Path.Combine(durableRoot, block.RelativePath);
                EnsurePathInside(block.ClonePath, durableRoot);
            }
        }

        private static void ValidateCloneDiffHashesAgainstWorkspace(
            string outDir,
            List<CloneDiffRecord> blockDiffs,
            List<CloneWorkspaceFileRecord> workspaceFiles)
        {
            Dictionary<string, CloneWorkspaceFileRecord> inventory = (workspaceFiles ?? new List<CloneWorkspaceFileRecord>())
                .ToDictionary(x => x.RelativePath, StringComparer.OrdinalIgnoreCase);
            foreach (CloneDiffRecord diff in blockDiffs ?? new List<CloneDiffRecord>())
            {
                if (string.IsNullOrWhiteSpace(diff.ClonePath)
                    || string.IsNullOrWhiteSpace(diff.CloneSourceSha256))
                {
                    continue;
                }

                EnsurePathInside(diff.ClonePath, Path.Combine(outDir, "_root"));
                string relativePath = NormalizeCloneWorkspaceRelativePath(MakeRelativePath(outDir, diff.ClonePath));
                CloneWorkspaceFileRecord record;
                if (!inventory.TryGetValue(relativePath, out record)
                    || !EqualsIgnoreCase(record.Kind, "source")
                    || !EqualsIgnoreCase(record.Sha256, diff.CloneSourceSha256))
                {
                    throw new InvalidDataException(
                        "Clone diff source hash is not bound to the same immutable workspace snapshot: "
                        + relativePath);
                }
            }
        }

        private static void TryDeleteDirectory(string path)
        {
            try
            {
                if (!string.IsNullOrWhiteSpace(path) && Directory.Exists(path))
                {
                    Directory.Delete(path, true);
                }
            }
            catch
            {
            }
        }

        private static void CleanupStaleOwnedCloneWorkspaceSnapshots(string snapshotBase)
        {
            if (!Directory.Exists(snapshotBase))
            {
                return;
            }

            EnsureExistingPathChainHasNoReparsePoints(snapshotBase, "clone snapshot base");
            foreach (DirectoryInfo directory in new DirectoryInfo(snapshotBase).GetDirectories("*", SearchOption.TopDirectoryOnly))
            {
                if ((directory.Attributes & FileAttributes.ReparsePoint) != 0)
                {
                    throw new InvalidOperationException("Refusing a reparse point/symlink in clone snapshot base: " + directory.FullName);
                }
                if (!IsOwnedCloneWorkspaceSnapshot(directory.FullName)
                    || directory.LastWriteTimeUtc > DateTime.UtcNow.AddHours(-24))
                {
                    continue;
                }
                DeleteOwnedCloneWorkspaceSnapshotStrict(directory.FullName);
            }
        }

        private static bool IsOwnedCloneWorkspaceSnapshot(string path)
        {
            string ownerPath = Path.Combine(path, CloneWorkspaceSnapshotOwnerFileName);
            if (!File.Exists(ownerPath))
            {
                return false;
            }
            try
            {
                Dictionary<string, string> owner = ParseStrictFlatJsonObject(
                    File.ReadAllText(ownerPath, Encoding.UTF8),
                    ownerPath);
                return EqualsIgnoreCase(MarkerValue(owner, "owner"), ProductName)
                    && EqualsIgnoreCase(MarkerValue(owner, "purpose"), "immutable-clone-check-snapshot");
            }
            catch
            {
                return false;
            }
        }

        private static void DeleteOwnedCloneWorkspaceSnapshotStrict(string path)
        {
            DeleteOwnedCloneWorkspaceSnapshotStrict(
                path,
                delegate(string candidate) { Directory.Delete(candidate, true); });
        }

        private static void DeleteOwnedCloneWorkspaceSnapshotStrict(string path, Action<string> deleteAction)
        {
            DeleteCloneWorkspaceSnapshotStrict(path, deleteAction, true);
        }

        private static void DeleteCloneWorkspaceSnapshotStrict(
            string path,
            Action<string> deleteAction,
            bool requireOwner)
        {
            if (string.IsNullOrWhiteSpace(path) || !Directory.Exists(path))
            {
                return;
            }

            string snapshotBase = Path.Combine(Path.GetTempPath(), "OpennessLLM-check-snapshots");
            EnsurePathInside(path, snapshotBase);
            if (requireOwner && !IsOwnedCloneWorkspaceSnapshot(path))
            {
                throw new InvalidOperationException("Refusing to delete an unowned clone workspace snapshot: " + path);
            }

            Exception lastFailure = null;
            for (int attempt = 1; attempt <= 3; attempt++)
            {
                try
                {
                    EnsureExistingTreeHasNoReparsePoints(path, "owned clone workspace snapshot");
                    deleteAction(path);
                    if (!Directory.Exists(path))
                    {
                        return;
                    }
                    lastFailure = new IOException("Snapshot directory still exists after delete attempt " + attempt.ToString(CultureInfo.InvariantCulture) + ".");
                }
                catch (Exception ex)
                {
                    lastFailure = ex;
                }
                System.Threading.Thread.Sleep(25);
            }

            string quarantinePath = Path.Combine(
                snapshotBase,
                "quarantine-" + Path.GetFileName(path) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8));
            string auditPath;
            try
            {
                Directory.Move(path, quarantinePath);
                auditPath = Path.Combine(quarantinePath, "cleanup-failure.txt");
            }
            catch (Exception moveException)
            {
                auditPath = Path.Combine(path, "cleanup-failure.txt");
                try
                {
                    WriteTextFile(
                        auditPath,
                        "Snapshot cleanup failed and quarantine move also failed.\nDelete error: "
                        + (lastFailure == null ? "unknown" : lastFailure.ToString())
                        + "\nMove error: " + moveException + "\n");
                }
                catch
                {
                }
                throw new IOException(
                    "Owned clone workspace snapshot cleanup failed and it could not be quarantined: " + path,
                    new AggregateException(lastFailure ?? new IOException("Unknown delete failure."), moveException));
            }

            WriteTextFile(
                auditPath,
                "Snapshot cleanup failed; the owned directory was quarantined.\nOriginal: " + path
                + "\nQuarantine: " + quarantinePath
                + "\nError: " + (lastFailure == null ? "unknown" : lastFailure.ToString()) + "\n");
            throw new IOException(
                "Owned clone workspace snapshot cleanup failed; snapshot was quarantined at: " + quarantinePath,
                lastFailure);
        }

        private static CloneWorkspaceFileRecord CreateCloneWorkspaceFileRecord(string outDir, string path, string kind)
        {
            EnsurePathInside(path, outDir);
            FileInfo info = new FileInfo(path);
            return new CloneWorkspaceFileRecord
            {
                Kind = kind,
                RelativePath = NormalizeCloneWorkspaceRelativePath(MakeRelativePath(outDir, path)),
                Size = info.Length,
                Sha256 = ComputeFileSha256(path)
            };
        }

        private static string NormalizeCloneWorkspaceRelativePath(string path)
        {
            return EmptyIfNull(path)
                .Replace(Path.DirectorySeparatorChar, '/')
                .Replace(Path.AltDirectorySeparatorChar, '/');
        }

        private static void ValidateCloneWorkspaceInventory(string outDir, List<Dictionary<string, string>> expectedRows)
        {
            List<CloneWorkspaceFileRecord> actual = BuildCloneWorkspaceInventory(outDir);
            List<CloneWorkspaceFileRecord> expected = new List<CloneWorkspaceFileRecord>();
            HashSet<string> paths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (Dictionary<string, string> row in expectedRows ?? new List<Dictionary<string, string>>())
            {
                string kind = GetCsvValue(row, "Kind");
                string relativePath = NormalizeCloneWorkspaceRelativePath(GetCsvValue(row, "RelativePath"));
                long size;
                string sha256 = GetCsvValue(row, "Sha256");
                if (string.IsNullOrWhiteSpace(kind)
                    || string.IsNullOrWhiteSpace(relativePath)
                    || Path.IsPathRooted(relativePath)
                    || relativePath.Split('/').Any(x => EqualsIgnoreCase(x, ".."))
                    || !long.TryParse(GetCsvValue(row, "Size"), NumberStyles.None, CultureInfo.InvariantCulture, out size)
                    || size < 0
                    || !Regex.IsMatch(sha256, "^[0-9a-fA-F]{64}$")
                    || !paths.Add(relativePath))
                {
                    throw new InvalidDataException("Clone-check workspace inventory contains an invalid or duplicate row: " + relativePath);
                }

                expected.Add(new CloneWorkspaceFileRecord { Kind = kind, RelativePath = relativePath, Size = size, Sha256 = sha256 });
            }

            expected = expected.OrderBy(x => x.RelativePath, StringComparer.OrdinalIgnoreCase).ToList();
            if (expected.Count != actual.Count)
            {
                throw new InvalidDataException(
                    "Clone workspace changed after check-clone (file count "
                    + expected.Count.ToString(CultureInfo.InvariantCulture) + " -> "
                    + actual.Count.ToString(CultureInfo.InvariantCulture) + "). Run check-clone again after every local edit/create/delete/rename.");
            }

            for (int i = 0; i < expected.Count; i++)
            {
                CloneWorkspaceFileRecord left = expected[i];
                CloneWorkspaceFileRecord right = actual[i];
                if (!EqualsIgnoreCase(left.Kind, right.Kind)
                    || !EqualsIgnoreCase(left.RelativePath, right.RelativePath)
                    || left.Size != right.Size
                    || !EqualsIgnoreCase(left.Sha256, right.Sha256))
                {
                    throw new InvalidDataException(
                        "Clone workspace changed after check-clone at '"
                        + FirstNonEmpty(left.RelativePath, right.RelativePath)
                        + "'. Run check-clone again after every local edit/create/delete/rename.");
                }
            }
        }

        private static void ValidateStagedRootAgainstWorkspaceInventory(
            string stagingRoot,
            List<Dictionary<string, string>> expectedRows)
        {
            string fullStagingRoot = Path.GetFullPath(stagingRoot);
            List<CloneWorkspaceFileRecord> expectedRoot = (expectedRows ?? new List<Dictionary<string, string>>())
                .Where(x => NormalizeCloneWorkspaceRelativePath(GetCsvValue(x, "RelativePath")).StartsWith("_root/", StringComparison.OrdinalIgnoreCase))
                .Select(x => new CloneWorkspaceFileRecord
                {
                    Kind = GetCsvValue(x, "Kind"),
                    RelativePath = NormalizeCloneWorkspaceRelativePath(GetCsvValue(x, "RelativePath")).Substring("_root/".Length),
                    Size = long.Parse(GetCsvValue(x, "Size"), CultureInfo.InvariantCulture),
                    Sha256 = GetCsvValue(x, "Sha256")
                })
                .OrderBy(x => x.RelativePath, StringComparer.OrdinalIgnoreCase)
                .ToList();
            List<CloneWorkspaceFileRecord> actualRoot = Directory.Exists(fullStagingRoot)
                ? Directory.GetFiles(fullStagingRoot, "*", SearchOption.AllDirectories)
                    .Select(x => CreateCloneWorkspaceFileRecord(fullStagingRoot, x,
                        IsKnownSourceFile(x) ? "source" : x.EndsWith(".meta.json", StringComparison.OrdinalIgnoreCase) ? "sidecar" : "root-file"))
                    .OrderBy(x => x.RelativePath, StringComparer.OrdinalIgnoreCase)
                    .ToList()
                : new List<CloneWorkspaceFileRecord>();

            if (expectedRoot.Count != actualRoot.Count
                || expectedRoot.Where((x, i) => !EqualsIgnoreCase(x.Kind, actualRoot[i].Kind)
                    || !EqualsIgnoreCase(x.RelativePath, actualRoot[i].RelativePath)
                    || x.Size != actualRoot[i].Size
                    || !EqualsIgnoreCase(x.Sha256, actualRoot[i].Sha256)).Any())
            {
                throw new InvalidDataException("Staged _root does not match the exact workspace bytes authorized by check-clone.");
            }
        }

        private static void EnsureCloneCheckCurrentSourcesUnchanged(List<Dictionary<string, string>> blockRows)
        {
            foreach (Dictionary<string, string> row in blockRows ?? new List<Dictionary<string, string>>())
            {
                string status = GetCsvValue(row, "Status");
                if (!EqualsIgnoreCase(status, "changed")
                    && !EqualsIgnoreCase(status, "added")
                    && !EqualsIgnoreCase(status, "moved-or-renamed")
                    && !EqualsIgnoreCase(status, "moved-or-renamed-and-changed"))
                {
                    continue;
                }

                string currentPath = GetCsvValue(row, "CurrentPath");
                string expectedHash = GetCsvValue(row, "CurrentSourceSha256");
                if (string.IsNullOrWhiteSpace(currentPath)
                    || string.IsNullOrWhiteSpace(expectedHash)
                    || !File.Exists(currentPath)
                    || !EqualsIgnoreCase(ComputeFileSha256(currentPath), expectedHash))
                {
                    throw new InvalidDataException("Current source snapshot changed after check-clone. Run check-clone again: " + FirstNonEmpty(currentPath, "missing path"));
                }
            }
        }

        private static void ValidateCloneCheckRowPaths(string outDir, string compareDirectory, List<Dictionary<string, string>> blockRows)
        {
            string rootDir = Path.Combine(Path.GetFullPath(outDir), "_root");
            string compareRoot = Path.Combine(compareDirectory, "_root");
            foreach (Dictionary<string, string> row in blockRows ?? new List<Dictionary<string, string>>())
            {
                string clonePath = GetCsvValue(row, "ClonePath");
                if (!string.IsNullOrWhiteSpace(clonePath))
                {
                    EnsurePathInside(clonePath, rootDir);
                }

                string currentPath = GetCsvValue(row, "CurrentPath");
                if (!string.IsNullOrWhiteSpace(currentPath))
                {
                    EnsurePathInside(currentPath, compareRoot);
                }
            }
        }

        private static void ValidateNoConflictingCloneDiffPairs(List<Dictionary<string, string>> blockRows)
        {
            List<Dictionary<string, string>> added = (blockRows ?? new List<Dictionary<string, string>>())
                .Where(row => EqualsIgnoreCase(GetCsvValue(row, "Status"), "added"))
                .ToList();
            List<Dictionary<string, string>> removed = (blockRows ?? new List<Dictionary<string, string>>())
                .Where(row => EqualsIgnoreCase(GetCsvValue(row, "Status"), "removed"))
                .ToList();

            foreach (Dictionary<string, string> addedRow in added)
            {
                BlockKey currentKey = new BlockKey(
                    FirstNonEmpty(GetCsvValue(addedRow, "CurrentSoftwarePath"), GetCsvValue(addedRow, "SoftwarePath")),
                    FirstNonEmpty(GetCsvValue(addedRow, "CurrentNumberSpace"), GetCsvValue(addedRow, "NumberSpace")),
                    FirstNonEmpty(GetCsvValue(addedRow, "CurrentNumber"), GetCsvValue(addedRow, "Number")),
                    FirstNonEmpty(GetCsvValue(addedRow, "CurrentName"), GetCsvValue(addedRow, "Name")));
                string currentRelativePath = GetCsvValue(addedRow, "CurrentRelativePath");

                foreach (Dictionary<string, string> removedRow in removed)
                {
                    BlockKey cloneKey = new BlockKey(
                        FirstNonEmpty(GetCsvValue(removedRow, "CloneSoftwarePath"), GetCsvValue(removedRow, "SoftwarePath")),
                        FirstNonEmpty(GetCsvValue(removedRow, "CloneNumberSpace"), GetCsvValue(removedRow, "NumberSpace")),
                        FirstNonEmpty(GetCsvValue(removedRow, "CloneNumber"), GetCsvValue(removedRow, "Number")),
                        FirstNonEmpty(GetCsvValue(removedRow, "CloneName"), GetCsvValue(removedRow, "Name")));
                    string cloneRelativePath = GetCsvValue(removedRow, "CloneRelativePath");
                    bool relativePathMatch = !string.IsNullOrWhiteSpace(currentRelativePath)
                        && EqualsIgnoreCase(currentRelativePath, cloneRelativePath);
                    if (relativePathMatch || currentKey.CouldBeSameBlockAs(cloneKey))
                    {
                        throw new InvalidDataException(
                            "Clone-check bundle contains conflicting added/removed rows that may identify the same block. "
                            + "Repair the colliding clone path, softwarePath sidecar, or plc-blocks.csv, then run check-clone again. Identity: "
                            + FirstNonEmpty(currentKey.Name, cloneKey.Name, currentRelativePath, cloneRelativePath, "unknown"));
                    }
                }
            }
        }

        private static void ValidateNoConflictingClonePhysicalPaths(string outDir, string compareDirectory, List<Dictionary<string, string>> blockRows)
        {
            string rootDir = Path.Combine(Path.GetFullPath(outDir), "_root");
            string compareRoot = Path.Combine(compareDirectory, "_root");
            Dictionary<string, string> pathOwners = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            int rowIndex = 0;

            foreach (Dictionary<string, string> row in blockRows ?? new List<Dictionary<string, string>>())
            {
                rowIndex++;
                string status = GetCsvValue(row, "Status");
                string clonePath = GetCsvValue(row, "ClonePath");
                string currentPath = GetCsvValue(row, "CurrentPath");
                List<string> touchedPaths = new List<string>();

                if (EqualsIgnoreCase(status, "removed"))
                {
                    touchedPaths.Add(clonePath);
                }
                else if (!EqualsIgnoreCase(status, "export-error") && !IsSourceBlockedStatus(status))
                {
                    string destinationPath = DetermineSyncDestinationPath(status, clonePath, currentPath, compareRoot, rootDir);
                    touchedPaths.Add(destinationPath);
                    if ((EqualsIgnoreCase(status, "moved-or-renamed") || EqualsIgnoreCase(status, "moved-or-renamed-and-changed"))
                        && !EqualsIgnoreCase(clonePath, destinationPath))
                    {
                        touchedPaths.Add(clonePath);
                    }
                }

                string owner = "row " + rowIndex.ToString(CultureInfo.InvariantCulture)
                    + " (" + FirstNonEmpty(status, "unknown-status")
                    + ", " + FirstNonEmpty(GetCsvValue(row, "Name"), "unknown-block")
                    + ", " + FirstNonEmpty(GetCsvValue(row, "SoftwarePath"), GetCsvValue(row, "CurrentSoftwarePath"), GetCsvValue(row, "CloneSoftwarePath"), "unscoped") + ")";
                foreach (string path in touchedPaths
                    .Where(x => !string.IsNullOrWhiteSpace(x))
                    .Select(Path.GetFullPath)
                    .Distinct(StringComparer.OrdinalIgnoreCase))
                {
                    string previousOwner;
                    if (pathOwners.TryGetValue(path, out previousOwner))
                    {
                        throw new InvalidDataException(
                            "Clone-check bundle contains multiple block rows that touch the same physical _root path regardless of SoftwarePath: "
                            + path + ". Conflicting rows: " + previousOwner + " and " + owner + ".");
                    }

                    pathOwners[path] = owner;
                }
            }
        }

        private static List<RemovedCloneRef> RemovedCloneRefsFromDiffs(List<CloneDiffRecord> blockDiffs)
        {
            return blockDiffs
                .Where(d => d != null && EqualsIgnoreCase(d.Status, "removed"))
                .Select(d => new RemovedCloneRef
                {
                    Key = new BlockKey(
                        FirstNonEmpty(d.CloneSoftwarePath, d.SoftwarePath),
                        FirstNonEmpty(d.CloneNumberSpace, d.NumberSpace),
                        FirstNonEmpty(d.CloneNumber, d.Number),
                        FirstNonEmpty(d.CloneName, d.Name)),
                    ExplicitNewLocalSource = EqualsIgnoreCase(d.CloneProvenance, "explicit-new-local-source"),
                })
                .ToList();
        }

        private static void WriteCloneCheckSourceBlockerReport(string path, List<CloneDiffRecord> blockDiffs)
        {
            WriteCloneCheckSourceBlockerReport(path, blockDiffs, CloneCheckBundleSchemaVersion, Guid.NewGuid().ToString("N"));
        }

        private static void WriteCloneCheckSourceBlockerReport(string path, List<CloneDiffRecord> blockDiffs, string schemaVersion, string checkRunId)
        {
            List<RemovedCloneRef> removedCloneKeys = RemovedCloneRefsFromDiffs(blockDiffs);

            WriteCsv(path,
                new[] { "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Severity", "Code", "Status", "GroupPath", "Name", "NumberSpace", "Number", "CloneLanguage", "CurrentLanguage", "ClonePath", "CurrentPath", "Action", "Message" },
                blockDiffs
                    .Where(IsSourceEvidenceBlockerDiff)
                    .OrderBy(x => x.GroupPath)
                    .ThenBy(x => SafeInt(x.Number))
                    .ThenBy(x => x.Name)
                    .Select(x => new[]
                    {
                        schemaVersion,
                        checkRunId,
                        FirstNonEmpty(x.CurrentSoftwarePath, x.SoftwarePath),
                        IsCloneCorrelationAmbiguityStatus(x.Status)
                            || SourceBlockedStatusBlocksWrite(
                                x.Status,
                                new BlockKey(
                                    FirstNonEmpty(x.CurrentSoftwarePath, x.SoftwarePath),
                                    FirstNonEmpty(x.CurrentNumberSpace, x.NumberSpace),
                                    FirstNonEmpty(x.CurrentNumber, x.Number),
                                    FirstNonEmpty(x.CurrentName, x.Name)),
                                removedCloneKeys) ? "error" : "warning",
                        SourceBlockerCode(x),
                        x.Status,
                        x.GroupPath,
                        x.Name,
                        x.NumberSpace,
                        x.Number,
                        x.CloneProgrammingLanguage,
                        x.CurrentProgrammingLanguage,
                        x.ClonePath,
                        x.CurrentPath,
                        SourceBlockerAction(x),
                        x.Message
                    }));
        }

        private static bool IsSourceBlockedDiff(CloneDiffRecord diff)
        {
            return diff != null && IsSourceBlockedStatus(diff.Status);
        }

        private static bool IsSourceEvidenceBlockerDiff(CloneDiffRecord diff)
        {
            return diff != null
                && (IsSourceBlockedStatus(diff.Status)
                    || (IsCloneCorrelationAmbiguityStatus(diff.Status)
                        && !EqualsIgnoreCase(diff.CurrentExportStatus, "ok")));
        }

        private static bool IsCloneCorrelationAmbiguityStatus(string status)
        {
            return EqualsIgnoreCase(status, "ambiguous-object-correlation")
                || EqualsIgnoreCase(status, "ambiguous-rename-and-renumber");
        }

        private static int BlockingSourceBlockedDiffCount(List<CloneDiffRecord> blockDiffs)
        {
            if (blockDiffs == null)
            {
                return 0;
            }

            List<RemovedCloneRef> removed = RemovedCloneRefsFromDiffs(blockDiffs);
            return blockDiffs.Count(d => IsSourceEvidenceBlockerDiff(d)
                && (IsCloneCorrelationAmbiguityStatus(d.Status)
                    || SourceBlockedStatusBlocksWrite(
                        d.Status,
                        new BlockKey(
                            FirstNonEmpty(d.CurrentSoftwarePath, d.SoftwarePath),
                            FirstNonEmpty(d.CurrentNumberSpace, d.NumberSpace),
                            FirstNonEmpty(d.CurrentNumber, d.Number),
                            FirstNonEmpty(d.CurrentName, d.Name)),
                        removed)));
        }

        private static bool IsSourceBlockedStatus(string status)
        {
            return !string.IsNullOrWhiteSpace(status)
                && status.StartsWith("source-blocked-", StringComparison.OrdinalIgnoreCase);
        }

        // ---- source-blocker write classification: single source of truth ------
        //
        // A "source-blocked-*" clone-check row blocks apply-clone / sync-clone
        // writes UNLESS it is a pre-existing visual / fail-safe block that the
        // source clone genuinely never tracked and that no pending clone
        // operation could refer to. Every pre-write gate, the after-write
        // verification, the formatting-reconciliation pass, `status` / `check-all`,
        // `init-workspace`, and the dedicated report use the helpers below so
        // their verdicts cannot disagree.
        //
        // Fail closed: only "source-blocked-current-only" is ever a candidate for
        // "informational". "source-blocked-language-converted",
        // "source-blocked-export-error", and any future / unknown
        // "source-blocked-*" status always block.
        //
        // "Never tracked" is NOT proven by `clone == null` alone: a once-tracked
        // block can lose its clone match after a path/name/number change. A
        // "source-blocked-current-only" row is treated as informational only when
        // BOTH hold:
        //   1. no "removed" clone row could be the same block by number or name, AND
        //   2. no "removed" clone row without the exact durable
        //      explicit-new-local-source origin shares or has unknown block
        //      number space.
        // (2) fails closed on the ambiguous case where a tracked block changed
        // both name and number before conversion, or where manifest provenance
        // was lost. Only an exact sidecar sourceOrigin opt-in proves a source is
        // genuinely new local input.

        private struct BlockKey
        {
            public string SoftwarePath;
            public string NumberSpace;
            public string Number;
            public string Name;

            public BlockKey(string softwarePath, string numberSpace, string number, string name)
            {
                SoftwarePath = EmptyIfNull(softwarePath).Trim();
                NumberSpace = EmptyIfNull(numberSpace).Trim();
                Number = EmptyIfNull(number).Trim();
                Name = EmptyIfNull(name).Trim();
            }

            public bool CouldBeSameBlockAs(BlockKey other)
            {
                if (!SoftwarePathsCouldOverlap(SoftwarePath, other.SoftwarePath))
                {
                    return false;
                }

                bool numberMatch = NumberSpace.Length > 0 && Number.Length > 0
                    && EqualsIgnoreCase(NumberSpace, other.NumberSpace)
                    && EqualsIgnoreCase(Number, other.Number);
                bool nameMatch = Name.Length > 0 && EqualsIgnoreCase(Name, other.Name);
                return numberMatch || nameMatch;
            }
        }

        private struct RemovedCloneRef
        {
            public BlockKey Key;
            public bool ExplicitNewLocalSource;
        }

        private static bool SoftwarePathsCouldOverlap(string first, string second)
        {
            return string.IsNullOrWhiteSpace(first)
                || string.IsNullOrWhiteSpace(second)
                || EqualsIgnoreCase(first, second);
        }

        private static bool NumberSpacesCouldOverlap(string first, string second)
        {
            return !IsKnownBlockNumberSpace(first)
                || !IsKnownBlockNumberSpace(second)
                || EqualsIgnoreCase(first, second);
        }

        private static bool IsKnownBlockNumberSpace(string value)
        {
            return EqualsIgnoreCase(value, "OB")
                || EqualsIgnoreCase(value, "FB")
                || EqualsIgnoreCase(value, "FC")
                || EqualsIgnoreCase(value, "DB");
        }

        private static bool IsInformationalSourceBlockedCandidate(string status)
        {
            return EqualsIgnoreCase(status, "source-blocked-current-only");
        }

        private static List<RemovedCloneRef> RemovedCloneRefs(List<Dictionary<string, string>> blockRows)
        {
            List<RemovedCloneRef> refs = new List<RemovedCloneRef>();
            if (blockRows == null)
            {
                return refs;
            }

            foreach (Dictionary<string, string> row in blockRows)
            {
                if (!EqualsIgnoreCase(GetCsvValue(row, "Status"), "removed"))
                {
                    continue;
                }

                string provenance = GetCsvValue(row, "CloneProvenance");
                refs.Add(new RemovedCloneRef
                {
                    Key = new BlockKey(
                        FirstNonEmpty(GetCsvValue(row, "CloneSoftwarePath"), GetCsvValue(row, "SoftwarePath")),
                        FirstNonEmpty(GetCsvValue(row, "CloneNumberSpace"), GetCsvValue(row, "NumberSpace")),
                        FirstNonEmpty(GetCsvValue(row, "CloneNumber"), GetCsvValue(row, "Number")),
                        FirstNonEmpty(GetCsvValue(row, "CloneName"), GetCsvValue(row, "Name"))),
                    // Unknown/blank/legacy provenance fails closed.
                    ExplicitNewLocalSource = EqualsIgnoreCase(provenance, "explicit-new-local-source"),
                });
            }

            return refs;
        }

        private static bool SourceBlockedStatusBlocksWrite(string status, BlockKey liveKey, List<RemovedCloneRef> removed)
        {
            if (!IsSourceBlockedStatus(status))
            {
                return false;
            }

            if (!IsInformationalSourceBlockedCandidate(status))
            {
                return true;
            }

            if (removed != null)
            {
                foreach (RemovedCloneRef r in removed)
                {
                    if (liveKey.CouldBeSameBlockAs(r.Key))
                    {
                        return true;
                    }

                    if (!r.ExplicitNewLocalSource
                        && SoftwarePathsCouldOverlap(liveKey.SoftwarePath, r.Key.SoftwarePath)
                        && NumberSpacesCouldOverlap(liveKey.NumberSpace, r.Key.NumberSpace))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private static List<Dictionary<string, string>> BlockingSourceBlockedRows(List<Dictionary<string, string>> blockRows)
        {
            List<Dictionary<string, string>> blocking = new List<Dictionary<string, string>>();
            if (blockRows == null)
            {
                return blocking;
            }

            List<RemovedCloneRef> removed = RemovedCloneRefs(blockRows);
            foreach (Dictionary<string, string> row in blockRows)
            {
                string status = GetCsvValue(row, "Status");
                if (!IsSourceBlockedStatus(status))
                {
                    continue;
                }

                BlockKey liveKey = new BlockKey(
                    FirstNonEmpty(GetCsvValue(row, "CurrentSoftwarePath"), GetCsvValue(row, "SoftwarePath")),
                    FirstNonEmpty(GetCsvValue(row, "CurrentNumberSpace"), GetCsvValue(row, "NumberSpace")),
                    FirstNonEmpty(GetCsvValue(row, "CurrentNumber"), GetCsvValue(row, "Number")),
                    FirstNonEmpty(GetCsvValue(row, "CurrentName"), GetCsvValue(row, "Name")));
                if (SourceBlockedStatusBlocksWrite(status, liveKey, removed))
                {
                    blocking.Add(row);
                }
            }

            return blocking;
        }

        // The dedicated clone-check-source-blockers.csv report is committed in
        // the same validated evidence bundle as clone-check-blocks.csv and carries a
        // Severity column ("error" for blocking rows). We recompute from the full
        // block report AND cross-check the dedicated report, then fail closed on
        // any disagreement, so a partial or stale main report cannot hide a real
        // blocker.
        private static bool DedicatedSourceBlockerRowBlocksWrite(Dictionary<string, string> row)
        {
            if (row == null)
            {
                return true;
            }

            string status = GetCsvValue(row, "Status");
            string severity = GetCsvValue(row, "Severity");
            if (!IsSourceBlockedStatus(status))
            {
                return true;
            }

            if (EqualsIgnoreCase(severity, "error"))
            {
                return true;
            }

            if (!EqualsIgnoreCase(severity, "warning"))
            {
                // Blank, missing, or unknown severity is malformed evidence.
                return true;
            }

            // Only current-only visual blocks may be informational warnings.
            if (!IsInformationalSourceBlockedCandidate(status))
            {
                return true;
            }

            string softwarePath = FirstNonEmpty(GetCsvValue(row, "CurrentSoftwarePath"), GetCsvValue(row, "SoftwarePath"));
            string name = FirstNonEmpty(GetCsvValue(row, "CurrentName"), GetCsvValue(row, "Name"));
            string numberSpace = FirstNonEmpty(GetCsvValue(row, "CurrentNumberSpace"), GetCsvValue(row, "NumberSpace"));
            string number = FirstNonEmpty(GetCsvValue(row, "CurrentNumber"), GetCsvValue(row, "Number"));
            bool hasIdentity = !string.IsNullOrWhiteSpace(softwarePath)
                && (!string.IsNullOrWhiteSpace(name)
                    || (!string.IsNullOrWhiteSpace(numberSpace) && !string.IsNullOrWhiteSpace(number)));
            return !hasIdentity;
        }

        private static int DedicatedReportBlockerCount(List<Dictionary<string, string>> sourceBlockerRows)
        {
            if (sourceBlockerRows == null || sourceBlockerRows.Count == 0)
            {
                return 0;
            }

            return sourceBlockerRows.Count(DedicatedSourceBlockerRowBlocksWrite);
        }

        private static int BlockingSourceBlockerCount(
            List<Dictionary<string, string>> blockRows,
            List<Dictionary<string, string>> sourceBlockerRows)
        {
            int fromBlocks = BlockingSourceBlockedRows(blockRows).Count;
            int fromReport = DedicatedReportBlockerCount(sourceBlockerRows);
            return Math.Max(fromBlocks, fromReport);
        }

        private static int InformationalSourceBlockerCount(List<Dictionary<string, string>> blockRows)
        {
            if (blockRows == null)
            {
                return 0;
            }

            int total = blockRows.Count(x => IsSourceBlockedStatus(GetCsvValue(x, "Status")));
            return total - BlockingSourceBlockedRows(blockRows).Count;
        }

        private static string SourceBlockerCode(CloneDiffRecord diff)
        {
            if (IsCloneCorrelationAmbiguityStatus(diff.Status))
            {
                return "AMBIGUOUS_OBJECT_CORRELATION_WITHOUT_SOURCE";
            }
            if (EqualsIgnoreCase(diff.Status, "source-blocked-language-converted"))
            {
                return "UNSUPPORTED_LANGUAGE_CONVERSION";
            }

            if (EqualsIgnoreCase(diff.Status, "source-blocked-current-only"))
            {
                return "UNSUPPORTED_LANGUAGE_CURRENT_ONLY";
            }

            return "SOURCE_EXPORT_FAILED";
        }

        private static string SourceBlockerAction(CloneDiffRecord diff)
        {
            if (IsCloneCorrelationAmbiguityStatus(diff.Status))
            {
                return "Restore durable object-ID/source evidence or resolve the correlation manually in TIA, then run check-clone again. Apply and sync remain blocked.";
            }
            if (EqualsIgnoreCase(diff.Status, "source-blocked-language-converted"))
            {
                return "Convert the current TIA block back to STL/SCL, compile it, then run check-clone again. Do not run sync-clone while this blocker exists.";
            }

            if (EqualsIgnoreCase(diff.Status, "source-blocked-current-only"))
            {
                return "Convert the current TIA block to STL/SCL before adding it to the source clone workflow, or keep it outside CLONE_PROJECT.";
            }

            return "Fix the source export problem in TIA, then run check-clone again.";
        }

        private static void EnsureNoSourceBlockersForWrite(
            string commandName,
            List<Dictionary<string, string>> blockRows,
            List<Dictionary<string, string>> sourceBlockerRows)
        {
            List<Dictionary<string, string>> blockers = BlockingSourceBlockedRows(blockRows);
            int blockerCount = BlockingSourceBlockerCount(blockRows, sourceBlockerRows);
            if (blockerCount == 0)
            {
                return;
            }

            string first = blockers
                .Select(x => FirstNonEmpty(GetCsvValue(x, "CurrentName"), GetCsvValue(x, "CloneName"), GetCsvValue(x, "Name")))
                .FirstOrDefault();
            if (string.IsNullOrWhiteSpace(first) && sourceBlockerRows != null)
            {
                first = sourceBlockerRows
                    .Where(DedicatedSourceBlockerRowBlocksWrite)
                    .Select(x => FirstNonEmpty(GetCsvValue(x, "CurrentName"), GetCsvValue(x, "CloneName"), GetCsvValue(x, "Name")))
                    .FirstOrDefault();
            }

            throw new InvalidOperationException(commandName + " is blocked because the latest check-clone bundle contains " + blockerCount + " blocking or malformed source-blocker evidence row(s). First blocker: " + FirstNonEmpty(first, "unknown") + ". Cause is one of: a clone-tracked block was converted to LAD/FBD/GRAPH; an unsupported visual block participates in ambiguous object correlation; a clone-tracked block failed source export; a current-only visual block shares a number/name with a removed clone row; a tracked/unknown-orphaned block of overlapping software and known-or-unknown number space went missing while an unmatched visual block is present; or dedicated source-blocker evidence is malformed. Resolve the TIA/clone conflict or regenerate the complete bundle with check-clone. Pre-existing LAD/F_LAD blocks that were never in CLONE_PROJECT and match no pending clone operation are informational only. See CLONE_PROJECT\\clone-check-source-blockers.csv.");
        }

        private static void WriteStatusCounts(StreamWriter writer, string label, IEnumerable<string> statuses)
        {
            foreach (IGrouping<string, string> group in statuses.GroupBy(x => x).OrderBy(x => x.Key))
            {
                writer.WriteLine(label + " " + group.Key + ": " + group.Count());
            }
        }

        private static void PrintDiffCount(string label, List<CloneDiffRecord> diffs, string status)
        {
            Console.WriteLine(label + ": " + diffs.Count(x => EqualsIgnoreCase(x.Status, status)));
        }

        private static void PrintGroupDiffCount(string label, List<CloneGroupDiffRecord> diffs, string status)
        {
            Console.WriteLine(label + ": " + diffs.Count(x => EqualsIgnoreCase(x.Status, status)));
        }

        private static void SyncProjectClone(string outDir)
        {
            using (AcquireCloneWorkspaceLock(outDir, "sync-clone"))
            {
                SyncProjectCloneLocked(outDir, null);
            }
        }

        private static void SyncProjectCloneForApplyValidation(string outDir, List<ApplyPlanItem> plan)
        {
            using (AcquireCloneWorkspaceLock(outDir, "apply-clone-reconciliation"))
            {
                SyncProjectCloneLocked(outDir, plan ?? new List<ApplyPlanItem>());
            }
        }

        private static void SyncProjectCloneLocked(string outDir, List<ApplyPlanItem> restrictedApplyPlan)
        {
            string rootDir = Path.Combine(outDir, "_root");
            if (!Directory.Exists(rootDir))
            {
                throw new DirectoryNotFoundException("Clone root was not found. Run init-clone first: " + rootDir);
            }

            CloneCheckBundleEvidence bundle = LoadAndValidateCloneCheckBundle(outDir);
            string compareDir = bundle.CompareDirectory;
            string compareRootDir = Path.Combine(compareDir, "_root");
            if (!Directory.Exists(compareRootDir))
            {
                throw new DirectoryNotFoundException("Latest compare root was not found: " + compareRootDir);
            }

            string syncStamp = DateTime.Now.ToString("yyyyMMdd-HHmmss-fff");
            string backupDir = UniquePath(Path.Combine(outDir, "_sync-backups", "sync-" + syncStamp));
            string stagingDir = Path.Combine(outDir, "_sync-staging", "run-" + Guid.NewGuid().ToString("N"));
            string stagingRoot = Path.Combine(stagingDir, "_root");
            string reportPath = Path.Combine(outDir, "sync-clone-report.csv");
            List<string[]> report = new List<string[]>();
            List<Dictionary<string, string>> blockRows = bundle.BlockRows;
            List<Dictionary<string, string>> sourceBlockerRows = bundle.SourceBlockerRows;
            EnsureNoSourceBlockersForWrite("sync-clone", blockRows, sourceBlockerRows);
            EnsureSyncCloneRowsSafe(blockRows);
            EnsureSyncCloneGroupsSafe(bundle.GroupRows);
            EnsureCloneCheckCurrentSourcesUnchanged(blockRows);
            if (restrictedApplyPlan != null)
            {
                List<string> scopeIssues = ApplyCloneReconciliationScopeIssues(
                    blockRows,
                    bundle.GroupRows,
                    restrictedApplyPlan);
                if (scopeIssues.Count > 0)
                {
                    throw new InvalidOperationException(
                        "Restricted apply reconciliation rejected unexplained post-write state: "
                        + string.Join("; ", scopeIssues.Take(10).ToArray()));
                }
            }

            int updated = 0;
            int added = 0;
            int removed = 0;
            int moved = 0;
            int skipped = 0;
            int errors = 0;
            SyncStagingLease syncLease = new SyncStagingLease { DirectoryPath = stagingDir };
            SyncInputSet syncInputs = null;
            PublicationExpectedModel expectedPublication = null;
            PublicationCommitResult publicationCommit = null;

            try
            {
                Directory.CreateDirectory(stagingDir);
                WritePublicationStagingOwnerMarker(
                    Path.Combine(stagingDir, SyncStagingOwnerMarkerFileName),
                    "sync-clone",
                    bundle.CheckRunId);
                syncInputs = StageImmutableSyncInputs(outDir, bundle, stagingDir, syncLease, null);
                CopyDirectory(Path.Combine(syncInputs.WorkspaceRoot, "_root"), stagingRoot, false);
                ValidateStagedRootAgainstWorkspaceInventory(stagingRoot, bundle.WorkspaceRows);
            }
            catch (Exception ex)
            {
                errors++;
                report.Add(SyncReportRow("stage-root", "_root", rootDir, string.Empty, stagingRoot, "error", ex.GetType().Name + ": " + ex.Message));
            }

            if (errors == 0)
            {
                foreach (Dictionary<string, string> row in blockRows)
                {
                    string status = GetCsvValue(row, "Status");
                    string name = GetCsvValue(row, "Name");
                    string clonePath = GetCsvValue(row, "ClonePath");
                    string currentPath = GetCsvValue(row, "CurrentPath");
                    string immutableCurrentPath = SyncStatusUsesCurrentSource(status)
                        ? syncInputs.CurrentSourcePath(currentPath)
                        : string.Empty;
                    string destinationPath = DetermineSyncDestinationPath(status, clonePath, currentPath, compareRootDir, rootDir);
                    string stagedClonePath = string.IsNullOrWhiteSpace(clonePath) ? string.Empty : MapClonePathToAlternateRoot(clonePath, rootDir, stagingRoot);
                    string stagedDestinationPath = string.IsNullOrWhiteSpace(destinationPath) ? string.Empty : MapClonePathToAlternateRoot(destinationPath, rootDir, stagingRoot);

                    try
                    {
                        if (EqualsIgnoreCase(status, "unchanged"))
                        {
                            NormalizeStagedAcceptedSourceSidecar(stagedDestinationPath, row, stagingRoot);
                            skipped++;
                            report.Add(SyncReportRow(status, name, clonePath, currentPath, destinationPath, "skipped", "Source bytes were already in sync; any retained sidecar was normalized to the authoritative tracked identity."));
                        }
                        else if (EqualsIgnoreCase(status, "changed"))
                        {
                            CopyFileIntoStagedClone(immutableCurrentPath, stagedDestinationPath, stagingRoot, GetCsvValue(row, "CurrentSourceSha256"));
                            NormalizeStagedAcceptedSourceSidecar(stagedDestinationPath, row, stagingRoot);
                            updated++;
                            report.Add(SyncReportRow(status, name, clonePath, currentPath, destinationPath, "ok", "Staged updated clone file from latest compare snapshot."));
                        }
                        else if (EqualsIgnoreCase(status, "added"))
                        {
                            CopyFileIntoStagedClone(immutableCurrentPath, stagedDestinationPath, stagingRoot, GetCsvValue(row, "CurrentSourceSha256"));
                            NormalizeStagedAcceptedSourceSidecar(stagedDestinationPath, row, stagingRoot);
                            added++;
                            report.Add(SyncReportRow(status, name, clonePath, currentPath, destinationPath, "ok", "Staged added clone file from latest compare snapshot."));
                        }
                        else if (EqualsIgnoreCase(status, "removed"))
                        {
                            RemoveStagedCloneSourceWithSidecar(stagedClonePath, stagingRoot);
                            removed++;
                            report.Add(SyncReportRow(status, name, clonePath, currentPath, destinationPath, "ok", "Staged clone file removal; original remains recoverable in the transaction backup."));
                        }
                        else if (EqualsIgnoreCase(status, "moved-or-renamed") || EqualsIgnoreCase(status, "moved-or-renamed-and-changed"))
                        {
                            if (!EqualsIgnoreCase(Path.GetFullPath(stagedClonePath), Path.GetFullPath(stagedDestinationPath)))
                            {
                                MoveStagedCloneSidecar(stagedClonePath, stagedDestinationPath, stagingRoot);
                                RemoveStagedClonePath(stagedClonePath, stagingRoot);
                            }

                            CopyFileIntoStagedClone(immutableCurrentPath, stagedDestinationPath, stagingRoot, GetCsvValue(row, "CurrentSourceSha256"));
                            NormalizeStagedAcceptedSourceSidecar(stagedDestinationPath, row, stagingRoot);
                            moved++;
                            report.Add(SyncReportRow(status, name, clonePath, currentPath, destinationPath, "ok", "Staged moved/renamed clone file from latest compare snapshot."));
                        }
                        else if (IsSourceBlockedStatus(status))
                        {
                            skipped++;
                            report.Add(SyncReportRow(status, name, clonePath, currentPath, destinationPath, "skipped", "Skipped because this block is source-blocked."));
                        }
                        else
                        {
                            skipped++;
                            report.Add(SyncReportRow(status, name, clonePath, currentPath, destinationPath, "skipped", "Unknown check status."));
                        }
                    }
                    catch (Exception ex)
                    {
                        errors++;
                        report.Add(SyncReportRow(status, name, clonePath, currentPath, destinationPath, "error", ex.GetType().Name + ": " + ex.Message));
                    }
                }
            }

            if (errors == 0)
            {
                errors += SyncCloneGroupsStaged(bundle.GroupRows, rootDir, stagingRoot, report);
            }

            string stagedBlockManifest = Path.Combine(stagingDir, "plc-blocks.csv");
            string stagedGroupManifest = Path.Combine(stagingDir, "block-groups.csv");
            if (errors == 0)
            {
                try
                {
                    ValidateStagedSyncSourcesAndSidecars(stagingRoot, rootDir, compareRootDir, blockRows, bundle.WorkspaceRows);
                    expectedPublication = BuildPublicationExpectedModel(
                        outDir,
                        bundle,
                        stagingDir,
                        rootDir,
                        compareRootDir,
                        syncInputs);
                    WriteExpectedPublicationArtifacts(stagingDir, expectedPublication);
                    ValidateStagedSyncSourcesAndSidecars(stagingRoot, rootDir, compareRootDir, blockRows, bundle.WorkspaceRows);
                    ValidateExpectedPublicationArtifacts(stagingDir, expectedPublication);
                }
                catch (Exception ex)
                {
                    errors++;
                    report.Add(SyncReportRow("stage-manifests", "MANIFESTS", string.Empty, string.Empty, stagingDir, "error", ex.GetType().Name + ": " + ex.Message));
                }
            }

            if (errors > 0)
            {
                WriteSyncCloneReports(outDir, compareDir, backupDir, report, updated, added, removed, moved, skipped, errors, false);
                syncLease.Dispose();
                CleanupSyncStaging(stagingDir);
                throw new InvalidOperationException("sync-clone failed with " + errors.ToString(CultureInfo.InvariantCulture) + " error(s); the original _root, manifests, metadata, and authorization bundle were left unchanged.");
            }

            try
            {
                SealSyncStaging(outDir, bundle, stagingDir, rootDir, compareRootDir, expectedPublication, syncLease);
            }
            catch (Exception ex)
            {
                report.Add(SyncReportRow("staging-seal", "STAGING", stagingDir, string.Empty, stagingDir, "error", ex.GetType().Name + ": " + ex.Message));
                WriteSyncCloneReports(outDir, compareDir, backupDir, report, updated, added, removed, moved, skipped, 1, false);
                syncLease.Dispose();
                CleanupSyncStaging(stagingDir);
                throw new InvalidOperationException("sync-clone stopped before commit because immutable staging verification failed; the active baseline and authorization bundle were left unchanged.", ex);
            }

            // Close the editor race after staging: a changed active workspace
            // is never moved to backup and replaced by stale staged bytes.
            try
            {
                ValidateCloneWorkspaceInventory(outDir, bundle.WorkspaceRows);
            }
            catch (Exception ex)
            {
                report.Add(SyncReportRow("commit-guard", "WORKSPACE", rootDir, string.Empty, stagingRoot, "error", ex.GetType().Name + ": " + ex.Message));
                WriteSyncCloneReports(outDir, compareDir, backupDir, report, updated, added, removed, moved, skipped, 1, false);
                syncLease.Dispose();
                CleanupSyncStaging(stagingDir);
                throw new InvalidOperationException("sync-clone stopped before commit because the active workspace changed after staging; staged bytes were deleted and the active workspace was left untouched.", ex);
            }
            try
            {
                ValidateSealedSyncStaging(stagingDir, syncLease);
                publicationCommit = CommitStagedSyncWorkspace(outDir, stagingDir, backupDir, "sync-clone", syncLease.PackagePath, syncLease.PackageSha256, null);
            }
            catch (PublicationCommittedDiagnosticException committedDiagnostic)
            {
                publicationCommit = committedDiagnostic.CommitResult;
                report.Add(SyncReportRow(
                    "completion-diagnostic",
                    "PUBLICATION",
                    stagingDir,
                    string.Empty,
                    publicationCommit == null ? string.Empty : publicationCommit.CompletionResultPath,
                    "warning",
                    committedDiagnostic.Message));
                Console.WriteLine("WARNING: " + committedDiagnostic.Message);
            }
            catch
            {
                syncLease.Dispose();
                CleanupSyncStaging(stagingDir);
                throw;
            }
            syncLease.Dispose();
            string retainedJournalPath = Path.Combine(outDir, PublicationTransactionFileName);
            ApplyStagingCleanupResult syncCleanup = File.Exists(retainedJournalPath)
                ? new ApplyStagingCleanupResult
                {
                    Status = "retained-for-committed-journal",
                    OriginalPath = stagingDir,
                    EvidencePath = retainedJournalPath,
                    Message = "Committed journal still owns the immutable package; the next clone command will verify the committed state and clean this staging."
                }
                : CleanupSyncStaging(stagingDir);
            report.Add(SyncReportRow(
                "cleanup",
                "SYNC-STAGING",
                stagingDir,
                string.Empty,
                syncCleanup.EvidencePath,
                syncCleanup.Removed ? "ok" : "warning",
                syncCleanup.Removed
                    ? "Owned immutable sync staging and publication package were removed."
                    : "Baseline committed; recovery is not required, but local confidentiality cleanup is required. " + syncCleanup.Message));
            bool syncReportsWritten = false;
            Exception syncReportFailure;
            syncReportsWritten = TryWriteCommittedPublicationDiagnostics(
                publicationCommit,
                "sync-clone",
                delegate
                {
                    WriteSyncCloneReports(outDir, compareDir, backupDir, report, updated, added, removed, moved, skipped, errors, true);
                },
                out syncReportFailure);

            Console.WriteLine("Clone sync completed.");
            Console.WriteLine("Clone directory: " + outDir);
            Console.WriteLine("Latest compare snapshot: " + compareDir);
            Console.WriteLine("Backup directory: " + backupDir);
            Console.WriteLine("Updated files: " + updated);
            Console.WriteLine("Added files: " + added);
            Console.WriteLine("Removed files: " + removed);
            Console.WriteLine("Moved/renamed files: " + moved);
            Console.WriteLine("Skipped files: " + skipped);
            Console.WriteLine("Errors: " + errors);
            if (!syncCleanup.Removed)
            {
                Console.WriteLine("WARNING: sync staging cleanup is deferred or requires local attention: " + syncCleanup.Message + " Path: " + syncCleanup.EvidencePath);
            }
            if (syncReportsWritten)
            {
                Console.WriteLine("Sync report written to: " + reportPath);
                Console.WriteLine("Summary written to: " + Path.Combine(outDir, "sync-clone-summary.txt"));
            }
        }

        private static string[] SyncReportRow(string checkStatus, string name, string clonePath, string currentPath, string destinationPath, string syncStatus, string message)
        {
            return new[] { checkStatus, name, clonePath, currentPath, destinationPath, syncStatus, message };
        }

        private static void CopyFileIntoStagedClone(string sourcePath, string destinationPath, string stagingRoot)
        {
            CopyFileIntoStagedClone(sourcePath, destinationPath, stagingRoot, string.Empty);
        }

        private static void CopyFileIntoStagedClone(string sourcePath, string destinationPath, string stagingRoot, string expectedSha256)
        {
            if (string.IsNullOrWhiteSpace(sourcePath) || !File.Exists(sourcePath))
            {
                throw new FileNotFoundException("Current compare file was not found.", sourcePath);
            }

            if (string.IsNullOrWhiteSpace(destinationPath))
            {
                throw new InvalidOperationException("Staged destination path is empty.");
            }

            EnsurePathInside(destinationPath, stagingRoot);
            if (Directory.Exists(destinationPath))
            {
                throw new IOException("Staged destination is an existing directory: " + destinationPath);
            }

            Directory.CreateDirectory(Path.GetDirectoryName(destinationPath));
            File.Copy(sourcePath, destinationPath, true);
            if (!string.IsNullOrWhiteSpace(expectedSha256)
                && !EqualsIgnoreCase(ComputeFileSha256(destinationPath), expectedSha256))
            {
                throw new InvalidDataException("Staged sync source does not match the authoritative current-source hash: " + destinationPath);
            }
        }

        private static void RemoveStagedClonePath(string path, string stagingRoot)
        {
            if (string.IsNullOrWhiteSpace(path))
            {
                return;
            }

            EnsurePathInside(path, stagingRoot);
            string fullRoot = Path.GetFullPath(stagingRoot).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            string fullPath = Path.GetFullPath(path).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            if (EqualsIgnoreCase(fullPath, fullRoot))
            {
                throw new InvalidOperationException("Refusing to remove the staged clone root itself.");
            }

            if (File.Exists(fullPath))
            {
                File.Delete(fullPath);
            }
            else if (Directory.Exists(fullPath))
            {
                Directory.Delete(fullPath, true);
            }
        }

        private static void RemoveStagedCloneSourceWithSidecar(string sourcePath, string stagingRoot)
        {
            RemoveStagedClonePath(sourcePath, stagingRoot);
            if (!string.IsNullOrWhiteSpace(sourcePath))
            {
                RemoveStagedClonePath(sourcePath + ".meta.json", stagingRoot);
            }
        }

        private static void MoveStagedCloneSidecar(string sourcePath, string destinationPath, string stagingRoot)
        {
            if (string.IsNullOrWhiteSpace(sourcePath) || string.IsNullOrWhiteSpace(destinationPath))
            {
                return;
            }

            string sourceSidecar = sourcePath + ".meta.json";
            string destinationSidecar = destinationPath + ".meta.json";
            EnsurePathInside(sourceSidecar, stagingRoot);
            EnsurePathInside(destinationSidecar, stagingRoot);
            if (!File.Exists(sourceSidecar) || EqualsIgnoreCase(Path.GetFullPath(sourceSidecar), Path.GetFullPath(destinationSidecar)))
            {
                return;
            }

            if (File.Exists(destinationSidecar) || Directory.Exists(destinationSidecar))
            {
                throw new IOException("Cannot move clone sidecar because the destination already exists: " + destinationSidecar);
            }

            Directory.CreateDirectory(Path.GetDirectoryName(destinationSidecar));
            File.Move(sourceSidecar, destinationSidecar);
        }

        private static void NormalizeStagedAcceptedSourceSidecar(
            string destinationPath,
            Dictionary<string, string> row,
            string stagingRoot)
        {
            if (string.IsNullOrWhiteSpace(destinationPath))
            {
                return;
            }

            string sidecarPath = destinationPath + ".meta.json";
            EnsurePathInside(sidecarPath, stagingRoot);
            if (Directory.Exists(sidecarPath))
            {
                throw new IOException("Clone source sidecar destination is a directory: " + sidecarPath);
            }
            if (!File.Exists(sidecarPath))
            {
                return;
            }

            Dictionary<string, string> sidecar = ParseStrictFlatJsonObject(
                File.ReadAllText(sidecarPath, Encoding.UTF8),
                sidecarPath);
            string origin = SidecarValue(sidecar, "sourceOrigin");
            if (!EqualsIgnoreCase(origin, "tracked-baseline")
                && !EqualsIgnoreCase(origin, "explicit-new-local-source"))
            {
                throw new InvalidDataException(
                    "Accepted TIA source has an unrecognized stale destination sidecar provenance: "
                    + sidecarPath);
            }

            sidecar["sourceOrigin"] = "tracked-baseline";
            string softwarePath = FirstNonEmpty(
                GetCsvValue(row, "CurrentSoftwarePath"),
                GetCsvValue(row, "CloneSoftwarePath"),
                GetCsvValue(row, "SoftwarePath"));
            string number = FirstNonEmpty(
                GetCsvValue(row, "CurrentNumber"),
                GetCsvValue(row, "CloneNumber"),
                GetCsvValue(row, "Number"));
            string name = FirstNonEmpty(
                GetCsvValue(row, "CurrentName"),
                GetCsvValue(row, "CloneName"),
                GetCsvValue(row, "Name"));
            string language = FirstNonEmpty(
                GetCsvValue(row, "CurrentProgrammingLanguage"),
                GetCsvValue(row, "CloneProgrammingLanguage"),
                GetCsvValue(row, "ProgrammingLanguage"));
            if (!string.IsNullOrWhiteSpace(softwarePath)) sidecar["softwarePath"] = softwarePath;
            if (!string.IsNullOrWhiteSpace(name)) sidecar["name"] = name;
            if (!string.IsNullOrWhiteSpace(number)) sidecar["number"] = number;
            if (!string.IsNullOrWhiteSpace(language)) sidecar["programmingLanguage"] = language;
            WriteFlatJsonObjectAtomically(sidecarPath, sidecar);
        }

        private static void EnsureSyncCloneRowsSafe(List<Dictionary<string, string>> rows)
        {
            List<string> invalid = new List<string>();
            foreach (Dictionary<string, string> row in rows ?? new List<Dictionary<string, string>>())
            {
                string status = GetCsvValue(row, "Status");
                bool known = EqualsIgnoreCase(status, "unchanged")
                    || EqualsIgnoreCase(status, "changed")
                    || EqualsIgnoreCase(status, "added")
                    || EqualsIgnoreCase(status, "removed")
                    || EqualsIgnoreCase(status, "moved-or-renamed")
                    || EqualsIgnoreCase(status, "moved-or-renamed-and-changed")
                    || IsSourceBlockedStatus(status);
                if (EqualsIgnoreCase(status, "export-error") || !known)
                {
                    invalid.Add(FirstNonEmpty(GetCsvValue(row, "CurrentName"), GetCsvValue(row, "Name"), "<unknown>") + ":" + FirstNonEmpty(status, "<blank>"));
                }
            }

            if (invalid.Count > 0)
            {
                throw new InvalidOperationException(
                    "sync-clone is blocked because current TIA export evidence contains an error or unknown state: "
                    + string.Join(", ", invalid.ToArray()) + ". Run check-clone again after resolving every export failure.");
            }
        }

        private static void EnsureSyncCloneGroupsSafe(List<Dictionary<string, string>> rows)
        {
            List<string> invalid = (rows ?? new List<Dictionary<string, string>>())
                .Where(row => !EqualsIgnoreCase(GetCsvValue(row, "Status"), "unchanged")
                    && !EqualsIgnoreCase(GetCsvValue(row, "Status"), "added")
                    && !EqualsIgnoreCase(GetCsvValue(row, "Status"), "removed"))
                .Select(row => FirstNonEmpty(RowGroupPathKey(row, "GroupPath"), "_root")
                    + ":" + FirstNonEmpty(GetCsvValue(row, "Status"), "<blank>"))
                .ToList();
            if (invalid.Count > 0)
            {
                throw new InvalidOperationException(
                    "sync-clone is blocked because the group report contains an unknown or malformed state: "
                    + string.Join(", ", invalid.ToArray()) + ".");
            }
        }

        private static int SyncCloneGroupsStaged(List<Dictionary<string, string>> groupRows, string rootDir, string stagingRoot, List<string[]> report)
        {
            int errors = 0;
            foreach (Dictionary<string, string> row in groupRows ?? new List<Dictionary<string, string>>())
            {
                string status = GetCsvValue(row, "Status");
                string groupPath = RowGroupPathKey(row, "GroupPath");
                string directory = GetCsvValue(row, "CloneDirectory");
                if (string.IsNullOrWhiteSpace(directory))
                {
                    directory = CloneDirectoryForBlockGroup(rootDir, groupPath);
                }

                string stagedDirectory = MapClonePathToAlternateRoot(directory, rootDir, stagingRoot);
                try
                {
                    if (EqualsIgnoreCase(status, "added") || EqualsIgnoreCase(status, "unchanged"))
                    {
                        Directory.CreateDirectory(stagedDirectory);
                        if (EqualsIgnoreCase(status, "added"))
                        {
                            report.Add(SyncReportRow("group-added", "GROUP:" + groupPath, directory, string.Empty, directory, "ok", "Staged clone group directory creation."));
                        }
                    }
                    else if (EqualsIgnoreCase(status, "removed"))
                    {
                        RemoveStagedClonePath(stagedDirectory, stagingRoot);
                        report.Add(SyncReportRow("group-removed", "GROUP:" + groupPath, directory, string.Empty, directory, "ok", "Staged clone group directory removal."));
                    }
                }
                catch (Exception ex)
                {
                    errors++;
                    report.Add(SyncReportRow("group-" + status, "GROUP:" + groupPath, directory, string.Empty, directory, "error", ex.GetType().Name + ": " + ex.Message));
                }
            }

            return errors;
        }

        private static void WriteSyncCloneReports(
            string outDir,
            string compareDir,
            string backupDir,
            List<string[]> report,
            int updated,
            int added,
            int removed,
            int moved,
            int skipped,
            int errors,
            bool completed)
        {
            WriteCsv(
                Path.Combine(outDir, "sync-clone-report.csv"),
                new[] { "CheckStatus", "Name", "ClonePath", "CurrentPath", "DestinationPath", "SyncStatus", "Message" },
                report);

            using (StreamWriter writer = NewUtf8Writer(Path.Combine(outDir, "sync-clone-summary.txt")))
            {
                writer.WriteLine("Project clone sync " + (completed ? "completed" : "failed") + " at: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
                writer.WriteLine("Clone directory: " + outDir);
                writer.WriteLine("Latest compare snapshot: " + compareDir);
                writer.WriteLine("Backup directory: " + (completed ? backupDir : "not created"));
                writer.WriteLine("Baseline published: " + completed);
                writer.WriteLine();
                writer.WriteLine("Updated files: " + updated);
                writer.WriteLine("Added files: " + added);
                writer.WriteLine("Removed files: " + removed);
                writer.WriteLine("Moved/renamed files: " + moved);
                writer.WriteLine("Skipped files: " + skipped);
                writer.WriteLine("Errors: " + errors);
            }
        }

        private static SyncInputSet StageImmutableSyncInputs(
            string outDir,
            CloneCheckBundleEvidence bundle,
            string stagingDir,
            SyncStagingLease lease,
            Action<string> testHook)
        {
            string inputRoot = Path.Combine(stagingDir, "_inputs");
            string workspaceInputRoot = Path.Combine(inputRoot, "workspace");
            string currentInputRoot = Path.Combine(inputRoot, "current");
            SyncInputSet result = new SyncInputSet { WorkspaceRoot = workspaceInputRoot };
            int inputIndex = 0;
            Directory.CreateDirectory(Path.Combine(workspaceInputRoot, "_root"));

            foreach (Dictionary<string, string> row in bundle.WorkspaceRows ?? new List<Dictionary<string, string>>())
            {
                string relativePath = NormalizeCloneWorkspaceRelativePath(GetCsvValue(row, "RelativePath"));
                string expectedHash = GetCsvValue(row, "Sha256");
                long expectedSize;
                if (string.IsNullOrWhiteSpace(relativePath)
                    || !long.TryParse(GetCsvValue(row, "Size"), NumberStyles.None, CultureInfo.InvariantCulture, out expectedSize)
                    || expectedSize < 0)
                {
                    throw new InvalidDataException("Clone workspace evidence contains an invalid immutable sync input row.");
                }
                string sourcePath = Path.Combine(outDir, relativePath.Replace('/', Path.DirectorySeparatorChar));
                string inputPath = Path.Combine(workspaceInputRoot, relativePath.Replace('/', Path.DirectorySeparatorChar));
                CopyHashBoundFileToOwnedSyncInput(sourcePath, outDir, inputPath, inputRoot, expectedHash, expectedSize, lease, null, "checked workspace");
            }

            result.BlockManifestPath = Path.Combine(workspaceInputRoot, "plc-blocks.csv");
            result.GroupManifestPath = Path.Combine(workspaceInputRoot, "block-groups.csv");
            if (!File.Exists(result.BlockManifestPath) || !File.Exists(result.GroupManifestPath))
            {
                throw new InvalidDataException("Immutable sync input is missing a checked block/group manifest.");
            }

            foreach (Dictionary<string, string> row in bundle.BlockRows ?? new List<Dictionary<string, string>>())
            {
                string status = GetCsvValue(row, "Status");
                if (!SyncStatusUsesCurrentSource(status)) continue;
                string currentPath = GetCsvValue(row, "CurrentPath");
                string expectedHash = GetCsvValue(row, "CurrentSourceSha256");
                if (string.IsNullOrWhiteSpace(currentPath) || string.IsNullOrWhiteSpace(expectedHash))
                {
                    throw new InvalidDataException("Authoritative sync row lacks current-source path/hash evidence.");
                }
                string key = NormalizeComparablePath(Path.GetFullPath(currentPath));
                string existing;
                if (result.CurrentSources.TryGetValue(key, out existing))
                {
                    if (!EqualsIgnoreCase(ComputeFileSha256(existing), expectedHash))
                    {
                        throw new InvalidDataException("Conflicting authoritative hashes refer to the same current source: " + currentPath);
                    }
                    continue;
                }
                string inputPath = Path.Combine(
                    currentInputRoot,
                    inputIndex.ToString("D4", CultureInfo.InvariantCulture) + Path.GetExtension(currentPath));
                CopyHashBoundFileToOwnedSyncInput(
                    currentPath,
                    Path.Combine(bundle.CompareDirectory, "_root"),
                    inputPath,
                    inputRoot,
                    expectedHash,
                    -1,
                    lease,
                    testHook,
                    "authoritative current source");
                result.CurrentSources.Add(key, inputPath);
                inputIndex++;
            }
            return result;
        }

        private static bool SyncStatusUsesCurrentSource(string status)
        {
            return EqualsIgnoreCase(status, "changed")
                || EqualsIgnoreCase(status, "added")
                || EqualsIgnoreCase(status, "moved-or-renamed")
                || EqualsIgnoreCase(status, "moved-or-renamed-and-changed");
        }

        private static void CopyHashBoundFileToOwnedSyncInput(
            string sourcePath,
            string sourceRoot,
            string inputPath,
            string inputRoot,
            string expectedHash,
            long expectedSize,
            SyncStagingLease lease,
            Action<string> testHook,
            string label)
        {
            EnsurePathInside(sourcePath, sourceRoot);
            EnsurePathInside(inputPath, inputRoot);
            if (string.IsNullOrWhiteSpace(expectedHash))
            {
                throw new InvalidDataException("Missing hash for " + label + ": " + sourcePath);
            }
            Directory.CreateDirectory(Path.GetDirectoryName(inputPath));
            using (FileStream source = new FileStream(sourcePath, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                EnsurePathInside(sourcePath, sourceRoot);
                if (testHook != null) testHook("source-open:" + sourcePath);
                using (FileStream destination = new FileStream(inputPath, FileMode.CreateNew, FileAccess.Write, FileShare.None))
                {
                    source.CopyTo(destination);
                    destination.Flush(true);
                }
            }
            FileInfo copied = new FileInfo(inputPath);
            if ((expectedSize >= 0 && copied.Length != expectedSize)
                || !EqualsIgnoreCase(ComputeFileSha256(inputPath), expectedHash))
            {
                throw new InvalidDataException("Immutable sync input did not preserve the checked bytes for " + label + ": " + sourcePath);
            }
            lease.HoldReadLock(inputPath);
        }

        private static void ValidateStagedSyncSourcesAndSidecars(
            string stagingRoot,
            string rootDir,
            string compareRootDir,
            List<Dictionary<string, string>> blockRows,
            List<Dictionary<string, string>> workspaceRows)
        {
            Dictionary<string, string> workspaceHashes = (workspaceRows ?? new List<Dictionary<string, string>>())
                .ToDictionary(
                    row => NormalizeCloneWorkspaceRelativePath(GetCsvValue(row, "RelativePath")),
                    row => GetCsvValue(row, "Sha256"),
                    StringComparer.OrdinalIgnoreCase);
            foreach (Dictionary<string, string> row in blockRows ?? new List<Dictionary<string, string>>())
            {
                string status = GetCsvValue(row, "Status");
                if (EqualsIgnoreCase(status, "removed") || EqualsIgnoreCase(status, "export-error") || IsSourceBlockedStatus(status)) continue;
                string destination = DetermineSyncDestinationPath(status, GetCsvValue(row, "ClonePath"), GetCsvValue(row, "CurrentPath"), compareRootDir, rootDir);
                string staged = MapClonePathToAlternateRoot(destination, rootDir, stagingRoot);
                string expectedHash = SyncStatusUsesCurrentSource(status)
                    ? GetCsvValue(row, "CurrentSourceSha256")
                    : GetCsvValue(row, "CloneSourceSha256");
                if (string.IsNullOrWhiteSpace(expectedHash))
                {
                    string relative = "_root/" + NormalizeCloneWorkspaceRelativePath(MakeRelativePath(rootDir, destination));
                    workspaceHashes.TryGetValue(relative, out expectedHash);
                }
                if (!File.Exists(staged)
                    || string.IsNullOrWhiteSpace(expectedHash)
                    || !EqualsIgnoreCase(ComputeFileSha256(staged), expectedHash))
                {
                    throw new InvalidDataException("Staged sync source is not the exact source authorized by check-clone: " + staged);
                }

                string sidecarPath = staged + ".meta.json";
                if (!File.Exists(sidecarPath)) continue;
                Dictionary<string, string> sidecar = ParseStrictFlatJsonObject(File.ReadAllText(sidecarPath, Encoding.UTF8), sidecarPath);
                string expectedSoftware = FirstNonEmpty(GetCsvValue(row, "CurrentSoftwarePath"), GetCsvValue(row, "CloneSoftwarePath"), GetCsvValue(row, "SoftwarePath"));
                string expectedName = FirstNonEmpty(GetCsvValue(row, "CurrentName"), GetCsvValue(row, "CloneName"), GetCsvValue(row, "Name"));
                string expectedNumber = FirstNonEmpty(GetCsvValue(row, "CurrentNumber"), GetCsvValue(row, "CloneNumber"), GetCsvValue(row, "Number"));
                string expectedLanguage = FirstNonEmpty(GetCsvValue(row, "CurrentProgrammingLanguage"), GetCsvValue(row, "CloneProgrammingLanguage"), GetCsvValue(row, "ProgrammingLanguage"));
                if (!EqualsIgnoreCase(SidecarValue(sidecar, "sourceOrigin"), "tracked-baseline")
                    || (!string.IsNullOrWhiteSpace(expectedSoftware) && !EqualsIgnoreCase(SidecarValue(sidecar, "softwarePath"), expectedSoftware))
                    || (!string.IsNullOrWhiteSpace(expectedName) && !EqualsIgnoreCase(SidecarValue(sidecar, "name"), expectedName))
                    || (!string.IsNullOrWhiteSpace(expectedNumber) && SafeInt(SidecarValue(sidecar, "number")) != SafeInt(expectedNumber))
                    || (!string.IsNullOrWhiteSpace(expectedLanguage) && !EqualsIgnoreCase(SidecarValue(sidecar, "programmingLanguage"), expectedLanguage)))
                {
                    throw new InvalidDataException("Retained sync sidecar contradicts the authoritative tracked identity: " + sidecarPath);
                }
            }
        }

        private static void ValidateStagedSyncManifest(
            string stagingDir,
            string outDir,
            string stagingRoot,
            List<Dictionary<string, string>> blockRows)
        {
            List<Dictionary<string, string>> manifest = ReadCsv(Path.Combine(stagingDir, "plc-blocks.csv"));
            int expectedRows = (blockRows ?? new List<Dictionary<string, string>>()).Count(row =>
                !EqualsIgnoreCase(GetCsvValue(row, "Status"), "removed")
                && !EqualsIgnoreCase(GetCsvValue(row, "Status"), "export-error")
                && !IsSourceBlockedStatus(GetCsvValue(row, "Status")));
            if (manifest.Count != expectedRows)
            {
                throw new InvalidDataException("Staged sync manifest row count does not match the accepted authoritative block set.");
            }
            HashSet<string> paths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            string finalRoot = Path.Combine(outDir, "_root");
            foreach (Dictionary<string, string> row in manifest)
            {
                string finalPath = GetCsvValue(row, "FilePath");
                EnsurePathInside(finalPath, finalRoot);
                string stagedPath = MapClonePathToAlternateRoot(finalPath, finalRoot, stagingRoot);
                List<Dictionary<string, string>> identityMatches = (blockRows ?? new List<Dictionary<string, string>>())
                    .Where(candidate => !EqualsIgnoreCase(GetCsvValue(candidate, "Status"), "removed")
                        && !EqualsIgnoreCase(GetCsvValue(candidate, "Status"), "export-error")
                        && !IsSourceBlockedStatus(GetCsvValue(candidate, "Status"))
                        && EqualsIgnoreCase(GetCsvValue(candidate, "Name"), GetCsvValue(row, "Name"))
                        && SafeInt(GetCsvValue(candidate, "Number")) == SafeInt(GetCsvValue(row, "Number"))
                        && EqualsIgnoreCase(FirstNonEmpty(GetCsvValue(candidate, "NumberSpace"), BlockNumberSpace(GetCsvValue(candidate, "TypeName"), GetCsvValue(candidate, "ProgrammingLanguage"))), GetCsvValue(row, "NumberSpace"))
                        && EqualsIgnoreCase(RowGroupPathKey(candidate, "GroupPath"), RowGroupPathKey(row, "GroupPath"))
                        && EqualsIgnoreCase(FirstNonEmpty(GetCsvValue(candidate, "CurrentSoftwarePath"), GetCsvValue(candidate, "CloneSoftwarePath"), GetCsvValue(candidate, "SoftwarePath")), GetCsvValue(row, "SoftwarePath")))
                    .ToList();
                if (!paths.Add(Path.GetFullPath(stagedPath))
                    || !File.Exists(stagedPath)
                    || identityMatches.Count != 1
                    || !EqualsIgnoreCase(GetCsvValue(row, "SourceOrigin"), "exported-source")
                    || !EqualsIgnoreCase(GetCsvValue(row, "SourceSha256"), ComputeFileSha256(stagedPath))
                    || !EqualsIgnoreCase(GetCsvValue(row, "NormalizedSourceSha256"), ComputeNormalizedTextSha256(stagedPath))
                    || string.IsNullOrWhiteSpace(GetCsvValue(row, "SoftwarePath")))
                {
                    throw new InvalidDataException("Staged sync manifest does not describe the exact staged source identity/content: " + finalPath);
                }
            }
        }

        private static void ValidateStagedSyncMetadata(string stagingDir, PublicationExpectedModel model)
        {
            string metadataDir = Path.Combine(stagingDir, "_metadata");
            string schemaPath = Path.Combine(metadataDir, "schema-version.txt");
            if (!File.Exists(schemaPath) || !EqualsIgnoreCase(File.ReadAllText(schemaPath, Encoding.UTF8).Trim(), "4"))
            {
                throw new InvalidDataException("Staged sync metadata has an invalid schema marker.");
            }

            List<Dictionary<string, string>> blocks = model.BlockRows;
            List<Dictionary<string, string>> groups = model.GroupRows;
            ValidateJsonlRowsEqual(Path.Combine(metadataDir, "blocks.jsonl"), blocks.Select(NormalizeBlockMetadataRow).ToList(), "staged block metadata");
            ValidateJsonlRowsEqual(Path.Combine(metadataDir, "groups.jsonl"), groups.Select(NormalizeGroupMetadataRow).ToList(), "staged group metadata");

            string cloneManifestPath = Path.Combine(metadataDir, "clone-manifest.json");
            Dictionary<string, string> cloneManifest = ParseStrictFlatJsonObject(File.ReadAllText(cloneManifestPath, Encoding.UTF8), cloneManifestPath);
            int blockCount;
            int groupCount;
            DateTime generatedAt;
            string[] cloneManifestKeys =
            {
                "schemaVersion", "generatedAt", "cloneDirectory", "blocksCsv", "groupsCsv",
                "blocksJsonl", "groupsJsonl", "blockCount", "groupCount", "sidecarConvention"
            };
            if (cloneManifest.Count != cloneManifestKeys.Length
                || cloneManifestKeys.Any(key => !cloneManifest.ContainsKey(key))
                || !DateTime.TryParse(SidecarValue(cloneManifest, "generatedAt"), CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out generatedAt)
                || !string.Equals(SidecarValue(cloneManifest, "generatedAt"), model.MetadataGeneratedAt, StringComparison.Ordinal)
                || !int.TryParse(SidecarValue(cloneManifest, "blockCount"), NumberStyles.None, CultureInfo.InvariantCulture, out blockCount)
                || !int.TryParse(SidecarValue(cloneManifest, "groupCount"), NumberStyles.None, CultureInfo.InvariantCulture, out groupCount)
                || blockCount != blocks.Count
                || groupCount != groups.Count
                || !EqualsIgnoreCase(SidecarValue(cloneManifest, "schemaVersion"), "4")
                || !string.Equals(SidecarValue(cloneManifest, "cloneDirectory"), model.LogicalOutDir, StringComparison.Ordinal)
                || !string.Equals(SidecarValue(cloneManifest, "blocksCsv"), Path.Combine(model.LogicalOutDir, "plc-blocks.csv"), StringComparison.Ordinal)
                || !string.Equals(SidecarValue(cloneManifest, "groupsCsv"), Path.Combine(model.LogicalOutDir, "block-groups.csv"), StringComparison.Ordinal)
                || !string.Equals(SidecarValue(cloneManifest, "blocksJsonl"), Path.Combine(model.LogicalOutDir, "_metadata", "blocks.jsonl"), StringComparison.Ordinal)
                || !string.Equals(SidecarValue(cloneManifest, "groupsJsonl"), Path.Combine(model.LogicalOutDir, "_metadata", "groups.jsonl"), StringComparison.Ordinal)
                || !EqualsIgnoreCase(SidecarValue(cloneManifest, "sidecarConvention"), "<source-file>.meta.json"))
            {
                throw new InvalidDataException("Staged clone-manifest metadata contradicts the staged manifests or logical workspace paths.");
            }
        }

        private static void ValidateStagedSyncGroupManifest(
            string stagingDir,
            string outDir,
            CloneCheckBundleEvidence bundle)
        {
            List<Dictionary<string, string>> actual = ReadCsv(Path.Combine(stagingDir, "block-groups.csv"));
            List<Dictionary<string, string>> expected = (bundle.GroupRows ?? new List<Dictionary<string, string>>())
                .Where(row => !EqualsIgnoreCase(GetCsvValue(row, "Status"), "removed"))
                .ToList();
            if (actual.Count != expected.Count) throw new InvalidDataException("Staged group manifest row count contradicts the authoritative group set.");
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (Dictionary<string, string> row in actual)
            {
                string groupPath = RowGroupPathKey(row, "GroupPath");
                List<Dictionary<string, string>> matches = expected.Where(candidate => EqualsIgnoreCase(RowGroupPathKey(candidate, "GroupPath"), groupPath)).ToList();
                string directory = GetCsvValue(row, "Directory");
                if (!seen.Add(groupPath)
                    || matches.Count != 1
                    || !EqualsIgnoreCase(directory, CloneDirectoryForBlockGroup(Path.Combine(outDir, "_root"), groupPath))
                    || (bundle.SoftwarePaths != null && bundle.SoftwarePaths.Count == 1
                        && !EqualsIgnoreCase(GetCsvValue(row, "SoftwarePath"), bundle.SoftwarePaths[0])))
                {
                    throw new InvalidDataException("Staged group manifest contradicts authoritative identity/path evidence: " + groupPath);
                }
            }
        }

        private static void ValidateJsonlRowsEqual(
            string path,
            List<Dictionary<string, string>> expected,
            string label)
        {
            if (!File.Exists(path)) throw new InvalidDataException(label + " is missing: " + path);
            List<Dictionary<string, string>> actual = File.ReadAllLines(path, Encoding.UTF8)
                .Where(line => !string.IsNullOrWhiteSpace(line))
                .Select((line, index) => ParseStrictFlatJsonObject(line, path + " row " + (index + 1).ToString(CultureInfo.InvariantCulture)))
                .ToList();
            if (actual.Count != expected.Count) throw new InvalidDataException(label + " row count does not match its CSV manifest.");
            for (int i = 0; i < actual.Count; i++)
            {
                if (actual[i].Count != expected[i].Count
                    || expected[i].Any(pair => !string.Equals(SidecarValue(actual[i], pair.Key), pair.Value, StringComparison.Ordinal)))
                {
                    throw new InvalidDataException(label + " row " + (i + 1).ToString(CultureInfo.InvariantCulture) + " contradicts its CSV manifest.");
                }
            }
        }

        private static void SealSyncStaging(
            string outDir,
            CloneCheckBundleEvidence bundle,
            string stagingDir,
            string rootDir,
            string compareRootDir,
            PublicationExpectedModel expectedModel,
            SyncStagingLease lease)
        {
            if (expectedModel == null) throw new InvalidDataException("Sync publication has no immutable expected model.");
            HashSet<string> expectedFiles = new HashSet<string>(expectedModel.ExpectedFiles, StringComparer.OrdinalIgnoreCase);
            HashSet<string> expectedDirectories = new HashSet<string>(expectedModel.ExpectedDirectories, StringComparer.OrdinalIgnoreCase);
            ValidateExactSyncPublishTree(stagingDir, expectedFiles, expectedDirectories);
            foreach (string relativePath in expectedFiles.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
            {
                lease.HoldReadLock(Path.Combine(stagingDir, relativePath.Replace('/', Path.DirectorySeparatorChar)));
            }
            ValidateExactSyncPublishTree(stagingDir, expectedFiles, expectedDirectories);
            ValidateStagedSyncSourcesAndSidecars(Path.Combine(stagingDir, "_root"), rootDir, compareRootDir, bundle.BlockRows, bundle.WorkspaceRows);
            ValidateExpectedPublicationArtifacts(stagingDir, expectedModel);
            lease.ExpectedFiles = expectedFiles
                .Select(relativePath => CreateCloneWorkspaceFileRecord(
                    stagingDir,
                    Path.Combine(stagingDir, relativePath.Replace('/', Path.DirectorySeparatorChar)),
                    "publication"))
                .OrderBy(record => record.RelativePath, StringComparer.OrdinalIgnoreCase)
                .ToList();
            lease.ExpectedDirectories = expectedDirectories.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
            lease.PackagePath = Path.Combine(stagingDir, SyncPublicationPackageFileName);
            CreateSyncPublicationPackage(stagingDir, lease);
            lease.PackageSha256 = ComputeFileSha256(lease.PackagePath);
            lease.HoldReadLock(lease.PackagePath);
            ValidateSyncPublicationPackage(lease.PackagePath, lease.PackageSha256, lease.ExpectedFiles, lease.ExpectedDirectories);
            ValidateSealedSyncStaging(stagingDir, lease);
        }

        private static void SealExistingPublicationStaging(
            string stagingDir,
            CloneCheckBundleEvidence authoritativeBundle,
            PublicationExpectedModel expectedModel,
            SyncStagingLease lease)
        {
            if (authoritativeBundle == null || expectedModel == null || lease == null)
            {
                throw new InvalidDataException("Apply publication seal requires immutable authoritative evidence.");
            }
            HashSet<string> expectedFiles = new HashSet<string>(expectedModel.ExpectedFiles, StringComparer.OrdinalIgnoreCase);
            HashSet<string> expectedDirectories = new HashSet<string>(expectedModel.ExpectedDirectories, StringComparer.OrdinalIgnoreCase);
            ValidateExactSyncPublishTree(stagingDir, expectedFiles, expectedDirectories);
            foreach (string relativePath in expectedFiles.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
            {
                lease.HoldReadLock(Path.Combine(stagingDir, relativePath.Replace('/', Path.DirectorySeparatorChar)));
            }
            ValidateExactSyncPublishTree(stagingDir, expectedFiles, expectedDirectories);
            ValidateStagedSyncSourcesAndSidecars(
                Path.Combine(stagingDir, "_root"),
                expectedModel.EvidenceRootDir,
                expectedModel.CompareRootDir,
                authoritativeBundle.BlockRows,
                authoritativeBundle.WorkspaceRows);
            ValidateExpectedPublicationArtifacts(stagingDir, expectedModel);
            lease.ExpectedFiles = expectedFiles.Select(relativePath => CreateCloneWorkspaceFileRecord(
                    stagingDir,
                    Path.Combine(stagingDir, relativePath.Replace('/', Path.DirectorySeparatorChar)),
                    "publication"))
                .OrderBy(x => x.RelativePath, StringComparer.OrdinalIgnoreCase)
                .ToList();
            lease.ExpectedDirectories = expectedDirectories.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
            lease.PackagePath = Path.Combine(stagingDir, SyncPublicationPackageFileName);
            CreateSyncPublicationPackage(stagingDir, lease);
            lease.PackageSha256 = ComputeFileSha256(lease.PackagePath);
            lease.HoldReadLock(lease.PackagePath);
            ValidateSyncPublicationPackage(lease.PackagePath, lease.PackageSha256, lease.ExpectedFiles, lease.ExpectedDirectories);
            ValidateSealedSyncStaging(stagingDir, lease);
        }

        private static HashSet<string> BuildExpectedSyncPublishFiles(
            CloneCheckBundleEvidence bundle,
            string stagingDir,
            string rootDir,
            string compareRootDir)
        {
            HashSet<string> expected = new HashSet<string>(
                (bundle.WorkspaceRows ?? new List<Dictionary<string, string>>())
                    .Select(row => NormalizeCloneWorkspaceRelativePath(GetCsvValue(row, "RelativePath")))
                    .Where(path => path.StartsWith("_root/", StringComparison.OrdinalIgnoreCase)),
                StringComparer.OrdinalIgnoreCase);
            foreach (Dictionary<string, string> row in bundle.BlockRows ?? new List<Dictionary<string, string>>())
            {
                string status = GetCsvValue(row, "Status");
                string clonePath = GetCsvValue(row, "ClonePath");
                string destination = DetermineSyncDestinationPath(status, clonePath, GetCsvValue(row, "CurrentPath"), compareRootDir, rootDir);
                string cloneRelative = string.IsNullOrWhiteSpace(clonePath) ? string.Empty : "_root/" + NormalizeCloneWorkspaceRelativePath(MakeRelativePath(rootDir, clonePath));
                string destinationRelative = string.IsNullOrWhiteSpace(destination) ? string.Empty : "_root/" + NormalizeCloneWorkspaceRelativePath(MakeRelativePath(rootDir, destination));
                if (EqualsIgnoreCase(status, "removed"))
                {
                    expected.Remove(cloneRelative);
                    expected.Remove(cloneRelative + ".meta.json");
                }
                else if (SyncStatusUsesCurrentSource(status))
                {
                    bool move = EqualsIgnoreCase(status, "moved-or-renamed") || EqualsIgnoreCase(status, "moved-or-renamed-and-changed");
                    if (move && !EqualsIgnoreCase(cloneRelative, destinationRelative))
                    {
                        bool hadSidecar = expected.Remove(cloneRelative + ".meta.json");
                        expected.Remove(cloneRelative);
                        if (hadSidecar) expected.Add(destinationRelative + ".meta.json");
                    }
                    expected.Add(destinationRelative);
                }
            }
            expected.Add("plc-blocks.csv");
            expected.Add("block-groups.csv");
            expected.Add("_metadata/schema-version.txt");
            expected.Add("_metadata/blocks.jsonl");
            expected.Add("_metadata/groups.jsonl");
            expected.Add("_metadata/clone-manifest.json");
            return expected;
        }

        private static HashSet<string> BuildExpectedSyncPublishDirectories(
            CloneCheckBundleEvidence bundle,
            string stagingDir,
            HashSet<string> expectedFiles)
        {
            HashSet<string> expected = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string relativeFile in expectedFiles)
            {
                string parent = NormalizeCloneWorkspaceRelativePath(Path.GetDirectoryName(relativeFile) ?? string.Empty);
                while (!string.IsNullOrWhiteSpace(parent))
                {
                    expected.Add(parent);
                    parent = NormalizeCloneWorkspaceRelativePath(Path.GetDirectoryName(parent) ?? string.Empty);
                }
            }
            string stagingRoot = Path.Combine(stagingDir, "_root");
            foreach (Dictionary<string, string> row in bundle.GroupRows ?? new List<Dictionary<string, string>>())
            {
                if (EqualsIgnoreCase(GetCsvValue(row, "Status"), "removed")) continue;
                string groupDir = CloneDirectoryForBlockGroup(stagingRoot, RowGroupPathKey(row, "GroupPath"));
                string relative = NormalizeCloneWorkspaceRelativePath(MakeRelativePath(stagingDir, groupDir));
                while (!string.IsNullOrWhiteSpace(relative))
                {
                    expected.Add(relative);
                    relative = NormalizeCloneWorkspaceRelativePath(Path.GetDirectoryName(relative) ?? string.Empty);
                }
            }
            expected.Add("_root");
            expected.Add("_metadata");
            return expected;
        }

        private static void ValidateExactSyncPublishTree(
            string stagingDir,
            HashSet<string> expectedFiles,
            HashSet<string> expectedDirectories)
        {
            EnsureExistingTreeHasNoReparsePoints(stagingDir, "owned sync staging");
            List<string> actualFiles = new List<string>();
            foreach (string rootName in new[] { "_root", "_metadata" })
            {
                string root = Path.Combine(stagingDir, rootName);
                if (Directory.Exists(root))
                {
                    actualFiles.AddRange(Directory.GetFiles(root, "*", SearchOption.AllDirectories)
                        .Select(path => NormalizeCloneWorkspaceRelativePath(MakeRelativePath(stagingDir, path))));
                }
            }
            foreach (string manifest in new[] { "plc-blocks.csv", "block-groups.csv" })
            {
                if (File.Exists(Path.Combine(stagingDir, manifest))) actualFiles.Add(manifest);
            }
            HashSet<string> actualFileSet = new HashSet<string>(actualFiles, StringComparer.OrdinalIgnoreCase);
            if (!actualFileSet.SetEquals(expectedFiles))
            {
                string unexpected = FirstNonEmpty(actualFileSet.Except(expectedFiles, StringComparer.OrdinalIgnoreCase).FirstOrDefault(), expectedFiles.Except(actualFileSet, StringComparer.OrdinalIgnoreCase).FirstOrDefault(), "unknown");
                throw new InvalidDataException("Sync staging contains a missing or unknown publish file: " + unexpected);
            }
            HashSet<string> actualDirectories = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string rootName in new[] { "_root", "_metadata" })
            {
                string root = Path.Combine(stagingDir, rootName);
                if (!Directory.Exists(root)) continue;
                actualDirectories.Add(rootName);
                foreach (string directory in Directory.GetDirectories(root, "*", SearchOption.AllDirectories))
                {
                    actualDirectories.Add(NormalizeCloneWorkspaceRelativePath(MakeRelativePath(stagingDir, directory)));
                }
            }
            if (!actualDirectories.SetEquals(expectedDirectories))
            {
                string unexpected = FirstNonEmpty(actualDirectories.Except(expectedDirectories, StringComparer.OrdinalIgnoreCase).FirstOrDefault(), expectedDirectories.Except(actualDirectories, StringComparer.OrdinalIgnoreCase).FirstOrDefault(), "unknown");
                throw new InvalidDataException("Sync staging contains a missing or unknown publish directory: " + unexpected);
            }
        }

        private static void CreateSyncPublicationPackage(string stagingDir, SyncStagingLease lease)
        {
            if (File.Exists(lease.PackagePath)) File.Delete(lease.PackagePath);
            using (ZipArchive archive = ZipFile.Open(lease.PackagePath, ZipArchiveMode.Create))
            {
                foreach (string directory in lease.ExpectedDirectories.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
                {
                    archive.CreateEntry(NormalizeCloneWorkspaceRelativePath(directory).TrimEnd('/') + "/", CompressionLevel.NoCompression);
                }
                foreach (CloneWorkspaceFileRecord record in lease.ExpectedFiles)
                {
                    ZipArchiveEntry entry = archive.CreateEntry(record.RelativePath.Replace('\\', '/'), CompressionLevel.NoCompression);
                    using (Stream output = entry.Open())
                    using (FileStream input = new FileStream(
                        Path.Combine(stagingDir, record.RelativePath.Replace('/', Path.DirectorySeparatorChar)),
                        FileMode.Open,
                        FileAccess.Read,
                        FileShare.Read))
                    {
                        input.CopyTo(output);
                    }
                }
            }
            FlushFileToDisk(lease.PackagePath);
        }

        private static void ValidateSyncPublicationPackage(
            string packagePath,
            string expectedPackageHash,
            List<CloneWorkspaceFileRecord> expectedFiles,
            List<string> expectedDirectories)
        {
            if (!File.Exists(packagePath) || !EqualsIgnoreCase(ComputeFileSha256(packagePath), expectedPackageHash))
            {
                throw new InvalidDataException("Immutable sync publication package hash mismatch: " + packagePath);
            }
            Dictionary<string, CloneWorkspaceFileRecord> files = (expectedFiles ?? new List<CloneWorkspaceFileRecord>())
                .ToDictionary(x => NormalizeCloneWorkspaceRelativePath(x.RelativePath), StringComparer.OrdinalIgnoreCase);
            HashSet<string> directories = new HashSet<string>(
                (expectedDirectories ?? new List<string>()).Select(x => NormalizeCloneWorkspaceRelativePath(x).TrimEnd('/') + "/"),
                StringComparer.OrdinalIgnoreCase);
            using (ZipArchive archive = ZipFile.OpenRead(packagePath))
            {
                if (archive.Entries.Count != files.Count + directories.Count)
                {
                    throw new InvalidDataException("Immutable sync publication package has an unexpected entry count.");
                }
                foreach (ZipArchiveEntry entry in archive.Entries)
                {
                    string relative = NormalizeCloneWorkspaceRelativePath(entry.FullName);
                    if (entry.FullName.EndsWith("/", StringComparison.Ordinal))
                    {
                        if (!directories.Remove(relative.TrimEnd('/') + "/")) throw new InvalidDataException("Unknown directory in sync publication package: " + relative);
                        continue;
                    }
                    CloneWorkspaceFileRecord expected;
                    if (!files.TryGetValue(relative, out expected) || entry.Length != expected.Size)
                    {
                        throw new InvalidDataException("Unknown or size-mismatched file in sync publication package: " + relative);
                    }
                    using (Stream stream = entry.Open())
                    {
                        if (!EqualsIgnoreCase(ComputeStreamSha256(stream), expected.Sha256))
                        {
                            throw new InvalidDataException("Hash-mismatched file in sync publication package: " + relative);
                        }
                    }
                    files.Remove(relative);
                }
            }
            if (files.Count != 0 || directories.Count != 0) throw new InvalidDataException("Sync publication package is incomplete.");
        }

        private static string ComputeStreamSha256(Stream stream)
        {
            using (SHA256 sha = SHA256.Create())
            {
                return ToHex(sha.ComputeHash(stream));
            }
        }

        private static void ValidateSealedSyncStaging(string stagingDir, SyncStagingLease lease)
        {
            HashSet<string> expectedFiles = new HashSet<string>(lease.ExpectedFiles.Select(x => NormalizeCloneWorkspaceRelativePath(x.RelativePath)), StringComparer.OrdinalIgnoreCase);
            HashSet<string> expectedDirectories = new HashSet<string>(lease.ExpectedDirectories, StringComparer.OrdinalIgnoreCase);
            ValidateExactSyncPublishTree(stagingDir, expectedFiles, expectedDirectories);
            foreach (CloneWorkspaceFileRecord record in lease.ExpectedFiles)
            {
                string path = Path.Combine(stagingDir, record.RelativePath.Replace('/', Path.DirectorySeparatorChar));
                FileInfo file = new FileInfo(path);
                if (!file.Exists || file.Length != record.Size || !EqualsIgnoreCase(ComputeFileSha256(path), record.Sha256))
                {
                    throw new InvalidDataException("Sealed sync staging changed before commit: " + path);
                }
            }
            ValidateSyncPublicationPackage(lease.PackagePath, lease.PackageSha256, lease.ExpectedFiles, lease.ExpectedDirectories);
        }

        private static PublicationCommitResult CommitStagedSyncWorkspace(
            string outDir,
            string stagingDir,
            string backupDir,
            string operation,
            string packagePath,
            string expectedPackageSha256,
            Action<string> crashHook)
        {
            RecoverIncompletePublication(outDir);
            outDir = Path.GetFullPath(outDir);
            stagingDir = Path.GetFullPath(stagingDir);
            backupDir = Path.GetFullPath(backupDir);
            packagePath = Path.GetFullPath(packagePath);
            if (!EqualsIgnoreCase(operation, "sync-clone") && !EqualsIgnoreCase(operation, "apply-publication"))
            {
                throw new InvalidDataException("Unsupported clone publication operation: " + operation);
            }
            EnsurePathInside(stagingDir, EqualsIgnoreCase(operation, "sync-clone") ? Path.Combine(outDir, "_sync-staging") : Path.Combine(outDir, "_apply-validation"));
            EnsurePathInside(backupDir, EqualsIgnoreCase(operation, "sync-clone") ? Path.Combine(outDir, "_sync-backups") : Path.Combine(outDir, "_apply-backups"));
            EnsurePathInside(packagePath, stagingDir);
            if (!File.Exists(packagePath) || !EqualsIgnoreCase(ComputeFileSha256(packagePath), expectedPackageSha256))
            {
                throw new InvalidDataException("Publication package does not match the sealed package digest.");
            }
            ValidateSyncPublicationPackage(packagePath, expectedPackageSha256, ReadPackageFileInventory(packagePath), ReadPackageDirectories(packagePath));
            string journalPath = Path.Combine(outDir, PublicationTransactionFileName);
            string finalRoot = Path.Combine(outDir, "_root");
            string finalBlocks = Path.Combine(outDir, "plc-blocks.csv");
            string finalGroups = Path.Combine(outDir, "block-groups.csv");
            string finalMetadata = Path.Combine(outDir, "_metadata");
            string finalMarker = Path.Combine(outDir, CloneCheckBundleFileName);
            if (File.Exists(finalRoot)
                || Directory.Exists(finalBlocks)
                || Directory.Exists(finalGroups)
                || File.Exists(finalMetadata)
                || Directory.Exists(finalMarker))
            {
                throw new InvalidDataException("Clone publication destination contains a conflicting filesystem object; no transaction was started.");
            }
            string backupRoot = Path.Combine(backupDir, "_root");
            string backupBlocks = Path.Combine(backupDir, "plc-blocks.csv");
            string backupGroups = Path.Combine(backupDir, "block-groups.csv");
            string backupMetadata = Path.Combine(backupDir, "_metadata");
            string backupMarker = Path.Combine(backupDir, CloneCheckBundleFileName);
            ValidatePublicationOldStateInvariant(
                operation,
                Directory.Exists(finalRoot),
                File.Exists(finalBlocks),
                File.Exists(finalGroups),
                Directory.Exists(finalMetadata),
                File.Exists(finalMarker));
            string transactionId = Guid.NewGuid().ToString("N");
            string installationDir = Path.Combine(stagingDir, "_publication-install-" + transactionId);
            string stagingOwnerSha256 = BindPublicationStagingOwner(
                stagingDir,
                operation,
                outDir,
                transactionId,
                expectedPackageSha256);
            string completionResultPath = Path.Combine(backupDir, "publication-completion.json");
            Dictionary<string, string> journal = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                { "owner", ProductName },
                { "journalSchemaVersion", PublicationJournalSchemaVersion },
                { "workspacePath", outDir },
                { "transactionId", transactionId },
                { "operation", EmptyIfNull(operation) },
                { "state", "prepared" },
                { "updatedUtc", string.Empty },
                { "stagingDir", stagingDir },
                { "installationDir", installationDir },
                { "backupDir", backupDir },
                { "packagePath", packagePath },
                { "packageSha256", expectedPackageSha256 },
                { "stagingOwnerSha256", stagingOwnerSha256 },
                { "completionResultPath", completionResultPath },
                { "oldRootExists", Directory.Exists(finalRoot).ToString() },
                { "oldRootSha256", PublicationPathFingerprint(finalRoot, true) },
                { "oldBlocksExists", File.Exists(finalBlocks).ToString() },
                { "oldBlocksSha256", PublicationPathFingerprint(finalBlocks, false) },
                { "oldGroupsExists", File.Exists(finalGroups).ToString() },
                { "oldGroupsSha256", PublicationPathFingerprint(finalGroups, false) },
                { "oldMetadataExists", Directory.Exists(finalMetadata).ToString() },
                { "oldMetadataSha256", PublicationPathFingerprint(finalMetadata, true) },
                { "oldMarkerExists", File.Exists(finalMarker).ToString() },
                { "oldMarkerSha256", PublicationPathFingerprint(finalMarker, false) },
                { "newRootSha256", PackageComponentFingerprint(packagePath, "_root") },
                { "newBlocksSha256", PackageFileFingerprint(packagePath, "plc-blocks.csv") },
                { "newGroupsSha256", PackageFileFingerprint(packagePath, "block-groups.csv") },
                { "newMetadataSha256", PackageComponentFingerprint(packagePath, "_metadata") }
            };
            PublicationCommitResult commitResult = PublicationCommitResultFromJournal(journal);
            Directory.CreateDirectory(backupDir);
            WritePublicationCompletionResult(
                journal,
                "not_committed",
                "pending",
                "Publication transaction is prepared; no commit has been recorded.");
            WritePublicationJournal(journalPath, journal, "prepared");
            try
            {
                // Expand every byte outside the active baseline before moving
                // any old component. Interrupted extraction can only leave an
                // incomplete transaction-owned candidate, never a partial final.
                Directory.CreateDirectory(installationDir);
                PreparePublicationComponent(packagePath, "_root", true, installationDir, journalPath, journal, "root", crashHook);
                PreparePublicationComponent(packagePath, "plc-blocks.csv", false, installationDir, journalPath, journal, "blocks", crashHook);
                PreparePublicationComponent(packagePath, "block-groups.csv", false, installationDir, journalPath, journal, "groups", crashHook);
                PreparePublicationComponent(packagePath, "_metadata", true, installationDir, journalPath, journal, "metadata", crashHook);
                ValidateInstalledPublication(installationDir, journal);

                MovePublicationComponentWithJournal(finalRoot, backupRoot, true, journalPath, journal, "root-backed-up", crashHook);
                MovePublicationComponentWithJournal(finalBlocks, backupBlocks, false, journalPath, journal, "blocks-backed-up", crashHook);
                MovePublicationComponentWithJournal(finalGroups, backupGroups, false, journalPath, journal, "groups-backed-up", crashHook);
                MovePublicationComponentWithJournal(finalMetadata, backupMetadata, true, journalPath, journal, "metadata-backed-up", crashHook);
                MovePublicationComponentWithJournal(finalMarker, backupMarker, false, journalPath, journal, "marker-backed-up", crashHook);

                WritePublicationJournal(journalPath, journal, "before-root-installed");
                InstallPreparedPublicationComponent(installationDir, "_root", finalRoot, true, journal["newRootSha256"]);
                InvokePublicationCrashHook(crashHook, "root-renamed");
                WritePublicationJournal(journalPath, journal, "root-installed");
                InvokePublicationCrashHook(crashHook, "root-installed");
                WritePublicationJournal(journalPath, journal, "before-blocks-installed");
                InstallPreparedPublicationComponent(installationDir, "plc-blocks.csv", finalBlocks, false, journal["newBlocksSha256"]);
                InvokePublicationCrashHook(crashHook, "blocks-renamed");
                WritePublicationJournal(journalPath, journal, "blocks-installed");
                InvokePublicationCrashHook(crashHook, "blocks-installed");
                WritePublicationJournal(journalPath, journal, "before-groups-installed");
                InstallPreparedPublicationComponent(installationDir, "block-groups.csv", finalGroups, false, journal["newGroupsSha256"]);
                InvokePublicationCrashHook(crashHook, "groups-renamed");
                WritePublicationJournal(journalPath, journal, "groups-installed");
                InvokePublicationCrashHook(crashHook, "groups-installed");
                WritePublicationJournal(journalPath, journal, "before-metadata-installed");
                InstallPreparedPublicationComponent(installationDir, "_metadata", finalMetadata, true, journal["newMetadataSha256"]);
                InvokePublicationCrashHook(crashHook, "metadata-renamed");
                WritePublicationJournal(journalPath, journal, "metadata-installed");
                InvokePublicationCrashHook(crashHook, "metadata-installed");

                ValidateInstalledPublication(outDir, journal);
                WritePublicationJournal(journalPath, journal, "committed");
                try
                {
                    WritePublicationCompletionResult(journal, "committed", "pending", "Publication committed; optional diagnostics have not completed yet.");
                    File.Delete(journalPath);
                }
                catch (Exception diagnosticException)
                {
                    commitResult.DiagnosticFailure = diagnosticException;
                    throw new PublicationCommittedDiagnosticException(
                        "Clone publication committed; recovery is not required, but durable completion diagnostics could not be finalized. Journal: " + journalPath,
                        commitResult,
                        diagnosticException);
                }
                return commitResult;
            }
            catch (PublicationCrashSimulationException)
            {
                // Self-tests use this exception to model abrupt process death:
                // no in-memory rollback is allowed and the durable journal must
                // be sufficient for the next invocation.
                throw;
            }
            catch (PublicationCommittedDiagnosticException)
            {
                throw;
            }
            catch (Exception ex)
            {
                try
                {
                    RecoverIncompletePublication(outDir);
                }
                catch (Exception recoveryException)
                {
                    throw new InvalidOperationException(
                        "Clone workspace publication failed and durable recovery was incomplete. Follow the transaction journal at " + journalPath + ".",
                        new AggregateException(ex, recoveryException));
                }
                throw new InvalidOperationException("Clone workspace publication failed; the previous durable baseline was restored from the transaction journal.", ex);
            }
        }

        private static void MovePublicationComponentWithJournal(
            string source,
            string destination,
            bool directory,
            string journalPath,
            Dictionary<string, string> journal,
            string completedState,
            Action<string> crashHook)
        {
            WritePublicationJournal(journalPath, journal, "before-" + completedState);
            bool exists = directory ? Directory.Exists(source) : File.Exists(source);
            if (exists)
            {
                if (directory) Directory.Move(source, destination); else File.Move(source, destination);
            }
            WritePublicationJournal(journalPath, journal, completedState);
            if (exists) InvokePublicationCrashHook(crashHook, completedState);
        }

        private static void WritePublicationStagingOwnerMarker(string markerPath, string purpose, string checkRunId)
        {
            WriteFlatJsonObjectAtomically(
                markerPath,
                new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                {
                    { "owner", ProductName },
                    { "markerSchemaVersion", PublicationOwnerMarkerSchemaVersion },
                    { "purpose", EmptyIfNull(purpose) },
                    { "checkRunId", EmptyIfNull(checkRunId) }
                });
            FlushFileToDisk(markerPath);
        }

        private static string PublicationStagingOwnerMarkerPath(string stagingDir, string operation)
        {
            return Path.Combine(
                stagingDir,
                EqualsIgnoreCase(operation, "sync-clone")
                    ? SyncStagingOwnerMarkerFileName
                    : ApplyValidationOwnerMarkerFileName);
        }

        private static string BindPublicationStagingOwner(
            string stagingDir,
            string operation,
            string workspacePath,
            string transactionId,
            string packageSha256)
        {
            string markerPath = PublicationStagingOwnerMarkerPath(stagingDir, operation);
            if (!File.Exists(markerPath)) throw new InvalidDataException("Publication staging owner marker is missing: " + markerPath);
            Dictionary<string, string> marker = ParseStrictFlatJsonObject(File.ReadAllText(markerPath, Encoding.UTF8), markerPath);
            ValidateExactFlatObjectKeys(marker, new[] { "owner", "markerSchemaVersion", "purpose", "checkRunId" }, "unbound publication staging owner marker");
            if (!EqualsIgnoreCase(SidecarValue(marker, "owner"), ProductName)
                || !EqualsIgnoreCase(SidecarValue(marker, "markerSchemaVersion"), PublicationOwnerMarkerSchemaVersion)
                || !EqualsIgnoreCase(SidecarValue(marker, "purpose"), operation))
            {
                throw new InvalidDataException("Publication staging owner marker does not match the requested operation: " + markerPath);
            }
            Dictionary<string, string> bound = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                { "owner", ProductName },
                { "markerSchemaVersion", PublicationOwnerMarkerSchemaVersion },
                { "purpose", operation },
                { "checkRunId", SidecarValue(marker, "checkRunId") },
                { "state", "transaction-bound" },
                { "workspacePath", Path.GetFullPath(workspacePath) },
                { "transactionId", transactionId },
                { "packageSha256", packageSha256 }
            };
            WriteFlatJsonObjectAtomically(markerPath, bound);
            FlushFileToDisk(markerPath);
            return ComputeFileSha256(markerPath);
        }

        private static void ValidatePublicationStagingOwner(
            string stagingDir,
            string operation,
            string workspacePath,
            string transactionId,
            string packageSha256,
            string expectedMarkerSha256)
        {
            string markerPath = PublicationStagingOwnerMarkerPath(stagingDir, operation);
            if (!File.Exists(markerPath) || !EqualsIgnoreCase(ComputeFileSha256(markerPath), expectedMarkerSha256))
            {
                throw new InvalidDataException("Publication staging owner marker is missing or does not match the journal transaction.");
            }
            Dictionary<string, string> marker = ParseStrictFlatJsonObject(File.ReadAllText(markerPath, Encoding.UTF8), markerPath);
            ValidateExactFlatObjectKeys(
                marker,
                new[] { "owner", "markerSchemaVersion", "purpose", "checkRunId", "state", "workspacePath", "transactionId", "packageSha256" },
                "bound publication staging owner marker");
            if (!EqualsIgnoreCase(SidecarValue(marker, "owner"), ProductName)
                || !EqualsIgnoreCase(SidecarValue(marker, "markerSchemaVersion"), PublicationOwnerMarkerSchemaVersion)
                || !EqualsIgnoreCase(SidecarValue(marker, "purpose"), operation)
                || !EqualsIgnoreCase(SidecarValue(marker, "state"), "transaction-bound")
                || !EqualsIgnoreCase(Path.GetFullPath(SidecarValue(marker, "workspacePath")), Path.GetFullPath(workspacePath))
                || !EqualsIgnoreCase(SidecarValue(marker, "transactionId"), transactionId)
                || !EqualsIgnoreCase(SidecarValue(marker, "packageSha256"), packageSha256))
            {
                throw new InvalidDataException("Publication staging owner marker contradicts the transaction journal.");
            }
        }

        private static void ValidateExactFlatObjectKeys(Dictionary<string, string> values, IEnumerable<string> keys, string label)
        {
            HashSet<string> expected = new HashSet<string>(keys, StringComparer.OrdinalIgnoreCase);
            if (values == null || values.Count != expected.Count || values.Keys.Any(key => !expected.Contains(key)))
            {
                throw new InvalidDataException(label + " has an unexpected or missing property.");
            }
        }

        private static void ValidatePublicationOldStateInvariant(
            string operation,
            bool rootExists,
            bool blocksExists,
            bool groupsExists,
            bool metadataExists,
            bool markerExists)
        {
            if (!rootExists || !blocksExists || !groupsExists || !metadataExists)
            {
                throw new InvalidDataException(operation + " requires an existing _root, block/group manifests, and metadata before publication.");
            }
            if (EqualsIgnoreCase(operation, "sync-clone") && !markerExists)
            {
                throw new InvalidDataException("sync-clone requires the authoritative marker that it is about to consume.");
            }
            if (EqualsIgnoreCase(operation, "apply-publication") && markerExists)
            {
                throw new InvalidDataException("apply publication requires the pre-write authorization marker to remain revoked.");
            }
        }

        private static PublicationCommitResult PublicationCommitResultFromJournal(Dictionary<string, string> journal)
        {
            return new PublicationCommitResult
            {
                TransactionId = SidecarValue(journal, "transactionId"),
                Operation = SidecarValue(journal, "operation"),
                WorkspacePath = SidecarValue(journal, "workspacePath"),
                BackupDir = SidecarValue(journal, "backupDir"),
                CompletionResultPath = SidecarValue(journal, "completionResultPath")
            };
        }

        private static void WritePublicationCompletionResult(
            Dictionary<string, string> journal,
            string state,
            string diagnosticStatus,
            string message)
        {
            PublicationCommitResult result = PublicationCommitResultFromJournal(journal);
            UpdatePublicationCompletionResult(result, state, diagnosticStatus, message);
        }

        private static void UpdatePublicationCompletionResult(
            PublicationCommitResult result,
            string state,
            string diagnosticStatus,
            string message)
        {
            if (result == null || string.IsNullOrWhiteSpace(result.CompletionResultPath)) return;
            EnsurePathInside(result.CompletionResultPath, result.BackupDir);
            Directory.CreateDirectory(result.BackupDir);
            WriteFlatJsonObjectAtomically(
                result.CompletionResultPath,
                new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                {
                    { "owner", ProductName },
                    { "resultSchemaVersion", PublicationResultSchemaVersion },
                    { "transactionId", result.TransactionId },
                    { "operation", result.Operation },
                    { "state", state },
                    { "workspacePath", result.WorkspacePath },
                    { "backupDir", result.BackupDir },
                    { "diagnosticStatus", diagnosticStatus },
                    { "message", EmptyIfNull(message) },
                    { "updatedUtc", DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) }
                });
            FlushFileToDisk(result.CompletionResultPath);
        }

        private static void UpdatePublicationCompletionResultBestEffort(
            PublicationCommitResult result,
            string state,
            string diagnosticStatus,
            string message)
        {
            try
            {
                UpdatePublicationCompletionResult(result, state, diagnosticStatus, message);
            }
            catch (Exception ex)
            {
                Console.WriteLine("WARNING: publication committed, but the completion file could not be updated: " + ex.Message);
                if (result != null)
                {
                    Console.WriteLine("Transaction: " + result.TransactionId + "; backup: " + result.BackupDir);
                    Console.WriteLine("A retained committed journal takes precedence over an older completion file: " + Path.Combine(result.WorkspacePath, PublicationTransactionFileName));
                }
            }
        }

        private static Exception FinalizeCommittedApplyPublication(
            PublicationCommitResult result, Action verifyPublishedBundle, Action publishAfterCheckReports)
        {
            // Verification is authoritative and must propagate errors. Everything
            // after it is diagnostic: a locked result/report cannot revoke the
            // verified bundle or send a committed apply into the failure branch.
            verifyPublishedBundle();
            Exception diagnosticFailure;
            TryWriteCommittedPublicationDiagnostics(result, "apply-clone", publishAfterCheckReports, out diagnosticFailure);
            return diagnosticFailure ?? (result == null ? null : result.DiagnosticFailure);
        }

        private static bool TryWriteCommittedPublicationDiagnostics(
            PublicationCommitResult result,
            string operationLabel,
            Action writer,
            out Exception failure)
        {
            failure = null;
            try
            {
                writer();
                bool priorFailure = result != null && result.DiagnosticFailure != null;
                UpdatePublicationCompletionResult(
                    result,
                    priorFailure ? "committed_with_diagnostic_failure" : "committed",
                    priorFailure ? "failed" : "ok",
                    priorFailure ? result.DiagnosticFailure.Message : operationLabel + " diagnostics were published.");
                return true;
            }
            catch (Exception ex)
            {
                failure = ex;
                if (result != null) result.DiagnosticFailure = ex;
                UpdatePublicationCompletionResultBestEffort(result, "committed_with_diagnostic_failure", "failed", ex.GetType().Name + ": " + ex.Message);
                Console.WriteLine("WARNING: " + operationLabel + " committed successfully; do not repeat writes or restore the project because of this diagnostic failure: " + ex.Message);
                if (result != null) Console.WriteLine("Durable completion result: " + result.CompletionResultPath);
                return false;
            }
        }

        private static void InvokePublicationCrashHook(Action<string> crashHook, string phase)
        {
            if (crashHook == null) return;
            try
            {
                crashHook(phase);
            }
            catch (PublicationCrashSimulationException)
            {
                throw;
            }
            catch (Exception ex)
            {
                throw new PublicationCrashSimulationException(phase, ex);
            }
        }

        private static void WritePublicationJournal(
            string journalPath,
            Dictionary<string, string> journal,
            string state)
        {
            if (!PublicationJournalStates().Contains(state, StringComparer.OrdinalIgnoreCase))
            {
                throw new InvalidDataException("Publication transaction journal state is not allowed: " + state);
            }
            journal["state"] = state;
            journal["updatedUtc"] = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            ValidateExactFlatObjectKeys(journal, PublicationJournalKeys(), "publication transaction journal");
            WriteFlatJsonObjectAtomically(journalPath, journal);
            FlushFileToDisk(journalPath);
        }

        private static string[] PublicationJournalKeys()
        {
            return new[]
            {
                "owner", "journalSchemaVersion", "workspacePath", "transactionId", "operation", "state", "updatedUtc",
                "stagingDir", "installationDir", "backupDir", "packagePath", "packageSha256", "stagingOwnerSha256", "completionResultPath",
                "oldRootExists", "oldRootSha256", "oldBlocksExists", "oldBlocksSha256",
                "oldGroupsExists", "oldGroupsSha256", "oldMetadataExists", "oldMetadataSha256",
                "oldMarkerExists", "oldMarkerSha256", "newRootSha256", "newBlocksSha256",
                "newGroupsSha256", "newMetadataSha256"
            };
        }

        private static string[] PublicationJournalStates()
        {
            return new[]
            {
                "prepared",
                "before-root-prepared", "root-prepared",
                "before-blocks-prepared", "blocks-prepared",
                "before-groups-prepared", "groups-prepared",
                "before-metadata-prepared", "metadata-prepared",
                "before-root-backed-up", "root-backed-up",
                "before-blocks-backed-up", "blocks-backed-up",
                "before-groups-backed-up", "groups-backed-up",
                "before-metadata-backed-up", "metadata-backed-up",
                "before-marker-backed-up", "marker-backed-up",
                "before-root-installed", "root-installed",
                "before-blocks-installed", "blocks-installed",
                "before-groups-installed", "groups-installed",
                "before-metadata-installed", "metadata-installed",
                "committed", "rolled-back"
            };
        }

        private static string PublicationPathFingerprint(string path, bool directory)
        {
            if (directory)
            {
                if (!Directory.Exists(path)) return string.Empty;
                EnsureExistingTreeHasNoReparsePoints(path, "publication component");
                List<string> entries = new List<string>();
                entries.AddRange(Directory.GetDirectories(path, "*", SearchOption.AllDirectories)
                    .Select(x => "D|" + MakeRelativePath(path, x)));
                entries.AddRange(Directory.GetFiles(path, "*", SearchOption.AllDirectories)
                    .Select(x => "F|" + MakeRelativePath(path, x) + "|" + ComputeFileSha256(x)));
                return ComputeTextSha256(string.Join("\n", entries.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToArray()));
            }
            return File.Exists(path) ? ComputeFileSha256(path) : string.Empty;
        }

        private static string PackageFileFingerprint(string packagePath, string relativePath)
        {
            using (ZipArchive archive = ZipFile.OpenRead(packagePath))
            {
                ZipArchiveEntry entry = archive.GetEntry(relativePath);
                if (entry == null) throw new InvalidDataException("Publication package is missing " + relativePath + ".");
                using (Stream stream = entry.Open()) return ComputeStreamSha256(stream);
            }
        }

        private static string PackageComponentFingerprint(string packagePath, string component)
        {
            string prefix = component.TrimEnd('/') + "/";
            List<string> entries = new List<string>();
            using (ZipArchive archive = ZipFile.OpenRead(packagePath))
            {
                foreach (ZipArchiveEntry entry in archive.Entries
                    .Where(x => x.FullName.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                    .OrderBy(x => x.FullName, StringComparer.OrdinalIgnoreCase))
                {
                    string relative = entry.FullName.Substring(prefix.Length).TrimEnd('/');
                    if (string.IsNullOrWhiteSpace(relative)) continue;
                    if (entry.FullName.EndsWith("/", StringComparison.Ordinal))
                    {
                        entries.Add("D|" + relative.Replace('/', Path.DirectorySeparatorChar));
                    }
                    else
                    {
                        using (Stream stream = entry.Open())
                        {
                            entries.Add("F|" + relative.Replace('/', Path.DirectorySeparatorChar) + "|" + ComputeStreamSha256(stream));
                        }
                    }
                }
            }
            return ComputeTextSha256(string.Join("\n", entries.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToArray()));
        }

        private static void PreparePublicationComponent(
            string packagePath, string name, bool directory, string installationDir,
            string journalPath, Dictionary<string, string> journal, string phase, Action<string> crashHook)
        {
            WritePublicationJournal(journalPath, journal, "before-" + phase + "-prepared");
            string target = Path.Combine(installationDir, name);
            if (directory) ExtractPublicationDirectory(packagePath, name, target, crashHook, phase);
            else ExtractPublicationFile(packagePath, name, target, crashHook, phase);
            string expected = journal["new" + char.ToUpperInvariant(phase[0]) + phase.Substring(1) + "Sha256"];
            if (!EqualsIgnoreCase(PublicationPathFingerprint(target, directory), expected))
                throw new InvalidDataException("Prepared publication component differs from the sealed package: " + target);
            WritePublicationJournal(journalPath, journal, phase + "-prepared");
            InvokePublicationCrashHook(crashHook, phase + "-prepared");
        }

        private static void InstallPreparedPublicationComponent(
            string installationDir, string name, string destination, bool directory, string expectedHash)
        {
            string prepared = Path.Combine(installationDir, name);
            EnsurePathInside(prepared, installationDir);
            EnsureExistingTreeHasNoReparsePoints(installationDir, "publication installation candidate");
            if (!EqualsIgnoreCase(Path.GetPathRoot(prepared), Path.GetPathRoot(destination)))
                throw new InvalidDataException("Publication installation requires a same-volume rename.");
            if (!EqualsIgnoreCase(PublicationPathFingerprint(prepared, directory), expectedHash))
                throw new InvalidDataException("Prepared publication component changed before installation: " + prepared);
            if (Directory.Exists(destination) || File.Exists(destination))
                throw new IOException("Publication destination already exists: " + destination);
            // No copy/extraction fallback: the final component appears whole.
            if (directory) Directory.Move(prepared, destination);
            else File.Move(prepared, destination);
        }

        private static void CopyPublicationContent(Stream source, FileStream output, Action<string> crashHook, string phase)
        {
            byte[] buffer = new byte[65536];
            int count;
            while ((count = source.Read(buffer, 0, buffer.Length)) > 0)
            {
                output.Write(buffer, 0, count);
                // Tests terminate the child while this file is still incomplete.
                InvokePublicationCrashHook(crashHook, "copying-" + phase);
            }
            output.Flush(true);
        }

        private static void ExtractPublicationDirectory(string packagePath, string component, string destination, Action<string> crashHook, string phase)
        {
            if (Directory.Exists(destination) || File.Exists(destination)) throw new IOException("Publication destination already exists: " + destination);
            Directory.CreateDirectory(destination);
            string prefix = component.TrimEnd('/') + "/";
            using (ZipArchive archive = ZipFile.OpenRead(packagePath))
            {
                foreach (ZipArchiveEntry entry in archive.Entries.Where(x => x.FullName.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)))
                {
                    string relative = entry.FullName.Substring(prefix.Length).TrimEnd('/');
                    if (string.IsNullOrWhiteSpace(relative)) continue;
                    string target = Path.Combine(destination, relative.Replace('/', Path.DirectorySeparatorChar));
                    EnsurePathInside(target, destination);
                    if (entry.FullName.EndsWith("/", StringComparison.Ordinal))
                    {
                        Directory.CreateDirectory(target);
                    }
                    else
                    {
                        Directory.CreateDirectory(Path.GetDirectoryName(target));
                        using (Stream source = entry.Open())
                        using (FileStream output = new FileStream(target, FileMode.CreateNew, FileAccess.Write, FileShare.None))
                        {
                            CopyPublicationContent(source, output, crashHook, phase);
                        }
                    }
                }
            }
        }

        private static void ExtractPublicationFile(string packagePath, string relativePath, string destination, Action<string> crashHook, string phase)
        {
            if (Directory.Exists(destination) || File.Exists(destination)) throw new IOException("Publication destination already exists: " + destination);
            using (ZipArchive archive = ZipFile.OpenRead(packagePath))
            {
                ZipArchiveEntry entry = archive.GetEntry(relativePath);
                if (entry == null) throw new InvalidDataException("Publication package is missing " + relativePath + ".");
                using (Stream source = entry.Open())
                using (FileStream output = new FileStream(destination, FileMode.CreateNew, FileAccess.Write, FileShare.None))
                {
                    CopyPublicationContent(source, output, crashHook, phase);
                }
            }
        }

        private static void ValidateInstalledPublication(string outDir, Dictionary<string, string> journal)
        {
            if (!EqualsIgnoreCase(PublicationPathFingerprint(Path.Combine(outDir, "_root"), true), RequiredCloneCheckMarkerValue(journal, "newRootSha256", PublicationTransactionFileName))
                || !EqualsIgnoreCase(PublicationPathFingerprint(Path.Combine(outDir, "plc-blocks.csv"), false), RequiredCloneCheckMarkerValue(journal, "newBlocksSha256", PublicationTransactionFileName))
                || !EqualsIgnoreCase(PublicationPathFingerprint(Path.Combine(outDir, "block-groups.csv"), false), RequiredCloneCheckMarkerValue(journal, "newGroupsSha256", PublicationTransactionFileName))
                || !EqualsIgnoreCase(PublicationPathFingerprint(Path.Combine(outDir, "_metadata"), true), RequiredCloneCheckMarkerValue(journal, "newMetadataSha256", PublicationTransactionFileName)))
            {
                throw new InvalidDataException("Installed clone publication does not match the immutable package fingerprints.");
            }
        }

        private static void ValidatePublicationJournalContract(
            string outDir,
            Dictionary<string, string> journal,
            string journalPath)
        {
            ValidateExactFlatObjectKeys(journal, PublicationJournalKeys(), "publication transaction journal");
            string transactionId = RequiredCloneCheckMarkerValue(journal, "transactionId", journalPath);
            string operation = RequiredCloneCheckMarkerValue(journal, "operation", journalPath);
            string state = RequiredCloneCheckMarkerValue(journal, "state", journalPath);
            string workspacePath = Path.GetFullPath(RequiredCloneCheckMarkerValue(journal, "workspacePath", journalPath));
            string stagingDir = Path.GetFullPath(RequiredCloneCheckMarkerValue(journal, "stagingDir", journalPath));
            string backupDir = Path.GetFullPath(RequiredCloneCheckMarkerValue(journal, "backupDir", journalPath));
            string packagePath = Path.GetFullPath(RequiredCloneCheckMarkerValue(journal, "packagePath", journalPath));
            string packageSha256 = RequiredCloneCheckMarkerValue(journal, "packageSha256", journalPath);
            string completionResultPath = Path.GetFullPath(RequiredCloneCheckMarkerValue(journal, "completionResultPath", journalPath));
            string installationDir = Path.GetFullPath(RequiredCloneCheckMarkerValue(journal, "installationDir", journalPath));
            DateTime updatedUtc;
            if (!EqualsIgnoreCase(SidecarValue(journal, "owner"), ProductName)
                || !EqualsIgnoreCase(SidecarValue(journal, "journalSchemaVersion"), PublicationJournalSchemaVersion)
                || !EqualsIgnoreCase(workspacePath, Path.GetFullPath(outDir))
                || !Regex.IsMatch(transactionId, "^[0-9a-fA-F]{32}$")
                || (!EqualsIgnoreCase(operation, "sync-clone") && !EqualsIgnoreCase(operation, "apply-publication"))
                || !PublicationJournalStates().Contains(state, StringComparer.OrdinalIgnoreCase)
                || !DateTime.TryParse(SidecarValue(journal, "updatedUtc"), CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out updatedUtc))
            {
                throw new InvalidDataException("Publication transaction journal has invalid owner/schema/workspace/identity/state fields: " + journalPath);
            }
            string stagingParent = EqualsIgnoreCase(operation, "sync-clone")
                ? Path.Combine(outDir, "_sync-staging")
                : Path.Combine(outDir, "_apply-validation");
            string backupParent = EqualsIgnoreCase(operation, "sync-clone")
                ? Path.Combine(outDir, "_sync-backups")
                : Path.Combine(outDir, "_apply-backups");
            EnsurePathInside(stagingDir, stagingParent);
            EnsurePathInside(packagePath, stagingDir);
            EnsurePathInside(backupDir, backupParent);
            EnsurePathInside(completionResultPath, backupDir);
            if (!EqualsIgnoreCase(installationDir, Path.Combine(stagingDir, "_publication-install-" + transactionId))
                || !EqualsIgnoreCase(packagePath, Path.Combine(stagingDir, SyncPublicationPackageFileName))
                || !EqualsIgnoreCase(completionResultPath, Path.Combine(backupDir, "publication-completion.json")))
                throw new InvalidDataException("Publication journal paths do not match the fixed transaction layout.");
            EnsureExistingTreeHasNoReparsePoints(stagingDir, "publication recovery staging");
            if (Directory.Exists(backupDir)) EnsureExistingTreeHasNoReparsePoints(backupDir, "publication recovery backup");
            if (!File.Exists(packagePath) || !EqualsIgnoreCase(ComputeFileSha256(packagePath), packageSha256))
            {
                throw new InvalidDataException("Publication transaction package is missing or does not match the journal digest; manual recovery is required.");
            }
            if (!EqualsIgnoreCase(PackageComponentFingerprint(packagePath, "_root"), SidecarValue(journal, "newRootSha256"))
                || !EqualsIgnoreCase(PackageFileFingerprint(packagePath, "plc-blocks.csv"), SidecarValue(journal, "newBlocksSha256"))
                || !EqualsIgnoreCase(PackageFileFingerprint(packagePath, "block-groups.csv"), SidecarValue(journal, "newGroupsSha256"))
                || !EqualsIgnoreCase(PackageComponentFingerprint(packagePath, "_metadata"), SidecarValue(journal, "newMetadataSha256")))
            {
                throw new InvalidDataException("Publication transaction new-state fingerprints do not match the bound package.");
            }
            ValidatePublicationStagingOwner(
                stagingDir,
                operation,
                outDir,
                transactionId,
                packageSha256,
                RequiredCloneCheckMarkerValue(journal, "stagingOwnerSha256", journalPath));

            bool oldRoot = ParsePublicationJournalExists(journal, "oldRoot", journalPath);
            bool oldBlocks = ParsePublicationJournalExists(journal, "oldBlocks", journalPath);
            bool oldGroups = ParsePublicationJournalExists(journal, "oldGroups", journalPath);
            bool oldMetadata = ParsePublicationJournalExists(journal, "oldMetadata", journalPath);
            bool oldMarker = ParsePublicationJournalExists(journal, "oldMarker", journalPath);
            ValidatePublicationOldStateInvariant(operation, oldRoot, oldBlocks, oldGroups, oldMetadata, oldMarker);
        }

        private static bool ParsePublicationJournalExists(
            Dictionary<string, string> journal,
            string keyPrefix,
            string journalPath)
        {
            bool exists;
            if (!bool.TryParse(RequiredCloneCheckMarkerValue(journal, keyPrefix + "Exists", journalPath), out exists))
            {
                throw new InvalidDataException("Publication journal has invalid " + keyPrefix + "Exists.");
            }
            string hash = SidecarValue(journal, keyPrefix + "Sha256");
            if (exists == string.IsNullOrWhiteSpace(hash))
            {
                throw new InvalidDataException("Publication journal has an inconsistent " + keyPrefix + " existence/fingerprint pair.");
            }
            return exists;
        }

        private static void RecoverIncompletePublication(string outDir)
        {
            RecoverIncompletePublication(outDir, false);
        }

        private static void RecoverIncompletePublication(string outDir, bool cleanupRecoveredStaging)
        {
            outDir = Path.GetFullPath(outDir);
            string journalPath = Path.Combine(outDir, PublicationTransactionFileName);
            if (!File.Exists(journalPath)) return;
            Dictionary<string, string> journal = ParseStrictFlatJsonObject(File.ReadAllText(journalPath, Encoding.UTF8), journalPath);
            ValidatePublicationJournalContract(outDir, journal, journalPath);
            string transactionId = SidecarValue(journal, "transactionId");
            string operation = SidecarValue(journal, "operation");
            string state = SidecarValue(journal, "state");
            string stagingDir = Path.GetFullPath(SidecarValue(journal, "stagingDir"));
            string backupDir = Path.GetFullPath(SidecarValue(journal, "backupDir"));

            if (EqualsIgnoreCase(state, "committed"))
            {
                try
                {
                    ValidateInstalledPublication(outDir, journal);
                    WritePublicationCompletionResult(journal, "committed", "recovered", "Committed publication was verified after process restart.");
                    File.Delete(journalPath);
                    if (cleanupRecoveredStaging) CleanupRecoveredPublicationStaging(operation, stagingDir);
                    return;
                }
                catch (Exception ex)
                {
                    throw new InvalidOperationException(
                        "Publication journal records a committed transaction, but installed-state or completion-result verification failed. Recovery is not required and no workspace component was changed; inspect " + journalPath + ".",
                        ex);
                }
            }

            ValidatePublicationRecoveryComponent(outDir, backupDir, "_root", true, journal, "oldRoot", "newRootSha256");
            ValidatePublicationRecoveryComponent(outDir, backupDir, "plc-blocks.csv", false, journal, "oldBlocks", "newBlocksSha256");
            ValidatePublicationRecoveryComponent(outDir, backupDir, "block-groups.csv", false, journal, "oldGroups", "newGroupsSha256");
            ValidatePublicationRecoveryComponent(outDir, backupDir, "_metadata", true, journal, "oldMetadata", "newMetadataSha256");
            ValidatePublicationRecoveryComponent(outDir, backupDir, CloneCheckBundleFileName, false, journal, "oldMarker", string.Empty);

            RestorePublicationComponent(outDir, backupDir, "_root", true, journal, "oldRoot", "newRootSha256");
            RestorePublicationComponent(outDir, backupDir, "plc-blocks.csv", false, journal, "oldBlocks", "newBlocksSha256");
            RestorePublicationComponent(outDir, backupDir, "block-groups.csv", false, journal, "oldGroups", "newGroupsSha256");
            RestorePublicationComponent(outDir, backupDir, "_metadata", true, journal, "oldMetadata", "newMetadataSha256");
            RestorePublicationComponent(outDir, backupDir, CloneCheckBundleFileName, false, journal, "oldMarker", string.Empty);
            if (EqualsIgnoreCase(operation, "apply-publication"))
            {
                // The TIA project may already have been saved before a local
                // publication crash. Never resurrect its pre-apply authorization.
                InvalidateCloneCheckBundle(outDir);
            }
            try
            {
                WritePublicationCompletionResult(
                    journal,
                    "not_committed",
                    "rolled_back",
                    "Interrupted publication was recovered by restoring the recorded previous baseline.");
            }
            catch (Exception completionException)
            {
                Console.WriteLine("WARNING: publication rollback completed, but its not_committed diagnostic could not be updated: " + completionException.Message);
            }
            WritePublicationJournal(journalPath, journal, "rolled-back");
            File.Delete(journalPath);
            Console.WriteLine("Recovered incomplete " + operation + " transaction " + transactionId + " by restoring the previous clone baseline.");
            if (cleanupRecoveredStaging) CleanupRecoveredPublicationStaging(operation, stagingDir);
        }

        private static void ValidatePublicationRecoveryComponent(
            string outDir,
            string backupDir,
            string name,
            bool directory,
            Dictionary<string, string> journal,
            string keyPrefix,
            string newHashKey)
        {
            string finalPath = Path.Combine(outDir, name);
            string backupPath = Path.Combine(backupDir, name);
            bool oldExists = ParsePublicationJournalExists(journal, keyPrefix, PublicationTransactionFileName);
            string expectedOldHash = SidecarValue(journal, keyPrefix + "Sha256");
            string expectedNewHash = string.IsNullOrWhiteSpace(newHashKey) ? string.Empty : SidecarValue(journal, newHashKey);
            bool backupExists = directory ? Directory.Exists(backupPath) : File.Exists(backupPath);
            bool finalExists = directory ? Directory.Exists(finalPath) : File.Exists(finalPath);
            if ((File.Exists(backupPath) || Directory.Exists(backupPath)) && !backupExists)
            {
                throw new InvalidDataException("Publication backup component has the wrong filesystem type: " + backupPath);
            }
            if ((File.Exists(finalPath) || Directory.Exists(finalPath)) && !finalExists)
            {
                throw new InvalidDataException("Active publication component has the wrong filesystem type: " + finalPath);
            }
            if (backupExists)
            {
                if (!oldExists || !EqualsIgnoreCase(PublicationPathFingerprint(backupPath, directory), expectedOldHash))
                {
                    throw new InvalidDataException("Publication backup does not match durable old-state evidence: " + backupPath);
                }
                if (finalExists)
                {
                    string finalHash = PublicationPathFingerprint(finalPath, directory);
                    if (!EqualsIgnoreCase(finalHash, expectedOldHash)
                        && (string.IsNullOrWhiteSpace(expectedNewHash) || !EqualsIgnoreCase(finalHash, expectedNewHash)))
                    {
                        throw new InvalidDataException("Active publication component matches neither recorded old nor transaction-installed new state; no recovery mutation was performed: " + finalPath);
                    }
                }
                return;
            }
            if (oldExists)
            {
                if (!finalExists || !EqualsIgnoreCase(PublicationPathFingerprint(finalPath, directory), expectedOldHash))
                {
                    throw new InvalidDataException("Neither final nor backup component matches durable old-state evidence; no recovery mutation was performed: " + finalPath);
                }
                return;
            }
            if (finalExists
                && (string.IsNullOrWhiteSpace(expectedNewHash)
                    || !EqualsIgnoreCase(PublicationPathFingerprint(finalPath, directory), expectedNewHash)))
            {
                throw new InvalidDataException("Journal cannot prove that the active component was installed by this transaction; no recovery mutation was performed: " + finalPath);
            }
        }

        private static void CleanupRecoveredPublicationStaging(string operation, string stagingDir)
        {
            ApplyStagingCleanupResult cleanup = EqualsIgnoreCase(operation, "sync-clone")
                ? CleanupSyncStaging(stagingDir)
                : CleanupApplyValidationWorkspace(stagingDir);
            if (!cleanup.Removed)
            {
                Console.WriteLine("WARNING: recovered publication staging requires local confidentiality cleanup: " + cleanup.EvidencePath + ". " + cleanup.Message);
            }
        }

        private static void RestorePublicationComponent(
            string outDir,
            string backupDir,
            string name,
            bool directory,
            Dictionary<string, string> journal,
            string keyPrefix,
            string newHashKey)
        {
            string finalPath = Path.Combine(outDir, name);
            string backupPath = Path.Combine(backupDir, name);
            bool oldExists;
            if (!bool.TryParse(RequiredCloneCheckMarkerValue(journal, keyPrefix + "Exists", PublicationTransactionFileName), out oldExists))
            {
                throw new InvalidDataException("Publication journal has invalid " + keyPrefix + "Exists.");
            }
            string expectedOldHash = MarkerValue(journal, keyPrefix + "Sha256");
            string expectedNewHash = string.IsNullOrWhiteSpace(newHashKey) ? string.Empty : MarkerValue(journal, newHashKey);
            bool backupExists = directory ? Directory.Exists(backupPath) : File.Exists(backupPath);
            bool finalExists = directory ? Directory.Exists(finalPath) : File.Exists(finalPath);
            if ((File.Exists(backupPath) || Directory.Exists(backupPath)) && !backupExists)
            {
                throw new InvalidDataException("Publication backup component has the wrong filesystem type: " + backupPath);
            }
            if ((File.Exists(finalPath) || Directory.Exists(finalPath)) && !finalExists)
            {
                throw new InvalidDataException("Active publication component has the wrong filesystem type: " + finalPath);
            }
            if (backupExists)
            {
                if (!oldExists || !EqualsIgnoreCase(PublicationPathFingerprint(backupPath, directory), expectedOldHash))
                {
                    throw new InvalidDataException("Publication backup does not match durable old-state evidence: " + backupPath);
                }
                if (finalExists)
                {
                    string finalHash = PublicationPathFingerprint(finalPath, directory);
                    if (EqualsIgnoreCase(finalHash, expectedOldHash)) return;
                    if (string.IsNullOrWhiteSpace(expectedNewHash) || !EqualsIgnoreCase(finalHash, expectedNewHash))
                    {
                        throw new InvalidDataException("Active publication component matches neither recorded old nor transaction-installed new state; manual recovery is required: " + finalPath);
                    }
                    DisplacePublicationComponentForRollback(finalPath, name, directory, journal);
                }
                if (directory) Directory.Move(backupPath, finalPath); else File.Move(backupPath, finalPath);
                return;
            }
            if (oldExists)
            {
                if (!finalExists || !EqualsIgnoreCase(PublicationPathFingerprint(finalPath, directory), expectedOldHash))
                {
                    throw new InvalidDataException("Neither final nor backup component matches durable old-state evidence: " + finalPath);
                }
                return;
            }
            if (!finalExists) return;
            if (string.IsNullOrWhiteSpace(expectedNewHash)
                || !EqualsIgnoreCase(PublicationPathFingerprint(finalPath, directory), expectedNewHash))
            {
                throw new InvalidDataException("Journal cannot prove that the active component was installed by this transaction; no deletion was performed: " + finalPath);
            }
            DisplacePublicationComponentForRollback(finalPath, name, directory, journal);
        }

        private static void DisplacePublicationComponentForRollback(
            string finalPath, string name, bool directory, Dictionary<string, string> journal)
        {
            // Recursive deletion here would introduce the same partial-component
            // crash window as extraction into the active tree. Move a proven new
            // component aside atomically; cleanup occurs only after recovery.
            string rollbackDir = Path.Combine(SidecarValue(journal, "installationDir"), "_rollback");
            EnsurePathInside(rollbackDir, SidecarValue(journal, "stagingDir"));
            Directory.CreateDirectory(rollbackDir);
            string displaced = Path.Combine(rollbackDir, name);
            if (File.Exists(displaced) || Directory.Exists(displaced))
                throw new InvalidDataException("Rollback displacement path is already occupied; transaction evidence was retained: " + displaced);
            if (directory) Directory.Move(finalPath, displaced);
            else File.Move(finalPath, displaced);
        }

        private static List<CloneWorkspaceFileRecord> ReadPackageFileInventory(string packagePath)
        {
            List<CloneWorkspaceFileRecord> result = new List<CloneWorkspaceFileRecord>();
            using (ZipArchive archive = ZipFile.OpenRead(packagePath))
            {
                foreach (ZipArchiveEntry entry in archive.Entries.Where(x => !x.FullName.EndsWith("/", StringComparison.Ordinal)))
                {
                    using (Stream stream = entry.Open())
                    {
                        result.Add(new CloneWorkspaceFileRecord
                        {
                            Kind = "publication",
                            RelativePath = NormalizeCloneWorkspaceRelativePath(entry.FullName),
                            Size = entry.Length,
                            Sha256 = ComputeStreamSha256(stream)
                        });
                    }
                }
            }
            return result;
        }

        private static List<string> ReadPackageDirectories(string packagePath)
        {
            using (ZipArchive archive = ZipFile.OpenRead(packagePath))
            {
                return archive.Entries
                    .Where(x => x.FullName.EndsWith("/", StringComparison.Ordinal))
                    .Select(x => NormalizeCloneWorkspaceRelativePath(x.FullName).TrimEnd('/'))
                    .ToList();
            }
        }

        private static ApplyStagingCleanupResult CleanupSyncStaging(string stagingDir)
        {
            ApplyStagingCleanupResult result = new ApplyStagingCleanupResult
            {
                OriginalPath = EmptyIfNull(stagingDir), EvidencePath = EmptyIfNull(stagingDir), Status = "removed",
                Message = "Sync staging did not exist or was removed."
            };
            if (string.IsNullOrWhiteSpace(stagingDir) || !Directory.Exists(stagingDir)) return result;
            if (RetainStagingForPublicationJournal(stagingDir, result)) return result;
            if (!File.Exists(Path.Combine(stagingDir, SyncStagingOwnerMarkerFileName)))
            {
                result.Status = "failed";
                result.Message = "Refused to remove sync staging without the OpennessLLM ownership marker.";
                return result;
            }
            string parent = Path.GetDirectoryName(stagingDir);
            string outDir = Path.GetDirectoryName(parent);
            try
            {
                Directory.Delete(stagingDir, true);
                if (Directory.Exists(parent) && !Directory.EnumerateFileSystemEntries(parent).Any()) Directory.Delete(parent, false);
                return result;
            }
            catch (Exception deleteException)
            {
                try
                {
                    string quarantineParent = Path.Combine(outDir, "_sync-staging-quarantine");
                    Directory.CreateDirectory(quarantineParent);
                    string quarantineDir = UniquePath(Path.Combine(quarantineParent, Path.GetFileName(stagingDir)));
                    Directory.Move(stagingDir, quarantineDir);
                    result.Status = "quarantined";
                    result.EvidencePath = Path.Combine(quarantineDir, "cleanup-failure.txt");
                    result.Message = "Sync staging cleanup failed; owned bytes were quarantined for explicit local cleanup.";
                    WriteTextFile(result.EvidencePath, result.Message + Environment.NewLine + deleteException.Message + Environment.NewLine);
                    return result;
                }
                catch (Exception quarantineException)
                {
                    result.Status = "failed";
                    result.Message = "Sync staging cleanup and quarantine both failed: " + deleteException.Message + "; " + quarantineException.Message;
                    try
                    {
                        string auditDir = Path.Combine(outDir, "_sync-staging-cleanup-audit");
                        Directory.CreateDirectory(auditDir);
                        result.EvidencePath = Path.Combine(auditDir, "failure-" + Guid.NewGuid().ToString("N") + ".txt");
                        WriteTextFile(result.EvidencePath, result.Message + Environment.NewLine + "Path: " + stagingDir + Environment.NewLine);
                    }
                    catch
                    {
                        result.EvidencePath = stagingDir;
                    }
                    return result;
                }
            }
        }

        private static string DetermineSyncDestinationPath(string status, string clonePath, string currentPath, string compareRootDir, string rootDir)
        {
            if ((EqualsIgnoreCase(status, "added")
                    || EqualsIgnoreCase(status, "moved-or-renamed")
                    || EqualsIgnoreCase(status, "moved-or-renamed-and-changed"))
                && !string.IsNullOrWhiteSpace(currentPath))
            {
                return MapComparePathToCloneRoot(currentPath, compareRootDir, rootDir);
            }

            if (!string.IsNullOrWhiteSpace(clonePath))
            {
                return clonePath;
            }

            return string.IsNullOrWhiteSpace(currentPath) ? string.Empty : MapComparePathToCloneRoot(currentPath, compareRootDir, rootDir);
        }

        private static string MapComparePathToCloneRoot(string currentPath, string compareRootDir, string rootDir)
        {
            EnsurePathInside(currentPath, compareRootDir);
            string relative = MakeRelativePath(compareRootDir, currentPath);
            return Path.Combine(rootDir, relative);
        }

        private static void CopyFileIntoClone(string sourcePath, string destinationPath, string backupDir, string rootDir)
        {
            if (string.IsNullOrWhiteSpace(sourcePath) || !File.Exists(sourcePath))
            {
                throw new FileNotFoundException("Current compare file was not found.", sourcePath);
            }

            if (string.IsNullOrWhiteSpace(destinationPath))
            {
                throw new InvalidOperationException("Destination path is empty.");
            }

            EnsurePathInside(destinationPath, rootDir);
            ArchiveExistingPath(destinationPath, backupDir, rootDir);
            Directory.CreateDirectory(Path.GetDirectoryName(destinationPath));
            File.Copy(sourcePath, destinationPath, false);
        }

        private static void ArchiveExistingPath(string path, string backupDir, string rootDir)
        {
            if (string.IsNullOrWhiteSpace(path))
            {
                return;
            }

            string fullPath = Path.GetFullPath(path);
            if (!File.Exists(fullPath) && !Directory.Exists(fullPath))
            {
                return;
            }

            EnsurePathInside(fullPath, rootDir);
            string fullRoot = Path.GetFullPath(rootDir).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            if (EqualsIgnoreCase(fullPath.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar), fullRoot))
            {
                return;
            }

            string relative = MakeRelativePath(rootDir, fullPath);
            string backupPath = UniquePath(Path.Combine(backupDir, relative));
            Directory.CreateDirectory(Path.GetDirectoryName(backupPath));

            if (File.Exists(fullPath))
            {
                File.Move(fullPath, backupPath);
            }
            else
            {
                Directory.Move(fullPath, backupPath);
            }
        }

        private static void SyncCloneGroups(List<Dictionary<string, string>> groupRows, string rootDir, string backupDir, List<string[]> report)
        {
            foreach (Dictionary<string, string> row in groupRows ?? new List<Dictionary<string, string>>())
            {
                string status = GetCsvValue(row, "Status");
                string groupPath = RowGroupPathKey(row, "GroupPath");
                string directory = GetCsvValue(row, "CloneDirectory");
                if (string.IsNullOrWhiteSpace(directory))
                {
                    directory = CloneDirectoryForBlockGroup(rootDir, groupPath);
                }

                try
                {
                    if (EqualsIgnoreCase(status, "added"))
                    {
                        EnsurePathInside(directory, rootDir);
                        Directory.CreateDirectory(directory);
                        report.Add(SyncReportRow("group-added", "GROUP:" + groupPath, directory, string.Empty, directory, "ok", "Created clone group directory."));
                    }
                    else if (EqualsIgnoreCase(status, "removed"))
                    {
                        ArchiveExistingPath(directory, backupDir, rootDir);
                        report.Add(SyncReportRow("group-removed", "GROUP:" + groupPath, directory, string.Empty, directory, "ok", "Removed clone group directory by moving it to sync backup."));
                    }
                }
                catch (Exception ex)
                {
                    report.Add(SyncReportRow("group-" + status, "GROUP:" + groupPath, directory, string.Empty, directory, "error", ex.GetType().Name + ": " + ex.Message));
                }
            }
        }

        private static PublicationExpectedModel BuildPublicationExpectedModel(
            string logicalOutDir,
            CloneCheckBundleEvidence bundle,
            string stagingDir,
            string evidenceRootDir,
            string compareRootDir,
            SyncInputSet immutableInputs)
        {
            if (bundle == null || immutableInputs == null)
            {
                throw new InvalidDataException("Publication expected model requires authoritative bundle and immutable inputs.");
            }

            string finalRootDir = Path.Combine(logicalOutDir, "_root");
            List<string[]> blockValues = BuildSyncedBlockManifestRows(
                immutableInputs.BlockManifestPath,
                evidenceRootDir,
                finalRootDir,
                compareRootDir,
                bundle.BlockRows,
                delegate(Dictionary<string, string> row, string evidenceDestination)
                {
                    string status = GetCsvValue(row, "Status");
                    if (SyncStatusUsesCurrentSource(status))
                    {
                        return immutableInputs.CurrentSourcePath(GetCsvValue(row, "CurrentPath"));
                    }
                    return MapClonePathToAlternateRoot(
                        evidenceDestination,
                        evidenceRootDir,
                        Path.Combine(immutableInputs.WorkspaceRoot, "_root"));
                });
            List<string[]> groupValues = BuildSyncedGroupManifestRows(
                immutableInputs.GroupManifestPath,
                finalRootDir,
                bundle.GroupRows);
            PublicationExpectedModel model = new PublicationExpectedModel
            {
                LogicalOutDir = Path.GetFullPath(logicalOutDir),
                EvidenceRootDir = Path.GetFullPath(evidenceRootDir),
                CompareRootDir = Path.GetFullPath(compareRootDir),
                MetadataGeneratedAt = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture),
                BlockRows = CsvValueRowsToDictionaries(BlockManifestHeaders(), blockValues),
                GroupRows = CsvValueRowsToDictionaries(GroupManifestHeaders(), groupValues),
                ExpectedFiles = BuildExpectedSyncPublishFiles(bundle, stagingDir, evidenceRootDir, compareRootDir)
            };
            model.ExpectedDirectories = BuildExpectedSyncPublishDirectories(bundle, stagingDir, model.ExpectedFiles);
            return model;
        }

        private static void WriteExpectedPublicationArtifacts(string stagingDir, PublicationExpectedModel model)
        {
            WriteCsv(
                Path.Combine(stagingDir, "plc-blocks.csv"),
                BlockManifestHeaders(),
                model.BlockRows.Select(row => BlockManifestHeaders().Select(header => GetCsvValue(row, header)).ToArray()));
            WriteCsv(
                Path.Combine(stagingDir, "block-groups.csv"),
                GroupManifestHeaders(),
                model.GroupRows.Select(row => GroupManifestHeaders().Select(header => GetCsvValue(row, header)).ToArray()));
            WriteCloneMetadata(
                stagingDir,
                model.LogicalOutDir,
                model.BlockRows,
                model.GroupRows,
                model.MetadataGeneratedAt);
        }

        private static void ValidateExpectedPublicationArtifacts(string stagingDir, PublicationExpectedModel model)
        {
            ValidateCsvRowsExactly(Path.Combine(stagingDir, "plc-blocks.csv"), BlockManifestHeaders(), model.BlockRows, "staged block manifest");
            ValidateCsvRowsExactly(Path.Combine(stagingDir, "block-groups.csv"), GroupManifestHeaders(), model.GroupRows, "staged group manifest");
            ValidateStagedSyncMetadata(stagingDir, model);
        }

        private static List<Dictionary<string, string>> CsvValueRowsToDictionaries(string[] headers, IEnumerable<string[]> values)
        {
            List<Dictionary<string, string>> result = new List<Dictionary<string, string>>();
            foreach (string[] valueRow in values ?? new string[0][])
            {
                if (valueRow.Length != headers.Length) throw new InvalidDataException("Expected publication row has an invalid field count.");
                Dictionary<string, string> row = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                for (int i = 0; i < headers.Length; i++) row.Add(headers[i], EmptyIfNull(valueRow[i]));
                result.Add(row);
            }
            return result;
        }

        private static void ValidateCsvRowsExactly(
            string path,
            string[] expectedHeaders,
            List<Dictionary<string, string>> expectedRows,
            string label)
        {
            if (!File.Exists(path)) throw new InvalidDataException(label + " is missing: " + path);
            List<string> records = ParseCsvRecords(File.ReadAllText(path, Encoding.UTF8));
            if (records.Count == 0) throw new InvalidDataException(label + " is empty: " + path);
            List<string> headers = ParseCsvLine(records[0]);
            if (headers.Count != expectedHeaders.Length
                || headers.Where((value, index) => !string.Equals(value, expectedHeaders[index], StringComparison.Ordinal)).Any())
            {
                throw new InvalidDataException(label + " headers do not match the fixed publication contract.");
            }
            List<Dictionary<string, string>> actualRows = ReadCsv(path);
            if (actualRows.Count != expectedRows.Count) throw new InvalidDataException(label + " row count does not match authoritative evidence.");
            for (int i = 0; i < expectedRows.Count; i++)
            {
                foreach (string header in expectedHeaders)
                {
                    if (!string.Equals(GetCsvValue(actualRows[i], header), GetCsvValue(expectedRows[i], header), StringComparison.Ordinal))
                    {
                        throw new InvalidDataException(label + " row " + (i + 1).ToString(CultureInfo.InvariantCulture) + " field " + header + " differs from authoritative evidence.");
                    }
                }
            }
        }

        private static void WriteSyncedBlockManifest(
            string manifestOutputPath,
            string originalManifestPath,
            string rootDir,
            string contentRootDir,
            string compareRootDir,
            List<Dictionary<string, string>> blockRows)
        {
            List<string[]> rows = BuildSyncedBlockManifestRows(
                originalManifestPath,
                rootDir,
                rootDir,
                compareRootDir,
                blockRows,
                delegate(Dictionary<string, string> row, string destinationPath)
                {
                    return MapClonePathToAlternateRoot(destinationPath, rootDir, contentRootDir);
                });
            WriteCsv(manifestOutputPath, BlockManifestHeaders(), rows);
        }

        private static List<string[]> BuildSyncedBlockManifestRows(
            string originalManifestPath,
            string evidenceRootDir,
            string finalRootDir,
            string compareRootDir,
            List<Dictionary<string, string>> blockRows,
            Func<Dictionary<string, string>, string, string> trustedContentPath)
        {
            Dictionary<string, string> softwarePaths = LoadSoftwarePathsByIdentity(originalManifestPath);
            string defaultSoftwarePath = LoadFirstSoftwarePath(originalManifestPath);
            List<string[]> rows = new List<string[]>();

            foreach (Dictionary<string, string> row in blockRows)
            {
                string status = GetCsvValue(row, "Status");
                if (EqualsIgnoreCase(status, "removed") || EqualsIgnoreCase(status, "export-error") || IsSourceBlockedStatus(status))
                {
                    continue;
                }

                string evidenceDestination = DetermineSyncDestinationPath(status, GetCsvValue(row, "ClonePath"), GetCsvValue(row, "CurrentPath"), compareRootDir, evidenceRootDir);
                if (string.IsNullOrWhiteSpace(evidenceDestination))
                {
                    continue;
                }
                string destinationPath = MapClonePathToAlternateRoot(evidenceDestination, evidenceRootDir, finalRootDir);

                string groupPath = RowGroupPathKey(row, "GroupPath");
                string name = GetCsvValue(row, "Name");
                string number = GetCsvValue(row, "Number");
                string language = GetCsvValue(row, "ProgrammingLanguage");
                string blockType = GetCsvValue(row, "BlockType");
                string typeName = GetCsvValue(row, "TypeName");
                string instanceOfName = GetCsvValue(row, "InstanceOfName");
                string identity = BlockNumberSpace(typeName, language) + "|" + number + "|" + name;
                string manifestSoftwarePath;
                softwarePaths.TryGetValue(identity, out manifestSoftwarePath);
                string softwarePath = FirstNonEmpty(
                    GetCsvValue(row, "CurrentSoftwarePath"),
                    GetCsvValue(row, "CloneSoftwarePath"),
                    GetCsvValue(row, "SoftwarePath"),
                    manifestSoftwarePath,
                    defaultSoftwarePath);

                string contentPath = trustedContentPath(row, evidenceDestination);
                if (string.IsNullOrWhiteSpace(contentPath) || !File.Exists(contentPath))
                {
                    throw new InvalidDataException("Immutable expected source content is missing for publication: " + evidenceDestination);
                }
                rows.Add(BuildSyncedBlockManifestRow(row, softwarePath, destinationPath, contentPath));
            }
            return rows;
        }

        private static void WriteSyncedGroupManifest(string manifestOutputPath, string originalManifestPath, string rootDir, List<Dictionary<string, string>> groupRows)
        {
            WriteCsv(manifestOutputPath, GroupManifestHeaders(), BuildSyncedGroupManifestRows(originalManifestPath, rootDir, groupRows));
        }

        private static string[] GroupManifestHeaders()
        {
            return new[] { "SoftwarePath", "ParentGroupPath", "ParentGroupPathDisplay", "GroupPath", "GroupPathDisplay", "GroupPathKey", "Name", "Directory" };
        }

        private static List<string[]> BuildSyncedGroupManifestRows(string originalManifestPath, string rootDir, List<Dictionary<string, string>> groupRows)
        {
            string softwarePath = LoadFirstSoftwarePath(originalManifestPath);
            List<string[]> rows = new List<string[]>();
            foreach (Dictionary<string, string> row in groupRows ?? new List<Dictionary<string, string>>())
            {
                if (EqualsIgnoreCase(GetCsvValue(row, "Status"), "removed"))
                {
                    continue;
                }

                string groupPath = RowGroupPathKey(row, "GroupPath");
                rows.Add(new[]
                {
                    softwarePath,
                    ParentGroupPathKey(groupPath),
                    GroupPathDisplay(ParentGroupPathKey(groupPath)),
                    groupPath,
                    GroupPathDisplay(groupPath),
                    groupPath,
                    string.IsNullOrEmpty(groupPath) ? "_root" : LastGroupNameFromKey(groupPath),
                    CloneDirectoryForBlockGroup(rootDir, groupPath)
                });
            }

            return rows.OrderBy(x => x[3].Length).ThenBy(x => x[3], StringComparer.OrdinalIgnoreCase).ToList();
        }

        private static string MapClonePathToAlternateRoot(string path, string rootDir, string alternateRootDir)
        {
            if (string.IsNullOrWhiteSpace(path))
            {
                return string.Empty;
            }

            EnsurePathInside(path, rootDir);
            return Path.Combine(alternateRootDir, MakeRelativePath(rootDir, path));
        }

        private static void WriteCloneMetadata(string outDir)
        {
            WriteCloneMetadata(
                outDir,
                outDir,
                Path.Combine(outDir, "plc-blocks.csv"),
                Path.Combine(outDir, "block-groups.csv"));
        }

        private static void WriteCloneMetadata(string outputDir, string logicalOutDir, string blocksSourcePath, string groupsSourcePath)
        {
            List<Dictionary<string, string>> blocks = File.Exists(blocksSourcePath)
                ? ReadCsv(blocksSourcePath)
                : new List<Dictionary<string, string>>();
            List<Dictionary<string, string>> groups = File.Exists(groupsSourcePath)
                ? ReadCsv(groupsSourcePath)
                : new List<Dictionary<string, string>>();
            WriteCloneMetadata(outputDir, logicalOutDir, blocks, groups, DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture));
        }

        private static void WriteCloneMetadata(
            string outputDir,
            string logicalOutDir,
            List<Dictionary<string, string>> blocks,
            List<Dictionary<string, string>> groups,
            string generatedAt)
        {
            string metadataDir = Path.Combine(outputDir, "_metadata");
            Directory.CreateDirectory(metadataDir);

            string logicalBlocksCsv = Path.Combine(logicalOutDir, "plc-blocks.csv");
            string logicalGroupsCsv = Path.Combine(logicalOutDir, "block-groups.csv");
            string logicalMetadataDir = Path.Combine(logicalOutDir, "_metadata");
            blocks = blocks ?? new List<Dictionary<string, string>>();
            groups = groups ?? new List<Dictionary<string, string>>();

            File.WriteAllText(Path.Combine(metadataDir, "schema-version.txt"), "4" + Environment.NewLine, new UTF8Encoding(false));
            WriteJsonl(Path.Combine(metadataDir, "blocks.jsonl"), blocks.Select(NormalizeBlockMetadataRow));
            WriteJsonl(Path.Combine(metadataDir, "groups.jsonl"), groups.Select(NormalizeGroupMetadataRow));

            using (StreamWriter writer = NewUtf8Writer(Path.Combine(metadataDir, "clone-manifest.json")))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"schemaVersion\": 4,");
                writer.WriteLine("  \"generatedAt\": " + Json(generatedAt) + ",");
                writer.WriteLine("  \"cloneDirectory\": " + Json(logicalOutDir) + ",");
                writer.WriteLine("  \"blocksCsv\": " + Json(logicalBlocksCsv) + ",");
                writer.WriteLine("  \"groupsCsv\": " + Json(logicalGroupsCsv) + ",");
                writer.WriteLine("  \"blocksJsonl\": " + Json(Path.Combine(logicalMetadataDir, "blocks.jsonl")) + ",");
                writer.WriteLine("  \"groupsJsonl\": " + Json(Path.Combine(logicalMetadataDir, "groups.jsonl")) + ",");
                writer.WriteLine("  \"blockCount\": " + blocks.Count + ",");
                writer.WriteLine("  \"groupCount\": " + groups.Count + ",");
                writer.WriteLine("  \"sidecarConvention\": " + Json("<source-file>.meta.json"));
                writer.WriteLine("}");
            }
        }

        private static Dictionary<string, string> NormalizeBlockMetadataRow(Dictionary<string, string> row)
        {
            string typeName = GetCsvValue(row, "TypeName");
            string language = GetCsvValue(row, "ProgrammingLanguage");
            string groupPathKey = RowGroupPathKey(row, "GroupPath");
            return new Dictionary<string, string>
            {
                { "softwarePath", GetCsvValue(row, "SoftwarePath") },
                { "groupPath", GroupPathDisplay(groupPathKey) },
                { "groupPathDisplay", GroupPathDisplay(groupPathKey) },
                { "groupPathKey", groupPathKey },
                { "groupSegmentsJson", GroupSegmentsDisplayJson(groupPathKey) },
                { "name", GetCsvValue(row, "Name") },
                { "number", GetCsvValue(row, "Number") },
                { "autoNumber", GetCsvValue(row, "AutoNumber") },
                { "numberMode", GetCsvValue(row, "NumberMode") },
                { "numberSpace", FirstNonEmpty(GetCsvValue(row, "NumberSpace"), BlockNumberSpace(typeName, language)) },
                { "programmingLanguage", language },
                { "blockType", GetCsvValue(row, "BlockType") },
                { "typeName", typeName },
                { "sourceTypeName", GetCsvValue(row, "SourceTypeName") },
                { "instanceOfName", GetCsvValue(row, "InstanceOfName") },
                { "instanceOfNumber", GetCsvValue(row, "InstanceOfNumber") },
                { "instanceOfType", GetCsvValue(row, "InstanceOfType") },
                { "secondaryType", GetCsvValue(row, "SecondaryType") },
                { "memoryLayout", GetCsvValue(row, "MemoryLayout") },
                { "isConsistent", GetCsvValue(row, "IsConsistent") },
                { "isKnowHowProtected", GetCsvValue(row, "IsKnowHowProtected") },
                { "tiaObjectId", GetCsvValue(row, "TiaObjectId") },
                { "tiaObjectIdStatus", GetCsvValue(row, "TiaObjectIdStatus") },
                { "filePath", GetCsvValue(row, "FilePath") },
                { "sourceSha256", GetCsvValue(row, "SourceSha256") },
                { "normalizedSourceSha256", GetCsvValue(row, "NormalizedSourceSha256") },
                { "status", GetCsvValue(row, "Status") },
                { "message", GetCsvValue(row, "Message") },
                { "sourceOrigin", GetCsvValue(row, "SourceOrigin") }
            };
        }

        private static Dictionary<string, string> NormalizeGroupMetadataRow(Dictionary<string, string> row)
        {
            string groupPathKey = RowGroupPathKey(row, "GroupPath");
            string parentGroupPathKey = RowGroupPathKey(row, "ParentGroupPath");
            return new Dictionary<string, string>
            {
                { "softwarePath", GetCsvValue(row, "SoftwarePath") },
                { "parentGroupPath", GroupPathDisplay(parentGroupPathKey) },
                { "parentGroupPathDisplay", GroupPathDisplay(parentGroupPathKey) },
                { "parentGroupPathKey", parentGroupPathKey },
                { "groupPath", GroupPathDisplay(groupPathKey) },
                { "groupPathDisplay", GroupPathDisplay(groupPathKey) },
                { "groupPathKey", groupPathKey },
                { "groupSegmentsJson", GroupSegmentsDisplayJson(groupPathKey) },
                { "name", GetCsvValue(row, "Name") },
                { "directory", GetCsvValue(row, "Directory") }
            };
        }

        private static void BlockInfoCommand(string cloneDir, Options options)
        {
            if (!string.IsNullOrWhiteSpace(options.Name) && options.Number > 0)
            {
                throw new ArgumentException("Use either --name or --number for block-info, not both.");
            }

            if (string.IsNullOrWhiteSpace(options.Name) && options.Number <= 0)
            {
                throw new ArgumentException("block-info requires --name <name> or --number <n>.");
            }

            List<BlockLookupRecord> records = LoadBlockLookupRecords(cloneDir);
            List<BlockLookupRecord> matches = FilterBlockLookupRecords(records, options)
                .OrderBy(x => BlockNumberSpaceSortKey(x.NumberSpace))
                .ThenBy(x => SafeInt(x.Number))
                .ThenBy(x => x.Name, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.GroupPath, StringComparer.OrdinalIgnoreCase)
                .ToList();

            if (matches.Count == 0)
            {
                string query = string.IsNullOrWhiteSpace(options.Name)
                    ? "number " + options.Number.ToString(CultureInfo.InvariantCulture)
                    : "name '" + options.Name + "'";
                throw new InvalidOperationException("No PLC block matched " + query + " in clone metadata: " + cloneDir);
            }

            if (options.Json)
            {
                WriteBlockInfoJson(cloneDir, options, matches);
            }
            else
            {
                WriteBlockInfoText(cloneDir, options, matches);
            }
        }

        private static List<BlockLookupRecord> FilterBlockLookupRecords(List<BlockLookupRecord> records, Options options)
        {
            string expectedGroup = NormalizeLookupGroupPath(FirstNonEmpty(options.GroupPathKey, options.GroupPath));
            string expectedGroupDisplay = EmptyIfNull(options.GroupPath).Trim('/').Trim('\\');
            string expectedNumberSpace = NormalizeNumberSpace(options.NumberSpace);
            return records.Where(record =>
                (string.IsNullOrWhiteSpace(options.Name) || MatchesBlockLookupName(record, options.Name))
                && (options.Number <= 0 || SafeInt(record.Number) == options.Number)
                && (string.IsNullOrWhiteSpace(expectedNumberSpace) || EqualsIgnoreCase(record.NumberSpace, expectedNumberSpace))
                && (string.IsNullOrWhiteSpace(expectedGroup)
                    || EqualsIgnoreCase(NormalizeLookupGroupPath(record.GroupPath), expectedGroup)
                    || EqualsIgnoreCase(EmptyIfNull(record.GroupPathDisplay), expectedGroupDisplay)))
                .ToList();
        }

        private static bool MatchesBlockLookupName(BlockLookupRecord record, string query)
        {
            string expected = EmptyIfNull(query).Trim();
            if (string.IsNullOrWhiteSpace(expected))
            {
                return true;
            }

            if (EqualsIgnoreCase(record.Name, expected) || EqualsIgnoreCase(record.Name, StripLeadingBlockNumberPrefix(expected)))
            {
                return true;
            }

            foreach (string path in new[] { record.FilePath, record.ClonePath, record.CurrentPath, record.CloneRelativePath, record.CurrentRelativePath })
            {
                string fileName = Path.GetFileName(EmptyIfNull(path));
                string stem = Path.GetFileNameWithoutExtension(fileName);
                if (EqualsIgnoreCase(fileName, expected)
                    || EqualsIgnoreCase(stem, expected)
                    || EqualsIgnoreCase(StripLeadingBlockNumberPrefix(stem), expected)
                    || EqualsIgnoreCase(StripLeadingBlockNumberPrefix(stem), StripLeadingBlockNumberPrefix(expected)))
                {
                    return true;
                }
            }

            return false;
        }

        private static string StripLeadingBlockNumberPrefix(string value)
        {
            string text = EmptyIfNull(value).Trim();
            int index = 0;
            while (index < text.Length && char.IsDigit(text[index]))
            {
                index++;
            }

            if (index > 0 && index < text.Length && (text[index] == '_' || text[index] == '-'))
            {
                return text.Substring(index + 1);
            }

            return text;
        }

        private static List<BlockLookupRecord> LoadBlockLookupRecords(string cloneDir)
        {
            if (!Directory.Exists(cloneDir))
            {
                throw new DirectoryNotFoundException("Clone directory was not found: " + cloneDir);
            }

            List<BlockLookupRecord> records = new List<BlockLookupRecord>();
            Dictionary<string, BlockLookupRecord> byIdentity = new Dictionary<string, BlockLookupRecord>(StringComparer.OrdinalIgnoreCase);

            string blocksJsonl = Path.Combine(cloneDir, "_metadata", "blocks.jsonl");
            if (File.Exists(blocksJsonl))
            {
                int rowNumber = 0;
                foreach (string line in File.ReadAllLines(blocksJsonl, Encoding.UTF8))
                {
                    rowNumber++;
                    string trimmed = EmptyIfNull(line).Trim();
                    if (string.IsNullOrWhiteSpace(trimmed))
                    {
                        continue;
                    }

                    AddOrMergeBlockLookupRecord(records, byIdentity, BlockLookupRecordFromMetadata(ParseFlatJsonObject(trimmed, blocksJsonl + " row " + rowNumber), blocksJsonl));
                }
            }

            string blocksCsv = Path.Combine(cloneDir, "plc-blocks.csv");
            if (File.Exists(blocksCsv))
            {
                foreach (Dictionary<string, string> row in ReadCsv(blocksCsv))
                {
                    AddOrMergeBlockLookupRecord(records, byIdentity, BlockLookupRecordFromBlockCsv(row, blocksCsv));
                }
            }

            string checkCsv = Path.Combine(cloneDir, "clone-check-blocks.csv");
            if (File.Exists(checkCsv))
            {
                foreach (Dictionary<string, string> row in ReadCsv(checkCsv))
                {
                    AddOrMergeBlockLookupRecord(records, byIdentity, BlockLookupRecordFromCheckCsv(row, checkCsv));
                }
            }

            if (records.Count == 0)
            {
                throw new FileNotFoundException("No block metadata was found. Run init-clone, check-clone, or sync-clone first.", Path.Combine(cloneDir, "_metadata", "blocks.jsonl"));
            }

            return records;
        }

        private static BlockLookupRecord BlockLookupRecordFromMetadata(Dictionary<string, string> row, string sourcePath)
        {
            return new BlockLookupRecord
            {
                SourcePath = sourcePath,
                SoftwarePath = GetCsvValue(row, "softwarePath"),
                GroupPath = NormalizeLookupGroupPath(FirstNonEmpty(GetCsvValue(row, "groupPathKey"), GetCsvValue(row, "groupPath"))),
                GroupPathDisplay = FirstNonEmpty(GetCsvValue(row, "groupPathDisplay"), GroupPathDisplay(FirstNonEmpty(GetCsvValue(row, "groupPathKey"), GetCsvValue(row, "groupPath")))),
                Name = GetCsvValue(row, "name"),
                Number = GetCsvValue(row, "number"),
                AutoNumber = GetCsvValue(row, "autoNumber"),
                NumberMode = GetCsvValue(row, "numberMode"),
                NumberSpace = NormalizeNumberSpace(GetCsvValue(row, "numberSpace")),
                ProgrammingLanguage = GetCsvValue(row, "programmingLanguage"),
                BlockType = GetCsvValue(row, "blockType"),
                TypeName = GetCsvValue(row, "typeName"),
                SourceTypeName = GetCsvValue(row, "sourceTypeName"),
                InstanceOfName = GetCsvValue(row, "instanceOfName"),
                InstanceOfNumber = GetCsvValue(row, "instanceOfNumber"),
                InstanceOfType = GetCsvValue(row, "instanceOfType"),
                SecondaryType = GetCsvValue(row, "secondaryType"),
                MemoryLayout = GetCsvValue(row, "memoryLayout"),
                IsConsistent = GetCsvValue(row, "isConsistent"),
                IsKnowHowProtected = GetCsvValue(row, "isKnowHowProtected"),
                TiaObjectIdStatus = GetCsvValue(row, "tiaObjectIdStatus"),
                FilePath = GetCsvValue(row, "filePath"),
                SourceSha256 = GetCsvValue(row, "sourceSha256"),
                NormalizedSourceSha256 = GetCsvValue(row, "normalizedSourceSha256"),
                Status = GetCsvValue(row, "status"),
                Message = GetCsvValue(row, "message")
            };
        }

        private static BlockLookupRecord BlockLookupRecordFromBlockCsv(Dictionary<string, string> row, string sourcePath)
        {
            string typeName = GetCsvValue(row, "TypeName");
            string language = GetCsvValue(row, "ProgrammingLanguage");
            return new BlockLookupRecord
            {
                SourcePath = sourcePath,
                SoftwarePath = GetCsvValue(row, "SoftwarePath"),
                GroupPath = RowGroupPathKey(row, "GroupPath"),
                GroupPathDisplay = RowGroupPathDisplay(row, "GroupPath"),
                Name = GetCsvValue(row, "Name"),
                Number = GetCsvValue(row, "Number"),
                AutoNumber = GetCsvValue(row, "AutoNumber"),
                NumberMode = GetCsvValue(row, "NumberMode"),
                NumberSpace = NormalizeNumberSpace(FirstNonEmpty(GetCsvValue(row, "NumberSpace"), BlockNumberSpace(typeName, language))),
                ProgrammingLanguage = language,
                BlockType = GetCsvValue(row, "BlockType"),
                TypeName = typeName,
                SourceTypeName = GetCsvValue(row, "SourceTypeName"),
                InstanceOfName = GetCsvValue(row, "InstanceOfName"),
                InstanceOfNumber = GetCsvValue(row, "InstanceOfNumber"),
                InstanceOfType = GetCsvValue(row, "InstanceOfType"),
                SecondaryType = GetCsvValue(row, "SecondaryType"),
                MemoryLayout = GetCsvValue(row, "MemoryLayout"),
                IsConsistent = GetCsvValue(row, "IsConsistent"),
                IsKnowHowProtected = GetCsvValue(row, "IsKnowHowProtected"),
                TiaObjectIdStatus = GetCsvValue(row, "TiaObjectIdStatus"),
                FilePath = GetCsvValue(row, "FilePath"),
                SourceSha256 = GetCsvValue(row, "SourceSha256"),
                NormalizedSourceSha256 = GetCsvValue(row, "NormalizedSourceSha256"),
                Status = GetCsvValue(row, "Status"),
                Message = GetCsvValue(row, "Message")
            };
        }

        private static BlockLookupRecord BlockLookupRecordFromCheckCsv(Dictionary<string, string> row, string sourcePath)
        {
            string typeName = FirstNonEmpty(GetCsvValue(row, "TypeName"), GetCsvValue(row, "CloneTypeName"), GetCsvValue(row, "CurrentTypeName"));
            string language = FirstNonEmpty(GetCsvValue(row, "ProgrammingLanguage"), GetCsvValue(row, "CloneProgrammingLanguage"), GetCsvValue(row, "CurrentProgrammingLanguage"));
            return new BlockLookupRecord
            {
                SourcePath = sourcePath,
                SoftwarePath = GetCsvValue(row, "SoftwarePath"),
                GroupPath = NormalizeLookupGroupPath(FirstNonEmpty(RowGroupPathKey(row, "GroupPath"), RowGroupPathKey(row, "CloneGroupPath"), RowGroupPathKey(row, "CurrentGroupPath"))),
                GroupPathDisplay = FirstNonEmpty(RowGroupPathDisplay(row, "GroupPath"), RowGroupPathDisplay(row, "CloneGroupPath"), RowGroupPathDisplay(row, "CurrentGroupPath")),
                Name = FirstNonEmpty(GetCsvValue(row, "Name"), GetCsvValue(row, "CloneName"), GetCsvValue(row, "CurrentName")),
                Number = FirstNonEmpty(GetCsvValue(row, "Number"), GetCsvValue(row, "CloneNumber"), GetCsvValue(row, "CurrentNumber")),
                AutoNumber = FirstNonEmpty(GetCsvValue(row, "AutoNumber"), GetCsvValue(row, "CloneAutoNumber"), GetCsvValue(row, "CurrentAutoNumber")),
                NumberMode = FirstNonEmpty(GetCsvValue(row, "NumberMode"), GetCsvValue(row, "CloneNumberMode"), GetCsvValue(row, "CurrentNumberMode")),
                NumberSpace = NormalizeNumberSpace(FirstNonEmpty(GetCsvValue(row, "NumberSpace"), GetCsvValue(row, "CloneNumberSpace"), GetCsvValue(row, "CurrentNumberSpace"), BlockNumberSpace(typeName, language))),
                ProgrammingLanguage = language,
                BlockType = FirstNonEmpty(GetCsvValue(row, "BlockType"), GetCsvValue(row, "CloneBlockType"), GetCsvValue(row, "CurrentBlockType")),
                TypeName = typeName,
                SourceTypeName = FirstNonEmpty(GetCsvValue(row, "SourceTypeName"), GetCsvValue(row, "CloneSourceTypeName"), GetCsvValue(row, "CurrentSourceTypeName")),
                InstanceOfName = FirstNonEmpty(GetCsvValue(row, "InstanceOfName"), GetCsvValue(row, "CloneInstanceOfName"), GetCsvValue(row, "CurrentInstanceOfName")),
                InstanceOfNumber = FirstNonEmpty(GetCsvValue(row, "InstanceOfNumber"), GetCsvValue(row, "CloneInstanceOfNumber"), GetCsvValue(row, "CurrentInstanceOfNumber")),
                InstanceOfType = FirstNonEmpty(GetCsvValue(row, "InstanceOfType"), GetCsvValue(row, "CloneInstanceOfType"), GetCsvValue(row, "CurrentInstanceOfType")),
                SecondaryType = FirstNonEmpty(GetCsvValue(row, "SecondaryType"), GetCsvValue(row, "CloneSecondaryType"), GetCsvValue(row, "CurrentSecondaryType")),
                MemoryLayout = FirstNonEmpty(GetCsvValue(row, "MemoryLayout"), GetCsvValue(row, "CloneMemoryLayout"), GetCsvValue(row, "CurrentMemoryLayout")),
                IsConsistent = FirstNonEmpty(GetCsvValue(row, "IsConsistent"), GetCsvValue(row, "CloneIsConsistent"), GetCsvValue(row, "CurrentIsConsistent")),
                IsKnowHowProtected = FirstNonEmpty(GetCsvValue(row, "IsKnowHowProtected"), GetCsvValue(row, "CloneIsKnowHowProtected"), GetCsvValue(row, "CurrentIsKnowHowProtected")),
                TiaObjectIdStatus = FirstNonEmpty(GetCsvValue(row, "TiaObjectIdStatus"), GetCsvValue(row, "CloneTiaObjectIdStatus"), GetCsvValue(row, "CurrentTiaObjectIdStatus")),
                FilePath = FirstNonEmpty(GetCsvValue(row, "ClonePath"), GetCsvValue(row, "CurrentPath"), GetCsvValue(row, "FilePath")),
                SourceSha256 = FirstNonEmpty(GetCsvValue(row, "SourceSha256"), GetCsvValue(row, "CloneSourceSha256"), GetCsvValue(row, "CurrentSourceSha256")),
                NormalizedSourceSha256 = FirstNonEmpty(GetCsvValue(row, "NormalizedSourceSha256"), GetCsvValue(row, "CloneNormalizedSourceSha256"), GetCsvValue(row, "CurrentNormalizedSourceSha256")),
                Status = GetCsvValue(row, "Status"),
                Message = GetCsvValue(row, "Message"),
                ClonePath = GetCsvValue(row, "ClonePath"),
                CurrentPath = GetCsvValue(row, "CurrentPath"),
                CloneRelativePath = GetCsvValue(row, "CloneRelativePath"),
                CurrentRelativePath = GetCsvValue(row, "CurrentRelativePath")
            };
        }

        private static void AddOrMergeBlockLookupRecord(List<BlockLookupRecord> records, Dictionary<string, BlockLookupRecord> byIdentity, BlockLookupRecord candidate)
        {
            if (candidate == null || string.IsNullOrWhiteSpace(candidate.Name))
            {
                return;
            }

            string key = BlockLookupIdentity(candidate);
            BlockLookupRecord existing;
            if (!byIdentity.TryGetValue(key, out existing))
            {
                records.Add(candidate);
                byIdentity[key] = candidate;
                return;
            }

            existing.SourcePath = MergeListValue(existing.SourcePath, candidate.SourcePath);
            existing.SoftwarePath = FirstNonEmpty(existing.SoftwarePath, candidate.SoftwarePath);
            existing.GroupPath = FirstNonEmpty(existing.GroupPath, candidate.GroupPath);
            existing.GroupPathDisplay = FirstNonEmpty(existing.GroupPathDisplay, candidate.GroupPathDisplay);
            existing.Number = FirstNonEmpty(existing.Number, candidate.Number);
            existing.AutoNumber = FirstNonEmpty(existing.AutoNumber, candidate.AutoNumber);
            existing.NumberMode = FirstNonEmpty(existing.NumberMode, candidate.NumberMode);
            existing.NumberSpace = FirstNonEmpty(existing.NumberSpace, candidate.NumberSpace);
            existing.ProgrammingLanguage = FirstNonEmpty(existing.ProgrammingLanguage, candidate.ProgrammingLanguage);
            existing.BlockType = FirstNonEmpty(existing.BlockType, candidate.BlockType);
            existing.TypeName = FirstNonEmpty(existing.TypeName, candidate.TypeName);
            existing.SourceTypeName = FirstNonEmpty(existing.SourceTypeName, candidate.SourceTypeName);
            existing.InstanceOfName = FirstNonEmpty(existing.InstanceOfName, candidate.InstanceOfName);
            existing.InstanceOfNumber = FirstNonEmpty(existing.InstanceOfNumber, candidate.InstanceOfNumber);
            existing.InstanceOfType = FirstNonEmpty(existing.InstanceOfType, candidate.InstanceOfType);
            existing.SecondaryType = FirstNonEmpty(existing.SecondaryType, candidate.SecondaryType);
            existing.MemoryLayout = FirstNonEmpty(existing.MemoryLayout, candidate.MemoryLayout);
            existing.IsConsistent = FirstNonEmpty(existing.IsConsistent, candidate.IsConsistent);
            existing.IsKnowHowProtected = FirstNonEmpty(existing.IsKnowHowProtected, candidate.IsKnowHowProtected);
            existing.TiaObjectIdStatus = FirstNonEmpty(existing.TiaObjectIdStatus, candidate.TiaObjectIdStatus);
            existing.FilePath = FirstNonEmpty(existing.FilePath, candidate.FilePath);
            existing.SourceSha256 = FirstNonEmpty(existing.SourceSha256, candidate.SourceSha256);
            existing.NormalizedSourceSha256 = FirstNonEmpty(existing.NormalizedSourceSha256, candidate.NormalizedSourceSha256);
            existing.Status = FirstNonEmpty(candidate.Status, existing.Status);
            existing.Message = FirstNonEmpty(candidate.Message, existing.Message);
            existing.ClonePath = FirstNonEmpty(existing.ClonePath, candidate.ClonePath);
            existing.CurrentPath = FirstNonEmpty(existing.CurrentPath, candidate.CurrentPath);
            existing.CloneRelativePath = FirstNonEmpty(existing.CloneRelativePath, candidate.CloneRelativePath);
            existing.CurrentRelativePath = FirstNonEmpty(existing.CurrentRelativePath, candidate.CurrentRelativePath);
        }

        private static string BlockLookupIdentity(BlockLookupRecord record)
        {
            return NormalizeLookupGroupPath(record.GroupPath)
                + "|" + EmptyIfNull(record.Name)
                + "|" + NormalizeNumberSpace(record.NumberSpace)
                + "|" + EmptyIfNull(record.Number);
        }

        private static string MergeListValue(string left, string right)
        {
            if (string.IsNullOrWhiteSpace(left))
            {
                return EmptyIfNull(right);
            }

            if (string.IsNullOrWhiteSpace(right) || left.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries).Any(x => EqualsIgnoreCase(x.Trim(), right.Trim())))
            {
                return left;
            }

            return left + "; " + right;
        }

        private static string NormalizeNumberSpace(string value)
        {
            return EmptyIfNull(value).Trim().ToUpperInvariant();
        }

        private static string NormalizeLookupGroupPath(string value)
        {
            return NormalizeGroupPathKey(value);
        }

        private static int BlockNumberSpaceSortKey(string value)
        {
            value = NormalizeNumberSpace(value);
            if (EqualsIgnoreCase(value, "OB")) return 1;
            if (EqualsIgnoreCase(value, "FB")) return 2;
            if (EqualsIgnoreCase(value, "FC")) return 3;
            if (EqualsIgnoreCase(value, "DB")) return 4;
            return 9;
        }

