                writer.WriteLine("    \"groupPath\": " + Json(EmptyIfNull(options.GroupPath)) + ",");
                writer.WriteLine("    \"groupPathKey\": " + Json(NormalizeLookupGroupPath(FirstNonEmpty(options.GroupPathKey, options.GroupPath))));
                writer.WriteLine("  },");
