        private static void WriteJsonl(string path, IEnumerable<Dictionary<string, string>> rows)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                foreach (Dictionary<string, string> row in rows)
                {
                    writer.WriteLine(JsonObject(row));
                }
            }
        }

        private static string JsonObject(Dictionary<string, string> row)
        {
            StringBuilder builder = new StringBuilder();
            builder.Append('{');
            int index = 0;
            foreach (KeyValuePair<string, string> pair in row)
            {
                if (index > 0)
                {
                    builder.Append(',');
                }

                builder.Append(Json(pair.Key));
                builder.Append(':');
                builder.Append(Json(pair.Value));
                index++;
            }

            builder.Append('}');
            return builder.ToString();
        }

        private static Dictionary<string, string> LoadSoftwarePathsByIdentity(string manifestPath)
        {
            Dictionary<string, string> result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (!File.Exists(manifestPath))
            {
                return result;
            }

            foreach (Dictionary<string, string> row in ReadCsv(manifestPath))
            {
                string key = BlockNumberSpace(GetCsvValue(row, "TypeName"), GetCsvValue(row, "ProgrammingLanguage")) + "|" + GetCsvValue(row, "Number") + "|" + GetCsvValue(row, "Name");
                if (!result.ContainsKey(key))
                {
                    result[key] = GetCsvValue(row, "SoftwarePath");
                }
            }

            return result;
        }

        private static string LoadFirstSoftwarePath(string manifestPath)
        {
            if (!File.Exists(manifestPath))
            {
                return string.Empty;
            }

            foreach (Dictionary<string, string> row in ReadCsv(manifestPath))
            {
                string value = GetCsvValue(row, "SoftwarePath");
                if (!string.IsNullOrWhiteSpace(value))
                {
                    return value;
                }
            }

            return string.Empty;
        }

        private static string FindLatestCompareDirectory(string outDir)
        {
            string summaryPath = Path.Combine(outDir, "clone-check-summary.txt");
            if (File.Exists(summaryPath))
            {
                foreach (string line in File.ReadAllLines(summaryPath, Encoding.UTF8))
                {
                    const string prefix = "Current export snapshot: ";
                    if (line.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                    {
                        string path = line.Substring(prefix.Length).Trim();
                        if (Directory.Exists(path))
                        {
                            return path;
                        }
                    }
                }
            }

            string compareRoot = Path.Combine(outDir, "_compare");
            if (!Directory.Exists(compareRoot))
            {
                throw new DirectoryNotFoundException("Compare directory was not found. Run check-clone first: " + compareRoot);
            }

            DirectoryInfo latest = new DirectoryInfo(compareRoot)
                .GetDirectories("current-*", SearchOption.TopDirectoryOnly)
                .OrderByDescending(x => x.LastWriteTimeUtc)
                .FirstOrDefault();
            if (latest == null)
            {
                throw new DirectoryNotFoundException("No current-* compare snapshots were found under: " + compareRoot);
            }

            return latest.FullName;
        }

        private static string UniquePath(string path)
        {
            if (!File.Exists(path) && !Directory.Exists(path))
            {
                return path;
            }

            string directory = Path.GetDirectoryName(path);
            string name = Path.GetFileNameWithoutExtension(path);
            string extension = Path.GetExtension(path);
            for (int i = 1; ; i++)
            {
                string candidate = Path.Combine(directory, name + "_" + i.ToString("000") + extension);
                if (!File.Exists(candidate) && !Directory.Exists(candidate))
                {
                    return candidate;
                }
            }
        }

        private static void EnsurePathInside(string path, string parentDirectory)
        {
            if (!IsPathInside(path, parentDirectory))
            {
                throw new InvalidOperationException("Path is outside the expected directory. Path: " + path + "; expected directory: " + parentDirectory);
            }
            EnsureExistingPathChainHasNoReparsePoints(parentDirectory, "expected directory");
            EnsureExistingPathChainHasNoReparsePoints(path, "confined path");
        }

        private static void EnsureExistingPathChainHasNoReparsePoints(string path, string context)
        {
            string fullPath = Path.GetFullPath(path);
            string root = Path.GetPathRoot(fullPath);
            string current = root;
            string remainder = fullPath.Substring(root.Length);
            foreach (string segment in remainder.Split(
                new[] { Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar },
                StringSplitOptions.RemoveEmptyEntries))
            {
                current = Path.Combine(current, segment);
                if (!File.Exists(current) && !Directory.Exists(current))
                {
                    // A later segment cannot exist if this one does not.
                    break;
                }
                if ((File.GetAttributes(current) & FileAttributes.ReparsePoint) != 0)
                {
                    throw new InvalidOperationException(
                        "Refusing a reparse point/symlink in " + context + ": " + current);
                }
            }
        }

        private static void EnsureExistingTreeHasNoReparsePoints(string rootPath, string context)
        {
            if (!Directory.Exists(rootPath))
            {
                return;
            }

            Stack<DirectoryInfo> pending = new Stack<DirectoryInfo>();
            pending.Push(new DirectoryInfo(rootPath));
            while (pending.Count > 0)
            {
                DirectoryInfo directory = pending.Pop();
                if ((directory.Attributes & FileAttributes.ReparsePoint) != 0)
                {
                    throw new InvalidOperationException("Refusing a reparse point/symlink in " + context + ": " + directory.FullName);
                }
                foreach (FileSystemInfo entry in directory.GetFileSystemInfos())
                {
                    if ((entry.Attributes & FileAttributes.ReparsePoint) != 0)
                    {
                        throw new InvalidOperationException("Refusing a reparse point/symlink in " + context + ": " + entry.FullName);
                    }
                    DirectoryInfo child = entry as DirectoryInfo;
                    if (child != null)
                    {
                        pending.Push(child);
                    }
                }
            }
        }

        private static void ValidateCloneWorkspacePhysicalIsolation(string outDir)
        {
            string fullOutDir = Path.GetFullPath(outDir);
            EnsureExistingPathChainHasNoReparsePoints(fullOutDir, "clone workspace path");
            EnsureExistingTreeHasNoReparsePoints(fullOutDir, "clone workspace");
        }

        private static bool IsPathInside(string path, string parentDirectory)
        {
            if (string.IsNullOrWhiteSpace(path) || string.IsNullOrWhiteSpace(parentDirectory))
            {
                return false;
            }

            string parent = AppendDirectorySeparator(Path.GetFullPath(parentDirectory));
            string child = Path.GetFullPath(path);
            return child.StartsWith(parent, StringComparison.OrdinalIgnoreCase)
                || EqualsIgnoreCase(child.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar), parent.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
        }

        private static void ExportXml(InventorySnapshot snapshot, string outDir, bool force)
        {
            Directory.CreateDirectory(outDir);
            List<string[]> report = new List<string[]>();

            foreach (BlockRecord block in snapshot.Blocks)
            {
                string relative = Path.Combine("blocks", SafeFilePath(block.GroupPath), SafeFileName(block.Number + "_" + block.Name + ".xml"));
                string filePath = Path.Combine(outDir, relative);
                ExportReportRow row = TryExportObject(block.Object, filePath, force);
                report.Add(new[] { "block", block.GroupPath, block.Name, filePath, row.Status, row.Message });
            }

            foreach (TagTableRecord table in snapshot.TagTables)
            {
                string relative = Path.Combine("tag-tables", SafeFilePath(table.GroupPath), SafeFileName(table.Name + ".xml"));
                string filePath = Path.Combine(outDir, relative);
                ExportReportRow row = TryExportObject(table.Object, filePath, force);
                report.Add(new[] { "tag-table", table.GroupPath, table.Name, filePath, row.Status, row.Message });
            }

            WriteCsv(Path.Combine(outDir, "export-report.csv"),
                new[] { "Kind", "GroupPath", "Name", "FilePath", "Status", "Message" },
                report);
        }

        private static void SystemBlocksProbe(InventorySnapshot snapshot, string outDir, Options options)
        {
            Directory.CreateDirectory(outDir);
            List<string[]> blockRows = new List<string[]>();
            List<string[]> exportRows = new List<string[]>();
            List<string[]> memberRows = new List<string[]>();
            List<object> modelObjects = new List<object>();

            object software = GetFirstPlcSoftware(snapshot);
            object blockGroup = TryGetPropertyValue(software, "BlockGroup");
            object systemBlockGroups = TryGetPropertyValue(blockGroup, "SystemBlockGroups");
            modelObjects.Add(systemBlockGroups);

            if (systemBlockGroups != null)
            {
                CollectSystemBlockGroupProbe(systemBlockGroups, string.Empty, options.Name, outDir, options.Force, blockRows, exportRows, memberRows, modelObjects);
            }

            WriteCsv(Path.Combine(outDir, "system-blocks.csv"),
                new[] { "GroupPath", "Name", "Number", "ProgrammingLanguage", "BlockType", "TypeName", "IsKnowHowProtected", "IsConsistent", "MemoryLayout", "ExportStatus", "ExportMessage", "XmlPath" },
                blockRows);

            WriteCsv(Path.Combine(outDir, "system-block-export-report.csv"),
                new[] { "GroupPath", "Name", "XmlPath", "Status", "Message" },
                exportRows);

            WriteCsv(Path.Combine(outDir, "system-block-interface-members.csv"),
                new[] { "Source", "GroupPath", "BlockName", "Section", "MemberPath", "Name", "Datatype", "Remanence", "Accessibility", "Informative", "Offset", "ComputedOffset", "Comment" },
                memberRows);

            using (StreamWriter writer = NewUtf8Writer(Path.Combine(outDir, "system-block-object-model.txt")))
            {
                WriteObjectProbe(writer, "Root BlockGroup", blockGroup);
                WriteObjectProbe(writer, "SystemBlockGroups", systemBlockGroups);
                int index = 0;
                foreach (object item in modelObjects.Where(x => x != null).Distinct().Take(12))
                {
                    WriteObjectProbe(writer, "Probe object " + index, item);
                    index++;
                }
            }
        }

        private static void CollectSystemBlockGroupProbe(
            object groups,
            string parentGroupPath,
            string nameFilter,
            string outDir,
            bool force,
            List<string[]> blockRows,
            List<string[]> exportRows,
            List<string[]> memberRows,
            List<object> modelObjects)
        {
            foreach (object group in AsEnumerable(groups))
            {
                string groupName = SafeName(group);
                string groupPath = CombineGroupPathKey(parentGroupPath, groupName);
                modelObjects.Add(group);

                object blocks = TryGetPropertyValue(group, "Blocks");
                if (blocks != null)
                {
                    modelObjects.Add(blocks);
                    foreach (object block in AsEnumerable(blocks))
                    {
                        string blockName = SafeName(block);
                        if (!string.IsNullOrWhiteSpace(nameFilter) && !EqualsIgnoreCase(blockName, nameFilter))
                        {
                            continue;
                        }

                        modelObjects.Add(block);
                        object blockInterface = TryGetPropertyValue(block, "Interface");
                        if (blockInterface != null)
                        {
                            modelObjects.Add(blockInterface);
                        }

                        string xmlPath = Path.Combine(outDir, "system-blocks", SafeFilePath(groupPath), SafeFileName(SafeGet(block, "Number") + "_" + blockName + ".xml"));
                        ExportReportRow export = TryExportObject(block, xmlPath, force);
                        exportRows.Add(new[] { groupPath, blockName, xmlPath, export.Status, export.Message });
                        if (EqualsIgnoreCase(export.Status, "ok") && File.Exists(xmlPath))
                        {
                            ParseSystemBlockInterfaceXml(xmlPath, groupPath, blockName, memberRows);
                        }

                        blockRows.Add(new[]
                        {
                            groupPath,
                            blockName,
                            SafeGet(block, "Number"),
                            SafeGet(block, "ProgrammingLanguage"),
                            SafeGet(block, "BlockType"),
                            block.GetType().FullName,
                            SafeGet(block, "IsKnowHowProtected"),
                            SafeGet(block, "IsConsistent"),
                            SafeGet(block, "MemoryLayout"),
                            export.Status,
                            export.Message,
                            xmlPath
                        });
                    }
                }

                object childGroups = TryGetPropertyValue(group, "Groups");
                if (childGroups == null)
                {
                    childGroups = TryGetPropertyValue(group, "SystemBlockGroups");
                }

                if (childGroups != null)
                {
                    modelObjects.Add(childGroups);
                    CollectSystemBlockGroupProbe(childGroups, groupPath, nameFilter, outDir, force, blockRows, exportRows, memberRows, modelObjects);
                }
            }
        }

        private static void ParseSystemBlockInterfaceXml(string xmlPath, string groupPath, string blockName, List<string[]> rows)
        {
            XmlDocument document = new XmlDocument();
            document.PreserveWhitespace = true;
            document.Load(xmlPath);

            int byteOffset = 0;
            int bitOffset = 0;
            foreach (XmlElement section in DescendantElements(document.DocumentElement).Where(x => EqualsIgnoreCase(x.LocalName, "Section")))
            {
                string sectionName = section.GetAttribute("Name");
                foreach (XmlElement member in ChildElements(section).Where(x => EqualsIgnoreCase(x.LocalName, "Member")))
                {
                    AddSystemBlockMemberRows(xmlPath, groupPath, blockName, sectionName, string.Empty, member, rows, ref byteOffset, ref bitOffset);
                }
            }
        }

        private static void AddSystemBlockMemberRows(
            string xmlPath,
            string groupPath,
            string blockName,
            string sectionName,
            string parentPath,
            XmlElement member,
            List<string[]> rows,
            ref int byteOffset,
            ref int bitOffset)
        {
            string name = member.GetAttribute("Name");
            string memberPath = string.IsNullOrEmpty(parentPath) ? name : parentPath + "." + name;
            string computedOffset = AllocateClassicMemberOffset(member.GetAttribute("Datatype"), ref byteOffset, ref bitOffset);
            rows.Add(new[]
            {
                xmlPath,
                groupPath,
                blockName,
                sectionName,
                memberPath,
                name,
                member.GetAttribute("Datatype"),
                member.GetAttribute("Remanence"),
                member.GetAttribute("Accessibility"),
                member.GetAttribute("Informative"),
                member.GetAttribute("Offset"),
                computedOffset,
                ExtractMemberComment(member)
            });

            foreach (XmlElement child in ChildElements(member).Where(x => EqualsIgnoreCase(x.LocalName, "Member")))
            {
                AddSystemBlockMemberRows(xmlPath, groupPath, blockName, sectionName, memberPath, child, rows, ref byteOffset, ref bitOffset);
            }

            foreach (XmlElement nestedSection in ChildElements(member).Where(x => EqualsIgnoreCase(x.LocalName, "Sections")).SelectMany(ChildElements).Where(x => EqualsIgnoreCase(x.LocalName, "Section")))
            {
                foreach (XmlElement child in ChildElements(nestedSection).Where(x => EqualsIgnoreCase(x.LocalName, "Member")))
                {
                    AddSystemBlockMemberRows(xmlPath, groupPath, blockName, sectionName, memberPath, child, rows, ref byteOffset, ref bitOffset);
                }
            }
        }

        private static string AllocateClassicMemberOffset(string datatype, ref int byteOffset, ref int bitOffset)
        {
            string normalized = (datatype ?? string.Empty).Trim();
            if (EqualsIgnoreCase(normalized, "Bool"))
            {
                if (bitOffset >= 8)
                {
                    byteOffset++;
                    bitOffset = 0;
                }

                string result = byteOffset.ToString(CultureInfo.InvariantCulture) + "." + bitOffset.ToString(CultureInfo.InvariantCulture);
                bitOffset++;
                return result;
            }

            if (bitOffset > 0)
            {
                byteOffset++;
                bitOffset = 0;
            }

            int size = ClassicDatatypeSize(normalized);
            if (ClassicDatatypeAlignment(normalized) > 1 && (byteOffset % 2) != 0)
            {
                byteOffset++;
            }

            string offset = byteOffset.ToString(CultureInfo.InvariantCulture) + ".0";
            byteOffset += size;
            return offset;
        }

        private static int ClassicDatatypeAlignment(string datatype)
        {
            if (EqualsIgnoreCase(datatype, "Byte") || EqualsIgnoreCase(datatype, "Char"))
            {
                return 1;
            }

            return 2;
        }

        private static int ClassicDatatypeSize(string datatype)
        {
            if (EqualsIgnoreCase(datatype, "Byte") || EqualsIgnoreCase(datatype, "Char"))
            {
                return 1;
            }

            if (EqualsIgnoreCase(datatype, "Word")
                || EqualsIgnoreCase(datatype, "Int")
                || EqualsIgnoreCase(datatype, "S5Time")
                || EqualsIgnoreCase(datatype, "Timer")
                || EqualsIgnoreCase(datatype, "Counter")
                || EqualsIgnoreCase(datatype, "Date"))
            {
                return 2;
            }

            if (EqualsIgnoreCase(datatype, "DWord")
                || EqualsIgnoreCase(datatype, "DInt")
                || EqualsIgnoreCase(datatype, "Real")
                || EqualsIgnoreCase(datatype, "Time")
                || EqualsIgnoreCase(datatype, "Time_Of_Day"))
            {
                return 4;
            }

            if (EqualsIgnoreCase(datatype, "LReal")
                || EqualsIgnoreCase(datatype, "Date_And_Time"))
            {
                return 8;
            }

            if (EqualsIgnoreCase(datatype, "Any"))
            {
                return 10;
            }

            return 0;
        }

        private static string ExtractMemberComment(XmlElement member)
        {
            foreach (XmlElement comment in ChildElements(member).Where(x => EqualsIgnoreCase(x.LocalName, "Comment")))
            {
                string text = CleanXmlText(comment.InnerText);
                if (!string.IsNullOrWhiteSpace(text))
                {
                    return text;
                }
            }

            return string.Empty;
        }

        private static void WriteObjectProbe(TextWriter writer, string label, object value)
        {
            writer.WriteLine(label + ":");
            if (value == null)
            {
                writer.WriteLine("  <not found>");
                writer.WriteLine();
                return;
            }

            writer.WriteLine("  Type: " + value.GetType().FullName);
            writer.WriteLine("  Name: " + SafeName(value));
            writer.WriteLine("  Count: " + SafeGet(value, "Count"));
            writer.WriteLine("  Properties:");
            foreach (PropertyInfo property in value.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance).OrderBy(x => x.Name))
            {
                writer.WriteLine("    " + property.Name + " : " + property.PropertyType.FullName + (property.CanWrite ? " writable" : string.Empty));
            }

            writer.WriteLine("  Enumerable preview:");
            int count = 0;
            foreach (object item in AsEnumerable(value).Take(8))
            {
                writer.WriteLine("    - " + SafeDescribe(item) + " [" + item.GetType().FullName + "]" + Details(item, new[] { "Name", "Number", "ProgrammingLanguage", "BlockType", "IsKnowHowProtected" }));
                count++;
            }

            if (count == 0)
            {
                writer.WriteLine("    <not enumerable or empty>");
            }

            writer.WriteLine("  Relevant methods:");
            foreach (MethodInfo method in value.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .Where(x => IsRelevantMethodName(x.Name))
                .OrderBy(x => x.Name))
            {
                writer.WriteLine("    " + DescribeMethod(method));
            }

            writer.WriteLine();
        }

        private static void ExportBlockDocuments(InventorySnapshot snapshot, string outDir, Options options)
        {
            Directory.CreateDirectory(outDir);
            List<string[]> report = new List<string[]>();
            List<BlockRecord> blocks = FindSelectedBlocks(snapshot, options);

            foreach (BlockRecord block in blocks)
            {
                string directory = Path.Combine(outDir, "blocks", SafeFilePath(block.GroupPath), SafeFileName(block.Number + "_" + block.Name));
                string fileNameWithoutExtension = SafeFileName(block.Number + "_" + block.Name);
                ExportReportRow row = TryExportBlockDocuments(block.Object, directory, fileNameWithoutExtension);
                string exportedFiles = string.Join(";", Directory.Exists(directory)
                    ? Directory.GetFiles(directory, "*", SearchOption.AllDirectories).OrderBy(x => x).ToArray()
                    : new string[0]);

                report.Add(new[]
                {
                    block.GroupPath,
                    block.Name,
                    block.ProgrammingLanguage,
                    directory,
                    row.Status,
                    row.Message,
                    exportedFiles
                });
            }

            WriteCsv(Path.Combine(outDir, "document-export-report.csv"),
                new[] { "GroupPath", "Name", "ProgrammingLanguage", "Directory", "Status", "Message", "ExportedFiles" },
                report);
        }

        private static void ExportBlockSources(InventorySnapshot snapshot, string outDir, Options options)
        {
            Directory.CreateDirectory(outDir);
            object software = GetFirstPlcSoftware(snapshot);
            object externalSourceGroup = TryGetPropertyValue(software, "ExternalSourceGroup");
            if (externalSourceGroup == null)
            {
                throw new InvalidOperationException("PLC software does not expose ExternalSourceGroup.");
            }

            Type generateSourceType = FindType("Siemens.Engineering.SW.ExternalSources.IGenerateSource");
            MethodInfo generateSource = FindGenerateSourceMethod(externalSourceGroup);

            List<string[]> report = new List<string[]>();
            List<BlockRecord> blocks = FindSelectedBlocks(snapshot, options);

            foreach (BlockRecord block in blocks)
            {
                string extension = NormalizeExtension(string.IsNullOrWhiteSpace(options.Extension)
                    ? DefaultSourceExtension(block.ProgrammingLanguage)
                    : options.Extension);
                string filePath = Path.Combine(outDir, "blocks", SafeFilePath(block.GroupPath), SafeFileName(block.Number + "_" + block.Name + extension));
                ExportReportRow row = TryGenerateSourceFile(externalSourceGroup, generateSource, generateSourceType, block.Object, filePath, options.Force);
                report.Add(new[]
                {
                    block.GroupPath,
                    block.Name,
                    block.ProgrammingLanguage,
                    filePath,
                    row.Status,
                    row.Message
                });
            }

            WriteCsv(Path.Combine(outDir, "source-export-report.csv"),
                new[] { "GroupPath", "Name", "ProgrammingLanguage", "FilePath", "Status", "Message" },
                report);
        }

        private static MethodInfo FindGenerateSourceMethod(object externalSourceGroup)
        {
            MethodInfo generateSource = externalSourceGroup.GetType()
                .GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .Where(x => x.Name == "GenerateSource")
                .OrderBy(x => x.GetParameters().Length)
                .FirstOrDefault(x =>
                {
                    ParameterInfo[] parameters = x.GetParameters();
                    return parameters.Length >= 2 && parameters[1].ParameterType == typeof(FileInfo);
                });

            if (generateSource == null)
            {
                throw new MissingMethodException(externalSourceGroup.GetType().FullName, "GenerateSource");
            }

            return generateSource;
        }

        private static List<BlockRecord> FindSelectedBlocks(InventorySnapshot snapshot, Options options)
        {
            IEnumerable<BlockRecord> blocks = snapshot.Blocks;
            if (!string.IsNullOrWhiteSpace(options.Name))
            {
                blocks = blocks.Where(x => EqualsIgnoreCase(x.Name, options.Name));
            }

            if (!string.IsNullOrWhiteSpace(options.GroupPath))
            {
                string groupPath = NormalizeGroupPathKey(FirstNonEmpty(options.GroupPathKey, options.GroupPath));
                string groupDisplay = EmptyIfNull(options.GroupPath).Trim('/').Trim('\\');
                blocks = blocks.Where(x => EqualsIgnoreCase(EmptyIfNull(x.GroupPath), groupPath) || EqualsIgnoreCase(EmptyIfNull(x.GroupPathDisplay), groupDisplay));
            }

            List<BlockRecord> selected = blocks.ToList();
            if (selected.Count == 0)
            {
                throw new InvalidOperationException("No matching PLC blocks were found.");
            }

            return selected;
        }

        private static ExportReportRow TryExportBlockDocuments(object block, string directory, string fileNameWithoutExtension)
        {
            Directory.CreateDirectory(directory);
            MethodInfo method = block.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(x =>
                {
                    if (x.Name != "ExportAsDocuments")
                    {
                        return false;
                    }

                    ParameterInfo[] parameters = x.GetParameters();
                    return parameters.Length == 2
                        && parameters[0].ParameterType == typeof(DirectoryInfo)
                        && parameters[1].ParameterType == typeof(string);
                });

            if (method == null)
            {
                return new ExportReportRow("error", "No compatible ExportAsDocuments(DirectoryInfo,string) method was found.");
            }

            try
            {
                object result = method.Invoke(block, new object[] { new DirectoryInfo(directory), fileNameWithoutExtension });
                string state = SafeGet(result, "State");
                string resultText = string.IsNullOrEmpty(state) ? SafeDescribe(result) : "State=" + state;
                return new ExportReportRow("ok", resultText);
            }
            catch (TargetInvocationException ex)
            {
                Exception inner = ex.InnerException ?? ex;
                return new ExportReportRow("error", inner.GetType().Name + ": " + inner.Message);
            }
            catch (Exception ex)
            {
                return new ExportReportRow("error", ex.GetType().Name + ": " + ex.Message);
            }
        }

        private static ExportReportRow TryGenerateSourceFile(object externalSourceGroup, MethodInfo generateSource, Type generateSourceType, object block, string filePath, bool force)
        {
            if (!generateSourceType.IsAssignableFrom(block.GetType()))
            {
                return new ExportReportRow("skipped", "Block type does not implement IGenerateSource.");
            }

            if (File.Exists(filePath) && !force)
            {
                return new ExportReportRow("skipped", "File already exists. Use --force to overwrite.");
            }

            Directory.CreateDirectory(Path.GetDirectoryName(filePath));
            if (File.Exists(filePath))
            {
                File.Delete(filePath);
            }

            Array blocks = Array.CreateInstance(generateSourceType, 1);
            blocks.SetValue(block, 0);

            try
            {
                ParameterInfo[] parameters = generateSource.GetParameters();
                object[] arguments = parameters.Length == 2
                    ? new object[] { blocks, new FileInfo(filePath) }
                    : new object[] { blocks, new FileInfo(filePath), ChooseEnumValue(parameters[2].ParameterType, new[] { "None" }) };

                generateSource.Invoke(externalSourceGroup, arguments);
                return File.Exists(filePath)
                    ? new ExportReportRow("ok", "Generated with " + DescribeMethod(generateSource))
                    : new ExportReportRow("error", "GenerateSource returned without creating the expected source file: " + filePath);
            }
            catch (TargetInvocationException ex)
            {
                Exception inner = ex.InnerException ?? ex;
                return new ExportReportRow("error", inner.GetType().Name + ": " + inner.Message);
            }
            catch (Exception ex)
            {
                return new ExportReportRow("error", ex.GetType().Name + ": " + ex.Message);
            }
        }

        private static ExportReportRow TryExportObject(object target, string filePath, bool force)
        {
            if (target == null)
            {
                return new ExportReportRow("error", "Target is null.");
            }

            if (File.Exists(filePath) && !force)
            {
                return new ExportReportRow("skipped", "File already exists. Use --force to overwrite.");
            }

            Directory.CreateDirectory(Path.GetDirectoryName(filePath));
            if (File.Exists(filePath))
            {
                File.Delete(filePath);
            }

            string lastError = null;
            foreach (MethodInfo method in target.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance).Where(x => x.Name == "Export"))
            {
                object[] arguments;
                if (!TryCreateArguments(method.GetParameters(), filePath, out arguments))
                {
                    continue;
                }

                try
                {
                    method.Invoke(target, arguments);
                    return File.Exists(filePath)
                        ? new ExportReportRow("ok", "Exported with " + DescribeMethod(method))
                        : new ExportReportRow("ok", "Export invoked with " + DescribeMethod(method) + "; expected file was not created.");
                }
                catch (TargetInvocationException ex)
                {
                    lastError = (ex.InnerException ?? ex).GetType().Name + ": " + (ex.InnerException ?? ex).Message;
                }
                catch (Exception ex)
                {
                    lastError = ex.GetType().Name + ": " + ex.Message;
                }
            }

            return new ExportReportRow("error", string.IsNullOrEmpty(lastError) ? "No compatible Export method was found." : lastError);
        }

        private static bool TryCreateArguments(ParameterInfo[] parameters, string filePath, out object[] arguments)
        {
            arguments = new object[parameters.Length];
            for (int i = 0; i < parameters.Length; i++)
            {
                Type parameterType = parameters[i].ParameterType;
                if (parameterType == typeof(FileInfo))
                {
                    arguments[i] = new FileInfo(filePath);
                }
                else if (parameterType == typeof(DirectoryInfo))
                {
                    arguments[i] = new DirectoryInfo(Path.GetDirectoryName(filePath));
                }
                else if (parameterType == typeof(string))
                {
                    arguments[i] = filePath;
                }
                else if (parameterType == typeof(bool))
                {
                    arguments[i] = false;
                }
                else if (parameterType.IsEnum)
                {
                    arguments[i] = ChooseEnumValue(parameterType, new[] { "WithDefaults", "None", "NoOptions" });
                }
                else if (parameters[i].IsOptional)
                {
                    arguments[i] = parameters[i].DefaultValue;
                }
                else
                {
                    return false;
                }
            }

            return true;
        }

        private static object ChooseEnumValue(Type enumType, string[] preferredNames)
        {
            string[] names = Enum.GetNames(enumType);
            foreach (string preferred in preferredNames)
            {
                foreach (string name in names)
                {
                    if (EqualsIgnoreCase(name, preferred))
                    {
                        return Enum.Parse(enumType, name);
                    }
                }
            }

            return names.Length == 0 ? Enum.ToObject(enumType, 0) : Enum.Parse(enumType, names[0]);
        }

        private static void InspectSnapshot(InventorySnapshot snapshot)
        {
            Console.WriteLine("Project inventory:");
            Console.WriteLine("  Devices/items/software: " + snapshot.Devices.Count);
            Console.WriteLine("  Blocks: " + snapshot.Blocks.Count);
            Console.WriteLine("  Tag tables: " + snapshot.TagTables.Count);
            Console.WriteLine("  Tags: " + snapshot.Tags.Count);
            Console.WriteLine();

            InspectFirstSoftwareContainer(snapshot);
            InspectObject("First block", snapshot.Blocks.Count == 0 ? null : snapshot.Blocks[0].Object);
            InspectObject("First tag table", snapshot.TagTables.Count == 0 ? null : snapshot.TagTables[0].Object);
            InspectObject("First tag", snapshot.Tags.Count == 0 ? null : snapshot.Tags[0].Object);
        }

        private static void InspectFirstSoftwareContainer(InventorySnapshot snapshot)
        {
            DeviceRecord softwareRecord = snapshot.Devices.FirstOrDefault(x => EqualsIgnoreCase(x.Kind, "Software"));
            if (softwareRecord == null || softwareRecord.Object == null)
            {
                return;
            }

            object blockGroup = TryGetPropertyValue(softwareRecord.Object, "BlockGroup");
            InspectObject("Root block group", blockGroup);
            InspectObject("Root block composition", TryGetPropertyValue(blockGroup, "Blocks"));
            InspectObject("Root block-group composition", TryGetPropertyValue(blockGroup, "Groups"));
        }

        private static void InspectObject(string label, object value)
        {
            Console.WriteLine(label + ":");
            if (value == null)
            {
                Console.WriteLine("  <not found>");
                Console.WriteLine();
                return;
            }

            Console.WriteLine("  Type: " + value.GetType().FullName);
            Console.WriteLine("  Name: " + SafeName(value));
            Console.WriteLine("  Properties:");
            foreach (PropertyInfo property in value.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance).OrderBy(x => x.Name))
            {
                Console.WriteLine("    " + property.Name + " : " + property.PropertyType.FullName + (property.CanWrite ? " writable" : ""));
            }

            Console.WriteLine("  Relevant methods:");
            foreach (MethodInfo method in value.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .Where(x => IsRelevantMethodName(x.Name))
                .OrderBy(x => x.Name))
            {
                Console.WriteLine("    " + DescribeMethod(method));
            }

            Console.WriteLine();
        }

        private static bool IsRelevantMethodName(string name)
        {
            return name.IndexOf("Export", StringComparison.OrdinalIgnoreCase) >= 0
                || name.IndexOf("Import", StringComparison.OrdinalIgnoreCase) >= 0
                || name.IndexOf("Create", StringComparison.OrdinalIgnoreCase) >= 0
                || name.IndexOf("Delete", StringComparison.OrdinalIgnoreCase) >= 0
                || name.IndexOf("Attribute", StringComparison.OrdinalIgnoreCase) >= 0
                || name.IndexOf("Compile", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static void SetAttributeCommand(object project, Options options)
        {
            if (string.IsNullOrWhiteSpace(options.TargetKind)
                || string.IsNullOrWhiteSpace(options.Name)
                || string.IsNullOrWhiteSpace(options.AttributeName))
            {
                throw new ArgumentException("set-attribute requires --target, --name, --attribute, and usually --value.");
            }

            InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
            List<object> matches = FindTargets(snapshot, options.TargetKind, options.Name, options.GroupPath);
            if (matches.Count == 0)
            {
                throw new InvalidOperationException("No matching target was found.");
            }

            if (matches.Count > 1)
            {
                Console.WriteLine("More than one target matched. Add --group to narrow it down.");
                foreach (object match in matches.Take(20))
                {
                    Console.WriteLine("  - " + SafeDescribe(match));
                }

                throw new InvalidOperationException("Ambiguous target.");
            }

            object target = matches[0];
            object oldValue = TryReadAttribute(target, options.AttributeName);
            Console.WriteLine("Target type: " + target.GetType().FullName);
            Console.WriteLine("Target name: " + SafeName(target));
            Console.WriteLine("Attribute: " + options.AttributeName);
            Console.WriteLine("Old value: " + SafeDescribe(oldValue));
            Console.WriteLine("New value: " + options.Value);

            if (!options.Apply)
            {
                Console.WriteLine();
                Console.WriteLine("Dry-run only. Re-run with --apply to write.");
                return;
            }

            WriteAttribute(target, options.AttributeName, options.Value, oldValue);
            Console.WriteLine("Attribute written.");

            if (options.Save)
            {
                SaveProject(project);
                Console.WriteLine("Project saved.");
            }
            else
            {
                Console.WriteLine("Project was not saved. Use --save to persist the change.");
            }
        }

        private static void CompileBlockCommand(object project, Options options)
        {
            if (string.IsNullOrWhiteSpace(options.Name))
            {
                throw new ArgumentException("compile-block requires --name.");
            }

            InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
            List<object> matches = FindTargets(snapshot, "block", options.Name, options.GroupPath);
            if (matches.Count == 0)
            {
                throw new InvalidOperationException("No matching block was found.");
            }

            if (matches.Count > 1)
            {
                throw new InvalidOperationException("More than one matching block was found. Add --group.");
            }

            object block = matches[0];
            Console.WriteLine("Compile block");
            Console.WriteLine("  Name: " + SafeName(block));
            Console.WriteLine("  Type: " + block.GetType().FullName);
            Console.WriteLine("  IsConsistent before: " + SafeGet(block, "IsConsistent"));

            if (!options.Apply)
            {
                Console.WriteLine();
                Console.WriteLine("Dry-run only. Re-run with --apply to compile.");
                return;
            }

            TryCompileAndPrint(block);
            Console.WriteLine("  IsConsistent after: " + SafeGet(block, "IsConsistent"));

            if (options.Save)
            {
                SaveProject(project);
                Console.WriteLine("Project saved.");
            }
            else
            {
                Console.WriteLine("Project was not saved. Use --save to persist the compile result.");
            }
        }

        private static void CompileAllCommand(object project, Options options)
        {
            InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
            List<CompileTargetRecord> targets = BuildCompileAllTargets(project, snapshot);

            Console.WriteLine("Compile all");
            Console.WriteLine("  Project: " + snapshot.ProjectName);
            Console.WriteLine("  Strategy: " + (targets.Count == 1 && EqualsIgnoreCase(targets[0].Kind, "Project") ? "project CompileProvider" : "software CompileProvider fallback"));
            Console.WriteLine("  Compile targets: " + targets.Count.ToString(CultureInfo.InvariantCulture));
            foreach (CompileTargetRecord target in targets)
            {
                Console.WriteLine("  - " + target.Kind + ": " + target.Path);
                Console.WriteLine("    Type: " + target.TypeName);
            }

            if (targets.Count == 0)
            {
                throw new InvalidOperationException("No compile-capable project or software target was found through Siemens.Engineering.Compiler.CompileProvider.");
            }

            if (!options.Apply)
            {
                Console.WriteLine();
                Console.WriteLine("Dry-run only. Re-run with --apply to compile all targets.");
                return;
            }

            int totalErrors = 0;
            int totalWarnings = 0;
            foreach (CompileTargetRecord target in targets)
            {
                Console.WriteLine();
                Console.WriteLine("Compile target: " + target.Kind + " " + target.Path);
                object result = TryCompileAndPrint(target.Object);
                totalErrors += CompilerResultCount(result, "ErrorCount");
                totalWarnings += CompilerResultCount(result, "WarningCount");
            }

            Console.WriteLine();
            Console.WriteLine("Compile-all summary:");
            Console.WriteLine("  Targets: " + targets.Count.ToString(CultureInfo.InvariantCulture));
            Console.WriteLine("  Errors: " + totalErrors.ToString(CultureInfo.InvariantCulture));
            Console.WriteLine("  Warnings: " + totalWarnings.ToString(CultureInfo.InvariantCulture));

            if (totalErrors > 0)
            {
                throw new InvalidOperationException("Compile-all finished with errors: " + totalErrors.ToString(CultureInfo.InvariantCulture));
            }

            if (options.Save)
            {
                SaveProject(project);
                Console.WriteLine("Project saved.");
            }
            else
            {
                Console.WriteLine("Project was not saved. Use --save to persist the compile result.");
            }
        }

        private static List<CompileTargetRecord> BuildCompileAllTargets(object project, InventorySnapshot snapshot)
        {
            List<CompileTargetRecord> targets = new List<CompileTargetRecord>();
            if (TryGetCompiler(project) != null)
            {
                targets.Add(new CompileTargetRecord
                {
                    Kind = "Project",
                    Path = FirstNonEmpty(snapshot.ProjectName, "Project"),
                    TypeName = project.GetType().FullName,
                    Object = project
                });
                return targets;
            }

            foreach (DeviceRecord record in snapshot.Devices.Where(x => EqualsIgnoreCase(x.Kind, "Software") && x.Object != null))
            {
                if (TryGetCompiler(record.Object) == null)
                {
                    continue;
                }

                targets.Add(new CompileTargetRecord
                {
                    Kind = record.SoftwareType != null && record.SoftwareType.IndexOf("PlcSoftware", StringComparison.OrdinalIgnoreCase) >= 0 ? "PlcSoftware" : "Software",
                    Path = record.Path,
                    TypeName = record.SoftwareType,
                    Object = record.Object
                });
            }

            return targets;
        }

        private static void CompileAllForApply(
            object project,
            InventorySnapshot snapshot,
            out int targetCount,
            out int errorCount,
            out int warningCount)
        {
            List<CompileTargetRecord> targets = BuildCompileAllTargets(project, snapshot);
            targetCount = targets.Count;
            errorCount = 0;
            warningCount = 0;
            if (targets.Count == 0)
            {
                throw new InvalidOperationException("apply-clone cannot save because no compile-capable project or software target was found.");
            }

            Console.WriteLine();
            Console.WriteLine("Compile before apply-clone save");
            foreach (CompileTargetRecord target in targets)
            {
                Console.WriteLine("Compile target: " + target.Kind + " " + target.Path);
                object result = TryCompileAndPrint(target.Object);
                if (result == null)
                {
                    throw new InvalidOperationException("Compile target returned no auditable CompilerResult: " + target.Path);
                }
                errorCount += RequiredCompilerResultCount(result, "ErrorCount", target.Path);
                warningCount += RequiredCompilerResultCount(result, "WarningCount", target.Path);
            }
            Console.WriteLine("Apply compile summary: targets=" + targetCount.ToString(CultureInfo.InvariantCulture)
                + "; errors=" + errorCount.ToString(CultureInfo.InvariantCulture)
                + "; warnings=" + warningCount.ToString(CultureInfo.InvariantCulture));
        }

        private static void ApplyCloneCommand(object project, Options options)
        {
            string outDir = ResolveCloneProjectDirectory(options.OutDir);
            using (AcquireCloneWorkspaceLock(outDir, "apply-clone"))
            {
                using (AcquireTiaExclusiveAccess(
                    options.Apply
                        ? "OpennessLLM apply-clone safety transaction"
                        : "OpennessLLM authoritative apply-clone dry-run"))
                {
                    ApplyCloneCommandLocked(project, options, outDir);
                }
            }
        }

        private static IDisposable AcquireTiaExclusiveAccess(string text)
        {
            if (_tiaPortal == null)
            {
                throw new InvalidOperationException("This authoritative TIA operation requires the owning TiaPortal object so ExclusiveAccess can be held for the complete snapshot or write interval.");
            }

            MethodInfo method = _tiaPortal.GetType().GetMethod(
                "ExclusiveAccess",
                BindingFlags.Public | BindingFlags.Instance,
                null,
                new[] { typeof(string) },
                null)
                ?? _tiaPortal.GetType().GetMethod(
                    "ExclusiveAccess",
                    BindingFlags.Public | BindingFlags.Instance,
                    null,
                    Type.EmptyTypes,
                    null);
            if (method == null)
            {
                throw new MissingMethodException(_tiaPortal.GetType().FullName, "ExclusiveAccess");
            }

            object access = method.GetParameters().Length == 0
                ? method.Invoke(_tiaPortal, null)
                : method.Invoke(_tiaPortal, new object[] { text });
            IDisposable disposable = access as IDisposable;
            if (disposable == null)
            {
                throw new InvalidOperationException("TIA Portal ExclusiveAccess did not return a disposable exclusive-access lease.");
            }

            return disposable;
        }

        private static IDisposable AcquireCloneWorkspaceLock(string outDir, string operation)
        {
            string fullOutDir = Path.GetFullPath(outDir);
            Directory.CreateDirectory(fullOutDir);
            string key = NormalizeComparablePath(fullOutDir).ToUpperInvariant();
            int ownerThreadId = System.Threading.Thread.CurrentThread.ManagedThreadId;
            lock (CloneWorkspaceLockGuard)
            {
                CloneWorkspaceLockState existing;
                if (CloneWorkspaceLocks.TryGetValue(key, out existing))
                {
                    if (existing.OwnerThreadId != ownerThreadId)
                    {
                        throw new InvalidOperationException("Clone workspace is already locked by another operation in this process: " + outDir);
                    }
                    existing.Depth++;
                    return new CloneWorkspaceLockLease(key);
                }

                // The lock lives in the workspace so case and ordinary path
                // aliases resolve to the same filesystem object. Clone entry
                // points and descendants are separately required to contain no
                // junction/symlink/reparse point. The lock is deliberately
                // excluded from signed inventory and _root transactions.
                string lockPath = Path.Combine(fullOutDir, CloneWorkspaceLockFileName);
                FileStream stream;
                try
                {
                    stream = new FileStream(lockPath, FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None);
                    stream.SetLength(0);
                    byte[] owner = Encoding.UTF8.GetBytes(
                        "operation=" + EmptyIfNull(operation) + Environment.NewLine
                        + "workspace=" + key + Environment.NewLine
                        + "started=" + DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) + Environment.NewLine);
                    stream.Write(owner, 0, owner.Length);
                    stream.Flush(true);
                }
                catch (IOException ex)
                {
                    throw new InvalidOperationException(
                        "Clone workspace is locked by another init/check/apply/sync process: " + outDir,
                        ex);
                }

                CloneWorkspaceLocks.Add(key, new CloneWorkspaceLockState { Stream = stream, Depth = 1, OwnerThreadId = ownerThreadId });
                try
                {
                    // Every clone command repairs or rejects a durable partial
                    // publication before it is allowed to inspect or mutate the
                    // workspace.
                    RecoverIncompletePublication(fullOutDir, true);
                    return new CloneWorkspaceLockLease(key);
                }
                catch
                {
                    CloneWorkspaceLocks.Remove(key);
                    stream.Dispose();
                    throw;
                }
            }
        }

        private static void ReleaseCloneWorkspaceLock(string key)
        {
            lock (CloneWorkspaceLockGuard)
            {
                CloneWorkspaceLockState state;
                if (!CloneWorkspaceLocks.TryGetValue(key, out state))
                {
                    return;
                }

                state.Depth--;
                if (state.Depth <= 0)
                {
                    CloneWorkspaceLocks.Remove(key);
                    state.Stream.Dispose();
                }
            }
        }

        private static void ApplyCloneCommandLocked(object project, Options options, string outDir)
        {
            string rootDir = Path.Combine(outDir, "_root");
            string blockReportPath = Path.Combine(outDir, "clone-check-blocks.csv");
            string sourceBlockerReportPath = Path.Combine(outDir, "clone-check-source-blockers.csv");
            List<ApplyCloneGateRecord> gates = new List<ApplyCloneGateRecord>();
            List<ApplyCloneOperationRecord> operations = new List<ApplyCloneOperationRecord>();
            List<ApplyPlanItem> plan = new List<ApplyPlanItem>();
            ApplyPreflightResult preflight = new ApplyPreflightResult();

            Directory.CreateDirectory(outDir);

            AddApplyCloneGate(
                gates,
                "before-write",
                "command-intent",
                EqualsIgnoreCase(options.Command, "apply-clone") ? "passed" : "failed",
                true,
                true,
                false,
                options.Apply ? "Real PLC clone apply was explicitly requested by --apply." : "Authoritative dry-run mode: all read-side safety proofs run, but no TIA write method will be invoked.",
                outDir,
                "command=apply-clone",
                "command=" + EmptyIfNull(options.Command) + "; --apply=" + options.Apply + "; --save=" + options.Save);

            AddApplyCloneGate(
                gates,
                "before-write",
                "tia-exclusive-access",
                "passed",
                true,
                true,
                false,
                options.Apply
                    ? "TIA Portal ExclusiveAccess is held for preflight, mutation, exact postcondition checks, compilation, Save(), and post-save snapshot."
                    : "TIA Portal ExclusiveAccess is held for the complete authoritative dry-run snapshot.",
                options.ProjectPath,
                "exclusive access held",
                "held");

            AddApplyCloneGate(
                gates,
                "before-write",
                "backup-required",
                options.Apply && options.NoBackup ? "failed" : "passed",
                true,
                true,
                false,
                options.Apply && options.NoBackup ? "Production apply-clone cannot run with --no-backup." : "Backup policy is compatible with this apply-clone invocation.",
                options.ProjectPath,
                "if --apply=true then --no-backup=false",
                "--apply=" + options.Apply + "; --no-backup=" + options.NoBackup);

            AddApplyCloneGate(
                gates,
                "before-write",
                "save-required",
                options.Apply && !options.Save ? "failed" : "passed",
                true,
                true,
                false,
                options.Apply && !options.Save
                    ? "Real apply-clone requires --save so TIA durability is established before the local baseline is published."
                    : "Save policy is compatible with this invocation.",
                options.ProjectPath,
                "if --apply=true then --save=true",
                "--apply=" + options.Apply + "; --save=" + options.Save);

            if (!Directory.Exists(rootDir))
            {
                AddApplyCloneGate(gates, "before-write", "workspace-reports", "failed", true, true, false, "Clone root was not found. Run init-clone first.", rootDir, "existing _root directory", "missing");
                WriteApplyClonePreflightReports(outDir, plan, preflight.Issues);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, false, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                throw new DirectoryNotFoundException("Clone root was not found. Run init-clone first: " + rootDir);
            }

            CloneCheckBundleEvidence bundle;
            try
            {
                bundle = LoadAndValidateCloneCheckBundle(outDir);
            }
            catch (Exception ex)
            {
                AddApplyCloneGate(gates, "before-write", "workspace-reports", "failed", true, true, false, "Clone-check evidence bundle is missing, incomplete, or inconsistent: " + ex.Message, Path.Combine(outDir, CloneCheckBundleFileName), "complete bundle with matching run IDs, hashes, and row counts", ex.GetType().Name + ": " + ex.Message);
                WriteApplyClonePreflightReports(outDir, plan, preflight.Issues);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, false, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                throw new InvalidOperationException("apply-clone requires a complete, self-consistent clone-check bundle. Run check-clone again.", ex);
            }

            AddApplyCloneGate(gates, "before-write", "workspace-reports", "passed", true, true, false, "Clone root and atomic clone-check evidence bundle are valid.", Path.Combine(outDir, CloneCheckBundleFileName), "matching schema/run IDs, hashes, and row counts", "run=" + bundle.CheckRunId);

            InventorySnapshot rawSnapshot;
            InventorySnapshot snapshot;
            DeviceRecord softwareRecord;
            try
            {
                rawSnapshot = CollectInventory(project, options.ProjectPath);
                softwareRecord = ValidateCloneCheckBundleTarget(bundle, rawSnapshot);
                snapshot = FilterInventoryBySoftwarePath(rawSnapshot, softwareRecord.Path);
            }
            catch (Exception ex)
            {
                AddApplyCloneGate(gates, "before-write", "target-identity", "failed", true, true, false, "Clone-check evidence does not authorize this open project/PLC: " + ex.Message, Path.Combine(outDir, CloneCheckBundleFileName), "same normalized project path/version/stable ID and exactly one matching PlcSoftware", ex.GetType().Name + ": " + ex.Message);
                WriteApplyClonePreflightReports(outDir, plan, preflight.Issues);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, false, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                throw new InvalidOperationException("apply-clone clone-check target identity validation failed before plan construction.", ex);
            }

            AddApplyCloneGate(
                gates,
                "before-write",
                "target-identity",
                "passed",
                true,
                true,
                false,
                "Clone-check evidence is bound to this open project and its only PlcSoftware.",
                Path.Combine(outDir, CloneCheckBundleFileName),
                "same normalized project path/version/stable ID and exactly one matching PlcSoftware",
                "project=" + snapshot.ProjectPath + "; softwarePath=" + softwareRecord.Path);

            bool? projectDirtyBeforeApply = TryReadProjectIsModified(project);
            bool dirtyStateAccepted = ProjectDirtyStateAllowsApply(
                projectDirtyBeforeApply,
                options.AcceptSavingPreexistingProjectChanges);
            string dirtyActual = projectDirtyBeforeApply.HasValue
                ? "Project.IsModified=" + projectDirtyBeforeApply.Value.ToString()
                : "Project.IsModified=unavailable";
            if (options.AcceptSavingPreexistingProjectChanges)
            {
                dirtyActual += "; explicit unsafe override=true";
            }
            AddApplyCloneGate(
                gates,
                "before-write",
                "project-clean-before-apply",
                dirtyStateAccepted ? "passed" : "failed",
                true,
                true,
                false,
                projectDirtyBeforeApply == false
                        ? "Project.IsModified is false while TIA ExclusiveAccess is held; Save() will not silently persist pre-existing unsaved work."
                        : options.AcceptSavingPreexistingProjectChanges
                            ? "UNSAFE OVERRIDE: the caller explicitly accepted saving pre-existing or unprovable project changes. This decision is recorded in the apply audit."
                            : "PROJECT_DIRTY_BEFORE_APPLY: Project.IsModified is true or unavailable. Refusing to write because mandatory Save() would persist changes outside the apply plan.",
                options.ProjectPath,
                "Project.IsModified=false (or explicit --i-accept-saving-preexisting-project-changes)",
                dirtyActual);

            List<Dictionary<string, string>> allRows = bundle.BlockRows;
            List<Dictionary<string, string>> sourceBlockerRows = bundle.SourceBlockerRows;
            int sourceBlockerCount = BlockingSourceBlockerCount(allRows, sourceBlockerRows);
            AddApplyCloneGate(
                gates,
                "before-write",
                "source-blockers",
                sourceBlockerCount == 0 ? "passed" : "failed",
                true,
                true,
                false,
                sourceBlockerCount == 0 ? "Latest clone-check reports contain no blocking source-blocked PLC rows; informational warnings do not gate this apply." : "Latest clone-check reports contain blocking or malformed source-blocker evidence; apply-clone is blocked.",
                sourceBlockerReportPath,
                "source blockers=0",
                "source blockers=" + sourceBlockerCount.ToString(CultureInfo.InvariantCulture));
            if (sourceBlockerCount > 0)
            {
                WriteApplyClonePreflightReports(outDir, plan, preflight.Issues);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, false, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                EnsureNoSourceBlockersForWrite("apply-clone", allRows, sourceBlockerRows);
            }

            if (!CanWriteApplyClone(gates))
            {
                WriteApplyClonePreflightReports(outDir, plan, preflight.Issues);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, false, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                throw new InvalidOperationException("apply-clone before-write gates failed. See apply-clone-gate.csv.");
            }

            List<Dictionary<string, string>> actionableRows = allRows
                .Where(x => EqualsIgnoreCase(GetCsvValue(x, "Status"), "changed")
                    || EqualsIgnoreCase(GetCsvValue(x, "Status"), "removed")
                    || EqualsIgnoreCase(GetCsvValue(x, "Status"), "added")
                    || EqualsIgnoreCase(GetCsvValue(x, "Status"), "moved-or-renamed")
                    || EqualsIgnoreCase(GetCsvValue(x, "Status"), "moved-or-renamed-and-changed"))
                .ToList();
            List<Dictionary<string, string>> rows = actionableRows
                .Where(x => RowMatchesName(x, options.Name))
                .Where(x => RowMatchesGroup(x, options.GroupPath))
                .ToList();
            rows = rows
                .OrderBy(ApplyCloneRowOrder)
                .ThenBy(x => EmptyIfNull(GetCsvValue(x, "GroupPath")), StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => SafeInt(FirstNonEmpty(GetCsvValue(x, "CloneNumber"), GetCsvValue(x, "CurrentNumber"), GetCsvValue(x, "Number"))))
                .ThenBy(x => FirstNonEmpty(GetCsvValue(x, "CloneName"), GetCsvValue(x, "CurrentName"), GetCsvValue(x, "Name")), StringComparer.OrdinalIgnoreCase)
                .ToList();

            AddApplyCloneGate(
                gates,
                "before-write",
                "selection",
                "passed",
                false,
                true,
                false,
                rows.Count == 0 ? "No changed, clone-only, clone-deleted, or moved/renamed blocks match the requested filters." : "Rows selected for apply-clone plan.",
                blockReportPath,
                "selected rows match --name/--group filters",
                "selected=" + rows.Count.ToString(CultureInfo.InvariantCulture) + "; --name=" + EmptyIfNull(options.Name) + "; --group=" + EmptyIfNull(options.GroupPath));

            int unselectedDirtyRows = actionableRows.Count - rows.Count;
            bool selectiveApplyIsUnsafe = SelectiveApplyWouldLeaveDirtyRows(options, actionableRows.Count, rows.Count);
            AddApplyCloneGate(
                gates,
                "before-write",
                "complete-dirty-selection",
                selectiveApplyIsUnsafe ? "failed" : "passed",
                true,
                true,
                false,
                selectiveApplyIsUnsafe
                    ? "Selective apply would leave dirty rows and fail only after TIA mutation. Run without filters or make the other rows clean first."
                    : "Every actionable dirty row is selected, or no selection filter was used.",
                blockReportPath,
                "unselected dirty rows=0",
                "unselected dirty rows=" + unselectedDirtyRows.ToString(CultureInfo.InvariantCulture));


            object software = softwareRecord.Object;
            object externalSourceGroup = TryGetPropertyValue(software, "ExternalSourceGroup");
            if (externalSourceGroup == null)
            {
                AddApplyCloneGate(gates, "before-write", "workspace-reports", "failed", true, true, false, "PLC software does not expose ExternalSourceGroup.", string.Empty, "ExternalSourceGroup present", "missing");
                WriteApplyClonePreflightReports(outDir, plan, preflight.Issues);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, false, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                throw new InvalidOperationException("PLC software does not expose ExternalSourceGroup.");
            }

            string authoritativePreStateExportDir = null;
            Exception applyClonePrimaryException = null;
            try
            {
                plan = BuildApplyClonePlan(rows, snapshot, rootDir);
                preflight = RunApplyClonePreflight(plan, snapshot, rootDir, true);
                ApplyPreStateValidationResult authoritativePreState = new ApplyPreStateValidationResult();
                if (preflight.ErrorCount == 0)
                {
                    authoritativePreState = ValidateCompleteApplyClonePreState(
                        bundle,
                        snapshot,
                        plan,
                        externalSourceGroup,
                        outDir,
                        preflight,
                        out authoritativePreStateExportDir);
                }

            AddApplyClonePreflightGates(gates, plan, preflight, true, outDir);
            AddApplyCloneGate(
                gates,
                "before-write",
                "complete-live-prestate",
                authoritativePreState.Performed && authoritativePreState.ErrorCount == 0 ? "passed" : "failed",
                true,
                true,
                false,
                authoritativePreState.Performed && authoritativePreState.ErrorCount == 0
                        ? "The complete current TIA block/group state and every exportable source match the checked bundle under the same ExclusiveAccess lease."
                        : "The complete current TIA state could not be proven equal to the checked bundle before mutation.",
                blockReportPath,
                "all current blocks/groups/source hashes match",
                "blocks=" + authoritativePreState.BlockCount.ToString(CultureInfo.InvariantCulture)
                    + "; groups=" + authoritativePreState.GroupCount.ToString(CultureInfo.InvariantCulture)
                    + "; sources=" + authoritativePreState.SourceCount.ToString(CultureInfo.InvariantCulture)
                    + "; errors=" + authoritativePreState.ErrorCount.ToString(CultureInfo.InvariantCulture));
            bool? projectDirtyAfterPreStateExport = authoritativePreState.Performed
                ? TryReadProjectIsModified(project)
                : (bool?)null;
            bool dirtyAfterPreStateAccepted = authoritativePreState.Performed
                && ProjectDirtyStateAllowsApply(projectDirtyAfterPreStateExport, options.AcceptSavingPreexistingProjectChanges);
            AddApplyCloneGate(
                gates,
                "before-write",
                "project-clean-after-prestate-export",
                dirtyAfterPreStateAccepted ? "passed" : "failed",
                true,
                true,
                false,
                projectDirtyAfterPreStateExport == false
                    ? "Project.IsModified remained false after the complete authoritative source export."
                    : options.AcceptSavingPreexistingProjectChanges && authoritativePreState.Performed
                        ? "UNSAFE OVERRIDE: Project.IsModified is true or unavailable after the complete source export; the caller explicitly accepted saving such state."
                        : "PROJECT_DIRTY_AFTER_PRESTATE_EXPORT: Project.IsModified became true or unavailable after the complete source export; backup and mutation are forbidden.",
                options.ProjectPath,
                "Project.IsModified=false after complete live pre-state export (or explicit unsafe override)",
                authoritativePreState.Performed
                    ? "Project.IsModified=" + (projectDirtyAfterPreStateExport.HasValue ? projectDirtyAfterPreStateExport.Value.ToString() : "unavailable")
                    : "complete live pre-state export not performed");
            AddApplyCloneGate(
                gates,
                "before-write",
                "tia-object-continuity-policy",
                authoritativePreState.UnprovenObjectIdCount == 0 ? "passed" : "warning",
                false,
                false,
                false,
                authoritativePreState.UnprovenObjectIdCount == 0
                        ? "Every current object identifier available in the bundle is continuous in the authoritative pre-state."
                        : "ObjectIdentifierProvider did not provide a durable ID for every current block. Production policy permits this explicitly reported state because full logical identity, metadata, and source hashes remain mandatory; within-apply ID continuity is still enforced whenever a fresh ID is available.",
                blockReportPath,
                "available IDs equal; unavailable IDs explicitly reported",
                "proven=" + authoritativePreState.ProvenObjectIdCount.ToString(CultureInfo.InvariantCulture)
                    + "; unproven=" + authoritativePreState.UnprovenObjectIdCount.ToString(CultureInfo.InvariantCulture));
            List<string> completeReportIssues = ApplyCloneCompleteReportIssues(
                allRows,
                bundle.GroupRows,
                plan);
            AddApplyCloneGate(
                gates,
                "before-write",
                "complete-report-safety",
                completeReportIssues.Count == 0 ? "passed" : "failed",
                true,
                true,
                false,
                completeReportIssues.Count == 0
                        ? "Every report row is unchanged, covered by the immutable plan, an expected missing target group, or a proven informational current-only source blocker."
                        : "Complete clone-check report contains state that is not safely explained by the immutable apply plan: " + string.Join("; ", completeReportIssues.Take(5).ToArray()),
                blockReportPath,
                "unexplained/malformed/export-error rows=0; unexplained group rows=0",
                "issues=" + completeReportIssues.Count.ToString(CultureInfo.InvariantCulture));
            WriteApplyClonePreflightReports(outDir, plan, preflight.Issues);
            PrintApplyClonePreflightSummary(outDir, plan, preflight);

            bool canWrite = CanWriteApplyClone(gates);
            if (preflight.ErrorCount > 0 || !canWrite)
            {
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, canWrite, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                throw new InvalidOperationException("apply-clone preflight failed with " + preflight.ErrorCount + " error(s). See apply-clone-preflight-issues.csv.");
            }

            string preparedApplyStagingDir = null;
            ApplyStagingLease preparedApplyStagingLease = null;
            if (plan.Count > 0)
            {
                try
                {
                    ValidateCloneWorkspaceInventory(outDir, bundle.WorkspaceRows);
                    preparedApplyStagingDir = StageApplyClonePlanSources(outDir, bundle, plan, rootDir, out preparedApplyStagingLease);
                    WriteApplyClonePreflightReports(outDir, plan, preflight.Issues);
                }
                catch (Exception ex)
                {
                    TryDispose(preparedApplyStagingLease);
                    preparedApplyStagingLease = null;
                    CleanupApplyStaging(preparedApplyStagingDir);
                    AddApplyCloneGate(gates, "before-write", "immutable-source-staging", "failed", true, true, false, "Immutable source staging failed before pre-state evidence cleanup or any TIA write: " + ex.Message, outDir, "all planned clone/live sources copied with checked hashes", ex.GetType().Name + ": " + ex.Message);
                    WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, false, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                    throw new InvalidOperationException("apply-clone immutable source staging failed before any TIA write; no TIA mutation started.", ex);
                }
            }

            try
            {
                CompleteApplyPreStateCleanupBeforeWrite(ref authoritativePreStateExportDir, outDir);
                AddApplyCloneGate(gates, "before-write", "prestate-evidence-cleanup", "passed", true, true, false, "Authoritative live-source evidence was copied into immutable staging and its owned export directory was strictly removed before backup or TIA mutation.", outDir, "owned authoritative pre-state export absent before first write", "removed");
            }
            catch (Exception ex)
            {
                TryDispose(preparedApplyStagingLease);
                preparedApplyStagingLease = null;
                CleanupApplyStaging(preparedApplyStagingDir);
                preparedApplyStagingDir = null;
                AddApplyCloneGate(gates, "before-write", "prestate-evidence-cleanup", "failed", true, true, false, "PRESTATE_EVIDENCE_CLEANUP_FAILED: strict cleanup failed before any TIA write; no TIA mutation started. " + ex.Message, outDir, "owned authoritative pre-state export absent before first write", ex.GetType().Name + ": " + ex.Message);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, false, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                throw new InvalidOperationException("PRESTATE_EVIDENCE_CLEANUP_FAILED before any TIA write; no TIA mutation started.", ex);
            }

            if (plan.Count == 0)
            {
                AddApplyCloneGate(gates, "write", "apply-operations", "skipped", false, false, true, "Authoritative validation completed; there are no plan items to write.", Path.Combine(outDir, "apply-clone-operations.csv"), "plan items=0", "plan items=0");
                AddApplyCloneSavePolicyGate(gates, false, false, false, options.Save, false, null);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, true, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                Console.WriteLine("No changed, clone-only, or clone-deleted blocks were found to apply. Authoritative TIA pre-state validation completed.");
                return;
            }

            if (!options.Apply)
            {
                string dryRunStagingDir = preparedApplyStagingDir;
                TryDispose(preparedApplyStagingLease);
                preparedApplyStagingLease = null;
                ApplyStagingCleanupResult dryRunCleanup = CleanupApplyStaging(dryRunStagingDir);
                if (!dryRunCleanup.Removed)
                {
                    throw new IOException("Authoritative dry-run immutable source staging could not be removed cleanly: " + dryRunCleanup.Message);
                }
                AddApplyCloneGate(gates, "before-write", "immutable-source-staging", "passed", true, true, false, "Every planned source was copied and hash-verified in immutable staging; staging was removed without invoking a TIA write.", dryRunStagingDir, "all planned sources staged with checked hashes", "plan items=" + plan.Count.ToString(CultureInfo.InvariantCulture));

                foreach (ApplyPlanItem item in plan)
                {
                    AddApplyCloneOperation(operations, item, "skipped", "authoritative-dry-run", "All read-side proofs passed; no TIA write method invoked.", null);
                }

                AddApplyCloneGate(gates, "write", "apply-operations", "skipped", false, false, true, "Authoritative dry-run completed; no TIA write method was invoked.", Path.Combine(outDir, "apply-clone-operations.csv"), "no write in dry-run", "write attempted=false");
                AddApplyCloneSavePolicyGate(gates, false, false, false, options.Save, false, null);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, true, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                Console.WriteLine();
                Console.WriteLine("Authoritative dry-run passed. Re-run with --apply --save to generate/delete blocks from clone state.");
                return;
            }

            string preApplyBackupPath;
            try
            {
                preApplyBackupPath = BackupProjectFolder(options.ProjectPath, outDir);
                if (!Directory.Exists(preApplyBackupPath))
                {
                    throw new IOException("Backup helper returned a missing directory: " + preApplyBackupPath);
                }
                AddApplyCloneGate(gates, "before-write", "pre-apply-backup", "passed", true, true, false, "A filesystem project backup was created while TIA ExclusiveAccess was held and after all pre-write state gates passed.", preApplyBackupPath, "backup exists before first TIA mutation", "created");
            }
            catch (Exception ex)
            {
                TryDispose(preparedApplyStagingLease);
                preparedApplyStagingLease = null;
                CleanupApplyStaging(preparedApplyStagingDir);
                preparedApplyStagingDir = null;
                AddApplyCloneGate(gates, "before-write", "pre-apply-backup", "failed", true, true, false, "Pre-apply project backup failed: " + ex.Message, options.ProjectPath, "backup exists before first TIA mutation", ex.GetType().Name + ": " + ex.Message);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, false, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                throw new InvalidOperationException("apply-clone could not create its pre-mutation project backup.", ex);
            }

            try
            {
                // Backup can be long-running. Revalidate both the live workspace
                // and the fixed staged digests immediately before the first TIA
                // mutation; staged files remain read-locked for TIA's readers.
                ValidateCloneWorkspaceInventory(outDir, bundle.WorkspaceRows);
                ValidateApplyStagingDigests(plan);
                AddApplyCloneGate(gates, "before-write", "post-backup-source-revalidation", "passed", true, true, false, "Active clone workspace and fixed staged raw/canonical digests were revalidated after backup and immediately before the first TIA write.", preparedApplyStagingDir, "workspace unchanged; every staged digest equals its fixed plan digest", "passed");
            }
            catch (Exception ex)
            {
                TryDispose(preparedApplyStagingLease);
                preparedApplyStagingLease = null;
                ApplyStagingCleanupResult cleanup = CleanupApplyStaging(preparedApplyStagingDir);
                AddApplyCloneGate(gates, "before-write", "post-backup-source-revalidation", "failed", true, true, false, "Post-backup source revalidation failed before any TIA write: " + ex.Message, preparedApplyStagingDir, "workspace unchanged; every staged digest equals its fixed plan digest", ex.GetType().Name + ": " + ex.Message + "; cleanup=" + cleanup.Status);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, false, false, false, false, plan.Count), options.Apply, options.Save, false, false, false, plan, preflight, gates, operations);
                throw new InvalidOperationException("apply-clone post-backup source revalidation failed before any TIA write; no TIA mutation started.", ex);
            }

            if (projectDirtyBeforeApply != false && options.AcceptSavingPreexistingProjectChanges)
            {
                AddApplyCloneGate(gates, "before-write", "backup-in-memory-state-limit", "warning", false, false, false, "UNSAFE OVERRIDE LIMITATION: the filesystem backup contains only the durable project files and cannot preserve pre-existing unsaved in-memory TIA changes that the mandatory Save() may persist.", preApplyBackupPath, "Project.IsModified=false for a fully restorable pre-apply backup", dirtyActual);
            }

            bool writeAttempted = true;
            bool writeCompleted = false;
            Exception writeException = null;
            bool originalSave = options.Save;
            string applyStagingDir = preparedApplyStagingDir;
            ApplyStagingLease applyStagingLease = preparedApplyStagingLease;
            try
            {
                options.Save = false;
                ExecuteApplyClonePlan(project, options, outDir, rootDir, snapshot, softwareRecord, plan, operations);
                writeCompleted = true;
            }
            catch (Exception ex)
            {
                writeException = ex;
                if (!operations.Any(x => EqualsIgnoreCase(x.Status, "failed")))
                {
                    AddApplyCloneOperation(operations, null, "failed", "apply-clone-engine", ex.Message, ex);
                }
            }
            finally
            {
                options.Save = originalSave;
            }

            if (writeException == null)
            {
                AddApplyCloneGate(gates, "write", "apply-operations", "passed", true, false, true, "All planned TIA write operations completed without exceptions.", Path.Combine(outDir, "apply-clone-operations.csv"), "failed operations=0", "failed operations=0");
            }
            else
            {
                AddApplyCloneGate(gates, "write", "apply-operations", "failed", true, false, true, "A TIA write operation failed: " + writeException.Message, Path.Combine(outDir, "apply-clone-operations.csv"), "failed operations=0", "failed operations=1");
                AddApplyCloneSavePolicyGate(gates, false, writeAttempted, false, originalSave, false, null);
                TryDispose(applyStagingLease);
                applyStagingLease = null;
                ApplyStagingCleanupResult failedWriteCleanup = CleanupApplyStaging(applyStagingDir);
                AddApplyStagingCleanupGate(gates, failedWriteCleanup, false, false);
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, true, writeAttempted, writeCompleted, false, plan.Count), options.Apply, originalSave, false, writeAttempted, true, plan, preflight, gates, operations);
                throw new InvalidOperationException("apply-clone write failed. The open TIA project may contain partial unsaved changes; close without saving or restore the pre-apply backup.", writeException);
            }

            string afterBlockReportPath = Path.Combine(outDir, "apply-clone-after-check-blocks.csv");
            string afterSourceBlockerReportPath = Path.Combine(outDir, "apply-clone-after-check-source-blockers.csv");
            Exception afterCheckException = null;
            bool afterCheckAccepted = false;
            InventorySnapshot afterApply = null;
            string validationDir = null;
            ApplyStagingCleanupResult committedValidationCleanup = null;
            PublicationCommitResult applyPublicationCommit = null;
            Exception postCommitDiagnosticException = null;
            try
            {
                afterApply = FilterInventoryBySoftwarePath(
                    CollectInventory(project, options.ProjectPath),
                    softwareRecord.Path);
                validationDir = CreateApplyValidationWorkspace(outDir, bundle, plan, rootDir);
                string validationRoot = Path.Combine(validationDir, "_root");
                List<ExplicitNewPromotionReceipt> promotionReceipts = BuildSuccessfulCreateBlockReceipts(
                    plan,
                    afterApply,
                    bundle.CheckRunId,
                    rootDir,
                    validationRoot);

                // The first check exports the post-write TIA state into an
                // isolated workspace. sync-clone then resolves every accepted
                // path/number/content transition there, never in the durable
                // baseline. The second check is the acceptance boundary.
                CheckProjectClone(afterApply, validationDir, promotionReceipts);
                CloneCheckBundleEvidence transitionBundle = LoadAndValidateCloneCheckBundle(validationDir);
                ApplyObjectContinuityResult objectContinuity = ValidateApplyClonePostconditions(snapshot, afterApply, transitionBundle, plan);
                AddApplyCloneGate(
                    gates,
                    "after-write",
                    "exact-plan-postconditions",
                    "passed",
                    true,
                    false,
                    true,
                    "Every planned transition has its exact expected identity/content result and the complete PLC block/group set contains no collateral state.",
                    Path.Combine(validationDir, CloneCheckBlockFileName),
                    "all plan postconditions satisfied; unexplained blocks/groups=0",
                    "plan items=" + plan.Count.ToString(CultureInfo.InvariantCulture));
                AddApplyCloneGate(
                    gates,
                    "after-write",
                    "tia-object-continuity",
                    objectContinuity.UnprovenCount == 0 ? "passed" : "warning",
                    false,
                    false,
                    true,
                    objectContinuity.UnprovenCount == 0
                        ? "Every create/update/rename/delete transition satisfied TIA object identifier continuity."
                        : "TIA did not expose a durable object identifier for every transition. Logical identity, full source evidence, and collateral-state checks remain mandatory; identifiers were enforced wherever available.",
                    Path.Combine(validationDir, CloneCheckBlockFileName),
                    "available IDs satisfy create/update/rename/delete continuity; unavailable IDs explicit",
                    "proven=" + objectContinuity.ProvenCount.ToString(CultureInfo.InvariantCulture)
                        + "; unproven=" + objectContinuity.UnprovenCount.ToString(CultureInfo.InvariantCulture));
                SyncProjectCloneForApplyValidation(validationDir, plan);
                CheckProjectClone(afterApply, validationDir);
                CloneCheckBundleEvidence afterBundle = LoadAndValidateCloneCheckBundle(validationDir);
                CopyApplyAfterCheckReports(validationDir, afterBlockReportPath, afterSourceBlockerReportPath);

                List<Dictionary<string, string>> afterRows = afterBundle.BlockRows;
                List<Dictionary<string, string>> afterSourceBlockers = afterBundle.SourceBlockerRows;
                int dirtyRows = ApplyCloneDirtyRowCount(afterRows);
                int afterSourceBlockerCount = BlockingSourceBlockerCount(afterRows, afterSourceBlockers);
                int dirtyGroups = afterBundle.GroupRows.Count(x => !EqualsIgnoreCase(GetCsvValue(x, "Status"), "unchanged"));

                // A successful deletion may legitimately leave a project with
                // zero block rows. Bundle integrity, not a nonzero row count,
                // proves that the after-check completed.
                afterCheckAccepted = dirtyRows == 0 && afterSourceBlockerCount == 0 && dirtyGroups == 0;
                AddApplyCloneGate(
                    gates,
                    "after-write",
                    "after-clone-check",
                    afterCheckAccepted ? "passed" : "failed",
                    true,
                    false,
                    true,
                    afterCheckAccepted ? "After-apply check-clone is clean; clone and TIA are synchronized." : "After-apply check-clone found dirty rows or source blockers.",
                    afterBlockReportPath,
                    "dirty rows=0; source blockers=0; dirty groups=0",
                    "rows=" + afterRows.Count.ToString(CultureInfo.InvariantCulture) + "; dirty rows=" + dirtyRows.ToString(CultureInfo.InvariantCulture) + "; source blockers=" + afterSourceBlockerCount.ToString(CultureInfo.InvariantCulture) + "; dirty groups=" + dirtyGroups.ToString(CultureInfo.InvariantCulture));
            }
            catch (Exception ex)
            {
                afterCheckException = ex;
                if (!gates.Any(x => EqualsIgnoreCase(x.Gate, "exact-plan-postconditions")))
                {
                    AddApplyCloneGate(gates, "after-write", "exact-plan-postconditions", "failed", true, false, true, "Exact plan postcondition verification failed before reconciliation: " + ex.Message, afterBlockReportPath, "all plan postconditions satisfied; unexplained blocks/groups=0", ex.GetType().Name + ": " + ex.Message);
                }
                AddApplyCloneGate(gates, "after-write", "after-clone-check", "failed", true, false, true, "After-apply check-clone failed: " + ex.Message, afterBlockReportPath, "after check completes", ex.GetType().Name + ": " + ex.Message);
            }

            bool accepted = afterCheckAccepted && IsApplyCloneAcceptedByGates(gates, writeAttempted);
            bool savedProject = false;
            bool saveAttempted = false;
            Exception finalizationException = null;
            Exception saveException = null;
            Exception publishException = null;
            if (accepted)
            {
                try
                {
                    int compileTargets;
                    int compileErrors;
                    int compileWarnings;
                    Exception compileException = null;
                    try
                    {
                        CompileAllForApply(project, afterApply, out compileTargets, out compileErrors, out compileWarnings);
                    }
                    catch (Exception ex)
                    {
                        compileTargets = 0;
                        compileErrors = 1;
                        compileWarnings = 0;
                        compileException = ex;
                    }
                    AddApplyCloneGate(
                        gates,
                        "before-save",
                        "compile-before-save",
                        compileErrors == 0 ? "passed" : "failed",
                        true,
                        false,
                        true,
                        compileException == null && compileErrors == 0
                            ? "Compile-all completed with zero errors before SaveProject."
                            : "Compile-all failed or reported errors; SaveProject is forbidden. " + (compileException == null ? string.Empty : compileException.Message),
                        options.ProjectPath,
                        "compile targets>0; errors=0",
                        "targets=" + compileTargets.ToString(CultureInfo.InvariantCulture)
                            + "; errors=" + compileErrors.ToString(CultureInfo.InvariantCulture)
                            + "; warnings=" + compileWarnings.ToString(CultureInfo.InvariantCulture));
                    if (compileException != null || compileErrors != 0)
                    {
                        throw new InvalidOperationException("Compile-before-save failed with " + compileErrors.ToString(CultureInfo.InvariantCulture) + " error(s).", compileException);
                    }

                    InventorySnapshot beforeSave = FilterInventoryBySoftwarePath(
                        CollectInventory(project, options.ProjectPath),
                        softwareRecord.Path);
                    ValidateApplyInventoryIdentityStable(afterApply, beforeSave, "compile-before-save");
                    CheckProjectClone(beforeSave, validationDir);
                    CloneCheckBundleEvidence beforeSaveBundle = LoadAndValidateCloneCheckBundle(validationDir);
                    EnsureCleanApplyVerificationBundle(beforeSaveBundle, "fresh pre-save");
                    AddApplyCloneGate(
                        gates,
                        "before-save",
                        "fresh-pre-save-snapshot",
                        "passed",
                        true,
                        false,
                        true,
                        "A fresh inventory and source export collected after compilation still match the verified staged baseline.",
                        Path.Combine(validationDir, CloneCheckBundleFileName),
                        "identity stable; dirty rows=0; source blockers=0; group rows unchanged",
                        "check run=" + beforeSaveBundle.CheckRunId);

                    ValidateCloneWorkspaceInventory(outDir, bundle.WorkspaceRows);
                    saveAttempted = true;
                    SaveProject(project);
                    savedProject = true;
                    Console.WriteLine("Project saved.");

                    bool? dirtyAfterSave = TryReadProjectIsModified(project);
                    if (dirtyAfterSave != false)
                    {
                        throw new InvalidDataException("Project.IsModified did not become false after SaveProject; durable post-save state cannot be proven.");
                    }

                    InventorySnapshot afterSave = FilterInventoryBySoftwarePath(
                        CollectInventory(project, options.ProjectPath),
                        softwareRecord.Path);
                    ValidateApplyInventoryIdentityStable(beforeSave, afterSave, "save");
                    CheckProjectClone(afterSave, validationDir);
                    CloneCheckBundleEvidence afterSaveBundle = LoadAndValidateCloneCheckBundle(validationDir);
                    EnsureCleanApplyVerificationBundle(afterSaveBundle, "fresh post-save");
                    AddApplyCloneGate(
                        gates,
                        "after-save",
                        "fresh-post-save-snapshot",
                        "passed",
                        true,
                        false,
                        true,
                        "Fresh post-save inventory/source evidence matches the pre-save staged baseline while TIA ExclusiveAccess remains held.",
                        Path.Combine(validationDir, CloneCheckBundleFileName),
                        "identity stable across Save(); dirty rows=0; source blockers=0; group rows unchanged",
                        "check run=" + afterSaveBundle.CheckRunId);

                    using (SyncStagingLease publicationLease = new SyncStagingLease { DirectoryPath = validationDir })
                    {
                        SyncInputSet publicationInputs = StageImmutableSyncInputs(
                            validationDir,
                            afterSaveBundle,
                            validationDir,
                            publicationLease,
                            null);
                        PublicationExpectedModel expectedPublication = BuildPublicationExpectedModel(
                            outDir,
                            afterSaveBundle,
                            validationDir,
                            Path.Combine(validationDir, "_root"),
                            Path.Combine(afterSaveBundle.CompareDirectory, "_root"),
                            publicationInputs);
                        PrepareApplyValidationWorkspaceForPublish(validationDir, expectedPublication);
                        // Do not overwrite an editor's concurrent local change.
                        ValidateCloneWorkspaceInventory(outDir, bundle.WorkspaceRows);
                        SealExistingPublicationStaging(validationDir, afterSaveBundle, expectedPublication, publicationLease);

                        string applyBackupDir = UniquePath(Path.Combine(
                            outDir,
                            "_apply-backups",
                            "apply-" + DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")));
                        try
                        {
                            applyPublicationCommit = CommitStagedSyncWorkspace(
                                outDir,
                                validationDir,
                                applyBackupDir,
                                "apply-publication",
                                publicationLease.PackagePath,
                                publicationLease.PackageSha256,
                                null);
                        }
                        catch (PublicationCommittedDiagnosticException committedDiagnostic)
                        {
                            applyPublicationCommit = committedDiagnostic.CommitResult;
                            postCommitDiagnosticException = committedDiagnostic;
                            Console.WriteLine("WARNING: " + committedDiagnostic.Message);
                        }
                    }
                    string retainedPublicationJournal = Path.Combine(outDir, PublicationTransactionFileName);
                    committedValidationCleanup = File.Exists(retainedPublicationJournal)
                        ? new ApplyStagingCleanupResult
                        {
                            Status = "retained-for-committed-journal",
                            OriginalPath = validationDir,
                            EvidencePath = retainedPublicationJournal,
                            Message = "Committed journal still owns the apply publication package; a clone command must verify it before staging cleanup."
                        }
                        : CleanupApplyValidationWorkspace(validationDir);
                    validationDir = null;

                    // Publish a fresh authorization bundle only after both the
                    // TIA save and durable workspace commit have succeeded.
                    postCommitDiagnosticException = FinalizeCommittedApplyPublication(
                        applyPublicationCommit,
                        delegate
                        {
                            CheckProjectClone(afterSave, outDir);
                            CloneCheckBundleEvidence publishedBundle = LoadAndValidateCloneCheckBundle(outDir);
                            EnsureCleanApplyVerificationBundle(publishedBundle, "published post-save");
                        },
                        delegate { CopyApplyAfterCheckReports(outDir, afterBlockReportPath, afterSourceBlockerReportPath); });
                }
                catch (Exception ex)
                {
                    if (!saveAttempted)
                    {
                        finalizationException = ex;
                        AddApplyCloneGate(
                            gates,
                            "before-save",
                            "pre-save-finalization",
                            "failed",
                            true,
                            false,
                            true,
                            "Pre-save compile or fresh-snapshot verification failed: " + ex.Message,
                            options.ProjectPath,
                            "compile succeeds and fresh pre-save snapshot remains clean",
                            ex.GetType().Name + ": " + ex.Message);
                        Console.WriteLine("Apply finalization failed before save: " + ex.Message);
                    }
                    else if (!savedProject)
                    {
                        saveException = ex;
                        Console.WriteLine("Project save failed: " + ex.Message);
                    }
                    else
                    {
                        publishException = ex;
                        InvalidateCloneCheckBundle(outDir);
                        Console.WriteLine("Apply workspace publication failed: " + ex.Message);
                    }
                }
            }
            else
            {
                Console.WriteLine("Project was not saved because apply-clone final gates rejected the result.");
            }

            bool fullyAccepted = accepted && savedProject && publishException == null;
            ApplyStagingCleanupResult validationCleanup = committedValidationCleanup ?? CleanupApplyValidationWorkspace(validationDir);
            AddApplyValidationCleanupGate(gates, validationCleanup, savedProject, fullyAccepted);
            AddApplyCloneSavePolicyGate(gates, accepted && finalizationException == null, writeAttempted, true, originalSave, savedProject, finalizationException ?? saveException ?? publishException);
            TryDispose(applyStagingLease);
            applyStagingLease = null;
            ApplyStagingCleanupResult finalStagingCleanup = CleanupApplyStaging(applyStagingDir);
            AddApplyStagingCleanupGate(gates, finalStagingCleanup, savedProject, fullyAccepted);
            if (applyPublicationCommit != null && fullyAccepted)
            {
                if (postCommitDiagnosticException != null)
                    applyPublicationCommit.DiagnosticFailure = postCommitDiagnosticException;
                Exception reportException;
                TryWriteCommittedPublicationDiagnostics(
                    applyPublicationCommit,
                    "apply-clone",
                    delegate
                    {
                        WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, true, writeAttempted, writeCompleted, fullyAccepted, plan.Count), options.Apply, originalSave, savedProject, writeAttempted, true, plan, preflight, gates, operations);
                    },
                    out reportException);
            }
            else
            {
                WriteApplyCloneFinalReports(outDir, ApplyCloneState(options.Apply, true, writeAttempted, writeCompleted, fullyAccepted, plan.Count), options.Apply, originalSave, savedProject, writeAttempted, true, plan, preflight, gates, operations);
            }

            if (finalizationException != null)
            {
                throw new InvalidOperationException("apply-clone postconditions or compile-before-save validation failed. The project was not saved; close it without saving or restore the pre-apply backup.", finalizationException);
            }

            if (saveException != null)
            {
                throw new InvalidOperationException("apply-clone completed but SaveProject failed. The open TIA project may contain unsaved changes.", saveException);
            }

            if (publishException != null)
            {
                throw new InvalidOperationException("apply-clone saved the TIA project but could not publish or verify the staged clone baseline. No authorization bundle remains; recover using the apply backup if necessary.", publishException);
            }

            if (!accepted)
            {
                string reason = afterCheckException == null ? "after-apply verification rejected the result" : "after-apply verification failed";
                throw new InvalidOperationException("apply-clone " + reason + ". The open TIA project may contain unsaved changes; close without saving or restore the pre-apply backup.");
            }
            }
            catch (Exception ex)
            {
                applyClonePrimaryException = ex;
                throw;
            }
            finally
            {
                try
                {
                    DeleteOwnedApplyPreStateExportStrict(authoritativePreStateExportDir, outDir);
                }
                catch (Exception cleanupException)
                {
                    if (applyClonePrimaryException != null)
                    {
                        throw new AggregateException(
                            "apply-clone failed before authoritative pre-state cleanup completed; the primary failure is preserved first and cleanup failure is secondary.",
                            applyClonePrimaryException,
                            cleanupException);
                    }
                    throw;
                }
            }
        }

        private static bool SelectiveApplyWouldLeaveDirtyRows(Options options, int actionableRowCount, int selectedRowCount)
        {
            return options != null
                && options.Apply
                && actionableRowCount > selectedRowCount
                && (!string.IsNullOrWhiteSpace(options.Name) || !string.IsNullOrWhiteSpace(options.GroupPath));
        }

        private static List<string> ApplyCloneCompleteReportIssues(
            List<Dictionary<string, string>> blockRows,
            List<Dictionary<string, string>> groupRows,
            List<ApplyPlanItem> plan)
        {
            List<string> issues = new List<string>();
            HashSet<Dictionary<string, string>> plannedRows = new HashSet<Dictionary<string, string>>(
                (plan ?? new List<ApplyPlanItem>())
                    .Where(x => x != null && x.Row != null)
                    .Select(x => x.Row));
            List<RemovedCloneRef> removedCloneKeys = RemovedCloneRefs(blockRows);

            foreach (Dictionary<string, string> row in blockRows ?? new List<Dictionary<string, string>>())
            {
                string status = GetCsvValue(row, "Status");
                string softwarePath = FirstNonEmpty(
                    GetCsvValue(row, "CurrentSoftwarePath"),
                    GetCsvValue(row, "CloneSoftwarePath"),
                    GetCsvValue(row, "SoftwarePath"));
                string name = FirstNonEmpty(
                    GetCsvValue(row, "CurrentName"),
                    GetCsvValue(row, "CloneName"),
                    GetCsvValue(row, "Name"));
                string numberSpace = FirstNonEmpty(
                    GetCsvValue(row, "CurrentNumberSpace"),
                    GetCsvValue(row, "CloneNumberSpace"),
                    GetCsvValue(row, "NumberSpace"));
                string number = FirstNonEmpty(
                    GetCsvValue(row, "CurrentNumber"),
                    GetCsvValue(row, "CloneNumber"),
                    GetCsvValue(row, "Number"));

                if (string.IsNullOrWhiteSpace(status)
                    || string.IsNullOrWhiteSpace(softwarePath)
                    || (string.IsNullOrWhiteSpace(name)
                        && (string.IsNullOrWhiteSpace(numberSpace) || string.IsNullOrWhiteSpace(number))))
                {
                    issues.Add("malformed block row " + FirstNonEmpty(name, "<unknown>"));
                    continue;
                }

                if (EqualsIgnoreCase(status, "unchanged"))
                {
                    continue;
                }

                if (EqualsIgnoreCase(status, "changed")
                    || EqualsIgnoreCase(status, "added")
                    || EqualsIgnoreCase(status, "removed")
                    || EqualsIgnoreCase(status, "moved-or-renamed")
                    || EqualsIgnoreCase(status, "moved-or-renamed-and-changed"))
                {
                    if (!plannedRows.Contains(row))
                    {
                        issues.Add("unplanned " + status + " block " + name);
                    }
                    continue;
                }

                if (EqualsIgnoreCase(status, "source-blocked-current-only"))
                {
                    BlockKey liveKey = new BlockKey(softwarePath, numberSpace, number, name);
                    if (!SourceBlockedStatusBlocksWrite(status, liveKey, removedCloneKeys))
                    {
                        continue;
                    }
                }

                issues.Add("blocking block state " + FirstNonEmpty(status, "<blank>") + " for " + name);
            }

            foreach (Dictionary<string, string> row in groupRows ?? new List<Dictionary<string, string>>())
            {
                string status = GetCsvValue(row, "Status");
                if (EqualsIgnoreCase(status, "unchanged"))
                {
                    continue;
                }

                string groupPath = RowGroupPathKey(row, "GroupPath");
                bool expectedMissingTargetGroup = EqualsIgnoreCase(status, "removed")
                    && (plan ?? new List<ApplyPlanItem>())
                        .Where(x => x != null && x.WillCreateGroup)
                        .Any(x => GroupPathContainsOrEquals(x.TargetGroupPath, groupPath));
                if (!expectedMissingTargetGroup)
                {
                    issues.Add("unplanned group state " + FirstNonEmpty(status, "<blank>") + " for " + FirstNonEmpty(groupPath, "_root"));
                }
            }

            return issues;
        }

        private static List<string> ApplyCloneReconciliationScopeIssues(
            List<Dictionary<string, string>> blockRows,
            List<Dictionary<string, string>> groupRows,
            List<ApplyPlanItem> plan)
        {
            List<string> issues = new List<string>();
            List<RemovedCloneRef> removedCloneKeys = RemovedCloneRefs(blockRows);
            foreach (Dictionary<string, string> row in blockRows ?? new List<Dictionary<string, string>>())
            {
                string status = GetCsvValue(row, "Status");
                if (EqualsIgnoreCase(status, "unchanged"))
                {
                    continue;
                }

                if (EqualsIgnoreCase(status, "source-blocked-current-only"))
                {
                    BlockKey liveKey = new BlockKey(
                        FirstNonEmpty(GetCsvValue(row, "CurrentSoftwarePath"), GetCsvValue(row, "SoftwarePath")),
                        FirstNonEmpty(GetCsvValue(row, "CurrentNumberSpace"), GetCsvValue(row, "NumberSpace")),
                        FirstNonEmpty(GetCsvValue(row, "CurrentNumber"), GetCsvValue(row, "Number")),
                        FirstNonEmpty(GetCsvValue(row, "CurrentName"), GetCsvValue(row, "Name")));
                    if (!SourceBlockedStatusBlocksWrite(status, liveKey, removedCloneKeys))
                    {
                        continue;
                    }
                }

                bool potentiallyReconcilable = EqualsIgnoreCase(status, "changed")
                    || EqualsIgnoreCase(status, "moved-or-renamed")
                    || EqualsIgnoreCase(status, "moved-or-renamed-and-changed");
                List<ApplyPlanItem> matches = potentiallyReconcilable
                    ? (plan ?? new List<ApplyPlanItem>())
                        .Where(x => x != null
                            && !x.WillDelete
                            && PostApplyRowMatchesPlanTarget(row, x)
                            && ApplyPostWriteStatusIsExpected(status, x))
                        .ToList()
                    : new List<ApplyPlanItem>();
                if (!potentiallyReconcilable || matches.Count != 1)
                {
                    issues.Add("block " + FirstNonEmpty(GetCsvValue(row, "Name"), "<unknown>") + " has " + FirstNonEmpty(status, "<blank>") + " with plan matches=" + matches.Count.ToString(CultureInfo.InvariantCulture));
                }
            }

            foreach (Dictionary<string, string> row in groupRows ?? new List<Dictionary<string, string>>())
            {
                if (!EqualsIgnoreCase(GetCsvValue(row, "Status"), "unchanged"))
                {
                    issues.Add("group " + FirstNonEmpty(RowGroupPathKey(row, "GroupPath"), "_root") + " has " + FirstNonEmpty(GetCsvValue(row, "Status"), "<blank>"));
                }
            }

            return issues;
        }

        private static bool ApplyPostWriteStatusIsExpected(string status, ApplyPlanItem item)
        {
            if (item == null)
            {
                return false;
            }
            if (EqualsIgnoreCase(status, "changed"))
            {
                return true;
            }
            return EqualsIgnoreCase(item.Action, "CreateBlock")
                && (EqualsIgnoreCase(status, "moved-or-renamed")
                    || EqualsIgnoreCase(status, "moved-or-renamed-and-changed"));
        }

        private static bool PostApplyRowMatchesPlanTarget(Dictionary<string, string> row, ApplyPlanItem item)
        {
            if (row == null || item == null)
            {
                return false;
            }

            string softwarePath = FirstNonEmpty(GetCsvValue(row, "CurrentSoftwarePath"), GetCsvValue(row, "SoftwarePath"));
            string groupPath = EmptyIfNull(FirstNonEmpty(RowGroupPathKey(row, "CurrentGroupPath"), RowGroupPathKey(row, "GroupPath")));
            string name = FirstNonEmpty(GetCsvValue(row, "CurrentName"), GetCsvValue(row, "Name"));
            string numberSpace = FirstNonEmpty(GetCsvValue(row, "CurrentNumberSpace"), GetCsvValue(row, "NumberSpace"));
            string number = FirstNonEmpty(GetCsvValue(row, "CurrentNumber"), GetCsvValue(row, "Number"));
            return EqualsIgnoreCase(softwarePath, item.SoftwarePath)
                && EqualsIgnoreCase(groupPath, EmptyIfNull(item.TargetGroupPath))
                && EqualsIgnoreCase(name, item.TargetName)
                && EqualsIgnoreCase(numberSpace, item.NumberSpace)
                && (item.DesiredNumber <= 0 || SafeInt(number) == item.DesiredNumber);
        }

        private static bool GroupPathContainsOrEquals(string descendant, string ancestor)
        {
            string child = EmptyIfNull(descendant).Trim('/');
            string parent = EmptyIfNull(ancestor).Trim('/');
            return EqualsIgnoreCase(child, parent)
                || (!string.IsNullOrWhiteSpace(parent)
                    && child.StartsWith(parent + "/", StringComparison.OrdinalIgnoreCase));
        }

        private static List<ExplicitNewPromotionReceipt> BuildSuccessfulCreateBlockReceipts(
            List<ApplyPlanItem> plan,
            InventorySnapshot afterApply,
            string checkRunId,
            string rootDir,
            string receiptRootDir)
        {
            List<ExplicitNewPromotionReceipt> receipts = new List<ExplicitNewPromotionReceipt>();
            foreach (ApplyPlanItem item in (plan ?? new List<ApplyPlanItem>())
                .Where(x => x != null
                    && EqualsIgnoreCase(x.Action, "CreateBlock")
                    && EqualsIgnoreCase(x.CloneProvenance, "explicit-new-local-source")))
            {
                EnsurePathInside(item.ClonePath, rootDir);
                string receiptSourcePath = MapClonePathToAlternateRoot(item.ClonePath, rootDir, receiptRootDir);
                string sourceHash = ComputeNormalizedTextSha256(receiptSourcePath);
                string sourceCanonicalHash = ComputeCanonicalSourceSha256(receiptSourcePath);
                List<BlockRecord> matches = (afterApply == null ? new List<BlockRecord>() : afterApply.Blocks)
                    .Where(x => EqualsIgnoreCase(x.SoftwarePath, item.SoftwarePath))
                    .Where(x => EqualsIgnoreCase(EmptyIfNull(x.GroupPath), EmptyIfNull(item.TargetGroupPath)))
                    .Where(x => EqualsIgnoreCase(x.Name, item.TargetName))
                    .Where(x => EqualsIgnoreCase(BlockNumberSpace(x), item.NumberSpace))
                    .Where(x => string.IsNullOrWhiteSpace(item.TargetNumber) || SafeInt(x.Number) == SafeInt(item.TargetNumber))
                    .Where(x => EqualsIgnoreCase(x.ProgrammingLanguage, item.ProgrammingLanguage))
                    .ToList();
                if (matches.Count != 1 || string.IsNullOrWhiteSpace(sourceHash) || string.IsNullOrWhiteSpace(sourceCanonicalHash))
                {
                    throw new InvalidDataException(
                        "Completed CreateBlock could not produce one promotion receipt for "
                        + item.SoftwarePath + "/" + item.TargetName + ".");
                }

                BlockRecord live = matches[0];
                receipts.Add(new ExplicitNewPromotionReceipt
                {
                    ReceiptId = Guid.NewGuid().ToString("N"),
                    CheckRunId = checkRunId,
                    SoftwarePath = item.SoftwarePath,
                    TargetGroupPath = item.TargetGroupPath,
                    TargetName = item.TargetName,
                    TargetNumberSpace = item.NumberSpace,
                    TargetNumber = item.TargetNumber,
                    ProgrammingLanguage = item.ProgrammingLanguage,
                    SourcePath = receiptSourcePath,
                    SourceNormalizedSha256 = sourceHash,
                    SourceCanonicalSha256 = sourceCanonicalHash,
                    LiveTiaObjectId = live.TiaObjectId,
                    LiveTiaObjectIdStatus = live.TiaObjectIdStatus
                });
            }

            return receipts;
        }

        private static string CreateApplyValidationWorkspace(
            string outDir,
            CloneCheckBundleEvidence bundle,
            List<ApplyPlanItem> plan,
            string rootDir)
        {
            string validationParent = Path.Combine(outDir, "_apply-validation");
            string validationDir = Path.Combine(
                validationParent,
                "run-" + bundle.CheckRunId + "-" + Guid.NewGuid().ToString("N").Substring(0, 8));
            string validationRoot = Path.Combine(validationDir, "_root");
            try
            {
                Directory.CreateDirectory(validationDir);
                WritePublicationStagingOwnerMarker(
                    Path.Combine(validationDir, ApplyValidationOwnerMarkerFileName),
                    "apply-publication",
                    bundle.CheckRunId);
                CopyDirectory(rootDir, validationRoot, false);

                foreach (string fileName in new[] { "plc-blocks.csv", "block-groups.csv" })
                {
                    string sourcePath = Path.Combine(outDir, fileName);
                    if (!File.Exists(sourcePath))
                    {
                        throw new FileNotFoundException("Apply validation workspace is missing a checked manifest.", sourcePath);
                    }
                    File.Copy(sourcePath, Path.Combine(validationDir, fileName), false);
                }

                string metadataDir = Path.Combine(outDir, "_metadata");
                if (Directory.Exists(metadataDir))
                {
                    CopyDirectory(metadataDir, Path.Combine(validationDir, "_metadata"), false);
                }

                ValidateCloneWorkspaceInventory(validationDir, bundle.WorkspaceRows);
                CommitCompletedApplyCloneDeletions(validationDir, plan);
                return validationDir;
            }
            catch (Exception ex)
            {
                ApplyStagingCleanupResult cleanup = CleanupApplyValidationWorkspace(validationDir);
                if (!cleanup.Removed)
                {
                    throw new IOException(
                        "Apply validation failed and its owned evidence could not be removed. Local confidentiality cleanup is required; path="
                            + cleanup.EvidencePath + ". " + cleanup.Message,
                        ex);
                }
                throw;
            }
        }

        private static ApplyObjectContinuityResult ValidateApplyClonePostconditions(
            InventorySnapshot beforeApply,
            InventorySnapshot afterApply,
            CloneCheckBundleEvidence transitionBundle,
            List<ApplyPlanItem> plan)
        {
            if (beforeApply == null || afterApply == null || transitionBundle == null)
            {
                throw new InvalidDataException("Exact apply postcondition verification is missing a required snapshot or evidence bundle.");
            }

            List<ApplyPlanItem> items = plan ?? new List<ApplyPlanItem>();
            ApplyObjectContinuityResult continuity = new ApplyObjectContinuityResult();
            Dictionary<string, int> expectedBlocks = InventoryBlockIdentityCounts(beforeApply);
            foreach (ApplyPlanItem item in items)
            {
                List<BlockRecord> beforeCurrent = beforeApply.Blocks
                    .Where(x => BlockMatchesPlanCurrent(x, item))
                    .ToList();
                List<BlockRecord> beforeTarget = beforeApply.Blocks
                    .Where(x => BlockMatchesPlanTarget(x, item))
                    .ToList();
                List<BlockRecord> afterCurrent = afterApply.Blocks
                    .Where(x => BlockMatchesPlanCurrent(x, item))
                    .ToList();
                List<BlockRecord> afterTarget = afterApply.Blocks
                    .Where(x => BlockMatchesPlanTarget(x, item))
                    .ToList();

                if (EqualsIgnoreCase(item.Action, "CreateBlock"))
                {
                    if (beforeTarget.Count != 0 || afterTarget.Count != 1)
                    {
                        throw new InvalidDataException("CreateBlock postcondition failed for " + item.TargetName + ": before=" + beforeTarget.Count.ToString(CultureInfo.InvariantCulture) + "; after=" + afterTarget.Count.ToString(CultureInfo.InvariantCulture) + ".");
                    }
                    AddIdentityCount(expectedBlocks, InventoryBlockIdentity(afterTarget[0]), 1);
                    if (HasUsableTiaObjectId(afterTarget[0]))
                    {
                        if (beforeApply.Blocks.Any(block => HasUsableTiaObjectId(block) && EqualsIgnoreCase(block.TiaObjectId, afterTarget[0].TiaObjectId)))
                        {
                            throw new InvalidDataException("CreateBlock reused a TIA object identifier that existed before apply: " + item.TargetName + ".");
                        }
                        continuity.ProvenCount++;
                    }
                    else
                    {
                        continuity.UnprovenCount++;
                    }
                }
                else
                {
                    if (beforeCurrent.Count != 1)
                    {
                        throw new InvalidDataException(item.Action + " pre-state no longer resolves to exactly one block: " + item.CurrentName + ".");
                    }

                    AddIdentityCount(expectedBlocks, InventoryBlockIdentity(beforeCurrent[0]), -1);
                    if (item.WillDelete)
                    {
                        if (afterCurrent.Count != 0)
                        {
                            throw new InvalidDataException("DeleteBlock postcondition failed; exact target still exists: " + item.CurrentName + ".");
                        }
                        if (HasUsableTiaObjectId(beforeCurrent[0]))
                        {
                            if (afterApply.Blocks.Any(block => HasUsableTiaObjectId(block) && EqualsIgnoreCase(block.TiaObjectId, beforeCurrent[0].TiaObjectId)))
                            {
                                throw new InvalidDataException("DeleteBlock left the former TIA object identifier present: " + item.CurrentName + ".");
                            }
                            continuity.ProvenCount++;
                        }
                        else
                        {
                            continuity.UnprovenCount++;
                        }
                    }
                    else
                    {
                        if (afterTarget.Count != 1)
                        {
                            throw new InvalidDataException(item.Action + " postcondition did not produce exactly one expected target: " + item.TargetName + ".");
                        }
                        if (item.WillRename
                            && !SameBlockIdentity(beforeCurrent[0], afterTarget[0])
                            && afterCurrent.Count != 0)
                        {
                            throw new InvalidDataException(item.Action + " postcondition left the old block identity present: " + item.CurrentName + ".");
                        }
                        if (HasUsableTiaObjectId(beforeCurrent[0]))
                        {
                            if (!HasUsableTiaObjectId(afterTarget[0])
                                || !EqualsIgnoreCase(beforeCurrent[0].TiaObjectId, afterTarget[0].TiaObjectId))
                            {
                                throw new InvalidDataException(item.Action + " replaced the TIA object instead of preserving object continuity: " + item.TargetName + ".");
                            }
                            continuity.ProvenCount++;
                        }
                        else
                        {
                            continuity.UnprovenCount++;
                        }
                        AddIdentityCount(expectedBlocks, InventoryBlockIdentity(afterTarget[0]), 1);
                    }
                }

                if (!item.WillDelete)
                {
                    ValidateApplyClonePostconditionContent(transitionBundle.BlockRows, item);
                }
            }

            Dictionary<string, int> actualBlocks = InventoryBlockIdentityCounts(afterApply);
            if (!IdentityCountsEqual(expectedBlocks, actualBlocks))
            {
                throw new InvalidDataException("The post-write PLC block set contains an unplanned create/delete/rename/renumber transition.");
            }

            HashSet<string> beforeGroups = new HashSet<string>(
                beforeApply.BlockGroups.Select(InventoryGroupIdentity),
                StringComparer.OrdinalIgnoreCase);
            HashSet<string> afterGroups = new HashSet<string>(
                afterApply.BlockGroups.Select(InventoryGroupIdentity),
                StringComparer.OrdinalIgnoreCase);
            List<string> removedGroups = beforeGroups.Where(x => !afterGroups.Contains(x)).ToList();
            List<string> addedGroups = afterGroups.Where(x => !beforeGroups.Contains(x)).ToList();
            if (removedGroups.Count > 0
                || addedGroups.Any(groupIdentity => !items
                    .Where(x => x.WillCreateGroup)
                    .Any(x => GroupIdentityIsExpectedForCreatedTarget(groupIdentity, x))))
            {
                throw new InvalidDataException("The post-write PLC block-group set contains collateral state not explained by CreateBlock target groups.");
            }

            List<string> scopeIssues = ApplyCloneReconciliationScopeIssues(
                transitionBundle.BlockRows,
                transitionBundle.GroupRows,
                items);
            if (scopeIssues.Count > 0)
            {
                throw new InvalidDataException("Post-write clone diff is not restricted to the immutable plan: " + string.Join("; ", scopeIssues.Take(10).ToArray()));
            }

            return continuity;
        }

        private static bool HasUsableTiaObjectId(BlockRecord block)
        {
            return block != null
                && EqualsIgnoreCase(block.TiaObjectIdStatus, "ok")
                && !string.IsNullOrWhiteSpace(block.TiaObjectId);
        }

        private static void ValidateApplyInventoryIdentityStable(
            InventorySnapshot expected,
            InventorySnapshot actual,
            string phase)
        {
            if (!IdentityCountsEqual(
                    InventoryBlockIdentityCounts(expected),
                    InventoryBlockIdentityCounts(actual)))
            {
                throw new InvalidDataException("PLC block identity set changed unexpectedly during " + phase + ".");
            }

            HashSet<string> expectedGroups = new HashSet<string>(
                expected == null ? new string[0] : expected.BlockGroups.Select(InventoryGroupIdentity),
                StringComparer.OrdinalIgnoreCase);
            HashSet<string> actualGroups = new HashSet<string>(
                actual == null ? new string[0] : actual.BlockGroups.Select(InventoryGroupIdentity),
                StringComparer.OrdinalIgnoreCase);
            if (!expectedGroups.SetEquals(actualGroups))
            {
                throw new InvalidDataException("PLC block-group identity set changed unexpectedly during " + phase + ".");
            }
        }

        private static void EnsureCleanApplyVerificationBundle(
            CloneCheckBundleEvidence bundle,
            string phase)
        {
            if (bundle == null)
            {
                throw new InvalidDataException("Missing " + phase + " clone-check evidence bundle.");
            }

            int dirtyRows = ApplyCloneDirtyRowCount(bundle.BlockRows);
            int sourceBlockers = BlockingSourceBlockerCount(bundle.BlockRows, bundle.SourceBlockerRows);
            int dirtyGroups = (bundle.GroupRows ?? new List<Dictionary<string, string>>())
                .Count(row => !EqualsIgnoreCase(GetCsvValue(row, "Status"), "unchanged"));
            if (dirtyRows != 0 || sourceBlockers != 0 || dirtyGroups != 0)
            {
                throw new InvalidDataException(
                    phase + " clone check is not clean: dirty rows="
                    + dirtyRows.ToString(CultureInfo.InvariantCulture)
                    + "; source blockers=" + sourceBlockers.ToString(CultureInfo.InvariantCulture)
                    + "; dirty groups=" + dirtyGroups.ToString(CultureInfo.InvariantCulture) + ".");
            }
        }

        private static void ValidateApplyClonePostconditionContent(
            List<Dictionary<string, string>> rows,
            ApplyPlanItem item)
        {
            List<Dictionary<string, string>> matches = (rows ?? new List<Dictionary<string, string>>())
                .Where(candidate => PostApplyRowMatchesPlanTarget(candidate, item))
                .ToList();
            if (matches.Count != 1)
            {
                throw new InvalidDataException(item.Action + " post-write export does not resolve to exactly one expected report row for " + item.TargetName + ".");
            }

            Dictionary<string, string> row = matches[0];
            string currentPath = GetCsvValue(row, "CurrentPath");
            string currentHash = GetCsvValue(row, "CurrentSourceSha256");
            string currentLanguage = FirstNonEmpty(GetCsvValue(row, "CurrentProgrammingLanguage"), GetCsvValue(row, "ProgrammingLanguage"));
            bool pureRename = EqualsIgnoreCase(item.Action, "RenameBlock");
            string expectedCanonical = pureRename
                ? item.ExecutionLiveSourceCanonicalSha256
                : item.ExecutionSourceCanonicalSha256;
            string expectedDeclarationName = pureRename
                ? item.ExecutionLiveSourceDeclarationName
                : item.ExecutionSourceDeclarationName;
            if (string.IsNullOrWhiteSpace(currentPath)
                || string.IsNullOrWhiteSpace(currentHash)
                || !File.Exists(currentPath)
                || !EqualsIgnoreCase(ComputeFileSha256(currentPath), currentHash)
                || string.IsNullOrWhiteSpace(expectedCanonical)
                || string.IsNullOrWhiteSpace(expectedDeclarationName)
                || !EqualsIgnoreCase(currentLanguage, item.ProgrammingLanguage))
            {
                throw new InvalidDataException(item.Action + " post-write source evidence is missing, stale, or has the wrong language for " + item.TargetName + ".");
            }

            if (pureRename)
            {
                string afterDeclarationName = TryReadBlockNameFromSource(currentPath);
                if (!EqualsIgnoreCase(expectedDeclarationName, item.CurrentName)
                    || !EqualsIgnoreCase(afterDeclarationName, item.TargetName))
                {
                    throw new InvalidDataException(
                        "RenameBlock post-write declaration names do not prove the authorized transition '"
                        + item.CurrentName + "' -> '" + item.TargetName + "'.");
                }
            }

            string actualCanonical = ComputeCanonicalSourceSha256(currentPath, pureRename);
            if (!EqualsIgnoreCase(expectedCanonical, actualCanonical))
            {
                throw new InvalidDataException(item.Action + " post-write token stream differs from the authorized source for " + item.TargetName + ".");
            }
        }

        private static bool BlockMatchesPlanCurrent(BlockRecord block, ApplyPlanItem item)
        {
            return block != null
                && item != null
                && EqualsIgnoreCase(block.SoftwarePath, item.SoftwarePath)
                && EqualsIgnoreCase(EmptyIfNull(block.GroupPath), EmptyIfNull(item.CurrentGroupPath))
                && EqualsIgnoreCase(block.Name, item.CurrentName)
                && EqualsIgnoreCase(BlockNumberSpace(block), FirstNonEmpty(item.CurrentNumberSpace, item.NumberSpace))
                && (SafeInt(item.CurrentNumber) <= 0 || SafeInt(block.Number) == SafeInt(item.CurrentNumber));
        }

        private static bool BlockMatchesPlanTarget(BlockRecord block, ApplyPlanItem item)
        {
            return block != null
                && item != null
                && EqualsIgnoreCase(block.SoftwarePath, item.SoftwarePath)
                && EqualsIgnoreCase(EmptyIfNull(block.GroupPath), EmptyIfNull(item.TargetGroupPath))
                && EqualsIgnoreCase(block.Name, item.TargetName)
                && EqualsIgnoreCase(BlockNumberSpace(block), item.NumberSpace)
                && (item.DesiredNumber <= 0 || SafeInt(block.Number) == item.DesiredNumber);
        }

        private static bool SameBlockIdentity(BlockRecord left, BlockRecord right)
        {
            return left != null && right != null
                && EqualsIgnoreCase(InventoryBlockIdentity(left), InventoryBlockIdentity(right));
        }

        private static Dictionary<string, int> InventoryBlockIdentityCounts(InventorySnapshot snapshot)
        {
            Dictionary<string, int> result = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (BlockRecord block in snapshot == null ? new List<BlockRecord>() : snapshot.Blocks)
            {
                AddIdentityCount(result, InventoryBlockIdentity(block), 1);
            }
            return result;
        }

        private static string InventoryBlockIdentity(BlockRecord block)
        {
            return EmptyIfNull(block.SoftwarePath) + "|"
                + EmptyIfNull(block.GroupPath) + "|"
                + BlockNumberSpace(block) + "|"
                + EmptyIfNull(block.Number) + "|"
                + EmptyIfNull(block.Name) + "|"
                + EmptyIfNull(block.ProgrammingLanguage) + "|"
                + EmptyIfNull(block.TypeName);
        }

        private static void AddIdentityCount(Dictionary<string, int> counts, string identity, int delta)
        {
            int count;
            counts.TryGetValue(identity, out count);
            count += delta;
            if (count == 0)
            {
                counts.Remove(identity);
            }
            else
            {
                counts[identity] = count;
            }
        }

        private static bool IdentityCountsEqual(Dictionary<string, int> left, Dictionary<string, int> right)
        {
            return left.Count == right.Count
                && left.All(x => right.ContainsKey(x.Key) && right[x.Key] == x.Value);
        }

        private static string InventoryGroupIdentity(BlockGroupRecord group)
        {
            return EmptyIfNull(group.SoftwarePath) + "|" + EmptyIfNull(group.GroupPath);
        }

        private static bool GroupIdentityIsExpectedForCreatedTarget(string groupIdentity, ApplyPlanItem item)
        {
            int separator = EmptyIfNull(groupIdentity).IndexOf('|');
            if (separator < 0 || item == null)
            {
                return false;
            }
            string softwarePath = groupIdentity.Substring(0, separator);
            string groupPath = groupIdentity.Substring(separator + 1);
            return EqualsIgnoreCase(softwarePath, item.SoftwarePath)
                && GroupPathContainsOrEquals(item.TargetGroupPath, groupPath);
        }

        private static void CopyApplyAfterCheckReports(string sourceDir, string blockReportPath, string sourceBlockerReportPath)
        {
            string sourceBlockReport = Path.Combine(sourceDir, CloneCheckBlockFileName);
            string sourceBlockerReport = Path.Combine(sourceDir, CloneCheckSourceBlockerFileName);
            if (File.Exists(sourceBlockReport))
            {
                File.Copy(sourceBlockReport, blockReportPath, true);
            }
            if (File.Exists(sourceBlockerReport))
            {
                File.Copy(sourceBlockerReport, sourceBlockerReportPath, true);
            }
        }

        private static void PrepareApplyValidationWorkspaceForPublish(
            string validationDir,
            PublicationExpectedModel expectedModel)
        {
            if (string.IsNullOrWhiteSpace(validationDir) || expectedModel == null)
            {
                throw new InvalidOperationException("Apply validation workspace or its immutable expected model is unavailable.");
            }

            string metadataDir = Path.Combine(validationDir, "_metadata");
            if (Directory.Exists(metadataDir))
            {
                Directory.Delete(metadataDir, true);
            }
            WriteExpectedPublicationArtifacts(validationDir, expectedModel);
            ValidateExpectedPublicationArtifacts(validationDir, expectedModel);
        }

        private static bool RetainStagingForPublicationJournal(string stagingDir, ApplyStagingCleanupResult result)
        {
            try
            {
                // Include parent transactions (apply publication) and journals
                // inside this tree (sync during apply reconciliation). Retain
                // conservatively even when a journal is unreadable or malformed.
                string directory = Path.GetFullPath(stagingDir);
                while (!string.IsNullOrWhiteSpace(directory))
                {
                    string journalPath = Path.Combine(directory, PublicationTransactionFileName);
                    if (File.Exists(journalPath) || Directory.Exists(journalPath))
                    {
                        result.EvidencePath = journalPath;
                        result.Status = "retained-for-publication-journal";
                        result.Message = "Publication journal is still present; staging, package and owner marker remain at their original paths until recovery completes: " + journalPath;
                        return true;
                    }
                    directory = Path.GetDirectoryName(directory);
                }
                EnsureExistingTreeHasNoReparsePoints(stagingDir, "publication cleanup retention check");
                string nested = Directory.GetFiles(stagingDir, PublicationTransactionFileName, SearchOption.AllDirectories).FirstOrDefault();
                if (nested != null)
                {
                    result.EvidencePath = nested;
                    result.Status = "retained-for-publication-journal";
                    result.Message = "An unfinished nested publication owns this staging tree; no cleanup or quarantine was performed: " + nested;
                    return true;
                }
                return false;
            }
            catch (Exception ex)
            {
                result.Status = "retained-for-publication-journal";
                result.Message = "Could not prove staging is free of publication journals; retained without deletion or quarantine: " + ex.Message;
                return true;
            }
        }

        private static ApplyStagingCleanupResult CleanupApplyValidationWorkspace(string validationDir)
        {
            return CleanupApplyValidationWorkspace(validationDir, path => Directory.Delete(path, true));
        }

        private static ApplyStagingCleanupResult CleanupApplyValidationWorkspace(string validationDir, Action<string> deleteDirectory)
        {
            ApplyStagingCleanupResult result = new ApplyStagingCleanupResult
            {
                OriginalPath = EmptyIfNull(validationDir),
                EvidencePath = EmptyIfNull(validationDir),
                Status = "removed",
                Message = "Apply validation workspace did not exist or was removed."
            };
            if (string.IsNullOrWhiteSpace(validationDir) || !Directory.Exists(validationDir))
            {
                return result;
            }
            if (RetainStagingForPublicationJournal(validationDir, result)) return result;
            string markerPath = Path.Combine(validationDir, ApplyValidationOwnerMarkerFileName);
            if (!File.Exists(markerPath))
            {
                result.Status = "failed";
                result.Message = "Refused to remove apply validation workspace without the OpennessLLM ownership marker.";
                return result;
            }
            string parent = Path.GetDirectoryName(validationDir);
            string outDir = Path.GetDirectoryName(parent);
            try
            {
                (deleteDirectory ?? (path => Directory.Delete(path, true)))(validationDir);
                if (Directory.Exists(validationDir)) throw new IOException("The apply validation directory still exists after deletion.");
                if (Directory.Exists(parent) && !Directory.EnumerateFileSystemEntries(parent).Any())
                {
                    Directory.Delete(parent, false);
                }
                return result;
            }
            catch (Exception deleteException)
            {
                try
                {
                    string quarantineParent = Path.Combine(outDir, "_apply-validation-quarantine");
                    Directory.CreateDirectory(quarantineParent);
                    string quarantineDir = UniquePath(Path.Combine(quarantineParent, Path.GetFileName(validationDir)));
                    Directory.Move(validationDir, quarantineDir);
                    string evidencePath = Path.Combine(quarantineDir, "cleanup-failure.txt");
                    WriteTextFile(
                        evidencePath,
                        "Apply validation cleanup failed and the owned evidence was quarantined.\n"
                            + deleteException.GetType().Name + ": " + deleteException.Message + "\n");
                    result.Status = "quarantined";
                    result.EvidencePath = evidencePath;
                    result.Message = "Apply validation cleanup failed; the owned evidence was quarantined for explicit local cleanup.";
                    return result;
                }
                catch (Exception quarantineException)
                {
                    result.Status = "failed";
                    result.Message = "Apply validation cleanup and quarantine both failed; explicit local confidentiality cleanup is required. Delete error: "
                        + deleteException.Message + "; quarantine error: " + quarantineException.Message;
                    try
                    {
                        string auditDir = Path.Combine(outDir, "_apply-validation-cleanup-audit");
                        Directory.CreateDirectory(auditDir);
                        result.EvidencePath = Path.Combine(auditDir, "failure-" + Guid.NewGuid().ToString("N") + ".txt");
                        WriteTextFile(result.EvidencePath, result.Message + Environment.NewLine + "Path: " + validationDir + Environment.NewLine);
                    }
                    catch
                    {
                        result.EvidencePath = validationDir;
                    }
                    return result;
                }
            }
        }

        private static string StageApplyClonePlanSources(
            string outDir,
            CloneCheckBundleEvidence bundle,
            List<ApplyPlanItem> plan,
            string rootDir,
            out ApplyStagingLease lease)
        {
            lease = null;
            string stagingParent = Path.Combine(outDir, "_apply-staging");
            string stagingDir = Path.Combine(stagingParent, "run-" + bundle.CheckRunId + "-" + Guid.NewGuid().ToString("N").Substring(0, 8));
            ApplyStagingLease stagedLease = new ApplyStagingLease { DirectoryPath = stagingDir };
            try
            {
                Directory.CreateDirectory(stagingDir);
                WriteTextFile(
                    Path.Combine(stagingDir, ApplyStagingOwnerMarkerFileName),
                    "OpennessLLM apply staging\ncheckRunId=" + EmptyIfNull(bundle.CheckRunId) + "\n");
                int index = 0;
                foreach (ApplyPlanItem item in plan ?? new List<ApplyPlanItem>())
                {
                    item.ExecutionSourcePath = string.Empty;
                    item.ExecutionSourceSha256 = string.Empty;
                    item.ExecutionSourceCanonicalSha256 = string.Empty;
                    item.ExecutionSourceDeclarationName = string.Empty;
                    item.ExecutionLiveSourcePath = string.Empty;
                    item.ExecutionLiveSourceSha256 = string.Empty;
                    item.ExecutionLiveSourceCanonicalSha256 = string.Empty;
                    item.ExecutionLiveSourceDeclarationName = string.Empty;
                    if (!string.IsNullOrWhiteSpace(item.LiveSourcePath))
                    {
                        if (!File.Exists(item.LiveSourcePath)
                            || string.IsNullOrWhiteSpace(item.LiveSourceSha256)
                            || !EqualsIgnoreCase(ComputeFileSha256(item.LiveSourcePath), item.LiveSourceSha256))
                        {
                            throw new InvalidDataException("Authoritative live source evidence changed before immutable staging: " + item.LiveSourcePath);
                        }

                        string stagedLiveSource = Path.Combine(
                            stagingDir,
                            "live-sources",
                            index.ToString("D4", CultureInfo.InvariantCulture) + Path.GetExtension(item.LiveSourcePath));
                        Directory.CreateDirectory(Path.GetDirectoryName(stagedLiveSource));
                        File.Copy(item.LiveSourcePath, stagedLiveSource, false);
                        if (!EqualsIgnoreCase(ComputeFileSha256(stagedLiveSource), item.LiveSourceSha256))
                        {
                            throw new InvalidDataException("Immutable live source staging did not preserve the authoritative bytes: " + item.LiveSourcePath);
                        }
                        CaptureApplyExecutionSourceEvidence(item, stagedLiveSource, true);
                    }

                    if (item.WillDelete || string.IsNullOrWhiteSpace(item.ClonePath))
                    {
                        index++;
                        continue;
                    }

                    EnsurePathInside(item.ClonePath, rootDir);
                    if (!File.Exists(item.ClonePath) || string.IsNullOrWhiteSpace(item.CloneSourceSha256))
                    {
                        throw new InvalidDataException("Apply source lacks hash-bound clone evidence: " + item.ClonePath);
                    }

                    string stagedSource = Path.Combine(
                        stagingDir,
                        "sources",
                        index.ToString("D4", CultureInfo.InvariantCulture) + Path.GetExtension(item.ClonePath));
                    Directory.CreateDirectory(Path.GetDirectoryName(stagedSource));
                    File.Copy(item.ClonePath, stagedSource, false);
                    if (!EqualsIgnoreCase(ComputeFileSha256(stagedSource), item.CloneSourceSha256))
                    {
                        throw new InvalidDataException("Apply source bytes no longer match the checked bundle: " + item.ClonePath);
                    }

                    CaptureApplyExecutionSourceEvidence(item, stagedSource, false);
                    index++;
                }

                foreach (string path in (plan ?? new List<ApplyPlanItem>())
                    .SelectMany(item => new[] { item.ExecutionLiveSourcePath, item.ExecutionSourcePath })
                    .Where(path => !string.IsNullOrWhiteSpace(path))
                    .Distinct(StringComparer.OrdinalIgnoreCase))
                {
                    // TIA may open the staged source by path. FileShare.Read allows
                    // that read while denying writers, deletion, and replacement.
                    stagedLease.HoldReadLock(path);
                }

                ValidateApplyStagingDigests(plan);
                // Detect edits that raced with staging before backup starts.
                ValidateCloneWorkspaceInventory(outDir, bundle.WorkspaceRows);
                lease = stagedLease;
                return stagingDir;
            }
            catch
            {
                stagedLease.Dispose();
                if (File.Exists(Path.Combine(stagingDir, ApplyStagingOwnerMarkerFileName)))
                {
                    CleanupApplyStaging(stagingDir);
                }
                else if (Directory.Exists(stagingDir))
                {
                    // This exact directory was created by this invocation, but
                    // marker publication itself failed before ownership became
                    // externally auditable.
                    try
                    {
                        Directory.Delete(stagingDir, true);
                    }
                    catch
                    {
                    }
                }
                throw;
            }
        }

        private static void CaptureApplyExecutionSourceEvidence(ApplyPlanItem item, string path, bool liveSource)
        {
            string rawSha256 = ComputeFileSha256(path);
            string canonicalSha256 = ComputeCanonicalSourceSha256(path, liveSource);
            string declarationName = TryReadBlockNameFromSource(path);
            if (string.IsNullOrWhiteSpace(rawSha256)
                || string.IsNullOrWhiteSpace(canonicalSha256)
                || string.IsNullOrWhiteSpace(declarationName))
            {
                throw new InvalidDataException("Staged apply source lacks immutable content evidence: " + path);
            }

            if (liveSource)
            {
                item.ExecutionLiveSourcePath = path;
                item.ExecutionLiveSourceSha256 = rawSha256;
                item.ExecutionLiveSourceCanonicalSha256 = canonicalSha256;
                item.ExecutionLiveSourceDeclarationName = declarationName;
            }
            else
            {
                item.ExecutionSourcePath = path;
                item.ExecutionSourceSha256 = rawSha256;
                item.ExecutionSourceCanonicalSha256 = canonicalSha256;
                item.ExecutionSourceDeclarationName = declarationName;
            }
        }

        private static void ValidateApplyStagingDigests(List<ApplyPlanItem> plan)
        {
            foreach (ApplyPlanItem item in plan ?? new List<ApplyPlanItem>())
            {
                ValidateApplyStagedFile(
                    item.ExecutionLiveSourcePath,
                    item.ExecutionLiveSourceSha256,
                    item.ExecutionLiveSourceCanonicalSha256,
                    item.ExecutionLiveSourceDeclarationName,
                    true,
                    item.Action + " authoritative live source");
                ValidateApplyStagedFile(
                    item.ExecutionSourcePath,
                    item.ExecutionSourceSha256,
                    item.ExecutionSourceCanonicalSha256,
                    item.ExecutionSourceDeclarationName,
                    false,
                    item.Action + " clone source");
            }
        }

        private static void ValidateApplyStagedFile(
            string path,
            string expectedRawSha256,
            string expectedCanonicalSha256,
            string expectedDeclarationName,
            bool normalizeDeclarationName,
            string label)
        {
            if (string.IsNullOrWhiteSpace(path))
            {
                return;
            }
            if (!File.Exists(path)
                || string.IsNullOrWhiteSpace(expectedRawSha256)
                || string.IsNullOrWhiteSpace(expectedCanonicalSha256)
                || string.IsNullOrWhiteSpace(expectedDeclarationName)
                || !EqualsIgnoreCase(ComputeFileSha256(path), expectedRawSha256)
                || !EqualsIgnoreCase(ComputeCanonicalSourceSha256(path, normalizeDeclarationName), expectedCanonicalSha256)
                || !EqualsIgnoreCase(TryReadBlockNameFromSource(path), expectedDeclarationName))
            {
                throw new InvalidDataException("Immutable staged bytes changed or lost their fixed evidence for " + label + ": " + path);
            }
        }

        private static ApplyStagingCleanupResult CleanupApplyStaging(string stagingDir)
        {
            return CleanupApplyStaging(stagingDir, path => Directory.Delete(path, true));
        }

        private static ApplyStagingCleanupResult CleanupApplyStaging(string stagingDir, Action<string> deleteDirectory)
        {
            ApplyStagingCleanupResult result = new ApplyStagingCleanupResult
            {
                OriginalPath = EmptyIfNull(stagingDir),
                EvidencePath = EmptyIfNull(stagingDir),
                Status = "removed",
                Message = "Apply staging did not exist or was removed."
            };
            if (string.IsNullOrWhiteSpace(stagingDir) || !Directory.Exists(stagingDir))
            {
                return result;
            }

            string markerPath = Path.Combine(stagingDir, ApplyStagingOwnerMarkerFileName);
            if (!File.Exists(markerPath))
            {
                result.Status = "failed";
                result.Message = "Refused to remove apply staging without the OpennessLLM ownership marker.";
                return result;
            }

            string stagingParent = Path.GetDirectoryName(stagingDir);
            string outDir = Path.GetDirectoryName(stagingParent);
            try
            {
                (deleteDirectory ?? (path => Directory.Delete(path, true)))(stagingDir);
                if (Directory.Exists(stagingDir))
                {
                    throw new IOException("The apply staging directory still exists after deletion.");
                }
                if (Directory.Exists(stagingParent) && !Directory.EnumerateFileSystemEntries(stagingParent).Any())
                {
                    Directory.Delete(stagingParent, false);
                }
                return result;
            }
            catch (Exception deleteException)
            {
                try
                {
                    string quarantineParent = Path.Combine(outDir, "_apply-staging-quarantine");
                    Directory.CreateDirectory(quarantineParent);
                    string quarantineDir = UniquePath(Path.Combine(quarantineParent, Path.GetFileName(stagingDir)));
                    Directory.Move(stagingDir, quarantineDir);
                    string evidencePath = Path.Combine(quarantineDir, "cleanup-failure.txt");
                    WriteTextFile(
                        evidencePath,
                        "Apply staging cleanup failed and the owned directory was quarantined.\n"
                            + deleteException.GetType().Name + ": " + deleteException.Message + "\n");
                    result.Status = "quarantined";
                    result.EvidencePath = evidencePath;
                    result.Message = "Apply staging cleanup failed; the owned directory was quarantined for explicit local cleanup.";
                    return result;
                }
                catch (Exception quarantineException)
                {
                    result.Status = "failed";
                    result.Message = "Apply staging cleanup and quarantine both failed; explicit local cleanup is required. Delete error: "
                        + deleteException.Message + "; quarantine error: " + quarantineException.Message;
                    try
                    {
                        string auditDir = Path.Combine(outDir, "_apply-staging-cleanup-audit");
                        Directory.CreateDirectory(auditDir);
                        result.EvidencePath = Path.Combine(auditDir, "failure-" + Guid.NewGuid().ToString("N") + ".txt");
                        WriteTextFile(result.EvidencePath, result.Message + Environment.NewLine + "Path: " + stagingDir + Environment.NewLine);
                    }
                    catch
                    {
                        result.EvidencePath = stagingDir;
                    }
                    return result;
                }
            }
        }

        private static void AddApplyStagingCleanupGate(
            List<ApplyCloneGateRecord> gates,
            ApplyStagingCleanupResult cleanup,
            bool savedProject,
            bool operationCommitted)
        {
            string message;
            if (cleanup.Removed)
            {
                message = "Owned immutable apply staging was removed.";
            }
            else if (operationCommitted)
            {
                message = "Operation committed; staging cleanup failed; path=" + cleanup.OriginalPath
                    + "; recovery not required; local confidentiality cleanup required. " + cleanup.Message;
            }
            else
            {
                message = "Staging cleanup failed; path=" + cleanup.OriginalPath
                    + "; local confidentiality cleanup required. Project recovery, if any, follows the primary apply result. " + cleanup.Message;
            }

            AddApplyCloneGate(
                gates,
                savedProject ? "after-save" : "after-write",
                "apply-staging-cleanup",
                cleanup.Removed ? "passed" : "warning",
                false,
                false,
                true,
                message,
                cleanup.EvidencePath,
                "owned staging removed",
                cleanup.Status);
        }

        private static void AddApplyValidationCleanupGate(
            List<ApplyCloneGateRecord> gates,
            ApplyStagingCleanupResult cleanup,
            bool savedProject,
            bool operationCommitted)
        {
            string message;
            if (cleanup.Removed)
            {
                message = "Owned apply validation evidence was removed.";
            }
            else if (operationCommitted)
            {
                message = "Operation committed; validation cleanup failed; path=" + cleanup.OriginalPath
                    + "; recovery not required; local confidentiality cleanup required. " + cleanup.Message;
            }
            else
            {
                message = "Validation cleanup failed; path=" + cleanup.OriginalPath
                    + "; local confidentiality cleanup required. Project recovery, if any, follows the primary apply result. " + cleanup.Message;
            }

            AddApplyCloneGate(
                gates,
                savedProject ? "after-save" : "after-write",
                "apply-validation-cleanup",
                cleanup.Removed ? "passed" : "warning",
                false,
                false,
                true,
                message,
                cleanup.EvidencePath,
                "owned validation workspace removed",
                cleanup.Status);
        }

        private static void ExecuteApplyClonePlan(
            object project,
            Options options,
            string outDir,
            string rootDir,
            InventorySnapshot snapshot,
            DeviceRecord softwareRecord,
            List<ApplyPlanItem> plan,
            List<ApplyCloneOperationRecord> operations)
        {
            object software = softwareRecord.Object;
            object externalSourceGroup = TryGetPropertyValue(software, "ExternalSourceGroup");
            if (externalSourceGroup == null)
            {
                throw new InvalidOperationException("PLC software does not expose ExternalSourceGroup.");
            }

            object blockGroup = TryGetPropertyValue(software, "BlockGroup");
            object externalSources = GetPropertyValue(externalSourceGroup, "ExternalSources");
            Dictionary<string, int> externalSourcesBefore = ExternalSourceIdentityCounts(externalSources);

            Console.WriteLine("Apply clone changes to TIA project");
            Console.WriteLine("Clone root: " + rootDir);
            Console.WriteLine("Changed/clone-only/clone-deleted/moved-renamed blocks selected: " + plan.Count);

            if (options.Apply)
            {
                // Once mutation begins, the pre-write evidence is no longer a
                // valid authorization artifact. A successful after-check will
                // publish a fresh completed bundle.
                InvalidateCloneCheckBundle(outDir);
            }

            for (int planIndex = 0; planIndex < plan.Count; planIndex++)
            {
                ApplyPlanItem item = plan[planIndex];
                AddApplyCloneOperation(operations, item, "started", "apply-clone-engine", "TIA operation started.", null);
                try
                {
                string status = item.Status;
                bool isChanged = EqualsIgnoreCase(item.Action, "UpdateSource");
                bool isCloneOnly = EqualsIgnoreCase(item.Action, "CreateBlock");
                bool isDeletedFromClone = EqualsIgnoreCase(item.Action, "DeleteBlock");
                bool isMovedOrRenamed = EqualsIgnoreCase(item.Action, "RenameBlock") || EqualsIgnoreCase(item.Action, "RenameAndUpdateSource");
                bool isMovedOrRenamedAndChanged = EqualsIgnoreCase(item.Action, "RenameAndUpdateSource");
                string name = item.TargetName;
                string groupPath = item.TargetGroupPath;
                string clonePath = FirstNonEmpty(item.ExecutionSourcePath, item.ClonePath);
                string language = item.ProgrammingLanguage;
                string typeName = item.TypeName;
                string instanceOfName = item.InstanceOfName;
                string numberSpace = item.NumberSpace;
                int desiredNumber = item.DesiredNumber;
                string currentName = item.CurrentName;
                string currentGroupPath = item.CurrentGroupPath;
                string currentNumber = item.CurrentNumber;
                string cloneNumber = item.TargetNumber;

                if (EqualsIgnoreCase(item.Action, "NoOp") || EqualsIgnoreCase(item.Action, "ForbiddenMove"))
                {
                    AddApplyCloneOperation(operations, item, "skipped", "apply-clone-engine", "Plan item does not execute a TIA write.", null);
                    continue;
                }

                if (!isDeletedFromClone && (string.IsNullOrWhiteSpace(clonePath) || !File.Exists(clonePath)))
                {
                    throw new FileNotFoundException("Clone source file was not found.", clonePath);
                }

                BlockRecord existing = isCloneOnly
                    ? null
                    : FindExistingBlockForApply(snapshot, currentName, currentGroupPath, currentNumber, FirstNonEmpty(item.CurrentNumberSpace, item.NumberSpace));
                if (isChanged && existing == null)
                {
                    throw new InvalidOperationException("Changed block is not present in TIA project or group changed: " + name);
                }

                if (isMovedOrRenamed && existing == null)
                {
                    throw new InvalidOperationException("Moved/renamed block is not present in TIA project: " + currentName);
                }

                if (isCloneOnly && existing != null)
                {
                    throw new InvalidOperationException("Clone-only block already exists in TIA project, refusing ambiguous create: " + name);
                }

                if (isDeletedFromClone && existing == null)
                {
                    throw new InvalidOperationException("Clone-deleted block is not present in TIA project: " + name);
                }

                if (isCloneOnly && desiredNumber > 0)
                {
                    BlockRecord numberConflict = FindBlockNumberConflict(snapshot, numberSpace, desiredNumber, null);
                    if (numberConflict != null)
                    {
                        throw new InvalidOperationException(numberSpace + " number " + desiredNumber + " is already used by '" + numberConflict.Name + "' in group '" + numberConflict.GroupPath + "'.");
                    }
                }

                bool targetGroupDiffers = item.TargetGroupDiffers;
                bool targetNameDiffers = item.TargetNameDiffers;
                object targetGroup = FindBlockGroup(blockGroup, groupPath);
                bool targetGroupMissing = item.WillCreateGroup;
                Console.WriteLine("  - " + name + " [" + language + ", " + numberSpace + "]" + (isDeletedFromClone ? "" : " from " + clonePath));
                Console.WriteLine("    Check status: " + status);
                Console.WriteLine("    Planned action: " + item.Action);
                Console.WriteLine("    Target group: " + (string.IsNullOrEmpty(groupPath) ? "_root" : groupPath));
                if (IsInstanceDbType(typeName))
                {
                    Console.WriteLine("    Instance of: " + (string.IsNullOrWhiteSpace(instanceOfName) ? "<unknown>" : instanceOfName));
                }

                if (targetGroupMissing)
                {
                    Console.WriteLine("    Action: create missing target group path before generating the block.");
                }

                if (isCloneOnly && desiredNumber > 0)
                {
                    Console.WriteLine("    Desired block number: " + numberSpace + desiredNumber);
                }

                Console.WriteLine(existing == null
                    ? "    Existing block: <not found, will create>"
                    : "    Existing block: " + existing.Name + " " + existing.ProgrammingLanguage + existing.Number);

                if (isDeletedFromClone)
                {
                    Console.WriteLine("    Action: delete block from TIA project because it is absent in clone.");
                }

                if (isMovedOrRenamed)
                {
                    Console.WriteLine("    Current TIA identity: " + (string.IsNullOrEmpty(currentGroupPath) ? "_root" : currentGroupPath) + "/" + currentName + " " + numberSpace + currentNumber);
                    Console.WriteLine("    Clone target identity: " + (string.IsNullOrEmpty(groupPath) ? "_root" : groupPath) + "/" + name + " " + numberSpace + cloneNumber);
                    if (targetGroupDiffers)
                    {
                        Console.WriteLine("    Action: forbidden clone-side move.");
                        Console.WriteLine("    Reason: TIA Openness has no safe PlcBlock move API; delete/recreate is intentionally disabled.");
                        Console.WriteLine("    To move this block, move it manually in TIA Portal, then run check-clone and sync-clone.");
                    }
                    else if (targetNameDiffers)
                    {
                        Console.WriteLine("    Action: rename block in TIA project.");
                    }
                    else
                    {
                        Console.WriteLine("    Action: refresh block metadata/content from clone.");
                    }
                }

                if (isMovedOrRenamed && targetGroupDiffers)
                {
                    throw new InvalidOperationException("Clone-side block move is forbidden for '" + currentName + "'. Move the block manually in TIA Portal and then sync the clone from the project.");
                }

                if (!options.Apply)
                {
                    AddApplyCloneOperation(operations, item, "skipped", "apply-clone-engine", "Dry-run item was not executed.", null);
                    continue;
                }

                if (isDeletedFromClone)
                {
                    DeleteEngineeringObject(existing.Object);
                    Console.WriteLine("    Block deleted.");
                    snapshot = CollectInventory(project, options.ProjectPath);
                    AddApplyCloneOperation(operations, item, "completed", "apply-clone-engine", "Block deletion completed.", null);
                    continue;
                }

                if (isMovedOrRenamed)
                {
                    if (targetNameDiffers)
                    {
                        BlockRecord nameConflict = snapshot.Blocks.FirstOrDefault(x => EqualsIgnoreCase(x.Name, name) && !SameBlockRecord(x, existing));
                        if (nameConflict != null)
                        {
                            throw new InvalidOperationException("A block named '" + name + "' already exists in group '" + nameConflict.GroupPath + "'.");
                        }
                    }

                    BlockRecord numberConflict = desiredNumber > 0 ? FindBlockNumberConflict(snapshot, numberSpace, desiredNumber, existing) : null;
                    if (numberConflict != null)
                    {
                        throw new InvalidOperationException(numberSpace + " number " + desiredNumber + " is already used by '" + numberConflict.Name + "' in group '" + numberConflict.GroupPath + "'.");
                    }

                    if (targetNameDiffers)
                    {
                        WriteAttribute(existing.Object, "Name", name, TryReadAttribute(existing.Object, "Name"));
                        Console.WriteLine("    Block renamed.");
                        snapshot = CollectInventory(project, options.ProjectPath);
                    existing = FindExistingBlockForApply(snapshot, name, groupPath, desiredNumber.ToString(), numberSpace);
                }

                    if (isMovedOrRenamedAndChanged)
                    {
                        targetGroup = FindBlockGroup(blockGroup, groupPath);
                        GenerateBlockFromCloneSource(externalSources, clonePath, targetGroup, groupPath, existing == null ? string.Empty : existing.Number, name);
                        Console.WriteLine("    Block source regenerated after rename.");
                        snapshot = CollectInventory(project, options.ProjectPath);
                        if (IsInstanceDbType(typeName))
                        {
                            VerifyInstanceDbAfterGenerate(snapshot, name, groupPath, instanceOfName);
                        }
                    }

                    AddApplyCloneOperation(operations, item, "completed", "apply-clone-engine", "Block rename/update completed.", null);
                    continue;
                }

                if (isCloneOnly)
                {
                    targetGroup = EnsureBlockGroup(blockGroup, groupPath);
                }

                string sourceName = UniqueExternalSourceName(externalSources, "_CodexApply_" + (existing == null ? "new" : existing.Number) + "_" + name + "_" + DateTime.Now.ToString("HHmmss"));
                object externalSource = CreateExternalSourceFromFile(externalSources, sourceName, clonePath);
                ExecuteWithStrictExternalSourceCleanup(externalSources, externalSource, sourceName, delegate
                {
                    object result = GenerateBlocksFromExternalSource(externalSource, targetGroup, groupPath);
                    Console.WriteLine("    GenerateBlocksFromSource result: " + SafeDescribe(result));
                    bool snapshotRefreshedAfterGenerate = false;
                    if (IsInstanceDbType(typeName))
                    {
                        snapshot = CollectInventory(project, options.ProjectPath);
                        snapshotRefreshedAfterGenerate = true;
                        VerifyInstanceDbAfterGenerate(snapshot, name, groupPath, instanceOfName);
                    }

                    if (isCloneOnly && desiredNumber > 0)
                    {
                        if (!snapshotRefreshedAfterGenerate)
                        {
                            snapshot = CollectInventory(project, options.ProjectPath);
                            snapshotRefreshedAfterGenerate = true;
                        }

                        BlockRecord created = snapshot.Blocks.FirstOrDefault(x => EqualsIgnoreCase(x.Name, name) && EqualsIgnoreCase(EmptyIfNull(x.GroupPath), groupPath));
                        if (created == null)
                        {
                            throw new InvalidOperationException("Generated block was not found for number assignment: " + name);
                        }

                        string createdNumberSpace = BlockNumberSpace(created);
                        if (!EqualsIgnoreCase(createdNumberSpace, numberSpace))
                        {
                            throw new InvalidOperationException("Generated block type does not match clone metadata. Expected " + numberSpace + ", got " + createdNumberSpace + ".");
                        }

                        BlockRecord numberConflict = FindBlockNumberConflict(snapshot, numberSpace, desiredNumber, created);
                        if (numberConflict != null)
                        {
                            throw new InvalidOperationException(numberSpace + " number " + desiredNumber + " is already used by '" + numberConflict.Name + "' in group '" + numberConflict.GroupPath + "'.");
                        }

                        SetManualBlockNumber(created, desiredNumber);
                        Console.WriteLine("    Manual number set: " + numberSpace + desiredNumber);
                        snapshot = CollectInventory(project, options.ProjectPath);
                        if (IsInstanceDbType(typeName))
                        {
                            VerifyInstanceDbAfterGenerate(snapshot, name, groupPath, instanceOfName);
                        }
                    }
                    return result;
                });
                AddApplyCloneOperation(operations, item, "completed", "apply-clone-engine", "Source generation completed.", null);
                }
                catch (Exception ex)
                {
                    AddApplyCloneOperation(operations, item, "failed", "apply-clone-engine", ex.Message, ex);
                    for (int remaining = planIndex + 1; remaining < plan.Count; remaining++)
                    {
                        AddApplyCloneOperation(operations, plan[remaining], "not-started", "apply-clone-engine", "Skipped because an earlier operation failed.", null);
                    }
                    throw;
                }
            }

            if (!IdentityCountsEqual(externalSourcesBefore, ExternalSourceIdentityCounts(externalSources)))
            {
                throw new InvalidDataException("ExternalSource collection changed during apply-clone; refusing to continue to SaveProject.");
            }
        }

        private static List<ApplyPlanItem> BuildApplyClonePlan(List<Dictionary<string, string>> rows, InventorySnapshot snapshot, string rootDir)
        {
            List<ApplyPlanItem> plan = new List<ApplyPlanItem>();
            int rowIndex = 0;
            foreach (Dictionary<string, string> row in rows)
            {
                rowIndex++;
                string status = GetCsvValue(row, "Status");
                string softwarePath = FirstNonEmpty(
                    GetCsvValue(row, "CurrentSoftwarePath"),
                    GetCsvValue(row, "CloneSoftwarePath"),
                    GetCsvValue(row, "SoftwarePath"));
                bool isChanged = EqualsIgnoreCase(status, "changed");
                bool isCloneOnly = EqualsIgnoreCase(status, "removed");
                bool isDeletedFromClone = EqualsIgnoreCase(status, "added");
                bool isMovedOrRenamed = EqualsIgnoreCase(status, "moved-or-renamed") || EqualsIgnoreCase(status, "moved-or-renamed-and-changed");
                bool isMovedOrRenamedAndChanged = EqualsIgnoreCase(status, "moved-or-renamed-and-changed");

                string cloneName = FirstNonEmpty(GetCsvValue(row, "CloneName"), isDeletedFromClone ? string.Empty : GetCsvValue(row, "Name"));
                string cloneGroupPath = isDeletedFromClone ? string.Empty : RowGroupPathKey(row, "CloneGroupPath");
                if (string.IsNullOrWhiteSpace(cloneGroupPath) && !isDeletedFromClone)
                {
                    cloneGroupPath = RowGroupPathKey(row, "GroupPath");
                }
                string cloneNumber = FirstNonEmpty(GetCsvValue(row, "CloneNumber"), isDeletedFromClone ? string.Empty : GetCsvValue(row, "Number"));
                string cloneLanguage = FirstNonEmpty(GetCsvValue(row, "CloneProgrammingLanguage"), isDeletedFromClone ? string.Empty : GetCsvValue(row, "ProgrammingLanguage"));
                string cloneTypeName = ResolveApplyRowCloneTypeName(row);
                string cloneNumberMode = FirstNonEmpty(GetCsvValue(row, "CloneNumberMode"), isDeletedFromClone ? string.Empty : GetCsvValue(row, "NumberMode"));
                string cloneAutoNumber = FirstNonEmpty(GetCsvValue(row, "CloneAutoNumber"), isDeletedFromClone ? string.Empty : GetCsvValue(row, "AutoNumber"));
                string cloneInstanceOfName = FirstNonEmpty(ResolveApplyRowCloneInstanceOfName(row), isDeletedFromClone ? string.Empty : GetCsvValue(row, "InstanceOfName"));
                string manifestSoftwarePath = GetCsvValue(row, "CloneSoftwarePath");
                string manifestGroupPath = RowGroupPathKey(row, "CloneGroupPath");
                string manifestName = GetCsvValue(row, "CloneName");
                string manifestNumber = GetCsvValue(row, "CloneNumber");
                string manifestNumberSpace = FirstNonEmpty(
                    GetCsvValue(row, "CloneNumberSpace"),
                    BlockNumberSpace(GetCsvValue(row, "CloneTypeName"), GetCsvValue(row, "CloneProgrammingLanguage")));
                bool consumesManifestRow = isDeletedFromClone
                    && !string.IsNullOrWhiteSpace(manifestSoftwarePath)
                    && !string.IsNullOrWhiteSpace(manifestName)
                    && !string.IsNullOrWhiteSpace(manifestNumberSpace);

                string currentName = FirstNonEmpty(GetCsvValue(row, "CurrentName"), isCloneOnly ? string.Empty : GetCsvValue(row, "Name"));
                string currentGroupPath = isCloneOnly ? string.Empty : RowGroupPathKey(row, "CurrentGroupPath");
                if (string.IsNullOrWhiteSpace(currentGroupPath) && !isCloneOnly)
                {
                    currentGroupPath = RowGroupPathKey(row, "GroupPath");
                }
                string currentNumber = FirstNonEmpty(GetCsvValue(row, "CurrentNumber"), isCloneOnly ? string.Empty : GetCsvValue(row, "Number"));
                string currentLanguage = FirstNonEmpty(GetCsvValue(row, "CurrentProgrammingLanguage"), isCloneOnly ? string.Empty : GetCsvValue(row, "ProgrammingLanguage"));
                string currentTypeName = ResolveApplyRowCurrentTypeName(row);
                string currentNumberMode = FirstNonEmpty(GetCsvValue(row, "CurrentNumberMode"), isCloneOnly ? string.Empty : GetCsvValue(row, "NumberMode"));
                string currentAutoNumber = FirstNonEmpty(GetCsvValue(row, "CurrentAutoNumber"), isCloneOnly ? string.Empty : GetCsvValue(row, "AutoNumber"));
                string currentInstanceOfName = FirstNonEmpty(GetCsvValue(row, "CurrentInstanceOfName"), isCloneOnly ? string.Empty : GetCsvValue(row, "InstanceOfName"));
                if (isCloneOnly)
                {
                    currentLanguage = string.Empty;
                    currentTypeName = string.Empty;
                    currentNumberMode = string.Empty;
                    currentAutoNumber = string.Empty;
                    currentInstanceOfName = string.Empty;
                }

                string currentNumberSpace = FirstNonEmpty(GetCsvValue(row, "CurrentNumberSpace"), BlockNumberSpace(currentTypeName, currentLanguage));
                string cloneNumberSpace = FirstNonEmpty(GetCsvValue(row, "CloneNumberSpace"), BlockNumberSpace(cloneTypeName, cloneLanguage));
                string targetName = isDeletedFromClone ? currentName : cloneName;
                string targetGroupPath = isDeletedFromClone ? currentGroupPath : cloneGroupPath;
                string targetNumber = isDeletedFromClone ? currentNumber : cloneNumber;
                string targetLanguage = isDeletedFromClone ? currentLanguage : cloneLanguage;
                string targetTypeName = isDeletedFromClone ? currentTypeName : cloneTypeName;
                string targetNumberMode = isDeletedFromClone ? currentNumberMode : cloneNumberMode;
                string targetAutoNumber = isDeletedFromClone ? currentAutoNumber : cloneAutoNumber;
                string targetInstanceOfName = isDeletedFromClone ? currentInstanceOfName : cloneInstanceOfName;
                string targetNumberSpace = FirstNonEmpty(isDeletedFromClone ? currentNumberSpace : cloneNumberSpace, BlockNumberSpace(targetTypeName, targetLanguage));
                string clonePath = GetCsvValue(row, "ClonePath");
                string currentPath = GetCsvValue(row, "CurrentPath");
                BlockRecord existing = isCloneOnly
                    ? null
                    : FindExistingBlockForApply(snapshot, currentName, currentGroupPath, currentNumber, FirstNonEmpty(currentNumberSpace, targetNumberSpace));
                bool targetGroupDiffers = !isCloneOnly && !isDeletedFromClone && !EqualsIgnoreCase(EmptyIfNull(currentGroupPath), EmptyIfNull(targetGroupPath));
                bool targetNameDiffers = !isCloneOnly && !isDeletedFromClone && !EqualsIgnoreCase(currentName, targetName);
                string action = "NoOp";
                if (isChanged)
                {
                    action = "UpdateSource";
                }
                else if (isCloneOnly)
                {
                    action = "CreateBlock";
                }
                else if (isDeletedFromClone)
                {
                    action = "DeleteBlock";
                }
                else if (isMovedOrRenamed)
                {
                    if (targetGroupDiffers)
                    {
                        action = "ForbiddenMove";
                    }
                    else if (targetNameDiffers)
                    {
                        action = isMovedOrRenamedAndChanged ? "RenameAndUpdateSource" : "RenameBlock";
                    }
                    else
                    {
                        action = isMovedOrRenamedAndChanged ? "UpdateSource" : "NoOp";
                    }
                }

                bool willGenerateSource = EqualsIgnoreCase(action, "UpdateSource")
                    || EqualsIgnoreCase(action, "CreateBlock")
                    || EqualsIgnoreCase(action, "RenameAndUpdateSource");
                bool willCreateGroup = EqualsIgnoreCase(action, "CreateBlock")
                    && !string.IsNullOrWhiteSpace(targetGroupPath)
                    && !GroupExistsInSnapshot(snapshot, targetGroupPath);

                plan.Add(new ApplyPlanItem
                {
                    Key = rowIndex.ToString(),
                    SourceRowIndex = rowIndex,
                    Row = row,
                    SoftwarePath = softwarePath,
                    Status = status,
                    Action = action,
                    CurrentGroupPath = currentGroupPath,
                    CurrentGroupPathDisplay = GroupPathDisplay(currentGroupPath),
                    CurrentName = currentName,
                    CurrentNumberSpace = currentNumberSpace,
                    CurrentNumber = currentNumber,
                    CurrentTypeName = currentTypeName,
                    CurrentProgrammingLanguage = currentLanguage,
                    CurrentNumberMode = currentNumberMode,
                    CurrentAutoNumber = currentAutoNumber,
                    CurrentInstanceOfName = currentInstanceOfName,
                    CurrentTiaObjectId = GetCsvValue(row, "CurrentTiaObjectId"),
                    CurrentTiaObjectIdStatus = GetCsvValue(row, "CurrentTiaObjectIdStatus"),
                    CurrentSourceSha256 = GetCsvValue(row, "CurrentSourceSha256"),
                    CloneSourceSha256 = GetCsvValue(row, "CloneSourceSha256"),
                    TargetGroupPath = targetGroupPath,
                    TargetGroupPathDisplay = GroupPathDisplay(targetGroupPath),
                    TargetName = targetName,
                    TargetNumberSpace = targetNumberSpace,
                    TargetNumber = targetNumber,
                    TypeName = targetTypeName,
                    SourceTypeName = FirstNonEmpty(GetCsvValue(row, "CloneSourceTypeName"), GetCsvValue(row, "SourceTypeName"), targetTypeName),
                    ProgrammingLanguage = targetLanguage,
                    NumberSpace = targetNumberSpace,
                    NumberMode = targetNumberMode,
                    AutoNumber = targetAutoNumber,
                    DesiredNumber = SafeInt(targetNumber),
                    InstanceOfName = targetInstanceOfName,
                    ClonePath = clonePath,
                    ExecutionSourcePath = clonePath,
                    CurrentPath = currentPath,
                    Existing = existing,
                    TargetGroupDiffers = targetGroupDiffers,
                    TargetNameDiffers = targetNameDiffers,
                    WillCreateGroup = willCreateGroup,
                    WillGenerateSource = willGenerateSource,
                    WillRename = EqualsIgnoreCase(action, "RenameBlock") || EqualsIgnoreCase(action, "RenameAndUpdateSource"),
                    WillDelete = EqualsIgnoreCase(action, "DeleteBlock"),
                    ConsumesManifestRow = consumesManifestRow,
                    ManifestSoftwarePath = manifestSoftwarePath,
                    ManifestGroupPath = manifestGroupPath,
                    ManifestName = manifestName,
                    ManifestNumberSpace = manifestNumberSpace,
                    ManifestNumber = manifestNumber,
                    ManifestFilePath = GetCsvValue(row, "ClonePath"),
                    CloneProvenance = GetCsvValue(row, "CloneProvenance"),
                    Message = GetCsvValue(row, "Message")
                });
            }

            return plan;
        }

        private static ApplyPreflightResult RunApplyClonePreflight(List<ApplyPlanItem> plan, InventorySnapshot snapshot, string rootDir, bool strictVisualSource)
        {
            ApplyPreflightResult result = new ApplyPreflightResult();
            foreach (ApplyPlanItem item in plan)
            {
                ValidateApplyPlanItem(item, plan, snapshot, rootDir, strictVisualSource, result);
            }

            ValidateApplyDeletionManifestRows(plan, Path.GetDirectoryName(rootDir), result);
            ValidateApplyCloneFinalState(plan, snapshot, result);
            return result;
        }

        private static void ValidateApplyDeletionManifestRows(List<ApplyPlanItem> plan, string outDir, ApplyPreflightResult result)
        {
            List<ApplyPlanItem> trackedDeletions = (plan ?? new List<ApplyPlanItem>())
                .Where(x => x != null && x.WillDelete && x.ConsumesManifestRow)
                .ToList();
            if (trackedDeletions.Count == 0)
            {
                return;
            }

            string manifestPath = Path.Combine(outDir, "plc-blocks.csv");
            if (!File.Exists(manifestPath))
            {
                foreach (ApplyPlanItem item in trackedDeletions)
                {
                    AddPreflightIssue(result, "error", "DELETE_MANIFEST_RECEIPT_INVALID", item, (BlockRecord)null, "Tracked clone deletion cannot be authorized because plc-blocks.csv is missing.");
                }

                return;
            }

            List<Dictionary<string, string>> rows = ReadCsv(manifestPath);
            HashSet<int> claimedRows = new HashSet<int>();
            foreach (ApplyPlanItem item in trackedDeletions)
            {
                List<int> matches = rows
                    .Select((row, index) => new { Row = row, Index = index })
                    .Where(x => ManifestRowMatchesApplyDeletion(x.Row, item))
                    .Select(x => x.Index)
                    .ToList();
                if (matches.Count != 1 || !claimedRows.Add(matches.Count == 1 ? matches[0] : -1))
                {
                    AddPreflightIssue(
                        result,
                        "error",
                        "DELETE_MANIFEST_RECEIPT_INVALID",
                        item,
                        (BlockRecord)null,
                        "DeleteTrackedBlockWithMissingSource must consume exactly one unique manifest row before any TIA write; matched " + matches.Count.ToString(CultureInfo.InvariantCulture) + ".");
                }
            }
        }

        private static void ValidateApplyPlanItem(ApplyPlanItem item, List<ApplyPlanItem> plan, InventorySnapshot snapshot, string rootDir, bool strictVisualSource, ApplyPreflightResult result)
        {
            List<DeviceRecord> selectedSoftware = GetPlcSoftwareRecords(snapshot);
            if (string.IsNullOrWhiteSpace(item.SoftwarePath))
            {
                AddPreflightIssue(result, "error", "SOFTWARE_PATH_MISSING", item, (BlockRecord)null, "Apply plan row has no authoritative SoftwarePath.");
            }
            else if (selectedSoftware.Count != 1 || !EqualsIgnoreCase(item.SoftwarePath, selectedSoftware[0].Path))
            {
                AddPreflightIssue(result, "error", "SOFTWARE_PATH_MISMATCH", item, (BlockRecord)null, "Apply plan row does not target the bundle-selected PlcSoftware.");
            }

            if (EqualsIgnoreCase(item.CloneProvenance, "explicit-new-local-source")
                && !EqualsIgnoreCase(item.Action, "CreateBlock"))
            {
                AddPreflightIssue(
                    result,
                    "error",
                    "EXPLICIT_NEW_ADOPTION_FORBIDDEN",
                    item,
                    (BlockRecord)null,
                    "An explicit-new source already collides with a live TIA block. Pending provenance can be consumed only by a successful CreateBlock receipt with matching language and canonical source content; adopting or overwriting a pre-existing block is forbidden.");
            }

            bool mutatesExistingFromClone = EqualsIgnoreCase(item.Action, "UpdateSource")
                || EqualsIgnoreCase(item.Action, "RenameBlock")
                || EqualsIgnoreCase(item.Action, "RenameAndUpdateSource");
            if (mutatesExistingFromClone
                && !EqualsIgnoreCase(item.CloneProvenance, "tracked-baseline"))
            {
                AddPreflightIssue(
                    result,
                    "error",
                    "UNKNOWN_ORPHANED_SOURCE_FORBIDDEN",
                    item,
                    (BlockRecord)null,
                    "Updating or renaming an existing TIA block is authorized only by tracked-baseline provenance. Unknown, loose, or orphaned clone sources are nonactionable; recover them through sync-clone or explicit provenance repair.");
            }

            if (EqualsIgnoreCase(item.Action, "CreateBlock")
                && !EqualsIgnoreCase(item.CloneProvenance, "explicit-new-local-source"))
            {
                AddPreflightIssue(
                    result,
                    "error",
                    "CREATE_SOURCE_PROVENANCE_REQUIRED",
                    item,
                    (BlockRecord)null,
                    "A clone-only source requires a valid adjacent sidecar with nonempty softwarePath and sourceOrigin=explicit-new-local-source. A filename number prefix alone does not authorize CreateBlock.");
            }

            if (EqualsIgnoreCase(item.Action, "ForbiddenMove"))
            {
                AddPreflightIssue(result, "error", "CLONE_SIDE_MOVE_FORBIDDEN", item, (BlockRecord)null, "Clone-side block move between groups is forbidden. Move the block manually in TIA, then run check-clone and sync-clone.");
            }

            if (!EqualsIgnoreCase(item.Action, "DeleteBlock") && !EqualsIgnoreCase(item.Action, "ForbiddenMove") && !EqualsIgnoreCase(item.Action, "NoOp"))
            {
                ValidateApplyPlanSourceFile(item, rootDir, result);
                ValidateApplyPlanVisualSource(item, strictVisualSource, result);
            }

            if (!EqualsIgnoreCase(item.Action, "CreateBlock") && !EqualsIgnoreCase(item.Action, "NoOp") && item.Existing == null)
            {
                AddPreflightIssue(result, "error", "CURRENT_BLOCK_NOT_FOUND", item, (BlockRecord)null, "Current TIA block from the latest check-clone report was not found in the live project.");
            }

            if (item.Existing != null)
            {
                ValidateCurrentBlockStillMatchesCheck(item, result);
                ValidateApplyPlanCurrentLanguage(item, result);
            }

            if (EqualsIgnoreCase(item.Action, "CreateBlock"))
            {
                BlockRecord existingByName = snapshot.Blocks.FirstOrDefault(x => EqualsIgnoreCase(x.Name, item.TargetName));
                if (existingByName != null)
                {
                    AddPreflightIssue(result, "error", "NAME_ALREADY_EXISTS", item, existingByName, "A block named '" + item.TargetName + "' already exists in the TIA project.");
                }

                if (item.DesiredNumber > 0)
                {
                    BlockRecord numberConflict = FindBlockNumberConflict(snapshot, item.NumberSpace, item.DesiredNumber, null);
                    if (numberConflict != null)
                    {
                        AddPreflightIssue(result, "error", "NUMBER_ALREADY_EXISTS", item, numberConflict, item.NumberSpace + " number " + item.DesiredNumber + " is already used.");
                    }
                }
            }

            if (item.WillRename)
            {
                BlockRecord occupied = snapshot.Blocks.FirstOrDefault(x => EqualsIgnoreCase(x.Name, item.TargetName) && !SameBlockRecord(x, item.Existing));
                if (occupied != null)
                {
                    AddPreflightIssue(result, "error", "RENAME_TARGET_NAME_OCCUPIED", item, occupied, "Rename target name is occupied at the start of apply. Complex rename/swap operations are intentionally forbidden.");
                }
            }

            if (item.TargetGroupDiffers)
            {
                AddPreflightIssue(result, "error", "GROUP_CHANGE_FORBIDDEN", item, item.Existing, "Changing a block group from clone is forbidden because TIA Openness has no safe public move API.");
            }

            if (!EqualsIgnoreCase(item.Action, "CreateBlock") && !EqualsIgnoreCase(item.Action, "DeleteBlock") && !GroupExistsInSnapshot(snapshot, item.TargetGroupPath))
            {
                AddPreflightIssue(result, "error", "TARGET_GROUP_NOT_FOUND", item, item.Existing, "Target block group does not exist in TIA and this action is not allowed to create groups.");
            }

            if (LogicalPathLooksUnsafe(item.TargetGroupPath))
            {
                AddPreflightIssue(result, "error", "UNSAFE_GROUP_PATH", item, (BlockRecord)null, "Target group path contains an unsafe segment.");
            }

            ValidateApplyPlanTypeAndNumber(item, result);
            ValidateApplyPlanInstanceDb(item, plan, snapshot, result);
            ValidateApplyPlanDeleteSafety(item, plan, snapshot, result);
        }

        private static void ValidateApplyPlanSourceFile(ApplyPlanItem item, string rootDir, ApplyPreflightResult result)
        {
            if (string.IsNullOrWhiteSpace(item.ClonePath))
            {
                AddPreflightIssue(result, "error", "CLONE_SOURCE_PATH_EMPTY", item, (BlockRecord)null, "Clone source path is empty.");
                return;
            }

            try
            {
                EnsurePathInside(item.ClonePath, rootDir);
            }
            catch (Exception ex)
            {
                AddPreflightIssue(result, "error", "CLONE_SOURCE_OUTSIDE_ROOT", item, (BlockRecord)null, ex.Message);
                return;
            }

            if (!File.Exists(item.ClonePath))
            {
                AddPreflightIssue(result, "error", "CLONE_SOURCE_NOT_FOUND", item, (BlockRecord)null, "Clone source file was not found: " + item.ClonePath);
                return;
            }

            string expectedHash = GetCsvValue(item.Row, "CloneSourceSha256");
            if (string.IsNullOrWhiteSpace(expectedHash))
            {
                AddPreflightIssue(result, "error", "CLONE_SOURCE_HASH_MISSING", item, (BlockRecord)null, "Clone check report does not contain CloneSourceSha256. Run check-clone with the current tool before apply-clone.");
                return;
            }

            string actualHash = ComputeFileSha256(item.ClonePath);
            if (!EqualsIgnoreCase(expectedHash, actualHash))
            {
                AddPreflightIssue(result, "error", "CLONE_SOURCE_STALE", item, (BlockRecord)null, "Clone source changed after the last check-clone. Run check-clone again before apply-clone.");
            }
        }

        private static void ValidateApplyPlanVisualSource(ApplyPlanItem item, bool strictVisualSource, ApplyPreflightResult result)
        {
            if (!item.WillGenerateSource || !IsVisualSourcePathOrLanguage(item.ClonePath, item.ProgrammingLanguage))
            {
                return;
            }

            bool hasSidecar = !string.IsNullOrWhiteSpace(item.ClonePath) && File.Exists(item.ClonePath + ".meta.json");
            if (EqualsIgnoreCase(item.Action, "CreateBlock") && !hasSidecar)
            {
                AddPreflightIssue(result, "error", "VISUAL_SOURCE_SIDECAR_REQUIRED", item, (BlockRecord)null, "Clone-only LAD/FBD/GRAPH source must have a sidecar .meta.json with blockKind and programmingLanguage.");
            }

            if (!VisualSourceIsVerified(item.ClonePath))
            {
                AddPreflightIssue(result, strictVisualSource ? "error" : "warning", "VISUAL_SOURCE_UNVERIFIED", item, item.Existing, "LAD/FBD/GRAPH source round-trip is experimental. Verify this source type first or mark the sidecar with visualSourceVerified=true before apply-clone --apply.");
            }
        }

        private static void ValidateCurrentBlockStillMatchesCheck(ApplyPlanItem item, ApplyPreflightResult result)
        {
            if (!string.IsNullOrWhiteSpace(item.CurrentName) && !EqualsIgnoreCase(item.Existing.Name, item.CurrentName))
            {
                AddPreflightIssue(result, "error", "CURRENT_METADATA_DRIFT", item, item.Existing, "Live TIA block name differs from the latest check-clone report.");
            }

            if (!EqualsIgnoreCase(EmptyIfNull(item.Existing.GroupPath), EmptyIfNull(item.CurrentGroupPath)))
            {
                AddPreflightIssue(result, "error", "CURRENT_METADATA_DRIFT", item, item.Existing, "Live TIA block group differs from the latest check-clone report.");
            }

            if (SafeInt(item.CurrentNumber) > 0 && SafeInt(item.Existing.Number) != SafeInt(item.CurrentNumber))
            {
                AddPreflightIssue(result, "error", "CURRENT_METADATA_DRIFT", item, item.Existing, "Live TIA block number differs from the latest check-clone report.");
            }

            if (!string.IsNullOrWhiteSpace(item.CurrentProgrammingLanguage) && !EqualsIgnoreCase(item.Existing.ProgrammingLanguage, item.CurrentProgrammingLanguage))
            {
                AddPreflightIssue(result, "error", "CURRENT_METADATA_DRIFT", item, item.Existing, "Live TIA block language differs from the latest check-clone report.");
            }

            if (EqualsIgnoreCase(item.CurrentTiaObjectIdStatus, "ok")
                && !string.IsNullOrWhiteSpace(item.CurrentTiaObjectId)
                && (!EqualsIgnoreCase(item.Existing.TiaObjectIdStatus, "ok")
                    || !EqualsIgnoreCase(item.Existing.TiaObjectId, item.CurrentTiaObjectId)))
            {
                AddPreflightIssue(result, "error", "CURRENT_OBJECT_ID_DRIFT", item, item.Existing, "Live TIA object identifier differs from the latest check-clone report.");
            }
        }

        private static void ValidateApplyPlanCurrentLanguage(ApplyPlanItem item, ApplyPreflightResult result)
        {
            if (!(item.WillGenerateSource || item.WillRename || item.WillDelete))
            {
                return;
            }

            string liveLanguage = item.Existing == null ? string.Empty : item.Existing.ProgrammingLanguage;
            if (!IsCloneSourceExportableLanguage(liveLanguage))
            {
                AddPreflightIssue(result, "error", "CURRENT_LANGUAGE_UNSUPPORTED", item, item.Existing, "Current TIA block language '" + liveLanguage + "' cannot participate in the source clone workflow. Convert the block to STL/SCL in TIA, compile, and run check-clone again.");
                return;
            }

            if (item.WillGenerateSource
                && !string.IsNullOrWhiteSpace(item.ProgrammingLanguage)
                && !EqualsIgnoreCase(liveLanguage, item.ProgrammingLanguage))
            {
                AddPreflightIssue(result, "error", "CURRENT_LANGUAGE_DIFFERS_FROM_CLONE", item, item.Existing, "Current TIA block language '" + liveLanguage + "' differs from clone language '" + item.ProgrammingLanguage + "'. Convert or sync the language change explicitly before apply-clone.");
            }
        }

        private static void ValidateApplyPlanTypeAndNumber(ApplyPlanItem item, ApplyPreflightResult result)
        {
            if (item.Existing == null || EqualsIgnoreCase(item.Action, "CreateBlock") || EqualsIgnoreCase(item.Action, "DeleteBlock"))
            {
                return;
            }

            string existingNumberSpace = FirstNonEmpty(BlockNumberSpace(item.Existing), item.CurrentNumberSpace);
            if (!string.IsNullOrWhiteSpace(existingNumberSpace)
                && !string.IsNullOrWhiteSpace(item.NumberSpace)
                && !EqualsIgnoreCase(existingNumberSpace, item.NumberSpace))
            {
                AddPreflightIssue(result, "error", "TYPE_CHANGE_FORBIDDEN", item, item.Existing, "Changing block number space from " + existingNumberSpace + " to " + item.NumberSpace + " is forbidden.");
            }

            if (!string.IsNullOrWhiteSpace(item.Existing.TypeName)
                && !string.IsNullOrWhiteSpace(item.TypeName)
                && !EqualsIgnoreCase(item.Existing.TypeName, item.TypeName))
            {
                AddPreflightIssue(result, "error", "TYPE_CHANGE_FORBIDDEN", item, item.Existing, "Changing block SDK type from '" + item.Existing.TypeName + "' to '" + item.TypeName + "' is forbidden.");
            }

            if (item.DesiredNumber > 0 && SafeInt(item.Existing.Number) > 0 && SafeInt(item.Existing.Number) != item.DesiredNumber)
            {
                AddPreflightIssue(result, "error", "NUMBER_CHANGE_FORBIDDEN", item, item.Existing, "Changing the number of an existing block is forbidden in apply-clone.");
            }

            if (MetadataValueChanged(item.Existing.NumberMode, item.NumberMode))
            {
                AddPreflightIssue(result, "error", "NUMBER_MODE_CHANGE_FORBIDDEN", item, item.Existing, "Changing NumberMode of an existing block is forbidden in apply-clone.");
            }
        }

        private static void ValidateApplyPlanInstanceDb(ApplyPlanItem item, List<ApplyPlanItem> plan, InventorySnapshot snapshot, ApplyPreflightResult result)
        {
            bool targetIsInstanceDb = IsInstanceDbType(item.TypeName);
            bool currentIsInstanceDb = IsInstanceDbType(item.CurrentTypeName);
            if (!targetIsInstanceDb && !currentIsInstanceDb)
            {
                return;
            }

            if (EqualsIgnoreCase(item.Action, "CreateBlock"))
            {
                if (string.IsNullOrWhiteSpace(item.InstanceOfName))
                {
                    AddPreflightIssue(result, "error", "INSTANCE_DB_TARGET_MISSING", item, (BlockRecord)null, "Clone-only Instance DB does not declare InstanceOfName.");
                    return;
                }

                if (!FbExistsOrWillExist(snapshot, plan, item.InstanceOfName))
                {
                    AddPreflightIssue(result, "error", "INSTANCE_DB_FB_NOT_FOUND", item, (BlockRecord)null, "Clone-only Instance DB references missing FB '" + item.InstanceOfName + "'.");
                }
            }

            if ((EqualsIgnoreCase(item.Action, "UpdateSource") || item.WillRename) && targetIsInstanceDb)
            {
                if (string.IsNullOrWhiteSpace(item.InstanceOfName))
                {
                    AddPreflightIssue(result, "error", "INSTANCE_DB_TARGET_MISSING", item, item.Existing, "Instance DB clone source does not declare InstanceOfName.");
                    return;
                }

                if (!string.IsNullOrWhiteSpace(item.CurrentInstanceOfName)
                    && !EqualsIgnoreCase(item.CurrentInstanceOfName, item.InstanceOfName))
                {
                    AddPreflightIssue(result, "error", "INSTANCE_DB_TARGET_CHANGE_FORBIDDEN", item, item.Existing, "Changing InstanceOfName is forbidden. Current: '" + item.CurrentInstanceOfName + "', clone: '" + item.InstanceOfName + "'.");
                }
            }
        }

        private static void ValidateApplyPlanDeleteSafety(ApplyPlanItem item, List<ApplyPlanItem> plan, InventorySnapshot snapshot, ApplyPreflightResult result)
        {
            if (!EqualsIgnoreCase(item.Action, "DeleteBlock") || item.Existing == null || !IsFbBlock(item.Existing))
            {
                return;
            }

            foreach (BlockRecord instanceDb in snapshot.Blocks.Where(x => IsInstanceDbType(x.TypeName) && EqualsIgnoreCase(x.InstanceOfName, item.Existing.Name)))
            {
                bool instanceDbDeletedToo = plan.Any(x => EqualsIgnoreCase(x.Action, "DeleteBlock") && x.Existing != null && SameBlockRecord(x.Existing, instanceDb));
                if (!instanceDbDeletedToo)
                {
                    AddPreflightIssue(result, "error", "DELETE_FB_HAS_INSTANCE_DB", item, instanceDb, "Deleting FB '" + item.Existing.Name + "' would leave Instance DB '" + instanceDb.Name + "' linked to it.");
                }
            }
        }

        private static void ValidateApplyCloneFinalState(List<ApplyPlanItem> plan, InventorySnapshot snapshot, ApplyPreflightResult result)
        {
            List<ApplyBlockState> states = snapshot.Blocks.Select(x => ApplyBlockState.FromBlock(x)).ToList();
            foreach (ApplyPlanItem item in plan)
            {
                if (EqualsIgnoreCase(item.Action, "ForbiddenMove"))
                {
                    continue;
                }

                if (EqualsIgnoreCase(item.Action, "DeleteBlock"))
                {
                    states.RemoveAll(x => item.Existing != null && x.SameBlock(item.Existing));
                    continue;
                }

                if (EqualsIgnoreCase(item.Action, "CreateBlock"))
                {
                    states.Add(ApplyBlockState.FromPlan(item));
                    continue;
                }

                if (EqualsIgnoreCase(item.Action, "UpdateSource")
                    || EqualsIgnoreCase(item.Action, "RenameBlock")
                    || EqualsIgnoreCase(item.Action, "RenameAndUpdateSource"))
                {
                    ApplyBlockState state = states.FirstOrDefault(x => item.Existing != null && x.SameBlock(item.Existing));
                    if (state != null)
                    {
                        state.Apply(item);
                    }
                }
            }

            foreach (IGrouping<string, ApplyBlockState> duplicate in states
                .Where(x => !string.IsNullOrWhiteSpace(x.Name))
                .GroupBy(x => x.Name, StringComparer.OrdinalIgnoreCase)
                .Where(x => x.Count() > 1 && x.Any(y => y.IsTouched)))
            {
                ApplyBlockState touched = duplicate.First(x => x.IsTouched);
                ApplyBlockState conflict = duplicate.First(x => !object.ReferenceEquals(x, touched));
                AddPreflightIssue(result, "error", "FINAL_DUPLICATE_NAME", touched.PlanItem, conflict, "Final state would contain duplicate block name '" + duplicate.Key + "'.");
            }

            foreach (IGrouping<string, ApplyBlockState> duplicate in states
                .Where(x => !string.IsNullOrWhiteSpace(x.NumberSpace) && SafeInt(x.Number) > 0)
                .GroupBy(x => x.NumberSpace + "|" + SafeInt(x.Number), StringComparer.OrdinalIgnoreCase)
                .Where(x => x.Count() > 1 && x.Any(y => y.IsTouched)))
            {
                ApplyBlockState touched = duplicate.First(x => x.IsTouched);
                ApplyBlockState conflict = duplicate.First(x => !object.ReferenceEquals(x, touched));
                AddPreflightIssue(result, "error", "FINAL_DUPLICATE_NUMBER", touched.PlanItem, conflict, "Final state would contain duplicate " + touched.NumberSpace + " number " + touched.Number + ".");
            }
        }

        private static string CreateOwnedApplyPreStateExportDirectory(string outDir)
        {
            string preflightRoot = Path.Combine(Path.GetFullPath(outDir), "_preflight");
            EnsureExistingPathChainHasNoReparsePoints(preflightRoot, "apply pre-state export root");
            string exportDir = Path.Combine(
                preflightRoot,
                "authoritative-" + DateTime.Now.ToString("yyyyMMdd-HHmmss-fff") + "-" + Guid.NewGuid().ToString("N").Substring(0, 8));
            try
            {
                Directory.CreateDirectory(exportDir);
                WriteFlatJsonObjectAtomically(
                    Path.Combine(exportDir, ApplyPreStateOwnerFileName),
                    new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                    {
                        { "owner", ProductName },
                        { "purpose", "authoritative-apply-prestate-export" },
                        { "createdUtc", DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) }
                    });
                return exportDir;
            }
            catch
            {
                if (Directory.Exists(exportDir))
                {
                    Directory.Delete(exportDir, true);
                }
                throw;
            }
        }

        private static bool IsOwnedApplyPreStateExport(string path)
        {
            string ownerPath = Path.Combine(path, ApplyPreStateOwnerFileName);
            if (!File.Exists(ownerPath))
            {
                return false;
            }
            try
            {
                Dictionary<string, string> owner = ParseStrictFlatJsonObject(File.ReadAllText(ownerPath, Encoding.UTF8), ownerPath);
                return EqualsIgnoreCase(MarkerValue(owner, "owner"), ProductName)
                    && EqualsIgnoreCase(MarkerValue(owner, "purpose"), "authoritative-apply-prestate-export");
            }
            catch
            {
                return false;
            }
        }

        private static void DeleteOwnedApplyPreStateExportStrict(string path, string outDir)
        {
            DeleteOwnedApplyPreStateExportStrict(path, outDir, delegate(string candidate) { Directory.Delete(candidate, true); });
        }

        private static void CompleteApplyPreStateCleanupBeforeWrite(ref string path, string outDir)
        {
            string cleanupPath = path;
            DeleteOwnedApplyPreStateExportStrict(cleanupPath, outDir);
            path = null;
        }

        private static void CompleteApplyPreStateCleanupBeforeWrite(
            ref string path,
            string outDir,
            Action<string> deleteAction)
        {
            string cleanupPath = path;
            DeleteOwnedApplyPreStateExportStrict(cleanupPath, outDir, deleteAction);
            path = null;
        }

        private static void DeleteOwnedApplyPreStateExportStrict(string path, string outDir, Action<string> deleteAction)
        {
            if (string.IsNullOrWhiteSpace(path) || !Directory.Exists(path))
            {
                return;
            }

            string preflightRoot = Path.Combine(Path.GetFullPath(outDir), "_preflight");
            EnsurePathInside(path, preflightRoot);
            if (!IsOwnedApplyPreStateExport(path))
            {
                throw new InvalidOperationException("Refusing to delete an unowned authoritative apply pre-state export: " + path);
            }

            Exception lastFailure = null;
            for (int attempt = 1; attempt <= 3; attempt++)
            {
                try
                {
                    EnsureExistingTreeHasNoReparsePoints(path, "owned authoritative apply pre-state export");
                    deleteAction(path);
                    if (!Directory.Exists(path))
                    {
                        return;
                    }
                    lastFailure = new IOException("Apply pre-state export still exists after delete attempt " + attempt.ToString(CultureInfo.InvariantCulture) + ".");
                }
                catch (Exception ex)
                {
                    lastFailure = ex;
                }
                System.Threading.Thread.Sleep(25);
            }

            string quarantineRoot = Path.Combine(Path.GetFullPath(outDir), "_preflight-quarantine");
            string quarantinePath = Path.Combine(
                quarantineRoot,
                "failed-" + Path.GetFileName(path) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8));
            try
            {
                Directory.CreateDirectory(quarantineRoot);
                Directory.Move(path, quarantinePath);
            }
            catch (Exception moveException)
            {
                throw new IOException(
                    "Owned authoritative apply pre-state export cleanup failed and quarantine also failed: " + path,
                    new AggregateException(lastFailure ?? new IOException("Unknown delete failure."), moveException));
            }

            WriteTextFile(
                Path.Combine(quarantinePath, "cleanup-failure.txt"),
                "Authoritative apply pre-state export cleanup failed; the owned directory was quarantined.\nOriginal: "
                    + path + "\nQuarantine: " + quarantinePath + "\nError: "
                    + (lastFailure == null ? "unknown" : lastFailure.ToString()) + "\n");
            throw new IOException(
                "Owned authoritative apply pre-state export cleanup failed; export was quarantined at: " + quarantinePath,
                lastFailure);
        }

        private static ApplyPreStateValidationResult ValidateCompleteApplyClonePreState(
            CloneCheckBundleEvidence bundle,
            InventorySnapshot snapshot,
            List<ApplyPlanItem> plan,
            object externalSourceGroup,
            string outDir,
            ApplyPreflightResult preflight,
            out string exportDir)
        {
            Type generateSourceType = FindType("Siemens.Engineering.SW.ExternalSources.IGenerateSource");
            MethodInfo generateSource = FindGenerateSourceMethod(externalSourceGroup);
            string localExportDir = CreateOwnedApplyPreStateExportDirectory(outDir);
            exportDir = localExportDir;

            int exportIndex = 0;
            return ValidateCompleteApplyClonePreStateCore(
                bundle,
                snapshot,
                plan,
                preflight,
                delegate(BlockRecord block)
                {
                    string extension = DefaultSourceExtension(block.ProgrammingLanguage);
                    string fileName = SafeFileName(
                        (++exportIndex).ToString("D4", CultureInfo.InvariantCulture)
                        + "_" + FirstNonEmpty(block.Number, "0")
                        + "_" + block.Name
                        + extension);
                    string filePath = Path.Combine(localExportDir, fileName);
                    ExportReportRow export = TryGenerateSourceFile(
                        externalSourceGroup,
                        generateSource,
                        generateSourceType,
                        block.Object,
                        filePath,
                        true);
                    return new FreshSourceEvidence
                    {
                        Status = export.Status,
                        Message = export.Message,
                        Path = filePath,
                        Sha256 = EqualsIgnoreCase(export.Status, "ok") && File.Exists(filePath)
                            ? ComputeFileSha256(filePath)
                            : string.Empty
                    };
                });
        }

        private static ApplyPreStateValidationResult ValidateCompleteApplyClonePreStateCore(
            CloneCheckBundleEvidence bundle,
            InventorySnapshot snapshot,
            List<ApplyPlanItem> plan,
            ApplyPreflightResult preflight,
            Func<BlockRecord, FreshSourceEvidence> exportSource)
        {
            ApplyPreStateValidationResult validation = new ApplyPreStateValidationResult
            {
                Performed = true,
                BlockCount = snapshot == null ? 0 : snapshot.Blocks.Count,
                GroupCount = snapshot == null ? 0 : snapshot.BlockGroups.Count
            };
            int errorsBefore = preflight.ErrorCount;
            List<Dictionary<string, string>> currentRows = (bundle == null || bundle.BlockRows == null
                    ? new List<Dictionary<string, string>>()
                    : bundle.BlockRows)
                .Where(CloneReportRowHasCurrentBlock)
                .ToList();
            List<BlockRecord> currentBlocks = snapshot == null
                ? new List<BlockRecord>()
                : snapshot.Blocks;
            HashSet<BlockRecord> claimedBlocks = new HashSet<BlockRecord>();

            if (currentRows.Count != currentBlocks.Count)
            {
                AddPreflightIssue(
                    preflight,
                    "error",
                    "COMPLETE_CURRENT_BLOCK_SET_DRIFT",
                    null,
                    (BlockRecord)null,
                    "Complete current block count differs from the checked bundle. Checked="
                        + currentRows.Count.ToString(CultureInfo.InvariantCulture)
                        + "; live=" + currentBlocks.Count.ToString(CultureInfo.InvariantCulture) + ".");
            }

            foreach (Dictionary<string, string> row in currentRows)
            {
                ApplyPlanItem item = (plan ?? new List<ApplyPlanItem>())
                    .FirstOrDefault(candidate => candidate != null && object.ReferenceEquals(candidate.Row, row));
                List<BlockRecord> matches = currentBlocks
                    .Where(candidateBlock => CloneReportCurrentRowMatchesBlock(row, candidateBlock))
                    .ToList();
                if (matches.Count != 1)
                {
                    AddPreflightIssue(
                        preflight,
                        "error",
                        "COMPLETE_CURRENT_BLOCK_IDENTITY_DRIFT",
                        item,
                        (BlockRecord)null,
                        "Checked current block does not resolve to exactly one live block: "
                            + CloneReportCurrentBlockDescription(row)
                            + "; matches=" + matches.Count.ToString(CultureInfo.InvariantCulture) + ".");
                    continue;
                }

                BlockRecord block = matches[0];
                claimedBlocks.Add(block);
                string metadataDifference = CompleteCurrentMetadataDifference(row, block);
                if (!string.IsNullOrWhiteSpace(metadataDifference))
                {
                    AddPreflightIssue(
                        preflight,
                        "error",
                        "COMPLETE_CURRENT_METADATA_DRIFT",
                        item,
                        block,
                        "Live TIA metadata differs from the checked bundle for "
                            + CloneReportCurrentBlockDescription(row) + ": " + metadataDifference + ".");
                }

                string checkedObjectId = GetCsvValue(row, "CurrentTiaObjectId");
                string checkedObjectIdStatus = GetCsvValue(row, "CurrentTiaObjectIdStatus");
                if (EqualsIgnoreCase(checkedObjectIdStatus, "ok") && !string.IsNullOrWhiteSpace(checkedObjectId))
                {
                    if (!EqualsIgnoreCase(block.TiaObjectIdStatus, "ok")
                        || !EqualsIgnoreCase(block.TiaObjectId, checkedObjectId))
                    {
                        AddPreflightIssue(
                            preflight,
                            "error",
                            "CURRENT_OBJECT_ID_DRIFT",
                            item,
                            block,
                            "Live TIA object identifier differs from the identifier captured by check-clone.");
                    }
                    else
                    {
                        validation.ProvenObjectIdCount++;
                    }
                }
                else
                {
                    validation.UnprovenObjectIdCount++;
                }

                if (!IsCloneSourceExportableLanguage(block.ProgrammingLanguage))
                {
                    continue;
                }

                validation.SourceCount++;
                string expectedHash = GetCsvValue(row, "CurrentSourceSha256");
                if (string.IsNullOrWhiteSpace(expectedHash))
                {
                    AddPreflightIssue(
                        preflight,
                        "error",
                        "CURRENT_SOURCE_HASH_MISSING",
                        item,
                        block,
                        "An exportable current block has no hash in the checked bundle: " + CloneReportCurrentBlockDescription(row) + ".");
                    continue;
                }

                FreshSourceEvidence source = exportSource == null ? null : exportSource(block);
                if (source == null
                    || !EqualsIgnoreCase(source.Status, "ok")
                    || string.IsNullOrWhiteSpace(source.Path)
                    || !File.Exists(source.Path)
                    || string.IsNullOrWhiteSpace(source.Sha256))
                {
                    AddPreflightIssue(
                        preflight,
                        "error",
                        "CURRENT_SOURCE_EXPORT_ERROR",
                        item,
                        block,
                        "Could not export the authoritative live TIA source: " + (source == null ? "no evidence" : source.Message));
                    continue;
                }

                if (item != null)
                {
                    item.LiveSourceDriftChecked = true;
                    item.LiveSourceStatus = source.Status;
                    item.LiveSourcePath = source.Path;
                    item.LiveSourceSha256 = source.Sha256;
                }
                if (!EqualsIgnoreCase(expectedHash, source.Sha256))
                {
                    AddPreflightIssue(
                        preflight,
                        "error",
                        "CURRENT_SOURCE_STALE",
                        item,
                        block,
                        "Live TIA source changed after check-clone for " + CloneReportCurrentBlockDescription(row) + ".");
                }
            }

            foreach (BlockRecord unclaimed in currentBlocks.Where(block => !claimedBlocks.Contains(block)))
            {
                AddPreflightIssue(
                    preflight,
                    "error",
                    "UNPLANNED_CURRENT_BLOCK",
                    null,
                    unclaimed,
                    "Live TIA contains a block that is absent from the checked current-side bundle: " + unclaimed.Name + ".");
            }

            HashSet<string> checkedGroups = new HashSet<string>(
                (bundle == null || bundle.GroupRows == null
                    ? new List<Dictionary<string, string>>()
                    : bundle.GroupRows)
                    .Where(row => !EqualsIgnoreCase(GetCsvValue(row, "Status"), "removed"))
                    .Select(row => NormalizeGroupPathKey(GetCsvValue(row, "GroupPath"))),
                StringComparer.OrdinalIgnoreCase);
            HashSet<string> liveGroups = new HashSet<string>(
                snapshot == null
                    ? new string[0]
                    : snapshot.BlockGroups.Select(group => NormalizeGroupPathKey(group.GroupPath)),
                StringComparer.OrdinalIgnoreCase);
            if (!checkedGroups.SetEquals(liveGroups))
            {
                AddPreflightIssue(
                    preflight,
                    "error",
                    "COMPLETE_CURRENT_GROUP_SET_DRIFT",
                    null,
                    (BlockRecord)null,
                    "Complete live TIA block-group set differs from the checked bundle.");
            }

            validation.ErrorCount = preflight.ErrorCount - errorsBefore;
            return validation;
        }

        private static bool CloneReportRowHasCurrentBlock(Dictionary<string, string> row)
        {
            return row != null
                && !string.IsNullOrWhiteSpace(GetCsvValue(row, "CurrentSoftwarePath"))
                && (!string.IsNullOrWhiteSpace(GetCsvValue(row, "CurrentName"))
                    || (!string.IsNullOrWhiteSpace(GetCsvValue(row, "CurrentNumberSpace"))
                        && !string.IsNullOrWhiteSpace(GetCsvValue(row, "CurrentNumber"))));
        }

        private static bool CloneReportCurrentRowMatchesBlock(Dictionary<string, string> row, BlockRecord block)
        {
            return block != null
                && EqualsIgnoreCase(GetCsvValue(row, "CurrentSoftwarePath"), block.SoftwarePath)
                && EqualsIgnoreCase(NormalizeGroupPathKey(GetCsvValue(row, "CurrentGroupPath")), NormalizeGroupPathKey(block.GroupPath))
                && EqualsIgnoreCase(GetCsvValue(row, "CurrentName"), block.Name)
                && EqualsIgnoreCase(GetCsvValue(row, "CurrentNumberSpace"), BlockNumberSpace(block))
                && SafeInt(GetCsvValue(row, "CurrentNumber")) == SafeInt(block.Number);
        }

        private static string CloneReportCurrentBlockDescription(Dictionary<string, string> row)
        {
            return GetCsvValue(row, "CurrentSoftwarePath") + "/"
                + GroupPathDisplay(GetCsvValue(row, "CurrentGroupPath")) + "/"
                + GetCsvValue(row, "CurrentName") + " "
                + GetCsvValue(row, "CurrentNumberSpace") + GetCsvValue(row, "CurrentNumber");
        }

        private static string CompleteCurrentMetadataDifference(Dictionary<string, string> row, BlockRecord block)
        {
            string[] differences = new[]
            {
                MetadataFieldDifference(row, "CurrentAutoNumber", block.AutoNumber),
                MetadataFieldDifference(row, "CurrentNumberMode", block.NumberMode),
                MetadataFieldDifference(row, "CurrentProgrammingLanguage", block.ProgrammingLanguage),
                MetadataFieldDifference(row, "CurrentBlockType", block.BlockType),
                MetadataFieldDifference(row, "CurrentTypeName", block.TypeName),
                MetadataFieldDifference(row, "CurrentInstanceOfName", block.InstanceOfName),
                MetadataFieldDifference(row, "CurrentInstanceOfNumber", block.InstanceOfNumber),
                MetadataFieldDifference(row, "CurrentInstanceOfType", block.InstanceOfType),
                MetadataFieldDifference(row, "CurrentSecondaryType", block.SecondaryType),
                MetadataFieldDifference(row, "CurrentMemoryLayout", block.MemoryLayout),
                MetadataFieldDifference(row, "CurrentIsConsistent", block.IsConsistent),
                MetadataFieldDifference(row, "CurrentIsKnowHowProtected", block.IsKnowHowProtected)
            };
            return string.Join(", ", differences.Where(value => !string.IsNullOrWhiteSpace(value)).ToArray());
        }

        private static string MetadataFieldDifference(Dictionary<string, string> row, string field, string actual)
        {
            string expected = GetCsvValue(row, field);
            return EqualsIgnoreCase(EmptyIfNull(expected), EmptyIfNull(actual))
                ? string.Empty
                : field + " checked='" + expected + "' live='" + EmptyIfNull(actual) + "'";
        }

        private static bool RequiresLiveSourceDriftCheck(ApplyPlanItem item)
        {
            return EqualsIgnoreCase(item.Action, "UpdateSource")
                || EqualsIgnoreCase(item.Action, "RenameBlock")
                || EqualsIgnoreCase(item.Action, "RenameAndUpdateSource")
                || EqualsIgnoreCase(item.Action, "DeleteBlock");
        }

        private static bool FbExistsOrWillExist(InventorySnapshot snapshot, List<ApplyPlanItem> plan, string fbName)
        {
            if (snapshot.Blocks.Any(x => IsFbBlock(x) && EqualsIgnoreCase(x.Name, fbName)))
            {
                return true;
            }

            return plan.Any(x => !EqualsIgnoreCase(x.Action, "DeleteBlock")
                && EqualsIgnoreCase(x.NumberSpace, "FB")
                && EqualsIgnoreCase(x.TargetName, fbName));
        }

        private static bool GroupExistsInSnapshot(InventorySnapshot snapshot, string groupPath)
        {
            if (string.IsNullOrWhiteSpace(groupPath))
            {
                return true;
            }

            string key = NormalizeGroupPathKey(groupPath);
            return snapshot.BlockGroups.Any(x => EqualsIgnoreCase(EmptyIfNull(x.GroupPath), key));
        }

        private static bool LogicalPathLooksUnsafe(string groupPath)
        {
            if (string.IsNullOrWhiteSpace(groupPath))
            {
                return false;
            }

            if (Path.IsPathRooted(groupPath))
            {
                return true;
            }

            return groupPath.Split(new[] { '/', '\\' }, StringSplitOptions.RemoveEmptyEntries)
                .Any(x => x == "." || x == ".." || x.IndexOf(':') >= 0);
        }

        private static void AddPreflightIssue(ApplyPreflightResult result, string severity, string code, ApplyPlanItem item, BlockRecord conflict, string message)
        {
            AddPreflightIssue(result, severity, code, item, conflict == null ? null : ApplyBlockState.FromBlock(conflict), message);
        }

        private static void AddPreflightIssue(ApplyPreflightResult result, string severity, string code, ApplyPlanItem item, ApplyBlockState conflict, string message)
        {
            result.Issues.Add(new ApplyPreflightIssue
            {
                Severity = severity,
                Code = code,
                Action = item == null ? string.Empty : item.Action,
                PlanItemKey = item == null ? string.Empty : item.Key,
                GroupPath = item == null ? string.Empty : item.TargetGroupPath,
                GroupPathDisplay = item == null ? string.Empty : item.TargetGroupPathDisplay,
                Name = item == null ? string.Empty : item.TargetName,
                NumberSpace = item == null ? string.Empty : item.NumberSpace,
                Number = item == null ? string.Empty : item.TargetNumber,
                ConflictingGroupPath = conflict == null ? string.Empty : conflict.GroupPath,
                ConflictingName = conflict == null ? string.Empty : conflict.Name,
                ConflictingNumber = conflict == null ? string.Empty : conflict.Number,
                Message = message
            });
        }

        private static void WriteApplyClonePreflightReports(string outDir, List<ApplyPlanItem> plan, List<ApplyPreflightIssue> issues)
        {
            string summaryPath = Path.Combine(outDir, "apply-clone-preflight-summary.txt");
            string planPath = Path.Combine(outDir, "apply-clone-preflight-plan.csv");
            string issuesPath = Path.Combine(outDir, "apply-clone-preflight-issues.csv");
            string metadataDir = Path.Combine(outDir, "_apply-reports");

            WriteCsv(planPath,
                new[]
                {
                    "Severity", "SoftwarePath", "Action", "Status", "CurrentGroupPath", "CurrentGroupPathDisplay", "CurrentGroupPathKey", "CurrentName", "CurrentNumberSpace", "CurrentNumber",
                    "TargetGroupPath", "TargetGroupPathDisplay", "TargetGroupPathKey", "TargetName", "TargetNumberSpace", "TargetNumber", "SourcePath", "CloneProvenance",
                    "WillCreateGroup", "WillRename", "WillDelete", "ConsumesManifestRow", "ManifestSoftwarePath", "ManifestGroupPath", "ManifestName", "ManifestNumberSpace", "ManifestNumber", "ManifestFilePath", "WillGenerateSource",
                    "LiveSourceDriftChecked", "LiveSourceStatus", "CurrentSourceSha256", "LiveSourceSha256", "LiveSourcePath",
                    "ExecutionSourcePath", "ExecutionSourceSha256", "ExecutionSourceCanonicalSha256", "ExecutionSourceDeclarationName",
                    "ExecutionLiveSourcePath", "ExecutionLiveSourceSha256", "ExecutionLiveSourceCanonicalSha256", "ExecutionLiveSourceDeclarationName", "Message"
                },
                plan.Select(x => new[]
                {
                    PreflightSeverityForItem(x, issues), x.SoftwarePath, x.Action, x.Status, x.CurrentGroupPath, x.CurrentGroupPathDisplay, x.CurrentGroupPath, x.CurrentName, x.CurrentNumberSpace, x.CurrentNumber,
                    x.TargetGroupPath, x.TargetGroupPathDisplay, x.TargetGroupPath, x.TargetName, x.NumberSpace, x.TargetNumber, x.ClonePath, x.CloneProvenance,
                    x.WillCreateGroup.ToString(), x.WillRename.ToString(), x.WillDelete.ToString(), x.ConsumesManifestRow.ToString(), x.ManifestSoftwarePath, x.ManifestGroupPath, x.ManifestName, x.ManifestNumberSpace, x.ManifestNumber, x.ManifestFilePath, x.WillGenerateSource.ToString(),
                    x.LiveSourceDriftChecked.ToString(), x.LiveSourceStatus, x.CurrentSourceSha256, x.LiveSourceSha256, x.LiveSourcePath,
                    x.ExecutionSourcePath, x.ExecutionSourceSha256, x.ExecutionSourceCanonicalSha256, x.ExecutionSourceDeclarationName,
                    x.ExecutionLiveSourcePath, x.ExecutionLiveSourceSha256, x.ExecutionLiveSourceCanonicalSha256, x.ExecutionLiveSourceDeclarationName, x.Message
                }));

            WriteCsv(issuesPath,
                new[]
                {
                    "Severity", "Code", "Action", "GroupPath", "GroupPathDisplay", "GroupPathKey", "Name", "NumberSpace", "Number",
                    "ConflictingGroupPath", "ConflictingName", "ConflictingNumber", "Message"
                },
                issues.Select(x => new[]
                {
                    x.Severity, x.Code, x.Action, x.GroupPath, x.GroupPathDisplay, x.GroupPath, x.Name, x.NumberSpace, x.Number,
                    x.ConflictingGroupPath, x.ConflictingName, x.ConflictingNumber, x.Message
                }));

            WriteJsonl(Path.Combine(metadataDir, "apply-clone-preflight-plan.jsonl"), plan.Select(x => ApplyPlanItemToJsonRow(x, PreflightSeverityForItem(x, issues))));
            WriteJsonl(Path.Combine(metadataDir, "apply-clone-preflight-issues.jsonl"), issues.Select(ApplyPreflightIssueToJsonRow));

            using (StreamWriter writer = NewUtf8Writer(summaryPath))
            {
                writer.WriteLine("Apply clone preflight");
                writer.WriteLine("Generated: " + DateTime.Now.ToString("o"));
                writer.WriteLine("Plan items: " + plan.Count);
                writer.WriteLine("Errors: " + issues.Count(x => EqualsIgnoreCase(x.Severity, "error")));
                writer.WriteLine("Warnings: " + issues.Count(x => EqualsIgnoreCase(x.Severity, "warning")));
                writer.WriteLine("Live source drift checks: " + plan.Count(x => x.LiveSourceDriftChecked));
                writer.WriteLine("Plan report: " + planPath);
                writer.WriteLine("Issues report: " + issuesPath);
            }
        }

        private static void PrintApplyClonePreflightSummary(string outDir, List<ApplyPlanItem> plan, ApplyPreflightResult result)
        {
            Console.WriteLine("Apply clone preflight");
            Console.WriteLine("  Plan items: " + plan.Count);
            Console.WriteLine("  Errors: " + result.ErrorCount);
            Console.WriteLine("  Warnings: " + result.WarningCount);
            Console.WriteLine("  Live source drift checks: " + plan.Count(x => x.LiveSourceDriftChecked));
            Console.WriteLine("  Plan report: " + Path.Combine(outDir, "apply-clone-preflight-plan.csv"));
            Console.WriteLine("  Issues report: " + Path.Combine(outDir, "apply-clone-preflight-issues.csv"));
            foreach (ApplyPreflightIssue issue in result.Issues.Where(x => EqualsIgnoreCase(x.Severity, "error") || EqualsIgnoreCase(x.Severity, "warning")).Take(20))
            {
                Console.WriteLine("  " + issue.Severity.ToUpperInvariant() + " " + issue.Code + ": " + issue.Message);
            }
        }

        private static void AddApplyClonePreflightGates(List<ApplyCloneGateRecord> gates, List<ApplyPlanItem> plan, ApplyPreflightResult preflight, bool applyRequested, string outDir)
        {
            AddApplyCloneGate(
                gates,
                "before-write",
                "plan-safety",
                preflight.ErrorCount == 0 ? "passed" : "failed",
                true,
                true,
                false,
                preflight.ErrorCount == 0 ? "Apply plan has no blocking preflight errors." : "Apply plan contains blocking preflight errors.",
                Path.Combine(outDir, "apply-clone-preflight-issues.csv"),
                "errors=0",
                "errors=" + preflight.ErrorCount.ToString(CultureInfo.InvariantCulture) + "; warnings=" + preflight.WarningCount.ToString(CultureInfo.InvariantCulture));

            int cloneSourceErrors = preflight.Issues.Count(x => EqualsIgnoreCase(x.Severity, "error")
                && (StartsWithIgnoreCase(x.Code, "CLONE_SOURCE_") || StartsWithIgnoreCase(x.Code, "VISUAL_SOURCE_")));
            AddApplyCloneGate(
                gates,
                "before-write",
                "clone-source-freshness",
                cloneSourceErrors == 0 ? "passed" : "failed",
                true,
                true,
                false,
                cloneSourceErrors == 0 ? "Clone source files match the latest check-clone hashes." : "At least one clone source file is stale, missing, outside _root, or not safely verified.",
                Path.Combine(outDir, "apply-clone-preflight-issues.csv"),
                "clone source errors=0",
                "clone source errors=" + cloneSourceErrors.ToString(CultureInfo.InvariantCulture));

            int liveSourceErrors = preflight.Issues.Count(x => EqualsIgnoreCase(x.Severity, "error") && StartsWithIgnoreCase(x.Code, "CURRENT_SOURCE_"));
            int liveChecks = plan.Count(x => x.LiveSourceDriftChecked);
            AddApplyCloneGate(
                gates,
                "before-write",
                "live-source-drift",
                applyRequested ? (liveSourceErrors == 0 ? "passed" : "failed") : "skipped",
                true,
                true,
                false,
                applyRequested
                    ? (liveSourceErrors == 0 ? "Live TIA source drift checks passed for required rows." : "Live TIA source drift check failed; run check-clone again before apply.")
                    : "Live TIA source drift is checked only for real --apply.",
                Path.Combine(outDir, "_preflight"),
                applyRequested ? "live source errors=0" : "not required in dry-run",
                "live checks=" + liveChecks.ToString(CultureInfo.InvariantCulture) + "; live source errors=" + liveSourceErrors.ToString(CultureInfo.InvariantCulture));
        }

        private static void AddApplyCloneSavePolicyGate(
            List<ApplyCloneGateRecord> gates,
            bool accepted,
            bool writeAttempted,
            bool writeCompleted,
            bool saveRequested,
            bool savedProject,
            Exception saveException)
        {
            string status = saveException == null && (!savedProject || (accepted && saveRequested)) ? "passed" : "failed";
            string message;
            if (saveException != null)
            {
                message = "Apply finalization, SaveProject, or post-save publication failed: " + saveException.Message;
            }
            else if (savedProject)
            {
                message = "Project was saved only after accepted apply and explicit --save.";
            }
            else if (!writeAttempted)
            {
                message = "Project was not modified by this command; save skipped.";
            }
            else if (!writeCompleted)
            {
                message = "Project was not saved because write operations did not complete.";
            }
            else if (!accepted)
            {
                message = "Project was not saved because apply-clone final gates rejected the result.";
            }
            else
            {
                message = "Project was left unsaved because --save was not requested.";
            }

            AddApplyCloneGate(
                gates,
                "save",
                "save-policy",
                status,
                true,
                false,
                true,
                message,
                string.Empty,
                "SaveProject only when accepted and --save=true",
                "accepted=" + accepted + "; writeAttempted=" + writeAttempted + "; writeCompleted=" + writeCompleted + "; saveRequested=" + saveRequested + "; saved=" + savedProject);
        }

        private static void AddApplyCloneGate(
            List<ApplyCloneGateRecord> gates,
            string phase,
            string gate,
            string status,
            bool blocking,
            bool beforeWrite,
            bool afterWrite,
            string message,
            string evidencePath,
            string expected,
            string actual)
        {
            gates.Add(new ApplyCloneGateRecord
            {
                Phase = phase,
                Gate = gate,
                Status = status,
                Blocking = blocking,
                BeforeWrite = beforeWrite,
                AfterWrite = afterWrite,
                Message = EmptyIfNull(message),
                EvidencePath = EmptyIfNull(evidencePath),
                Expected = EmptyIfNull(expected),
                Actual = EmptyIfNull(actual)
            });
        }

        private static bool CanWriteApplyClone(List<ApplyCloneGateRecord> gates)
        {
            return !gates.Any(x => x.Blocking && x.BeforeWrite && EqualsIgnoreCase(x.Status, "failed"));
        }

        private static bool IsApplyCloneAcceptedByGates(List<ApplyCloneGateRecord> gates, bool writeAttempted)
        {
            return writeAttempted && !gates.Any(x => x.Blocking && EqualsIgnoreCase(x.Status, "failed"));
        }

        private static string ApplyCloneState(bool applyRequested, bool canWrite, bool writeAttempted, bool writeCompleted, bool accepted, int planCount)
        {
            if (!canWrite)
            {
                return "blocked_before_write";
            }

            if (planCount == 0)
            {
                return "no_changes";
            }

            if (!applyRequested)
            {
                return "dry_run";
            }

            if (accepted)
            {
                return "accepted_after_write";
            }

            if (writeAttempted && !writeCompleted)
            {
                return "write_error";
            }

            return writeAttempted ? "rejected_after_write" : "blocked_before_write";
        }

        private static int ApplyCloneDirtyRowCount(List<Dictionary<string, string>> rows)
        {
            if (rows == null)
            {
                return 0;
            }

            List<RemovedCloneRef> removedCloneKeys = RemovedCloneRefs(rows);
            return rows.Count(x =>
            {
                string status = GetCsvValue(x, "Status");
                if (IsSourceBlockedStatus(status))
                {
                    BlockKey liveKey = new BlockKey(
                        FirstNonEmpty(GetCsvValue(x, "CurrentSoftwarePath"), GetCsvValue(x, "SoftwarePath")),
                        FirstNonEmpty(GetCsvValue(x, "CurrentNumberSpace"), GetCsvValue(x, "NumberSpace")),
                        FirstNonEmpty(GetCsvValue(x, "CurrentNumber"), GetCsvValue(x, "Number")),
                        FirstNonEmpty(GetCsvValue(x, "CurrentName"), GetCsvValue(x, "Name")));
                    return SourceBlockedStatusBlocksWrite(status, liveKey, removedCloneKeys);
                }

                return IsApplyCloneDirtyStatus(status);
            });
        }

        private static List<Dictionary<string, string>> ApplyCloneFormattingOnlyDirtyRows(List<Dictionary<string, string>> rows, List<ApplyPlanItem> plan, string rootDir)
        {
            return rows
                .Where(x => IsApplyCloneDirtyStatus(GetCsvValue(x, "Status")))
                .Where(x => IsApplyCloneFormattingOnlyDirtyRow(x, plan, rootDir))
                .ToList();
        }

        private static bool IsApplyCloneFormattingOnlyDirtyRow(Dictionary<string, string> row, List<ApplyPlanItem> plan, string rootDir)
        {
            if (!EqualsIgnoreCase(GetCsvValue(row, "Status"), "changed"))
            {
                return false;
            }

            string clonePath = GetCsvValue(row, "ClonePath");
            string currentPath = GetCsvValue(row, "CurrentPath");
            if (string.IsNullOrWhiteSpace(clonePath) || string.IsNullOrWhiteSpace(currentPath) || !File.Exists(clonePath) || !File.Exists(currentPath))
            {
                return false;
            }

            try
            {
                EnsurePathInside(clonePath, rootDir);
            }
            catch
            {
                return false;
            }

            ApplyPlanItem item = FindApplyPlanItemForAfterCheckRow(row, plan);
            if (item == null || item.WillDelete || !item.WillGenerateSource)
            {
                return false;
            }

            string cloneCanonical = ComputeCanonicalSourceSha256(clonePath);
            string currentCanonical = ComputeCanonicalSourceSha256(currentPath);
            return !string.IsNullOrWhiteSpace(cloneCanonical) && EqualsIgnoreCase(cloneCanonical, currentCanonical);
        }

        private static ApplyPlanItem FindApplyPlanItemForAfterCheckRow(Dictionary<string, string> row, List<ApplyPlanItem> plan)
        {
            string name = FirstNonEmpty(GetCsvValue(row, "CloneName"), GetCsvValue(row, "Name"), GetCsvValue(row, "CurrentName"));
            string groupPath = EmptyIfNull(FirstNonEmpty(RowGroupPathKey(row, "CloneGroupPath"), RowGroupPathKey(row, "GroupPath"), RowGroupPathKey(row, "CurrentGroupPath")));
            string numberSpace = FirstNonEmpty(GetCsvValue(row, "CloneNumberSpace"), GetCsvValue(row, "NumberSpace"), GetCsvValue(row, "CurrentNumberSpace"));
            string number = FirstNonEmpty(GetCsvValue(row, "CloneNumber"), GetCsvValue(row, "Number"), GetCsvValue(row, "CurrentNumber"));
            return plan.FirstOrDefault(x =>
                EqualsIgnoreCase(x.TargetName, name)
                && EqualsIgnoreCase(EmptyIfNull(x.TargetGroupPath), groupPath)
                && (string.IsNullOrWhiteSpace(number) || SafeInt(x.TargetNumber) == SafeInt(number))
                && (string.IsNullOrWhiteSpace(numberSpace) || EqualsIgnoreCase(x.NumberSpace, numberSpace)));
        }

        private static int ReconcileApplyCloneFormattingOnlyRows(List<Dictionary<string, string>> rows, string rootDir)
        {
            int reconciled = 0;
            foreach (Dictionary<string, string> row in rows)
            {
                string clonePath = GetCsvValue(row, "ClonePath");
                string currentPath = GetCsvValue(row, "CurrentPath");
                if (string.IsNullOrWhiteSpace(clonePath) || string.IsNullOrWhiteSpace(currentPath) || !File.Exists(currentPath))
                {
                    continue;
                }

                EnsurePathInside(clonePath, rootDir);
                Directory.CreateDirectory(Path.GetDirectoryName(clonePath));
                File.Copy(currentPath, clonePath, true);
                reconciled++;
            }

            return reconciled;
        }

        private static string ComputeCanonicalSourceSha256(string path)
        {
            return ComputeCanonicalSourceSha256(path, false);
        }

        private static string ComputeCanonicalSourceSha256(string path, bool normalizeTopLevelDeclarationName)
        {
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            {
                return string.Empty;
            }

            string dialect = Path.GetExtension(path).TrimStart('.').ToUpperInvariant();
            string canonical = CanonicalizeSourceText(
                File.ReadAllText(path, Encoding.UTF8),
                dialect,
                normalizeTopLevelDeclarationName);
            using (SHA256 sha = SHA256.Create())
            {
                return ToHex(sha.ComputeHash(Encoding.UTF8.GetBytes(canonical)));
            }
        }

        private static string CanonicalizeSourceText(string text, string dialect)
        {
            return CanonicalizeSourceText(text, dialect, false);
        }

        private static string CanonicalizeSourceText(string text, string dialect, bool normalizeTopLevelDeclarationName)
        {
            StringBuilder builder = new StringBuilder();
            AppendCanonicalToken(builder, "D", EmptyIfNull(dialect).ToUpperInvariant());
            bool declarationNamePending = false;
            bool declarationNameNormalized = false;
            for (int i = 0; i < text.Length; i++)
            {
                char ch = text[i];
                char next = i + 1 < text.Length ? text[i + 1] : '\0';

                if (char.IsWhiteSpace(ch))
                {
                    continue;
                }

                if (ch == '/' && next == '/')
                {
                    int commentStart = i + 2;
                    i += 2;
                    while (i < text.Length && text[i] != '\n' && text[i] != '\r')
                    {
                        i++;
                    }
                    AppendCanonicalToken(builder, "LC", NormalizeSourceComment(text.Substring(commentStart, i - commentStart)));
                    continue;
                }

                if (ch == '(' && next == '*')
                {
                    int commentStart = i + 2;
                    int depth = 1;
                    i += 2;
                    while (i < text.Length && depth > 0)
                    {
                        if (i + 1 < text.Length && text[i] == '(' && text[i + 1] == '*')
                        {
                            depth++;
                            i += 2;
                            continue;
                        }
                        if (i + 1 < text.Length && text[i] == '*' && text[i + 1] == ')')
                        {
                            depth--;
                            i += 2;
                            continue;
                        }
                        i++;
                    }
                    if (depth != 0)
                    {
                        throw new InvalidDataException("Unterminated SCL/STL block comment cannot be canonicalized safely.");
                    }
                    AppendCanonicalToken(builder, "BC", NormalizeSourceComment(text.Substring(commentStart, i - commentStart - 2)));
                    i--;
                    continue;
                }

                if (ch == '"' || ch == '\'')
                {
                    char delimiter = ch;
                    StringBuilder literal = new StringBuilder();
                    literal.Append(ch);
                    bool closed = false;
                    while (++i < text.Length)
                    {
                        char literalChar = text[i];
                        literal.Append(literalChar);
                        if (literalChar != delimiter)
                        {
                            continue;
                        }
                        if (i + 1 < text.Length && text[i + 1] == delimiter)
                        {
                            literal.Append(text[++i]);
                            continue;
                        }
                        closed = true;
                        break;
                    }
                    if (!closed)
                    {
                        throw new InvalidDataException("Unterminated SCL/STL quoted token cannot be canonicalized safely.");
                    }
                    if (normalizeTopLevelDeclarationName
                        && declarationNamePending
                        && !declarationNameNormalized)
                    {
                        AppendCanonicalToken(
                            builder,
                            delimiter == '"' ? "Q" : "L",
                            delimiter + "<BLOCK-NAME>" + delimiter);
                        declarationNamePending = false;
                        declarationNameNormalized = true;
                    }
                    else
                    {
                        AppendCanonicalToken(builder, delimiter == '"' ? "Q" : "L", literal.ToString());
                    }
                    continue;
                }

                if ((ch == '#' || ch == '%')
                    && i + 1 < text.Length
                    && IsSourceIdentifierCharacter(text[i + 1]))
                {
                    int start = i++;
                    while (i + 1 < text.Length
                        && (IsSourceIdentifierCharacter(text[i + 1])
                            || (ch == '%' && text[i + 1] == '.')))
                    {
                        i++;
                    }
                    AppendCanonicalToken(builder, ch == '#' ? "V" : "A", text.Substring(start, i - start + 1));
                    continue;
                }

                if (char.IsLetter(ch) || ch == '_')
                {
                    int start = i;
                    while (i + 1 < text.Length && IsSourceIdentifierCharacter(text[i + 1]))
                    {
                        i++;
                    }
                    string identifier = text.Substring(start, i - start + 1);
                    if (normalizeTopLevelDeclarationName
                        && declarationNamePending
                        && !declarationNameNormalized)
                    {
                        AppendCanonicalToken(builder, "I", "<BLOCK-NAME>");
                        declarationNamePending = false;
                        declarationNameNormalized = true;
                    }
                    else
                    {
                        AppendCanonicalToken(builder, "I", identifier);
                        if (normalizeTopLevelDeclarationName
                            && !declarationNameNormalized
                            && IsSourceBlockDeclarationKeyword(identifier))
                        {
                            declarationNamePending = true;
                        }
                    }
                    continue;
                }

                if (char.IsDigit(ch))
                {
                    int start = i;
                    while (i + 1 < text.Length && IsSourceNumberCharacter(text[i + 1]))
                    {
                        i++;
                    }
                    AppendCanonicalToken(builder, "N", text.Substring(start, i - start + 1));
                    continue;
                }

                string punctuation = ch.ToString();
                if (i + 1 < text.Length)
                {
                    string pair = text.Substring(i, 2);
                    if (pair == ":=" || pair == "=>" || pair == "<>" || pair == "<="
                        || pair == ">=" || pair == "**" || pair == ".." || pair == "::")
                    {
                        punctuation = pair;
                        i++;
                    }
                }
                AppendCanonicalToken(builder, "P", punctuation);
            }

            return builder.ToString();
        }

        private static bool IsSourceBlockDeclarationKeyword(string identifier)
        {
            return EqualsIgnoreCase(identifier, "FUNCTION_BLOCK")
                || EqualsIgnoreCase(identifier, "FUNCTION")
                || EqualsIgnoreCase(identifier, "DATA_BLOCK")
                || EqualsIgnoreCase(identifier, "ORGANIZATION_BLOCK");
        }

        private static string NormalizeSourceComment(string value)
        {
            StringBuilder normalized = new StringBuilder();
            bool pendingSpace = false;
            foreach (char ch in EmptyIfNull(value).Trim())
            {
                if (char.IsWhiteSpace(ch))
                {
                    pendingSpace = normalized.Length > 0;
                    continue;
                }
                if (pendingSpace)
                {
                    normalized.Append(' ');
                    pendingSpace = false;
                }
                normalized.Append(ch);
            }
            return normalized.ToString();
        }

        private static bool IsSourceIdentifierCharacter(char value)
        {
            return char.IsLetterOrDigit(value) || value == '_';
        }

        private static bool IsSourceNumberCharacter(char value)
        {
            return char.IsLetterOrDigit(value)
                || value == '_'
                || value == '#'
                || value == '.';
        }

        private static void AppendCanonicalToken(StringBuilder builder, string kind, string value)
        {
            string token = EmptyIfNull(value);
            builder.Append(kind);
            builder.Append(token.Length.ToString(CultureInfo.InvariantCulture));
            builder.Append(':');
            builder.Append(token);
            builder.Append(';');
        }

        private static bool IsApplyCloneDirtyStatus(string status)
        {
            return EqualsIgnoreCase(status, "changed")
                || EqualsIgnoreCase(status, "added")
                || EqualsIgnoreCase(status, "removed")
                || EqualsIgnoreCase(status, "moved-or-renamed")
                || EqualsIgnoreCase(status, "moved-or-renamed-and-changed")
                || EqualsIgnoreCase(status, "object-replaced-or-mismatched")
                || EqualsIgnoreCase(status, "object-id-continuity-unproven")
                || EqualsIgnoreCase(status, "ambiguous-rename-and-renumber")
                || EqualsIgnoreCase(status, "ambiguous-object-correlation")
                || EqualsIgnoreCase(status, "export-error")
                || IsSourceBlockedStatus(status);
        }

        private static void AddApplyCloneOperation(List<ApplyCloneOperationRecord> operations, ApplyPlanItem item, string status, string method, string message, Exception exception)
        {
            operations.Add(new ApplyCloneOperationRecord
            {
                Action = item == null ? string.Empty : item.Action,
                TargetGroupPath = item == null ? string.Empty : item.TargetGroupPath,
                TargetGroupPathDisplay = item == null ? string.Empty : item.TargetGroupPathDisplay,
                TargetName = item == null ? string.Empty : item.TargetName,
                NumberSpace = item == null ? string.Empty : item.NumberSpace,
                Number = item == null ? string.Empty : item.TargetNumber,
                Status = EmptyIfNull(status),
                Method = EmptyIfNull(method),
                Message = EmptyIfNull(message),
                ExceptionType = exception == null ? string.Empty : exception.GetType().Name
            });
        }

        private static void WriteApplyCloneFinalReports(
            string outDir,
            string applyState,
            bool applyRequested,
            bool saveRequested,
            bool savedProject,
            bool writeAttempted,
            bool projectMayBeModified,
            List<ApplyPlanItem> plan,
            ApplyPreflightResult preflight,
            List<ApplyCloneGateRecord> gates,
            List<ApplyCloneOperationRecord> operations)
        {
            string gatePath = Path.Combine(outDir, "apply-clone-gate.csv");
            string operationsPath = Path.Combine(outDir, "apply-clone-operations.csv");
            string summaryPath = Path.Combine(outDir, "apply-clone-summary.txt");
            string metadataDir = Path.Combine(outDir, "_apply-reports");

            WriteCsv(gatePath, ApplyCloneGateHeaders(), gates.Select(ApplyCloneGateRow));
            WriteCsv(operationsPath, ApplyCloneOperationHeaders(), operations.Select(ApplyCloneOperationRow));
            WriteJsonl(Path.Combine(metadataDir, "apply-clone-gate.jsonl"), gates.Select(ApplyCloneGateJsonRow));
            WriteJsonl(Path.Combine(metadataDir, "apply-clone-operations.jsonl"), operations.Select(ApplyCloneOperationJsonRow));

            using (StreamWriter writer = NewUtf8Writer(summaryPath))
            {
                writer.WriteLine("Apply clone summary");
                writer.WriteLine("Generated: " + DateTime.Now.ToString("o"));
                writer.WriteLine("Apply state: " + applyState);
                writer.WriteLine("Plan items: " + plan.Count);
                writer.WriteLine("Preflight errors: " + preflight.ErrorCount);
                writer.WriteLine("Preflight warnings: " + preflight.WarningCount);
                writer.WriteLine("Blocking gate failures: " + gates.Count(x => x.Blocking && EqualsIgnoreCase(x.Status, "failed")));
                writer.WriteLine("Write requested: " + applyRequested);
                writer.WriteLine("Write attempted: " + writeAttempted);
                writer.WriteLine("Project may be modified: " + projectMayBeModified);
                writer.WriteLine("Save requested: " + saveRequested);
                writer.WriteLine("Project saved: " + savedProject);
                writer.WriteLine("Recovery: " + ApplyCloneRecoveryInstruction(applyState, writeAttempted, EqualsIgnoreCase(applyState, "accepted_after_write")));
                writer.WriteLine("Gate report: " + gatePath);
                writer.WriteLine("Operations report: " + operationsPath);
            }
        }

        private static string ApplyCloneRecoveryInstruction(string applyState, bool writeAttempted, bool accepted)
        {
            if (EqualsIgnoreCase(applyState, "no_changes") || EqualsIgnoreCase(applyState, "dry_run"))
            {
                return "No recovery required.";
            }

            if (!writeAttempted)
            {
                return "No write was attempted; fix failed before-write gates and re-run check-clone/apply-clone.";
            }

            if (accepted)
            {
                return "No recovery required.";
            }

            return "Write was attempted but final gates rejected the result. Do not save the project; close without saving or restore the pre-apply backup.";
        }

