        private static string PreflightSeverityForItem(ApplyPlanItem item, List<ApplyPreflightIssue> issues)
        {
            if (issues.Any(x => EqualsIgnoreCase(x.PlanItemKey, item.Key) && EqualsIgnoreCase(x.Severity, "error")))
            {
                return "error";
            }

            if (issues.Any(x => EqualsIgnoreCase(x.PlanItemKey, item.Key) && EqualsIgnoreCase(x.Severity, "warning")))
            {
                return "warning";
            }

            return "info";
        }

