        private static int ApplyCloneRowOrder(Dictionary<string, string> row)
        {
            string status = GetCsvValue(row, "Status");
            bool isDeletedFromClone = EqualsIgnoreCase(status, "added");
            string typeName = isDeletedFromClone ? ResolveApplyRowCurrentTypeName(row) : ResolveApplyRowCloneTypeName(row);
            string language = isDeletedFromClone
                ? FirstNonEmpty(GetCsvValue(row, "CurrentProgrammingLanguage"), GetCsvValue(row, "ProgrammingLanguage"))
                : FirstNonEmpty(GetCsvValue(row, "CloneProgrammingLanguage"), GetCsvValue(row, "ProgrammingLanguage"));
            string numberSpace = BlockNumberSpace(typeName, language);

            if (isDeletedFromClone)
            {
                if (IsInstanceDbType(typeName))
                {
                    return 0;
                }

                return EqualsIgnoreCase(numberSpace, "DB") ? 1 : 2;
            }

            if (IsInstanceDbType(typeName))
            {
                return 30;
            }

            return EqualsIgnoreCase(numberSpace, "DB") ? 20 : 10;
        }

        private static void ValidateApplyCloneSourceHashes(List<Dictionary<string, string>> rows, string rootDir)
        {
            foreach (Dictionary<string, string> row in rows)
            {
                string status = GetCsvValue(row, "Status");
                if (EqualsIgnoreCase(status, "added") || EqualsIgnoreCase(status, "export-error"))
                {
                    continue;
                }

                string clonePath = GetCsvValue(row, "ClonePath");
                if (string.IsNullOrWhiteSpace(clonePath))
                {
                    continue;
                }

                EnsurePathInside(clonePath, rootDir);
                if (!File.Exists(clonePath))
                {
                    continue;
                }

                string expectedHash = GetCsvValue(row, "CloneSourceSha256");
                if (string.IsNullOrWhiteSpace(expectedHash))
                {
                    throw new InvalidOperationException("Clone check report does not contain CloneSourceSha256 for '" + FirstNonEmpty(GetCsvValue(row, "CloneName"), GetCsvValue(row, "Name")) + "'. Run check-clone with the current tool before apply-clone.");
                }

                string actualHash = ComputeFileSha256(clonePath);
                if (!EqualsIgnoreCase(expectedHash, actualHash))
                {
                    throw new InvalidOperationException("Clone source changed after the last check-clone: " + clonePath + ". Run check-clone again before apply-clone.");
                }
            }
        }

        private static void ValidateApplyCloneInstanceDbPreflight(List<Dictionary<string, string>> rows, InventorySnapshot snapshot, string rootDir)
        {
            foreach (Dictionary<string, string> row in rows)
            {
                string status = GetCsvValue(row, "Status");
                bool isCloneOnly = EqualsIgnoreCase(status, "removed");
                bool isDeletedFromClone = EqualsIgnoreCase(status, "added");
                bool isChanged = EqualsIgnoreCase(status, "changed");
                bool isMovedOrRenamed = EqualsIgnoreCase(status, "moved-or-renamed") || EqualsIgnoreCase(status, "moved-or-renamed-and-changed");

                if (!isDeletedFromClone)
                {
                    string clonePath = GetCsvValue(row, "ClonePath");
                    if (!string.IsNullOrWhiteSpace(clonePath))
                    {
                        EnsurePathInside(clonePath, rootDir);
                    }
                }

                string cloneTypeName = ResolveApplyRowCloneTypeName(row);
                string currentTypeName = ResolveApplyRowCurrentTypeName(row);
                bool cloneIsInstanceDb = IsInstanceDbType(cloneTypeName);
                bool currentIsInstanceDb = IsInstanceDbType(currentTypeName);
                if (!cloneIsInstanceDb && !currentIsInstanceDb)
                {
                    continue;
                }

                string cloneName = FirstNonEmpty(GetCsvValue(row, "CloneName"), isDeletedFromClone ? string.Empty : GetCsvValue(row, "Name"));
                string currentName = FirstNonEmpty(GetCsvValue(row, "CurrentName"), isCloneOnly ? string.Empty : GetCsvValue(row, "Name"));
                string displayName = FirstNonEmpty(cloneName, currentName, GetCsvValue(row, "Name"));

                if (isCloneOnly)
                {
                    string instanceOfName = ResolveApplyRowCloneInstanceOfName(row);
                    if (string.IsNullOrWhiteSpace(instanceOfName))
                    {
                        throw new InvalidOperationException("Clone-only Instance DB '" + displayName + "' does not declare InstanceOfName in its .db source.");
                    }

                    if (!InstanceDbTargetExistsOrWillExist(snapshot, rows, instanceOfName))
                    {
                        throw new InvalidOperationException("Clone-only Instance DB '" + displayName + "' references missing FB '" + instanceOfName + "'. Create or import the FB first.");
                    }
                }

                if (isChanged || isMovedOrRenamed)
                {
                    string cloneInstanceOfName = ResolveApplyRowCloneInstanceOfName(row);
                    string currentInstanceOfName = ResolveApplyRowCurrentInstanceOfName(row, snapshot);
                    if (string.IsNullOrWhiteSpace(cloneInstanceOfName))
                    {
                        throw new InvalidOperationException("Instance DB '" + displayName + "' does not declare InstanceOfName in clone source.");
                    }

                    if (!string.IsNullOrWhiteSpace(currentInstanceOfName)
                        && !EqualsIgnoreCase(currentInstanceOfName, cloneInstanceOfName))
                    {
                        throw new InvalidOperationException("Changing InstanceOfName for Instance DB '" + displayName + "' is forbidden. Current: '" + currentInstanceOfName + "', clone: '" + cloneInstanceOfName + "'.");
                    }
                }
            }
        }

        private static bool InstanceDbTargetExistsOrWillExist(InventorySnapshot snapshot, List<Dictionary<string, string>> rows, string instanceOfName)
        {
            if (snapshot.Blocks.Any(x => IsFbBlock(x) && EqualsIgnoreCase(x.Name, instanceOfName)))
            {
                return true;
            }

            foreach (Dictionary<string, string> row in rows)
            {
                string status = GetCsvValue(row, "Status");
                if (EqualsIgnoreCase(status, "added"))
                {
                    continue;
                }

                string cloneTypeName = ResolveApplyRowCloneTypeName(row);
                string cloneLanguage = FirstNonEmpty(GetCsvValue(row, "CloneProgrammingLanguage"), GetCsvValue(row, "ProgrammingLanguage"));
                if (!EqualsIgnoreCase(BlockNumberSpace(cloneTypeName, cloneLanguage), "FB"))
                {
                    continue;
                }

                string cloneName = FirstNonEmpty(GetCsvValue(row, "CloneName"), GetCsvValue(row, "Name"));
                if (EqualsIgnoreCase(cloneName, instanceOfName))
                {
                    return true;
                }
            }

            return false;
        }

        private static bool IsFbBlock(BlockRecord block)
        {
            return block != null && EqualsIgnoreCase(BlockNumberSpace(block), "FB");
        }

        private static bool IsFbBlock(string typeName)
        {
            return EmptyIfNull(typeName).EndsWith(".FB", StringComparison.OrdinalIgnoreCase);
        }

        private static string ResolveApplyRowCloneTypeName(Dictionary<string, string> row)
        {
            string typeName = FirstNonEmpty(GetCsvValue(row, "CloneTypeName"), GetCsvValue(row, "TypeName"));
            string clonePath = GetCsvValue(row, "ClonePath");
            DbSourceInfo dbSource = ParseDbSource(clonePath);
            if (dbSource.IsDataBlock)
            {
                return dbSource.IsInstanceDb
                    ? "Siemens.Engineering.SW.Blocks.InstanceDB"
                    : "Siemens.Engineering.SW.Blocks.GlobalDB";
            }

            if (string.IsNullOrWhiteSpace(typeName) && !string.IsNullOrWhiteSpace(clonePath) && File.Exists(clonePath))
            {
                typeName = InferBlockTypeNameFromSourceFile(clonePath, FirstNonEmpty(GetCsvValue(row, "CloneProgrammingLanguage"), GetCsvValue(row, "ProgrammingLanguage")));
            }

            return typeName;
        }

        private static string ResolveApplyRowCurrentTypeName(Dictionary<string, string> row)
        {
            return FirstNonEmpty(GetCsvValue(row, "CurrentTypeName"), GetCsvValue(row, "TypeName"));
        }

        private static string ResolveApplyRowCloneInstanceOfName(Dictionary<string, string> row)
        {
            string instanceOfName = FirstNonEmpty(GetCsvValue(row, "CloneInstanceOfName"), GetCsvValue(row, "InstanceOfName"));
            if (!string.IsNullOrWhiteSpace(instanceOfName))
            {
                return instanceOfName;
            }

            DbSourceInfo dbSource = ParseDbSource(GetCsvValue(row, "ClonePath"));
            return dbSource.IsInstanceDb ? dbSource.InstanceOfName : string.Empty;
        }

        private static string ResolveApplyRowCurrentInstanceOfName(Dictionary<string, string> row, InventorySnapshot snapshot)
        {
            string instanceOfName = FirstNonEmpty(GetCsvValue(row, "CurrentInstanceOfName"), GetCsvValue(row, "InstanceOfName"));
            if (!string.IsNullOrWhiteSpace(instanceOfName))
            {
                return instanceOfName;
            }

            string currentName = FirstNonEmpty(GetCsvValue(row, "CurrentName"), GetCsvValue(row, "Name"));
            string currentGroupPath = RowGroupPathKey(row, "CurrentGroupPath");
            if (string.IsNullOrWhiteSpace(currentGroupPath))
            {
                currentGroupPath = RowGroupPathKey(row, "GroupPath");
            }
            string currentNumber = FirstNonEmpty(GetCsvValue(row, "CurrentNumber"), GetCsvValue(row, "Number"));
            string currentTypeName = ResolveApplyRowCurrentTypeName(row);
            string currentLanguage = FirstNonEmpty(GetCsvValue(row, "CurrentProgrammingLanguage"), GetCsvValue(row, "ProgrammingLanguage"));
            BlockRecord existing = FindExistingBlockForApply(snapshot, currentName, currentGroupPath, currentNumber, BlockNumberSpace(currentTypeName, currentLanguage));
            return existing == null ? string.Empty : existing.InstanceOfName;
        }

        private static bool IsInstanceDbType(string typeName)
        {
            return EmptyIfNull(typeName).EndsWith(".InstanceDB", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsGlobalDbType(string typeName)
        {
            return EmptyIfNull(typeName).EndsWith(".GlobalDB", StringComparison.OrdinalIgnoreCase);
        }

        private static void VerifyInstanceDbAfterGenerate(InventorySnapshot snapshot, string name, string groupPath, string instanceOfName)
        {
            BlockRecord block = snapshot.Blocks.FirstOrDefault(x => EqualsIgnoreCase(x.Name, name) && EqualsIgnoreCase(EmptyIfNull(x.GroupPath), EmptyIfNull(groupPath)));
            if (block == null)
            {
                throw new InvalidOperationException("Generated Instance DB was not found in TIA project: " + name);
            }

            if (!IsInstanceDbType(block.TypeName))
            {
                throw new InvalidOperationException("Generated block '" + name + "' is not an InstanceDB. Actual type: " + block.TypeName);
            }

            if (!string.IsNullOrWhiteSpace(instanceOfName)
                && !EqualsIgnoreCase(block.InstanceOfName, instanceOfName))
            {
                throw new InvalidOperationException("Generated Instance DB '" + name + "' is linked to '" + block.InstanceOfName + "', expected '" + instanceOfName + "'.");
            }
        }

        private static void DeleteBlockCommand(object project, Options options)
        {
            if (string.IsNullOrWhiteSpace(options.Name))
            {
                throw new ArgumentException("delete-block requires --name.");
            }

            InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
            List<BlockRecord> matches = snapshot.Blocks
                .Where(x => EqualsIgnoreCase(x.Name, options.Name))
                .Where(x => string.IsNullOrWhiteSpace(options.GroupPath)
                    || EqualsIgnoreCase(EmptyIfNull(x.GroupPath), NormalizeGroupPathKey(FirstNonEmpty(options.GroupPathKey, options.GroupPath)))
                    || EqualsIgnoreCase(EmptyIfNull(x.GroupPathDisplay), EmptyIfNull(options.GroupPath).Trim('/').Trim('\\')))
                .ToList();

            if (matches.Count == 0)
            {
                throw new InvalidOperationException("No matching block was found.");
            }

            if (matches.Count > 1)
            {
                Console.WriteLine("More than one block matched. Add --group to narrow it down.");
                foreach (BlockRecord match in matches.Take(20))
                {
                    Console.WriteLine("  - " + (string.IsNullOrWhiteSpace(match.GroupPathDisplay) ? "_root" : match.GroupPathDisplay) + "/" + match.Name + " DB" + match.Number + " " + match.ProgrammingLanguage);
                }

                throw new InvalidOperationException("Ambiguous block target.");
            }

            BlockRecord block = matches[0];
            Console.WriteLine("Delete block");
            Console.WriteLine("  Name: " + block.Name);
            Console.WriteLine("  Number: " + block.Number);
            Console.WriteLine("  Language: " + block.ProgrammingLanguage);
            Console.WriteLine("  Group: " + (string.IsNullOrEmpty(block.GroupPathDisplay) ? "<root>" : block.GroupPathDisplay));
            Console.WriteLine("  Group key: " + (string.IsNullOrEmpty(block.GroupPath) ? "_root" : block.GroupPath));
            Console.WriteLine("  Type: " + block.TypeName);

            if (!options.Apply)
            {
                Console.WriteLine();
                Console.WriteLine("Dry-run only. Re-run with --apply to delete the block.");
                return;
            }

            DeleteEngineeringObject(block.Object);
            Console.WriteLine("Block deleted.");

            if (options.Save)
            {
                SaveProject(project);
                Console.WriteLine("Project saved.");
            }
            else
            {
                Console.WriteLine("Project was not saved. Use --save to persist the delete.");
            }
        }

        private static void CreateTestVisualFbCommand(object project, Options options)
        {
            List<string> languages = ParseVisualTestLanguages(options.Language);
            if (options.Number > 0 && languages.Count > 1)
            {
                throw new ArgumentException("--number can be used only when --language selects one language.");
            }

            InventorySnapshot snapshot = CollectInventory(project, options.ProjectPath);
            string groupPath = string.IsNullOrWhiteSpace(options.GroupPath)
                ? "Openness_Visual_Tests"
                : NormalizeGroupPathKey(FirstNonEmpty(options.GroupPathKey, options.GroupPath));

            object software = GetFirstPlcSoftware(snapshot);
            if (software == null)
            {
                throw new InvalidOperationException("No PLC software container was found.");
            }

            object blockGroup = TryGetPropertyValue(software, "BlockGroup");
            object targetGroup = FindBlockGroup(blockGroup, groupPath);
            bool targetGroupCreatedInThisRun = false;

            Console.WriteLine("Create test visual FB block(s)");
            Console.WriteLine("  Group: " + (string.IsNullOrEmpty(groupPath) ? "<root>" : groupPath));
            Console.WriteLine("  Languages: " + string.Join(", ", languages.ToArray()));
            if (targetGroup == null)
            {
                Console.WriteLine("  Target group: <missing, will be created on --apply>");
            }

            int createdCount = 0;
            try
            {
                foreach (string language in languages)
                {
                    string fbName = VisualTestFbName(options.Name, language, languages.Count);
                    BlockRecord existingByName = snapshot.Blocks.FirstOrDefault(x => EqualsIgnoreCase(x.Name, fbName));
                    if (existingByName != null)
                    {
                        Console.WriteLine("  - " + fbName + " [" + language + "]");
                        Console.WriteLine("    Existing block: " + existingByName.Name + " " + BlockNumberSpace(existingByName) + existingByName.Number + " in " + (string.IsNullOrWhiteSpace(existingByName.GroupPath) ? "_root" : existingByName.GroupPath));
                        Console.WriteLine("    Action: skip existing test block.");
                        continue;
                    }

                    int desiredNumber = options.Number > 0 ? options.Number : FindFreeNumberInBlockSpace(snapshot, "FB", VisualTestFbStartNumber(language));
                    BlockRecord numberConflict = FindBlockNumberConflict(snapshot, "FB", desiredNumber, null);
                    if (numberConflict != null)
                    {
                        throw new InvalidOperationException("FB number " + desiredNumber + " is already used by '" + numberConflict.Name + "'.");
                    }

                    Console.WriteLine("  - " + fbName + " [" + language + "]");
                    Console.WriteLine("    Number: FB" + desiredNumber);
                    Console.WriteLine("    SDK: PlcBlockComposition.CreateFB(name, autoNumber=false, number, " + language + ")");

                    if (!options.Apply)
                    {
                        continue;
                    }

                    if (targetGroup == null)
                    {
                        targetGroup = EnsureBlockGroup(blockGroup, groupPath);
                        targetGroupCreatedInThisRun = true;
                    }

                    object blocks = GetPropertyValue(targetGroup, "Blocks");
                    object created = CreateFbBlockWithLanguage(blocks, fbName, false, desiredNumber, language);
                    Console.WriteLine("    Created block: " + SafeName(created));
                    TryCompileAndPrint(created);
                    createdCount++;
                    snapshot = CollectInventory(project, options.ProjectPath);
                }
            }
            catch (Exception ex)
            {
                if (targetGroupCreatedInThisRun && createdCount == 0 && BlockGroupIsEmpty(targetGroup))
                {
                    TryDeleteEngineeringObject(targetGroup);
                    Console.WriteLine("    Empty target group was removed after failed visual FB creation.");
                }

                throw new InvalidOperationException("TIA refused direct visual FB creation through PlcBlockComposition.CreateFB. For LAD/FBD/GRAPH in this project, seed blocks may need to be created manually in TIA Portal or imported from a real TIA-generated source/document format. Original error: " + UnwrapExceptionMessage(ex), ex);
            }

            if (!options.Apply)
            {
                Console.WriteLine();
                Console.WriteLine("Dry-run only. Re-run with --apply to create the visual FB block(s).");
                return;
            }

            Console.WriteLine("Created visual FB blocks: " + createdCount);
            if (options.Save)
            {
                SaveProject(project);
                Console.WriteLine("Project saved.");
            }
            else
            {
                Console.WriteLine("Project was not saved. Use --save to persist the create.");
            }
        }

        private static List<string> ParseVisualTestLanguages(string language)
        {
            string normalized = string.IsNullOrWhiteSpace(language) ? "ALL" : language.Trim();
            if (EqualsIgnoreCase(normalized, "ALL"))
            {
                return new List<string> { "LAD", "FBD", "GRAPH" };
            }

            string[] parts = normalized.Split(new[] { ',', ';', '+', ' ' }, StringSplitOptions.RemoveEmptyEntries);
            List<string> result = new List<string>();
            foreach (string part in parts)
            {
                string item = part.Trim().ToUpperInvariant();
                if (!(item == "LAD" || item == "FBD" || item == "GRAPH"))
                {
                    throw new ArgumentException("Unsupported visual test language: " + part + ". Use LAD, FBD, GRAPH, or ALL.");
                }

                if (!result.Any(x => EqualsIgnoreCase(x, item)))
                {
                    result.Add(item);
                }
            }

            return result.Count == 0 ? new List<string> { "LAD", "FBD", "GRAPH" } : result;
        }

        private static string VisualTestFbName(string explicitName, string language, int languageCount)
        {
            if (string.IsNullOrWhiteSpace(explicitName))
            {
                return "FB_Openness_" + language + "_Test";
            }

            return languageCount == 1 ? explicitName : explicitName + "_" + language;
        }

        private static int VisualTestFbStartNumber(string language)
        {
            if (EqualsIgnoreCase(language, "LAD"))
            {
                return 9101;
            }

            if (EqualsIgnoreCase(language, "FBD"))
            {
                return 9102;
            }

            return 9103;
        }

        private static object CreateFbBlockWithLanguage(object blocks, string name, bool autoNumber, int number, string language)
        {
            MethodInfo createFb = blocks.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .Where(x => x.Name == "CreateFB")
                .FirstOrDefault(x =>
                {
                    ParameterInfo[] parameters = x.GetParameters();
                    return parameters.Length == 4
                        && parameters[0].ParameterType == typeof(string)
                        && parameters[1].ParameterType == typeof(bool)
                        && parameters[2].ParameterType == typeof(int)
                        && parameters[3].ParameterType.IsEnum;
                });

            if (createFb == null)
            {
                throw new MissingMethodException(blocks.GetType().FullName, "CreateFB(string,bool,int,ProgrammingLanguage)");
            }

            object programmingLanguage = ChooseEnumValue(createFb.GetParameters()[3].ParameterType, new[] { language });
            return createFb.Invoke(blocks, new object[] { name, autoNumber, number, programmingLanguage });
        }

        private static bool BlockGroupIsEmpty(object group)
        {
            if (group == null)
            {
                return false;
            }

            object blocks = TryGetPropertyValue(group, "Blocks");
            object groups = TryGetPropertyValue(group, "Groups");
            return !AsEnumerable(blocks).Any() && !AsEnumerable(groups).Any();
        }

        private static string UnwrapExceptionMessage(Exception ex)
        {
            while (ex is TargetInvocationException && ex.InnerException != null)
            {
                ex = ex.InnerException;
            }

            return ex == null ? string.Empty : ex.Message;
        }

        private static object TryCompileAndPrint(object target)
        {
            object compiler = TryGetCompiler(target);
            if (compiler == null)
            {
                Console.WriteLine("Compile service was not available for this object.");
                return null;
            }

            Console.WriteLine("Compiling...");
            MethodInfo compile = compiler.GetType().GetMethod("Compile", BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
            if (compile == null)
            {
                Console.WriteLine("Compile method was not available.");
                return null;
            }

            object result = compile.Invoke(compiler, null);
            PrintCompilerResult(result);
            return result;
        }

        private static object TryGetCompiler(object target)
        {
            Type compilableType = TryFindType("Siemens.Engineering.Compiler.ICompilable");
            object compiler = TryGetService(target, compilableType);
            if (compiler != null)
            {
                return compiler;
            }

            Type compileProviderType = TryFindType("Siemens.Engineering.Compiler.CompileProvider");
            compiler = TryGetService(target, compileProviderType);
            if (compiler != null)
            {
                return compiler;
            }

            MethodInfo compile = target.GetType().GetMethod("Compile", BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
            return compile == null ? null : target;
        }

        private static void PrintCompilerResult(object result)
        {
            if (result == null)
            {
                Console.WriteLine("Compile returned no result.");
                return;
            }

            Console.WriteLine("Compile result:");
            Console.WriteLine("  State: " + SafeGet(result, "State"));
            Console.WriteLine("  Errors: " + SafeGet(result, "ErrorCount"));
            Console.WriteLine("  Warnings: " + SafeGet(result, "WarningCount"));

            object messages = TryGetPropertyValue(result, "Messages");
            int printed = 0;
            Console.WriteLine("Compiler messages:");
            if (!PrintCompilerMessages(messages, "  ", ref printed, 200))
            {
                Console.WriteLine("  <none>");
            }
        }

        private static bool PrintCompilerMessages(object messages, string indent, ref int printed, int maxItems)
        {
            bool any = false;
            foreach (object message in AsEnumerable(messages))
            {
                if (printed >= maxItems)
                {
                    Console.WriteLine(indent + "...");
                    return any;
                }

                any = true;
                PrintCompilerMessage(message, indent);
                printed++;

                object nested = TryGetPropertyValue(message, "Messages");
                if (nested != null)
                {
                    bool nestedAny = PrintCompilerMessages(nested, indent + "  ", ref printed, maxItems);
                    any = any || nestedAny;
                }
            }

            return any;
        }

        private static void PrintCompilerMessage(object message, string indent)
        {
            string state = SafeGet(message, "State");
            string description = SafeGet(message, "Description");
            string path = SafeGet(message, "Path");
            string errors = SafeGet(message, "ErrorCount");
            string warnings = SafeGet(message, "WarningCount");
            string timestamp = SafeGet(message, "DateTime");

            List<string> parts = new List<string>();
            if (!string.IsNullOrWhiteSpace(state))
            {
                parts.Add("State=" + state);
            }

            if (!string.IsNullOrWhiteSpace(errors) && errors != "0")
            {
                parts.Add("Errors=" + errors);
            }

            if (!string.IsNullOrWhiteSpace(warnings) && warnings != "0")
            {
                parts.Add("Warnings=" + warnings);
            }

            if (!string.IsNullOrWhiteSpace(path))
            {
                parts.Add("Path=" + path);
            }

            if (!string.IsNullOrWhiteSpace(timestamp))
            {
                parts.Add("DateTime=" + timestamp);
            }

            string header = parts.Count == 0 ? "Message" : string.Join("; ", parts.ToArray());
            Console.WriteLine(indent + header);
            if (!string.IsNullOrWhiteSpace(description))
            {
                Console.WriteLine(indent + "  Description: " + description);
            }
        }

        private static int CompilerResultCount(object result, string propertyName)
        {
            return SafeInt(SafeGet(result, propertyName));
        }

        private static int RequiredCompilerResultCount(object result, string propertyName, string targetPath)
        {
            string value = SafeGet(result, propertyName);
            int count;
            if (!int.TryParse(value, NumberStyles.None, CultureInfo.InvariantCulture, out count) || count < 0)
            {
                throw new InvalidDataException("CompilerResult for '" + targetPath + "' has no valid " + propertyName + ".");
            }
            return count;
        }

        private static object GetFirstPlcSoftware(InventorySnapshot snapshot)
        {
            DeviceRecord record = GetPlcSoftwareRecords(snapshot).FirstOrDefault();
            return record == null ? null : record.Object;
        }

        private static List<DeviceRecord> GetPlcSoftwareRecords(InventorySnapshot snapshot)
        {
            return snapshot == null
                ? new List<DeviceRecord>()
                : snapshot.Devices
                    .Where(x => x != null
                        && EqualsIgnoreCase(x.Kind, "Software")
                        && (x.SoftwareType ?? string.Empty).IndexOf("PlcSoftware", StringComparison.OrdinalIgnoreCase) >= 0)
                    .GroupBy(x => EmptyIfNull(x.Path), StringComparer.OrdinalIgnoreCase)
                    .Select(x => x.First())
                    .OrderBy(x => EmptyIfNull(x.Path), StringComparer.OrdinalIgnoreCase)
                    .ToList();
        }

        private static DeviceRecord RequireSinglePlcSoftware(InventorySnapshot snapshot, string operation)
        {
            List<DeviceRecord> records = GetPlcSoftwareRecords(snapshot);
            if (records.Count != 1)
            {
                throw new InvalidOperationException(
                    operation + " requires exactly one selected PlcSoftware; found "
                    + records.Count.ToString(CultureInfo.InvariantCulture)
                    + ". In a multi-PLC project, rerun the read-only clone command with --software-path. apply-clone remains fail-closed while more than one PlcSoftware is present in the open project.");
            }

            if (records[0].Object == null)
            {
                throw new InvalidOperationException(operation + " selected PlcSoftware has no live TIA object.");
            }

            return records[0];
        }

        private static CloneCheckTargetIdentity CloneCheckTargetFromSnapshot(InventorySnapshot snapshot)
        {
            if (snapshot == null)
            {
                throw new ArgumentNullException("snapshot");
            }

            List<string> softwarePaths = GetPlcSoftwareRecords(snapshot)
                .Select(x => EmptyIfNull(x.Path).Trim())
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (softwarePaths.Count == 0)
            {
                throw new InvalidOperationException("Clone-check target has no selected PlcSoftware path.");
            }

            return new CloneCheckTargetIdentity
            {
                ProjectPath = NormalizeComparablePath(snapshot.ProjectPath),
                ProjectName = EmptyIfNull(snapshot.ProjectName),
                ProjectVersion = FirstNonEmpty(snapshot.ProjectVersion, GetProjectVersionMajor(snapshot.ProjectPath).ToString(CultureInfo.InvariantCulture)),
                ProjectObjectId = EmptyIfNull(snapshot.ProjectObjectId),
                ProjectObjectIdStatus = FirstNonEmpty(snapshot.ProjectObjectIdStatus, "unavailable"),
                SoftwarePaths = softwarePaths
            };
        }

        private static string CanonicalSoftwarePaths(IEnumerable<string> softwarePaths)
        {
            return string.Join("\n", (softwarePaths ?? new string[0])
                .Select(x => EmptyIfNull(x).Trim())
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToArray());
        }

        private static DeviceRecord ValidateCloneCheckBundleTarget(CloneCheckBundleEvidence bundle, InventorySnapshot snapshot)
        {
            if (bundle == null)
            {
                throw new ArgumentNullException("bundle");
            }

            DeviceRecord liveSoftware = RequireSinglePlcSoftware(snapshot, "apply-clone");
            if (bundle.SoftwarePaths == null || bundle.SoftwarePaths.Count != 1)
            {
                throw new InvalidDataException("apply-clone requires a clone-check bundle scoped to exactly one PlcSoftware.");
            }

            if (!EqualsIgnoreCase(NormalizeComparablePath(bundle.ProjectPath), NormalizeComparablePath(snapshot.ProjectPath)))
            {
                throw new InvalidDataException("Clone-check bundle project path does not match the open TIA project.");
            }

            if (!EqualsIgnoreCase(bundle.ProjectVersion, snapshot.ProjectVersion))
            {
                throw new InvalidDataException("Clone-check bundle project version does not match the open TIA project.");
            }

            if (!string.IsNullOrWhiteSpace(bundle.ProjectName)
                && !EqualsIgnoreCase(bundle.ProjectName, snapshot.ProjectName))
            {
                throw new InvalidDataException("Clone-check bundle project name does not match the open TIA project.");
            }

            if (EqualsIgnoreCase(bundle.ProjectObjectIdStatus, "ok"))
            {
                if (!EqualsIgnoreCase(snapshot.ProjectObjectIdStatus, "ok")
                    || string.IsNullOrWhiteSpace(bundle.ProjectObjectId)
                    || !EqualsIgnoreCase(bundle.ProjectObjectId, snapshot.ProjectObjectId))
                {
                    throw new InvalidDataException("Clone-check bundle stable project identifier does not match the open TIA project.");
                }
            }

            if (!EqualsIgnoreCase(bundle.SoftwarePaths[0], liveSoftware.Path))
            {
                throw new InvalidDataException("Clone-check bundle PlcSoftware path does not match the only PlcSoftware in the open TIA project.");
            }

            return liveSoftware;
        }

        private static object FindBlockGroup(object rootGroup, string groupPath)
        {
            if (rootGroup == null)
            {
                return null;
            }

            if (string.IsNullOrWhiteSpace(groupPath))
            {
                return rootGroup;
            }

            object current = rootGroup;
            foreach (string part in GroupPathKeySegments(groupPath))
            {
                object groups = TryGetPropertyValue(current, "Groups");
                object next = null;
                foreach (object child in AsEnumerable(groups))
                {
                    if (EqualsIgnoreCase(SafeName(child), part))
                    {
                        next = child;
                        break;
                    }
                }

                if (next == null)
                {
                    return null;
                }

                current = next;
            }

            return current;
        }

        private static object EnsureBlockGroup(object rootGroup, string groupPath)
        {
            if (rootGroup == null)
            {
                throw new InvalidOperationException("Root block group was not found.");
            }

            if (string.IsNullOrWhiteSpace(groupPath))
            {
                return rootGroup;
            }

            object current = rootGroup;
            foreach (string part in GroupPathKeySegments(groupPath))
            {
                object groups = GetPropertyValue(current, "Groups");
                object next = null;
                foreach (object child in AsEnumerable(groups))
                {
                    if (EqualsIgnoreCase(SafeName(child), part))
                    {
                        next = child;
                        break;
                    }
                }

                if (next == null)
                {
                    MethodInfo create = groups.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                        .FirstOrDefault(x =>
                        {
                            if (x.Name != "Create")
                            {
                                return false;
                            }

                            ParameterInfo[] parameters = x.GetParameters();
                            return parameters.Length == 1 && parameters[0].ParameterType == typeof(string);
                        });
                    if (create == null)
                    {
                        throw new MissingMethodException(groups.GetType().FullName, "Create(string)");
                    }

                    next = create.Invoke(groups, new object[] { part });
                    Console.WriteLine("    Created target group: " + part);
                }

                current = next;
            }

            return current;
        }

        private static BlockRecord FindExistingBlockForApply(InventorySnapshot snapshot, string name, string groupPath, string number, string numberSpace)
        {
            if (snapshot == null)
            {
                return null;
            }

            if (!string.IsNullOrWhiteSpace(name))
            {
                BlockRecord byName = snapshot.Blocks.FirstOrDefault(x => EqualsIgnoreCase(x.Name, name) && EqualsIgnoreCase(EmptyIfNull(x.GroupPath), EmptyIfNull(groupPath)));
                if (byName != null)
                {
                    return byName;
                }
            }

            int blockNumber = SafeInt(number);
            if (blockNumber > 0 && !string.IsNullOrWhiteSpace(numberSpace))
            {
                return snapshot.Blocks.FirstOrDefault(x => SafeInt(x.Number) == blockNumber && EqualsIgnoreCase(BlockNumberSpace(x), numberSpace));
            }

            return null;
        }

        private static int FindFreeDbNumber(InventorySnapshot snapshot, int startAt)
        {
            return FindFreeNumberInBlockSpace(snapshot, "DB", startAt);
        }

        private static int FindFreeBlockNumber(InventorySnapshot snapshot, int startAt)
        {
            return FindFreeNumberInBlockSpace(snapshot, "FB", startAt);
        }

        private static int FindFreeNumberInBlockSpace(InventorySnapshot snapshot, string numberSpace, int startAt)
        {
            HashSet<int> used = new HashSet<int>(snapshot.Blocks
                .Where(x => EqualsIgnoreCase(BlockNumberSpace(x), numberSpace))
                .Select(x => SafeInt(x.Number))
                .Where(x => x > 0));

            for (int number = startAt; number < 65535; number++)
            {
                if (!used.Contains(number))
                {
                    return number;
                }
            }

            int max = used.Count == 0 ? 0 : used.Max();
            return max + 1;
        }

        private static BlockRecord FindBlockNumberConflict(InventorySnapshot snapshot, string numberSpace, int number, BlockRecord except)
        {
            if (snapshot == null || string.IsNullOrWhiteSpace(numberSpace) || number <= 0)
            {
                return null;
            }

            return snapshot.Blocks
                .Where(x => SafeInt(x.Number) == number)
                .Where(x => EqualsIgnoreCase(BlockNumberSpace(x), numberSpace))
                .FirstOrDefault(x => except == null || !SameBlockRecord(x, except));
        }

        private static bool SameBlockRecord(BlockRecord left, BlockRecord right)
        {
            if (left == null || right == null)
            {
                return false;
            }

            return EqualsIgnoreCase(left.Name, right.Name)
                && EqualsIgnoreCase(EmptyIfNull(left.GroupPath), EmptyIfNull(right.GroupPath))
                && EqualsIgnoreCase(BlockNumberSpace(left), BlockNumberSpace(right));
        }

        private static void SetManualBlockNumber(BlockRecord block, int number)
        {
            if (block == null || block.Object == null)
            {
                throw new ArgumentNullException("block");
            }

            object oldAutoNumber = TryReadAttribute(block.Object, "AutoNumber");
            WriteAttribute(block.Object, "AutoNumber", "false", oldAutoNumber);

            if (SafeInt(block.Number) != number)
            {
                object oldNumber = TryReadAttribute(block.Object, "Number");
                WriteAttribute(block.Object, "Number", number.ToString(), oldNumber);
            }
        }

        private static object CreateExternalSourceFromFile(object externalSources, string sourceName, string sourcePath)
        {
            MethodInfo createFromFile = externalSources.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .Where(x => x.Name == "CreateFromFile")
                .FirstOrDefault(x =>
                {
                    ParameterInfo[] parameters = x.GetParameters();
                    return parameters.Length == 2
                        && parameters[0].ParameterType == typeof(string)
                        && parameters[1].ParameterType == typeof(string);
                });

            if (createFromFile == null)
            {
                throw new MissingMethodException(externalSources.GetType().FullName, "CreateFromFile(string,string)");
            }

            ParameterInfo[] p = createFromFile.GetParameters();
            object[] args = (p[0].Name ?? string.Empty).IndexOf("path", StringComparison.OrdinalIgnoreCase) >= 0
                ? new object[] { Path.GetFullPath(sourcePath), sourceName }
                : new object[] { sourceName, Path.GetFullPath(sourcePath) };

            return createFromFile.Invoke(externalSources, args);
        }

        private static object GenerateBlocksFromExternalSource(object externalSource, object targetGroup, string groupPath)
        {
            if (!string.IsNullOrWhiteSpace(groupPath))
            {
                if (targetGroup == null)
                {
                    throw new InvalidOperationException("Target block group was not found: " + groupPath);
                }

                MethodInfo withGroup = externalSource.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                    .Where(x => x.Name == "GenerateBlocksFromSource")
                    .FirstOrDefault(x =>
                    {
                        ParameterInfo[] parameters = x.GetParameters();
                        return parameters.Length == 2
                            && parameters[0].ParameterType.IsInstanceOfType(targetGroup)
                            && parameters[1].ParameterType.IsEnum;
                    });

                if (withGroup != null)
                {
                    object option = ChooseEnumValue(withGroup.GetParameters()[1].ParameterType, new[] { "None" });
                    return withGroup.Invoke(externalSource, new object[] { targetGroup, option });
                }
            }

            MethodInfo withOption = externalSource.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .Where(x => x.Name == "GenerateBlocksFromSource")
                .FirstOrDefault(x =>
                {
                    ParameterInfo[] parameters = x.GetParameters();
                    return parameters.Length == 1 && parameters[0].ParameterType.IsEnum;
                });

            if (withOption != null)
            {
                object option = ChooseEnumValue(withOption.GetParameters()[0].ParameterType, new[] { "None" });
                return withOption.Invoke(externalSource, new object[] { option });
            }

            MethodInfo noArgs = externalSource.GetType().GetMethod("GenerateBlocksFromSource", BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
            if (noArgs == null)
            {
                throw new MissingMethodException(externalSource.GetType().FullName, "GenerateBlocksFromSource");
            }

            return noArgs.Invoke(externalSource, null);
        }

        private static object GenerateBlockFromCloneSource(object externalSources, string clonePath, object targetGroup, string groupPath, string existingNumber, string name)
        {
            string sourceName = UniqueExternalSourceName(externalSources, "_CodexApply_" + (string.IsNullOrWhiteSpace(existingNumber) ? "new" : existingNumber) + "_" + name + "_" + DateTime.Now.ToString("HHmmss"));
            object externalSource = CreateExternalSourceFromFile(externalSources, sourceName, clonePath);
            return ExecuteWithStrictExternalSourceCleanup(externalSources, externalSource, sourceName, delegate
            {
                object result = GenerateBlocksFromExternalSource(externalSource, targetGroup, groupPath);
                Console.WriteLine("    GenerateBlocksFromSource result: " + SafeDescribe(result));
                return result;
            });
        }

        private static object ExecuteWithStrictExternalSourceCleanup(
            object externalSources,
            object externalSource,
            string sourceName,
            Func<object> operation)
        {
            object result = null;
            Exception operationException = null;
            Exception cleanupException = null;
            try
            {
                result = operation();
            }
            catch (Exception ex)
            {
                operationException = ex;
            }

            try
            {
                DeleteEngineeringObject(externalSource);
                bool stillPresent = AsEnumerable(externalSources).Any(candidate =>
                    object.ReferenceEquals(candidate, externalSource)
                    || EqualsIgnoreCase(SafeName(candidate), sourceName));
                if (stillPresent)
                {
                    throw new InvalidDataException("Temporary ExternalSource is still present after Delete(): " + sourceName + ".");
                }
            }
            catch (Exception ex)
            {
                cleanupException = ex;
            }

            if (operationException != null && cleanupException != null)
            {
                throw new AggregateException(
                    "ExternalSource generation and mandatory cleanup both failed for '" + sourceName + "'.",
                    operationException,
                    cleanupException);
            }
            if (cleanupException != null)
            {
                throw new InvalidOperationException(
                    "Mandatory cleanup of temporary ExternalSource failed for '" + sourceName + "'. SaveProject is forbidden.",
                    cleanupException);
            }
            if (operationException != null)
            {
                throw new InvalidOperationException(
                    "ExternalSource generation failed for '" + sourceName + "'.",
                    operationException);
            }

            return result;
        }

        private static Dictionary<string, int> ExternalSourceIdentityCounts(object externalSources)
        {
            Dictionary<string, int> result = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (object source in AsEnumerable(externalSources))
            {
                string key = SafeName(source) + "|" + (source == null ? string.Empty : source.GetType().FullName);
                AddIdentityCount(result, key, 1);
            }
            return result;
        }

        private static string UniqueExternalSourceName(object externalSources, string preferredName)
        {
            string baseName = SafeFileName(preferredName);
            if (baseName.Length > 80)
            {
                baseName = baseName.Substring(0, 80);
            }

            HashSet<string> existing = new HashSet<string>(AsEnumerable(externalSources).Select(SafeName), StringComparer.OrdinalIgnoreCase);
            if (!existing.Contains(baseName))
            {
                return baseName;
            }

            for (int i = 1; ; i++)
            {
                string candidate = baseName + "_" + i.ToString("000");
                if (!existing.Contains(candidate))
                {
                    return candidate;
                }
            }
        }

        private static void TryDeleteEngineeringObject(object value)
        {
            if (value == null)
            {
                return;
            }

            MethodInfo delete = value.GetType().GetMethod("Delete", BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
            if (delete == null)
            {
                return;
            }

            try
            {
                delete.Invoke(value, null);
            }
            catch
            {
            }
        }

        private static void DeleteEngineeringObject(object value)
        {
            if (value == null)
            {
                throw new ArgumentNullException("value");
            }

            MethodInfo delete = value.GetType().GetMethod("Delete", BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
            if (delete == null)
            {
                throw new MissingMethodException(value.GetType().FullName, "Delete");
            }

            delete.Invoke(value, null);
        }

        private static List<object> FindTargets(InventorySnapshot snapshot, string targetKind, string name, string groupPath)
        {
            List<object> result = new List<object>();
            if (EqualsIgnoreCase(targetKind, "block"))
            {
                foreach (BlockRecord block in snapshot.Blocks)
                {
                    if (MatchesNameAndGroup(block.Name, block.GroupPath, name, groupPath))
                    {
                        result.Add(block.Object);
                    }
                }
            }
            else if (EqualsIgnoreCase(targetKind, "tag-table"))
            {
                foreach (TagTableRecord table in snapshot.TagTables)
                {
                    if (MatchesNameAndGroup(table.Name, table.GroupPath, name, groupPath))
                    {
                        result.Add(table.Object);
                    }
                }
            }
            else if (EqualsIgnoreCase(targetKind, "tag"))
            {
                foreach (TagRecord tag in snapshot.Tags)
                {
                    if (MatchesNameAndGroup(tag.Name, tag.GroupPath, name, groupPath))
                    {
                        result.Add(tag.Object);
                    }
                }
            }
            else
            {
                throw new ArgumentException("Unknown target kind: " + targetKind);
            }

            return result;
        }

        private static bool MatchesNameAndGroup(string actualName, string actualGroup, string expectedName, string expectedGroup)
        {
            if (!EqualsIgnoreCase(actualName, expectedName))
            {
                return false;
            }

            return string.IsNullOrWhiteSpace(expectedGroup)
                || EqualsIgnoreCase(NormalizeGroupPathKey(actualGroup), NormalizeGroupPathKey(expectedGroup))
                || EqualsIgnoreCase(GroupPathDisplay(actualGroup), EmptyIfNull(expectedGroup).Trim('/').Trim('\\'));
        }

        private static object TryReadAttribute(object target, string attributeName)
        {
            PropertyInfo property = target.GetType().GetProperty(attributeName, BindingFlags.Public | BindingFlags.Instance);
            if (property != null && property.CanRead)
            {
                try
                {
                    return property.GetValue(target, null);
                }
                catch
                {
                }
            }

            MethodInfo method = target.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(x => x.Name == "GetAttribute"
                    && x.GetParameters().Length == 1
                    && x.GetParameters()[0].ParameterType == typeof(string));

            if (method == null)
            {
                return null;
            }

            try
            {
                return method.Invoke(target, new object[] { attributeName });
            }
            catch
            {
                return null;
            }
        }

        private static string DetermineNumberMode(object block, string autoNumber)
        {
            if (string.IsNullOrWhiteSpace(autoNumber))
            {
                return "Unknown";
            }

            bool isAuto;
            if (bool.TryParse(autoNumber, out isAuto) && isAuto)
            {
                return "Auto";
            }

            return IsAttributeWritable(block, "AutoNumber") ? "Manual" : "Fixed";
        }

        private static string NumberModeFromAutoNumber(string autoNumber, string fallback)
        {
            if (string.IsNullOrWhiteSpace(autoNumber))
            {
                return fallback;
            }

            bool isAuto;
            if (!bool.TryParse(autoNumber, out isAuto))
            {
                return fallback;
            }

            return isAuto ? "Auto" : "Manual";
        }

        private static bool IsAttributeWritable(object target, string attributeName)
        {
            MethodInfo method = target.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(x => x.Name == "GetAttributeInfos" && x.GetParameters().Length == 0);
            if (method != null)
            {
                try
                {
                    IEnumerable infos = method.Invoke(target, null) as IEnumerable;
                    if (infos != null)
                    {
                        foreach (object info in infos)
                        {
                            if (!EqualsIgnoreCase(SafeGet(info, "Name"), attributeName))
                            {
                                continue;
                            }

                            return Convert.ToString(TryGetPropertyValue(info, "AccessMode")).IndexOf("Write", StringComparison.OrdinalIgnoreCase) >= 0;
                        }
                    }
                }
                catch
                {
                }
            }

            PropertyInfo property = target.GetType().GetProperty(attributeName, BindingFlags.Public | BindingFlags.Instance);
            return property != null && property.CanWrite;
        }

        private static object TryGetObjectIdentifierProvider(object project)
        {
            Type providerType = TryFindType("Siemens.Engineering.ObjectIdentifierProvider");
            return providerType == null ? null : TryGetService(project, providerType);
        }

        private static void TryReadTiaObjectId(object provider, object engineeringObject, out string identifier, out string status)
        {
            identifier = string.Empty;
            status = provider == null ? "unavailable" : "empty";
            if (provider == null || engineeringObject == null)
            {
                return;
            }

            MethodInfo method = provider.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(x => x.Name == "GetIdentifier" && x.GetParameters().Length == 1);
            if (method == null)
            {
                status = "unsupported";
                return;
            }

            try
            {
                object value = method.Invoke(provider, new[] { engineeringObject });
                identifier = Convert.ToString(value);
                status = string.IsNullOrWhiteSpace(identifier) ? "empty" : "ok";
            }
            catch (Exception ex)
            {
                status = "error:" + ex.GetType().Name;
            }
        }

        private static void WriteAttribute(object target, string attributeName, string value, object oldValue)
        {
            PropertyInfo property = target.GetType().GetProperty(attributeName, BindingFlags.Public | BindingFlags.Instance);
            if (property != null && property.CanWrite)
            {
                object typedValue = ConvertStringValue(value, property.PropertyType, oldValue);
                property.SetValue(target, typedValue, null);
                return;
            }

            MethodInfo method = target.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(x => x.Name == "SetAttribute"
                    && x.GetParameters().Length == 2
                    && x.GetParameters()[0].ParameterType == typeof(string));

            if (method == null)
            {
                throw new MissingMethodException(target.GetType().FullName, "SetAttribute");
            }

            object typedAttributeValue = ConvertStringValue(value, oldValue == null ? typeof(string) : oldValue.GetType(), oldValue);
            method.Invoke(target, new object[] { attributeName, typedAttributeValue });
        }

        private static object ConvertStringValue(string value, Type targetType, object oldValue)
        {
            if (targetType == typeof(string) || targetType == typeof(object))
            {
                return value;
            }

            if (targetType == typeof(int))
            {
                return int.Parse(value);
            }

            if (targetType == typeof(uint))
            {
                return uint.Parse(value);
            }

            if (targetType == typeof(bool))
            {
                return bool.Parse(value);
            }

            if (targetType.IsEnum)
            {
                return Enum.Parse(targetType, value);
            }

            return Convert.ChangeType(value, targetType);
        }

        private static void SaveProject(object project)
        {
            MethodInfo save = project.GetType().GetMethod("Save", BindingFlags.Public | BindingFlags.Instance, null, Type.EmptyTypes, null);
            if (save == null)
