        }

        private static object TryGetSoftware(object deviceItem)
        {
            Type softwareContainerType = TryFindType("Siemens.Engineering.HW.Features.SoftwareContainer");
            if (softwareContainerType == null)
            {
                return null;
            }

            object container = TryGetService(deviceItem, softwareContainerType);
            return container == null ? null : TryGetPropertyValue(container, "Software");
        }

        private static object TryGetService(object target, Type serviceType)
        {
            if (target == null || serviceType == null)
            {
                return null;
            }

            foreach (MethodInfo method in target.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance))
            {
                if (method.Name != "GetService")
                {
                    continue;
                }

                try
                {
                    if (method.IsGenericMethodDefinition && method.GetParameters().Length == 0)
                    {
                        return method.MakeGenericMethod(serviceType).Invoke(target, null);
                    }

                    ParameterInfo[] parameters = method.GetParameters();
                    if (!method.IsGenericMethodDefinition && parameters.Length == 1 && parameters[0].ParameterType == typeof(Type))
                    {
                        return method.Invoke(target, new object[] { serviceType });
                    }
                }
                catch
                {
                    return null;
                }
            }

            return null;
        }

        private static IEnumerable<object> AsEnumerable(object value)
        {
            IEnumerable enumerable = value as IEnumerable;
            if (enumerable == null)
            {
                yield break;
            }

            foreach (object item in enumerable)
            {
                yield return item;
            }
        }

        private static void WriteCsv(string path, string[] headers, IEnumerable<string[]> rows)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine(string.Join(",", headers.Select(CsvEscape).ToArray()));
                foreach (string[] row in rows)
                {
                    writer.WriteLine(string.Join(",", row.Select(CsvEscape).ToArray()));
                }
            }
        }

        private static string CsvEscape(string value)
        {
            value = value ?? string.Empty;
            if (value.IndexOfAny(new[] { ',', '"', '\r', '\n' }) < 0)
            {
                return value;
            }

            return "\"" + value.Replace("\"", "\"\"") + "\"";
        }

