                "SoftwarePath", "GroupPath", "GroupPathDisplay", "GroupPathKey", "Name", "Number", "AutoNumber", "NumberMode", "NumberSpace",
                "ProgrammingLanguage", "BlockType", "TypeName", "SourceTypeName",
                "InstanceOfName", "InstanceOfNumber", "InstanceOfType", "SecondaryType",
                "MemoryLayout", "IsConsistent", "IsKnowHowProtected", "TiaObjectId", "TiaObjectIdStatus",
                "FilePath", "SourceSha256", "NormalizedSourceSha256", "Status", "Message", "SourceOrigin"
            };
        }

        private static string[] BuildBlockManifestRow(BlockRecord block, string filePath, string status, string message)
        {
            string sourceTypeName = File.Exists(filePath)
                ? InferBlockTypeNameFromSourceFile(filePath, block.ProgrammingLanguage)
                : EmptyIfNull(block.SourceTypeName);
            return new[]
            {
                block.SoftwarePath,
                block.GroupPath,
                block.GroupPathDisplay,
                block.GroupPath,
                block.Name,
                block.Number,
                block.AutoNumber,
                block.NumberMode,
                FirstNonEmpty(block.NumberSpace, BlockNumberSpace(block.TypeName, block.ProgrammingLanguage)),
                block.ProgrammingLanguage,
                block.BlockType,
                block.TypeName,
                sourceTypeName,
                block.InstanceOfName,
                block.InstanceOfNumber,
                block.InstanceOfType,
                block.SecondaryType,
                block.MemoryLayout,
                block.IsConsistent,
                block.IsKnowHowProtected,
                block.TiaObjectId,
                block.TiaObjectIdStatus,
                filePath,
                File.Exists(filePath) ? ComputeFileSha256(filePath) : string.Empty,
                File.Exists(filePath) ? ComputeNormalizedTextSha256(filePath) : string.Empty,
                status,
                message,
                File.Exists(filePath)
                    ? "exported-source"
                    : (EqualsIgnoreCase(status, "unsupported-language") ? "inventory-only-unsupported" : "unknown")
            };
        }

        private static string[] BuildSyncedBlockManifestRow(Dictionary<string, string> row, string softwarePath, string destinationPath, string contentPath)
        {
            string language = GetCsvValue(row, "ProgrammingLanguage");
            string typeName = GetCsvValue(row, "TypeName");
            string sourceTypeName = FirstNonEmpty(GetCsvValue(row, "SourceTypeName"), File.Exists(contentPath) ? InferBlockTypeNameFromSourceFile(contentPath, language) : string.Empty);
            return new[]
            {
                softwarePath,
                RowGroupPathKey(row, "GroupPath"),
                RowGroupPathDisplay(row, "GroupPath"),
                RowGroupPathKey(row, "GroupPath"),
                GetCsvValue(row, "Name"),
                GetCsvValue(row, "Number"),
                GetCsvValue(row, "AutoNumber"),
                GetCsvValue(row, "NumberMode"),
                FirstNonEmpty(GetCsvValue(row, "NumberSpace"), BlockNumberSpace(typeName, language)),
                language,
                GetCsvValue(row, "BlockType"),
                typeName,
                sourceTypeName,
                GetCsvValue(row, "InstanceOfName"),
                GetCsvValue(row, "InstanceOfNumber"),
                GetCsvValue(row, "InstanceOfType"),
                GetCsvValue(row, "SecondaryType"),
                GetCsvValue(row, "MemoryLayout"),
                GetCsvValue(row, "IsConsistent"),
                GetCsvValue(row, "IsKnowHowProtected"),
                GetCsvValue(row, "TiaObjectId"),
                GetCsvValue(row, "TiaObjectIdStatus"),
                destinationPath,
                File.Exists(contentPath) ? ComputeFileSha256(contentPath) : string.Empty,
                File.Exists(contentPath) ? ComputeNormalizedTextSha256(contentPath) : string.Empty,
                "ok",
                "Synced from latest clone check.",
                "exported-source"
            };
        }

        private static string ComputeFileSha256(string path)
        {
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            {
                return string.Empty;
            }

            using (SHA256 sha = SHA256.Create())
            using (FileStream stream = File.OpenRead(path))
            {
                return ToHex(sha.ComputeHash(stream));
            }
        }

        private static string ComputeNormalizedTextSha256(string path)
        {
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            {
                return string.Empty;
            }

            string text = File.ReadAllText(path, Encoding.UTF8)
                .Replace("\r\n", "\n")
                .Replace("\r", "\n");
            using (SHA256 sha = SHA256.Create())
            {
                return ToHex(sha.ComputeHash(Encoding.UTF8.GetBytes(text)));
            }
        }

        private static string ToHex(byte[] bytes)
        {
            StringBuilder builder = new StringBuilder(bytes.Length * 2);
            foreach (byte value in bytes)
            {
                builder.Append(value.ToString("x2"));
            }

            return builder.ToString();
        }

        private static void WriteInventoryJson(InventorySnapshot snapshot, string path)
        {
            using (StreamWriter writer = NewUtf8Writer(path))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"project\": {");
                writer.WriteLine("    \"name\": " + Json(snapshot.ProjectName) + ",");
                writer.WriteLine("    \"path\": " + Json(snapshot.ProjectPath) + ",");
                writer.WriteLine("    \"type\": " + Json(snapshot.ProjectType) + ",");
                writer.WriteLine("    \"createdAt\": " + Json(snapshot.CreatedAt.ToString("o")));
                writer.WriteLine("  },");
                WriteJsonArray(writer, "devices", snapshot.Devices.Select(x => new Dictionary<string, string>
                {
                    { "kind", x.Kind },
                    { "path", x.Path },
                    { "name", x.Name },
                    { "typeIdentifier", x.TypeIdentifier },
                    { "orderNumber", x.OrderNumber },
                    { "softwareType", x.SoftwareType }
                }), true);
                WriteJsonArray(writer, "blockGroups", snapshot.BlockGroups.Select(x => new Dictionary<string, string>
                {
                    { "softwarePath", x.SoftwarePath },
                    { "parentGroupPath", x.ParentGroupPath },
                    { "parentGroupPathDisplay", x.ParentGroupPathDisplay },
                    { "groupPath", x.GroupPath },
                    { "groupPathDisplay", x.GroupPathDisplay },
                    { "groupPathKey", x.GroupPath },
                    { "groupSegmentsJson", GroupSegmentsDisplayJson(x.GroupPath) },
                    { "name", x.Name },
                    { "typeName", x.TypeName }
                }), true);
                WriteJsonArray(writer, "blocks", snapshot.Blocks.Select(x => new Dictionary<string, string>
                {
                    { "softwarePath", x.SoftwarePath },
                    { "groupPath", x.GroupPath },
                    { "groupPathDisplay", x.GroupPathDisplay },
                    { "groupPathKey", x.GroupPath },
                    { "groupSegmentsJson", GroupSegmentsDisplayJson(x.GroupPath) },
                    { "name", x.Name },
                    { "number", x.Number },
                    { "autoNumber", x.AutoNumber },
                    { "numberMode", x.NumberMode },
                    { "numberSpace", x.NumberSpace },
                    { "programmingLanguage", x.ProgrammingLanguage },
                    { "blockType", x.BlockType },
                    { "typeName", x.TypeName },
                    { "sourceTypeName", x.SourceTypeName },
                    { "instanceOfName", x.InstanceOfName },
                    { "instanceOfNumber", x.InstanceOfNumber },
                    { "instanceOfType", x.InstanceOfType },
                    { "secondaryType", x.SecondaryType },
                    { "memoryLayout", x.MemoryLayout },
                    { "isConsistent", x.IsConsistent },
                    { "isKnowHowProtected", x.IsKnowHowProtected },
                    { "tiaObjectId", x.TiaObjectId },
                    { "tiaObjectIdStatus", x.TiaObjectIdStatus }
                }), true);
                WriteJsonArray(writer, "tagTables", snapshot.TagTables.Select(x => new Dictionary<string, string>
                {
                    { "softwarePath", x.SoftwarePath },
                    { "groupPath", x.GroupPath },
                    { "name", x.Name },
                    { "typeName", x.TypeName }
                }), true);
                WriteJsonArray(writer, "tags", snapshot.Tags.Select(x => new Dictionary<string, string>
                {
                    { "softwarePath", x.SoftwarePath },
                    { "groupPath", x.GroupPath },
                    { "tableName", x.TableName },
                    { "name", x.Name },
                    { "dataTypeName", x.DataTypeName },
                    { "logicalAddress", x.LogicalAddress },
                    { "typeName", x.TypeName }
                }), false);
                writer.WriteLine("}");
            }
        }

        private static void WriteJsonArray(StreamWriter writer, string name, IEnumerable<Dictionary<string, string>> rows, bool trailingComma)
        {
            writer.WriteLine("  \"" + name + "\": [");
            List<Dictionary<string, string>> list = rows.ToList();
            for (int i = 0; i < list.Count; i++)
            {
                Dictionary<string, string> row = list[i];
                writer.WriteLine("    {");
                int j = 0;
                foreach (KeyValuePair<string, string> pair in row)
                {
                    string comma = j == row.Count - 1 ? string.Empty : ",";
                    writer.WriteLine("      " + Json(pair.Key) + ": " + Json(pair.Value) + comma);
                    j++;
                }

                writer.WriteLine("    }" + (i == list.Count - 1 ? string.Empty : ","));
            }

            writer.WriteLine("  ]" + (trailingComma ? "," : string.Empty));
        }

        private static string Json(string value)
        {
            if (value == null)
            {
                return "null";
            }

            StringBuilder builder = new StringBuilder();
            builder.Append('"');
            foreach (char c in value)
            {
                switch (c)
                {
                    case '\\':
                        builder.Append("\\\\");
                        break;
                    case '"':
                        builder.Append("\\\"");
                        break;
                    case '\r':
                        builder.Append("\\r");
                        break;
                    case '\n':
                        builder.Append("\\n");
                        break;
                    case '\t':
                        builder.Append("\\t");
                        break;
                    default:
                        if (c < 32)
                        {
                            builder.Append("\\u");
                            builder.Append(((int)c).ToString("x4"));
                        }
                        else
                        {
                            builder.Append(c);
                        }
                        break;
                }
            }

            builder.Append('"');
            return builder.ToString();
        }

        private static StreamWriter NewUtf8Writer(string path)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(path));
            return new StreamWriter(path, false, new UTF8Encoding(false));
        }

        private static string ResolveOutputDirectory(string explicitOutDir, string command)
        {
            if (!string.IsNullOrWhiteSpace(explicitOutDir))
            {
                return Path.GetFullPath(explicitOutDir);
            }

            string stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
            return Path.Combine(ResolveToolDirectoryForCleanLocal(), "out", command + "-" + stamp);
        }

        private static string ResolveRequiredInputDirectory(string explicitInDir)
        {
            if (string.IsNullOrWhiteSpace(explicitInDir))
            {
                throw new ArgumentException("--in <path> is required for this command.");
            }

            string path = Path.GetFullPath(explicitInDir);
            if (!Directory.Exists(path))
            {
                throw new DirectoryNotFoundException("Input directory was not found: " + path);
            }

            return path;
        }

        private static void PrepareHmiImportProbeCopyOptions(Options options)
        {
            if (options.Attach)
            {
                throw new InvalidOperationException(options.Command + " must not use --attach. It creates and opens a separate copied project.");
            }

            ResolveRequiredInputDirectory(options.InDir);

            string sourceProjectPath = Path.GetFullPath(options.ProjectPath);
            string copyDir = CreateHmiImportProbeProjectCopy(sourceProjectPath);
            string copiedProjectPath = Path.Combine(copyDir, Path.GetFileName(sourceProjectPath));
            if (!File.Exists(copiedProjectPath))
            {
                throw new FileNotFoundException("Copied project file was not found after probe copy was created.", copiedProjectPath);
            }

            options.OriginalProjectPath = sourceProjectPath;
            options.ImportProbeProjectCopyDir = copyDir;
            options.ProjectPath = copiedProjectPath;
            options.Attach = false;
            options.NoBackup = true;

            Console.WriteLine("HMI copied-project probe project copy created:");
            Console.WriteLine("  Source project: " + sourceProjectPath);
            Console.WriteLine("  Copied project: " + copiedProjectPath);
            Console.WriteLine();
        }

        private static string CreateHmiImportProbeProjectCopy(string projectPath)
        {
            string sourceDir = Path.GetDirectoryName(projectPath);
            string driveRoot = Path.GetPathRoot(Path.GetFullPath(sourceDir));
            string probeRoot = Path.Combine(driveRoot, "TIA_HMI_IMPORT_PROBE");
            string stamp = DateTime.Now.ToString("yyyyMMddHHmmss");
            for (int i = 0; i < 1000; i++)
            {
                string suffix = i == 0 ? string.Empty : "_" + i.ToString("000");
                string destDir = Path.Combine(probeRoot, "p" + stamp + suffix);
                if (Directory.Exists(destDir))
                {
                    continue;
                }

                CopyTiaProjectDirectoryForProbe(sourceDir, destDir, true);
                return destDir;
            }

            throw new IOException("Could not create a unique HMI import probe project copy directory under: " + probeRoot);
        }

        private static void CopyTiaProjectDirectoryForProbe(string sourceDir, string destDir, bool topLevel)
        {
            CopyTiaProjectDirectoryForProbe(sourceDir, destDir, topLevel, null);
        }

        private static void CopyTiaProjectDirectoryForProbe(string sourceDir, string destDir, bool topLevel, string excludedDirectory)
        {
            EnsureExistingPathChainHasNoReparsePoints(sourceDir, "TIA project copy source");
            EnsureExistingPathChainHasNoReparsePoints(destDir, "TIA project copy destination");
            DirectoryInfo source = new DirectoryInfo(sourceDir);
            if (!source.Exists)
            {
                throw new DirectoryNotFoundException(sourceDir);
            }

            if (Directory.Exists(destDir))
            {
                throw new IOException("Destination already exists: " + destDir);
            }

            Directory.CreateDirectory(destDir);

            foreach (FileInfo file in source.GetFiles())
            {
                if ((file.Attributes & FileAttributes.ReparsePoint) != 0)
                {
                    throw new InvalidOperationException("Refusing to copy a reparse point/symlink: " + file.FullName);
                }
                file.CopyTo(Path.Combine(destDir, file.Name), false);
            }

            foreach (DirectoryInfo directory in source.GetDirectories())
            {
                if ((directory.Attributes & FileAttributes.ReparsePoint) != 0)
                {
                    throw new InvalidOperationException("Refusing to copy a reparse point/symlink: " + directory.FullName);
                }
                if (ShouldSkipHmiImportProbeCopyDirectory(directory.Name, topLevel))
                {
                    continue;
                }

                if (!string.IsNullOrWhiteSpace(excludedDirectory) && SameDirectory(directory.FullName, excludedDirectory))
                {
                    continue;
                }

                CopyTiaProjectDirectoryForProbe(directory.FullName, Path.Combine(destDir, directory.Name), false, excludedDirectory);
            }
        }

        private static bool ShouldSkipHmiImportProbeCopyDirectory(string name, bool topLevel)
        {
            if (EqualsIgnoreCase(name, ".git") || EqualsIgnoreCase(name, "out"))
            {
                return true;
            }

            if (!topLevel)
            {
                return false;
            }

            return EqualsIgnoreCase(name, "CLONE_PROJECT")
                || IsToolDirectoryName(name)
                || EqualsIgnoreCase(name, "TIA_PROJECT_BACKUPS")
                || EqualsIgnoreCase(name, "HMI_IMPORT_PROBE_PROJECTS");
        }

        private static string ResolveRequiredPatchFile(string explicitPatchPath)
        {
            if (string.IsNullOrWhiteSpace(explicitPatchPath))
            {
                throw new ArgumentException("--patch <path> is required for this command.");
            }

            string path = Path.GetFullPath(explicitPatchPath);
            if (!File.Exists(path))
            {
                throw new FileNotFoundException("Patch file was not found: " + path, path);
            }

            return path;
        }

        private static string ResolveCloneProjectDirectory(string explicitOutDir)
        {
            string outDir = string.IsNullOrWhiteSpace(explicitOutDir)
                ? Path.Combine(Environment.CurrentDirectory, "CLONE_PROJECT")
                : Path.GetFullPath(explicitOutDir);
            ValidateCloneWorkspacePhysicalIsolation(outDir);
            return outDir;
        }

        private static string CloneDirectoryForBlockGroup(string rootDir, string groupPath)
        {
            if (string.IsNullOrWhiteSpace(groupPath))
            {
                return rootDir;
            }

            return Path.Combine(rootDir, SafeFilePath(groupPath));
        }

        private static string BlockSourceRelativePath(BlockRecord block)
        {
            string fileName = SafeFileName(BlockSourceFileName(block, DefaultSourceExtension(block.ProgrammingLanguage)));
            string groupPath = EmptyIfNull(block.GroupPath);
            return string.IsNullOrWhiteSpace(groupPath)
                ? fileName
                : Path.Combine(SafeFilePath(groupPath), fileName);
        }

        private static List<CloneBlockRecord> LoadCloneBlockManifest(string outDir, string rootDir)
        {
            ValidateCloneWorkspacePhysicalIsolation(outDir);
            EnsurePathInside(rootDir, outDir);
            string manifestPath = Path.Combine(outDir, "plc-blocks.csv");
            List<CloneBlockRecord> records = new List<CloneBlockRecord>();
            if (File.Exists(manifestPath))
            {
                foreach (Dictionary<string, string> row in ReadCsv(manifestPath))
                {
                    string groupPath = RowGroupPathKey(row, "GroupPath");
                    string filePath = GetCsvValue(row, "FilePath");
                    string fileName = Path.GetFileName(filePath);
                    string language = GetCsvValue(row, "ProgrammingLanguage");
                    string blockType = GetCsvValue(row, "BlockType");
                    string typeName = GetCsvValue(row, "TypeName");
                    string sourceTypeName = GetCsvValue(row, "SourceTypeName");
                    string instanceOfName = GetCsvValue(row, "InstanceOfName");
                    string autoNumber = GetCsvValue(row, "AutoNumber");
                    string numberMode = GetCsvValue(row, "NumberMode");
                    string numberSpace = GetCsvValue(row, "NumberSpace");
                    if (string.IsNullOrWhiteSpace(fileName))
                    {
                        string extension = DefaultSourceExtension(language);
                        fileName = SafeFileName(GetCsvValue(row, "Number") + "_" + GetCsvValue(row, "Name") + extension);
                    }

                    string relativePath = string.IsNullOrWhiteSpace(groupPath)
                        ? fileName
                        : Path.Combine(SafeFilePath(groupPath), SafeFileName(fileName));
                    string clonePath = Path.Combine(rootDir, relativePath);
                    bool cloneFileExists = File.Exists(clonePath);
                    string manifestStatus = GetCsvValue(row, "Status");
                    string manifestSourceOrigin = GetCsvValue(row, "SourceOrigin");
                    bool inventoryOnlyUnsupported = !cloneFileExists
                        && EqualsIgnoreCase(manifestSourceOrigin, "inventory-only-unsupported")
                        && EqualsIgnoreCase(manifestStatus, "unsupported-language")
                        && !IsCloneSourceExportableLanguage(language);
                    if (!cloneFileExists && inventoryOnlyUnsupported)
                    {
                        // init-clone inventories pre-existing LAD/FBD/GRAPH
                        // blocks even though no source clone was ever produced.
                        // Such a row proves inventory presence, not tracked
                        // source provenance. Previously exported rows (normally
                        // Status=ok) remain represented when their file goes
                        // missing so conversion/deletion ambiguity still fails
                        // closed.
                        continue;
                    }

                    bool sourceOriginContradictory = !string.IsNullOrWhiteSpace(manifestSourceOrigin)
                        && !EqualsIgnoreCase(manifestSourceOrigin, "exported-source");
                    bool manifestProvesTrackedSource = EqualsIgnoreCase(manifestSourceOrigin, "exported-source")
                        || (string.IsNullOrWhiteSpace(manifestSourceOrigin) && cloneFileExists);

                    string sourceName = cloneFileExists ? TryReadBlockNameFromSource(clonePath) : string.Empty;
                    DbSourceInfo dbSource = cloneFileExists ? ParseDbSource(clonePath) : new DbSourceInfo();
                    if (cloneFileExists)
                    {
                        sourceTypeName = InferBlockTypeNameFromSourceFile(clonePath, language);
                    }
                    if (string.IsNullOrWhiteSpace(typeName))
                    {
                        typeName = sourceTypeName;
                    }
                    else if (dbSource.IsDataBlock)
                    {
                        typeName = dbSource.IsInstanceDb
                            ? "Siemens.Engineering.SW.Blocks.InstanceDB"
                            : "Siemens.Engineering.SW.Blocks.GlobalDB";
                    }

                    if (string.IsNullOrWhiteSpace(blockType))
                    {
                        blockType = BlockNumberSpace(typeName, language);
                    }

                    if (string.IsNullOrWhiteSpace(numberSpace))
                    {
                        numberSpace = BlockNumberSpace(typeName, language);
                    }

                    if (string.IsNullOrWhiteSpace(numberMode))
                    {
                        numberMode = NumberModeFromAutoNumber(autoNumber, "Unknown");
                    }

                    if (string.IsNullOrWhiteSpace(instanceOfName) && dbSource.IsInstanceDb)
                    {
                        instanceOfName = dbSource.InstanceOfName;
                    }

                    records.Add(new CloneBlockRecord
                    {
                        SoftwarePath = GetCsvValue(row, "SoftwarePath"),
                        GroupPath = groupPath,
                        GroupPathDisplay = RowGroupPathDisplay(row, "GroupPath"),
                        Name = string.IsNullOrWhiteSpace(sourceName) ? GetCsvValue(row, "Name") : sourceName,
                        Number = GetCsvValue(row, "Number"),
                        AutoNumber = autoNumber,
                        NumberMode = numberMode,
                        NumberSpace = numberSpace,
                        ProgrammingLanguage = language,
                        BlockType = blockType,
                        TypeName = typeName,
                        SourceTypeName = sourceTypeName,
                        InstanceOfName = instanceOfName,
                        InstanceOfNumber = GetCsvValue(row, "InstanceOfNumber"),
                        InstanceOfType = GetCsvValue(row, "InstanceOfType"),
                        SecondaryType = GetCsvValue(row, "SecondaryType"),
                        MemoryLayout = GetCsvValue(row, "MemoryLayout"),
                        IsConsistent = GetCsvValue(row, "IsConsistent"),
                        IsKnowHowProtected = GetCsvValue(row, "IsKnowHowProtected"),
                        TiaObjectId = GetCsvValue(row, "TiaObjectId"),
                        TiaObjectIdStatus = GetCsvValue(row, "TiaObjectIdStatus"),
                        SourceSha256 = ComputeFileSha256(clonePath),
                        NormalizedSourceSha256 = ComputeNormalizedTextSha256(clonePath),
                        RelativePath = relativePath,
                        ClonePath = clonePath,
                        CurrentPath = string.Empty,
                        ExportStatus = cloneFileExists ? manifestStatus : "missing-source",
                        ExportMessage = cloneFileExists ? GetCsvValue(row, "Message") : "Tracked manifest source file is missing from _root.",
                        Provenance = sourceOriginContradictory || (!cloneFileExists && !manifestProvesTrackedSource)
                            ? "unknown-orphaned"
                            : "tracked-baseline"
                    });
                }
            }

            HashSet<string> manifestRelativePaths = new HashSet<string>(records.Select(x => x.RelativePath), StringComparer.OrdinalIgnoreCase);
            foreach (string file in Directory.GetFiles(rootDir, "*", SearchOption.AllDirectories).Where(IsKnownSourceFile).OrderBy(x => x))
            {
                string relativePath = MakeRelativePath(rootDir, file);
                if (manifestRelativePaths.Contains(relativePath))
                {
                    continue;
                }

                records.Add(CreateCloneBlockRecordFromSourceFile(rootDir, file, "Loaded from clone file scan."));
            }

            ReconcileMovedTrackedCloneSources(records);
            return records;
        }

        private static void ReconcileMovedTrackedCloneSources(List<CloneBlockRecord> records)
        {
            List<CloneBlockRecord> missingTracked = (records ?? new List<CloneBlockRecord>())
                .Where(x => x != null
                    && EqualsIgnoreCase(x.Provenance, "tracked-baseline")
                    && !CloneSourceFileExists(x))
                .ToList();
            List<CloneBlockRecord> looseSources = (records ?? new List<CloneBlockRecord>())
                .Where(x => x != null
                    && EqualsIgnoreCase(x.Provenance, "unknown-orphaned")
                    && CloneSourceFileExists(x))
                .ToList();
            List<Tuple<CloneBlockRecord, CloneBlockRecord>> matches = new List<Tuple<CloneBlockRecord, CloneBlockRecord>>();

            foreach (CloneBlockRecord loose in looseSources)
            {
                List<CloneBlockRecord> candidates = missingTracked
                    .Where(tracked => MovedTrackedCloneSourceMatches(tracked, loose))
                    .ToList();
                if (candidates.Count != 1)
                {
                    continue;
                }

                CloneBlockRecord trackedMatch = candidates[0];
                if (looseSources.Count(candidate => MovedTrackedCloneSourceMatches(trackedMatch, candidate)) != 1)
                {
                    continue;
                }

                matches.Add(Tuple.Create(trackedMatch, loose));
            }

            foreach (Tuple<CloneBlockRecord, CloneBlockRecord> match in matches
                .Where(x => matches.Count(y => object.ReferenceEquals(y.Item1, x.Item1)) == 1))
            {
                CloneBlockRecord tracked = match.Item1;
                CloneBlockRecord moved = match.Item2;
                bool hasTrackedSidecar = HasValidTrackedBaselineSidecar(moved, tracked.SoftwarePath);

                moved.SoftwarePath = tracked.SoftwarePath;
                moved.Number = tracked.Number;
                if (!hasTrackedSidecar)
                {
                    moved.AutoNumber = tracked.AutoNumber;
                    moved.NumberMode = tracked.NumberMode;
                    moved.InstanceOfName = FirstNonEmpty(moved.InstanceOfName, tracked.InstanceOfName);
                }
                moved.InstanceOfNumber = FirstNonEmpty(moved.InstanceOfNumber, tracked.InstanceOfNumber);
                moved.InstanceOfType = FirstNonEmpty(moved.InstanceOfType, tracked.InstanceOfType);
                moved.SecondaryType = FirstNonEmpty(moved.SecondaryType, tracked.SecondaryType);
                moved.MemoryLayout = FirstNonEmpty(moved.MemoryLayout, tracked.MemoryLayout);
                moved.IsConsistent = FirstNonEmpty(moved.IsConsistent, tracked.IsConsistent);
                moved.IsKnowHowProtected = FirstNonEmpty(moved.IsKnowHowProtected, tracked.IsKnowHowProtected);
                moved.TiaObjectId = FirstNonEmpty(moved.TiaObjectId, tracked.TiaObjectId);
                moved.TiaObjectIdStatus = FirstNonEmpty(moved.TiaObjectIdStatus, tracked.TiaObjectIdStatus);
                moved.Provenance = "tracked-baseline";
                moved.ExportMessage = "Matched moved tracked source to its missing manifest row by unique PLC/group/type/number identity.";
                records.Remove(tracked);
            }
        }

        private static bool MovedTrackedCloneSourceMatches(CloneBlockRecord tracked, CloneBlockRecord loose)
        {
            if (tracked == null
                || loose == null
                || CloneSourceFileExists(tracked)
                || !CloneSourceFileExists(loose)
                || SafeInt(tracked.Number) <= 0
                || SafeInt(tracked.Number) != SafeInt(loose.Number)
                || !EqualsIgnoreCase(EmptyIfNull(tracked.GroupPath), EmptyIfNull(loose.GroupPath))
                || !EqualsIgnoreCase(
                    FirstNonEmpty(tracked.NumberSpace, BlockNumberSpace(tracked.TypeName, tracked.ProgrammingLanguage)),
                    FirstNonEmpty(loose.NumberSpace, BlockNumberSpace(loose.TypeName, loose.ProgrammingLanguage)))
                || (!string.IsNullOrWhiteSpace(tracked.ProgrammingLanguage)
                    && !string.IsNullOrWhiteSpace(loose.ProgrammingLanguage)
                    && !EqualsIgnoreCase(tracked.ProgrammingLanguage, loose.ProgrammingLanguage)))
            {
                return false;
            }

            string sidecarPath = loose.ClonePath + ".meta.json";
            if (!File.Exists(sidecarPath))
            {
                return string.IsNullOrWhiteSpace(loose.SoftwarePath);
            }

            return HasValidTrackedBaselineSidecar(loose, tracked.SoftwarePath);
        }

        private static bool HasValidTrackedBaselineSidecar(CloneBlockRecord source, string softwarePath)
        {
            if (source == null || string.IsNullOrWhiteSpace(source.ClonePath))
            {
                return false;
            }

            string sidecarPath = source.ClonePath + ".meta.json";
            if (!File.Exists(sidecarPath))
            {
                return false;
            }

            Dictionary<string, string> sidecar = LoadSidecarMetadata(source.ClonePath);
            return sidecar.Count > 0
                && EqualsIgnoreCase(SidecarValue(sidecar, "sourceOrigin"), "tracked-baseline")
                && !string.IsNullOrWhiteSpace(SidecarValue(sidecar, "softwarePath"))
                && EqualsIgnoreCase(SidecarValue(sidecar, "softwarePath"), softwarePath);
        }

        private static int PromoteMatchedExplicitNewSources(
            string outDir,
            string rootDir,
            List<CloneBlockRecord> cloneBlocks,
            List<CloneBlockRecord> currentBlocks,
            List<ExplicitNewPromotionReceipt> receipts)
        {
            List<CloneBlockRecord> pending = (cloneBlocks ?? new List<CloneBlockRecord>())
                .Where(x => x != null
                    && EqualsIgnoreCase(x.Provenance, "explicit-new-local-source")
                    && CloneSourceFileExists(x))
                .ToList();
            List<ExplicitNewPromotionReceipt> usableReceipts = (receipts ?? new List<ExplicitNewPromotionReceipt>())
                .Where(x => x != null)
                .ToList();
            if (pending.Count == 0 || usableReceipts.Count == 0)
            {
                return 0;
            }

            List<ExplicitNewPromotionCandidate> promotions = new List<ExplicitNewPromotionCandidate>();
            foreach (ExplicitNewPromotionReceipt receipt in usableReceipts)
            {
                ValidateExplicitNewPromotionReceipt(receipt, rootDir);
                List<CloneBlockRecord> cloneMatches = pending
                    .Where(x => ExplicitNewReceiptMatchesClone(receipt, x))
                    .ToList();
                List<CloneBlockRecord> liveMatches = (currentBlocks ?? new List<CloneBlockRecord>())
                    .Where(x => ExplicitNewReceiptMatchesLive(receipt, x))
                    .ToList();
                if (cloneMatches.Count != 1 || liveMatches.Count != 1)
                {
                    throw new InvalidDataException(
                        "Successful CreateBlock receipt does not resolve to exactly one pending source and one exportable live block: "
                        + receipt.SoftwarePath + "/" + receipt.TargetName + "; pending matches="
                        + cloneMatches.Count.ToString(CultureInfo.InvariantCulture) + "; live matches="
                        + liveMatches.Count.ToString(CultureInfo.InvariantCulture) + ".");
                }

                CloneBlockRecord clone = cloneMatches[0];
                CloneBlockRecord live = liveMatches[0];
                string cloneCanonicalHash = ComputeCanonicalSourceSha256(clone.ClonePath);
                string liveCanonicalHash = ComputeCanonicalSourceSha256(live.CurrentPath);
                if (!EqualsIgnoreCase(clone.ProgrammingLanguage, live.ProgrammingLanguage)
                    || string.IsNullOrWhiteSpace(cloneCanonicalHash)
                    || !EqualsIgnoreCase(cloneCanonicalHash, liveCanonicalHash)
                    || !EqualsIgnoreCase(receipt.SourceCanonicalSha256, liveCanonicalHash))
                {
                    throw new InvalidDataException(
                        "Successful CreateBlock receipt cannot promote a source unless exportable language and canonical source content match the live block: "
                        + receipt.SoftwarePath + "/" + receipt.TargetName + ".");
                }

                promotions.Add(new ExplicitNewPromotionCandidate { Clone = clone, Current = live, Receipt = receipt });
            }

            if (promotions.Count == 0)
            {
                return 0;
            }

            string manifestPath = Path.Combine(outDir, "plc-blocks.csv");
            string[] headers = BlockManifestHeaders();
            List<Dictionary<string, string>> existingRows = File.Exists(manifestPath)
                ? ReadCsv(manifestPath)
                : new List<Dictionary<string, string>>();
            ValidateUniquePromotionBatch(promotions);
            foreach (ExplicitNewPromotionCandidate promotion in promotions)
            {
                if (existingRows.Any(row => ManifestRowMatchesCloneRecord(row, promotion.Current)))
                {
                    throw new InvalidDataException(
                        "Explicit-new source collides with an already tracked manifest identity: "
                        + promotion.Clone.SoftwarePath + "/" + promotion.Clone.Name + ".");
                }
            }

            List<string[]> rows = existingRows
                .Select(row => headers.Select(header => GetCsvValue(row, header)).ToArray())
                .ToList();
            foreach (ExplicitNewPromotionCandidate promotion in promotions)
            {
                rows.Add(BuildBlockManifestRowFromCloneRecord(
                    promotion.Current,
                    promotion.Clone.ClonePath,
                    "Promoted from explicit-new-local-source by successful CreateBlock receipt " + promotion.Receipt.ReceiptId + "."));
            }

            CommitProvenancePromotions(outDir, rootDir, manifestPath, headers, rows, promotions);
            return promotions.Count;
        }

        private static void ValidateExplicitNewPromotionReceipt(ExplicitNewPromotionReceipt receipt, string rootDir)
        {
            if (string.IsNullOrWhiteSpace(receipt.ReceiptId)
                || string.IsNullOrWhiteSpace(receipt.CheckRunId)
                || string.IsNullOrWhiteSpace(receipt.SoftwarePath)
                || string.IsNullOrWhiteSpace(receipt.TargetName)
                || string.IsNullOrWhiteSpace(receipt.TargetNumberSpace)
                || string.IsNullOrWhiteSpace(receipt.SourcePath)
                || string.IsNullOrWhiteSpace(receipt.SourceNormalizedSha256)
                || string.IsNullOrWhiteSpace(receipt.SourceCanonicalSha256))
            {
                throw new InvalidDataException("Successful CreateBlock promotion receipt is incomplete.");
            }

            EnsurePathInside(receipt.SourcePath, rootDir);
            if (!File.Exists(receipt.SourcePath)
                || !EqualsIgnoreCase(ComputeNormalizedTextSha256(receipt.SourcePath), receipt.SourceNormalizedSha256)
                || !EqualsIgnoreCase(ComputeCanonicalSourceSha256(receipt.SourcePath), receipt.SourceCanonicalSha256))
            {
                throw new InvalidDataException("Successful CreateBlock promotion receipt source is missing or changed: " + receipt.SourcePath);
            }
        }

        private static bool ExplicitNewReceiptMatchesClone(ExplicitNewPromotionReceipt receipt, CloneBlockRecord clone)
        {
            return receipt != null
                && clone != null
                && EqualsIgnoreCase(Path.GetFullPath(receipt.SourcePath), Path.GetFullPath(clone.ClonePath))
                && EqualsIgnoreCase(receipt.SoftwarePath, clone.SoftwarePath)
                && EqualsIgnoreCase(EmptyIfNull(receipt.TargetGroupPath), EmptyIfNull(clone.GroupPath))
                && EqualsIgnoreCase(receipt.TargetName, clone.Name)
                && EqualsIgnoreCase(receipt.TargetNumberSpace, FirstNonEmpty(clone.NumberSpace, BlockNumberSpace(clone.TypeName, clone.ProgrammingLanguage)))
                && (string.IsNullOrWhiteSpace(receipt.TargetNumber)
                    || SafeInt(receipt.TargetNumber) == SafeInt(clone.Number))
                && EqualsIgnoreCase(receipt.ProgrammingLanguage, clone.ProgrammingLanguage)
                && EqualsIgnoreCase(receipt.SourceCanonicalSha256, ComputeCanonicalSourceSha256(clone.ClonePath));
        }

        private static bool ExplicitNewReceiptMatchesLive(ExplicitNewPromotionReceipt receipt, CloneBlockRecord live)
        {
            if (receipt == null || live == null || !EqualsIgnoreCase(live.ExportStatus, "ok"))
            {
                return false;
            }

            bool objectIdentityMatches = string.IsNullOrWhiteSpace(receipt.LiveTiaObjectId)
                || string.IsNullOrWhiteSpace(live.TiaObjectId)
                || EqualsIgnoreCase(receipt.LiveTiaObjectId, live.TiaObjectId);
            return objectIdentityMatches
                && EqualsIgnoreCase(receipt.SoftwarePath, live.SoftwarePath)
                && EqualsIgnoreCase(EmptyIfNull(receipt.TargetGroupPath), EmptyIfNull(live.GroupPath))
                && EqualsIgnoreCase(receipt.TargetName, live.Name)
                && EqualsIgnoreCase(receipt.TargetNumberSpace, FirstNonEmpty(live.NumberSpace, BlockNumberSpace(live.TypeName, live.ProgrammingLanguage)))
                && (string.IsNullOrWhiteSpace(receipt.TargetNumber)
                    || SafeInt(receipt.TargetNumber) == SafeInt(live.Number))
                && EqualsIgnoreCase(receipt.ProgrammingLanguage, live.ProgrammingLanguage)
                && EqualsIgnoreCase(receipt.SourceCanonicalSha256, ComputeCanonicalSourceSha256(live.CurrentPath));
        }

        private static void ValidateUniquePromotionBatch(List<ExplicitNewPromotionCandidate> promotions)
        {
            List<ExplicitNewPromotionCandidate> batch = promotions ?? new List<ExplicitNewPromotionCandidate>();
            if (batch.GroupBy(x => x.Receipt.ReceiptId, StringComparer.OrdinalIgnoreCase).Any(x => x.Count() != 1)
                || batch.Select(x => x.Receipt.CheckRunId).Distinct(StringComparer.OrdinalIgnoreCase).Count() != 1
                || batch.GroupBy(x => Path.GetFullPath(x.Clone.ClonePath), StringComparer.OrdinalIgnoreCase).Any(x => x.Count() != 1)
                || batch.GroupBy(x => PromotionIdentity(x.Clone), StringComparer.OrdinalIgnoreCase).Any(x => x.Count() != 1)
                || batch.GroupBy(x => PromotionIdentity(x.Current), StringComparer.OrdinalIgnoreCase).Any(x => x.Count() != 1)
                || batch.Where(x => !string.IsNullOrWhiteSpace(x.Current.TiaObjectId))
                    .GroupBy(x => x.Current.TiaObjectId, StringComparer.OrdinalIgnoreCase)
                    .Any(x => x.Count() != 1))
            {
                throw new InvalidDataException("Explicit-new promotion batch is not one-to-one across source paths, target identities, and live blocks.");
            }
        }

        private static string PromotionIdentity(CloneBlockRecord block)
        {
            return block == null
                ? string.Empty
                : EmptyIfNull(block.SoftwarePath) + "|" + EmptyIfNull(block.GroupPath) + "|" + EmptyIfNull(block.Name) + "|"
                    + FirstNonEmpty(block.NumberSpace, BlockNumberSpace(block.TypeName, block.ProgrammingLanguage)) + "|" + EmptyIfNull(block.Number);
        }

        private static string[] BuildBlockManifestRowFromCloneRecord(CloneBlockRecord block, string filePath, string message)
        {
            return new[]
            {
                block.SoftwarePath, block.GroupPath, block.GroupPathDisplay, block.GroupPath, block.Name, block.Number,
                block.AutoNumber, block.NumberMode, FirstNonEmpty(block.NumberSpace, BlockNumberSpace(block.TypeName, block.ProgrammingLanguage)),
                block.ProgrammingLanguage, block.BlockType, block.TypeName, block.SourceTypeName,
                block.InstanceOfName, block.InstanceOfNumber, block.InstanceOfType, block.SecondaryType,
                block.MemoryLayout, block.IsConsistent, block.IsKnowHowProtected, block.TiaObjectId, block.TiaObjectIdStatus,
                filePath, ComputeFileSha256(filePath), ComputeNormalizedTextSha256(filePath), "ok", message, "exported-source"
            };
        }

        private static void CommitProvenancePromotions(
            string outDir,
            string rootDir,
            string manifestPath,
            string[] headers,
            List<string[]> rows,
            List<ExplicitNewPromotionCandidate> promotions)
        {
            string publishRoot = Path.Combine(outDir, "_manifest-publish");
            string publishDir = Path.Combine(publishRoot, "run-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(publishDir);
            string stagedManifestPath = Path.Combine(publishDir, "plc-blocks.csv");
            string journalPath = Path.Combine(publishDir, "provenance-promotions.csv");
            string statePath = Path.Combine(publishDir, "provenance-promotion.json");

            foreach (ExplicitNewPromotionCandidate promotion in promotions)
            {
                string sidecarPath = promotion.Clone.ClonePath + ".meta.json";
                Dictionary<string, string> sidecar = ParseStrictFlatJsonObject(File.ReadAllText(sidecarPath, Encoding.UTF8), sidecarPath);
                if (!EqualsIgnoreCase(SidecarValue(sidecar, "sourceOrigin"), "explicit-new-local-source")
                    || !EqualsIgnoreCase(SidecarValue(sidecar, "softwarePath"), promotion.Clone.SoftwarePath))
                {
                    throw new InvalidDataException("Explicit-new promotion sidecar changed before transaction staging: " + sidecarPath);
                }
            }

            WriteCsv(stagedManifestPath, headers, rows);
            WriteCsv(
                journalPath,
                new[] { "ReceiptId", "CheckRunId", "SourcePath", "SidecarPath", "SourceNormalizedSha256", "SourceCanonicalSha256", "SoftwarePath", "GroupPath", "Name", "NumberSpace", "Number", "ProgrammingLanguage", "LiveTiaObjectId", "LiveTiaObjectIdStatus" },
                promotions.Select(x => new[]
                {
                    x.Receipt.ReceiptId,
                    x.Receipt.CheckRunId,
                    x.Clone.ClonePath,
                    x.Clone.ClonePath + ".meta.json",
                    x.Clone.NormalizedSourceSha256,
                    x.Receipt.SourceCanonicalSha256,
                    x.Clone.SoftwarePath,
                    x.Clone.GroupPath,
                    x.Clone.Name,
                    FirstNonEmpty(x.Clone.NumberSpace, BlockNumberSpace(x.Clone.TypeName, x.Clone.ProgrammingLanguage)),
                    x.Current.Number,
                    x.Receipt.ProgrammingLanguage,
                    x.Receipt.LiveTiaObjectId,
                    x.Receipt.LiveTiaObjectIdStatus
                }));
            WriteFlatJsonObjectAtomically(
                statePath,
                new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                {
                    { "state", "ready" },
                    { "manifestPath", Path.GetFullPath(manifestPath) },
                    { "manifestSha256", ComputeFileSha256(stagedManifestPath) },
                    { "journalSha256", ComputeFileSha256(journalPath) },
                    { "promotionCount", promotions.Count.ToString(CultureInfo.InvariantCulture) }
                });

            FinishProvenancePromotionTransaction(outDir, rootDir, publishDir);
        }

        private static void RecoverPendingProvenancePromotions(string outDir, string rootDir)
        {
            string publishRoot = Path.Combine(outDir, "_manifest-publish");
            if (!Directory.Exists(publishRoot))
            {
                return;
            }

            foreach (string publishDir in Directory.GetDirectories(publishRoot, "run-*", SearchOption.TopDirectoryOnly).OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
            {
                if (File.Exists(Path.Combine(publishDir, "provenance-promotion.json")))
                {
                    FinishProvenancePromotionTransaction(outDir, rootDir, publishDir);
                }
            }

            if (Directory.Exists(publishRoot) && !Directory.EnumerateFileSystemEntries(publishRoot).Any())
            {
                Directory.Delete(publishRoot, false);
            }
        }

        private static void FinishProvenancePromotionTransaction(string outDir, string rootDir, string publishDir)
        {
            EnsurePathInside(publishDir, Path.Combine(outDir, "_manifest-publish"));
            string statePath = Path.Combine(publishDir, "provenance-promotion.json");
            string journalPath = Path.Combine(publishDir, "provenance-promotions.csv");
            Dictionary<string, string> state = ParseStrictFlatJsonObject(File.ReadAllText(statePath, Encoding.UTF8), statePath);
            if (!EqualsIgnoreCase(SidecarValue(state, "state"), "ready"))
            {
                throw new InvalidDataException("Provenance promotion transaction is not ready: " + publishDir);
            }

            string manifestPath = SidecarValue(state, "manifestPath");
            string expectedManifestHash = SidecarValue(state, "manifestSha256");
            string expectedJournalHash = SidecarValue(state, "journalSha256");
            int expectedCount;
            if (string.IsNullOrWhiteSpace(manifestPath)
                || string.IsNullOrWhiteSpace(expectedManifestHash)
                || string.IsNullOrWhiteSpace(expectedJournalHash)
                || !int.TryParse(SidecarValue(state, "promotionCount"), NumberStyles.None, CultureInfo.InvariantCulture, out expectedCount)
                || expectedCount <= 0)
            {
                throw new InvalidDataException("Provenance promotion transaction state is incomplete: " + publishDir);
            }

            EnsurePathInside(manifestPath, outDir);
            string expectedManifestPath = Path.GetFullPath(Path.Combine(outDir, "plc-blocks.csv"));
            if (!EqualsIgnoreCase(Path.GetFullPath(manifestPath), expectedManifestPath))
            {
                throw new InvalidDataException("Provenance promotion transaction targets an unexpected manifest: " + manifestPath);
            }

            if (!File.Exists(journalPath) || !EqualsIgnoreCase(ComputeFileSha256(journalPath), expectedJournalHash))
            {
                throw new InvalidDataException("Provenance promotion transaction journal is missing or changed: " + journalPath);
            }

            List<Dictionary<string, string>> journal = ReadCsv(journalPath);
            if (journal.Count != expectedCount)
            {
                throw new InvalidDataException("Provenance promotion transaction row count mismatch: " + publishDir);
            }

            string stagedManifestPath = Path.Combine(publishDir, "plc-blocks.csv");
            bool hasStagedManifest = File.Exists(stagedManifestPath);
            if (hasStagedManifest)
            {
                if (!EqualsIgnoreCase(ComputeFileSha256(stagedManifestPath), expectedManifestHash))
                {
                    throw new InvalidDataException("Staged provenance manifest hash mismatch: " + stagedManifestPath);
                }
            }
            else if (!File.Exists(manifestPath) || !EqualsIgnoreCase(ComputeFileSha256(manifestPath), expectedManifestHash))
            {
                throw new InvalidDataException("Provenance promotion transaction has neither its staged nor published manifest: " + publishDir);
            }

            // Validate the complete durable transaction before consuming even
            // one sidecar. A late invalid row must not leave an earlier row in
            // tracked-baseline while the manifest remains unpublished.
            HashSet<string> receiptIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            HashSet<string> checkRunIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            HashSet<string> sourcePaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            HashSet<string> sidecarPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            HashSet<string> targetIdentities = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            HashSet<string> liveObjectIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            Dictionary<string, Dictionary<string, string>> pendingSidecars =
                new Dictionary<string, Dictionary<string, string>>(StringComparer.OrdinalIgnoreCase);
            foreach (Dictionary<string, string> row in journal)
            {
                string receiptId = GetCsvValue(row, "ReceiptId");
                string checkRunId = GetCsvValue(row, "CheckRunId");
                string sourcePath = GetCsvValue(row, "SourcePath");
                string sidecarPath = GetCsvValue(row, "SidecarPath");
                string sourceHash = GetCsvValue(row, "SourceNormalizedSha256");
                string sourceCanonicalHash = GetCsvValue(row, "SourceCanonicalSha256");
                string liveObjectId = GetCsvValue(row, "LiveTiaObjectId");
                if (string.IsNullOrWhiteSpace(receiptId)
                    || string.IsNullOrWhiteSpace(checkRunId)
                    || string.IsNullOrWhiteSpace(GetCsvValue(row, "ProgrammingLanguage")))
                {
                    throw new InvalidDataException("Provenance promotion recovery receipt is incomplete: " + publishDir);
                }
                if (!EqualsIgnoreCase(Path.GetFullPath(sidecarPath), Path.GetFullPath(sourcePath + ".meta.json"))
                    || string.IsNullOrWhiteSpace(GetCsvValue(row, "SoftwarePath"))
                    || string.IsNullOrWhiteSpace(GetCsvValue(row, "Name"))
                    || string.IsNullOrWhiteSpace(GetCsvValue(row, "NumberSpace")))
                {
                    throw new InvalidDataException("Provenance promotion recovery target identity is incomplete or inconsistent: " + publishDir);
                }
                string targetIdentity = GetCsvValue(row, "SoftwarePath") + "|" + RowGroupPathKey(row, "GroupPath") + "|"
                    + GetCsvValue(row, "Name") + "|" + GetCsvValue(row, "NumberSpace") + "|" + GetCsvValue(row, "Number");
                EnsurePathInside(sourcePath, rootDir);
                EnsurePathInside(sidecarPath, rootDir);
                if (!receiptIds.Add(receiptId)
                    || !sourcePaths.Add(Path.GetFullPath(sourcePath))
                    || !sidecarPaths.Add(Path.GetFullPath(sidecarPath))
                    || !targetIdentities.Add(targetIdentity)
                    || (!string.IsNullOrWhiteSpace(liveObjectId) && !liveObjectIds.Add(liveObjectId)))
                {
                    throw new InvalidDataException("Provenance promotion recovery journal is not one-to-one: " + publishDir);
                }
                checkRunIds.Add(checkRunId);

                if (!File.Exists(sourcePath)
                    || !EqualsIgnoreCase(ComputeNormalizedTextSha256(sourcePath), sourceHash)
                    || string.IsNullOrWhiteSpace(sourceCanonicalHash)
                    || !EqualsIgnoreCase(ComputeCanonicalSourceSha256(sourcePath), sourceCanonicalHash))
                {
                    throw new InvalidDataException("Provenance promotion source changed before transaction completion: " + sourcePath);
                }

                Dictionary<string, string> sidecar = ParseStrictFlatJsonObject(File.ReadAllText(sidecarPath, Encoding.UTF8), sidecarPath);
                string origin = SidecarValue(sidecar, "sourceOrigin");
                if (!EqualsIgnoreCase(SidecarValue(sidecar, "softwarePath"), GetCsvValue(row, "SoftwarePath")))
                {
                    throw new InvalidDataException("Provenance promotion sidecar software identity changed before transaction completion: " + sidecarPath);
                }
                if (EqualsIgnoreCase(origin, "explicit-new-local-source"))
                {
                    sidecar["number"] = GetCsvValue(row, "Number");
                    pendingSidecars.Add(sidecarPath, sidecar);
                }
                else if (!EqualsIgnoreCase(origin, "tracked-baseline"))
                {
                    throw new InvalidDataException("Provenance promotion sidecar is neither pending nor consumed: " + sidecarPath);
                }
            }

            if (checkRunIds.Count != 1)
            {
                throw new InvalidDataException("Provenance promotion recovery journal mixes check runs: " + publishDir);
            }

            foreach (KeyValuePair<string, Dictionary<string, string>> pendingSidecar in pendingSidecars)
            {
                pendingSidecar.Value["sourceOrigin"] = "tracked-baseline";
                WriteFlatJsonObjectAtomically(pendingSidecar.Key, pendingSidecar.Value);
            }

            if (hasStagedManifest)
            {
                PublishFileAtomically(stagedManifestPath, manifestPath, publishDir);
            }

            if (!File.Exists(manifestPath) || !EqualsIgnoreCase(ComputeFileSha256(manifestPath), expectedManifestHash))
            {
                throw new InvalidDataException("Published provenance manifest hash mismatch: " + manifestPath);
            }

            Directory.Delete(publishDir, true);
            string publishRoot = Path.GetDirectoryName(publishDir);
            if (Directory.Exists(publishRoot) && !Directory.EnumerateFileSystemEntries(publishRoot).Any())
            {
                Directory.Delete(publishRoot, false);
            }
        }

        private static void RewriteExplicitNewSidecarAsTracked(string sourcePath)
        {
            string sidecarPath = sourcePath + ".meta.json";
            Dictionary<string, string> sidecar = ParseStrictFlatJsonObject(File.ReadAllText(sidecarPath, Encoding.UTF8), sidecarPath);
            if (!EqualsIgnoreCase(SidecarValue(sidecar, "sourceOrigin"), "explicit-new-local-source"))
            {
                throw new InvalidDataException("Expected explicit-new-local-source sidecar was not found during provenance promotion: " + sidecarPath);
            }

            sidecar["sourceOrigin"] = "tracked-baseline";
            WriteFlatJsonObjectAtomically(sidecarPath, sidecar);
        }

        private static bool ManifestRowMatchesBlock(Dictionary<string, string> row, BlockRecord block)
        {
            if (row == null || block == null)
            {
                return false;
            }

            string rowTypeName = GetCsvValue(row, "TypeName");
            string rowLanguage = GetCsvValue(row, "ProgrammingLanguage");
            string rowNumberSpace = FirstNonEmpty(GetCsvValue(row, "NumberSpace"), BlockNumberSpace(rowTypeName, rowLanguage));
            return EqualsIgnoreCase(GetCsvValue(row, "SoftwarePath"), block.SoftwarePath)
                && EqualsIgnoreCase(RowGroupPathKey(row, "GroupPath"), EmptyIfNull(block.GroupPath))
                && EqualsIgnoreCase(GetCsvValue(row, "Name"), block.Name)
                && EqualsIgnoreCase(rowNumberSpace, BlockNumberSpace(block))
                && SafeInt(GetCsvValue(row, "Number")) == SafeInt(block.Number);
        }

        private static bool ManifestRowMatchesCloneRecord(Dictionary<string, string> row, CloneBlockRecord block)
        {
            if (row == null || block == null)
            {
                return false;
            }

            string rowTypeName = GetCsvValue(row, "TypeName");
            string rowLanguage = GetCsvValue(row, "ProgrammingLanguage");
            string rowNumberSpace = FirstNonEmpty(GetCsvValue(row, "NumberSpace"), BlockNumberSpace(rowTypeName, rowLanguage));
            return EqualsIgnoreCase(GetCsvValue(row, "SoftwarePath"), block.SoftwarePath)
                && EqualsIgnoreCase(RowGroupPathKey(row, "GroupPath"), EmptyIfNull(block.GroupPath))
                && EqualsIgnoreCase(GetCsvValue(row, "Name"), block.Name)
                && EqualsIgnoreCase(rowNumberSpace, FirstNonEmpty(block.NumberSpace, BlockNumberSpace(block.TypeName, block.ProgrammingLanguage)))
                && SafeInt(GetCsvValue(row, "Number")) == SafeInt(block.Number);
        }

        private static void CommitCompletedApplyCloneDeletions(string outDir, List<ApplyPlanItem> plan)
        {
            List<ApplyPlanItem> deletions = (plan ?? new List<ApplyPlanItem>())
                .Where(x => x != null && x.WillDelete && x.ConsumesManifestRow)
                .ToList();
            if (deletions.Count == 0)
            {
                return;
            }

            string manifestPath = Path.Combine(outDir, "plc-blocks.csv");
            if (!File.Exists(manifestPath))
            {
                throw new InvalidDataException("Cannot commit completed clone deletions because plc-blocks.csv is missing.");
            }

            List<Dictionary<string, string>> rows = ReadCsv(manifestPath);
            foreach (ApplyPlanItem deletion in deletions)
            {
                int removed = rows.RemoveAll(row => ManifestRowMatchesApplyDeletion(row, deletion));
                if (removed != 1)
                {
                    throw new InvalidDataException(
                        "Completed DeleteBlock could not consume exactly one tracked manifest row for "
                        + deletion.ManifestSoftwarePath + "/" + deletion.ManifestName + ".");
                }
            }

            string[] headers = BlockManifestHeaders();
            WriteCsvAtomically(
                manifestPath,
                headers,
                rows.Select(row => headers.Select(header => GetCsvValue(row, header)).ToArray()),
                outDir);
        }

        private static bool ManifestRowMatchesApplyDeletion(Dictionary<string, string> row, ApplyPlanItem item)
        {
            string rowTypeName = GetCsvValue(row, "TypeName");
            string rowLanguage = GetCsvValue(row, "ProgrammingLanguage");
            string rowNumberSpace = FirstNonEmpty(GetCsvValue(row, "NumberSpace"), BlockNumberSpace(rowTypeName, rowLanguage));
            string rowFilePath = GetCsvValue(row, "FilePath");
            return item != null
                && item.ConsumesManifestRow
                && EqualsIgnoreCase(GetCsvValue(row, "SoftwarePath"), item.ManifestSoftwarePath)
                && EqualsIgnoreCase(RowGroupPathKey(row, "GroupPath"), EmptyIfNull(item.ManifestGroupPath))
                && EqualsIgnoreCase(GetCsvValue(row, "Name"), item.ManifestName)
                && EqualsIgnoreCase(rowNumberSpace, item.ManifestNumberSpace)
                && (string.IsNullOrWhiteSpace(item.ManifestNumber)
                    || SafeInt(GetCsvValue(row, "Number")) == SafeInt(item.ManifestNumber))
                && (string.IsNullOrWhiteSpace(item.ManifestFilePath)
                    || (!string.IsNullOrWhiteSpace(rowFilePath) && EqualsIgnoreCase(
                        Path.GetFullPath(GetCsvValue(row, "FilePath")),
                        Path.GetFullPath(item.ManifestFilePath))));
        }

        private static void WriteCsvAtomically(string path, string[] headers, IEnumerable<string[]> rows, string stagingBaseDirectory)
        {
            string publishDir = Path.Combine(stagingBaseDirectory, "_manifest-publish", "run-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(publishDir);
            string stagedPath = Path.Combine(publishDir, Path.GetFileName(path));
            WriteCsv(stagedPath, headers, rows);
            PublishFileAtomically(stagedPath, path, publishDir);
            try
            {
                Directory.Delete(publishDir, true);
                string parent = Path.GetDirectoryName(publishDir);
                if (Directory.Exists(parent) && !Directory.EnumerateFileSystemEntries(parent).Any())
                {
                    Directory.Delete(parent, false);
                }
            }
            catch
            {
            }
        }

        private static void WriteFlatJsonObjectAtomically(string path, Dictionary<string, string> values)
        {
            string stagedPath = path + "." + Guid.NewGuid().ToString("N") + ".tmp";
            string backupPath = stagedPath + ".previous";
            using (StreamWriter writer = NewUtf8Writer(stagedPath))
            {
                writer.WriteLine("{");
                List<KeyValuePair<string, string>> entries = (values ?? new Dictionary<string, string>())
                    .OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                for (int i = 0; i < entries.Count; i++)
                {
                    writer.Write("  " + Json(entries[i].Key) + ": " + Json(entries[i].Value));
                    writer.WriteLine(i + 1 < entries.Count ? "," : string.Empty);
                }

                writer.WriteLine("}");
                writer.Flush();
                FileStream durableStream = writer.BaseStream as FileStream;
                if (durableStream != null) durableStream.Flush(true);
            }

            if (File.Exists(path))
            {
                File.Replace(stagedPath, path, backupPath, true);
                if (File.Exists(backupPath))
                {
                    File.Delete(backupPath);
                }
            }
            else
            {
                File.Move(stagedPath, path);
            }
        }

        private static CloneBlockRecord CreateCloneBlockRecordFromSourceFile(string rootDir, string file, string message)
        {
            Dictionary<string, string> sidecar = LoadSidecarMetadata(file);
            bool hasSidecar = sidecar.Count > 0;
            string relativePath = MakeRelativePath(rootDir, file);
            string groupPath = DirectoryNameToGroupPath(Path.GetDirectoryName(relativePath));
            string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(file);
            string number = string.Empty;
            string nameFromFile = fileNameWithoutExtension;
            int underscore = fileNameWithoutExtension.IndexOf('_');
            if (underscore > 0)
            {
                string maybeNumber = fileNameWithoutExtension.Substring(0, underscore);
                if (maybeNumber.All(char.IsDigit))
                {
                    number = maybeNumber;
                    nameFromFile = fileNameWithoutExtension.Substring(underscore + 1);
                }
            }

            string nameFromSource = TryReadBlockNameFromSource(file);
            string language = FirstNonEmpty(SidecarValue(sidecar, "programmingLanguage"), ProgrammingLanguageFromSourceFile(file));
            string typeName = InferBlockTypeNameFromSourceFile(file, language);
            DbSourceInfo dbSource = ParseDbSource(file);
            string blockKind = SidecarValue(sidecar, "blockKind");
            if (!string.IsNullOrWhiteSpace(blockKind))
            {
                typeName = TypeNameFromBlockKind(blockKind, typeName);
            }

            string sidecarNumber = SidecarValue(sidecar, "number");
            string sidecarNumberMode = SidecarValue(sidecar, "numberMode");
            if (hasSidecar)
            {
                string sidecarOrigin = SidecarValue(sidecar, "sourceOrigin");
                bool trackedBaselineSidecar = EqualsIgnoreCase(sidecarOrigin, "tracked-baseline")
                    && !string.IsNullOrWhiteSpace(SidecarValue(sidecar, "softwarePath"));
                number = FirstNonEmpty(sidecarNumber, trackedBaselineSidecar ? number : string.Empty);
            }

            bool manualNumberFromFile = !hasSidecar && !string.IsNullOrWhiteSpace(number);
            string numberMode = FirstNonEmpty(sidecarNumberMode, manualNumberFromFile ? "Manual" : "Auto");
            string autoNumber = FirstNonEmpty(SidecarValue(sidecar, "autoNumber"), AutoNumberFromNumberMode(numberMode));
            string instanceOfName = FirstNonEmpty(SidecarValue(sidecar, "instanceOfName"), dbSource.IsInstanceDb ? dbSource.InstanceOfName : string.Empty);
            string sidecarName = SidecarValue(sidecar, "name");
            string sidecarSoftwarePath = SidecarValue(sidecar, "softwarePath");
            string sourceOrigin = SidecarValue(sidecar, "sourceOrigin");
            bool explicitNewLocalSource = EqualsIgnoreCase(sourceOrigin, "explicit-new-local-source")
                && !string.IsNullOrWhiteSpace(sidecarSoftwarePath);
            return new CloneBlockRecord
            {
                // A first-manifest-path fallback is not proof of ownership in a
                // multi-PLC clone. Loose sources stay unscoped unless the
                // sidecar names their software explicitly.
                SoftwarePath = sidecarSoftwarePath,
                GroupPath = groupPath,
                GroupPathDisplay = GroupPathDisplay(groupPath),
                Name = FirstNonEmpty(nameFromSource, sidecarName, nameFromFile),
                Number = number,
                AutoNumber = autoNumber,
                NumberMode = numberMode,
                NumberSpace = BlockNumberSpace(typeName, language),
                ProgrammingLanguage = language,
                BlockType = BlockNumberSpace(typeName, language),
                TypeName = typeName,
                SourceTypeName = typeName,
                InstanceOfName = instanceOfName,
                SourceSha256 = ComputeFileSha256(file),
                NormalizedSourceSha256 = ComputeNormalizedTextSha256(file),
                RelativePath = relativePath,
                ClonePath = file,
                CurrentPath = string.Empty,
                ExportStatus = "ok",
                ExportMessage = message,
                Provenance = explicitNewLocalSource
                    ? "explicit-new-local-source"
                    : "unknown-orphaned"
            };
        }

        private static string TryReadBlockNameFromSource(string path)
        {
            string keyword;
            string name;
            return TryReadTopLevelSourceDeclaration(path, out keyword, out name)
                ? name
                : string.Empty;
        }

        private static bool TryReadTopLevelSourceDeclaration(string path, out string keyword, out string name)
        {
            keyword = string.Empty;
            name = string.Empty;
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            {
                return false;
            }

            string text = File.ReadAllText(path, Encoding.UTF8);
            int index = 0;
            while (index < text.Length)
            {
                SkipSourceDeclarationTrivia(text, ref index, true);
                if (index >= text.Length)
                {
                    return false;
                }

                char current = text[index];
                if (current == '"' || current == '\'')
                {
                    SkipSourceQuotedToken(text, ref index);
                    continue;
                }
                if (!char.IsLetter(current) && current != '_')
                {
                    index++;
                    continue;
                }

                int identifierStart = index++;
                while (index < text.Length && IsSourceIdentifierCharacter(text[index]))
                {
                    index++;
                }
                string identifier = text.Substring(identifierStart, index - identifierStart);
                if (!IsSourceBlockDeclarationKeyword(identifier))
                {
                    continue;
                }

                keyword = identifier.ToUpperInvariant();
                SkipSourceDeclarationTrivia(text, ref index, true);
                if (index >= text.Length)
                {
                    return false;
                }
                if (text[index] == '"')
                {
                    name = ReadSourceQuotedName(text, ref index);
                    return !string.IsNullOrWhiteSpace(name);
                }
                if (!char.IsLetter(text[index]) && text[index] != '_')
                {
                    return false;
                }

                int nameStart = index++;
                while (index < text.Length && IsSourceIdentifierCharacter(text[index]))
                {
                    index++;
                }
                name = text.Substring(nameStart, index - nameStart);
                return !string.IsNullOrWhiteSpace(name);
            }

            return false;
        }

        private static void SkipSourceDeclarationTrivia(string text, ref int index, bool skipAttributes)
        {
            while (index < text.Length)
            {
                if (text[index] == '\ufeff' || char.IsWhiteSpace(text[index]))
                {
                    index++;
                    continue;
                }
                if (index + 1 < text.Length && text[index] == '/' && text[index + 1] == '/')
                {
                    index += 2;
                    while (index < text.Length && text[index] != '\r' && text[index] != '\n') index++;
                    continue;
                }
                if (index + 1 < text.Length && text[index] == '(' && text[index + 1] == '*')
                {
                    int depth = 1;
                    index += 2;
                    while (index < text.Length && depth > 0)
                    {
                        if (index + 1 < text.Length && text[index] == '(' && text[index + 1] == '*')
                        {
                            depth++;
                            index += 2;
                        }
                        else if (index + 1 < text.Length && text[index] == '*' && text[index + 1] == ')')
                        {
                            depth--;
                            index += 2;
                        }
                        else
                        {
                            index++;
                        }
                    }
                    if (depth != 0)
                    {
                        throw new InvalidDataException("Unterminated SCL/STL block comment before the block declaration.");
                    }
                    continue;
                }
                if (skipAttributes && text[index] == '{')
                {
                    int depth = 1;
                    index++;
                    while (index < text.Length && depth > 0)
                    {
                        if (text[index] == '"' || text[index] == '\'')
                        {
                            SkipSourceQuotedToken(text, ref index);
                        }
                        else if (text[index] == '{')
                        {
                            depth++;
                            index++;
                        }
                        else if (text[index] == '}')
                        {
                            depth--;
                            index++;
                        }
                        else
                        {
                            index++;
                        }
                    }
                    if (depth != 0)
                    {
                        throw new InvalidDataException("Unterminated SCL/STL attribute or pragma before the block declaration.");
                    }
                    continue;
                }
                return;
            }
        }

        private static void SkipSourceQuotedToken(string text, ref int index)
        {
            char delimiter = text[index++];
            while (index < text.Length)
            {
                if (text[index++] != delimiter)
                {
                    continue;
                }
                if (index < text.Length && text[index] == delimiter)
                {
                    index++;
                    continue;
                }
                return;
            }
            throw new InvalidDataException("Unterminated SCL/STL quoted token before the block declaration.");
        }

        private static string ReadSourceQuotedName(string text, ref int index)
        {
            StringBuilder value = new StringBuilder();
            index++;
            while (index < text.Length)
            {
                char current = text[index++];
                if (current != '"')
                {
                    value.Append(current);
                    continue;
                }
                if (index < text.Length && text[index] == '"')
                {
                    value.Append('"');
                    index++;
                    continue;
                }
                return value.ToString();
            }
            throw new InvalidDataException("Unterminated quoted block name in SCL/STL source.");
        }

        private static Dictionary<string, string> LoadSidecarMetadata(string sourcePath)
        {
            string path = sourcePath + ".meta.json";
            if (!File.Exists(path))
            {
                return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            }

            try
            {
                return ParseStrictFlatJsonObject(File.ReadAllText(path, Encoding.UTF8), path);
            }
            catch (InvalidDataException)
            {
                // A malformed or nested sidecar must never grant a safety
                // exemption. Treat it as absent/unknown; downstream preflight
                // remains conservative.
                return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            }
        }

        private static Dictionary<string, string> ParseStrictFlatJsonObject(string text, string context)
        {
            string trimmed = TrimStrictJsonWhitespace(EmptyIfNull(text));
            if (!trimmed.StartsWith("{", StringComparison.Ordinal) || !trimmed.EndsWith("}", StringComparison.Ordinal))
            {
                throw new InvalidDataException(context + " is not a complete JSON object.");
            }

            Dictionary<string, string> result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            int index = 1;
            while (true)
            {
                SkipStrictJsonWhitespace(trimmed, ref index);
                if (index == trimmed.Length - 1)
                {
                    return result;
                }

                string key = ReadStrictJsonStringLiteral(trimmed, ref index, context + " key");
                if (string.IsNullOrWhiteSpace(key) || result.ContainsKey(key))
                {
                    throw new InvalidDataException(context + " contains an empty or duplicate property name.");
                }

                SkipStrictJsonWhitespace(trimmed, ref index);
                if (index >= trimmed.Length || trimmed[index] != ':')
                {
                    throw new InvalidDataException(context + " has a property without ':'.");
                }

                index++;
                SkipStrictJsonWhitespace(trimmed, ref index);
                string value;
                if (index < trimmed.Length && trimmed[index] == '"')
                {
                    value = ReadStrictJsonStringLiteral(trimmed, ref index, context + " value");
                }
                else
                {
                    int start = index;
                    while (index < trimmed.Length && trimmed[index] != ',' && trimmed[index] != '}')
                    {
                        if (trimmed[index] == '{' || trimmed[index] == '[' || trimmed[index] == ']')
                        {
                            throw new InvalidDataException(context + " must be a flat JSON object with primitive values.");
                        }

                        index++;
                    }

                    string raw = TrimStrictJsonWhitespace(trimmed.Substring(start, index - start));
                    if (!Regex.IsMatch(raw, "\\A(?:true|false|null|-?(?:0|[1-9][0-9]*)(?:\\.[0-9]+)?(?:[eE][+-]?[0-9]+)?)\\z"))
                    {
                        throw new InvalidDataException(context + " contains a non-primitive or malformed value.");
                    }

                    value = EqualsIgnoreCase(raw, "null") ? string.Empty : raw;
                }

                result[key] = value;
                SkipStrictJsonWhitespace(trimmed, ref index);
                if (index == trimmed.Length - 1 && trimmed[index] == '}')
                {
                    return result;
                }

                if (index >= trimmed.Length || trimmed[index] != ',')
                {
                    throw new InvalidDataException(context + " has invalid JSON object syntax.");
                }

                index++;
                SkipStrictJsonWhitespace(trimmed, ref index);
                if (index >= trimmed.Length - 1)
                {
                    throw new InvalidDataException(context + " has a trailing comma or incomplete property.");
                }
            }
        }

        private static string TrimStrictJsonWhitespace(string value)
        {
            string text = value ?? string.Empty;
            int start = 0;
            int end = text.Length - 1;
            while (start <= end && IsStrictJsonWhitespace(text[start]))
            {
                start++;
            }

            while (end >= start && IsStrictJsonWhitespace(text[end]))
            {
                end--;
            }

            return start > end ? string.Empty : text.Substring(start, end - start + 1);
        }

        private static void SkipStrictJsonWhitespace(string text, ref int index)
        {
            while (index < text.Length && IsStrictJsonWhitespace(text[index]))
            {
                index++;
            }
        }

        private static bool IsStrictJsonWhitespace(char value)
        {
            return value == ' ' || value == '\t' || value == '\r' || value == '\n';
        }

        private static string ReadStrictJsonStringLiteral(string text, ref int index, string context)
        {
            if (index >= text.Length || text[index] != '"')
            {
                throw new InvalidDataException(context + " is not a JSON string.");
            }

            index++;
            StringBuilder value = new StringBuilder();
            while (index < text.Length)
            {
                char c = text[index++];
                if (c == '"')
                {
                    return value.ToString();
                }

                if (c < 0x20)
                {
                    throw new InvalidDataException(context + " contains an unescaped control character.");
                }

                if (c != '\\')
                {
                    value.Append(c);
                    continue;
                }

                if (index >= text.Length)
                {
                    throw new InvalidDataException(context + " has an incomplete escape sequence.");
                }

                char escaped = text[index++];
                switch (escaped)
                {
                    case '"':
                    case '\\':
                    case '/':
                        value.Append(escaped);
                        break;
                    case 'b':
                        value.Append('\b');
                        break;
                    case 'f':
                        value.Append('\f');
                        break;
                    case 'n':
                        value.Append('\n');
                        break;
                    case 'r':
                        value.Append('\r');
                        break;
                    case 't':
                        value.Append('\t');
                        break;
                    case 'u':
                        if (index + 4 > text.Length)
                        {
                            throw new InvalidDataException(context + " has an incomplete unicode escape.");
                        }

                        string hex = text.Substring(index, 4);
                        int code;
                        if (!int.TryParse(hex, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out code))
                        {
                            throw new InvalidDataException(context + " has an invalid unicode escape.");
                        }

                        value.Append((char)code);
                        index += 4;
                        break;
                    default:
                        throw new InvalidDataException(context + " has an invalid escape sequence: \\" + escaped + ".");
                }
            }

            throw new InvalidDataException(context + " is unterminated.");
        }

        private static string SidecarValue(Dictionary<string, string> sidecar, string key)
        {
            string value;
            return sidecar != null && sidecar.TryGetValue(key, out value) ? value : string.Empty;
        }

        private static string JsonUnescape(string value)
        {
            if (string.IsNullOrEmpty(value))
            {
                return string.Empty;
            }

            StringBuilder builder = new StringBuilder(value.Length);
            for (int i = 0; i < value.Length; i++)
            {
                char c = value[i];
                if (c != '\\' || i + 1 >= value.Length)
                {
                    builder.Append(c);
                    continue;
                }

                char escaped = value[++i];
                switch (escaped)
                {
                    case '"':
                    case '\\':
                    case '/':
                        builder.Append(escaped);
                        break;
                    case 'b':
                        builder.Append('\b');
                        break;
                    case 'f':
                        builder.Append('\f');
                        break;
                    case 'n':
                        builder.Append('\n');
                        break;
                    case 'r':
                        builder.Append('\r');
                        break;
                    case 't':
                        builder.Append('\t');
                        break;
                    case 'u':
                        if (i + 4 < value.Length)
                        {
                            string hex = value.Substring(i + 1, 4);
                            int code;
                            if (int.TryParse(hex, System.Globalization.NumberStyles.HexNumber, null, out code))
                            {
                                builder.Append((char)code);
                                i += 4;
                                break;
                            }
                        }

                        builder.Append("\\u");
                        break;
                    default:
                        builder.Append(escaped);
                        break;
                }
            }

            return builder.ToString();
        }

        private static string TypeNameFromBlockKind(string blockKind, string fallbackTypeName)
        {
            string normalized = EmptyIfNull(blockKind).Trim();
            if (EqualsIgnoreCase(normalized, "FB"))
            {
                return "Siemens.Engineering.SW.Blocks.FB";
            }

            if (EqualsIgnoreCase(normalized, "FC"))
            {
                return "Siemens.Engineering.SW.Blocks.FC";
            }

            if (EqualsIgnoreCase(normalized, "OB"))
            {
                return "Siemens.Engineering.SW.Blocks.OB";
            }

            if (EqualsIgnoreCase(normalized, "DB") || EqualsIgnoreCase(normalized, "GlobalDB"))
            {
                return "Siemens.Engineering.SW.Blocks.GlobalDB";
            }

            if (EqualsIgnoreCase(normalized, "InstanceDB"))
            {
                return "Siemens.Engineering.SW.Blocks.InstanceDB";
            }

            return fallbackTypeName;
        }

        private static string AutoNumberFromNumberMode(string numberMode)
        {
            if (EqualsIgnoreCase(numberMode, "Auto"))
            {
                return "True";
            }

            if (EqualsIgnoreCase(numberMode, "Manual") || EqualsIgnoreCase(numberMode, "Fixed"))
            {
                return "False";
            }

            return string.Empty;
        }

        private static DbSourceInfo ParseDbSource(string path)
        {
            DbSourceInfo result = new DbSourceInfo();
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path) || !EqualsIgnoreCase(Path.GetExtension(path), ".db"))
            {
                return result;
            }

            string declarationKeyword;
            string declarationName;
            if (!TryReadTopLevelSourceDeclaration(path, out declarationKeyword, out declarationName)
                || !EqualsIgnoreCase(declarationKeyword, "DATA_BLOCK"))
            {
                return result;
            }
            result.IsDataBlock = true;
            result.BlockName = declarationName;

            bool dataBlockSeen = false;
            bool inAttributeBlock = false;
            foreach (string line in File.ReadLines(path, Encoding.UTF8))
            {
                string trimmed = StripLineComment(line).Trim();
                if (string.IsNullOrWhiteSpace(trimmed))
                {
                    continue;
                }

                if (inAttributeBlock)
                {
                    if (trimmed.IndexOf('}') >= 0)
                    {
                        inAttributeBlock = false;
                    }

                    continue;
                }

                if (trimmed.StartsWith("{", StringComparison.OrdinalIgnoreCase))
                {
                    if (trimmed.IndexOf('}') < 0)
                    {
                        inAttributeBlock = true;
                    }

                    continue;
                }

                if (!dataBlockSeen)
                {
                    if (!trimmed.StartsWith("DATA_BLOCK", StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    dataBlockSeen = true;
                    continue;
                }

                if (trimmed.StartsWith("VERSION", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                string quoted = ExtractSingleQuotedLineValue(trimmed);
                if (!string.IsNullOrWhiteSpace(quoted))
                {
                    result.IsInstanceDb = true;
                    result.InstanceOfName = quoted;
                    return result;
                }

                return result;
            }

            return result;
        }

        private static string StripLineComment(string value)
        {
            if (string.IsNullOrEmpty(value))
            {
                return string.Empty;
            }

            bool inString = false;
            for (int i = 0; i < value.Length - 1; i++)
            {
                if (value[i] == '"')
                {
                    inString = !inString;
                }

                if (!inString && value[i] == '/' && value[i + 1] == '/')
                {
                    return value.Substring(0, i);
                }
            }

            return value;
        }

        private static string ExtractFirstQuotedValue(string value)
        {
            if (string.IsNullOrEmpty(value))
            {
                return string.Empty;
            }

            int firstQuote = value.IndexOf('"');
            if (firstQuote < 0)
            {
                return string.Empty;
            }

            int secondQuote = value.IndexOf('"', firstQuote + 1);
            return secondQuote <= firstQuote ? string.Empty : value.Substring(firstQuote + 1, secondQuote - firstQuote - 1);
        }

        private static string ExtractSingleQuotedLineValue(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return string.Empty;
            }

            string trimmed = value.Trim();
            if (!trimmed.StartsWith("\"", StringComparison.OrdinalIgnoreCase))
            {
                return string.Empty;
            }

            int secondQuote = trimmed.IndexOf('"', 1);
            if (secondQuote <= 0)
            {
                return string.Empty;
            }

            string suffix = trimmed.Substring(secondQuote + 1).Trim();
            if (!(suffix.Length == 0 || suffix == ";"))
            {
                return string.Empty;
            }

            return trimmed.Substring(1, secondQuote - 1);
        }

        private static string InferBlockTypeNameFromSourceFile(string path, string programmingLanguage)
        {
            DbSourceInfo dbSource = ParseDbSource(path);
            if (dbSource.IsDataBlock)
            {
                return dbSource.IsInstanceDb
                    ? "Siemens.Engineering.SW.Blocks.InstanceDB"
                    : "Siemens.Engineering.SW.Blocks.GlobalDB";
            }

            string declarationKeyword;
            string declarationName;
            if (TryReadTopLevelSourceDeclaration(path, out declarationKeyword, out declarationName))
            {
                if (EqualsIgnoreCase(declarationKeyword, "FUNCTION_BLOCK")) return "Siemens.Engineering.SW.Blocks.FB";
                if (EqualsIgnoreCase(declarationKeyword, "FUNCTION")) return "Siemens.Engineering.SW.Blocks.FC";
                if (EqualsIgnoreCase(declarationKeyword, "ORGANIZATION_BLOCK")) return "Siemens.Engineering.SW.Blocks.OB";
                if (EqualsIgnoreCase(declarationKeyword, "DATA_BLOCK")) return "Siemens.Engineering.SW.Blocks.GlobalDB";
            }

            if (EqualsIgnoreCase(programmingLanguage, "DB")
                || EqualsIgnoreCase(programmingLanguage, "CPU_DB")
                || EqualsIgnoreCase(programmingLanguage, "F_DB")
                || EqualsIgnoreCase(programmingLanguage, "Motion_DB"))
            {
                return "Siemens.Engineering.SW.Blocks.GlobalDB";
            }

            return string.Empty;
        }

        private static string BlockNumberSpace(BlockRecord block)
        {
            return block == null ? string.Empty : BlockNumberSpace(block.TypeName, block.ProgrammingLanguage);
        }

        private static string BlockNumberSpace(string typeName, string programmingLanguage)
        {
            string normalizedType = EmptyIfNull(typeName);
            if (normalizedType.EndsWith(".FB", StringComparison.OrdinalIgnoreCase))
            {
                return "FB";
            }

            if (normalizedType.EndsWith(".FC", StringComparison.OrdinalIgnoreCase))
            {
                return "FC";
            }

            if (normalizedType.EndsWith(".OB", StringComparison.OrdinalIgnoreCase))
            {
                return "OB";
            }

            if (normalizedType.EndsWith(".GlobalDB", StringComparison.OrdinalIgnoreCase)
                || normalizedType.EndsWith(".InstanceDB", StringComparison.OrdinalIgnoreCase)
                || normalizedType.EndsWith(".DataBlock", StringComparison.OrdinalIgnoreCase))
            {
                return "DB";
            }

            if (EqualsIgnoreCase(programmingLanguage, "DB")
                || EqualsIgnoreCase(programmingLanguage, "CPU_DB")
                || EqualsIgnoreCase(programmingLanguage, "F_DB")
                || EqualsIgnoreCase(programmingLanguage, "Motion_DB"))
            {
                return "DB";
            }

            return string.IsNullOrWhiteSpace(normalizedType) ? EmptyIfNull(programmingLanguage) : normalizedType;
        }

        private static string ProgrammingLanguageFromSourceFile(string path)
        {
            string extension = Path.GetExtension(path);
            if (EqualsIgnoreCase(extension, ".scl"))
            {
                return "SCL";
            }

            if (EqualsIgnoreCase(extension, ".awl"))
            {
                return "STL";
            }

            if (EqualsIgnoreCase(extension, ".db"))
            {
                return "DB";
            }

            if (EqualsIgnoreCase(extension, ".lad"))
            {
                return "LAD";
            }

            if (EqualsIgnoreCase(extension, ".fbd"))
            {
                return "FBD";
            }

            if (EqualsIgnoreCase(extension, ".gr7"))
            {
                return "GRAPH";
            }

            return "SCL";
        }

        private static HashSet<string> LoadCloneGroupPaths(string outDir)
        {
            HashSet<string> groups = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            string manifestPath = Path.Combine(outDir, "block-groups.csv");
            if (File.Exists(manifestPath))
            {
                foreach (Dictionary<string, string> row in ReadCsv(manifestPath))
                {
                    groups.Add(RowGroupPathKey(row, "GroupPath"));
                }
            }

            string rootDir = Path.Combine(outDir, "_root");
            if (!Directory.Exists(rootDir))
            {
                return groups;
            }

            groups.Add(string.Empty);
            foreach (string directory in Directory.GetDirectories(rootDir, "*", SearchOption.AllDirectories))
            {
                bool containsSourceFile = Directory.GetFiles(directory, "*", SearchOption.TopDirectoryOnly).Any(IsKnownSourceFile);
                if (containsSourceFile)
                {
                    groups.Add(DirectoryNameToGroupPath(MakeRelativePath(rootDir, directory)));
                }
            }

            return groups;
        }

        private static List<Dictionary<string, string>> ReadCsv(string path)
        {
            List<Dictionary<string, string>> rows = new List<Dictionary<string, string>>();
            List<string> records = ParseCsvRecords(File.ReadAllText(path, Encoding.UTF8));
            if (records.Count == 0)
            {
                return rows;
            }

            List<string> headers = ParseCsvLine(records[0]);
            for (int i = 1; i < records.Count; i++)
            {
                if (string.IsNullOrWhiteSpace(records[i]))
                {
                    continue;
                }

                List<string> values = ParseCsvLine(records[i]);
                Dictionary<string, string> row = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                for (int j = 0; j < headers.Count; j++)
                {
                    row[headers[j]] = j < values.Count ? values[j] : string.Empty;
                }

                rows.Add(row);
            }

            return rows;
        }

        private static List<string> ParseCsvRecords(string text)
        {
            List<string> records = new List<string>();
            StringBuilder current = new StringBuilder();
            bool quoted = false;
            string value = text ?? string.Empty;
            for (int i = 0; i < value.Length; i++)
            {
                char c = value[i];
                if (c == '"')
                {
                    current.Append(c);
                    if (quoted && i + 1 < value.Length && value[i + 1] == '"')
                    {
                        current.Append(value[++i]);
                    }
                    else
                    {
                        quoted = !quoted;
                    }
                    continue;
                }

                if (!quoted && (c == '\r' || c == '\n'))
                {
                    records.Add(current.ToString());
                    current.Length = 0;
                    if (c == '\r' && i + 1 < value.Length && value[i + 1] == '\n')
                    {
                        i++;
                    }

                    continue;
                }

                current.Append(c);
            }

            if (current.Length > 0)
            {
                records.Add(current.ToString());
            }

            return records;
        }

        private static List<string> ParseCsvLine(string line)
        {
            List<string> values = new List<string>();
            StringBuilder current = new StringBuilder();
            bool quoted = false;

            for (int i = 0; i < line.Length; i++)
            {
                char c = line[i];
                if (quoted)
                {
                    if (c == '"')
                    {
                        if (i + 1 < line.Length && line[i + 1] == '"')
                        {
                            current.Append('"');
                            i++;
                        }
                        else
                        {
                            quoted = false;
                        }
                    }
                    else
                    {
                        current.Append(c);
                    }
                }
                else
                {
                    if (c == '"')
                    {
                        quoted = true;
                    }
                    else if (c == ',')
                    {
                        values.Add(current.ToString());
                        current.Length = 0;
                    }
                    else
                    {
                        current.Append(c);
                    }
                }
            }

            values.Add(current.ToString());
            return values;
        }

        private static string GetCsvValue(Dictionary<string, string> row, string key)
        {
            if (row == null)
            {
                return string.Empty;
            }

            string value;
            return row.TryGetValue(key, out value) ? value : string.Empty;
        }

        private static string GetCsvValueOrFallback(Dictionary<string, string> row, string key, string fallback)
        {
            if (row == null)
            {
                return fallback;
            }

            return row.ContainsKey(key) ? GetCsvValue(row, key) : fallback;
        }

        private static bool RowMatchesName(Dictionary<string, string> row, string expectedName)
        {
            if (string.IsNullOrWhiteSpace(expectedName))
            {
                return true;
            }

            return EqualsIgnoreCase(GetCsvValue(row, "Name"), expectedName)
                || EqualsIgnoreCase(GetCsvValue(row, "CloneName"), expectedName)
                || EqualsIgnoreCase(GetCsvValue(row, "CurrentName"), expectedName);
        }

        private static bool RowMatchesGroup(Dictionary<string, string> row, string expectedGroup)
        {
            if (string.IsNullOrWhiteSpace(expectedGroup))
            {
                return true;
            }

            string normalized = NormalizeGroupPathKey(expectedGroup);
            return EqualsIgnoreCase(RowGroupPathKey(row, "GroupPath"), normalized)
                || EqualsIgnoreCase(RowGroupPathKey(row, "CloneGroupPath"), normalized)
                || EqualsIgnoreCase(RowGroupPathKey(row, "CurrentGroupPath"), normalized)
                || EqualsIgnoreCase(RowGroupPathDisplay(row, "GroupPath"), expectedGroup)
                || EqualsIgnoreCase(RowGroupPathDisplay(row, "CloneGroupPath"), expectedGroup)
                || EqualsIgnoreCase(RowGroupPathDisplay(row, "CurrentGroupPath"), expectedGroup);
        }

        private static string RowGroupPathKey(Dictionary<string, string> row, string baseColumn)
        {
            string keyColumn = baseColumn + "Key";
            return NormalizeGroupPathKey(FirstNonEmpty(GetCsvValue(row, keyColumn), GetCsvValue(row, baseColumn)));
        }

        private static string RowGroupPathDisplay(Dictionary<string, string> row, string baseColumn)
        {
            string displayColumn = baseColumn + "Display";
            string display = GetCsvValue(row, displayColumn);
            return string.IsNullOrWhiteSpace(display) ? GroupPathDisplay(RowGroupPathKey(row, baseColumn)) : display;
        }

        private static string FirstNonEmpty(params string[] values)
        {
            foreach (string value in values)
            {
                if (!string.IsNullOrWhiteSpace(value))
                {
                    return value;
                }
            }

            return string.Empty;
        }

        private static string MakeRelativePath(string baseDirectory, string path)
        {
            Uri baseUri = new Uri(AppendDirectorySeparator(Path.GetFullPath(baseDirectory)));
            Uri pathUri = new Uri(Path.GetFullPath(path));
            if (!EqualsIgnoreCase(baseUri.Scheme, pathUri.Scheme))
            {
                return path;
            }

            return Uri.UnescapeDataString(baseUri.MakeRelativeUri(pathUri).ToString()).Replace('/', Path.DirectorySeparatorChar);
        }

        private static string AppendDirectorySeparator(string path)
        {
            return path.EndsWith(Path.DirectorySeparatorChar.ToString(), StringComparison.Ordinal)
                ? path
                : path + Path.DirectorySeparatorChar;
        }

        private static string DirectoryNameToGroupPath(string directory)
        {
            if (string.IsNullOrWhiteSpace(directory) || directory == ".")
            {
                return string.Empty;
            }

            return NormalizeGroupPathKey(directory);
        }

        private static string NormalizeLogicalPath(string path)
        {
            return EmptyIfNull(path).Replace('\\', '/').Trim('/').Trim('\\');
        }

        private static bool IsKnownSourceFile(string path)
        {
            string extension = Path.GetExtension(path);
            return EqualsIgnoreCase(extension, ".scl")
                || EqualsIgnoreCase(extension, ".awl")
                || EqualsIgnoreCase(extension, ".db")
                || EqualsIgnoreCase(extension, ".lad")
                || EqualsIgnoreCase(extension, ".fbd")
                || EqualsIgnoreCase(extension, ".gr7");
        }

        private static bool IsVisualSourcePathOrLanguage(string path, string programmingLanguage)
        {
            return IsVisualSourceFile(path) || IsVisualProgrammingLanguage(programmingLanguage);
        }

        private static bool IsCloneSourceExportableLanguage(string programmingLanguage)
        {
            return EqualsIgnoreCase(programmingLanguage, "SCL")
                || EqualsIgnoreCase(programmingLanguage, "STL")
                || EqualsIgnoreCase(programmingLanguage, "F_STL")
                || EqualsIgnoreCase(programmingLanguage, "DB")
                || EqualsIgnoreCase(programmingLanguage, "CPU_DB")
                || EqualsIgnoreCase(programmingLanguage, "F_DB")
                || EqualsIgnoreCase(programmingLanguage, "Motion_DB");
        }

        private static string UnsupportedCloneSourceLanguageMessage(BlockRecord block)
        {
            string language = block == null ? string.Empty : EmptyIfNull(block.ProgrammingLanguage);
            string name = block == null ? string.Empty : EmptyIfNull(block.Name);
            string numberSpace = block == null ? string.Empty : FirstNonEmpty(block.NumberSpace, BlockNumberSpace(block.TypeName, block.ProgrammingLanguage));
            string number = block == null ? string.Empty : EmptyIfNull(block.Number);
            return "Source clone export is not supported for language '" + language + "' on block '" + name + "' (" + numberSpace + number + "). Convert the block to STL/SCL in TIA Portal before syncing it into CLONE_PROJECT.";
        }

        private static bool IsVisualSourceFile(string path)
        {
            string extension = Path.GetExtension(EmptyIfNull(path));
            return EqualsIgnoreCase(extension, ".lad")
                || EqualsIgnoreCase(extension, ".fbd")
                || EqualsIgnoreCase(extension, ".gr7");
        }

        private static bool IsVisualProgrammingLanguage(string programmingLanguage)
        {
            return EqualsIgnoreCase(programmingLanguage, "LAD")
                || EqualsIgnoreCase(programmingLanguage, "LAD_IEC")
                || EqualsIgnoreCase(programmingLanguage, "F_LAD")
                || EqualsIgnoreCase(programmingLanguage, "F_LAD_LIB")
                || EqualsIgnoreCase(programmingLanguage, "FBD")
                || EqualsIgnoreCase(programmingLanguage, "FBD_IEC")
                || EqualsIgnoreCase(programmingLanguage, "F_FBD")
                || EqualsIgnoreCase(programmingLanguage, "F_FBD_LIB")
                || EqualsIgnoreCase(programmingLanguage, "GRAPH");
        }

        private static bool VisualSourceIsVerified(string sourcePath)
        {
            if (string.IsNullOrWhiteSpace(sourcePath) || !File.Exists(sourcePath + ".meta.json"))
            {
                return false;
            }

            Dictionary<string, string> sidecar = LoadSidecarMetadata(sourcePath);
            return IsTruthy(SidecarValue(sidecar, "visualSourceVerified"))
                || IsTruthy(SidecarValue(sidecar, "visualLanguageVerified"))
                || IsTruthy(SidecarValue(sidecar, "tiaGeneratedSource"));
        }

        private static bool IsTruthy(string value)
        {
            return EqualsIgnoreCase(value, "true")
                || EqualsIgnoreCase(value, "yes")
                || EqualsIgnoreCase(value, "1");
        }

        private static bool FilesEqual(string leftPath, string rightPath)
        {
            if (!File.Exists(leftPath) || !File.Exists(rightPath))
            {
                return false;
            }

            FileInfo left = new FileInfo(leftPath);
            FileInfo right = new FileInfo(rightPath);
            if (left.Length != right.Length)
            {
                return false;
            }

            byte[] leftBuffer = new byte[8192];
            byte[] rightBuffer = new byte[8192];
            using (FileStream leftStream = File.OpenRead(leftPath))
            using (FileStream rightStream = File.OpenRead(rightPath))
            {
                while (true)
                {
                    int leftRead = leftStream.Read(leftBuffer, 0, leftBuffer.Length);
                    int rightRead = rightStream.Read(rightBuffer, 0, rightBuffer.Length);
                    if (leftRead != rightRead)
                    {
                        return false;
                    }

                    if (leftRead == 0)
                    {
                        return true;
                    }

                    for (int i = 0; i < leftRead; i++)
                    {
                        if (leftBuffer[i] != rightBuffer[i])
                        {
                            return false;
                        }
                    }
                }
            }
        }

        private static string CloneProjectFolder(string projectPath, string explicitOutDir)
        {
            if (!File.Exists(projectPath))
            {
                throw new FileNotFoundException("Project file was not found.", projectPath);
            }

            string sourceDir = Path.GetDirectoryName(projectPath);
            string destDir = string.IsNullOrWhiteSpace(explicitOutDir)
                ? Path.Combine(Path.GetDirectoryName(sourceDir), Path.GetFileName(sourceDir) + "_work_" + DateTime.Now.ToString("yyyyMMdd-HHmmss"))
                : Path.GetFullPath(explicitOutDir);

            CopyDirectory(sourceDir, destDir, true);
            return destDir;
        }

        private static string BackupProjectFolder(string projectPath)
        {
            return BackupProjectFolder(projectPath, null);
        }

        private static string BackupProjectFolder(string projectPath, string excludedDirectory)
        {
            string sourceDir = Path.GetDirectoryName(projectPath);
            string excludedPath = string.IsNullOrWhiteSpace(excludedDirectory)
                ? null
                : Path.GetFullPath(excludedDirectory);
            if (!string.IsNullOrWhiteSpace(excludedPath))
            {
                if (SameDirectory(excludedPath, sourceDir))
                {
                    throw new InvalidOperationException("The project backup cannot exclude the project directory itself: " + excludedPath);
                }

                if (!IsPathUnder(excludedPath, sourceDir))
                {
                    excludedPath = null;
                }
            }

            string backupRoot = Path.Combine(Path.GetPathRoot(Path.GetFullPath(sourceDir)), "TIA_PROJECT_BACKUPS");
            string destDir = UniquePath(Path.Combine(backupRoot, Path.GetFileName(sourceDir) + "_" + DateTime.Now.ToString("yyyyMMdd-HHmmss")));
            try
            {
                CopyTiaProjectDirectoryForProbe(sourceDir, destDir, true, excludedPath);
            }
            catch (Exception copyException)
            {
                try
                {
                    if (Directory.Exists(destDir))
                    {
                        Directory.Delete(destDir, true);
                    }
                }
                catch (Exception cleanupException)
                {
                    throw new IOException(
                        "Project backup failed and its incomplete directory could not be removed: " + destDir,
                        new AggregateException(copyException, cleanupException));
                }

                throw;
            }
            return destDir;
        }

        private static void CopyDirectory(string sourceDir, string destDir, bool skipGeneratedToolOutputs)
        {
            EnsureExistingPathChainHasNoReparsePoints(sourceDir, "copy source");
            EnsureExistingPathChainHasNoReparsePoints(destDir, "copy destination");
            DirectoryInfo source = new DirectoryInfo(sourceDir);
            if (!source.Exists)
            {
                throw new DirectoryNotFoundException(sourceDir);
            }

            if (Directory.Exists(destDir))
            {
                throw new IOException("Destination already exists: " + destDir);
            }

            Directory.CreateDirectory(destDir);

            foreach (FileInfo file in source.GetFiles())
            {
                if ((file.Attributes & FileAttributes.ReparsePoint) != 0)
                {
                    throw new InvalidOperationException("Refusing to copy a reparse point/symlink: " + file.FullName);
                }
                file.CopyTo(Path.Combine(destDir, file.Name), false);
            }

            foreach (DirectoryInfo directory in source.GetDirectories())
            {
                if ((directory.Attributes & FileAttributes.ReparsePoint) != 0)
                {
                    throw new InvalidOperationException("Refusing to copy a reparse point/symlink: " + directory.FullName);
                }
                if (skipGeneratedToolOutputs && EqualsIgnoreCase(directory.Name, "out"))
                {
                    continue;
                }

                CopyDirectory(directory.FullName, Path.Combine(destDir, directory.Name), skipGeneratedToolOutputs);
            }
        }

        private static string Label(object value)
        {
            string name = SafeGet(value, "Name");
            string typeIdentifier = SafeGet(value, "TypeIdentifier");
            string orderNumber = SafeGet(value, "OrderNumber");

            List<string> parts = new List<string>();
            if (!string.IsNullOrEmpty(typeIdentifier))
            {
                parts.Add("type=" + typeIdentifier);
            }

            if (!string.IsNullOrEmpty(orderNumber))
            {
                parts.Add("order=" + orderNumber);
            }

            string details = parts.Count == 0 ? string.Empty : " [" + string.Join(", ", parts.ToArray()) + "]";
            return (string.IsNullOrEmpty(name) ? SafeDescribe(value) : name) + details;
        }

        private static string Details(object value, string[] properties)
        {
            List<string> parts = new List<string>();
            foreach (string property in properties)
            {
                string text = SafeGet(value, property);
                if (!string.IsNullOrEmpty(text))
                {
                    parts.Add(property + "=" + text);
                }
            }

            return parts.Count == 0 ? string.Empty : " [" + string.Join(", ", parts.ToArray()) + "]";
        }

        private static string SafeName(object value)
        {
            string name = SafeGet(value, "Name");
            return string.IsNullOrEmpty(name) ? SafeDescribe(value) : name;
        }

        private static string SafeGet(object value, string property)
        {
            object result = TryGetPropertyValue(value, property);
            return result == null ? string.Empty : Convert.ToString(result);
        }

        private static object GetPropertyValue(object target, string property)
        {
            object result = TryGetPropertyValue(target, property);
            if (result == null)
            {
                throw new MissingMemberException(target.GetType().FullName, property);
            }

            return result;
        }

        private static object TryGetPropertyValue(object target, string property)
        {
            if (target == null)
            {
                return null;
            }

            PropertyInfo info = target.GetType().GetProperty(property, BindingFlags.Public | BindingFlags.Instance);
            if (info == null)
            {
                return null;
            }

            try
            {
                return info.GetValue(target, null);
            }
            catch
            {
                return null;
            }
        }

        private static MethodInfo FindInstanceMethod(Type type, string name, int parameterCount)
        {
            return type.GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .FirstOrDefault(x => x.Name == name && x.GetParameters().Length == parameterCount);
        }

        private static Type FindType(string fullName)
        {
            Type type = TryFindType(fullName);
            if (type == null)
            {
                throw new TypeLoadException("Type was not found: " + fullName);
            }

            return type;
        }

        private static Type TryFindType(string fullName)
        {
            foreach (Assembly assembly in AppDomain.CurrentDomain.GetAssemblies())
            {
                Type type = assembly.GetType(fullName, false);
                if (type != null)
                {
                    return type;
                }
            }

            return null;
        }

        private static string DescribeMethod(MethodInfo method)
        {
            string[] parameters = method.GetParameters()
                .Select(x => x.ParameterType.FullName + " " + x.Name)
                .ToArray();
            return method.ReturnType.FullName + " " + method.Name + "(" + string.Join(", ", parameters) + ")";
        }

        private static string SafeDescribe(object value)
        {
            return value == null ? string.Empty : Convert.ToString(value);
        }

        private static bool CanPrintMore(int maxItems)
        {
            return _printedItems < maxItems;
        }

        private static void PrintLine(string text, int maxItems)
        {
            if (!CanPrintMore(maxItems))
            {
                return;
            }

            Console.WriteLine(text);
            _printedItems++;
        }

        private static void TryDispose(object value)
        {
            IDisposable disposable = value as IDisposable;
            if (disposable == null)
            {
                return;
            }

            try
            {
                disposable.Dispose();
            }
            catch
            {
            }
        }

        private static bool IsWriteCommand(string command)
        {
            return EqualsIgnoreCase(command, "set-attribute")
                || EqualsIgnoreCase(command, "compile-block")
                || EqualsIgnoreCase(command, "compile-all")
                || EqualsIgnoreCase(command, "delete-block")
                || EqualsIgnoreCase(command, "create-test-visual-fb")
                || EqualsIgnoreCase(command, "hmi-project-texts-apply")
                || EqualsIgnoreCase(command, "apply-clone");
        }

