            WriteSelfTestReports(outDir, results);

            int passed = results.Count(x => EqualsIgnoreCase(x.Status, "passed"));
            int failed = results.Count(x => EqualsIgnoreCase(x.Status, "failed"));
            Console.WriteLine("Self-test completed.");
            Console.WriteLine("Passed: " + passed);
            Console.WriteLine("Failed: " + failed);
            Console.WriteLine("Artifacts: " + outDir);
            foreach (SelfTestResult result in results.Where(x => EqualsIgnoreCase(x.Status, "failed")))
            {
                Console.WriteLine("  FAIL " + result.Name + ": " + result.Message);
            }

            if (failed > 0)
            {
                throw new InvalidOperationException("Self-test failed: " + failed + " failed.");
            }
        }

        private static string ResolveSelfTestOutputDirectory(string explicitOutDir)
        {
            if (!string.IsNullOrWhiteSpace(explicitOutDir))
            {
                return Path.GetFullPath(explicitOutDir);
            }

            DirectoryInfo baseDir = new DirectoryInfo(AppDomain.CurrentDomain.BaseDirectory);
            DirectoryInfo probeDir = baseDir.Name.Equals("bin", StringComparison.OrdinalIgnoreCase) && baseDir.Parent != null
                ? baseDir.Parent
                : new DirectoryInfo(Environment.CurrentDirectory);
            return Path.Combine(probeDir.FullName, "out", "self-test-current");
        }

        private static void RecreateSelfTestOutputDirectory(string outDir)
        {
            string fullPath = Path.GetFullPath(outDir);
            if (Directory.Exists(fullPath))
            {
                string trimmed = fullPath.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
                string name = Path.GetFileName(trimmed);
                bool safeName = !string.IsNullOrWhiteSpace(name) && name.StartsWith("self-test", StringComparison.OrdinalIgnoreCase);
                bool underToolOut = IsUnderToolOutDirectory(trimmed);
                if (!safeName && !underToolOut)
                {
                    throw new InvalidOperationException("Refusing to delete existing self-test output directory outside a self-test/" + ProductName + " out path: " + fullPath);
                }

                Directory.Delete(fullPath, true);
            }

            Directory.CreateDirectory(fullPath);
        }

        private static bool IsUnderToolOutDirectory(string path)
        {
            foreach (string toolDirectoryName in ToolDirectoryNames)
            {
                string marker = Path.DirectorySeparatorChar + toolDirectoryName + Path.DirectorySeparatorChar + "out" + Path.DirectorySeparatorChar;
                if (path.IndexOf(marker, StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return true;
                }
            }

            return false;
        }

        private static void RunSelfTestCase(List<SelfTestResult> results, string outDir, string name, Action<string> body)
        {
            DateTime started = DateTime.UtcNow;
            SelfTestResult result = new SelfTestResult
            {
                Name = name,
                Status = "passed",
                Message = "ok",
                Details = string.Empty
            };

            string caseDir = Path.Combine(outDir, "w", "t" + (results.Count + 1).ToString("00", CultureInfo.InvariantCulture));
            Directory.CreateDirectory(caseDir);

            try
            {
                Console.WriteLine("Self-test: " + name);
                body(caseDir);
            }
            catch (Exception ex)
            {
                result.Status = "failed";
                result.Message = ex.GetType().Name + ": " + ex.Message;
                result.Details = ex.ToString().Replace("\r", " ").Replace("\n", " ");
            }

            result.DurationMs = Convert.ToInt64((DateTime.UtcNow - started).TotalMilliseconds);
            results.Add(result);
        }

        private static void WriteSelfTestReports(string outDir, List<SelfTestResult> results)
        {
            string summaryPath = Path.Combine(outDir, "self-test-summary.txt");
            string csvPath = Path.Combine(outDir, "self-test-results.csv");
            string jsonPath = Path.Combine(outDir, "self-test-results.json");

            using (StreamWriter writer = NewUtf8Writer(summaryPath))
            {
                writer.WriteLine(ProductName + " self-test");
                writer.WriteLine("Generated: " + DateTime.Now.ToString("o"));
                writer.WriteLine("Output directory: " + outDir);
                writer.WriteLine("Passed: " + results.Count(x => EqualsIgnoreCase(x.Status, "passed")));
                writer.WriteLine("Failed: " + results.Count(x => EqualsIgnoreCase(x.Status, "failed")));
                writer.WriteLine();
                foreach (SelfTestResult result in results)
                {
                    writer.WriteLine(result.Status + " " + result.Name + " (" + result.DurationMs + " ms): " + result.Message);
                }
            }

            WriteCsv(csvPath,
                new[] { "Name", "Status", "DurationMs", "Message", "Details" },
                results.Select(x => new[] { x.Name, x.Status, x.DurationMs.ToString(CultureInfo.InvariantCulture), x.Message, x.Details }));

            using (StreamWriter writer = NewUtf8Writer(jsonPath))
            {
                writer.WriteLine("{");
                writer.WriteLine("  \"generatedAt\": " + Json(DateTime.Now.ToString("o")) + ",");
                writer.WriteLine("  \"outputDirectory\": " + Json(outDir) + ",");
                writer.WriteLine("  \"passed\": " + results.Count(x => EqualsIgnoreCase(x.Status, "passed")).ToString(CultureInfo.InvariantCulture) + ",");
                writer.WriteLine("  \"failed\": " + results.Count(x => EqualsIgnoreCase(x.Status, "failed")).ToString(CultureInfo.InvariantCulture) + ",");
                WriteJsonArray(writer, "results", results.Select(x => new Dictionary<string, string>
                {
                    { "name", x.Name },
                    { "status", x.Status },
                    { "durationMs", x.DurationMs.ToString(CultureInfo.InvariantCulture) },
                    { "message", x.Message },
                    { "details", x.Details }
                }), false);
                writer.WriteLine("}");
            }
        }

