        private static void SelfTestHmiPatchJsonlParser(string caseDir)
        {
            string patchPath = Path.Combine(caseDir, "patch.jsonl");
            List<string> lines = new List<string>
            {
                "# comment",
                string.Empty,
                "{\"op\":\"set-attribute\",\"object\":\"screen-item\",\"screen\":\"Main\",\"item\":\"Valve\",\"attribute\":\"Top\",\"value\":\"42\"}",
                "{\"op\":\"set-link\",\"object\":\"screen-item\",\"screen\":\"Main\",\"item\":\"Valve\",\"link\":\"Tag\",\"value\":\"Tag_1\"}",
                "{\"op\":\"set-text-list-entry\",\"object\":\"text-list-entry\",\"textList\":\"Mode\",\"from\":\"1\",\"culture\":\"ru-RU\",\"text\":" + Json(SelfTestQuotedText()) + "}",
                "{\"op\":\"set-screen-item-text\",\"object\":\"screen-item\",\"screen\":\"Main\",\"item\":\"Label\",\"culture\":\"ru-RU\",\"text\":" + Json(SelfTestNewText()) + "}",
                "{\"op\":\"duplicate-screen-items\",\"object\":\"screen-items\",\"screen\":\"Main\",\"itemIds\":\"A,B\",\"newItemIds\":\"A2,B2\",\"newItems\":\"A copy,B copy\",\"deltaX\":\"10\",\"deltaY\":\"20\"}",
                "{\"op\":\"move-screen-items\",\"object\":\"screen-items\",\"screen\":\"Main\",\"itemIds\":\"A,B\",\"deltaX\":\"0\",\"deltaY\":\"-60\"}",
                "{\"op\":\"set-event-parameter\",\"object\":\"event-handler\",\"screen\":\"Main\",\"item\":\"Button\",\"event\":\"Click\",\"function\":\"SetBit\",\"parameter\":\"Tag\",\"value\":\"Tag_1\"}"
            };
            File.WriteAllLines(patchPath, lines.ToArray(), Encoding.UTF8);

            List<HmiApplyPatchItem> patches = ReadHmiPatchJsonl(patchPath);
            AssertEqual("7", patches.Count.ToString(CultureInfo.InvariantCulture), "patch row count");
            AssertTrue(patches.All(x => string.IsNullOrWhiteSpace(x.ParseError)), "All supported patch rows should parse without errors.");
            AssertEqual("set-attribute", patches[0].Operation, "first operation");
            AssertEqual(SelfTestQuotedText(), PatchValue(patches[2], "text"), "quoted unicode patch text");
            AssertTrue(patches.Any(x => EqualsIgnoreCase(x.Operation, "move-screen-items")), "move-screen-items operation was not parsed.");

            string invalidPath = Path.Combine(caseDir, "invalid.jsonl");
            File.WriteAllText(invalidPath, "{bad", Encoding.UTF8);
            List<HmiApplyPatchItem> invalid = ReadHmiPatchJsonl(invalidPath);
            AssertEqual("1", invalid.Count.ToString(CultureInfo.InvariantCulture), "invalid patch row count");
            AssertTrue(!string.IsNullOrWhiteSpace(invalid[0].ParseError), "invalid JSON should be reported as parse error.");
        }

