        private static void SelfTestBlockInfoLookupIndex(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string metadataDir = Path.Combine(cloneDir, "_metadata");
            Directory.CreateDirectory(metadataDir);

            WriteTextFile(Path.Combine(metadataDir, "blocks.jsonl"),
                JsonObject(new Dictionary<string, string>
                {
                    { "groupPath", string.Empty },
                    { "name", "MotorFB" },
                    { "number", "5" },
                    { "numberSpace", "FB" },
                    { "programmingLanguage", "SCL" },
                    { "typeName", "Siemens.Engineering.SW.Blocks.FB" },
                    { "filePath", Path.Combine(cloneDir, "_root", "5_MotorFB.scl") },
                    { "status", "ok" }
                }) + Environment.NewLine
                + JsonObject(new Dictionary<string, string>
                {
                    { "groupPath", string.Empty },
                    { "name", "MotorDB" },
                    { "number", "5" },
                    { "numberSpace", "DB" },
                    { "programmingLanguage", "DB" },
                    { "typeName", "Siemens.Engineering.SW.Blocks.GlobalDB" },
                    { "filePath", Path.Combine(cloneDir, "_root", "5_MotorDB.db") },
                    { "status", "ok" }
                }) + Environment.NewLine);

            WriteCsv(Path.Combine(cloneDir, "clone-check-blocks.csv"),
                new[] { "Status", "GroupPath", "Name", "Number", "NumberSpace", "ProgrammingLanguage", "TypeName", "ClonePath", "CurrentPath", "Message" },
                new[]
                {
                    new[] { "unchanged", string.Empty, "MotorFB", "5", "FB", "SCL", "Siemens.Engineering.SW.Blocks.FB", Path.Combine(cloneDir, "_root", "5_MotorFB.scl"), Path.Combine(cloneDir, "_compare", "5_MotorFB.scl"), "Content is identical." },
                    new[] { "unchanged", string.Empty, "MotorDB", "5", "DB", "DB", "Siemens.Engineering.SW.Blocks.GlobalDB", Path.Combine(cloneDir, "_root", "5_MotorDB.db"), Path.Combine(cloneDir, "_compare", "5_MotorDB.db"), "Content is identical." }
                });

            List<BlockLookupRecord> records = LoadBlockLookupRecords(cloneDir);
            Options byName = new Options { Name = "MotorFB" };
            List<BlockLookupRecord> nameMatches = FilterBlockLookupRecords(records, byName);
            AssertEqual("1", nameMatches.Count.ToString(CultureInfo.InvariantCulture), "block-info name match count");
            AssertEqual("FB", nameMatches[0].NumberSpace, "block-info name number-space");
            AssertEqual("5", nameMatches[0].Number, "block-info name number");
            AssertEqual("unchanged", nameMatches[0].Status, "block-info should merge clone-check status");

            Options byFileStem = new Options { Name = "5_MotorFB" };
            List<BlockLookupRecord> fileStemMatches = FilterBlockLookupRecords(records, byFileStem);
            AssertEqual("1", fileStemMatches.Count.ToString(CultureInfo.InvariantCulture), "block-info file-stem match count");
            AssertEqual("MotorFB", fileStemMatches[0].Name, "block-info file-stem resolves block name");

            Options byNumber = new Options { Number = 5 };
            List<BlockLookupRecord> numberMatches = FilterBlockLookupRecords(records, byNumber);
            AssertEqual("2", numberMatches.Count.ToString(CultureInfo.InvariantCulture), "block-info number match count across spaces");

            Options byDbNumber = new Options { Number = 5, NumberSpace = "db" };
            List<BlockLookupRecord> dbMatches = FilterBlockLookupRecords(records, byDbNumber);
            AssertEqual("1", dbMatches.Count.ToString(CultureInfo.InvariantCulture), "block-info number-space filter count");
            AssertEqual("MotorDB", dbMatches[0].Name, "block-info reverse lookup DB name");
        }

        private static void SelfTestPlcRuntimeDwordOutputMaskGuard(string caseDir)
        {
            Dictionary<string, string> outputMask = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                { "DbName", "DB_Test_Outputs" },
                { "VariablePath", "AllowedOutputMask" }
            };

            GuardRuntimeDwordWrite(outputMask, 0x00FFFFFFu);

            bool rejected = false;
            try
            {
                GuardRuntimeDwordWrite(outputMask, 0x01000000u);
            }
            catch (InvalidOperationException)
            {
                rejected = true;
            }

            AssertTrue(rejected, "24-bit output-mask guard must reject bits 24..31 regardless of DB name.");

            Dictionary<string, string> ordinaryDword = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                { "DbName", "DB_Test_Data" },
                { "VariablePath", "DiagnosticValue" }
            };
            GuardRuntimeDwordWrite(ordinaryDword, 0xFFFFFFFFu);
        }

