            List<Dictionary<string, string>> rows = ReadCsv(Path.Combine(mapDir, "plc-runtime-map.csv"));
            AssertRuntimeMapRow(rows, "Flag", "0", "0", "write-candidate");
            AssertRuntimeMapRow(rows, "Quoted_flag", "0", "1", "write-candidate");
            AssertRuntimeMapRow(rows, "Count", "2", string.Empty, "write-candidate");
            AssertRuntimeMapRow(rows, "Nested.Inner", "4", string.Empty, "write-candidate");
            AssertRuntimeMapRow(rows, "Tail", "8", "0", "write-candidate");
        }

        private static void AssertRuntimeMapRow(List<Dictionary<string, string>> rows, string variablePath, string byteOffset, string bitOffset, string accessPolicy)
        {
            Dictionary<string, string> row = rows.FirstOrDefault(x => EqualsIgnoreCase(GetCsvValue(x, "VariablePath"), variablePath));
            AssertTrue(row != null, "Runtime map row not found: " + variablePath);
            AssertEqual(byteOffset, GetCsvValue(row, "ByteOffset"), "Runtime map byte offset for " + variablePath);
            AssertEqual(bitOffset, GetCsvValue(row, "BitOffset"), "Runtime map bit offset for " + variablePath);
            AssertEqual(accessPolicy, GetCsvValue(row, "AccessPolicy"), "Runtime map access policy for " + variablePath);
        }

        private static void SelfTestPlcGroupPathCodecSlashName(string caseDir)
        {
            string literalSlashKey = CombineGroupPathKey(CombineGroupPathKey(string.Empty, "Libraries"), "Units/sensors");
            string nestedKey = CombineGroupPathKey(CombineGroupPathKey(CombineGroupPathKey(string.Empty, "Libraries"), "Units"), "sensors");

            AssertEqual("Libraries/Units%2Fsensors", literalSlashKey, "Group key should escape slash inside a TIA group name.");
            AssertEqual("Libraries/Units/sensors", nestedKey, "Nested group key should keep slash as segment separator.");
            AssertTrue(!EqualsIgnoreCase(literalSlashKey, nestedKey), "Literal slash group name and nested group path must have different keys.");
            AssertEqual("Units/sensors", LastGroupNameFromKey(literalSlashKey), "Decoded last segment should preserve slash in group name.");
            AssertEqual("Libraries", ParentGroupPathKey(literalSlashKey), "Parent key should stay at the real TIA parent group.");
            AssertEqual("Libraries/Units/sensors", GroupPathDisplay(literalSlashKey), "Display path should stay human-readable.");
        }

        private static void SelfTestPlcGroupDiffIgnoresIntermediateFolders(string caseDir)
        {
            string outDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(outDir, "_root");
            string sourceDir = Path.Combine(rootDir, "Libraries", "Units", "sensors");
            Directory.CreateDirectory(sourceDir);
            WriteTextFile(Path.Combine(sourceDir, "1103_Pump_FB.awl"), "FUNCTION_BLOCK \"Pump_FB\"\nEND_FUNCTION_BLOCK\n");

            WriteCsv(Path.Combine(outDir, "block-groups.csv"),
                new[] { "SoftwarePath", "ParentGroupPath", "GroupPath", "Name", "Directory" },
                new[]
                {
                    new[] { "PLC", string.Empty, string.Empty, "_root", rootDir },
                    new[] { "PLC", string.Empty, "Libraries", "Libraries", Path.Combine(rootDir, "Libraries") },
                    new[] { "PLC", "Libraries", "Libraries/Units/sensors", "Units/sensors", sourceDir }
                });

            InventorySnapshot snapshot = new InventorySnapshot();
            snapshot.BlockGroups.Add(new BlockGroupRecord { SoftwarePath = "PLC", GroupPath = string.Empty, GroupPathDisplay = string.Empty, Name = "_root" });
            snapshot.BlockGroups.Add(new BlockGroupRecord { SoftwarePath = "PLC", GroupPath = "Libraries", GroupPathDisplay = "Libraries", Name = "Libraries" });
            snapshot.BlockGroups.Add(new BlockGroupRecord { SoftwarePath = "PLC", GroupPath = "Libraries/Units/sensors", GroupPathDisplay = "Libraries/Units/sensors", Name = "Units/sensors" });

            List<CloneGroupDiffRecord> diffs = BuildCloneGroupDiffs(outDir, snapshot);
            AssertTrue(!diffs.Any(x => EqualsIgnoreCase(x.Status, "removed") && EqualsIgnoreCase(x.GroupPath, "Libraries/Units")), "Intermediate filesystem directory must not be reported as removed TIA group.");
            AssertTrue(diffs.Any(x => EqualsIgnoreCase(x.Status, "unchanged") && EqualsIgnoreCase(x.GroupPath, "Libraries/Units/sensors")), "Actual slash-name group should remain unchanged in legacy clone layout.");
        }

        private static void SelfTestCleanLocalClassification(string caseDir)
        {
            string projectRoot = Path.Combine(caseDir, "Project");
            string toolDir = Path.Combine(projectRoot, ProductName);
            string cloneDir = Path.Combine(projectRoot, "CLONE_PROJECT");

            WriteTextFile(Path.Combine(toolDir, "Program.cs"), "// tool");
            WriteTextFile(Path.Combine(toolDir, "bin", ProductName + ".exe"), "exe");
            WriteTextFile(Path.Combine(toolDir, "out", "old-report", "report.txt"), "report");
            WriteTextFile(Path.Combine(cloneDir, "_root", "1_Block.scl"), "FUNCTION_BLOCK \"Block\"\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(Path.Combine(cloneDir, "_compare", "current", "1_Block.scl"), "snapshot");

            List<CleanLocalCandidate> audit = BuildCleanLocalCandidates(projectRoot, toolDir, cloneDir, "audit");
            CleanLocalCandidate outCandidate = audit.FirstOrDefault(x => EqualsIgnoreCase(x.Category, "probe-output"));
            CleanLocalCandidate binCandidate = audit.FirstOrDefault(x => EqualsIgnoreCase(x.Category, "probe-build-output"));
            CleanLocalCandidate workspace = audit.FirstOrDefault(x => EqualsIgnoreCase(x.Category, "project-workspace"));

            AssertTrue(outCandidate != null && outCandidate.Exists, "clean-local did not classify " + ProductName + "/out.");
            AssertEqual("candidate-delete", outCandidate.Action, "audit scope should not delete out.");
            AssertTrue(binCandidate != null && binCandidate.Exists, "clean-local did not classify " + ProductName + "/bin.");
            AssertTrue(workspace != null && EqualsIgnoreCase(workspace.Action, "keep"), "CLONE_PROJECT should be kept in audit scope.");

            List<CleanLocalCandidate> generated = BuildCleanLocalCandidates(projectRoot, toolDir, cloneDir, "probe-generated");
            CleanLocalCandidate generatedOut = generated.FirstOrDefault(x => EqualsIgnoreCase(x.Category, "probe-output"));
            CleanLocalCandidate generatedBin = generated.FirstOrDefault(x => EqualsIgnoreCase(x.Category, "probe-build-output"));
            AssertEqual("delete", generatedOut == null ? string.Empty : generatedOut.Action, "probe-generated scope should delete out.");
            AssertTrue(generatedBin != null && (EqualsIgnoreCase(generatedBin.Action, "delete") || EqualsIgnoreCase(generatedBin.Action, "manual-delete")), "probe-generated scope should mark bin as delete/manual-delete.");
        }

