        private static Dictionary<string, string> SourceBlockerTestRow(string status, string numberSpace, string number, string name)
        {
            // A "removed" row defaults to durable tracked-baseline provenance.
            return SourceBlockerTestRow(status, numberSpace, number, name,
                EqualsIgnoreCase(status, "removed") ? "tracked-baseline" : string.Empty);
        }

        private static Dictionary<string, string> SourceBlockerTestRow(string status, string numberSpace, string number, string name, string cloneProvenance)
        {
            return SourceBlockerTestRow(status, numberSpace, number, name, cloneProvenance, "PLC");
        }

        private static Dictionary<string, string> SourceBlockerTestRow(string status, string numberSpace, string number, string name, string cloneProvenance, string softwarePath)
        {
            bool removed = EqualsIgnoreCase(status, "removed");
            return new Dictionary<string, string>
            {
                { "SoftwarePath", softwarePath },
                { "Status", status },
                { "NumberSpace", numberSpace },
                { "Number", number },
                { "Name", name },
                { "CurrentNumberSpace", removed ? string.Empty : numberSpace },
                { "CurrentNumber", removed ? string.Empty : number },
                { "CurrentName", removed ? string.Empty : name },
                { "CurrentSoftwarePath", removed ? string.Empty : softwarePath },
                { "CloneNumberSpace", removed ? numberSpace : string.Empty },
                { "CloneNumber", removed ? number : string.Empty },
                { "CloneName", removed ? name : string.Empty },
                { "CloneSoftwarePath", removed ? softwarePath : string.Empty },
                { "CloneProvenance", cloneProvenance },
            };
        }

        private static bool SourceBlockerGateThrows(string commandName, List<Dictionary<string, string>> rows)
        {
            return SourceBlockerGateThrows(commandName, rows, new List<Dictionary<string, string>>());
        }

        private static bool SourceBlockerGateThrows(
            string commandName,
            List<Dictionary<string, string>> rows,
            List<Dictionary<string, string>> sourceBlockerRows)
        {
            try
            {
                EnsureNoSourceBlockersForWrite(commandName, rows, sourceBlockerRows);
                return false;
            }
            catch (InvalidOperationException)
            {
                return true;
            }
        }

        private static void SelfTestSourceBlockerClassificationShared(string caseDir)
        {
            List<Dictionary<string, string>> noReport = new List<Dictionary<string, string>>();

            // Pure fail-safe project: pre-existing F_LAD/LAD blocks the clone never
            // tracked, plus one unrelated changed SCL block. Nothing blocks.
            List<Dictionary<string, string>> failSafe = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("changed", "FB", "10", "FB_Logic"),
                SourceBlockerTestRow("source-blocked-current-only", "OB", "1", "Main"),
                SourceBlockerTestRow("source-blocked-current-only", "FB", "1", "Main_Safety_RTG1"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "6", "SAFETY_COMMON"),
            };
            EnsureNoSourceBlockersForWrite("apply-clone", failSafe, noReport);
            AssertTrue(BlockingSourceBlockerCount(failSafe, noReport) == 0, "fail-safe current-only rows must not block");
            AssertTrue(InformationalSourceBlockerCount(failSafe) == 3, "fail-safe current-only rows must be counted as informational");

            // Both genuinely blocking statuses.
            List<Dictionary<string, string>> converted = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("source-blocked-language-converted", "FB", "20", "FB_Was_Scl"),
            };
            AssertTrue(BlockingSourceBlockerCount(converted, noReport) == 1, "language-converted must block");
            AssertTrue(SourceBlockerGateThrows("apply-clone", converted), "language-converted must throw the gate");

            List<Dictionary<string, string>> exportErr = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("source-blocked-export-error", "FC", "7", "FC_Broken"),
            };
            AssertTrue(BlockingSourceBlockerCount(exportErr, noReport) == 1, "export-error must block");

            // Fail closed: an unknown future source-blocked-* status still blocks.
            List<Dictionary<string, string>> unknown = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("source-blocked-future-reason", "FB", "30", "FB_New"),
            };
            AssertTrue(BlockingSourceBlockerCount(unknown, noReport) == 1, "unknown source-blocked-* status must fail closed (block)");
            AssertTrue(SourceBlockerGateThrows("sync-clone", unknown), "unknown source-blocked-* status must throw the gate");

            // Degraded input (only the dedicated report, no block report): fail closed.
            List<Dictionary<string, string>> reportOnly = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("source-blocked-current-only", "FC", "4", "KUKA_SAFETY_IO"),
            };
            AssertTrue(BlockingSourceBlockerCount(null, reportOnly) == 1, "with only the dedicated report available, count every source blocker");
        }

        private static void SelfTestSourceBlockerReportSeverity(string caseDir)
        {
            string reportPath = Path.Combine(caseDir, "clone-check-source-blockers.csv");
            List<CloneDiffRecord> diffs = new List<CloneDiffRecord>
            {
                // informational: current-only, no matching removed clone record
                CloneDiff("source-blocked-current-only", new CloneBlockRecord { SoftwarePath = "PLC", Name = "Main_Safety_RTG1", Number = "1", NumberSpace = "FB", ProgrammingLanguage = "F_LAD" }, null, "current-only"),
                // blocking: clone-tracked block converted to a visual language
                CloneDiff("source-blocked-language-converted", new CloneBlockRecord { SoftwarePath = "PLC", Name = "FB_Was_Scl", Number = "20", NumberSpace = "FB", ProgrammingLanguage = "LAD" }, new CloneBlockRecord { SoftwarePath = "PLC", Name = "FB_Was_Scl", Number = "20", NumberSpace = "FB", ProgrammingLanguage = "SCL", Provenance = "tracked-baseline" }, "converted"),
                // blocking: current-only that shares a number with a removed clone record
                CloneDiff("source-blocked-current-only", new CloneBlockRecord { SoftwarePath = "PLC", Name = "Time_Meter", Number = "31", NumberSpace = "FC", ProgrammingLanguage = "LAD" }, null, "current-only paired"),
                CloneDiff("removed", null, new CloneBlockRecord { SoftwarePath = "PLC", Name = "Time_Meter", Number = "31", NumberSpace = "FC", ProgrammingLanguage = "SCL", Provenance = "tracked-baseline" }, "removed clone record"),
            };

            WriteCloneCheckSourceBlockerReport(reportPath, diffs);
            List<Dictionary<string, string>> rows = ReadCsv(reportPath);
            AssertTrue(rows.Count == 3, "source blocker report lists the three source-blocked rows");

            Dictionary<string, string> safety = rows.First(r => EqualsIgnoreCase(GetCsvValue(r, "Name"), "Main_Safety_RTG1"));
            Dictionary<string, string> convertedRow = rows.First(r => EqualsIgnoreCase(GetCsvValue(r, "Name"), "FB_Was_Scl"));
            Dictionary<string, string> pairedRow = rows.First(r => EqualsIgnoreCase(GetCsvValue(r, "Name"), "Time_Meter"));
            AssertEqual("warning", GetCsvValue(safety, "Severity"), "unmatched fail-safe current-only row is a warning");
            AssertEqual("error", GetCsvValue(convertedRow, "Severity"), "language-converted row is an error");
            AssertEqual("error", GetCsvValue(pairedRow, "Severity"), "current-only row paired with a removed clone record is an error");
        }

        private static void SelfTestSourceBlockerAfterWriteAndSync(string caseDir)
        {
            // After-write verification for "changed SCL + current-only F_LAD": once
            // the changed row is applied it reads back as unchanged, and the F_LAD
            // current-only row must not make ApplyCloneDirtyRowCount or the source
            // blocker count non-zero, so the after-clone-check gate can accept.
            List<Dictionary<string, string>> afterRows = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("unchanged", "FB", "10", "FB_Logic"),
                SourceBlockerTestRow("source-blocked-current-only", "FB", "1", "Main_Safety_RTG1"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "6", "SAFETY_COMMON"),
            };
            AssertTrue(ApplyCloneDirtyRowCount(afterRows) == 0, "unmatched current-only rows must not count as dirty after apply");
            AssertTrue(BlockingSourceBlockerCount(afterRows, new List<Dictionary<string, string>>()) == 0, "unmatched current-only rows must not fail after-write source-blocker check");

            // sync-clone must refuse when a current-only visual block collides with a
            // removed clone record (silent-divergence guard).
            List<Dictionary<string, string>> colliding = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", "FC", "31", "Time_Meter"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "31", "Time_Meter"),
            };
            AssertTrue(SourceBlockerGateThrows("sync-clone", colliding), "sync-clone must refuse a current-only/removed collision");
            AssertTrue(ApplyCloneDirtyRowCount(colliding) >= 1, "a colliding current-only row counts as dirty");

            // A genuinely new clone-only block with the exact durable sidecar
            // provenance plus an unrelated fail-safe block: the new block
            // proceeds, the fail-safe block stays informational.
            List<Dictionary<string, string>> newAndFailSafe = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", "FC", "31", "Widget_New", "explicit-new-local-source"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "4", "KUKA_SAFETY_IO"),
            };
            EnsureNoSourceBlockersForWrite("apply-clone", newAndFailSafe, new List<Dictionary<string, string>>());
            AssertTrue(BlockingSourceBlockerCount(newAndFailSafe, new List<Dictionary<string, string>>()) == 0, "new clone-only block must not be blocked by an unrelated fail-safe block");

            // But a new clone-only file that reuses the number of a live visual
            // block still fails closed (number collision).
            List<Dictionary<string, string>> newCollidesNumber = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", "FC", "4", "Widget_New", "explicit-new-local-source"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "4", "KUKA_SAFETY_IO"),
            };
            AssertTrue(SourceBlockerGateThrows("apply-clone", newCollidesNumber), "a new clone-only block reusing a live visual block's number must block");
        }

        private static void SelfTestSourceBlockerTrackedIdentityChange(string caseDir)
        {
            // Tracked SCL block renamed in TIA (number kept) and converted to LAD.
            List<Dictionary<string, string>> renamedKeptNumber = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", "FC", "20", "FooBlock"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "20", "BarBlock"),
            };
            AssertTrue(SourceBlockerGateThrows("apply-clone", renamedKeptNumber), "renamed+converted tracked block (number kept) must block");

            // Number changed, name kept -> paired by name.
            List<Dictionary<string, string>> renumberedKeptName = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", "FC", "20", "FooBlock"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "99", "FooBlock"),
            };
            AssertTrue(SourceBlockerGateThrows("apply-clone", renumberedKeptName), "renamed+converted tracked block (name kept) must block");

            // BOTH name and number change: no name/number pairing, but the removed
            // row is a manifest-tracked block of the same number space -> fail closed.
            List<Dictionary<string, string>> renamedAndRenumbered = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", "FC", "20", "FooBlock"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "99", "BarBlock"),
            };
            AssertTrue(SourceBlockerGateThrows("apply-clone", renamedAndRenumbered), "tracked block with both name and number changed before visual conversion must fail closed");
            AssertTrue(SourceBlockerGateThrows("sync-clone", renamedAndRenumbered), "sync-clone must also refuse the ambiguous set");

            // A tracked block of a DIFFERENT number space that went missing does not
            // make an unrelated fail-safe block blocking.
            List<Dictionary<string, string>> differentSpace = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", "FB", "20", "FooFb"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "6", "SAFETY_COMMON"),
            };
            EnsureNoSourceBlockersForWrite("apply-clone", differentSpace, new List<Dictionary<string, string>>());
            AssertTrue(BlockingSourceBlockerCount(differentSpace, new List<Dictionary<string, string>>()) == 0, "a missing tracked block of a different number space must not block an unrelated fail-safe block");

            List<Dictionary<string, string>> differentSoftware = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", "FC", "20", "FooBlock", "tracked-baseline", "PLC_A"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "99", "BarBlock", string.Empty, "PLC_B"),
            };
            EnsureNoSourceBlockersForWrite("apply-clone", differentSoftware, new List<Dictionary<string, string>>());
            AssertTrue(BlockingSourceBlockerCount(differentSoftware, new List<Dictionary<string, string>>()) == 0, "rows from distinct SoftwarePath values must not be matched");

            List<Dictionary<string, string>> missingSoftware = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", "FC", "20", "FooBlock", "tracked-baseline", string.Empty),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "99", "BarBlock", string.Empty, "PLC_B"),
            };
            AssertTrue(SourceBlockerGateThrows("apply-clone", missingSoftware), "missing SoftwarePath must fail closed because software scope is ambiguous");

            List<Dictionary<string, string>> missingNumberSpace = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", string.Empty, "20", "LostDeclaration", "unknown-orphaned", "PLC"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "99", "RenamedVisual", string.Empty, "PLC"),
            };
            AssertTrue(SourceBlockerGateThrows("apply-clone", missingNumberSpace), "a missing removed NumberSpace must overlap every live number space and fail closed");

            List<Dictionary<string, string>> unrecognizedNumberSpace = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", "SCL", "20", "LostDeclaration", "unknown-orphaned", "PLC"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "99", "RenamedVisual", string.Empty, "PLC"),
            };
            AssertTrue(SourceBlockerGateThrows("sync-clone", unrecognizedNumberSpace), "an unrecognized removed NumberSpace must overlap every live number space and fail closed");
        }

        private static void SelfTestSourceBlockerReportCrossCheck(string caseDir)
        {
            // The main block report looks benign (no source-blocked rows), but the
            // dedicated report carries a Severity=error row: fail closed.
            List<Dictionary<string, string>> benignBlockRows = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("changed", "FB", "10", "FB_Logic"),
                SourceBlockerTestRow("unchanged", "FC", "6", "SAFETY_COMMON"),
            };
            List<Dictionary<string, string>> dedicated = new List<Dictionary<string, string>>
            {
                new Dictionary<string, string>
                {
                    { "Severity", "error" }, { "Status", "source-blocked-language-converted" },
                    { "Name", "FB_Was_Scl" }, { "NumberSpace", "FB" }, { "Number", "20" },
                },
            };
            AssertTrue(BlockingSourceBlockerCount(benignBlockRows, dedicated) == 1,
                "a Severity=error row in the dedicated report must be counted even when the main report looks benign");

            // A dedicated report with only Severity=warning rows does not add a blocker.
            List<Dictionary<string, string>> warningOnly = new List<Dictionary<string, string>>
            {
                new Dictionary<string, string>
                {
                    { "Severity", "warning" }, { "Status", "source-blocked-current-only" },
                    { "SoftwarePath", "PLC" },
                    { "Name", "Main_Safety_RTG1" }, { "NumberSpace", "FB" }, { "Number", "1" },
                },
            };
            AssertTrue(BlockingSourceBlockerCount(benignBlockRows, warningOnly) == 0,
                "a warning-only dedicated report must not add a blocker");

            List<Dictionary<string, string>> warningWithoutIdentity = new List<Dictionary<string, string>>
            {
                new Dictionary<string, string>
                {
                    { "Severity", "warning" }, { "Status", "source-blocked-current-only" },
                    { "SoftwarePath", "PLC" }, { "Name", string.Empty },
                    { "NumberSpace", string.Empty }, { "Number", string.Empty },
                },
            };
            AssertTrue(BlockingSourceBlockerCount(benignBlockRows, warningWithoutIdentity) == 1,
                "a warning row without a usable block identity must fail closed");

            // A dedicated report with no Severity column (older format) fails closed.
            List<Dictionary<string, string>> noSeverity = new List<Dictionary<string, string>>
            {
                new Dictionary<string, string>
                {
                    { "Status", "source-blocked-current-only" }, { "Name", "Legacy" },
                    { "NumberSpace", "FC" }, { "Number", "5" },
                },
            };
            AssertTrue(BlockingSourceBlockerCount(benignBlockRows, noSeverity) == 1,
                "a dedicated report without a Severity column must fail closed");

            List<Dictionary<string, string>> blankSeverity = new List<Dictionary<string, string>>
            {
                new Dictionary<string, string>
                {
                    { "Severity", string.Empty }, { "Status", "source-blocked-current-only" },
                    { "Name", "BlankSeverity" }, { "NumberSpace", "FC" }, { "Number", "7" },
                },
            };
            AssertTrue(BlockingSourceBlockerCount(benignBlockRows, blankSeverity) == 1,
                "a dedicated report with blank Severity must fail closed");

            List<Dictionary<string, string>> unknownSeverity = new List<Dictionary<string, string>>
            {
                new Dictionary<string, string>
                {
                    { "Severity", "info" }, { "Status", "source-blocked-current-only" },
                    { "Name", "UnknownSeverity" }, { "NumberSpace", "FC" }, { "Number", "8" },
                },
            };
            AssertTrue(BlockingSourceBlockerCount(benignBlockRows, unknownSeverity) == 1,
                "a dedicated report with unknown Severity must fail closed");
        }

        private static void SelfTestSyncCloneSourceBlockerCrossReportGate(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string compareRoot = Path.Combine(cloneDir, "_compare", "current-self-test", "_root");
            string clonePath = Path.Combine(rootDir, "10_FB_Logic.scl");
            string currentPath = Path.Combine(compareRoot, "10_FB_Logic.scl");
            WriteTextFile(clonePath, "clone-before" + Environment.NewLine);
            WriteTextFile(currentPath, "current-after" + Environment.NewLine);
            string checkRunId = Guid.NewGuid().ToString("N");

            WriteCsv(
                Path.Combine(cloneDir, CloneCheckBlockFileName),
                new[]
                {
                    "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Status", "Name", "NumberSpace", "Number",
                    "CloneName", "CloneNumberSpace", "CloneNumber",
                    "CurrentName", "CurrentNumberSpace", "CurrentNumber",
                    "CloneSoftwarePath", "CurrentSoftwarePath", "ClonePath", "CurrentPath", "CurrentSourceSha256", "CloneProvenance"
                },
                new[]
                {
                    new[]
                    {
                        CloneCheckBundleSchemaVersion, checkRunId, "PLC", "changed", "FB_Logic", "FB", "10",
                        "FB_Logic", "FB", "10",
                        "FB_Logic", "FB", "10",
                        "PLC", "PLC", clonePath, currentPath, ComputeFileSha256(currentPath), "tracked-baseline"
                    }
                });

            WriteCsv(
                Path.Combine(cloneDir, CloneCheckSourceBlockerFileName),
                new[] { "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Severity", "Status", "Name", "NumberSpace", "Number" },
                new[]
                {
                    new[] { CloneCheckBundleSchemaVersion, checkRunId, "PLC", "error", "source-blocked-language-converted", "FB_Was_Scl", "FB", "20" }
                });
            CompleteSelfTestCloneCheckBundle(cloneDir, Path.GetDirectoryName(compareRoot), checkRunId, 1, 1);

            bool blocked = false;
            try
            {
                SyncProjectClone(cloneDir);
            }
            catch (InvalidOperationException ex)
            {
                blocked = ex.Message.IndexOf("sync-clone is blocked", StringComparison.OrdinalIgnoreCase) >= 0;
            }

            AssertTrue(blocked, "sync-clone must consume the dedicated source-blocker report and fail closed on Severity=error.");
            AssertEqual("clone-before" + Environment.NewLine, File.ReadAllText(clonePath, Encoding.UTF8), "sync-clone gate must fire before clone source mutation");
            AssertTrue(!Directory.Exists(Path.Combine(cloneDir, "_sync-backups")), "sync-clone gate must fire before backup/mutation starts");
            AssertTrue(!File.Exists(Path.Combine(cloneDir, "sync-clone-report.csv")), "sync-clone gate must fire before a success report is written");
        }

        private static void CompleteSelfTestCloneCheckBundle(string cloneDir, string compareDirectory, string checkRunId, int blockRows, int sourceBlockerRows)
        {
            string groupPath = Path.Combine(cloneDir, CloneCheckGroupFileName);
            WriteCsv(
                groupPath,
                new[] { "CheckSchemaVersion", "CheckRunId", "Status" },
                new string[0][]);
            string summaryPath = Path.Combine(cloneDir, CloneCheckSummaryFileName);
            WriteTextFile(summaryPath, "Check schema version: " + CloneCheckBundleSchemaVersion + Environment.NewLine + "Check run ID: " + checkRunId + Environment.NewLine);
            string workspacePath = Path.Combine(cloneDir, CloneCheckWorkspaceFileName);
            List<CloneWorkspaceFileRecord> workspaceFiles = BuildCloneWorkspaceInventory(cloneDir);
            WriteCsv(
                workspacePath,
                new[] { "CheckSchemaVersion", "CheckRunId", "Kind", "RelativePath", "Size", "Sha256" },
                workspaceFiles.Select(x => new[]
                {
                    CloneCheckBundleSchemaVersion, checkRunId, x.Kind, x.RelativePath,
                    x.Size.ToString(CultureInfo.InvariantCulture), x.Sha256
                }));
            WriteCloneCheckBundleMarker(
                Path.Combine(cloneDir, CloneCheckBundleFileName),
                checkRunId,
                compareDirectory,
                new CloneCheckTargetIdentity
                {
                    ProjectPath = Path.Combine(cloneDir, "self-test.ap21"),
                    ProjectName = "self-test",
                    ProjectVersion = "21",
                    ProjectObjectId = string.Empty,
                    ProjectObjectIdStatus = "unavailable",
                    SoftwarePaths = new List<string> { "PLC" }
                },
                Path.Combine(cloneDir, CloneCheckBlockFileName),
                blockRows,
                groupPath,
                0,
                Path.Combine(cloneDir, CloneCheckSourceBlockerFileName),
                sourceBlockerRows,
                workspacePath,
                workspaceFiles.Count,
                summaryPath,
                "authoritative-complete");
        }

        private static void SelfTestCloneCheckBundleSafetyPolicyRevision(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "policy-revision");
            string compareDir = Path.Combine(cloneDir, "_compare", "current-policy");
            Directory.CreateDirectory(Path.Combine(compareDir, "_root"));
            WriteTextFile(Path.Combine(cloneDir, "_root", "1_A.scl"), "FUNCTION_BLOCK \"A\"\nEND_FUNCTION_BLOCK\n");
            WriteCsv(Path.Combine(cloneDir, CloneCheckBlockFileName), new[] { "CheckSchemaVersion", "CheckRunId" }, new string[0][]);
            WriteCsv(Path.Combine(cloneDir, CloneCheckSourceBlockerFileName), new[] { "CheckSchemaVersion", "CheckRunId" }, new string[0][]);
            string checkRunId = Guid.NewGuid().ToString("N");
            CompleteSelfTestCloneCheckBundle(cloneDir, compareDir, checkRunId, 0, 0);
            CloneCheckBundleEvidence current = LoadAndValidateCloneCheckBundle(cloneDir);
            AssertEqual(CloneMatcherRevision, current.CloneMatcherRevision, "a current bundle must bind the matcher policy revision");
            AssertEqual(CloneWriteSafetyPolicyRevision, current.WriteSafetyPolicyRevision, "a current bundle must bind the write-safety policy revision");

            string markerPath = Path.Combine(cloneDir, CloneCheckBundleFileName);
            Dictionary<string, string> marker = ParseStrictFlatJsonObject(File.ReadAllText(markerPath, Encoding.UTF8), markerPath);
            marker["schemaVersion"] = "4";
            marker.Remove("toolVersion");
            marker.Remove("cloneMatcherRevision");
            marker.Remove("writeSafetyPolicyRevision");
            WriteFlatJsonObjectAtomically(markerPath, marker);
            bool oldSchemaRejected = false;
            try
            {
                LoadAndValidateCloneCheckBundle(cloneDir);
            }
            catch (InvalidDataException ex)
            {
                oldSchemaRejected = ex.Message.IndexOf("current safety policy", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            AssertTrue(oldSchemaRejected, "a hash-valid schema-4 marker from the previous matcher must be rejected with a rerun instruction");

            marker["schemaVersion"] = CloneCheckBundleSchemaVersion;
            marker["toolVersion"] = ProductVersion;
            marker["cloneMatcherRevision"] = "legacy-greedy-number-fallback";
            marker["writeSafetyPolicyRevision"] = CloneWriteSafetyPolicyRevision;
            WriteFlatJsonObjectAtomically(markerPath, marker);
            bool syncRejected = false;
            try
            {
                SyncProjectClone(cloneDir);
            }
            catch (InvalidDataException ex)
            {
                syncRejected = ex.Message.IndexOf("current safety policy", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            AssertTrue(syncRejected, "sync-clone must reject a bundle produced by an obsolete matcher revision");
            AssertTrue(!Directory.Exists(Path.Combine(cloneDir, "_sync-backups")), "policy revision rejection must happen before sync backup or mutation");
        }

        private static void SelfTestCloneAuthorizationRefreshTransaction(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "transaction");
            string compareDir = Path.Combine(cloneDir, "_compare", "current-transaction");
            Directory.CreateDirectory(Path.Combine(compareDir, "_root"));
            WriteTextFile(Path.Combine(cloneDir, "_root", "1_A.scl"), "FUNCTION_BLOCK \"A\"\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(Path.Combine(cloneDir, "plc-blocks.csv"), "manifest\n");
            WriteTextFile(Path.Combine(cloneDir, "block-groups.csv"), "groups\n");
            WriteTextFile(Path.Combine(cloneDir, "_metadata", "schema-version.txt"), CloneCheckBundleSchemaVersion + "\n");
            string checkRunId = Guid.NewGuid().ToString("N");
            WriteCsv(Path.Combine(cloneDir, CloneCheckBlockFileName), new[] { "CheckSchemaVersion", "CheckRunId" }, new string[0][]);
            WriteCsv(Path.Combine(cloneDir, CloneCheckSourceBlockerFileName), new[] { "CheckSchemaVersion", "CheckRunId" }, new string[0][]);
            CompleteSelfTestCloneCheckBundle(cloneDir, compareDir, checkRunId, 0, 0);

            CloneAuthorizationRefreshLease interrupted = BeginCloneAuthorizationRefresh(
                new Options { Command = "check-clone", OutDir = cloneDir });
            AssertTrue(!File.Exists(Path.Combine(cloneDir, CloneCheckBundleFileName)), "refresh attempt must revoke the old bundle before TIA resolution/attach");
            CompleteSelfTestCloneCheckBundle(cloneDir, compareDir, checkRunId, 0, 0);
            string markerPath = Path.Combine(cloneDir, CloneCheckBundleFileName);
            Dictionary<string, string> prepared = ParseStrictFlatJsonObject(File.ReadAllText(markerPath, Encoding.UTF8), markerPath);
            prepared["state"] = "reports-prepared";
            WriteFlatJsonObjectAtomically(markerPath, prepared);
            interrupted.Dispose();

            bool interruptedRejected = false;
            try
            {
                LoadAndValidateCloneCheckBundle(cloneDir);
            }
            catch (InvalidDataException ex)
            {
                interruptedRejected = ex.Message.IndexOf("refresh is incomplete", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            AssertTrue(interruptedRejected, "a crash after report preparation but before authoritative commit must leave the bundle unusable");

            File.Delete(Path.Combine(cloneDir, CloneCheckAttemptFileName));
            bool provisionalRejected = false;
            try
            {
                LoadAndValidateCloneCheckBundle(cloneDir);
            }
            catch (InvalidDataException ex)
            {
                provisionalRejected = ex.Message.IndexOf("not authoritative-complete", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            AssertTrue(provisionalRejected, "reports-prepared must never authorize a consumer even when no attempt sentinel is present");

            using (CloneAuthorizationRefreshLease completed = BeginCloneAuthorizationRefresh(
                new Options { Command = "check-clone", OutDir = cloneDir }))
            {
                CompleteSelfTestCloneCheckBundle(cloneDir, compareDir, checkRunId, 0, 0);
                prepared = ParseStrictFlatJsonObject(File.ReadAllText(markerPath, Encoding.UTF8), markerPath);
                prepared["state"] = "reports-prepared";
                WriteFlatJsonObjectAtomically(markerPath, prepared);
                completed.CompleteWithPlcBundle();
            }
            AssertTrue(!File.Exists(Path.Combine(cloneDir, CloneCheckAttemptFileName)), "successful authoritative commit must remove its attempt sentinel");
            AssertTrue(LoadAndValidateCloneCheckBundle(cloneDir) != null, "successful authoritative commit must publish a consumable bundle");

            string failedDir = Path.Combine(caseDir, "failed-command");
            string failedCompare = Path.Combine(failedDir, "_compare", "current-old");
            Directory.CreateDirectory(Path.Combine(failedCompare, "_root"));
            WriteTextFile(Path.Combine(failedDir, "_root", "1_A.scl"), "FUNCTION_BLOCK \"A\"\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(Path.Combine(failedDir, "plc-blocks.csv"), "manifest\n");
            WriteTextFile(Path.Combine(failedDir, "block-groups.csv"), "groups\n");
            WriteTextFile(Path.Combine(failedDir, "_metadata", "schema-version.txt"), CloneCheckBundleSchemaVersion + "\n");
            string failedRunId = Guid.NewGuid().ToString("N");
            WriteCsv(Path.Combine(failedDir, CloneCheckBlockFileName), new[] { "CheckSchemaVersion", "CheckRunId" }, new string[0][]);
            WriteCsv(Path.Combine(failedDir, CloneCheckSourceBlockerFileName), new[] { "CheckSchemaVersion", "CheckRunId" }, new string[0][]);
            CompleteSelfTestCloneCheckBundle(failedDir, failedCompare, failedRunId, 0, 0);

            string executable = Assembly.GetExecutingAssembly().Location;
            string fakeProject = Path.Combine(caseDir, "api-failure.ap21");
            WriteTextFile(fakeProject, "not a real TIA project\n");
            string missingApiDirectory = Path.Combine(caseDir, "missing-public-api");
            System.Diagnostics.ProcessStartInfo start = new System.Diagnostics.ProcessStartInfo(
                executable,
                "check-clone --project \"" + fakeProject + "\" --out \"" + failedDir
                    + "\" --api-dir \"" + missingApiDirectory + "\"");
            start.UseShellExecute = false;
            start.CreateNoWindow = true;
            start.RedirectStandardOutput = true;
            start.RedirectStandardError = true;
            using (System.Diagnostics.Process process = System.Diagnostics.Process.Start(start))
            {
                process.WaitForExit();
                AssertTrue(process.ExitCode != 0, "real check-clone command must fail for the injected API-resolution error");
            }
            AssertTrue(File.Exists(Path.Combine(failedDir, CloneCheckAttemptFileName)), "failed real command must leave durable refresh revocation evidence");
            AssertTrue(!File.Exists(Path.Combine(failedDir, CloneCheckBundleFileName)), "failed real command must not leave the old authorization marker");
        }

        private static void SelfTestCloneObjectIdBaselineCorrelation(string caseDir)
        {
            string replacementDir = Path.Combine(caseDir, "replacement");
            string replacementClonePath = Path.Combine(replacementDir, "clone", "20_Foo.scl");
            string replacementCurrentPath = Path.Combine(replacementDir, "current", "20_Foo.scl");
            WriteTextFile(replacementClonePath, "FUNCTION_BLOCK \"Foo\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(replacementCurrentPath, "FUNCTION_BLOCK \"Foo\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            CloneBlockRecord replacementClone = CreateSelfTestCloneIdentityRecord(
                "Foo", "20", "20_Foo.scl", replacementClonePath, true, "ID-1", "ok");
            CloneBlockRecord replacementCurrent = CreateSelfTestCloneIdentityRecord(
                "Foo", "20", "20_Foo.scl", replacementCurrentPath, false, "ID-2", "ok");
            List<CloneDiffRecord> replacementDiffs = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { replacementClone },
                new List<CloneBlockRecord> { replacementCurrent });
            AssertEqual("1", replacementDiffs.Count.ToString(CultureInfo.InvariantCulture), "same logical identity with different usable object IDs must remain one correlated blocking row");
            AssertEqual("object-replaced-or-mismatched", replacementDiffs[0].Status, "different usable object IDs must block as an engineering-object replacement");
            AssertEqual("ID-1", replacementDiffs[0].CloneTiaObjectId, "replacement evidence must retain the baseline object ID");
            AssertEqual("ID-2", replacementDiffs[0].CurrentTiaObjectId, "replacement evidence must retain the current object ID");
            AssertTrue(IsApplyCloneDirtyStatus(replacementDiffs[0].Status), "object replacement status must gate apply-clone");

            string reservationDir = Path.Combine(caseDir, "id-first-reservation");
            string reservationClonePath = Path.Combine(reservationDir, "clone", "20_Foo.scl");
            string trackedCurrentPath = Path.Combine(reservationDir, "current", "30_Foo_New.scl");
            string unrelatedCurrentPath = Path.Combine(reservationDir, "current", "20_Bar.scl");
            WriteTextFile(reservationClonePath, "FUNCTION_BLOCK \"Foo\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(trackedCurrentPath, "FUNCTION_BLOCK \"Foo_New\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(unrelatedCurrentPath, "FUNCTION_BLOCK \"Bar\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            CloneBlockRecord reservationClone = CreateSelfTestCloneIdentityRecord(
                "Foo", "20", "20_Foo.scl", reservationClonePath, true, "ID-1", "ok");
            CloneBlockRecord unrelatedCurrent = CreateSelfTestCloneIdentityRecord(
                "Bar", "20", "20_Bar.scl", unrelatedCurrentPath, false, "ID-2", "ok");
            CloneBlockRecord trackedCurrent = CreateSelfTestCloneIdentityRecord(
                "Foo_New", "30", "30_Foo_New.scl", trackedCurrentPath, false, "ID-1", "ok");
            List<CloneDiffRecord> reservationDiffs = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { reservationClone },
                new List<CloneBlockRecord> { unrelatedCurrent, trackedCurrent });
            CloneDiffRecord trackedDiff = reservationDiffs.Single(x => EqualsIgnoreCase(x.CurrentTiaObjectId, "ID-1"));
            CloneDiffRecord unrelatedDiff = reservationDiffs.Single(x => EqualsIgnoreCase(x.CurrentTiaObjectId, "ID-2"));
            AssertEqual("ID-1", trackedDiff.CloneTiaObjectId, "the durable ID pair must be reserved before an unrelated block can reuse the old number");
            AssertTrue(EqualsIgnoreCase(trackedDiff.Status, "moved-or-renamed") || EqualsIgnoreCase(trackedDiff.Status, "moved-or-renamed-and-changed"), "the tracked object must be represented as its rename and renumber transition");
            AssertEqual("added", unrelatedDiff.Status, "the unrelated object that reused the old number must remain a distinct addition");

            string ambiguousDir = Path.Combine(caseDir, "ambiguous-no-id");
            string ambiguousClonePath = Path.Combine(ambiguousDir, "clone", "20_Old.scl");
            string ambiguousCurrentPath = Path.Combine(ambiguousDir, "current", "30_New.scl");
            WriteTextFile(ambiguousClonePath, "FUNCTION_BLOCK \"Old\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(ambiguousCurrentPath, "FUNCTION_BLOCK \"New\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            CloneBlockRecord ambiguousClone = CreateSelfTestCloneIdentityRecord(
                "Old", "20", "20_Old.scl", ambiguousClonePath, true, string.Empty, "unavailable");
            CloneBlockRecord ambiguousCurrent = CreateSelfTestCloneIdentityRecord(
                "New", "30", "30_New.scl", ambiguousCurrentPath, false, string.Empty, "unavailable");
            List<CloneDiffRecord> ambiguousDiffs = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { ambiguousClone },
                new List<CloneBlockRecord> { ambiguousCurrent });
            CloneDiffRecord ambiguous = ambiguousDiffs.Single(x => EqualsIgnoreCase(x.Status, "ambiguous-rename-and-renumber"));
            AssertEqual("1", ambiguousDiffs.Count.ToString(CultureInfo.InvariantCulture), "a unique ambiguous candidate must not also produce an actionable removed row");
            AssertEqual("Old", ambiguous.CloneName, "the unique baseline candidate must be retained only as blocking evidence");
            AssertTrue(IsApplyCloneDirtyStatus(ambiguous.Status), "rename plus renumber without a durable ID must be a blocking status");
            AssertTrue(!ambiguousDiffs.Any(x => EqualsIgnoreCase(x.Status, "moved-or-renamed") || EqualsIgnoreCase(x.Status, "moved-or-renamed-and-changed")), "rename plus renumber without a durable ID must not be accepted as an automatic transition");

            string reusedDir = Path.Combine(caseDir, "ambiguous-no-id-reused-number");
            string reusedClonePath = Path.Combine(reusedDir, "clone", "20_Foo.scl");
            string reusedNumberPath = Path.Combine(reusedDir, "current", "20_Bar.scl");
            string renamedTrackedPath = Path.Combine(reusedDir, "current", "30_Foo_New.scl");
            WriteTextFile(reusedClonePath, "FUNCTION_BLOCK \"Foo\"\nBEGIN\n    #value := 1;\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(reusedNumberPath, "FUNCTION_BLOCK \"Bar\"\nBEGIN\n    #value := 999;\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(renamedTrackedPath, "FUNCTION_BLOCK \"Foo_New\"\nBEGIN\n    #value := 1;\nEND_FUNCTION_BLOCK\n");
            CloneBlockRecord reusedClone = CreateSelfTestCloneIdentityRecord(
                "Foo", "20", "20_Foo.scl", reusedClonePath, true, string.Empty, "unavailable");
            CloneBlockRecord unrelatedOldNumber = CreateSelfTestCloneIdentityRecord(
                "Bar", "20", "20_Bar.scl", reusedNumberPath, false, string.Empty, "unavailable");
            CloneBlockRecord renamedTracked = CreateSelfTestCloneIdentityRecord(
                "Foo_New", "30", "30_Foo_New.scl", renamedTrackedPath, false, string.Empty, "unavailable");
            List<CloneDiffRecord> reusedDiffs = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { reusedClone },
                new List<CloneBlockRecord> { unrelatedOldNumber, renamedTracked });
            AssertEqual("2", reusedDiffs.Count.ToString(CultureInfo.InvariantCulture), "both current vertices in a non-bijective no-ID component must remain visible as blocking evidence");
            AssertTrue(reusedDiffs.All(x => EqualsIgnoreCase(x.Status, "ambiguous-object-correlation")), "old-number reuse plus rename/renumber must produce only ambiguous-object-correlation rows");
            AssertTrue(reusedDiffs.All(x => IsApplyCloneDirtyStatus(x.Status)), "every row in the ambiguous no-ID component must gate apply and sync");
            AssertTrue(!reusedDiffs.Any(x => EqualsIgnoreCase(x.Status, "moved-or-renamed")
                || EqualsIgnoreCase(x.Status, "moved-or-renamed-and-changed")
                || EqualsIgnoreCase(x.Status, "added")
                || EqualsIgnoreCase(x.Status, "removed")), "ambiguous no-ID correlation must not leak rename, delete, or create actions into a destructive plan");
        }

        private static void SelfTestCloneAmbiguousVisualCorrelation(string caseDir)
        {
            string cloneAPath = Path.Combine(caseDir, "clone", "20_A.scl");
            string cloneBPath = Path.Combine(caseDir, "clone", "21_B.scl");
            string currentPath = Path.Combine(caseDir, "current", "20_Visual.scl");
            WriteTextFile(cloneAPath, "FUNCTION_BLOCK \"A\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(cloneBPath, "FUNCTION_BLOCK \"B\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(currentPath, "FUNCTION_BLOCK \"Visual\"\nBEGIN\nEND_FUNCTION_BLOCK\n");

            CloneBlockRecord cloneA = CreateSelfTestCloneIdentityRecord("A", "20", "20_A.scl", cloneAPath, true, string.Empty, "unavailable");
            CloneBlockRecord cloneB = CreateSelfTestCloneIdentityRecord("B", "21", "21_B.scl", cloneBPath, true, string.Empty, "unavailable");
            CloneBlockRecord visual = CreateSelfTestCloneIdentityRecord("Visual", "20", "20_Visual.scl", currentPath, false, string.Empty, "unavailable");
            visual.ProgrammingLanguage = "LAD";
            visual.ExportStatus = "unsupported-language";
            visual.ExportMessage = "LAD source export is unavailable.";

            List<CloneDiffRecord> diffs = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { cloneA, cloneB },
                new List<CloneBlockRecord> { visual });
            AssertEqual("1", diffs.Count.ToString(CultureInfo.InvariantCulture), "all tracked candidates must be reserved by the ambiguous visual component");
            AssertEqual("ambiguous-object-correlation", diffs[0].Status, "correlation ambiguity must take priority over unsupported-language classification");
            AssertTrue(diffs[0].Message.IndexOf("source export", StringComparison.OrdinalIgnoreCase) >= 0, "ambiguity evidence must retain the unsupported-source detail");
            AssertTrue(!diffs.Any(x => EqualsIgnoreCase(x.Status, "removed")), "ambiguous visual candidates must not leak delete rows");
            AssertTrue(IsApplyCloneDirtyStatus(diffs[0].Status), "ambiguous visual correlation must block apply and sync before staging");

            string reportPath = Path.Combine(caseDir, "clone-check-source-blockers.csv");
            WriteCloneCheckSourceBlockerReport(reportPath, diffs);
            List<Dictionary<string, string>> reportRows = ReadCsv(reportPath);
            AssertEqual("1", reportRows.Count.ToString(CultureInfo.InvariantCulture), "ambiguous visual correlation must appear in the dedicated blocker report");
            AssertEqual("error", GetCsvValue(reportRows[0], "Severity"), "ambiguous visual correlation must be Severity=error");
        }

        private static void SelfTestCloneStrongNoIdShadowCorrelation(string caseDir)
        {
            string clonePath = Path.Combine(caseDir, "clone", "20_Foo.scl");
            string replacementPath = Path.Combine(caseDir, "current", "20_Foo.scl");
            string movedPath = Path.Combine(caseDir, "current", "30_Foo_New.scl");
            WriteTextFile(clonePath, "FUNCTION_BLOCK \"Foo\"\nBEGIN\n #value := 1;\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(replacementPath, "FUNCTION_BLOCK \"Foo\"\nBEGIN\n #value := 999;\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(movedPath, "FUNCTION_BLOCK \"Foo_New\"\nBEGIN\n #value := 1;\nEND_FUNCTION_BLOCK\n");

            CloneBlockRecord clone = CreateSelfTestCloneIdentityRecord("Foo", "20", "20_Foo.scl", clonePath, true, string.Empty, "unavailable");
            CloneBlockRecord replacement = CreateSelfTestCloneIdentityRecord("Foo", "20", "20_Foo.scl", replacementPath, false, string.Empty, "unavailable");
            CloneBlockRecord moved = CreateSelfTestCloneIdentityRecord("Foo_New", "30", "30_Foo_New.scl", movedPath, false, string.Empty, "unavailable");
            List<CloneDiffRecord> diffs = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { clone },
                new List<CloneBlockRecord> { replacement, moved });

            AssertEqual("2", diffs.Count.ToString(CultureInfo.InvariantCulture), "replacement and source-equivalent moved candidate must remain visible");
            AssertTrue(diffs.All(x => EqualsIgnoreCase(x.Status, "ambiguous-object-correlation")), "a strong no-ID replacement must not bypass the global weak graph");
            AssertTrue(!diffs.Any(x => EqualsIgnoreCase(x.Status, "changed")
                || EqualsIgnoreCase(x.Status, "moved-or-renamed")
                || EqualsIgnoreCase(x.Status, "removed")), "ambiguous shadow correlation must not authorize update, rename, or delete");
        }

        private static void SelfTestCloneStrongNoIdShadowLongHeader(string caseDir)
        {
            string clonePath = Path.Combine(caseDir, "clone", "20_Foo.scl");
            string replacementPath = Path.Combine(caseDir, "current", "20_Foo.scl");
            string movedPath = Path.Combine(caseDir, "current", "30_Foo_New.scl");
            string header = string.Join("\n", Enumerable.Range(1, 25).Select(i => "// header " + i.ToString(CultureInfo.InvariantCulture)).ToArray()) + "\n"
                + "(* nested (* block *) comment *)\n{ S7_Optimized_Access := 'TRUE' }\n";
            WriteTextFile(clonePath, header + "FUNCTION_BLOCK \"Foo\"\nBEGIN\n #value := 1;\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(replacementPath, header + "FUNCTION_BLOCK \"Foo\"\nBEGIN\n #value := 999;\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(movedPath, header + "FUNCTION_BLOCK \"Foo_New\"\nBEGIN\n #value := 1;\nEND_FUNCTION_BLOCK\n");

            AssertEqual("Foo", TryReadBlockNameFromSource(clonePath), "declaration scanner must cross an arbitrary multi-line comment/attribute header");
            AssertEqual("Siemens.Engineering.SW.Blocks.FB", InferBlockTypeNameFromSourceFile(clonePath, "SCL"), "name/type inference must share the unbounded declaration scanner");
            CloneBlockRecord clone = CreateSelfTestCloneIdentityRecord("Foo", "20", "20_Foo.scl", clonePath, true, string.Empty, "unavailable");
            CloneBlockRecord replacement = CreateSelfTestCloneIdentityRecord("Foo", "20", "20_Foo.scl", replacementPath, false, string.Empty, "unavailable");
            CloneBlockRecord moved = CreateSelfTestCloneIdentityRecord("Foo_New", "30", "30_Foo_New.scl", movedPath, false, string.Empty, "unavailable");
            List<CloneDiffRecord> diffs = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { clone },
                new List<CloneBlockRecord> { replacement, moved });
            AssertEqual("2", diffs.Count.ToString(CultureInfo.InvariantCulture), "long-header replacement and moved original must remain in one visible component");
            AssertTrue(diffs.All(x => EqualsIgnoreCase(x.Status, "ambiguous-object-correlation")), "long headers must not bypass strong no-ID shadow ambiguity");
            AssertTrue(!diffs.Any(x => EqualsIgnoreCase(x.Status, "removed")
                || EqualsIgnoreCase(x.Status, "changed")
                || EqualsIgnoreCase(x.Status, "moved-or-renamed")), "long-header shadow state must authorize no DeleteBlock or UpdateSource");
        }

        private static void SelfTestCloneObjectIdContinuityUnproven(string caseDir)
        {
            string clonePath = Path.Combine(caseDir, "clone", "20_Foo.scl");
            string currentPath = Path.Combine(caseDir, "current", "20_Foo.scl");
            WriteTextFile(clonePath, "FUNCTION_BLOCK \"Foo\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(currentPath, "FUNCTION_BLOCK \"Foo\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            CloneBlockRecord clone = CreateSelfTestCloneIdentityRecord("Foo", "20", "20_Foo.scl", clonePath, true, "ID-1", "ok");
            CloneBlockRecord current = CreateSelfTestCloneIdentityRecord("Foo", "20", "20_Foo.scl", currentPath, false, string.Empty, "unavailable");

            CloneDiffRecord diff = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { clone },
                new List<CloneBlockRecord> { current }).Single();
            AssertEqual("object-id-continuity-unproven", diff.Status, "usable baseline ID plus unavailable current ID must never become unchanged");
            AssertEqual("ID-1", diff.CloneTiaObjectId, "the durable baseline ID must remain in evidence");
            AssertTrue(IsApplyCloneDirtyStatus(diff.Status), "unproven durable ID continuity must block apply");
            bool syncRejected = false;
            try
            {
                EnsureSyncCloneRowsSafe(new List<Dictionary<string, string>>
                {
                    new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase) { { "Status", diff.Status }, { "Name", "Foo" } }
                });
            }
            catch (InvalidOperationException)
            {
                syncRejected = true;
            }
            AssertTrue(syncRejected, "sync must not overwrite the manifest and erase a prior durable ID");
        }

        private static void SelfTestCloneExplicitNewExcludedFromWeakGraph(string caseDir)
        {
            string clonePath = Path.Combine(caseDir, "clone", "20_New.scl");
            string currentPath = Path.Combine(caseDir, "current", "99_Existing.scl");
            WriteTextFile(clonePath, "FUNCTION_BLOCK \"New\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(currentPath, "FUNCTION_BLOCK \"Existing\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            CloneBlockRecord explicitNew = CreateSelfTestCloneIdentityRecord("New", "20", "20_New.scl", clonePath, true, string.Empty, "unavailable");
            explicitNew.Provenance = "explicit-new-local-source";
            CloneBlockRecord existing = CreateSelfTestCloneIdentityRecord("Existing", "99", "99_Existing.scl", currentPath, false, string.Empty, "unavailable");

            List<CloneDiffRecord> diffs = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { explicitNew },
                new List<CloneBlockRecord> { existing });
            AssertTrue(!diffs.Any(x => IsCloneCorrelationAmbiguityStatus(x.Status)), "explicit-new sources must not enter the weak rename/renumber graph");
            AssertTrue(diffs.Any(x => EqualsIgnoreCase(x.Status, "added") && EqualsIgnoreCase(x.CurrentName, "Existing")), "unrelated current block must remain a distinct addition");
            AssertTrue(diffs.Any(x => EqualsIgnoreCase(x.Status, "removed") && EqualsIgnoreCase(x.CloneName, "New")), "explicit-new source must remain a distinct create candidate");
        }

        private static CloneBlockRecord CreateSelfTestCloneIdentityRecord(
            string name,
            string number,
            string relativePath,
            string sourcePath,
            bool cloneSide,
            string objectId,
            string objectIdStatus)
        {
            return new CloneBlockRecord
            {
                SoftwarePath = "PLC",
                GroupPath = string.Empty,
                GroupPathDisplay = string.Empty,
                Name = name,
                Number = number,
                AutoNumber = "False",
                NumberMode = "Manual",
                NumberSpace = "FB",
                ProgrammingLanguage = "SCL",
                BlockType = "FB",
                TypeName = "Siemens.Engineering.SW.Blocks.FB",
                RelativePath = relativePath,
                ClonePath = cloneSide ? sourcePath : string.Empty,
                CurrentPath = cloneSide ? string.Empty : sourcePath,
                ExportStatus = "ok",
                SourceSha256 = ComputeFileSha256(sourcePath),
                NormalizedSourceSha256 = ComputeNormalizedTextSha256(sourcePath),
                TiaObjectId = objectId,
                TiaObjectIdStatus = objectIdStatus,
                Provenance = cloneSide ? "tracked-baseline" : string.Empty
            };
        }

        private static void SelfTestCloneAuthorizationWithoutPlc(string caseDir)
        {
            InventorySnapshot emptySnapshot = new InventorySnapshot();
            HmiInventorySnapshot emptyHmiSnapshot = new HmiInventorySnapshot();
            HmiInventorySnapshot hmiOnlySnapshot = new HmiInventorySnapshot();
            hmiOnlySnapshot.Targets.Add(new HmiTargetRecord
            {
                TargetPath = "HMI_1",
                Name = "HMI_1",
                TypeName = "SelfTest.HmiTarget",
                Object = new object()
            });

            string hmiOnlyDir = Path.Combine(caseDir, "hmi-only");
            using (CloneAuthorizationRefreshLease initRefresh = BeginCloneAuthorizationRefresh(
                new Options { Command = "init-workspace", OutDir = hmiOnlyDir }))
            {
                bool preparedPlcAuthorization = InitializeWorkspaceLocked(
                    emptySnapshot,
                    hmiOnlySnapshot,
                    hmiOnlyDir,
                    new Options { Command = "init-workspace", OutDir = hmiOnlyDir, Force = false });
                AssertTrue(!preparedPlcAuthorization, "HMI-only init-workspace must explicitly report that no PLC authorization was prepared");
                initRefresh.CompleteWithoutPlcAuthorization();
            }
            AssertTrue(File.ReadAllText(Path.Combine(hmiOnlyDir, "workspace-init-summary.txt"), Encoding.UTF8).IndexOf("ReadyHmiOnly", StringComparison.OrdinalIgnoreCase) >= 0, "HMI-only init-workspace must retain its ReadyHmiOnly verdict");
            AssertTrue(!File.Exists(Path.Combine(hmiOnlyDir, CloneCheckAttemptFileName)), "successful HMI-only init-workspace must remove its refresh attempt marker");
            AssertTrue(!File.Exists(Path.Combine(hmiOnlyDir, CloneCheckBundleFileName)), "successful HMI-only init-workspace must not create a PLC authorization bundle");

            using (CloneAuthorizationRefreshLease statusRefresh = BeginCloneAuthorizationRefresh(
                new Options { Command = "status", OutDir = hmiOnlyDir }))
            {
                bool preparedPlcAuthorization = WriteToolStatus(emptySnapshot, hmiOnlySnapshot, hmiOnlyDir);
                AssertTrue(!preparedPlcAuthorization, "HMI-only status must explicitly report that no PLC authorization was prepared");
                statusRefresh.CompleteWithoutPlcAuthorization();
            }
            AssertTrue(!File.Exists(Path.Combine(hmiOnlyDir, CloneCheckAttemptFileName)), "successful HMI-only status must remove its refresh attempt marker");
            AssertTrue(!File.Exists(Path.Combine(hmiOnlyDir, CloneCheckBundleFileName)), "successful HMI-only status must not retain a PLC authorization bundle");

            string existingDir = Path.Combine(caseDir, "existing-workspace");
            WriteTextFile(Path.Combine(existingDir, "_root", "sentinel.scl"), "FUNCTION_BLOCK \"Sentinel\"\nEND_FUNCTION_BLOCK\n");
            using (CloneAuthorizationRefreshLease existingRefresh = BeginCloneAuthorizationRefresh(
                new Options { Command = "init-workspace", OutDir = existingDir }))
            {
                bool preparedPlcAuthorization = InitializeWorkspaceLocked(
                    emptySnapshot,
                    emptyHmiSnapshot,
                    existingDir,
                    new Options { Command = "init-workspace", OutDir = existingDir, Force = false });
                AssertTrue(!preparedPlcAuthorization, "ExistingWorkspace must complete without claiming that a PLC bundle was prepared");
                existingRefresh.CompleteWithoutPlcAuthorization();
            }
            AssertTrue(File.ReadAllText(Path.Combine(existingDir, "workspace-init-summary.txt"), Encoding.UTF8).IndexOf("ExistingWorkspace", StringComparison.OrdinalIgnoreCase) >= 0, "existing workspace result must remain a successful diagnostic outcome");
            AssertTrue(!File.Exists(Path.Combine(existingDir, CloneCheckAttemptFileName)), "ExistingWorkspace completion must close the refresh attempt");
            AssertTrue(!File.Exists(Path.Combine(existingDir, CloneCheckBundleFileName)), "ExistingWorkspace completion must leave prior PLC authorization revoked");
        }

        private static void SelfTestStatusPlcFailureKeepsAuthorizationRevoked(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "status-failure");
            InventorySnapshot snapshot = CreateSelfTestApplySnapshot();
            CloneAuthorizationRefreshLease refresh = BeginCloneAuthorizationRefresh(
                new Options { Command = "status", OutDir = cloneDir });
            try
            {
                ToolStatusLayerRecord layer = RunPlcToolStatus(
                    snapshot,
                    cloneDir,
                    delegate
                    {
                        WriteTextFile(Path.Combine(cloneDir, CloneCheckBundleFileName), "{\"state\":\"reports-prepared\"}\n");
                        throw new IOException("injected PLC cleanup failure");
                    });
                AssertEqual("error", layer.Status, "PLC evidence failure must remain visible in tool-status diagnostics");
                AssertTrue(layer.Failure is IOException, "tool-status must retain the original PLC evidence exception");

                Exception surfaced = null;
                try
                {
                    ThrowIfPlcToolStatusFailed(layer);
                }
                catch (Exception ex)
                {
                    surfaced = ex;
                }
                AssertTrue(surfaced is InvalidOperationException, "the authoritative status command must fail after diagnostics are written");
                Exception finalFailure = AbortFailedCloneAuthorizationRefresh(refresh, surfaced);
                AssertTrue(object.ReferenceEquals(surfaced, finalFailure), "successful revocation cleanup must preserve the original command failure");
                AssertTrue(File.Exists(Path.Combine(cloneDir, CloneCheckAttemptFileName)), "failed status must retain durable refresh revocation evidence");
                AssertTrue(!File.Exists(Path.Combine(cloneDir, CloneCheckBundleFileName)), "failed status must remove a provisional PLC authorization marker");
            }
            finally
            {
                refresh.Dispose();
            }
        }

