        private static void SelfTestApplyPreStateCleanupLifecycle(string caseDir)
        {
            string successfulRoot = Path.Combine(caseDir, "successful-cleanup");
            string successfulExport = CreateOwnedApplyPreStateExportDirectory(successfulRoot);
            WriteTextFile(Path.Combine(successfulExport, "source.scl"), "FUNCTION_BLOCK \"A\"\nEND_FUNCTION_BLOCK\n");
            DeleteOwnedApplyPreStateExportStrict(successfulExport, successfulRoot);
            AssertTrue(!Directory.Exists(successfulExport), "successful apply pre-state cleanup must remove the owned authoritative export");

            string failedRoot = Path.Combine(caseDir, "failed-cleanup");
            string failedExport = CreateOwnedApplyPreStateExportDirectory(failedRoot);
            WriteTextFile(Path.Combine(failedExport, "source.scl"), "FUNCTION_BLOCK \"B\"\nEND_FUNCTION_BLOCK\n");
            bool cleanupFailed = false;
            try
            {
                DeleteOwnedApplyPreStateExportStrict(
                    failedExport,
                    failedRoot,
                    delegate(string ignored) { throw new IOException("injected pre-state cleanup failure"); });
            }
            catch (IOException ex)
            {
                cleanupFailed = ex.Message.IndexOf("quarantined", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            AssertTrue(cleanupFailed, "failed apply pre-state cleanup must be surfaced as a command failure");
            AssertTrue(!Directory.Exists(failedExport), "failed cleanup must move the owned export away from the active _preflight directory");
            string quarantineRoot = Path.Combine(failedRoot, "_preflight-quarantine");
            string[] quarantined = Directory.GetDirectories(quarantineRoot);
            AssertEqual("1", quarantined.Length.ToString(CultureInfo.InvariantCulture), "failed pre-state cleanup must retain exactly one quarantine artifact");
            AssertTrue(File.Exists(Path.Combine(quarantined[0], "cleanup-failure.txt")), "quarantined pre-state evidence must contain a cleanup audit");

            string beforeWriteRoot = Path.Combine(caseDir, "cleanup-before-write");
            string beforeWriteExport = CreateOwnedApplyPreStateExportDirectory(beforeWriteRoot);
            WriteTextFile(Path.Combine(beforeWriteExport, "source.scl"), "FUNCTION_BLOCK \"C\"\nEND_FUNCTION_BLOCK\n");
            bool tiaWriteInvoked = false;
            bool beforeWriteCleanupBlocked = false;
            try
            {
                CompleteApplyPreStateCleanupBeforeWrite(
                    ref beforeWriteExport,
                    beforeWriteRoot,
                    delegate(string ignored) { throw new IOException("injected cleanup failure before write"); });
                tiaWriteInvoked = true;
            }
            catch (IOException ex)
            {
                beforeWriteCleanupBlocked = ex.Message.IndexOf("quarantined", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            AssertTrue(beforeWriteCleanupBlocked, "strict pre-state cleanup failure must be surfaced at the before-write boundary");
            AssertTrue(!tiaWriteInvoked, "a TIA write callback must remain unreachable when pre-state cleanup fails");

            string orderedRoot = Path.Combine(caseDir, "cleanup-order");
            string orderedExport = CreateOwnedApplyPreStateExportDirectory(orderedRoot);
            WriteTextFile(Path.Combine(orderedExport, "source.scl"), "FUNCTION_BLOCK \"D\"\nEND_FUNCTION_BLOCK\n");
            List<string> lifecycle = new List<string>();
            CompleteApplyPreStateCleanupBeforeWrite(
                ref orderedExport,
                orderedRoot,
                delegate(string candidate)
                {
                    lifecycle.Add("cleanup");
                    Directory.Delete(candidate, true);
                });
            lifecycle.Add("tia-write");
            lifecycle.Add("save-and-publish");
            AssertEqual("cleanup,tia-write,save-and-publish", string.Join(",", lifecycle.ToArray()), "strict cleanup must complete before the first write and cannot run after committed success");
            AssertTrue(string.IsNullOrWhiteSpace(orderedExport), "successful before-write cleanup must clear the retained export path so outer failure handling cannot repeat it");
        }

        private static void SelfTestCloneCheckBundleInterruptedPublication(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string compareDir = Path.Combine(cloneDir, "_compare", "current-interrupted");
            string clonePath = Path.Combine(rootDir, "20_FooBlock.scl");
            WriteTextFile(clonePath, "FUNCTION \"FooBlock\"\nEND_FUNCTION_BLOCK\n");
            Directory.CreateDirectory(Path.Combine(compareDir, "_root"));
            string checkRunId = Guid.NewGuid().ToString("N");

            WriteCsv(
                Path.Combine(cloneDir, CloneCheckBlockFileName),
                new[] { "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Status", "Name", "NumberSpace", "Number", "CloneSoftwarePath", "CloneName", "CloneNumberSpace", "CloneNumber", "ClonePath", "CloneProvenance" },
                new[]
                {
                    new[] { CloneCheckBundleSchemaVersion, checkRunId, "PLC", "removed", "FooBlock", "FC", "20", "PLC", "FooBlock", "FC", "20", clonePath, "tracked-baseline" }
                });

            bool missingMarkerRejected = false;
            try
            {
                SyncProjectClone(cloneDir);
            }
            catch (InvalidDataException)
            {
                missingMarkerRejected = true;
            }

            AssertTrue(missingMarkerRejected, "an interrupted publication with only a new main report (even one containing only removed) must be rejected");
            AssertTrue(File.Exists(clonePath), "missing bundle marker must be rejected before a removed clone source is mutated");
            AssertTrue(!Directory.Exists(Path.Combine(cloneDir, "_sync-backups")), "missing bundle marker must be rejected before backup creation");

            WriteCsv(
                Path.Combine(cloneDir, CloneCheckSourceBlockerFileName),
                new[] { "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Severity", "Status", "Name", "NumberSpace", "Number" },
                new string[0][]);
            CompleteSelfTestCloneCheckBundle(cloneDir, compareDir, checkRunId, 1, 0);
            File.Delete(Path.Combine(cloneDir, CloneCheckSourceBlockerFileName));

            bool missingDedicatedRejected = false;
            try
            {
                SyncProjectClone(cloneDir);
            }
            catch (InvalidDataException)
            {
                missingDedicatedRejected = true;
            }

            AssertTrue(missingDedicatedRejected, "a committed bundle with a missing dedicated source-blocker report must fail closed");
            AssertTrue(File.Exists(clonePath), "missing dedicated report must be rejected before clone mutation");

            WriteCsv(
                Path.Combine(cloneDir, CloneCheckSourceBlockerFileName),
                new[] { "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Severity", "Status", "Name", "NumberSpace", "Number" },
                new string[0][]);
            CompleteSelfTestCloneCheckBundle(cloneDir, compareDir, checkRunId, 1, 0);
            WriteTextFile(Path.Combine(cloneDir, CloneCheckSourceBlockerFileName), "tampered after marker\n");

            bool mismatchedBundleRejected = false;
            try
            {
                SyncProjectClone(cloneDir);
            }
            catch (InvalidDataException)
            {
                mismatchedBundleRejected = true;
            }

            AssertTrue(mismatchedBundleRejected, "a report changed after marker publication must be rejected by hash validation");
            AssertTrue(File.Exists(clonePath), "mismatched report bundle must be rejected before clone mutation");

            string conflictingCurrentPath = Path.Combine(compareDir, "_root", "20_FooBlock.scl");
            WriteTextFile(conflictingCurrentPath, "FUNCTION \"FooBlock\" : Void\nEND_FUNCTION\n");
            checkRunId = Guid.NewGuid().ToString("N");
            WriteCsv(
                Path.Combine(cloneDir, CloneCheckBlockFileName),
                new[]
                {
                    "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Status", "Name", "NumberSpace", "Number",
                    "CloneSoftwarePath", "CloneName", "CloneNumberSpace", "CloneNumber", "CloneRelativePath", "ClonePath", "CloneProvenance",
                    "CurrentSoftwarePath", "CurrentName", "CurrentNumberSpace", "CurrentNumber", "CurrentRelativePath", "CurrentPath"
                },
                new[]
                {
                    new[] { CloneCheckBundleSchemaVersion, checkRunId, "PLC", "added", "FooBlock", "FC", "20", string.Empty, string.Empty, string.Empty, string.Empty, string.Empty, clonePath, string.Empty, "PLC", "FooBlock", "FC", "20", "20_FooBlock.scl", conflictingCurrentPath },
                    new[] { CloneCheckBundleSchemaVersion, checkRunId, string.Empty, "removed", "FooBlock", "FC", "20", string.Empty, "FooBlock", "FC", "20", "20_FooBlock.scl", clonePath, "unknown-orphaned", string.Empty, string.Empty, string.Empty, string.Empty, string.Empty, string.Empty }
                });
            WriteCsv(
                Path.Combine(cloneDir, CloneCheckSourceBlockerFileName),
                new[] { "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Severity", "Status", "Name", "NumberSpace", "Number" },
                new string[0][]);
            CompleteSelfTestCloneCheckBundle(cloneDir, compareDir, checkRunId, 2, 0);

            bool conflictingPairRejected = false;
            try
            {
                SyncProjectClone(cloneDir);
            }
            catch (InvalidDataException)
            {
                conflictingPairRejected = true;
            }

            AssertTrue(conflictingPairRejected, "an unscoped removed source paired with the same scoped added block must fail closed");
            AssertTrue(File.Exists(clonePath), "conflicting added/removed plan must be rejected before sync mutation");

            checkRunId = Guid.NewGuid().ToString("N");
            WriteCsv(
                Path.Combine(cloneDir, CloneCheckBlockFileName),
                new[]
                {
                    "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Status", "Name", "NumberSpace", "Number",
                    "CloneSoftwarePath", "CloneName", "CloneNumberSpace", "CloneNumber", "CloneRelativePath", "ClonePath", "CloneProvenance",
                    "CurrentSoftwarePath", "CurrentName", "CurrentNumberSpace", "CurrentNumber", "CurrentRelativePath", "CurrentPath"
                },
                new[]
                {
                    new[] { CloneCheckBundleSchemaVersion, checkRunId, "PLC_1", "added", "Live_A", "FC", "20", string.Empty, string.Empty, string.Empty, string.Empty, string.Empty, clonePath, string.Empty, "PLC_1", "Live_A", "FC", "20", "20_FooBlock.scl", conflictingCurrentPath },
                    new[] { CloneCheckBundleSchemaVersion, checkRunId, "PLC_2", "removed", "Old_B", "FC", "99", "PLC_2", "Old_B", "FC", "99", "20_FooBlock.scl", clonePath, "tracked-baseline", string.Empty, string.Empty, string.Empty, string.Empty, string.Empty, string.Empty }
                });
            WriteCsv(
                Path.Combine(cloneDir, CloneCheckSourceBlockerFileName),
                new[] { "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Severity", "Status", "Name", "NumberSpace", "Number" },
                new string[0][]);
            CompleteSelfTestCloneCheckBundle(cloneDir, compareDir, checkRunId, 2, 0);

            bool crossSoftwarePathCollisionRejected = false;
            try
            {
                SyncProjectClone(cloneDir);
            }
            catch (InvalidDataException)
            {
                crossSoftwarePathCollisionRejected = true;
            }

            AssertTrue(crossSoftwarePathCollisionRejected, "an added and removed row that share one physical _root path must fail closed even across different SoftwarePath values");
            AssertTrue(File.Exists(clonePath), "cross-software physical path collision must be rejected before sync mutation");

            string reinitWorkspace = Path.Combine(caseDir, "REINIT_WORKSPACE");
            string staleStagingFile = Path.Combine(reinitWorkspace, "_check-publish", "run-stale", "staged.tmp");
            string staleManifestStagingFile = Path.Combine(reinitWorkspace, "_manifest-publish", "run-stale", "staged.tmp");
            string staleSyncStagingFile = Path.Combine(reinitWorkspace, "_sync-staging", "run-stale", "staged.tmp");
            WriteTextFile(staleStagingFile, "interrupted staging\n");
            WriteTextFile(staleManifestStagingFile, "interrupted manifest staging\n");
            WriteTextFile(staleSyncStagingFile, "interrupted sync staging\n");
            AssertTrue(IsWorkspaceGeneratedArtifactName("_check-publish"), "check-clone staging parent must be classified as a generated workspace artifact");
            AssertTrue(IsWorkspaceGeneratedArtifactName("_manifest-publish"), "manifest staging parent must be classified as a generated workspace artifact");
            AssertTrue(IsWorkspaceGeneratedArtifactName("_sync-staging"), "sync staging parent must be classified as a generated workspace artifact");
            string initBackup = BackupWorkspaceGeneratedArtifacts(reinitWorkspace);
            AssertTrue(!Directory.Exists(Path.Combine(reinitWorkspace, "_check-publish")), "init-workspace backup must remove stale check-clone staging from the active workspace");
            AssertTrue(!Directory.Exists(Path.Combine(reinitWorkspace, "_manifest-publish")), "init-workspace backup must remove stale manifest staging from the active workspace");
            AssertTrue(!Directory.Exists(Path.Combine(reinitWorkspace, "_sync-staging")), "init-workspace backup must remove stale sync staging from the active workspace");
            AssertTrue(File.Exists(Path.Combine(initBackup, "_check-publish", "run-stale", "staged.tmp")), "init-workspace backup must preserve stale check-clone staging for recovery");
            AssertTrue(File.Exists(Path.Combine(initBackup, "_manifest-publish", "run-stale", "staged.tmp")), "init-workspace backup must preserve stale manifest staging for recovery");
            AssertTrue(File.Exists(Path.Combine(initBackup, "_sync-staging", "run-stale", "staged.tmp")), "init-workspace backup must preserve stale sync staging for recovery");
        }

        private static void SelfTestCloneSourceOriginProvenance(string caseDir)
        {
            string trackedCloneDir = Path.Combine(caseDir, "TRACKED_CLONE_PROJECT");
            string trackedRootDir = Path.Combine(trackedCloneDir, "_root");
            string missingTrackedPath = Path.Combine(trackedRootDir, "20_Widget_Old.scl");
            string neverTrackedVisualPath = Path.Combine(trackedRootDir, "1_Main.lad");
            Directory.CreateDirectory(trackedRootDir);
            WriteCsv(
                Path.Combine(trackedCloneDir, "plc-blocks.csv"),
                new[] { "SoftwarePath", "GroupPath", "Name", "Number", "NumberSpace", "ProgrammingLanguage", "BlockType", "TypeName", "FilePath", "Status", "SourceOrigin" },
                new[]
                {
                    new[] { "PLC", string.Empty, "Widget_Old", "20", "FC", "SCL", "FC", "Siemens.Engineering.SW.Blocks.FC", missingTrackedPath, "ok", "exported-source" },
                    new[] { "PLC", string.Empty, "Main", "1", "OB", "LAD", "OB", "Siemens.Engineering.SW.Blocks.OB", neverTrackedVisualPath, "unsupported-language", "inventory-only-unsupported" }
                });
            List<CloneBlockRecord> missingTracked = LoadCloneBlockManifest(trackedCloneDir, trackedRootDir);
            AssertTrue(missingTracked.Count == 1, "a manifest-tracked row must remain represented when its _root source is missing");
            AssertEqual("tracked-baseline", missingTracked[0].Provenance, "missing tracked source must retain tracked-baseline provenance");
            AssertTrue(!File.Exists(missingTracked[0].ClonePath), "tracked-source regression fixture must actually be missing");
            AssertTrue(!missingTracked.Any(x => EqualsIgnoreCase(x.Name, "Main")), "a missing unsupported-language inventory row must not claim tracked source provenance when no clone source was ever produced");

            CloneBlockRecord neverTrackedVisualCurrent = new CloneBlockRecord
            {
                SoftwarePath = "PLC",
                Name = "Main",
                Number = "1",
                NumberSpace = "OB",
                ProgrammingLanguage = "LAD",
                BlockType = "OB",
                TypeName = "Siemens.Engineering.SW.Blocks.OB",
                RelativePath = "1_Main.lad",
                ClonePath = neverTrackedVisualPath,
                ExportStatus = "unsupported-language",
            };
            List<CloneDiffRecord> neverTrackedVisualDiffs = BuildCloneBlockDiffs(
                missingTracked,
                new List<CloneBlockRecord> { neverTrackedVisualCurrent });
            AssertTrue(neverTrackedVisualDiffs.Count == 1 && EqualsIgnoreCase(neverTrackedVisualDiffs[0].Status, "source-blocked-current-only"), "a pre-existing unsupported-language block without source history must remain current-only");
            AssertTrue(BlockingSourceBlockedDiffCount(neverTrackedVisualDiffs) == 0, "a pre-existing unsupported-language block from inventory only must be informational");

            string trackedCurrentPath = Path.Combine(caseDir, "TRACKED_CURRENT", missingTracked[0].RelativePath);
            WriteTextFile(trackedCurrentPath, "FUNCTION \"Widget_Old\" : Void\nEND_FUNCTION\n");
            CloneBlockRecord trackedCurrent = new CloneBlockRecord
            {
                SoftwarePath = missingTracked[0].SoftwarePath,
                GroupPath = missingTracked[0].GroupPath,
                Name = missingTracked[0].Name,
                Number = missingTracked[0].Number,
                NumberSpace = missingTracked[0].NumberSpace,
                ProgrammingLanguage = missingTracked[0].ProgrammingLanguage,
                BlockType = missingTracked[0].BlockType,
                TypeName = missingTracked[0].TypeName,
                SourceTypeName = missingTracked[0].SourceTypeName,
                RelativePath = missingTracked[0].RelativePath,
                ClonePath = missingTracked[0].ClonePath,
                CurrentPath = trackedCurrentPath,
                ExportStatus = "ok",
            };
            List<CloneDiffRecord> cloneDeletionDiffs = BuildCloneBlockDiffs(
                missingTracked,
                new List<CloneBlockRecord> { trackedCurrent });
            AssertTrue(cloneDeletionDiffs.Count == 1 && EqualsIgnoreCase(cloneDeletionDiffs[0].Status, "added"), "a tracked missing source with an exportable live block must remain a clone-side deletion action");
            AssertTrue(!cloneDeletionDiffs.Any(x => EqualsIgnoreCase(x.Status, "changed")), "a tracked missing source must not be misclassified as changed");

            List<CloneDiffRecord> completedDeletionDiffs = BuildCloneBlockDiffs(
                missingTracked,
                new List<CloneBlockRecord>());
            AssertTrue(completedDeletionDiffs.Count == 0, "a missing tracked source with no remaining live block must be clean after deletion");

            CloneBlockRecord ambiguousVisualCurrent = new CloneBlockRecord
            {
                SoftwarePath = "PLC",
                Name = "Widget_Visual_Renamed",
                Number = "99",
                NumberSpace = "FC",
                ProgrammingLanguage = "LAD",
                BlockType = "FC",
                TypeName = "Siemens.Engineering.SW.Blocks.FC",
                RelativePath = "99_Widget_Visual_Renamed.lad",
                ClonePath = Path.Combine(trackedRootDir, "99_Widget_Visual_Renamed.lad"),
                ExportStatus = "unsupported-language",
            };
            List<CloneDiffRecord> missingTrackedVisualDiffs = BuildCloneBlockDiffs(
                missingTracked,
                new List<CloneBlockRecord> { ambiguousVisualCurrent });
            AssertTrue(missingTrackedVisualDiffs.Any(x => EqualsIgnoreCase(x.Status, "removed")), "missing tracked manifest evidence must remain present when an unmatched visual block could be the converted source");
            AssertTrue(BlockingSourceBlockedDiffCount(missingTrackedVisualDiffs) > 0, "missing tracked provenance must still block an ambiguous renamed and renumbered visual block");

            string unscopedLoosePath = Path.Combine(trackedRootDir, "30_Unscoped_New.scl");
            WriteTextFile(unscopedLoosePath, "FUNCTION \"Unscoped_New\" : Void\nEND_FUNCTION\n");
            List<CloneBlockRecord> mixedSoftwareRecords = LoadCloneBlockManifest(trackedCloneDir, trackedRootDir);
            CloneBlockRecord unscopedLoose = mixedSoftwareRecords.First(x => EqualsIgnoreCase(x.ClonePath, unscopedLoosePath));
            AssertEqual("unknown-orphaned", unscopedLoose.Provenance, "loose source without sidecar scope must remain unknown/orphaned");
            AssertEqual(string.Empty, unscopedLoose.SoftwarePath, "loose source must not inherit the first SoftwarePath from the manifest");

            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string sourcePath = Path.Combine(rootDir, "31_Widget_New.scl");
            WriteTextFile(sourcePath, "FUNCTION \"Widget_New\" : Void\nEND_FUNCTION\n");

            List<CloneBlockRecord> unknown = LoadCloneBlockManifest(cloneDir, rootDir);
            AssertTrue(unknown.Count == 1, "loose clone source should be discovered");
            AssertEqual("unknown-orphaned", unknown[0].Provenance, "a loose source without exact origin sidecar must fail closed as unknown/orphaned");
            AssertEqual(string.Empty, unknown[0].SoftwarePath, "unscoped loose source must overlap all software paths conservatively");

            string postApplyCurrentPath = Path.Combine(caseDir, "POST_APPLY_COMPARE", unknown[0].RelativePath);
            WriteTextFile(postApplyCurrentPath, "FUNCTION \"Widget_New\" : Void\nEND_FUNCTION\n");
            CloneBlockRecord scopedPostApply = new CloneBlockRecord
            {
                SoftwarePath = "PLC",
                GroupPath = unknown[0].GroupPath,
                Name = unknown[0].Name,
                Number = unknown[0].Number,
                NumberSpace = unknown[0].NumberSpace,
                ProgrammingLanguage = unknown[0].ProgrammingLanguage,
                BlockType = unknown[0].BlockType,
                TypeName = unknown[0].TypeName,
                SourceTypeName = unknown[0].SourceTypeName,
                RelativePath = unknown[0].RelativePath,
                ClonePath = unknown[0].ClonePath,
                CurrentPath = postApplyCurrentPath,
                ExportStatus = "ok",
            };
            List<CloneDiffRecord> postApplyDiffs = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { unknown[0] },
                new List<CloneBlockRecord> { scopedPostApply });
            AssertTrue(postApplyDiffs.Count == 1, "a uniquely matching post-apply export must bind to its unscoped loose source");
            AssertTrue(!postApplyDiffs.Any(x => EqualsIgnoreCase(x.Status, "added") || EqualsIgnoreCase(x.Status, "removed")), "a unique unscoped post-apply match must not become a false added/removed pair");
            AssertEqual(string.Empty, postApplyDiffs[0].CloneSoftwarePath, "unique relative matching must preserve unknown clone scope for later ambiguity checks");
            AssertEqual("PLC", postApplyDiffs[0].CurrentSoftwarePath, "post-apply match must retain the resolved live SoftwarePath separately");

            CloneBlockRecord secondScopedPostApply = new CloneBlockRecord
            {
                SoftwarePath = "PLC_2",
                GroupPath = scopedPostApply.GroupPath,
                Name = "Widget_Other",
                Number = "32",
                NumberSpace = scopedPostApply.NumberSpace,
                ProgrammingLanguage = scopedPostApply.ProgrammingLanguage,
                BlockType = scopedPostApply.BlockType,
                TypeName = scopedPostApply.TypeName,
                SourceTypeName = scopedPostApply.SourceTypeName,
                RelativePath = scopedPostApply.RelativePath,
                ClonePath = scopedPostApply.ClonePath,
                CurrentPath = scopedPostApply.CurrentPath,
                ExportStatus = "ok",
            };
            List<CloneDiffRecord> ambiguousPostApplyDiffs = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { unknown[0] },
                new List<CloneBlockRecord> { scopedPostApply, secondScopedPostApply });
            AssertTrue(ambiguousPostApplyDiffs.Count(x => EqualsIgnoreCase(x.Status, "removed")) == 1, "an unscoped loose source must remain unmatched when multiple live software scopes share its relative path");
            AssertTrue(ambiguousPostApplyDiffs.Count(x => EqualsIgnoreCase(x.Status, "added")) == 2, "ambiguous cross-software relative paths must remain visible for the fail-closed bundle gate");

            List<Dictionary<string, string>> orphanedIdentityChange = new List<Dictionary<string, string>>
            {
                SourceBlockerTestRow("removed", "FC", "31", "Widget_Old", unknown[0].Provenance, "PLC"),
                SourceBlockerTestRow("source-blocked-current-only", "FC", "99", "Widget_Renamed", string.Empty, "PLC"),
            };
            AssertTrue(SourceBlockerGateThrows("apply-clone", orphanedIdentityChange), "unknown/orphaned source plus renamed+renumbered visual block in the same software/number space must fail closed");

            WriteTextFile(sourcePath + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\"\n");
            AssertEqual("unknown-orphaned", LoadCloneBlockManifest(cloneDir, rootDir)[0].Provenance, "malformed sidecar must not grant explicit-new provenance");

            WriteTextFile(sourcePath + ".meta.json", "{\"metadata\":{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\"}}\n");
            AssertEqual("unknown-orphaned", LoadCloneBlockManifest(cloneDir, rootDir)[0].Provenance, "nested sidecar origin must not grant a flat metadata exemption");

            WriteTextFile(sourcePath + ".meta.json", "{\"source\\Origin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\"}\n");
            AssertEqual("unknown-orphaned", LoadCloneBlockManifest(cloneDir, rootDir)[0].Provenance, "invalid JSON escape in a trusted key must not grant explicit-new provenance");

            WriteTextFile(sourcePath + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\",\"flag\":TRUE}\n");
            AssertEqual("unknown-orphaned", LoadCloneBlockManifest(cloneDir, rootDir)[0].Provenance, "case-insensitive non-JSON literal must invalidate the entire provenance sidecar");

            WriteTextFile(sourcePath + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\",\"number\":01}\n");
            AssertEqual("unknown-orphaned", LoadCloneBlockManifest(cloneDir, rootDir)[0].Provenance, "non-JSON leading-zero number must invalidate the entire provenance sidecar");

            WriteTextFile(sourcePath + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\",\"extra\":1\u0661}\n");
            AssertEqual("unknown-orphaned", LoadCloneBlockManifest(cloneDir, rootDir)[0].Provenance, "Unicode decimal digits must not be accepted in a JSON number");

            WriteTextFile(sourcePath + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\u00A0\"softwarePath\":\"PLC\"}\n");
            AssertEqual("unknown-orphaned", LoadCloneBlockManifest(cloneDir, rootDir)[0].Provenance, "non-JSON Unicode whitespace must invalidate the entire provenance sidecar");

            WriteTextFile(sourcePath + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\"}\n");
            CloneBlockRecord originWithoutScope = LoadCloneBlockManifest(cloneDir, rootDir)[0];
            AssertEqual("unknown-orphaned", originWithoutScope.Provenance, "explicit origin without softwarePath must remain unknown/orphaned");
            AssertEqual(string.Empty, originWithoutScope.SoftwarePath, "origin without softwarePath must remain unscoped");

            WriteTextFile(sourcePath + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\"}\n");
            List<CloneBlockRecord> explicitNew = LoadCloneBlockManifest(cloneDir, rootDir);
            AssertTrue(explicitNew.Count == 1, "sidecar must not be scanned as a PLC source");
            AssertEqual("explicit-new-local-source", explicitNew[0].Provenance, "exact sourceOrigin opt-in must establish durable new-local provenance");
            AssertEqual("PLC", explicitNew[0].SoftwarePath, "sidecar softwarePath must scope a new local source");
        }

        private static void SelfTestApplyClonePostDeleteTransition(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string missingSource = Path.Combine(rootDir, "20_FB20.scl");
            Directory.CreateDirectory(rootDir);
            WriteCsv(
                Path.Combine(cloneDir, "plc-blocks.csv"),
                BlockManifestHeaders(),
                new[]
                {
                    new[]
                    {
                        "PLC", string.Empty, string.Empty, string.Empty, "FB20", "20", "False", "Manual", "FB",
                        "SCL", "FB", "Siemens.Engineering.SW.Blocks.FB", "Siemens.Engineering.SW.Blocks.FB",
                        string.Empty, string.Empty, string.Empty, string.Empty,
                        "Standard", "True", "False", string.Empty, "empty",
                        missingSource, string.Empty, string.Empty, "ok", "tracked before clone-side deletion", "exported-source"
                    }
                });

            List<CloneBlockRecord> tracked = LoadCloneBlockManifest(cloneDir, rootDir);
            string liveExportPath = Path.Combine(caseDir, "CURRENT", "20_FB20.scl");
            WriteTextFile(liveExportPath, "FUNCTION_BLOCK \"FB20\"\nEND_FUNCTION_BLOCK\n");
            CloneBlockRecord liveExportable = new CloneBlockRecord
            {
                SoftwarePath = "PLC", Name = "FB20", Number = "20", NumberSpace = "FB", ProgrammingLanguage = "SCL",
                BlockType = "FB", TypeName = "Siemens.Engineering.SW.Blocks.FB", RelativePath = "20_FB20.scl",
                ClonePath = missingSource, CurrentPath = liveExportPath, ExportStatus = "ok"
            };
            CloneBlockRecord unrelatedVisual = new CloneBlockRecord
            {
                SoftwarePath = "PLC", Name = "F_LAD", Number = "1", NumberSpace = "FB", ProgrammingLanguage = "F_LAD",
                BlockType = "FB", TypeName = "Siemens.Engineering.SW.Blocks.FB", RelativePath = "1_F_LAD.lad",
                ClonePath = Path.Combine(rootDir, "1_F_LAD.lad"), ExportStatus = "unsupported-language"
            };

            List<CloneDiffRecord> before = BuildCloneBlockDiffs(tracked, new List<CloneBlockRecord> { liveExportable, unrelatedVisual });
            AssertTrue(before.Any(x => EqualsIgnoreCase(x.Status, "added") && EqualsIgnoreCase(x.Name, "FB20")), "missing tracked FB20 source must plan DeleteBlock before the write");
            AssertTrue(BlockingSourceBlockedDiffCount(before) == 0, "unrelated current-only F_LAD must be informational before DeleteBlock");

            List<CloneDiffRecord> unsafeAfter = BuildCloneBlockDiffs(tracked, new List<CloneBlockRecord> { unrelatedVisual });
            AssertTrue(BlockingSourceBlockedDiffCount(unsafeAfter) > 0, "fixture must reproduce the old post-delete false blocker while stale manifest evidence remains");

            BlockRecord deleted = CreateSelfTestBlock("FB20", 20, "SCL", "Siemens.Engineering.SW.Blocks.FB");
            ApplyPlanItem deletePlan = CreateSelfTestDeletePlanItem(deleted);
            deletePlan.ConsumesManifestRow = true;
            deletePlan.ManifestSoftwarePath = tracked[0].SoftwarePath;
            deletePlan.ManifestGroupPath = tracked[0].GroupPath;
            deletePlan.ManifestName = tracked[0].Name;
            deletePlan.ManifestNumberSpace = tracked[0].NumberSpace;
            deletePlan.ManifestNumber = tracked[0].Number;
            deletePlan.ManifestFilePath = tracked[0].ClonePath;
            CommitCompletedApplyCloneDeletions(cloneDir, new List<ApplyPlanItem> { deletePlan });

            List<CloneBlockRecord> committed = LoadCloneBlockManifest(cloneDir, rootDir);
            List<CloneDiffRecord> safeAfter = BuildCloneBlockDiffs(committed, new List<CloneBlockRecord> { unrelatedVisual });
            AssertTrue(!safeAfter.Any(x => EqualsIgnoreCase(x.Status, "removed")), "completed DeleteBlock must consume its tracked manifest row");
            AssertTrue(BlockingSourceBlockedDiffCount(safeAfter) == 0, "post-delete check must remain accepted with an unrelated current-only F_LAD block");
        }

        private static void SelfTestCloneSourceOriginLifecycle(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string sourcePath = Path.Combine(rootDir, "31_Widget_New.scl");
            WriteTextFile(sourcePath, "FUNCTION \"Widget_New\" : Void\nEND_FUNCTION\n");
            WriteTextFile(sourcePath + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\",\"number\":\"31\",\"numberMode\":\"Manual\"}\n");

            List<CloneBlockRecord> pending = LoadCloneBlockManifest(cloneDir, rootDir);
            AssertEqual("explicit-new-local-source", pending[0].Provenance, "new local source must begin in pending provenance state");

            string differentCurrentPath = Path.Combine(caseDir, "DIFFERENT", "31_Widget_New.scl");
            WriteTextFile(differentCurrentPath, "FUNCTION \"Widget_New\" : Void\nBEGIN\n    #Different := TRUE;\nEND_FUNCTION\n");
            CloneBlockRecord differentCurrent = CreateSelfTestCurrentCloneRecord(pending[0], differentCurrentPath);
            int adoptedWithoutReceipt = PromoteMatchedExplicitNewSources(
                cloneDir,
                rootDir,
                pending,
                new List<CloneBlockRecord> { differentCurrent },
                new List<ExplicitNewPromotionReceipt>());
            AssertTrue(adoptedWithoutReceipt == 0, "a pre-existing same-identity block must not consume pending provenance without a successful CreateBlock receipt");
            AssertTrue(!File.Exists(Path.Combine(cloneDir, "plc-blocks.csv")), "metadata-only identity must not publish a tracked manifest row");
            AssertEqual("explicit-new-local-source", SidecarValue(LoadSidecarMetadata(sourcePath), "sourceOrigin"), "metadata-only identity must leave the one-shot sidecar unchanged");

            string preflightRoot = Path.Combine(caseDir, "PREFLIGHT_ROOT");
            ApplyPlanItem conflictingApply = CreateSelfTestApplyPlanItem(preflightRoot, "UpdateSource", "Widget_New", 31, "SCL", "Siemens.Engineering.SW.Blocks.FC", true, ".scl");
            conflictingApply.CloneProvenance = "explicit-new-local-source";
            ApplyPreflightResult conflictingPreflight = RunApplyClonePreflight(new List<ApplyPlanItem> { conflictingApply }, CreateSelfTestApplySnapshot(conflictingApply.Existing), preflightRoot, false);
            AssertTrue(conflictingPreflight.Issues.Any(x => EqualsIgnoreCase(x.Code, "EXPLICIT_NEW_ADOPTION_FORBIDDEN")), "apply must block adoption or overwrite of a pre-existing same-identity block");

            string currentPath = Path.Combine(caseDir, "CURRENT", "31_Widget_New.scl");
            WriteTextFile(currentPath, "  FUNCTION   \"Widget_New\"    :   Void\r\n\r\n    END_FUNCTION\r\n");
            AssertTrue(!EqualsIgnoreCase(ComputeNormalizedTextSha256(sourcePath), ComputeNormalizedTextSha256(currentPath)), "promotion fixture must contain a formatting-only normalized hash difference");
            AssertEqual(ComputeCanonicalSourceSha256(sourcePath), ComputeCanonicalSourceSha256(currentPath), "promotion fixture must remain canonically equivalent");
            CloneBlockRecord current = CreateSelfTestCurrentCloneRecord(pending[0], currentPath);
            ExplicitNewPromotionReceipt receipt = CreateSelfTestPromotionReceipt(pending[0], current, sourcePath, "check-self-test");
            int promoted = PromoteMatchedExplicitNewSources(
                cloneDir,
                rootDir,
                pending,
                new List<CloneBlockRecord> { current },
                new List<ExplicitNewPromotionReceipt> { receipt });
            AssertTrue(promoted == 1, "a successful CreateBlock receipt plus matching exported content must promote explicit-new provenance exactly once");
            AssertEqual("tracked-baseline", SidecarValue(LoadSidecarMetadata(sourcePath), "sourceOrigin"), "one-shot sidecar origin must be consumed after promotion");
            AssertEqual("31", SidecarValue(LoadSidecarMetadata(sourcePath), "number"), "promotion must persist the assigned live number in the tracked sidecar");
            AssertEqual("tracked-baseline", LoadCloneBlockManifest(cloneDir, rootDir)[0].Provenance, "promoted source must be represented by the tracked manifest");

            File.Delete(Path.Combine(cloneDir, "plc-blocks.csv"));
            CloneBlockRecord afterManifestLoss = LoadCloneBlockManifest(cloneDir, rootDir)[0];
            AssertEqual("unknown-orphaned", afterManifestLoss.Provenance, "manifest loss must not resurrect consumed explicit-new provenance");

            CloneBlockRecord renamedVisual = new CloneBlockRecord
            {
                SoftwarePath = "PLC", Name = "Widget_Renamed", Number = "99", NumberSpace = "FC", ProgrammingLanguage = "LAD",
                BlockType = "FC", TypeName = "Siemens.Engineering.SW.Blocks.FC", RelativePath = "99_Widget_Renamed.lad",
                ClonePath = Path.Combine(rootDir, "99_Widget_Renamed.lad"), ExportStatus = "unsupported-language"
            };
            List<CloneDiffRecord> laterConversion = BuildCloneBlockDiffs(
                new List<CloneBlockRecord> { afterManifestLoss },
                new List<CloneBlockRecord> { renamedVisual });
            AssertTrue(BlockingSourceBlockedDiffCount(laterConversion) > 0, "renamed+renumbered visual conversion must fail closed after promotion and later manifest loss");
        }

        private static void SelfTestApplyCloneDeletionManifestReceipts(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string trackedPath = Path.Combine(rootDir, "Group_A", "20_FB_Tracked.scl");
            Directory.CreateDirectory(rootDir);
            WriteCsv(
                Path.Combine(cloneDir, "plc-blocks.csv"),
                new[] { "SoftwarePath", "GroupPath", "Name", "Number", "NumberSpace", "ProgrammingLanguage", "TypeName", "FilePath", "Status", "SourceOrigin" },
                new[]
                {
                    new[] { "PLC", "Group_A", "FB_Tracked", "20", "FB", "SCL", "Siemens.Engineering.SW.Blocks.FB", trackedPath, "ok", "exported-source" }
                });

            BlockRecord renamed = CreateSelfTestBlock("FB_Renamed", 20, "SCL", "Siemens.Engineering.SW.Blocks.FB");
            renamed.GroupPath = "Group_B";
            renamed.GroupPathDisplay = "Group_B";
            BlockRecord liveOnly = CreateSelfTestBlock("FC_LiveOnly", 30, "SCL", "Siemens.Engineering.SW.Blocks.FC");
            InventorySnapshot snapshot = CreateSelfTestApplySnapshot(renamed, liveOnly);
            List<Dictionary<string, string>> rows = new List<Dictionary<string, string>>
            {
                new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                {
                    { "Status", "added" }, { "SoftwarePath", "PLC" },
                    { "CurrentSoftwarePath", "PLC" }, { "CurrentGroupPath", "Group_B" }, { "CurrentName", "FB_Renamed" },
                    { "CurrentNumberSpace", "FB" }, { "CurrentNumber", "20" }, { "CurrentProgrammingLanguage", "SCL" },
                    { "CurrentTypeName", "Siemens.Engineering.SW.Blocks.FB" }, { "CurrentNumberMode", "Manual" }, { "CurrentAutoNumber", "False" },
                    { "CloneSoftwarePath", "PLC" }, { "CloneGroupPath", "Group_A" }, { "CloneName", "FB_Tracked" },
                    { "CloneNumberSpace", "FB" }, { "CloneNumber", "20" }, { "ClonePath", trackedPath }, { "CloneProvenance", "tracked-baseline" }
                },
                new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                {
                    { "Status", "added" }, { "SoftwarePath", "PLC" },
                    { "CurrentSoftwarePath", "PLC" }, { "CurrentGroupPath", string.Empty }, { "CurrentName", "FC_LiveOnly" },
                    { "CurrentNumberSpace", "FC" }, { "CurrentNumber", "30" }, { "CurrentProgrammingLanguage", "SCL" },
                    { "CurrentTypeName", "Siemens.Engineering.SW.Blocks.FC" }, { "CurrentNumberMode", "Manual" }, { "CurrentAutoNumber", "False" }
                }
            };

            List<ApplyPlanItem> plan = BuildApplyClonePlan(rows, snapshot, rootDir);
            ApplyPlanItem trackedDelete = plan.Single(x => EqualsIgnoreCase(x.CurrentName, "FB_Renamed"));
            ApplyPlanItem liveOnlyDelete = plan.Single(x => EqualsIgnoreCase(x.CurrentName, "FC_LiveOnly"));
            AssertTrue(trackedDelete.ConsumesManifestRow, "renamed/moved tracked deletion must carry an immutable manifest-row receipt");
            AssertEqual("FB_Tracked", trackedDelete.ManifestName, "tracked deletion receipt must preserve the clone-side name rather than the renamed live name");
            AssertEqual("Group_A", trackedDelete.ManifestGroupPath, "tracked deletion receipt must preserve the clone-side group");
            AssertTrue(!liveOnlyDelete.ConsumesManifestRow, "a TIA-only block must be classified as DeleteLiveOnlyBlock and consume no manifest row");

            string manifestName = trackedDelete.ManifestName;
            trackedDelete.ManifestName = "wrong-preflight-identity";
            ApplyPreflightResult rejectedPreflight = RunApplyClonePreflight(plan, snapshot, rootDir, false);
            AssertTrue(rejectedPreflight.Issues.Any(x => EqualsIgnoreCase(x.Code, "DELETE_MANIFEST_RECEIPT_INVALID")), "a missing tracked manifest receipt must be rejected before TIA mutation");
            trackedDelete.ManifestName = manifestName;
            ApplyPreflightResult preflight = RunApplyClonePreflight(plan, snapshot, rootDir, false);
            AssertTrue(!preflight.Issues.Any(x => EqualsIgnoreCase(x.Code, "DELETE_MANIFEST_RECEIPT_INVALID")), "both deletion kinds must be fully validated before TIA mutation");
            CommitCompletedApplyCloneDeletions(cloneDir, plan);
            AssertTrue(ReadCsv(Path.Combine(cloneDir, "plc-blocks.csv")).Count == 0, "completed tracked deletion must consume exactly its original manifest row while live-only deletion consumes none");
        }

        private static void SelfTestCloneSourceOriginPromotionBatch(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "DUPLICATE", "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string sourceA = Path.Combine(rootDir, "31_Widget_A.scl");
            string sourceB = Path.Combine(rootDir, "31_Widget_B.scl");
            string sourceText = "FUNCTION \"Widget_Duplicate\" : Void\nEND_FUNCTION\n";
            WriteTextFile(sourceA, sourceText);
            WriteTextFile(sourceB, sourceText);
            WriteTextFile(sourceA + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\",\"number\":\"31\",\"numberMode\":\"Manual\"}\n");
            WriteTextFile(sourceB + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\",\"number\":\"31\",\"numberMode\":\"Manual\"}\n");
            List<CloneBlockRecord> pending = LoadCloneBlockManifest(cloneDir, rootDir);
            string currentPath = Path.Combine(caseDir, "DUPLICATE", "CURRENT", "31_Widget_Duplicate.scl");
            WriteTextFile(currentPath, sourceText);
            CloneBlockRecord current = CreateSelfTestCurrentCloneRecord(pending[0], currentPath);
            List<ExplicitNewPromotionReceipt> receipts = pending
                .Select(x => CreateSelfTestPromotionReceipt(x, current, x.ClonePath, "check-duplicate"))
                .ToList();
            bool duplicateRejected = false;
            try
            {
                PromoteMatchedExplicitNewSources(cloneDir, rootDir, pending, new List<CloneBlockRecord> { current }, receipts);
            }
            catch (InvalidDataException ex)
            {
                duplicateRejected = ex.Message.IndexOf("one-to-one", StringComparison.OrdinalIgnoreCase) >= 0;
            }

            AssertTrue(duplicateRejected, "duplicate target identities in one promotion batch must fail before sidecar or manifest mutation");
            AssertEqual("explicit-new-local-source", SidecarValue(LoadSidecarMetadata(sourceA), "sourceOrigin"), "duplicate rejection must preserve the first one-shot sidecar");
            AssertEqual("explicit-new-local-source", SidecarValue(LoadSidecarMetadata(sourceB), "sourceOrigin"), "duplicate rejection must preserve the second one-shot sidecar");
            AssertTrue(!File.Exists(Path.Combine(cloneDir, "plc-blocks.csv")), "duplicate rejection must not publish a manifest");

            string recoveryDir = Path.Combine(caseDir, "RECOVERY", "CLONE_PROJECT");
            string recoveryRoot = Path.Combine(recoveryDir, "_root");
            string recoverySource = Path.Combine(recoveryRoot, "41_Widget_Recovery.scl");
            WriteTextFile(recoverySource, "FUNCTION \"Widget_Recovery\" : Void\nEND_FUNCTION\n");
            WriteTextFile(recoverySource + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\",\"number\":\"41\",\"numberMode\":\"Manual\"}\n");
            CloneBlockRecord recoveryPending = LoadCloneBlockManifest(recoveryDir, recoveryRoot).Single();
            string recoveryCurrentPath = Path.Combine(caseDir, "RECOVERY", "CURRENT", "41_Widget_Recovery.scl");
            WriteTextFile(recoveryCurrentPath, File.ReadAllText(recoverySource, Encoding.UTF8));
            CloneBlockRecord recoveryCurrent = CreateSelfTestCurrentCloneRecord(recoveryPending, recoveryCurrentPath);
            string transactionDir = Path.Combine(recoveryDir, "_manifest-publish", "run-interrupted");
            string stagedManifest = Path.Combine(transactionDir, "plc-blocks.csv");
            string finalManifest = Path.Combine(recoveryDir, "plc-blocks.csv");
            WriteCsv(stagedManifest, BlockManifestHeaders(), new[] { BuildBlockManifestRowFromCloneRecord(recoveryCurrent, recoverySource, "recovered") });
            WriteCsv(
                Path.Combine(transactionDir, "provenance-promotions.csv"),
                new[] { "ReceiptId", "CheckRunId", "SourcePath", "SidecarPath", "SourceNormalizedSha256", "SourceCanonicalSha256", "SoftwarePath", "GroupPath", "Name", "NumberSpace", "Number", "ProgrammingLanguage", "LiveTiaObjectId", "LiveTiaObjectIdStatus" },
                new[]
                {
                    new[] { "receipt-recovery", "check-recovery", recoverySource, recoverySource + ".meta.json", ComputeNormalizedTextSha256(recoverySource), ComputeCanonicalSourceSha256(recoverySource), "PLC", string.Empty, "Widget_Recovery", "FC", "41", "SCL", "self-test-live-object", "available" }
                });
            WriteFlatJsonObjectAtomically(
                Path.Combine(transactionDir, "provenance-promotion.json"),
                new Dictionary<string, string>
                {
                    { "state", "ready" }, { "manifestPath", finalManifest }, { "manifestSha256", ComputeFileSha256(stagedManifest) },
                    { "journalSha256", ComputeFileSha256(Path.Combine(transactionDir, "provenance-promotions.csv")) }, { "promotionCount", "1" }
                });
            RecoverPendingProvenancePromotions(recoveryDir, recoveryRoot);
            AssertEqual("tracked-baseline", SidecarValue(LoadSidecarMetadata(recoverySource), "sourceOrigin"), "interrupted sidecar transition must be recoverable");
            AssertTrue(File.Exists(finalManifest), "interrupted promotion must recover and publish the prepared manifest");
            AssertTrue(!Directory.Exists(Path.Combine(recoveryDir, "_manifest-publish")), "completed promotion recovery must clean its staging root");

            string guardedInitDir = Path.Combine(caseDir, "GUARDED_INIT", "CLONE_PROJECT");
            string guardedInitRoot = Path.Combine(guardedInitDir, "_root");
            string guardedSourceA = Path.Combine(guardedInitRoot, "51_Widget_Guarded_A.scl");
            string guardedSourceB = Path.Combine(guardedInitRoot, "52_Widget_Guarded_B.scl");
            WriteTextFile(guardedSourceA, "FUNCTION \"Widget_Guarded_A\" : Void\nEND_FUNCTION\n");
            WriteTextFile(guardedSourceB, "FUNCTION \"Widget_Guarded_B\" : Void\nEND_FUNCTION\n");
            WriteTextFile(guardedSourceA + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\",\"number\":\"51\",\"numberMode\":\"Manual\"}\n");
            WriteTextFile(guardedSourceB + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\",\"number\":\"52\",\"numberMode\":\"Manual\"}\n");
            List<CloneBlockRecord> guardedPending = LoadCloneBlockManifest(guardedInitDir, guardedInitRoot)
                .OrderBy(x => x.Name, StringComparer.OrdinalIgnoreCase)
                .ToList();
            List<CloneBlockRecord> guardedCurrent = new List<CloneBlockRecord>();
            foreach (CloneBlockRecord guardedClone in guardedPending)
            {
                string guardedCurrentPath = Path.Combine(caseDir, "GUARDED_INIT", "CURRENT", Path.GetFileName(guardedClone.ClonePath));
                WriteTextFile(guardedCurrentPath, File.ReadAllText(guardedClone.ClonePath, Encoding.UTF8));
                guardedCurrent.Add(CreateSelfTestCurrentCloneRecord(guardedClone, guardedCurrentPath));
            }

            string guardedTransactionDir = Path.Combine(guardedInitDir, "_manifest-publish", "run-interrupted-batch");
            string guardedStagedManifest = Path.Combine(guardedTransactionDir, "plc-blocks.csv");
            string guardedFinalManifest = Path.Combine(guardedInitDir, "plc-blocks.csv");
            WriteCsv(
                guardedStagedManifest,
                BlockManifestHeaders(),
                guardedCurrent.Select((x, index) => BuildBlockManifestRowFromCloneRecord(x, guardedPending[index].ClonePath, "guarded recovery")));
            WriteCsv(
                Path.Combine(guardedTransactionDir, "provenance-promotions.csv"),
                new[] { "ReceiptId", "CheckRunId", "SourcePath", "SidecarPath", "SourceNormalizedSha256", "SourceCanonicalSha256", "SoftwarePath", "GroupPath", "Name", "NumberSpace", "Number", "ProgrammingLanguage", "LiveTiaObjectId", "LiveTiaObjectIdStatus" },
                guardedPending.Select((x, index) => new[]
                {
                    "receipt-guarded-" + index.ToString(CultureInfo.InvariantCulture),
                    "check-guarded",
                    x.ClonePath,
                    x.ClonePath + ".meta.json",
                    x.NormalizedSourceSha256,
                    ComputeCanonicalSourceSha256(x.ClonePath),
                    x.SoftwarePath,
                    x.GroupPath,
                    x.Name,
                    x.NumberSpace,
                    x.Number,
                    x.ProgrammingLanguage,
                    "self-test-live-object-" + index.ToString(CultureInfo.InvariantCulture),
                    "available"
                }));
            WriteFlatJsonObjectAtomically(
                Path.Combine(guardedTransactionDir, "provenance-promotion.json"),
                new Dictionary<string, string>
                {
                    { "state", "ready" },
                    { "manifestPath", guardedFinalManifest },
                    { "manifestSha256", ComputeFileSha256(guardedStagedManifest) },
                    { "journalSha256", ComputeFileSha256(Path.Combine(guardedTransactionDir, "provenance-promotions.csv")) },
                    { "promotionCount", "2" }
                });
            WriteTextFile(guardedFinalManifest, "existing baseline must survive rejected recovery\n");
            WriteTextFile(Path.Combine(guardedInitDir, CloneCheckBundleFileName), "existing authorization marker\n");

            WriteTextFile(guardedSourceB + ".meta.json", "{\"sourceOrigin\":\"changed-after-staging\",\"softwarePath\":\"PLC\",\"number\":\"52\",\"numberMode\":\"Manual\"}\n");
            string guardedBeforeRejectedInit = DirectoryTreeFingerprint(guardedInitDir);
            bool guardedInitRejected = false;
            try
            {
                PrepareProjectCloneInitializationWorkspace(guardedInitDir);
            }
            catch (InvalidDataException)
            {
                guardedInitRejected = true;
            }

            AssertTrue(guardedInitRejected, "init-clone preparation must reject a changed later sidecar before reinitializing the baseline");
            AssertEqual(guardedBeforeRejectedInit, DirectoryTreeFingerprint(guardedInitDir), "failed whole-batch recovery must not consume an earlier sidecar, invalidate the bundle, or change any workspace file");
            AssertEqual("explicit-new-local-source", SidecarValue(LoadSidecarMetadata(guardedSourceA), "sourceOrigin"), "a valid earlier row must remain pending when a later recovery row is invalid");

            WriteTextFile(guardedSourceB + ".meta.json", "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\",\"number\":\"52\",\"numberMode\":\"Manual\"}\n");
            PrepareProjectCloneInitializationWorkspace(guardedInitDir);
            AssertTrue(!File.Exists(Path.Combine(guardedInitDir, CloneCheckBundleFileName)), "init-clone preparation must invalidate the old bundle only after pending promotion recovery succeeds");
            AssertTrue(!Directory.Exists(Path.Combine(guardedInitDir, "_manifest-publish")), "init-clone preparation must finish and remove the stale promotion transaction before baseline writes begin");
            AssertTrue(guardedPending.All(x => EqualsIgnoreCase(SidecarValue(LoadSidecarMetadata(x.ClonePath), "sourceOrigin"), "tracked-baseline")), "successful whole-batch recovery must consume every validated sidecar");
            AssertTrue(ReadCsv(guardedFinalManifest).Count == 2, "successful whole-batch recovery must publish the staged manifest");

            WriteTextFile(guardedFinalManifest, "newly initialized baseline\n");
            string newBaselineHash = ComputeFileSha256(guardedFinalManifest);
            RecoverPendingProvenancePromotions(guardedInitDir, guardedInitRoot);
            AssertEqual(newBaselineHash, ComputeFileSha256(guardedFinalManifest), "a later check-clone recovery must not overwrite the newly initialized baseline with a stale manifest");
        }

        private static void SelfTestCloneManifestSourceOriginDurable(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string exportedPath = Path.Combine(rootDir, "20_Tracked.scl");
            string inventoryPath = Path.Combine(rootDir, "1_Main.lad");
            string legacyPath = Path.Combine(rootDir, "2_Legacy.lad");
            Directory.CreateDirectory(rootDir);
            WriteCsv(
                Path.Combine(cloneDir, "plc-blocks.csv"),
                new[] { "SoftwarePath", "GroupPath", "Name", "Number", "NumberSpace", "ProgrammingLanguage", "TypeName", "FilePath", "Status", "SourceOrigin" },
                new[]
                {
                    new[] { "PLC", string.Empty, "Tracked", "20", "FC", "SCL", "Siemens.Engineering.SW.Blocks.FC", exportedPath, "unsupported-language", "exported-source" },
                    new[] { "PLC", string.Empty, "Main", "1", "OB", "LAD", "Siemens.Engineering.SW.Blocks.OB", inventoryPath, "unsupported-language", "inventory-only-unsupported" },
                    new[] { "PLC", string.Empty, "Legacy", "2", "FC", "LAD", "Siemens.Engineering.SW.Blocks.FC", legacyPath, "unsupported-language", string.Empty }
                });

            List<CloneBlockRecord> records = LoadCloneBlockManifest(cloneDir, rootDir);
            AssertTrue(records.Any(x => EqualsIgnoreCase(x.Name, "Tracked") && EqualsIgnoreCase(x.Provenance, "tracked-baseline")), "editing mutable Status must not erase explicit exported-source provenance");
            AssertTrue(!records.Any(x => EqualsIgnoreCase(x.Name, "Main")), "valid inventory-only-unsupported proof must not claim a source baseline");
            AssertTrue(records.Any(x => EqualsIgnoreCase(x.Name, "Legacy") && EqualsIgnoreCase(x.Provenance, "unknown-orphaned")), "legacy unsupported rows without durable origin must fail closed as unknown-orphaned");

            CloneBlockRecord renamedVisual = new CloneBlockRecord
            {
                SoftwarePath = "PLC", Name = "Renamed_Visual", Number = "99", NumberSpace = "FC", ProgrammingLanguage = "LAD",
                TypeName = "Siemens.Engineering.SW.Blocks.FC", ExportStatus = "unsupported-language", RelativePath = "99_Renamed_Visual.lad",
                ClonePath = Path.Combine(rootDir, "99_Renamed_Visual.lad")
            };
            List<CloneDiffRecord> diffs = BuildCloneBlockDiffs(records, new List<CloneBlockRecord> { renamedVisual });
            AssertTrue(BlockingSourceBlockedDiffCount(diffs) > 0, "durable exported or unknown legacy provenance must block a later renamed and renumbered visual block");
        }

        private static void SelfTestCloneCommandPrevalidationNoMutation(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            WriteTextFile(Path.Combine(cloneDir, "_root", "sentinel.scl"), "sentinel\n");
            WriteTextFile(Path.Combine(cloneDir, CloneCheckBundleFileName), "valid-existing-marker\n");
            WriteTextFile(Path.Combine(cloneDir, "block-groups.csv"), "existing-groups\n");
            string before = DirectoryTreeFingerprint(cloneDir);

            InventorySnapshot multi = CreateSelfTestApplySnapshot();
            multi.Devices.Clear();
            multi.Devices.Add(new DeviceRecord { Kind = "Software", Path = "PLC_A", SoftwareType = "Siemens.Engineering.SW.PlcSoftware", Object = new object() });
            multi.Devices.Add(new DeviceRecord { Kind = "Software", Path = "PLC_B", SoftwareType = "Siemens.Engineering.SW.PlcSoftware", Object = new object() });
            bool initRejected = false;
            bool checkRejected = false;
            try
            {
                InitializeProjectClone(multi, cloneDir, new Options());
            }
            catch (InvalidOperationException)
            {
                initRejected = true;
            }
            AssertEqual(before, DirectoryTreeFingerprint(cloneDir), "mis-scoped multi-PLC init-clone must not change any existing workspace file or marker");

            try
            {
                CheckProjectClone(multi, cloneDir);
            }
            catch (InvalidOperationException)
            {
                checkRejected = true;
            }
            AssertTrue(initRejected && checkRejected, "init-clone and check-clone must reject ambiguous multi-PLC selection");
            AssertEqual(before, DirectoryTreeFingerprint(cloneDir), "mis-scoped multi-PLC check-clone must not invalidate the existing marker or create compare/staging artifacts");
        }

        private static void SelfTestSyncCloneTransactionSuccess(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string compareDir = Path.Combine(cloneDir, "_compare", "current-transaction");
            string compareRoot = Path.Combine(compareDir, "_root");
            string clonePath = Path.Combine(rootDir, "10_FB.scl");
            string currentPath = Path.Combine(compareRoot, "10_FB.scl");
            WriteTextFile(clonePath, "FUNCTION_BLOCK \"FB\"\nBEGIN\n    #Value := 1;\nEND_FUNCTION_BLOCK\n");
            string oldContent = File.ReadAllText(clonePath, Encoding.UTF8);
            WriteTextFile(currentPath, "FUNCTION_BLOCK \"FB\"\nBEGIN\n    #Value := 2;\nEND_FUNCTION_BLOCK\n");
            WriteCsv(
                Path.Combine(cloneDir, "plc-blocks.csv"),
                new[] { "SoftwarePath", "GroupPath", "Name", "Number", "NumberSpace", "ProgrammingLanguage", "TypeName", "FilePath", "Status", "SourceOrigin" },
                new[] { new[] { "PLC", string.Empty, "FB", "10", "FB", "SCL", "Siemens.Engineering.SW.Blocks.FB", clonePath, "ok", "exported-source" } });
            WriteCsv(Path.Combine(cloneDir, "block-groups.csv"), new[] { "SoftwarePath", "GroupPath", "Name", "Directory" }, new string[0][]);
            WriteTextFile(Path.Combine(cloneDir, "_metadata", "sentinel.txt"), "old metadata\n");
            string checkRunId = Guid.NewGuid().ToString("N");
            WriteCsv(
                Path.Combine(cloneDir, CloneCheckBlockFileName),
                new[] { "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Status", "Name", "NumberSpace", "Number", "ProgrammingLanguage", "TypeName", "CloneSoftwarePath", "CloneName", "CloneNumberSpace", "CloneNumber", "ClonePath", "CloneProvenance", "CurrentSoftwarePath", "CurrentName", "CurrentNumberSpace", "CurrentNumber", "CurrentPath", "CurrentSourceSha256" },
                new[]
                {
                    new[] { CloneCheckBundleSchemaVersion, checkRunId, "PLC", "changed", "FB", "FB", "10", "SCL", "Siemens.Engineering.SW.Blocks.FB", "PLC", "FB", "FB", "10", clonePath, "tracked-baseline", "PLC", "FB", "FB", "10", currentPath, ComputeFileSha256(currentPath) }
                });
            WriteCsv(Path.Combine(cloneDir, CloneCheckSourceBlockerFileName), new[] { "CheckSchemaVersion", "CheckRunId", "Severity" }, new string[0][]);
            CompleteSelfTestCloneCheckBundle(cloneDir, compareDir, checkRunId, 1, 0);

            SyncProjectClone(cloneDir);

            AssertEqual(File.ReadAllText(currentPath, Encoding.UTF8), File.ReadAllText(clonePath, Encoding.UTF8), "successful sync transaction must publish the staged source");
            Dictionary<string, string> manifest = ReadCsv(Path.Combine(cloneDir, "plc-blocks.csv")).Single();
            AssertEqual("exported-source", GetCsvValue(manifest, "SourceOrigin"), "successful sync must publish durable source origin");
            AssertEqual(ComputeFileSha256(clonePath), GetCsvValue(manifest, "SourceSha256"), "successful sync manifest hash must describe the installed source");
            AssertEqual("4", File.ReadAllText(Path.Combine(cloneDir, "_metadata", "schema-version.txt"), Encoding.UTF8).Trim(), "successful sync must preserve PLC clone metadata schema 4 independently of the check-bundle schema");
            AssertTrue(!File.Exists(Path.Combine(cloneDir, CloneCheckBundleFileName)), "successful sync must invalidate the consumed authorization bundle");
            AssertTrue(!Directory.Exists(Path.Combine(cloneDir, "_sync-staging")), "successful sync must remove committed staging");
            string backup = Directory.GetDirectories(Path.Combine(cloneDir, "_sync-backups"), "sync-*", SearchOption.TopDirectoryOnly).Single();
            AssertEqual(oldContent, File.ReadAllText(Path.Combine(backup, "_root", "10_FB.scl"), Encoding.UTF8), "successful sync must retain the previous source in its transaction backup");
            Dictionary<string, string> completion = ParseStrictFlatJsonObject(File.ReadAllText(Path.Combine(backup, "publication-completion.json"), Encoding.UTF8), Path.Combine(backup, "publication-completion.json"));
            AssertEqual("committed", SidecarValue(completion, "state"), "successful sync must leave an unambiguous durable committed result");
            AssertEqual("ok", SidecarValue(completion, "diagnosticStatus"), "successful sync report publication must update the durable diagnostic status");
        }

        private static void SelfTestSyncCloneTransactionFailure(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string compareDir = Path.Combine(cloneDir, "_compare", "current-transaction");
