            bool failed = false;
            try
            {
                SyncProjectClone(cloneDir);
            }
            catch (InvalidOperationException ex)
            {
                failed = ex.Message.IndexOf("original _root", StringComparison.OrdinalIgnoreCase) >= 0;
            }

            AssertTrue(failed, "a per-row staging failure must make sync-clone return non-zero");
            AssertEqual(rootBefore, DirectoryTreeFingerprint(rootDir), "failed sync must leave the original _root byte-for-byte unchanged");
            AssertEqual(manifestBefore, File.ReadAllText(Path.Combine(cloneDir, "plc-blocks.csv"), Encoding.UTF8), "failed sync must not publish a new block manifest");
            AssertEqual(groupsBefore, File.ReadAllText(Path.Combine(cloneDir, "block-groups.csv"), Encoding.UTF8), "failed sync must not publish a new group manifest");
            AssertEqual(metadataBefore, DirectoryTreeFingerprint(Path.Combine(cloneDir, "_metadata")), "failed sync must not publish new metadata");
            AssertEqual(markerBefore, ComputeFileSha256(Path.Combine(cloneDir, CloneCheckBundleFileName)), "failed sync must preserve the valid authorization bundle");
            AssertTrue(!Directory.Exists(Path.Combine(cloneDir, "_sync-backups")), "failed staging must not create a commit backup because original data was never touched");
        }

        private static void SelfTestSyncCloneImmutableCurrentInput(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string compareDir = Path.Combine(cloneDir, "_compare", "current-input");
            string compareRoot = Path.Combine(compareDir, "_root");
            string clonePath = Path.Combine(rootDir, "1_A.scl");
            string currentPath = Path.Combine(compareRoot, "1_A.scl");
            WriteTextFile(clonePath, "FUNCTION_BLOCK \"A\"\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(Path.Combine(cloneDir, "plc-blocks.csv"), "blocks\n");
            WriteTextFile(Path.Combine(cloneDir, "block-groups.csv"), "groups\n");
            string authorized = "FUNCTION_BLOCK \"A\"\nBEGIN\n #authorized := 1;\nEND_FUNCTION_BLOCK\n";
            WriteTextFile(currentPath, authorized);
            Dictionary<string, string> blockRow = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                { "Status", "changed" }, { "ClonePath", clonePath }, { "CurrentPath", currentPath },
                { "CurrentSourceSha256", ComputeFileSha256(currentPath) }
            };
            CloneCheckBundleEvidence bundle = new CloneCheckBundleEvidence
            {
                CompareDirectory = compareDir,
                WorkspaceRows = CloneWorkspaceInventoryRows(BuildCloneWorkspaceInventory(cloneDir)),
                BlockRows = new List<Dictionary<string, string>> { blockRow }
            };

            string staleStage = Path.Combine(cloneDir, "_sync-staging", "run-stale");
            Directory.CreateDirectory(staleStage);
            WriteTextFile(Path.Combine(staleStage, SyncStagingOwnerMarkerFileName), "owned\n");
            WriteTextFile(currentPath, authorized.Replace("1", "2"));
            bool staleRejected = false;
            SyncStagingLease staleLease = new SyncStagingLease { DirectoryPath = staleStage };
            try
            {
                StageImmutableSyncInputs(cloneDir, bundle, staleStage, staleLease, null);
            }
            catch (InvalidDataException)
            {
                staleRejected = true;
            }
            finally
            {
                staleLease.Dispose();
                CleanupSyncStaging(staleStage);
            }
            AssertTrue(staleRejected, "a current compare source changed after the initial hash check must be rejected before commit");

            WriteTextFile(currentPath, authorized);
            string lockedStage = Path.Combine(cloneDir, "_sync-staging", "run-locked");
            Directory.CreateDirectory(lockedStage);
            WriteTextFile(Path.Combine(lockedStage, SyncStagingOwnerMarkerFileName), "owned\n");
            bool concurrentWriteRejected = false;
            SyncStagingLease lockedLease = new SyncStagingLease { DirectoryPath = lockedStage };
            try
            {
                SyncInputSet inputs = StageImmutableSyncInputs(
                    cloneDir,
                    bundle,
                    lockedStage,
                    lockedLease,
                    delegate(string phase)
                    {
                        if (phase.EndsWith(currentPath, StringComparison.OrdinalIgnoreCase))
                        {
                            try { WriteTextFile(currentPath, authorized.Replace("1", "9")); }
                            catch (IOException) { concurrentWriteRejected = true; }
                            catch (UnauthorizedAccessException) { concurrentWriteRejected = true; }
                        }
                    });
                AssertTrue(concurrentWriteRejected, "the compare source must remain read-locked while its authoritative bytes are copied");
                AssertEqual(ComputeTextSha256(authorized), ComputeTextSha256(File.ReadAllText(inputs.CurrentSourcePath(currentPath), Encoding.UTF8)), "immutable sync input must contain exactly the authorized current bytes");
            }
            finally
            {
                lockedLease.Dispose();
                CleanupSyncStaging(lockedStage);
            }

            string outsideDir = Path.Combine(caseDir, "outside-current");
            string junctionPath = Path.Combine(compareRoot, "late-link");
            WriteTextFile(Path.Combine(outsideDir, "1_A.scl"), authorized);
            System.Diagnostics.ProcessStartInfo start = new System.Diagnostics.ProcessStartInfo(
                "cmd.exe", "/d /c mklink /J \"" + junctionPath + "\" \"" + outsideDir + "\"");
            start.UseShellExecute = false;
            start.CreateNoWindow = true;
            start.RedirectStandardOutput = true;
            start.RedirectStandardError = true;
            using (System.Diagnostics.Process process = System.Diagnostics.Process.Start(start))
            {
                process.WaitForExit();
                if (process.ExitCode != 0) throw new InvalidOperationException("Could not create sync-input junction fixture: " + process.StandardError.ReadToEnd());
            }
            blockRow["CurrentPath"] = Path.Combine(junctionPath, "1_A.scl");
            blockRow["CurrentSourceSha256"] = ComputeFileSha256(Path.Combine(outsideDir, "1_A.scl"));
            string junctionStage = Path.Combine(cloneDir, "_sync-staging", "run-junction");
            Directory.CreateDirectory(junctionStage);
            WriteTextFile(Path.Combine(junctionStage, SyncStagingOwnerMarkerFileName), "owned\n");
            bool junctionRejected = false;
            SyncStagingLease junctionLease = new SyncStagingLease { DirectoryPath = junctionStage };
            try
            {
                StageImmutableSyncInputs(cloneDir, bundle, junctionStage, junctionLease, null);
            }
            catch (InvalidOperationException ex)
            {
                junctionRejected = ex.Message.IndexOf("reparse", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            finally
            {
                junctionLease.Dispose();
                CleanupSyncStaging(junctionStage);
                if (Directory.Exists(junctionPath)) Directory.Delete(junctionPath, false);
            }
            AssertTrue(junctionRejected, "a current source replaced by a junction/symlink must be rejected before external bytes are read");
        }

        private static SelfTestPublicationFixture CreateSelfTestPublicationExpectedFixture(
            string caseDir,
            bool applyPublication)
        {
            string logicalOutDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string stagingDir = applyPublication
                ? Path.Combine(logicalOutDir, "_apply-validation", "run-expected-model")
                : Path.Combine(logicalOutDir, "_sync-staging", "run-expected-model");
            string evidenceDir = applyPublication ? stagingDir : logicalOutDir;
            string evidenceRoot = Path.Combine(evidenceDir, "_root");
            string compareRoot = Path.Combine(evidenceDir, "_compare", "current-model", "_root");
            List<Dictionary<string, string>> blockRows = new List<Dictionary<string, string>>();
            List<string[]> manifestRows = new List<string[]>();
            foreach (Tuple<string, string> item in new[] { Tuple.Create("A", "1"), Tuple.Create("B", "2") })
            {
                string relative = item.Item2 + "_" + item.Item1 + ".scl";
                string sourcePath = Path.Combine(evidenceRoot, relative);
                string currentPath = Path.Combine(compareRoot, relative);
                string source = "FUNCTION_BLOCK \"" + item.Item1 + "\"\nBEGIN\nEND_FUNCTION_BLOCK\n";
                WriteTextFile(sourcePath, source);
                WriteTextFile(currentPath, source);
                CloneBlockRecord record = CreateSelfTestCloneIdentityRecord(item.Item1, item.Item2, relative, sourcePath, true, "tia-object-" + item.Item2, "available");
                manifestRows.Add(BuildBlockManifestRowFromCloneRecord(record, sourcePath, "baseline"));
                blockRows.Add(new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                {
                    { "Status", "unchanged" }, { "SoftwarePath", "PLC" }, { "CloneSoftwarePath", "PLC" }, { "CurrentSoftwarePath", "PLC" },
                    { "Name", item.Item1 }, { "CloneName", item.Item1 }, { "CurrentName", item.Item1 },
                    { "Number", item.Item2 }, { "CloneNumber", item.Item2 }, { "CurrentNumber", item.Item2 },
                    { "AutoNumber", "False" }, { "NumberMode", "Manual" }, { "NumberSpace", "FB" },
                    { "ProgrammingLanguage", "SCL" }, { "BlockType", "FB" }, { "TypeName", "Siemens.Engineering.SW.Blocks.FB" },
                    { "SourceTypeName", "Siemens.Engineering.SW.Blocks.FB" }, { "TiaObjectId", "tia-object-" + item.Item2 }, { "TiaObjectIdStatus", "available" },
                    { "ClonePath", sourcePath }, { "CloneSourceSha256", ComputeFileSha256(sourcePath) }, { "CloneNormalizedSourceSha256", ComputeNormalizedTextSha256(sourcePath) },
                    { "CurrentPath", currentPath }, { "CurrentSourceSha256", ComputeFileSha256(currentPath) }, { "CurrentNormalizedSourceSha256", ComputeNormalizedTextSha256(currentPath) },
                    { "CloneProvenance", "tracked-baseline" }
                });
            }
            WriteCsv(Path.Combine(evidenceDir, "plc-blocks.csv"), BlockManifestHeaders(), manifestRows);
            WriteCsv(Path.Combine(evidenceDir, "block-groups.csv"), GroupManifestHeaders(), new string[0][]);
            WriteCloneMetadata(evidenceDir);
            CloneCheckBundleEvidence bundle = new CloneCheckBundleEvidence
            {
                CheckRunId = "expected-model-test",
                CompareDirectory = Path.GetDirectoryName(compareRoot),
                WorkspaceRows = CloneWorkspaceInventoryRows(BuildCloneWorkspaceInventory(evidenceDir)),
                BlockRows = blockRows,
                GroupRows = new List<Dictionary<string, string>>()
            };
            if (!applyPublication)
            {
                WritePublicationStagingOwnerMarker(Path.Combine(stagingDir, SyncStagingOwnerMarkerFileName), "sync-clone", bundle.CheckRunId);
            }
            else
            {
                WritePublicationStagingOwnerMarker(Path.Combine(stagingDir, ApplyValidationOwnerMarkerFileName), "apply-publication", bundle.CheckRunId);
            }
            SyncStagingLease inputLease = new SyncStagingLease { DirectoryPath = stagingDir };
            SyncInputSet inputs = StageImmutableSyncInputs(evidenceDir, bundle, stagingDir, inputLease, null);
            if (!applyPublication)
            {
                CopyDirectory(Path.Combine(inputs.WorkspaceRoot, "_root"), Path.Combine(stagingDir, "_root"), false);
            }
            PublicationExpectedModel model = BuildPublicationExpectedModel(
                logicalOutDir,
                bundle,
                stagingDir,
                evidenceRoot,
                compareRoot,
                inputs);
            if (applyPublication) PrepareApplyValidationWorkspaceForPublish(stagingDir, model);
            else WriteExpectedPublicationArtifacts(stagingDir, model);
            return new SelfTestPublicationFixture
            {
                LogicalOutDir = logicalOutDir,
                StagingDir = stagingDir,
                EvidenceRootDir = evidenceRoot,
                CompareRootDir = compareRoot,
                Bundle = bundle,
                ExpectedModel = model,
                InputLease = inputLease
            };
        }

        private static void SelfTestSyncPublicationAuthoritativeModel(string caseDir)
        {
            foreach (string mutation in new[] { "csv-durable-id", "coordinated-csv-jsonl", "swapped-file-path" })
            {
                using (SelfTestPublicationFixture fixture = CreateSelfTestPublicationExpectedFixture(Path.Combine(caseDir, mutation), false))
                {
                    string blocksPath = Path.Combine(fixture.StagingDir, "plc-blocks.csv");
                    List<Dictionary<string, string>> rows = ReadCsv(blocksPath);
                    if (EqualsIgnoreCase(mutation, "swapped-file-path"))
                    {
                        string first = GetCsvValue(rows[0], "FilePath");
                        rows[0]["FilePath"] = GetCsvValue(rows[1], "FilePath");
                        rows[1]["FilePath"] = first;
                    }
                    else
                    {
                        rows[0]["TiaObjectId"] = string.Empty;
                        rows[0]["TiaObjectIdStatus"] = "unavailable";
                        rows[0]["SourceOrigin"] = "unknown";
                    }
                    WriteCsv(blocksPath, BlockManifestHeaders(), rows.Select(row => BlockManifestHeaders().Select(header => GetCsvValue(row, header)).ToArray()));
                    if (EqualsIgnoreCase(mutation, "coordinated-csv-jsonl") || EqualsIgnoreCase(mutation, "swapped-file-path"))
                    {
                        WriteCloneMetadata(
                            fixture.StagingDir,
                            fixture.LogicalOutDir,
                            blocksPath,
                            Path.Combine(fixture.StagingDir, "block-groups.csv"));
                    }
                    SyncStagingLease sealLease = new SyncStagingLease { DirectoryPath = fixture.StagingDir };
                    bool rejected = false;
                    try
                    {
                        SealSyncStaging(
                            fixture.LogicalOutDir,
                            fixture.Bundle,
                            fixture.StagingDir,
                            fixture.EvidenceRootDir,
                            fixture.CompareRootDir,
                            fixture.ExpectedModel,
                            sealLease);
                    }
                    catch (InvalidDataException)
                    {
                        rejected = true;
                    }
                    finally
                    {
                        sealLease.Dispose();
                    }
                    AssertTrue(rejected, "sync seal must reject authoritative-model mutation: " + mutation);
                }
            }
        }

