        private static void SelfTestCloneTrackedRenameReconciliation(string caseDir)
        {
            string cloneDir = Path.Combine(caseDir, "CLONE_PROJECT");
            string rootDir = Path.Combine(cloneDir, "_root");
            string oldPath = Path.Combine(rootDir, "1_OldName.scl");
            string renamedPath = Path.Combine(rootDir, "1_NewName.scl");
            WriteTextFile(renamedPath, "FUNCTION_BLOCK \"NewName\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(
                renamedPath + ".meta.json",
                "{\"sourceOrigin\":\"tracked-baseline\",\"softwarePath\":\"PLC\",\"autoNumber\":\"true\",\"numberMode\":\"Auto\"}\n");
            WriteCsv(
                Path.Combine(cloneDir, "plc-blocks.csv"),
                new[] { "SoftwarePath", "GroupPath", "Name", "Number", "AutoNumber", "NumberMode", "NumberSpace", "ProgrammingLanguage", "TypeName", "FilePath", "Status", "SourceOrigin" },
                new[]
                {
                    new[] { "PLC", string.Empty, "OldName", "1", "True", "Auto", "FB", "SCL", "Siemens.Engineering.SW.Blocks.FB", oldPath, "ok", "exported-source" }
                });

            List<CloneBlockRecord> cloneRecords = LoadCloneBlockManifest(cloneDir, rootDir);
            AssertEqual("1", cloneRecords.Count.ToString(CultureInfo.InvariantCulture), "a unique moved tracked source must replace its missing manifest-path record");
            CloneBlockRecord renamed = cloneRecords[0];
            AssertEqual("NewName", renamed.Name, "renamed source name must come from source text");
            AssertEqual("1", renamed.Number, "tracked sidecar without number must retain the canonical filename number");
            AssertEqual("PLC", renamed.SoftwarePath, "moved tracked source must retain manifest PLC scope");
            AssertEqual("tracked-baseline", renamed.Provenance, "unique moved source must retain tracked provenance");

            string currentPath = Path.Combine(caseDir, "CURRENT", "1_OldName.scl");
            WriteTextFile(currentPath, "FUNCTION_BLOCK \"OldName\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            CloneBlockRecord current = new CloneBlockRecord
            {
                SoftwarePath = "PLC",
                GroupPath = string.Empty,
                GroupPathDisplay = string.Empty,
                Name = "OldName",
                Number = "1",
                AutoNumber = "True",
                NumberMode = "Auto",
                NumberSpace = "FB",
                ProgrammingLanguage = "SCL",
                BlockType = "FB",
                TypeName = "Siemens.Engineering.SW.Blocks.FB",
                SourceTypeName = "Siemens.Engineering.SW.Blocks.FB",
                RelativePath = "1_OldName.scl",
                ClonePath = oldPath,
                CurrentPath = currentPath,
                ExportStatus = "ok"
            };
            List<CloneDiffRecord> diffs = BuildCloneBlockDiffs(cloneRecords, new List<CloneBlockRecord> { current });
            AssertEqual("1", diffs.Count.ToString(CultureInfo.InvariantCulture), "tracked rename must produce one diff row");
            AssertEqual("moved-or-renamed", diffs[0].Status, "a declaration-name-only tracked rename must classify as pure RenameBlock");

            WriteTextFile(renamedPath, "FUNCTION_BLOCK \"NewName\"\nBEGIN\n #Value := 1;\nEND_FUNCTION_BLOCK\n");
            List<CloneDiffRecord> changedDiffs = BuildCloneBlockDiffs(cloneRecords, new List<CloneBlockRecord> { current });
            AssertEqual("moved-or-renamed-and-changed", changedDiffs[0].Status, "a tracked rename with any body change must require RenameAndUpdateSource");

            string unsafeDir = Path.Combine(caseDir, "EXPLICIT_NEW");
            string unsafeRoot = Path.Combine(unsafeDir, "_root");
            string unsafeOldPath = Path.Combine(unsafeRoot, "1_OldName.scl");
            string unsafeNewPath = Path.Combine(unsafeRoot, "1_NewName.scl");
            WriteTextFile(unsafeNewPath, "FUNCTION_BLOCK \"NewName\"\nBEGIN\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(
                unsafeNewPath + ".meta.json",
                "{\"sourceOrigin\":\"explicit-new-local-source\",\"softwarePath\":\"PLC\",\"number\":\"1\",\"numberMode\":\"Manual\"}\n");
            WriteCsv(
                Path.Combine(unsafeDir, "plc-blocks.csv"),
                new[] { "SoftwarePath", "GroupPath", "Name", "Number", "NumberSpace", "ProgrammingLanguage", "TypeName", "FilePath", "Status", "SourceOrigin" },
                new[]
                {
                    new[] { "PLC", string.Empty, "OldName", "1", "FB", "SCL", "Siemens.Engineering.SW.Blocks.FB", unsafeOldPath, "ok", "exported-source" }
                });
            List<CloneBlockRecord> unsafeRecords = LoadCloneBlockManifest(unsafeDir, unsafeRoot);
            AssertTrue(unsafeRecords.Any(x => EqualsIgnoreCase(x.Provenance, "explicit-new-local-source")), "explicit-new source must remain pending and must never adopt a missing tracked identity");
            AssertTrue(unsafeRecords.Any(x => EqualsIgnoreCase(x.Provenance, "tracked-baseline") && !CloneSourceFileExists(x)), "explicit-new source must not consume the missing tracked manifest record");
        }

        private static void SelfTestApplyClonePostWritePathTransition(
            string cloneDir,
            string oldFileName,
            string newFileName,
            string finalName,
            string finalNumber)
        {
            string rootDir = Path.Combine(cloneDir, "_root");
            string compareDir = Path.Combine(cloneDir, "_compare", "current-transition");
            string compareRoot = Path.Combine(compareDir, "_root");
            string oldPath = Path.Combine(rootDir, oldFileName);
            string newPath = Path.Combine(rootDir, newFileName);
            string currentPath = Path.Combine(compareRoot, newFileName);
            WriteTextFile(oldPath, "FUNCTION_BLOCK \"" + finalName + "\"\nBEGIN\n    #Value := 1;\nEND_FUNCTION_BLOCK\n");
            WriteTextFile(oldPath + ".meta.json", "{\"sourceOrigin\":\"tracked-baseline\",\"softwarePath\":\"PLC\"}\n");
            WriteTextFile(currentPath, "FUNCTION_BLOCK \"" + finalName + "\"\r\nBEGIN\r\n\t#Value:=1; // TIA formatting\r\nEND_FUNCTION_BLOCK\r\n");
            WriteCsv(
                Path.Combine(cloneDir, "plc-blocks.csv"),
                new[] { "SoftwarePath", "GroupPath", "Name", "Number", "NumberSpace", "ProgrammingLanguage", "TypeName", "FilePath", "Status", "SourceOrigin" },
                new[] { new[] { "PLC", string.Empty, finalName, finalNumber, "FB", "SCL", "Siemens.Engineering.SW.Blocks.FB", oldPath, "ok", "exported-source" } });
            WriteCsv(Path.Combine(cloneDir, "block-groups.csv"), new[] { "SoftwarePath", "GroupPath", "Name", "Directory" }, new string[0][]);
            WriteTextFile(Path.Combine(cloneDir, "_metadata", "sentinel.txt"), "old metadata\n");
            string checkRunId = Guid.NewGuid().ToString("N");
            WriteCsv(
                Path.Combine(cloneDir, CloneCheckBlockFileName),
                new[]
                {
                    "CheckSchemaVersion", "CheckRunId", "SoftwarePath", "Status", "GroupPath", "Name", "Number", "AutoNumber", "NumberMode", "NumberSpace", "ProgrammingLanguage", "BlockType", "TypeName",
                    "CloneSoftwarePath", "CloneGroupPath", "CloneName", "CloneNumber", "CloneNumberSpace", "ClonePath", "CloneProvenance",
                    "CurrentSoftwarePath", "CurrentGroupPath", "CurrentName", "CurrentNumber", "CurrentNumberSpace", "CurrentPath", "CurrentSourceSha256"
                },
                new[]
                {
                    new[]
                    {
                        CloneCheckBundleSchemaVersion, checkRunId, "PLC", "moved-or-renamed-and-changed", string.Empty, finalName, finalNumber, "False", "Manual", "FB", "SCL", "FB", "Siemens.Engineering.SW.Blocks.FB",
                        "PLC", string.Empty, finalName, finalNumber, "FB", oldPath, "tracked-baseline",
                        "PLC", string.Empty, finalName, finalNumber, "FB", currentPath, ComputeFileSha256(currentPath)
                    }
                });
            WriteCsv(Path.Combine(cloneDir, CloneCheckSourceBlockerFileName), new[] { "CheckSchemaVersion", "CheckRunId", "Severity" }, new string[0][]);
            CompleteSelfTestCloneCheckBundle(cloneDir, compareDir, checkRunId, 1, 0);

            SyncProjectClone(cloneDir);

            AssertTrue(!File.Exists(oldPath) && !File.Exists(oldPath + ".meta.json"), "post-write transition must remove the obsolete source/sidecar path");
            AssertEqual(File.ReadAllText(currentPath, Encoding.UTF8), File.ReadAllText(newPath, Encoding.UTF8), "post-write transition must publish the exact TIA export at its canonical path");
            AssertTrue(File.Exists(newPath + ".meta.json"), "post-write transition must move the sidecar with its source");
            Dictionary<string, string> manifest = ReadCsv(Path.Combine(cloneDir, "plc-blocks.csv")).Single();
            AssertEqual(Path.GetFullPath(newPath), Path.GetFullPath(GetCsvValue(manifest, "FilePath")), "post-write manifest must reference the canonical assigned-number/renamed path");
            string metadata = File.ReadAllText(Path.Combine(cloneDir, "_metadata", "blocks.jsonl"), Encoding.UTF8);
            AssertTrue(metadata.IndexOf(newFileName, StringComparison.OrdinalIgnoreCase) >= 0, "post-write metadata must be regenerated with the canonical path");
        }

        private static ApplyPlanItem CreateSelfTestApplyPlanItem(string rootDir, string action, string name, int number, string language, string typeName, bool hasExisting, string extension)
        {
            Directory.CreateDirectory(rootDir);
            string clonePath = Path.Combine(rootDir, SafeFileName(number.ToString(CultureInfo.InvariantCulture) + "_" + name + extension));
            WriteTextFile(clonePath, "// self-test source " + name + Environment.NewLine);
            string sourceHash = ComputeFileSha256(clonePath);
            BlockRecord existing = hasExisting ? CreateSelfTestBlock(name, number, language, typeName) : null;

            return new ApplyPlanItem
            {
                Key = name,
                SourceRowIndex = number,
                SoftwarePath = "PLC",
                Row = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
                {
                    { "CloneSourceSha256", sourceHash }
                },
                Status = EqualsIgnoreCase(action, "CreateBlock") ? "removed" : "changed",
                Action = action,
                CurrentGroupPath = string.Empty,
                CurrentGroupPathDisplay = string.Empty,
                CurrentName = hasExisting ? name : string.Empty,
                CurrentNumberSpace = BlockNumberSpace(typeName, language),
                CurrentNumber = hasExisting ? number.ToString(CultureInfo.InvariantCulture) : string.Empty,
                CurrentTypeName = hasExisting ? typeName : string.Empty,
                CurrentProgrammingLanguage = hasExisting ? language : string.Empty,
                CurrentNumberMode = "Manual",
                CurrentSourceSha256 = sourceHash,
                TargetGroupPath = string.Empty,
                TargetGroupPathDisplay = string.Empty,
                TargetName = name,
                TargetNumberSpace = BlockNumberSpace(typeName, language),
                TargetNumber = number.ToString(CultureInfo.InvariantCulture),
                TypeName = typeName,
                ProgrammingLanguage = language,
                NumberSpace = BlockNumberSpace(typeName, language),
                NumberMode = "Manual",
                DesiredNumber = number,
                ClonePath = clonePath,
                CloneProvenance = EqualsIgnoreCase(action, "CreateBlock") ? "explicit-new-local-source" : "tracked-baseline",
                Existing = existing,
                WillCreateGroup = false,
                WillGenerateSource = EqualsIgnoreCase(action, "CreateBlock") || EqualsIgnoreCase(action, "UpdateSource") || EqualsIgnoreCase(action, "RenameAndUpdateSource"),
                WillRename = EqualsIgnoreCase(action, "RenameBlock") || EqualsIgnoreCase(action, "RenameAndUpdateSource"),
                WillDelete = EqualsIgnoreCase(action, "DeleteBlock"),
                Message = "self-test"
            };
        }

        private static ApplyPlanItem CreateSelfTestDeletePlanItem(BlockRecord block)
        {
            return new ApplyPlanItem
            {
                Key = block.Name,
                SoftwarePath = FirstNonEmpty(block.SoftwarePath, "PLC"),
                Row = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase),
                Status = "added",
                Action = "DeleteBlock",
                CurrentGroupPath = EmptyIfNull(block.GroupPath),
                CurrentGroupPathDisplay = EmptyIfNull(block.GroupPathDisplay),
                CurrentName = block.Name,
                CurrentNumberSpace = BlockNumberSpace(block),
                CurrentNumber = block.Number,
                CurrentTypeName = block.TypeName,
                CurrentProgrammingLanguage = block.ProgrammingLanguage,
                TargetGroupPath = EmptyIfNull(block.GroupPath),
                TargetGroupPathDisplay = EmptyIfNull(block.GroupPathDisplay),
                TargetName = block.Name,
                TargetNumberSpace = BlockNumberSpace(block),
                TargetNumber = block.Number,
                TypeName = block.TypeName,
                ProgrammingLanguage = block.ProgrammingLanguage,
                NumberSpace = BlockNumberSpace(block),
                DesiredNumber = SafeInt(block.Number),
                Existing = block,
                WillDelete = true,
                Message = "self-test"
            };
        }

        private static InventorySnapshot CreateSelfTestApplySnapshot(params BlockRecord[] blocks)
        {
            InventorySnapshot snapshot = new InventorySnapshot
            {
                ProjectName = "self-test",
                ProjectPath = Path.GetFullPath("self-test.ap21"),
                ProjectType = "self-test",
                ProjectVersion = "21",
                ProjectObjectId = string.Empty,
                ProjectObjectIdStatus = "unavailable",
                CreatedAt = DateTime.UtcNow
            };
            snapshot.Devices.Add(new DeviceRecord
            {
                Kind = "Software",
                Path = "PLC",
                SoftwareType = "Siemens.Engineering.SW.PlcSoftware",
                Object = new object()
            });
            foreach (BlockRecord block in blocks.Where(x => x != null))
            {
                block.SoftwarePath = FirstNonEmpty(block.SoftwarePath, "PLC");
                snapshot.Blocks.Add(block);
            }

            return snapshot;
        }

