        private static void WriteSelfTestCopyProbeReports(string cloneDir, string patchedDirInSummary, List<HmiProjectTextImportTarget> targets, int unexpectedCollateralRows)
        {
            Directory.CreateDirectory(cloneDir);
            string targetCulture = targets.Count == 0 ? "ru-RU" : FirstNonEmpty(targets[0].Culture, "ru-RU");
            bool updateSourceLanguage = EqualsIgnoreCase(targetCulture, "en-US");
            WriteTextFile(Path.Combine(cloneDir, "hmi-project-texts-import-probe-copy-summary.txt"),
                "HMI project-texts import probe on copied project" + Environment.NewLine
                + "Patched preflight directory: " + Path.GetFullPath(patchedDirInSummary) + Environment.NewLine
                + "Source culture: en-US" + Environment.NewLine
                + "Target culture: " + targetCulture + Environment.NewLine
                + "Import uses updateSourceLanguage: " + updateSourceLanguage + Environment.NewLine);
            WriteCsv(Path.Combine(cloneDir, "hmi-project-texts-import-probe-copy-targets.csv"), HmiProjectTextImportTargetHeaders(), targets.Select(HmiProjectTextImportTargetRow));
            List<string[]> collateralRows = new List<string[]>();
            for (int i = 0; i < unexpectedCollateralRows; i++)
            {
                collateralRows.Add(HmiApplyCollateralDiffRow(new HmiApplyCollateralDiffRecord
                {
                    Expected = false,
                    Report = "hmi-screen-items.csv",
                    Status = "changed",
                    Key = "unexpected-" + i.ToString(CultureInfo.InvariantCulture),
                    RelativePath = "screens\\001_Main.xml",
                    Before = "before",
                    After = "after",
                    Message = "Unexpected collateral digest change."
                }));
            }

            WriteCsv(Path.Combine(cloneDir, "hmi-project-texts-import-probe-copy-collateral.csv"), HmiApplyCollateralDiffHeaders(), collateralRows);
        }

        private static void CreateSelfTestHmiClone(string cloneDir)
        {
            string hmiRoot = Path.Combine(cloneDir, "_hmi");
            string metadataDir = Path.Combine(cloneDir, "_hmi_metadata");
            string digestDir = Path.Combine(metadataDir, "digest");
            Directory.CreateDirectory(metadataDir);
            CreateSelfTestHmiExport(hmiRoot, SelfTestOldText());
            WriteHmiDigest(hmiRoot, digestDir);

            List<HmiObjectManifestRecord> manifest = BuildHmiObjectManifest(hmiRoot, digestDir);
            WriteHmiObjectManifest(Path.Combine(metadataDir, "hmi-objects.csv"), manifest);

            List<HmiObjectDiffRecord> diffs = BuildHmiObjectDiffs(manifest, manifest);
            WriteCsv(Path.Combine(cloneDir, "hmi-check-objects.csv"), HmiObjectDiffHeaders(), diffs.Select(HmiObjectDiffRow));
        }

        private static void CreateSelfTestHmiExport(string hmiRoot, string labelText)
        {
            Directory.CreateDirectory(Path.Combine(hmiRoot, "screens"));
            Directory.CreateDirectory(Path.Combine(hmiRoot, "text-lists"));
            Directory.CreateDirectory(Path.Combine(hmiRoot, "tag-tables"));

            string screenPath = Path.Combine(hmiRoot, "screens", "001_Main.xml");
            string textListPath = Path.Combine(hmiRoot, "text-lists", "001_Mode.xml");
            string tagTablePath = Path.Combine(hmiRoot, "tag-tables", "001_Tags.xml");
            WriteTextFile(screenPath, BuildSelfTestScreenXml("2026-05-30T01:00:00", labelText));
            WriteTextFile(textListPath, BuildSelfTestTextListXml("2026-05-30T01:00:00"));
            WriteTextFile(tagTablePath, BuildSelfTestTagTableXml("2026-05-30T01:00:00"));

            WriteCsv(Path.Combine(hmiRoot, "hmi-export-report.csv"),
                new[] { "Kind", "TargetPath", "FolderPath", "Name", "TypeName", "FilePath", "Status", "Message" },
                new[]
                {
                    new[] { "Screen", "HMI_1", string.Empty, "Main", "Hmi.Screen.Screen", screenPath, "ok", string.Empty },
                    new[] { "TextList", "HMI_1", string.Empty, "Mode", "Hmi.TextGraphicList.TextList", textListPath, "ok", string.Empty },
                    new[] { "TagTable", "HMI_1", string.Empty, "Tags", "Hmi.Tag.TagTable", tagTablePath, "ok", string.Empty }
                });
        }

        private static string BuildSelfTestScreenXml(string created, string labelText)
        {
            StringBuilder builder = new StringBuilder();
            builder.AppendLine("<?xml version=\"1.0\" encoding=\"utf-8\"?>");
            builder.AppendLine("<Document>");
            builder.AppendLine("  <Engineering version=\"V21\" />");
            builder.AppendLine("  <DocumentInfo><Created>" + XmlEscape(created) + "</Created><ExportSetting>All</ExportSetting></DocumentInfo>");
            builder.AppendLine("  <Hmi.Screen.Screen ID=\"Screen1\">");
            builder.AppendLine("    <AttributeList><Name>Main</Name><Width>800</Width><Height>480</Height></AttributeList>");
            builder.AppendLine("    <ObjectList>");
            builder.AppendLine("      <Hmi.Screen.Text ID=\"Label1\" CompositionName=\"ScreenItems\">");
            builder.AppendLine("        <AttributeList><Name>Label</Name><ObjectName>Label</ObjectName><Left>100</Left><Top>200</Top><Width>120</Width><Height>30</Height></AttributeList>");
            builder.AppendLine("        <ObjectList>");
            builder.AppendLine("          <MultilingualText ID=\"LabelText\" CompositionName=\"Text\">");
            builder.AppendLine("            <ObjectList><MultilingualTextItem ID=\"LabelTextRu\" CompositionName=\"Items\"><AttributeList><Culture>ru-RU</Culture><Text><body><p>" + XmlEscape(labelText) + "</p></body></Text></AttributeList></MultilingualTextItem></ObjectList>");
            builder.AppendLine("          </MultilingualText>");
            builder.AppendLine("        </ObjectList>");
            builder.AppendLine("      </Hmi.Screen.Text>");
            builder.AppendLine("      <Hmi.Screen.Polygon ID=\"Poly1\" CompositionName=\"ScreenItems\">");
            builder.AppendLine("        <AttributeList><Name>Poly</Name><ObjectName>Poly</ObjectName><Left>100</Left><Top>200</Top><Width>20</Width><Height>30</Height><Points>0, 0 10, 20 -5, 30</Points></AttributeList>");
            builder.AppendLine("      </Hmi.Screen.Polygon>");
            builder.AppendLine("    </ObjectList>");
            builder.AppendLine("  </Hmi.Screen.Screen>");
            builder.AppendLine("</Document>");
            return builder.ToString();
        }

