        private static string GetLatestSelfTestPatchedHmiRoot(string cloneDir)
        {
            string preflightRoot = Path.Combine(cloneDir, "_hmi_preflight");
            string latest = Directory.GetDirectories(preflightRoot, "patched-*")
                .OrderByDescending(Directory.GetCreationTimeUtc)
                .FirstOrDefault();
            if (string.IsNullOrWhiteSpace(latest))
            {
                throw new DirectoryNotFoundException("No patched-* preflight directory was created.");
            }

            return Path.Combine(latest, "_hmi");
        }

