        private static string CombinePath(string left, string right)
        {
            right = right ?? string.Empty;
            if (string.IsNullOrEmpty(left))
            {
                return right.Trim('/').Trim('\\');
            }

            if (string.IsNullOrEmpty(right))
            {
                return left.Trim('/').Trim('\\');
            }

            return left.Trim('/').Trim('\\') + "/" + right.Trim('/').Trim('\\');
        }

        private static string CombineGroupPathKey(string parentGroupKey, string childGroupName)
        {
            string parent = NormalizeGroupPathKey(parentGroupKey);
            string child = EncodeGroupPathSegment(childGroupName);
            if (string.IsNullOrEmpty(parent))
            {
                return child;
            }

            return parent + "/" + child;
        }

        private static string NormalizeGroupPathKey(string value)
        {
            string normalized = NormalizeLogicalPath(value);
            return EqualsIgnoreCase(normalized, "_root") ? string.Empty : normalized;
        }

        private static string ParentGroupPathKey(string groupPathKey)
        {
            return ParentLogicalPath(NormalizeGroupPathKey(groupPathKey));
        }

        private static string LastGroupNameFromKey(string groupPathKey)
        {
            string[] segments = GroupPathKeySegments(groupPathKey);
            return segments.Length == 0 ? string.Empty : segments[segments.Length - 1];
        }

        private static string GroupPathDisplay(string groupPathKey)
        {
            string[] segments = GroupPathKeySegments(groupPathKey);
            return segments.Length == 0 ? string.Empty : string.Join("/", segments);
        }

        private static string GroupSegmentsDisplayJson(string groupPathKey)
        {
            string[] segments = GroupPathKeySegments(groupPathKey);
            return "[" + string.Join(",", segments.Select(Json).ToArray()) + "]";
        }

        private static string[] GroupPathKeySegments(string groupPathKey)
        {
            string normalized = NormalizeGroupPathKey(groupPathKey);
            if (string.IsNullOrEmpty(normalized))
            {
                return new string[0];
            }

            return normalized
                .Split(new[] { '/' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(DecodeGroupPathSegment)
                .ToArray();
        }

        private static string EncodeGroupPathSegment(string segment)
        {
            string value = EmptyIfNull(segment);
            if (string.IsNullOrEmpty(value))
            {
                return "_unnamed";
            }

            StringBuilder builder = new StringBuilder(value.Length);
            for (int i = 0; i < value.Length; i++)
            {
                char c = value[i];
                bool trailingUnsafe = i == value.Length - 1 && (c == ' ' || c == '.');
                if (GroupPathSegmentCharMustBeEscaped(c) || trailingUnsafe)
                {
                    AppendPercentEncodedUtf8(builder, c.ToString());
                }
                else
                {
                    builder.Append(c);
                }
            }

            string encoded = builder.ToString();
            if (IsWindowsReservedDeviceName(encoded))
            {
                StringBuilder reserved = new StringBuilder();
                AppendPercentEncodedUtf8(reserved, encoded.Substring(0, 1));
                reserved.Append(encoded.Substring(1));
                encoded = reserved.ToString();
            }

            return encoded;
        }

        private static bool GroupPathSegmentCharMustBeEscaped(char c)
        {
            return c == '%'
                || c == '/'
                || c == '\\'
                || c == ':'
                || c == '*'
                || c == '?'
                || c == '"'
                || c == '<'
                || c == '>'
                || c == '|'
                || char.IsControl(c);
        }

        private static void AppendPercentEncodedUtf8(StringBuilder builder, string text)
        {
            byte[] bytes = Encoding.UTF8.GetBytes(text);
            foreach (byte b in bytes)
            {
                builder.Append('%');
                builder.Append(b.ToString("X2", CultureInfo.InvariantCulture));
            }
        }

        private static string DecodeGroupPathSegment(string encodedSegment)
        {
            string value = EmptyIfNull(encodedSegment);
            if (value.IndexOf('%') < 0)
            {
                return value;
            }

            List<byte> bytes = new List<byte>();
            StringBuilder builder = new StringBuilder(value.Length);
            for (int i = 0; i < value.Length; i++)
            {
                char c = value[i];
                if (c == '%' && i + 2 < value.Length && IsHexDigit(value[i + 1]) && IsHexDigit(value[i + 2]))
                {
                    bytes.Add((byte)((HexValue(value[i + 1]) << 4) + HexValue(value[i + 2])));
                    i += 2;
                    continue;
                }

                if (bytes.Count > 0)
                {
                    builder.Append(Encoding.UTF8.GetString(bytes.ToArray()));
                    bytes.Clear();
                }

                builder.Append(c);
            }

            if (bytes.Count > 0)
            {
                builder.Append(Encoding.UTF8.GetString(bytes.ToArray()));
            }

            return builder.ToString();
        }

        private static bool IsHexDigit(char c)
        {
            return (c >= '0' && c <= '9')
                || (c >= 'a' && c <= 'f')
                || (c >= 'A' && c <= 'F');
        }

        private static int HexValue(char c)
        {
            if (c >= '0' && c <= '9') return c - '0';
            if (c >= 'a' && c <= 'f') return c - 'a' + 10;
            return c - 'A' + 10;
        }

        private static bool IsWindowsReservedDeviceName(string encodedSegment)
        {
            string segment = EmptyIfNull(encodedSegment).TrimEnd(' ', '.');
            int dot = segment.IndexOf('.');
            string stem = dot >= 0 ? segment.Substring(0, dot) : segment;
            if (stem.Length == 0)
            {
                return false;
            }

            string upper = stem.ToUpperInvariant();
            if (upper == "CON" || upper == "PRN" || upper == "AUX" || upper == "NUL")
            {
                return true;
            }

            if (upper.Length == 4 && (upper.StartsWith("COM", StringComparison.Ordinal) || upper.StartsWith("LPT", StringComparison.Ordinal)))
            {
                return upper[3] >= '1' && upper[3] <= '9';
            }

            return false;
        }

        private static string ParentLogicalPath(string path)
        {
            path = EmptyIfNull(path).Trim('/').Trim('\\');
            if (string.IsNullOrEmpty(path))
            {
                return string.Empty;
            }

            int index = path.LastIndexOf('/');
            if (index < 0)
            {
                index = path.LastIndexOf('\\');
            }

            return index < 0 ? string.Empty : path.Substring(0, index);
        }

        private static string LastLogicalPathPart(string path)
        {
            path = EmptyIfNull(path).Trim('/').Trim('\\');
            if (string.IsNullOrEmpty(path))
            {
                return string.Empty;
            }

            int index = path.LastIndexOf('/');
            if (index < 0)
            {
                index = path.LastIndexOf('\\');
            }

            return index < 0 ? path : path.Substring(index + 1);
        }

        private static string EmptyIfNull(string value)
        {
            return value ?? string.Empty;
        }

        private static string SafeFilePath(string path)
        {
            if (string.IsNullOrWhiteSpace(path))
            {
                return "_root";
            }

            string[] parts = path.Split(new[] { '/', '\\' }, StringSplitOptions.RemoveEmptyEntries);
            return Path.Combine(parts.Select(SafeFileName).ToArray());
        }

        private static string SafeFileName(string name)
        {
            if (string.IsNullOrWhiteSpace(name))
            {
                return "_unnamed";
            }

            foreach (char c in Path.GetInvalidFileNameChars())
            {
                name = name.Replace(c, '_');
            }

            name = name.Replace(':', '_').Replace('/', '_').Replace('\\', '_');
            return name.Length > 120 ? name.Substring(0, 120) : name;
        }

        private static string BlockSourceFileName(BlockRecord block, string extension)
        {
            string prefix = string.IsNullOrWhiteSpace(block.Number) ? string.Empty : block.Number + "_";
            return prefix + block.Name + NormalizeExtension(extension);
        }

        private static string NormalizeExtension(string extension)
        {
            if (string.IsNullOrWhiteSpace(extension))
            {
                return ".scl";
            }

            extension = extension.Trim();
            return extension.StartsWith(".", StringComparison.Ordinal) ? extension : "." + extension;
        }

        private static string DefaultSourceExtension(string programmingLanguage)
        {
            if (EqualsIgnoreCase(programmingLanguage, "SCL"))
            {
                return ".scl";
            }

            if (EqualsIgnoreCase(programmingLanguage, "STL"))
            {
                return ".awl";
            }

            if (EqualsIgnoreCase(programmingLanguage, "F_STL"))
            {
                return ".awl";
            }

            if (EqualsIgnoreCase(programmingLanguage, "DB")
                || EqualsIgnoreCase(programmingLanguage, "CPU_DB")
                || EqualsIgnoreCase(programmingLanguage, "F_DB")
                || EqualsIgnoreCase(programmingLanguage, "Motion_DB"))
            {
                return ".db";
            }

            if (EqualsIgnoreCase(programmingLanguage, "LAD")
                || EqualsIgnoreCase(programmingLanguage, "LAD_IEC")
                || EqualsIgnoreCase(programmingLanguage, "F_LAD")
                || EqualsIgnoreCase(programmingLanguage, "F_LAD_LIB"))
            {
                return ".lad";
            }

            if (EqualsIgnoreCase(programmingLanguage, "FBD")
                || EqualsIgnoreCase(programmingLanguage, "FBD_IEC")
                || EqualsIgnoreCase(programmingLanguage, "F_FBD")
                || EqualsIgnoreCase(programmingLanguage, "F_FBD_LIB"))
            {
                return ".fbd";
            }

            if (EqualsIgnoreCase(programmingLanguage, "GRAPH"))
            {
                return ".gr7";
            }

            return ".scl";
        }

        private static int SafeInt(string value)
        {
            int result;
            return int.TryParse(value, out result) ? result : 0;
        }

        private static string XmlEscape(string value)
        {
            if (value == null)
            {
                return string.Empty;
            }

            return value
                .Replace("&", "&amp;")
                .Replace("<", "&lt;")
                .Replace(">", "&gt;")
                .Replace("\"", "&quot;")
                .Replace("'", "&apos;");
        }

        private static void PrintException(Exception ex)
        {
            Console.Error.WriteLine();
            Console.Error.WriteLine("ERROR: " + ex.GetType().FullName);
            Console.Error.WriteLine(ex.Message);

            Exception current = ex.InnerException;
            while (current != null)
            {
                Console.Error.WriteLine();
                Console.Error.WriteLine("Caused by: " + current.GetType().FullName);
                Console.Error.WriteLine(current.Message);
                current = current.InnerException;
            }
        }

        private static bool EqualsIgnoreCase(string left, string right)
        {
            return string.Equals(left, right, StringComparison.OrdinalIgnoreCase);
        }

