            public static Options Parse(string[] args)
            {
                Options options = new Options();
                int index = 0;
                if (args.Length > 0 && !args[0].StartsWith("-", StringComparison.Ordinal))
                {
                    options.Command = args[0];
                    index = 1;
                }

                for (int i = index; i < args.Length; i++)
                {
                    string arg = args[i];
                    if (EqualsIgnoreCase(arg, "--project") && i + 1 < args.Length)
                    {
                        options.ProjectPath = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--api-dir") && i + 1 < args.Length)
                    {
                        options.ApiDir = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--out") && i + 1 < args.Length)
                    {
                        options.OutDir = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--in") && i + 1 < args.Length)
                    {
                        options.InDir = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--patch") && i + 1 < args.Length)
                    {
                        options.PatchPath = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--map") && i + 1 < args.Length)
                    {
                        options.MapPath = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--software-path") && i + 1 < args.Length)
                    {
                        options.SoftwarePathFilter = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--hmi-target-path") && i + 1 < args.Length)
                    {
                        options.HmiTargetPathFilter = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--headless"))
                    {
                        options.Headless = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--attach"))
                    {
                        options.Attach = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--force"))
                    {
                        options.Force = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--apply"))
                    {
                        options.Apply = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--save"))
                    {
                        options.Save = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--no-backup"))
                    {
                        options.NoBackup = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--i-accept-saving-preexisting-project-changes"))
                    {
                        options.AcceptSavingPreexistingProjectChanges = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--i-know-this-writes-plc"))
                    {
                        options.WritesPlcConfirmed = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--update-source-language"))
                    {
                        options.UpdateSourceLanguage = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--json"))
                    {
                        options.Json = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--max") && i + 1 < args.Length)
                    {
                        int parsed;
                        if (int.TryParse(args[++i], out parsed) && parsed > 0)
                        {
                            options.MaxItems = parsed;
                        }
                    }
                    else if (EqualsIgnoreCase(arg, "--attach-index") && i + 1 < args.Length)
                    {
                        int parsed;
                        if (int.TryParse(args[++i], out parsed) && parsed >= 0)
                        {
                            options.AttachIndex = parsed;
                        }
                    }
                    else if (EqualsIgnoreCase(arg, "--number") && i + 1 < args.Length)
                    {
                        int parsed;
                        if (int.TryParse(args[++i], out parsed) && parsed > 0)
                        {
                            options.Number = parsed;
                        }
                    }
                    else if (EqualsIgnoreCase(arg, "--host") && i + 1 < args.Length)
                    {
                        options.Host = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--rack") && i + 1 < args.Length)
                    {
                        int parsed;
                        if (int.TryParse(args[++i], out parsed) && parsed >= 0)
                        {
                            options.Rack = parsed;
                        }
                    }
                    else if (EqualsIgnoreCase(arg, "--slot") && i + 1 < args.Length)
                    {
                        int parsed;
                        if (int.TryParse(args[++i], out parsed) && parsed >= 0)
                        {
                            options.Slot = parsed;
                        }
                    }
                    else if (EqualsIgnoreCase(arg, "--connection-type") && i + 1 < args.Length)
                    {
                        int parsed;
                        if (int.TryParse(args[++i], out parsed) && parsed > 0)
                        {
                            options.ConnectionType = parsed;
                        }
                    }
                    else if (EqualsIgnoreCase(arg, "--db") && i + 1 < args.Length)
                    {
                        string db = args[++i];
                        int parsed;
                        if (int.TryParse(db, out parsed) && parsed > 0)
                        {
                            options.DbNumber = parsed;
                        }
                        else
                        {
                            options.DbName = db;
                        }
                    }
                    else if (EqualsIgnoreCase(arg, "--var") && i + 1 < args.Length)
                    {
                        options.VarName = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--vars") && i + 1 < args.Length)
                    {
                        options.VarsText = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--var-list") && i + 1 < args.Length)
