                    }
                    else if (EqualsIgnoreCase(arg, "--to") && i + 1 < args.Length)
                    {
                        options.ToVar = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--range") && i + 1 < args.Length)
                    {
                        options.RuntimeRange = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--print-values"))
                    {
                        options.PrintValues = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--single-read"))
                    {
                        options.SingleRead = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--start") && i + 1 < args.Length)
                    {
                        int parsed;
                        if (int.TryParse(args[++i], out parsed) && parsed >= 0)
                        {
                            options.RuntimeStart = parsed;
                        }
                    }
                    else if (EqualsIgnoreCase(arg, "--size") && i + 1 < args.Length)
                    {
                        int parsed;
                        if (int.TryParse(args[++i], out parsed) && parsed > 0)
                        {
                            options.RuntimeSize = parsed;
                        }
                    }
                    else if (EqualsIgnoreCase(arg, "--max-read-bytes") && i + 1 < args.Length)
                    {
                        int parsed;
                        if (int.TryParse(args[++i], out parsed) && parsed > 0)
                        {
                            options.MaxReadBytes = parsed;
                        }
                    }
                    else if (EqualsIgnoreCase(arg, "--timeout-ms") && i + 1 < args.Length)
                    {
                        int parsed;
                        if (int.TryParse(args[++i], out parsed) && parsed > 0)
                        {
                            options.TimeoutMs = parsed;
                        }
                    }
                    else if (EqualsIgnoreCase(arg, "--target") && i + 1 < args.Length)
                    {
                        options.TargetKind = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--name") && i + 1 < args.Length)
                    {
                        options.Name = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--group") && i + 1 < args.Length)
                    {
                        options.GroupPath = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--group-key") && i + 1 < args.Length)
                    {
                        options.GroupPathKey = args[++i];
                        options.GroupPath = options.GroupPathKey;
                    }
                    else if (EqualsIgnoreCase(arg, "--attribute") && i + 1 < args.Length)
                    {
                        options.AttributeName = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--value") && i + 1 < args.Length)
                    {
                        options.Value = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--extension") && i + 1 < args.Length)
                    {
                        options.Extension = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--language") && i + 1 < args.Length)
                    {
                        options.Language = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--number-space") && i + 1 < args.Length)
                    {
                        options.NumberSpace = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--scope") && i + 1 < args.Length)
                    {
                        options.Scope = args[++i];
                    }
                    else if (EqualsIgnoreCase(arg, "--version") || EqualsIgnoreCase(arg, "-v"))
                    {
                        options.ShowVersion = true;
                    }
                    else if (EqualsIgnoreCase(arg, "--help") || EqualsIgnoreCase(arg, "-h") || EqualsIgnoreCase(arg, "/?"))
                    {
                        options.ShowHelp = true;
                    }
                    else
                    {
                        throw new ArgumentException("Unknown argument: " + arg);
                    }
                }

                return options;
            }
        }

        private sealed class S7RuntimeClient : IDisposable
        {
            private readonly string _host;
            private readonly int _rack;
            private readonly int _slot;
            private readonly int _connectionType;
            private readonly int _timeoutMs;
            private TcpClient _tcpClient;
            private NetworkStream _stream;
            private ushort _pduReference;

            public S7RuntimeClient(string host, int rack, int slot, int connectionType, int timeoutMs)
            {
                _host = host;
                _rack = rack;
                _slot = slot;
                _connectionType = connectionType;
                _timeoutMs = timeoutMs;
                PduLength = 240;
                _pduReference = 1;
            }

            public int PduLength { get; private set; }

            public void Connect()
            {
                _tcpClient = new TcpClient();
                IAsyncResult connectResult = _tcpClient.BeginConnect(_host, 102, null, null);
                if (!connectResult.AsyncWaitHandle.WaitOne(_timeoutMs))
                {
                    try
                    {
                        _tcpClient.Close();
                    }
                    catch
                    {
                    }

                    throw new TimeoutException("TCP connect timeout.");
                }

                _tcpClient.EndConnect(connectResult);
                _tcpClient.ReceiveTimeout = _timeoutMs;
                _tcpClient.SendTimeout = _timeoutMs;
                _stream = _tcpClient.GetStream();
                _stream.ReadTimeout = _timeoutMs;
                _stream.WriteTimeout = _timeoutMs;

                SendPacket(BuildCotpConnectRequest());
                byte[] cotpResponse = ReceiveTpkt();
                if (cotpResponse.Length < 7 || cotpResponse[5] != 0xD0)
                {
                    throw new InvalidOperationException("Unexpected COTP connect response: " + BytesToHex(cotpResponse));
                }

                SendPacket(BuildSetupCommunicationRequest());
                byte[] setupResponse = ReceiveTpkt();
                ValidateS7Ack(setupResponse, "setup communication");
                int s7HeaderLength = S7HeaderLength(setupResponse);
                int parameterStart = 7 + s7HeaderLength;
                if (setupResponse.Length >= parameterStart + 8)
                {
                    PduLength = ReadUInt16(setupResponse, parameterStart + 6);
                }
            }

            public byte[] ReadDb(int dbNumber, int startByte, int size)
            {
                if (_stream == null)
                {
                    throw new InvalidOperationException("Client is not connected.");
                }

                SendPacket(BuildReadDbRequest(dbNumber, startByte, size));
                byte[] response = ReceiveTpkt();
                ValidateS7Ack(response, "read DB");

                int s7HeaderLength = S7HeaderLength(response);
                int parameterLength = ReadUInt16(response, 13);
                int dataLength = ReadUInt16(response, 15);
                int dataStart = 7 + s7HeaderLength + parameterLength;
                if (dataLength < 4 || response.Length < dataStart + 4)
                {
                    throw new InvalidOperationException("S7 read response has no data item: " + BytesToHex(response));
                }

                byte returnCode = response[dataStart];
                byte transportSize = response[dataStart + 1];
                int reportedLength = ReadUInt16(response, dataStart + 2);
                if (returnCode != 0xFF)
                {
                    throw new InvalidOperationException("S7 read item failed. Return code: 0x" + returnCode.ToString("X2", CultureInfo.InvariantCulture));
                }

                int byteCount = transportSize == 0x04 || transportSize == 0x03
                    ? (reportedLength + 7) / 8
                    : reportedLength;
                if (byteCount < size)
                {
                    throw new InvalidOperationException("S7 read returned fewer bytes than requested. Requested=" + size.ToString(CultureInfo.InvariantCulture) + ", returned=" + byteCount.ToString(CultureInfo.InvariantCulture));
                }

                if (response.Length < dataStart + 4 + byteCount)
                {
                    throw new InvalidOperationException("S7 read response is truncated: " + BytesToHex(response));
                }

                byte[] result = new byte[size];
                Buffer.BlockCopy(response, dataStart + 4, result, 0, size);
                return result;
            }

            public void WriteDb(int dbNumber, int startByte, byte[] data)
            {
                if (_stream == null)
                {
                    throw new InvalidOperationException("Client is not connected.");
                }

                if (data == null || data.Length == 0)
                {
                    throw new ArgumentException("Write data must not be empty.");
                }

                SendPacket(BuildWriteDbRequest(dbNumber, startByte, data));
                byte[] response = ReceiveTpkt();
                ValidateS7Ack(response, "write DB");

                int s7HeaderLength = S7HeaderLength(response);
                int parameterLength = ReadUInt16(response, 13);
                int dataLength = ReadUInt16(response, 15);
                int dataStart = 7 + s7HeaderLength + parameterLength;
                if (dataLength < 1 || response.Length < dataStart + 1)
                {
                    throw new InvalidOperationException("S7 write response has no result item: " + BytesToHex(response));
                }

                byte returnCode = response[dataStart];
                if (returnCode != 0xFF)
                {
                    throw new InvalidOperationException("S7 write item failed. Return code: 0x" + returnCode.ToString("X2", CultureInfo.InvariantCulture));
                }
            }

            public void Dispose()
            {
                if (_stream != null)
                {
                    _stream.Dispose();
                    _stream = null;
                }

                if (_tcpClient != null)
                {
                    _tcpClient.Close();
                    _tcpClient = null;
                }
            }

            private byte[] BuildCotpConnectRequest()
            {
                int remoteTsap = ((_connectionType & 0xFF) << 8) | ((_rack & 0x07) << 5) | (_slot & 0x1F);
                return new byte[]
                {
                    0x03, 0x00, 0x00, 0x16,
                    0x11, 0xE0, 0x00, 0x00, 0x00, 0x01, 0x00,
                    0xC0, 0x01, 0x0A,
                    0xC1, 0x02, 0x01, 0x00,
                    0xC2, 0x02, (byte)((remoteTsap >> 8) & 0xFF), (byte)(remoteTsap & 0xFF)
                };
            }

            private byte[] BuildSetupCommunicationRequest()
            {
                ushort pduRef = NextPduReference();
                return new byte[]
                {
                    0x03, 0x00, 0x00, 0x19,
                    0x02, 0xF0, 0x80,
                    0x32, 0x01, 0x00, 0x00, (byte)(pduRef >> 8), (byte)(pduRef & 0xFF), 0x00, 0x08, 0x00, 0x00,
                    0xF0, 0x00, 0x00, 0x01, 0x00, 0x01, 0x01, 0xE0
                };
            }

            private byte[] BuildReadDbRequest(int dbNumber, int startByte, int size)
            {
                ushort pduRef = NextPduReference();
                int bitAddress = startByte * 8;
                return new byte[]
                {
                    0x03, 0x00, 0x00, 0x1F,
                    0x02, 0xF0, 0x80,
                    0x32, 0x01, 0x00, 0x00, (byte)(pduRef >> 8), (byte)(pduRef & 0xFF), 0x00, 0x0E, 0x00, 0x00,
                    0x04, 0x01,
                    0x12, 0x0A, 0x10, 0x02,
                    (byte)((size >> 8) & 0xFF), (byte)(size & 0xFF),
                    (byte)((dbNumber >> 8) & 0xFF), (byte)(dbNumber & 0xFF),
                    0x84,
                    (byte)((bitAddress >> 16) & 0xFF),
                    (byte)((bitAddress >> 8) & 0xFF),
                    (byte)(bitAddress & 0xFF)
                };
            }

            private byte[] BuildWriteDbRequest(int dbNumber, int startByte, byte[] data)
            {
                ushort pduRef = NextPduReference();
                int bitAddress = startByte * 8;
                int dataBitLength = data.Length * 8;
                int dataItemLength = 4 + data.Length;
                int paddedDataItemLength = dataItemLength + ((data.Length % 2) == 0 ? 0 : 1);
                int tpktLength = 7 + 10 + 14 + paddedDataItemLength;

                List<byte> packet = new List<byte>(tpktLength);
                packet.AddRange(new byte[]
                {
                    0x03, 0x00, (byte)((tpktLength >> 8) & 0xFF), (byte)(tpktLength & 0xFF),
                    0x02, 0xF0, 0x80,
                    0x32, 0x01, 0x00, 0x00, (byte)(pduRef >> 8), (byte)(pduRef & 0xFF), 0x00, 0x0E,
                    (byte)((paddedDataItemLength >> 8) & 0xFF), (byte)(paddedDataItemLength & 0xFF),
                    0x05, 0x01,
                    0x12, 0x0A, 0x10, 0x02,
                    (byte)((data.Length >> 8) & 0xFF), (byte)(data.Length & 0xFF),
                    (byte)((dbNumber >> 8) & 0xFF), (byte)(dbNumber & 0xFF),
                    0x84,
                    (byte)((bitAddress >> 16) & 0xFF),
                    (byte)((bitAddress >> 8) & 0xFF),
                    (byte)(bitAddress & 0xFF),
                    0x00, 0x04,
                    (byte)((dataBitLength >> 8) & 0xFF), (byte)(dataBitLength & 0xFF)
                });
                packet.AddRange(data);
                if ((data.Length % 2) != 0)
                {
                    packet.Add(0x00);
                }

                return packet.ToArray();
            }

            private ushort NextPduReference()
            {
                _pduReference++;
                if (_pduReference == 0)
                {
                    _pduReference = 1;
                }

                return _pduReference;
            }

            private void SendPacket(byte[] packet)
            {
                _stream.Write(packet, 0, packet.Length);
            }

            private byte[] ReceiveTpkt()
            {
                byte[] header = ReadExact(4);
                if (header[0] != 0x03)
                {
                    throw new InvalidOperationException("Invalid TPKT version: 0x" + header[0].ToString("X2", CultureInfo.InvariantCulture));
                }

                int length = ReadUInt16(header, 2);
                if (length < 4 || length > 4096)
                {
                    throw new InvalidOperationException("Invalid TPKT length: " + length.ToString(CultureInfo.InvariantCulture));
                }

                byte[] packet = new byte[length];
                Buffer.BlockCopy(header, 0, packet, 0, 4);
                byte[] rest = ReadExact(length - 4);
                Buffer.BlockCopy(rest, 0, packet, 4, rest.Length);
                return packet;
            }

            private byte[] ReadExact(int count)
            {
                byte[] buffer = new byte[count];
                int offset = 0;
                while (offset < count)
                {
                    int read = _stream.Read(buffer, offset, count - offset);
                    if (read <= 0)
                    {
                        throw new IOException("Connection closed while reading.");
                    }

                    offset += read;
                }

                return buffer;
            }

            private static void ValidateS7Ack(byte[] packet, string operation)
            {
                if (packet.Length < 19)
                {
                    throw new InvalidOperationException("Short S7 response for " + operation + ": " + BytesToHex(packet));
                }

                if (packet[4] != 0x02 || packet[5] != 0xF0 || packet[6] != 0x80)
                {
                    throw new InvalidOperationException("Unexpected COTP data header for " + operation + ": " + BytesToHex(packet));
                }

                if (packet[7] != 0x32)
                {
                    throw new InvalidOperationException("Unexpected S7 protocol id for " + operation + ": " + BytesToHex(packet));
                }

                if (packet[8] == 0x03 && (packet[17] != 0x00 || packet[18] != 0x00))
                {
                    throw new InvalidOperationException("S7 " + operation + " error class/code: 0x" + packet[17].ToString("X2", CultureInfo.InvariantCulture) + "/0x" + packet[18].ToString("X2", CultureInfo.InvariantCulture));
                }
            }

            private static int S7HeaderLength(byte[] packet)
            {
                return packet.Length > 8 && packet[8] == 0x03 ? 12 : 10;
            }

            private static int ReadUInt16(byte[] data, int offset)
            {
                if (data.Length < offset + 2)
                {
                    throw new InvalidOperationException("Cannot read UInt16 at offset " + offset.ToString(CultureInfo.InvariantCulture) + ".");
                }

                return (data[offset] << 8) | data[offset + 1];
            }

            private static string BytesToHex(byte[] data)
            {
                return string.Join(" ", data.Select(x => x.ToString("X2", CultureInfo.InvariantCulture)).ToArray());
            }
        }

