            public ApplyPlanItem PlanItem;

            public static ApplyBlockState FromBlock(BlockRecord block)
            {
                return new ApplyBlockState
                {
                    GroupPath = EmptyIfNull(block.GroupPath),
                    GroupPathDisplay = EmptyIfNull(block.GroupPathDisplay),
                    Name = block.Name,
                    NumberSpace = BlockNumberSpace(block),
                    Number = block.Number,
                    TypeName = block.TypeName,
                    ProgrammingLanguage = block.ProgrammingLanguage,
                    InstanceOfName = block.InstanceOfName,
                    IsTouched = false
                };
            }

            public static ApplyBlockState FromPlan(ApplyPlanItem item)
            {
                return new ApplyBlockState
                {
                    GroupPath = EmptyIfNull(item.TargetGroupPath),
                    GroupPathDisplay = EmptyIfNull(item.TargetGroupPathDisplay),
                    Name = item.TargetName,
                    NumberSpace = item.NumberSpace,
                    Number = item.TargetNumber,
                    TypeName = item.TypeName,
                    ProgrammingLanguage = item.ProgrammingLanguage,
                    InstanceOfName = item.InstanceOfName,
                    IsTouched = true,
                    PlanItem = item
                };
            }

            public bool SameBlock(BlockRecord block)
            {
                return block != null
                    && EqualsIgnoreCase(Name, block.Name)
                    && EqualsIgnoreCase(EmptyIfNull(GroupPath), EmptyIfNull(block.GroupPath))
                    && EqualsIgnoreCase(NumberSpace, BlockNumberSpace(block));
            }

            public void Apply(ApplyPlanItem item)
            {
                GroupPath = EmptyIfNull(item.TargetGroupPath);
                GroupPathDisplay = EmptyIfNull(item.TargetGroupPathDisplay);
                Name = item.TargetName;
                NumberSpace = item.NumberSpace;
                Number = item.TargetNumber;
                TypeName = item.TypeName;
                ProgrammingLanguage = item.ProgrammingLanguage;
                InstanceOfName = item.InstanceOfName;
                IsTouched = true;
                PlanItem = item;
            }
        }

